class UpdateError(RuntimeError):
    """An expected, user-actionable update refusal."""

    def __init__(
        self,
        code: str,
        message: str,
        retryable: bool = False,
        *,
        maintenance_not_acquired: bool = False,
    ) -> None:
        super().__init__(message)
        self.code = code
        self.retryable = retryable
        self.maintenance_not_acquired = maintenance_not_acquired


@dataclass(frozen=True)
class Candidate:
    """One verified manifest selected by a trusted channel index."""

    component: dict[str, Any]
    manifest: dict[str, Any]
    manifest_digest: str
    artifact_digest: str
    manifest_uri: str
    index: dict[str, Any]
    index_uri: str
    manifest_bytes: bytes | None = None
    release_assets: tuple[dict[str, Any], ...] = ()
    release_tag: str | None = None
    index_asset_name: str | None = None
    index_asset_digest: str | None = None
    manifest_asset_digest: str | None = None


def _jcs_string(value: str) -> str:
    if any(0xD800 <= ord(char) <= 0xDFFF for char in value):
        raise UpdateError("INVALID_JSON", "Canonical JSON does not permit unpaired surrogates.")
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def canonical_jcs(value: Any) -> bytes:
    """Serialize the RFC 8785 JSON subset used by the component contracts.

    Public manifests intentionally permit safe integers only (no floating point).
    Object keys are ordered by UTF-16 code units as required by JCS.
    """

    def encode(item: Any) -> str:
        if item is None:
            return "null"
        if item is True:
            return "true"
        if item is False:
            return "false"
        if isinstance(item, int):
            if abs(item) > MAX_SAFE_INTEGER:
                raise UpdateError("INVALID_JSON", "Canonical JSON integer exceeds the safe range.")
            return str(item)
        if isinstance(item, float):
            raise UpdateError(
                "INVALID_JSON", "Component JSON must not contain floating-point values."
            )
        if isinstance(item, str):
            return _jcs_string(item)
        if isinstance(item, list):
            return "[" + ",".join(encode(value) for value in item) + "]"
        if isinstance(item, dict):
            if not all(isinstance(key, str) for key in item):
                raise UpdateError("INVALID_JSON", "Canonical JSON object keys must be strings.")
            keys = sorted(item, key=lambda key: key.encode("utf-16be"))
            return "{" + ",".join(_jcs_string(key) + ":" + encode(item[key]) for key in keys) + "}"
        raise UpdateError(
            "INVALID_JSON", f"Unsupported canonical JSON value: {type(item).__name__}."
        )

    return encode(value).encode("utf-8")


def _digest_json(value: dict[str, Any], field: str) -> str:
    material = dict(value)
    material.pop(field, None)
    return "sha256:" + hashlib.sha256(canonical_jcs(material)).hexdigest()


def _file_digest(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return "sha256:" + digest.hexdigest()


def _valid_digest(value: Any) -> bool:
    return isinstance(value, str) and DIGEST_PATTERN.fullmatch(value) is not None


def _trusted_contract_lock(value: Any) -> bool:
    if not isinstance(value, dict) or set(value) != {"repository", "commit", "path", "sha256"}:
        return False
    if (
        value.get("repository") != "DoHorizon-AI/Cyrene-Workspace"
        or not isinstance(value.get("commit"), str)
        or re.fullmatch(r"[0-9a-f]{40}", value["commit"]) is None
        or value.get("path") not in TRUSTED_CONTRACT_LOCK_PATHS
        or not _valid_digest(value.get("sha256"))
    ):
        return False
    try:
        _safe_relative(value["path"], field="compatibility.contractLock.path")
    except UpdateError:
        return False
    return True


def _unique_json_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    value: dict[str, Any] = {}
    for key, item in pairs:
        if key in value:
            raise UpdateError("INVALID_JSON", f"JSON object contains duplicate key {key!r}.")
        value[key] = item
    return value


def _running_as_root() -> bool:
    """Report whether this process has the OS identity required for apply."""

    return hasattr(os, "geteuid") and os.geteuid() == 0


def _maintenance_request_id(transaction: dict[str, Any]) -> str:
    """Return the durable broker transaction ID bound to this plan."""

    plan_id = transaction.get("planId")
    if not isinstance(plan_id, str) or PLAN_ID_PATTERN.fullmatch(plan_id) is None:
        raise UpdateError("INVALID_TRANSACTION", "Maintenance transaction has an invalid planId.")
    if transaction.get("transactionKind") == "workload-assembly.v1":
        phase = transaction.get("maintenancePhase")
        if phase in {
            "core-runtime-install",
            "package-only",
            "core-runtime-activate",
            "core-runtime-uninstall",
        }:
            expected = f"cyrene-workload-{phase}-{plan_id}"
            request_id = transaction.get("maintenanceRequestId", expected)
            if request_id != expected:
                raise UpdateError(
                    "INVALID_TRANSACTION",
                    "Workload maintenance requestId does not match its exact phase and plan.",
                )
            transaction["maintenanceRequestId"] = request_id
            return request_id
    expected = "cyrene-update-" + plan_id
    request_id = transaction.get("requestId", expected)
    if request_id != expected:
        raise UpdateError(
            "INVALID_TRANSACTION", "Maintenance requestId does not match the confirmed plan."
        )
    transaction["requestId"] = request_id
    return request_id


def _parse_supported_version_range(
    value: Any,
) -> tuple[str, tuple[int, int, int], tuple[int, int, int] | None]:
    """Parse the deliberately small SemVer requirement subset in the catalog."""

    if not isinstance(value, str):
        raise UpdateError(
            "DEPENDENCY_RANGE_UNSUPPORTED", "A component dependency has no supported versionRange."
        )
    exact = re.fullmatch(r"=([0-9]+\.[0-9]+\.[0-9]+)", value)
    if exact:
        match = SEMVER3_PATTERN.fullmatch(exact.group(1))
        if match is None:
            raise UpdateError(
                "DEPENDENCY_RANGE_UNSUPPORTED", f"Unsupported component versionRange {value!r}."
            )
        return "exact", tuple(map(int, match.groups())), None
    interval = re.fullmatch(r">=([0-9]+\.[0-9]+\.[0-9]+), <([0-9]+\.[0-9]+\.[0-9]+)", value)
    if interval:
        lower_match = SEMVER3_PATTERN.fullmatch(interval.group(1))
        upper_match = SEMVER3_PATTERN.fullmatch(interval.group(2))
        if lower_match is None or upper_match is None:
            raise UpdateError(
                "DEPENDENCY_RANGE_UNSUPPORTED", f"Unsupported component versionRange {value!r}."
            )
        lower = tuple(map(int, lower_match.groups()))
        upper = tuple(map(int, upper_match.groups()))
        if lower >= upper:
            raise UpdateError(
                "DEPENDENCY_RANGE_UNSUPPORTED", f"Invalid component versionRange {value!r}."
            )
        return "interval", lower, upper
    raise UpdateError(
        "DEPENDENCY_RANGE_UNSUPPORTED", f"Unsupported component versionRange {value!r}."
    )


def _version_satisfies(version: Any, version_range: Any) -> bool:
    kind, lower, upper = _parse_supported_version_range(version_range)
    if not isinstance(version, str):
        return False
    match = SEMVER3_PATTERN.fullmatch(version)
    if match is None:
        return False
    parsed = tuple(map(int, match.groups()))
    return (
        parsed == lower
        if kind == "exact"
        else (parsed >= lower and upper is not None and parsed < upper)
    )


def _safe_relative(value: Any, *, field: str) -> PurePosixPath:
    if not isinstance(value, str) or not value or "\\" in value:
        raise UpdateError("INVALID_MANIFEST", f"{field} must be a safe relative path.")
    path = PurePosixPath(value)
    if path.is_absolute() or any(part in {"", ".", ".."} for part in path.parts):
        raise UpdateError("INVALID_MANIFEST", f"{field} escapes the artifact root.")
    if path.as_posix() != value:
        raise UpdateError("INVALID_MANIFEST", f"{field} is not normalized.")
    return path


def _native_executable_files(artifact: Any) -> set[str]:
    """Validate the signed native file map and return its executable paths."""

    if not isinstance(artifact, dict):
        raise UpdateError("INVALID_MANIFEST", "Native artifact metadata is invalid.")
    entrypoint_value = artifact.get("entrypoint")
    files = artifact.get("files")
    if not isinstance(files, dict) or not files or not isinstance(entrypoint_value, str):
        raise UpdateError("INVALID_MANIFEST", "Native artifact payload map is invalid.")
    entrypoint = _safe_relative(entrypoint_value, field="artifact.entrypoint").as_posix()
    for name, file_digest in files.items():
        _safe_relative(name, field="artifact.files path")
        if not _valid_digest(file_digest):
            raise UpdateError("INVALID_MANIFEST", "Native artifact file digest is invalid.")
    if entrypoint not in files:
        raise UpdateError("INVALID_MANIFEST", "Native artifact entrypoint is not a signed file.")

    if "executableFiles" not in artifact:
        return {entrypoint}
    executable_files = artifact["executableFiles"]
    if (
        not isinstance(executable_files, list)
        or not executable_files
        or any(not isinstance(name, str) for name in executable_files)
        or len(set(executable_files)) != len(executable_files)
    ):
        raise UpdateError("INVALID_MANIFEST", "Native artifact executableFiles is invalid.")
    normalized = {
        _safe_relative(name, field="artifact.executableFiles path").as_posix()
        for name in executable_files
    }
    if len(normalized) != len(executable_files) or entrypoint not in normalized:
        raise UpdateError(
            "INVALID_MANIFEST", "Native artifact executableFiles must include the entrypoint."
        )
    if not normalized.issubset(files):
        raise UpdateError(
            "INVALID_MANIFEST", "Native artifact executableFiles must name signed files."
        )
    return normalized


def _artifact_digest_from_manifest(manifest: Any) -> str | None:
    if not isinstance(manifest, dict):
        return None
    artifact = manifest.get("artifact")
    if not isinstance(artifact, dict):
        return None
    value = artifact.get("sha256", artifact.get("digest"))
    return value if isinstance(value, str) else None


def _artifact_kind_from_manifest(manifest: Any) -> str | None:
    if not isinstance(manifest, dict):
        return None
    artifact = manifest.get("artifact")
    kind = artifact.get("kind") if isinstance(artifact, dict) else None
    return kind if isinstance(kind, str) else None


def _native_release_directory_identity(directory_name: str) -> tuple[str, str | None]:
    """Parse a legacy or digest-specific native release directory basename."""

    match = re.fullmatch(r"(.+)--([0-9a-f]{64})", directory_name)
    if match:
        return match.group(1), match.group(2)
    return directory_name, None


def _native_release_pointer_identity(item: dict[str, Any]) -> str:
    pointer_identity = item.get("pointerIdentity")
    if isinstance(pointer_identity, str):
        version, pointer_digest = _native_release_directory_identity(pointer_identity)
        if VERSION_PATTERN.fullmatch(version) and (
            pointer_digest is None or len(pointer_digest) == 64
        ):
            return pointer_identity
    version = item.get("version")
    manifest_digest = item.get("manifestDigest")
    if (
        not isinstance(version, str)
        or VERSION_PATTERN.fullmatch(version) is None
        or not _valid_digest(manifest_digest)
    ):
        raise UpdateError(
            "TRANSACTION_IDENTITY_UNKNOWN", "Native release has no verified pointer identity."
        )
    return f"{version}--{manifest_digest.removeprefix('sha256:')}"


def _read_object(path: Path, description: str) -> dict[str, Any]:
    if path.is_symlink():
        raise UpdateError("UNSAFE_STATE", f"Refusing a symlink while reading {description}: {path}")
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
        raise UpdateError("INVALID_LOCAL_STATE", f"Cannot read {description}: {error}") from error
    if not isinstance(value, dict):
        raise UpdateError("INVALID_LOCAL_STATE", f"{description} must be a JSON object.")
    return value


def _atomic_json(path: Path, value: dict[str, Any], *, mode: int = 0o600) -> None:
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    _verify_private_directory(path.parent)
    temporary = path.parent / f".{path.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp"
    try:
        descriptor = os.open(
            temporary, os.O_CREAT | os.O_EXCL | os.O_WRONLY | getattr(os, "O_NOFOLLOW", 0), mode
        )
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(
                json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2).encode("utf-8")
                + b"\n"
            )
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary, mode)
        os.replace(temporary, path)
        directory_fd = os.open(path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        temporary.unlink(missing_ok=True)


def _atomic_private_bytes(path: Path, value: bytes) -> None:
    """Atomically store an opaque private cache object without changing its bytes."""

    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    _verify_private_directory(path.parent)
    temporary = path.parent / f".{path.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp"
    try:
        descriptor = os.open(
            temporary, os.O_CREAT | os.O_EXCL | os.O_WRONLY | getattr(os, "O_NOFOLLOW", 0), 0o600
        )
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(value)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary, 0o600)
        os.replace(temporary, path)
        directory_fd = os.open(path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        temporary.unlink(missing_ok=True)


def _read_private_cache_bytes(path: Path, *, max_bytes: int, description: str) -> bytes:
    """Read one regular, single-link, current-user-owned 0600 cache file safely."""

    try:
        before = path.lstat()
        if (
            not stat.S_ISREG(before.st_mode)
            or before.st_uid != os.geteuid()
            or stat.S_IMODE(before.st_mode) != 0o600
            or before.st_nlink != 1
            or before.st_size < 1
            or before.st_size > max_bytes
        ):
            raise UpdateError("UNSAFE_STATE", f"Private {description} metadata is unsafe.")
        descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    except FileNotFoundError:
        raise
    except OSError as error:
        raise UpdateError("UNSAFE_STATE", f"Cannot open private {description}: {error}") from error

    try:
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_dev != before.st_dev
            or opened.st_ino != before.st_ino
            or opened.st_uid != os.geteuid()
            or stat.S_IMODE(opened.st_mode) != 0o600
            or opened.st_nlink != 1
        ):
            raise UpdateError("UNSAFE_STATE", f"Private {description} changed while opening.")
        with os.fdopen(descriptor, "rb", closefd=False) as stream:
            payload = stream.read(max_bytes + 1)
        after = os.fstat(descriptor)
        if (
            len(payload) < 1
            or len(payload) > max_bytes
            or after.st_dev != opened.st_dev
            or after.st_ino != opened.st_ino
            or after.st_size != opened.st_size
        ):
            raise UpdateError("UNSAFE_STATE", f"Private {description} changed while reading.")
        return payload
    except OSError as error:
        raise UpdateError("UNSAFE_STATE", f"Cannot read private {description}: {error}") from error
    finally:
        os.close(descriptor)


def _atomic_control_state(path: Path, value: dict[str, Any], *, gid: int) -> None:
    """Atomically persist one reader-accessible gate record without exposing a token."""

    temporary = path.parent / f".{path.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp"
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()
    try:
        descriptor = os.open(
            temporary,
            os.O_CREAT | os.O_EXCL | os.O_WRONLY | getattr(os, "O_NOFOLLOW", 0),
            0o600,
        )
        try:
            os.fchown(descriptor, 0, gid)
            os.fchmod(descriptor, 0o640)
            with os.fdopen(descriptor, "wb") as stream:
                stream.write(payload)
                stream.flush()
                os.fsync(stream.fileno())
        except Exception:
            os.close(descriptor)
            raise
        os.replace(temporary, path)
        directory_fd = os.open(path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        temporary.unlink(missing_ok=True)


def _verify_root_protected_directory(path: Path, *, create: bool = False) -> None:
    """Require the complete public catalog path to be root-owned and non-writable."""

    absolute = path.absolute()
    if create:
        absolute.mkdir(parents=True, exist_ok=True, mode=0o755)
    current = Path(absolute.anchor)
    for part in absolute.parts[1:]:
        current /= part
        try:
            info = current.lstat()
        except OSError as error:
            raise UpdateError(
                "UNSAFE_CATALOG", f"Cannot inspect protected catalog directory {current}: {error}"
            ) from error
        if (
            not stat.S_ISDIR(info.st_mode)
            or info.st_uid != 0
            or stat.S_IMODE(info.st_mode) & 0o022
            or not stat.S_IMODE(info.st_mode) & 0o001
        ):
            raise UpdateError(
                "UNSAFE_CATALOG",
                f"Catalog directory and ancestors must be root-owned real directories without group/world write access: {current}",
            )


def _atomic_root_catalog_bytes(path: Path, payload: bytes) -> None:
    """Atomically publish one immutable, root-readable catalog object."""

    _verify_root_protected_directory(path.parent, create=True)
    temporary = path.parent / f".{path.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp"
    try:
        descriptor = os.open(
            temporary,
            os.O_CREAT | os.O_EXCL | os.O_WRONLY | getattr(os, "O_NOFOLLOW", 0),
            0o644,
        )
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        os.chown(temporary, 0, 0)
        os.chmod(temporary, 0o644)
        os.replace(temporary, path)
        directory_fd = os.open(path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        temporary.unlink(missing_ok=True)


def _read_root_catalog_object(path: Path, description: str) -> bytes:
    if path.is_symlink():
        raise UpdateError("UNSAFE_CATALOG", f"Refusing a symbolic link for {description}: {path}")
    try:
        info = path.lstat()
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_uid != 0
            or stat.S_IMODE(info.st_mode) & 0o022
            or not stat.S_IMODE(info.st_mode) & 0o004
        ):
            raise UpdateError(
                "UNSAFE_CATALOG",
                f"{description} must be root-owned, readable, and not group/world writable.",
            )
        return path.read_bytes()
    except OSError as error:
        raise UpdateError("UNSAFE_CATALOG", f"Cannot read {description}: {error}") from error


def _stage_initial_catalog_directory(
    metadata: dict[str, Any], catalog_bytes: bytes, attestation_bytes: bytes
) -> Path:
    """Build a complete first catalog snapshot outside the active path."""

    parent = ACTIVE_CATALOG_ROOT.parent
    _verify_root_protected_directory(parent)
    if ACTIVE_CATALOG_ROOT.exists() or ACTIVE_CATALOG_ROOT.is_symlink():
        raise UpdateError("UNSAFE_CATALOG", "The active catalog directory already exists.")
    staging = parent / f".{ACTIVE_CATALOG_ROOT.name}.staging-{os.getpid()}-{uuid.uuid4().hex}"
    created = False
    try:
        staging.mkdir(mode=0o700)
        created = True
        os.chown(staging, 0, 0)
        os.chmod(staging, 0o755)
        _verify_root_protected_directory(staging)
        digest_hex = metadata["catalogSha256"].removeprefix("sha256:")
        catalog_name = f"catalog-{digest_hex}.json"
        attestation_name = f"catalog-{digest_hex}-{metadata['sourceCommit']}.attestation.jsonl"
        _atomic_root_catalog_bytes(staging / catalog_name, catalog_bytes)
        _atomic_root_catalog_bytes(staging / attestation_name, attestation_bytes)
        directory_fd = os.open(staging, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
        return staging
    except BaseException:
        if created and staging.exists() and not staging.is_symlink():
            shutil.rmtree(staging, ignore_errors=True)
        raise


def _activate_initial_catalog_directory(staging: Path) -> None:
    """Atomically expose a fully populated first active catalog directory."""

    parent = ACTIVE_CATALOG_ROOT.parent
    _verify_root_protected_directory(parent)
    _verify_root_protected_directory(staging)
    if ACTIVE_CATALOG_ROOT.exists() or ACTIVE_CATALOG_ROOT.is_symlink():
        raise UpdateError("UNSAFE_CATALOG", "The active catalog directory appeared during import.")
    os.rename(staging, ACTIVE_CATALOG_ROOT)
    directory_fd = os.open(parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)


def _verify_private_directory(path: Path) -> None:
    """Require a real, current-user-owned directory with no group/other access."""

    absolute = path.absolute()
    try:
        if absolute.resolve(strict=True) != absolute:
            raise UpdateError(
                "UNSAFE_STATE", f"Refusing a symlinked update state directory: {path}"
            )
        info = absolute.lstat()
    except OSError as error:
        raise UpdateError(
            "UNSAFE_STATE", f"Cannot inspect update state directory {path}: {error}"
        ) from error
    if (
        not stat.S_ISDIR(info.st_mode)
        or info.st_uid != os.geteuid()
        or stat.S_IMODE(info.st_mode) & 0o077
    ):
        raise UpdateError(
            "UNSAFE_STATE",
            f"Update state directory must be owned by uid {os.geteuid()} and mode 0700: {path}",
        )


def _verify_private_file(path: Path) -> None:
    """Require a single-link root-owned private file before passing proof to a native CLI."""
    descriptor: int | None = None
    try:
        before = path.lstat()
        if (
            not stat.S_ISREG(before.st_mode)
            or before.st_uid != 0
            or stat.S_IMODE(before.st_mode) != 0o600
            or before.st_nlink != 1
        ):
            raise UpdateError("UNSAFE_STATE", f"Private proof file metadata is unsafe: {path}")
        descriptor = os.open(
            path,
            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0),
        )
        opened = os.fstat(descriptor)
        if (
            not stat.S_ISREG(opened.st_mode)
            or (opened.st_dev, opened.st_ino) != (before.st_dev, before.st_ino)
            or opened.st_uid != 0
            or stat.S_IMODE(opened.st_mode) != 0o600
            or opened.st_nlink != 1
        ):
            raise UpdateError("UNSAFE_STATE", f"Private proof file changed while opening: {path}")
    except OSError as error:
        raise UpdateError(
            "UNSAFE_STATE", f"Cannot verify private proof file {path}: {error}"
        ) from error
    finally:
        if descriptor is not None:
            os.close(descriptor)


class ComponentUpdater:
    """Drive the fixed JSON helper protocol against trusted local catalog data."""

    @staticmethod
    def _running_from_installed_helper() -> bool:
        """Return whether this code is running from the immutable package helper path."""

        return Path(__file__).resolve().parent == INSTALLED_HELPER_DIRECTORY

    def _load_installed_bootstrap_catalog_binding(self) -> dict[str, Any]:
        """Validate the fixed package binding against the fixed installed catalog."""

        catalog_path = self.catalog_path
        helper_path = Path(__file__).resolve().with_name("bootstrap_catalog_binding.py")
        if helper_path.is_symlink() or not helper_path.is_file():
            raise UpdateError(
                "INVALID_BOOTSTRAP_BINDING",
                "The installed bootstrap catalog binding verifier is missing or unsafe.",
            )
        import importlib.util

        module_name = "_cyrene_bootstrap_catalog_binding"
        spec = importlib.util.spec_from_file_location(module_name, helper_path)
        if spec is None or spec.loader is None:
            raise UpdateError(
                "INVALID_BOOTSTRAP_BINDING",
                "The installed bootstrap catalog binding verifier cannot be loaded.",
            )
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        try:
            spec.loader.exec_module(module)
            binding = module.load_bootstrap_catalog_binding(
                INSTALLED_BOOTSTRAP_CATALOG_BINDING,
                catalog_path,
                source_catalog_digest=TRUSTED_CATALOG_DIGEST,
            )
        except Exception as error:
            raise UpdateError(
                "INVALID_BOOTSTRAP_BINDING",
                f"The installed bootstrap catalog binding could not be verified: {error}",
            ) from error
        return binding

    def __init__(
        self,
        *,
        catalog_path: Path = DEFAULT_CATALOG,
        activity_catalog_path: Path = DEFAULT_ACTIVITY_CATALOG,
        socket_path: Path = DEFAULT_SOCKET,
        broker_path: Path | None = None,
        install_root: Path = DEFAULT_INSTALL_ROOT,
        state_root: Path = DEFAULT_STATE_ROOT,
        release_lock_path: Path = DEFAULT_RELEASE_LOCK,
        trusted_catalog_digest: str | None = TRUSTED_CATALOG_DIGEST,
        opener: Callable[..., Any] = urllib.request.urlopen,
        runner: Callable[..., subprocess.CompletedProcess[str]] = subprocess.run,
        systemd_unit_dirs: tuple[Path, ...] | None = None,
        data_bundle_root: Path = DEFAULT_DATA_BUNDLE_ROOT,
        authority_admin_socket: Path = DEFAULT_AUTHORITY_ADMIN_SOCKET,
        load_active_catalog: bool = True,
        allow_incomplete_catalog: bool = False,
    ) -> None:
        requested_catalog_path = Path(catalog_path)
        installed_catalog_paths = {
            Path(INSTALLED_CATALOG),
            Path(INSTALLED_CATALOG_V2),
        }
        packaged_helper = self._running_from_installed_helper()
        if packaged_helper and requested_catalog_path not in installed_catalog_paths:
            raise UpdateError(
                "UNSAFE_CATALOG",
                "The installed updater can use only its fixed bootstrap catalog path.",
            )
        self.catalog_path = requested_catalog_path
        self.activity_catalog_path = Path(activity_catalog_path)
        self.socket_path = Path(socket_path)
        # None means resolve only the catalog-pinned, installed broker. An explicit
        # path preserves the legacy/test override without changing its semantics.
        self.broker_path = Path(broker_path) if broker_path is not None else None
        self.install_root = Path(install_root)
        self.state_root = Path(state_root)
        self.data_bundle_root = Path(data_bundle_root)
        self.release_lock_path = Path(release_lock_path)
        self.authority_admin_socket = Path(authority_admin_socket)
        self.opener = opener
        self.runner = runner
        self.allow_incomplete_catalog = allow_incomplete_catalog
        self.systemd_unit_dirs = (
            tuple(Path(path) for path in systemd_unit_dirs)
            if systemd_unit_dirs is not None
            else (
                Path("/etc/systemd/system"),
                Path("/lib/systemd/system"),
                Path("/usr/lib/systemd/system"),
            )
        )
        if self.catalog_path.is_symlink():
            raise UpdateError(
                "UNSAFE_CATALOG", "The trusted component catalog path must not be a symbolic link."
            )
        catalog_info = self.catalog_path.lstat()
        if not stat.S_ISREG(catalog_info.st_mode):
            raise UpdateError(
                "UNSAFE_CATALOG", "The trusted component catalog must be a regular file."
            )
        if self.catalog_path in installed_catalog_paths and (
            catalog_info.st_uid != 0 or stat.S_IMODE(catalog_info.st_mode) & 0o022
        ):
            raise UpdateError(
                "UNSAFE_CATALOG",
                "The installed component catalog must be root-owned and not group/world writable.",
            )
        bootstrap_bytes = self.catalog_path.read_bytes()
        bootstrap_digest = "sha256:" + hashlib.sha256(bootstrap_bytes).hexdigest()
        self.bootstrap_catalog_binding: dict[str, Any] | None = None
        if self.catalog_path in installed_catalog_paths:
            # The package binding selects the official catalog release without baking a
            # release-specific digest into this helper's source bytes.
            self.bootstrap_catalog_binding = self._load_installed_bootstrap_catalog_binding()
            binding_catalog = self.bootstrap_catalog_binding.get("catalog")
            binding_digest = (
                binding_catalog.get("sha256") if isinstance(binding_catalog, dict) else None
            )
            if (
                not isinstance(binding_digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", binding_digest) is None
                or "sha256:" + binding_digest != bootstrap_digest
            ):
                raise UpdateError(
                    "CATALOG_DIGEST_MISMATCH",
                    "The installed component catalog differs from its validated package binding.",
                )
            self.bootstrap_catalog_authorized = True
        else:
            if trusted_catalog_digest is not None and bootstrap_digest != trusted_catalog_digest:
                raise UpdateError(
                    "CATALOG_DIGEST_MISMATCH",
                    "The source component catalog does not match its compiled authority pin.",
                )
            # Keep broker resolution tied to the source-compiled authority pin even
            # when a development caller supplies a separate catalog digest.
            self.bootstrap_catalog_authorized = bootstrap_digest == TRUSTED_CATALOG_DIGEST
        self.bootstrap_catalog_digest = bootstrap_digest
        self.bootstrap_catalog_bytes = bootstrap_bytes
        self.load_active_catalog = load_active_catalog
        self._index_cache: dict[
            tuple[str, ...],
            tuple[dict[str, Any], str, tuple[dict[str, Any], ...], str],
        ] = {}
        self._index_asset_identity: dict[tuple[str, ...], tuple[str, str]] = {}
        self._release_list_cache: dict[tuple[str, str, str], bytes] = {}
        self._readiness_cache: dict[tuple[str, bool], dict[str, Any]] = {}
        self.catalog_source: dict[str, Any] | None = None
        self.catalog_bytes = bootstrap_bytes
        self.catalog_digest = bootstrap_digest
        try:
            catalog_value = json.loads(bootstrap_bytes.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_LOCAL_STATE", f"Cannot read component catalog: {error}"
            ) from error
        if load_active_catalog:
            active = self._read_active_catalog()
            if active is not None:
                catalog_bytes, metadata = active
                try:
                    catalog_value = json.loads(catalog_bytes.decode("utf-8"))
                except (UnicodeDecodeError, json.JSONDecodeError) as error:
                    raise UpdateError(
                        "INVALID_CATALOG", f"The active component catalog is invalid: {error}"
                    ) from error
                self.catalog_bytes = catalog_bytes
                self.catalog_digest = metadata["catalogSha256"]
                self.catalog_source = metadata
        if not isinstance(catalog_value, dict):
            raise UpdateError("INVALID_CATALOG", "The component catalog must be a JSON object.")
        self.catalog = catalog_value
        if (
            isinstance(self.catalog.get("schemaVersion"), bool)
            or self.catalog.get("schemaVersion") not in {1, 2}
            or not isinstance(self.catalog.get("components"), list)
        ):
            raise UpdateError(
                "INVALID_CATALOG", "The installed component catalog has an unsupported schema."
            )
        generation = self.catalog.get("generation")
        if not isinstance(generation, int) or isinstance(generation, bool) or generation < 1:
            raise UpdateError(
                "INVALID_CATALOG", "The installed component catalog generation is invalid."
            )
        self.catalog_generation = generation
        self.components = {
            item.get("componentId"): item
            for item in self.catalog["components"]
            if isinstance(item, dict) and isinstance(item.get("componentId"), str)
        }
        self.targets = {
            item["id"]: item
            for item in self.catalog.get("targets", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        }
        self.native_python_profiles = self._read_native_python_profiles()
        self.publishers = {
            item["repository"]: item
            for item in self.catalog.get("publishers", [])
            if isinstance(item, dict) and isinstance(item.get("repository"), str)
        }
        self.publisher_ids = {
            item["id"]: item
            for item in self.catalog.get("publishers", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        }

    def _read_native_python_profiles(self) -> dict[str, dict[str, Any]]:
        """Read package-pinned Python target profiles; a missing lock disables Python updates."""

        path = self.release_lock_path
        if not path.exists() and not path.is_symlink():
            return {}
        try:
            info = path.lstat()
            if (
                path.is_symlink()
                or not stat.S_ISREG(info.st_mode)
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) & 0o022
            ):
                return {}
            value = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return {}
        profiles = value.get("nativePythonProfiles") if isinstance(value, dict) else None
        if not isinstance(profiles, dict):
            return {}

        validated: dict[str, dict[str, Any]] = {}
        for profile_id, profile in profiles.items():
            if not isinstance(profile_id, str) or not isinstance(profile, dict):
                continue
            if (
                set(profile)
                != set(NATIVE_PYTHON_TARGET_FIELDS)
                | {"pythonVersion", "pythonExecutable", "pythonInput", "wheelResolver"}
                or profile.get("pythonVersion") != "3.12.14"
                or profile.get("pythonExecutable") != str(DEFAULT_PRIVATE_PYTHON)
                or profile.get("pythonInput") != "packaging/python-runtime.lock.json"
                or profile.get("runtime") != "python:3.12"
                or profile.get("architecture") != "x86_64"
                or profile.get("distribution") != "ubuntu"
                or (profile.get("osVersion"), profile.get("abi"))
                not in {("22.04", "glibc-2.35"), ("24.04", "glibc-2.39")}
            ):
                continue
            resolver = profile.get("wheelResolver")
            if not isinstance(resolver, dict) or not isinstance(
                resolver.get("allowedWheelTags"), dict
            ):
                continue
            allowed = resolver["allowedWheelTags"]
            pep600 = allowed.get("pep600")
            if (
                set(resolver) != {"tool", "version", "arguments", "allowedWheelTags"}
                or set(allowed) != {"purePython", "pep600"}
                or not isinstance(pep600, dict)
                or set(pep600) != {"architecture", "maxGlibc"}
                or resolver.get("tool") != "uv"
                or resolver.get("version") != "0.12.21"
                or resolver.get("arguments") != ["--python-platform", "x86_64-unknown-linux-gnu"]
                or allowed.get("purePython") != ["*-none-any"]
                or pep600.get("architecture") != "x86_64"
                or pep600.get("maxGlibc") != profile["abi"].removeprefix("glibc-")
            ):
                continue
            if (
                profile.get("os") != "linux"
                or profile.get("osVersion") not in {"22.04", "24.04"}
                or profile.get("distributionVersion") != profile.get("osVersion")
                or profile_id != f"linux-ubuntu-{profile['osVersion']}-x86_64-python-3.12"
            ):
                continue
            validated[profile_id] = profile
        return validated

    def _private_python_runtime_ready(self, profile: dict[str, Any]) -> bool:
        """Require the exact root-owned CPython runtime installed by the DEB."""

        executable = Path(str(profile.get("pythonExecutable", "")))
        if executable != DEFAULT_PRIVATE_PYTHON:
            return False
        current = Path(executable.anchor)
        try:
            for part in executable.parts[1:]:
                current = current / part
                info = current.lstat()
                if current == executable:
                    if (
                        not stat.S_ISREG(info.st_mode)
                        or info.st_uid != 0
                        or info.st_mode & 0o022
                        or not os.access(current, os.X_OK)
                    ):
                        return False
                elif not stat.S_ISDIR(info.st_mode) or info.st_uid != 0 or info.st_mode & 0o022:
                    return False
            result = self.runner(
                [
                    str(executable),
                    "-I",
                    "-c",
                    (
                        "import platform,sys; "
                        "print(platform.python_implementation()); "
                        "print('.'.join(map(str, sys.version_info[:3]))); "
                        "print(platform.machine())"
                    ),
                ],
                check=False,
                capture_output=True,
                text=True,
            )
        except OSError:
            return False
        if result.returncode != 0:
            return False
        return result.stdout.strip().splitlines() == [
            "CPython",
            profile["pythonVersion"],
            "x86_64",
        ]

    def _read_active_catalog(self) -> tuple[bytes, dict[str, Any]] | None:
        """Load the public high-water pointer and its protected immutable snapshot."""

        root_exists = ACTIVE_CATALOG_ROOT.exists() or ACTIVE_CATALOG_ROOT.is_symlink()
        pointer_exists = ACTIVE_CATALOG_POINTER.exists() or ACTIVE_CATALOG_POINTER.is_symlink()
        if not root_exists and not pointer_exists:
            return None
        if not pointer_exists:
            if getattr(self, "allow_incomplete_catalog", False) and root_exists:
                # Only the explicit import command enables this recovery path. The public
                # updater and component runner fail closed when first activation stopped
                # after publishing its snapshot directory but before the state pointer.
                return None
            raise UpdateError(
                "UNSAFE_CATALOG",
                "A catalog snapshot directory exists without its protected high-water pointer.",
            )
        if not root_exists:
            raise UpdateError(
                "UNSAFE_CATALOG",
                "The protected catalog high-water pointer exists but its snapshot directory is missing.",
            )
        _verify_root_protected_directory(ACTIVE_CATALOG_ROOT)
        _verify_root_protected_directory(ACTIVE_CATALOG_POINTER.parent)
        if ACTIVE_CATALOG_POINTER.is_symlink() or not ACTIVE_CATALOG_POINTER.is_file():
            raise UpdateError("UNSAFE_CATALOG", "The protected active-catalog pointer is unsafe.")
        pointer_bytes = _read_root_catalog_object(
            ACTIVE_CATALOG_POINTER, "active component-catalog pointer"
        )
        try:
            pointer = json.loads(
                pointer_bytes.decode("utf-8"), object_pairs_hook=_unique_json_object
            )
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_CATALOG", f"Active catalog pointer is invalid: {error}"
            ) from error
        if (
            not isinstance(pointer, dict)
            or set(pointer) != {"schemaVersion", "catalogFile", "attestationFile", "metadata"}
            or isinstance(pointer.get("schemaVersion"), bool)
            or pointer.get("schemaVersion") != 1
        ):
            raise UpdateError("INVALID_CATALOG", "Active catalog pointer has an unsupported shape.")
        metadata = pointer.get("metadata")
        if not isinstance(metadata, dict):
            raise UpdateError("INVALID_CATALOG", "Active catalog metadata is missing.")
        required_metadata = {
            "schemaVersion",
            "repository",
            "workflow",
            "channel",
            "releaseId",
            "sourceCommit",
            "sourceRef",
            "catalogSha256",
            "generation",
            "subjectName",
            "attestationAssetName",
        }
        if set(metadata) != required_metadata:
            raise UpdateError(
                "INVALID_CATALOG", "Active catalog metadata has an unsupported shape."
            )
        digest = metadata.get("catalogSha256")
        match = re.fullmatch(r"sha256:([0-9a-f]{64})", str(digest))
        if (
            isinstance(metadata.get("schemaVersion"), bool)
            or metadata.get("schemaVersion") != 1
            or metadata.get("repository") != "DoHorizon-AI/Cyrene-Workspace"
            or metadata.get("workflow")
            != "DoHorizon-AI/Cyrene-Workspace/.github/workflows/component-catalog-release.yml"
            or metadata.get("channel") not in {"stable", "preview"}
            or not isinstance(metadata.get("releaseId"), str)
            or not isinstance(metadata.get("sourceCommit"), str)
            or re.fullmatch(r"[0-9a-f]{40}", metadata["sourceCommit"]) is None
            or metadata.get("sourceRef")
            not in (
                {"refs/heads/main", "refs/heads/release"}
                if metadata.get("channel") == "stable"
                else {"refs/heads/develop"}
            )
            or match is None
            or not isinstance(metadata.get("generation"), int)
            or isinstance(metadata.get("generation"), bool)
            or metadata["generation"] < 1
            or metadata.get("subjectName") != "component-catalog-v1.json"
            or metadata.get("attestationAssetName") != "component-catalog-v1.json.attestation.jsonl"
        ):
            raise UpdateError("INVALID_CATALOG", "Active catalog metadata identity is invalid.")
        expected_tag = f"catalog-{metadata['channel']}-{metadata['sourceCommit']}"
        if metadata.get("releaseId") != expected_tag:
            raise UpdateError(
                "INVALID_CATALOG", "Active catalog tag does not match its channel/source."
            )
        catalog_name = f"catalog-{match.group(1)}.json"
        attestation_name = f"catalog-{match.group(1)}-{metadata['sourceCommit']}.attestation.jsonl"
        if (
            pointer.get("catalogFile") != catalog_name
            or pointer.get("attestationFile") != attestation_name
        ):
            raise UpdateError(
                "INVALID_CATALOG", "Active catalog pointer paths do not match its digest."
            )
        catalog_bytes = _read_root_catalog_object(
            ACTIVE_CATALOG_ROOT / catalog_name, "active catalog"
        )
        if "sha256:" + hashlib.sha256(catalog_bytes).hexdigest() != digest:
            raise UpdateError(
                "CATALOG_DIGEST_MISMATCH", "Active catalog bytes differ from its receipt."
            )
        _read_root_catalog_object(
            ACTIVE_CATALOG_ROOT / attestation_name, "active catalog detached attestation"
        )
        try:
            catalog_value = json.loads(
                catalog_bytes.decode("utf-8"), object_pairs_hook=_unique_json_object
            )
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_CATALOG", f"Active catalog JSON is invalid: {error}"
            ) from error
        if (
            not isinstance(catalog_value, dict)
            or catalog_value.get("generation") != metadata["generation"]
        ):
            raise UpdateError(
                "INVALID_CATALOG", "Active catalog generation differs from its receipt."
            )
        return catalog_bytes, metadata

    def _ensure_state_root(self) -> Path:
        """Create or validate the private root-owned updater journal directory."""

        try:
            self.state_root.mkdir(parents=True, exist_ok=True, mode=0o700)
        except OSError as error:
            raise UpdateError(
                "UNSAFE_STATE", f"Cannot prepare update state directory: {error}"
            ) from error
        _verify_private_directory(self.state_root)
        return self.state_root

    def _private_state_directory(self, name: str) -> Path:
        if name not in {
            "plans",
            "staged",
            "transactions",
            "locks",
            "installed",
            "placement",
            "attestations",
        }:
            raise UpdateError("UNSAFE_STATE", "Invalid updater state directory.")
        root = self._ensure_state_root()
        directory = root / name
        try:
            directory.mkdir(mode=0o700, exist_ok=True)
        except OSError as error:
            raise UpdateError(
                "UNSAFE_STATE", f"Cannot prepare update state directory {directory}: {error}"
            ) from error
        _verify_private_directory(directory)
        return directory

    def _clear_release_discovery_caches(self) -> None:
        """Discard operation-local release metadata before a new protocol operation."""

        self._index_cache.clear()
        self._index_asset_identity.clear()
        self._release_list_cache.clear()

    def _read_catalog_floor(self) -> dict[str, Any] | None:
        """Read the private monotonic catalog receipt used by privileged operations."""

        floor_path = self.state_root / "catalog-state.json"
        if not self.state_root.exists() and not self.state_root.is_symlink():
            return None
        _verify_private_directory(self.state_root)
        if not floor_path.exists() and not floor_path.is_symlink():
            return None
        if floor_path.is_symlink():
            raise UpdateError("UNSAFE_CATALOG", "Catalog monotonic receipt must not be a symlink.")
        try:
            info = floor_path.lstat()
            if (
                not stat.S_ISREG(info.st_mode)
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) != 0o600
            ):
                raise UpdateError(
                    "UNSAFE_CATALOG", "Catalog monotonic receipt must be a root-owned 0600 file."
                )
        except OSError as error:
            raise UpdateError(
                "UNSAFE_CATALOG", f"Cannot inspect catalog receipt: {error}"
            ) from error
        floor = _read_object(floor_path, "catalog monotonic receipt")
        if (
            set(floor) != {"schemaVersion", "generation", "catalogSha256", "releaseId"}
            or floor.get("schemaVersion") != 1
            or not isinstance(floor.get("generation"), int)
            or isinstance(floor.get("generation"), bool)
            or floor["generation"] < 1
            or not _valid_digest(floor.get("catalogSha256"))
            or not isinstance(floor.get("releaseId"), str)
        ):
            raise UpdateError("INVALID_CATALOG", "Catalog monotonic receipt has an invalid shape.")
        return floor

    def _write_catalog_floor(self, metadata: dict[str, Any]) -> None:
        self._private_state_directory("locks")
        _atomic_json(
            self.state_root / "catalog-state.json",
            {
                "schemaVersion": 1,
                "generation": metadata["generation"],
                "catalogSha256": metadata["catalogSha256"],
                "releaseId": metadata["releaseId"],
            },
            mode=0o600,
        )

    def _check_catalog_floor(self, metadata: dict[str, Any]) -> None:
        floor = self._read_catalog_floor()
        if floor is None:
            return
        generation = metadata["generation"]
        if generation < floor["generation"]:
            raise UpdateError(
                "CATALOG_ROLLBACK",
                "The active catalog generation is below the protected monotonic receipt.",
            )
        if (
            generation == floor["generation"]
            and metadata["catalogSha256"] != floor["catalogSha256"]
        ):
            raise UpdateError(
                "CATALOG_GENERATION_COLLISION",
                "The same catalog generation is already pinned to different raw catalog bytes.",
            )

    def _assert_no_pending_catalog_intent(self) -> None:
        """Do not switch trusted policy while maintenance or restore recovery is pending."""

        transaction_root = self.state_root / "transactions"
        if transaction_root.exists() or transaction_root.is_symlink():
            if transaction_root.is_symlink() or not transaction_root.is_dir():
                raise UpdateError("UNSAFE_STATE", "Update transaction directory is unsafe.")
            _verify_private_directory(transaction_root)
            for path in sorted(transaction_root.iterdir()):
                if path.is_symlink() or not path.is_file():
                    raise UpdateError(
                        "PENDING_MAINTENANCE", "A transaction entry blocks catalog activation."
                    )
                transaction = _read_object(path, "pending component update transaction")
                if transaction.get("phase") not in {"succeeded", "rolled_back"}:
                    raise UpdateError(
                        "PENDING_MAINTENANCE",
                        "Resolve pending maintenance or rollback recovery before importing a catalog.",
                    )

        for service in ("navigator", "yield", "reactor", "exchange", "catalyst"):
            intent = self.install_root / "services" / service / "update-journal.json"
            if intent.exists() or intent.is_symlink():
                raise UpdateError(
                    "PENDING_RESTORE_INTENT",
                    f"Resolve the pending {service} update/restore intent before importing a catalog.",
                )

    def _fetch_catalog_candidate(
        self,
        *,
        channel: str,
        release_id: str | None = None,
        latest: bool = False,
    ) -> tuple[dict[str, Any], bytes, bytes]:
        if channel not in {"stable", "preview"}:
            raise UpdateError("INVALID_CATALOG", "Catalog channel must be stable or preview.")
        if (release_id is None) == (not latest):
            raise UpdateError(
                "INVALID_REQUEST",
                "Specify exactly one catalog release ID or latest-candidate selector.",
            )
        try:
            import importlib.util

            metadata_path = Path(__file__).resolve().with_name("catalog_metadata.py")
            metadata_spec = importlib.util.spec_from_file_location(
                "_cyrene_catalog_metadata", metadata_path
            )
            if metadata_spec is None or metadata_spec.loader is None:
                raise ImportError("catalog metadata module has no import loader")
            catalog_metadata = importlib.util.module_from_spec(metadata_spec)
            metadata_spec.loader.exec_module(catalog_metadata)
        except (ImportError, OSError, AttributeError) as error:
            raise UpdateError(
                "CATALOG_HELPER_MISSING", "The trusted catalog metadata helper is missing."
            ) from error
        with tempfile.TemporaryDirectory(prefix="cyrene-catalog-") as temporary:
            root = Path(temporary)
            raw_path = root / "component-catalog-v1.json"
            metadata_path = root / "component-catalog-v1.metadata.json"
            attestation_path = root / "component-catalog-v1.json.attestation.jsonl"
            try:
                metadata = catalog_metadata.fetch_verified_catalog(
                    channel=channel,
                    release_id=release_id,
                    latest_channel=channel if latest else None,
                    output_path=raw_path,
                    metadata_path=metadata_path,
                    attestation_output_path=attestation_path,
                    schema_root=(
                        CATALOG_SCHEMA_ROOT
                        if CATALOG_SCHEMA_ROOT.is_dir()
                        else Path(__file__).resolve().parents[1] / "governance"
                    ),
                    verify_attestation=self._verify_attestation,
                )
            except Exception as error:
                code = getattr(error, "code", "CATALOG_VERIFICATION_FAILED")
                raise UpdateError(code, f"Trusted catalog verification failed: {error}") from error
            try:
                return metadata, raw_path.read_bytes(), attestation_path.read_bytes()
            except OSError as error:
                raise UpdateError(
                    "CATALOG_HELPER_OUTPUT_INVALID",
                    f"Verified catalog helper omitted an asset: {error}",
                ) from error

    def catalog_status(self) -> dict[str, Any]:
        """Report the active trusted catalog identity without changing it."""

        self._verify_placement_catalog_readonly()
        active = self._read_active_catalog()
        if active is None:
            metadata: dict[str, Any] = {
                "channel": "bootstrap",
                "releaseId": None,
                "sourceCommit": None,
                "sourceRef": None,
                "generation": self.catalog_generation,
                "catalogSha256": self.bootstrap_catalog_digest,
            }
        else:
            _, metadata = active
            self._check_catalog_floor(metadata) if _running_as_root() else None
        return {"status": "ready", "active": metadata}

    def catalog_check(
        self, *, channel: str, release_id: str | None = None, latest: bool = False
    ) -> dict[str, Any]:
        """Verify and describe a catalog candidate without activating it."""

        metadata, _, _ = self._fetch_catalog_candidate(
            channel=channel, release_id=release_id, latest=latest
        )
        return {"status": "candidate_verified", "activated": False, "candidate": metadata}

    def catalog_import(self, *, channel: str, release_id: str) -> dict[str, Any]:
        """Verify an exact immutable catalog release and explicitly activate its metadata."""

        self._require_authorized_process()
        self._ensure_state_root()
        metadata, catalog_bytes, attestation_bytes = self._fetch_catalog_candidate(
            channel=channel, release_id=release_id
        )
        with self._exclusive_update_lock():
            active = self._read_active_catalog()
            floor = self._read_catalog_floor()
            current_generation = self.catalog_generation
            current_digest = self.bootstrap_catalog_digest
            if active is not None:
                current_generation = active[1]["generation"]
                current_digest = active[1]["catalogSha256"]
            if floor is not None:
                if floor["generation"] > current_generation:
                    current_generation = floor["generation"]
                    current_digest = floor["catalogSha256"]
                elif (
                    floor["generation"] == current_generation
                    and floor["catalogSha256"] != current_digest
                ):
                    raise UpdateError(
                        "CATALOG_GENERATION_COLLISION",
                        "The protected catalog receipt conflicts with the active catalog bytes.",
                    )
            candidate_generation = metadata["generation"]
            if candidate_generation < current_generation:
                raise UpdateError(
                    "CATALOG_ROLLBACK", "Catalog import would roll back the active generation."
                )
            if (
                candidate_generation == current_generation
                and metadata["catalogSha256"] != current_digest
            ):
                raise UpdateError(
                    "CATALOG_GENERATION_COLLISION",
                    "The same catalog generation is already pinned to different raw catalog bytes.",
                )
            if (
                active is not None
                and active[1]["generation"] == candidate_generation
                and active[1]["catalogSha256"] == metadata["catalogSha256"]
                and candidate_generation == current_generation
            ):
                self._refresh_active_catalog()
                return {
                    "status": "already_active",
                    "active": active[1],
                    "activated": False,
                }

            self._assert_no_pending_catalog_intent()
            digest_hex = metadata["catalogSha256"].removeprefix("sha256:")
            catalog_name = f"catalog-{digest_hex}.json"
            attestation_name = f"catalog-{digest_hex}-{metadata['sourceCommit']}.attestation.jsonl"
            catalog_path = ACTIVE_CATALOG_ROOT / catalog_name
            attestation_path = ACTIVE_CATALOG_ROOT / attestation_name
            pointer = {
                "schemaVersion": 1,
                "catalogFile": catalog_name,
                "attestationFile": attestation_name,
                "metadata": metadata,
            }
            if not ACTIVE_CATALOG_ROOT.exists() and not ACTIVE_CATALOG_ROOT.is_symlink():
                staging = _stage_initial_catalog_directory(
                    metadata, catalog_bytes, attestation_bytes
                )
                try:
                    _activate_initial_catalog_directory(staging)
                    _atomic_root_catalog_bytes(
                        ACTIVE_CATALOG_POINTER,
                        json.dumps(pointer, ensure_ascii=False, sort_keys=True, indent=2).encode(
                            "utf-8"
                        )
                        + b"\n",
                    )
                    # The public state pointer carries the active generation/digest and remains
                    # readable by non-root service launchers. A crash before this write leaves
                    # an unmarked snapshot that only explicit import recovery may load.
                    self._write_catalog_floor(metadata)
                finally:
                    if staging.exists() and not staging.is_symlink():
                        shutil.rmtree(staging, ignore_errors=True)
            else:
                _verify_root_protected_directory(ACTIVE_CATALOG_ROOT)
                if catalog_path.exists() or catalog_path.is_symlink():
                    existing = _read_root_catalog_object(catalog_path, "catalog snapshot")
                    if (
                        "sha256:" + hashlib.sha256(existing).hexdigest()
                        != metadata["catalogSha256"]
                    ):
                        raise UpdateError(
                            "CATALOG_DIGEST_MISMATCH", "Catalog snapshot path collision detected."
                        )
                else:
                    _atomic_root_catalog_bytes(catalog_path, catalog_bytes)
                if attestation_path.exists() or attestation_path.is_symlink():
                    previous_proof = _read_root_catalog_object(
                        attestation_path, "catalog attestation snapshot"
                    )
                    if previous_proof != attestation_bytes:
                        raise UpdateError(
                            "CATALOG_PROOF_COLLISION",
                            "Detached proof differs for identical catalog bytes.",
                        )
                else:
                    _atomic_root_catalog_bytes(attestation_path, attestation_bytes)
                _atomic_root_catalog_bytes(
                    ACTIVE_CATALOG_POINTER,
                    json.dumps(pointer, ensure_ascii=False, sort_keys=True, indent=2).encode(
                        "utf-8"
                    )
                    + b"\n",
                )
                # The pointer carries the active generation and digest. If interrupted before
                # this receipt update, the next root load advances the floor from that pointer.
                self._write_catalog_floor(metadata)
            self._refresh_active_catalog()
            return {"status": "imported", "active": metadata, "activated": True}

    def _refresh_active_catalog(self) -> None:
        active = self._read_active_catalog()
        if active is None:
            raise UpdateError(
                "UNSAFE_CATALOG", "Catalog activation did not publish an active pointer."
            )
        catalog_bytes, metadata = active
        if _running_as_root():
            floor = self._read_catalog_floor()
            if floor is not None and (
                floor["generation"] > metadata["generation"]
                or (
                    floor["generation"] == metadata["generation"]
                    and floor["catalogSha256"] != metadata["catalogSha256"]
                )
            ):
                raise UpdateError(
                    "CATALOG_ROLLBACK",
                    "Active catalog pointer conflicts with its monotonic receipt.",
                )
            if floor is None or floor["generation"] < metadata["generation"]:
                self._write_catalog_floor(metadata)
        try:
            catalog_value = json.loads(
                catalog_bytes.decode("utf-8"), object_pairs_hook=_unique_json_object
            )
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_CATALOG", f"Active catalog JSON is invalid: {error}"
            ) from error
        if not isinstance(catalog_value, dict):
            raise UpdateError("INVALID_CATALOG", "Active catalog must be a JSON object.")
        self.catalog = catalog_value
        self.catalog_bytes = catalog_bytes
        self.catalog_digest = metadata["catalogSha256"]
        self.catalog_generation = metadata["generation"]
        self.catalog_source = metadata
        self.components = {
            item.get("componentId"): item
            for item in self.catalog.get("components", [])
            if isinstance(item, dict) and isinstance(item.get("componentId"), str)
        }
        self.targets = {
            item["id"]: item
            for item in self.catalog.get("targets", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        }
        self.publishers = {
            item["repository"]: item
            for item in self.catalog.get("publishers", [])
            if isinstance(item, dict) and isinstance(item.get("repository"), str)
        }
        self.publisher_ids = {
            item["id"]: item
            for item in self.catalog.get("publishers", [])
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        }
        self._index_cache.clear()
        self._index_asset_identity.clear()

    def _reload_catalog_for_operation(self) -> None:
        """Re-read the protected active pointer at each check/stage/apply boundary."""

        # These objects are discovery accelerators for one operation only. In particular,
        # a later check/stage/apply must observe the current release list and selected index.
        self._clear_release_discovery_caches()
        active = self._read_active_catalog()
        if active is None:
            if _running_as_root() and self._read_catalog_floor() is not None:
                raise UpdateError(
                    "UNSAFE_CATALOG", "A previously activated catalog pointer is missing."
                )
            if self.catalog_source is not None:
                try:
                    value = json.loads(self.bootstrap_catalog_bytes.decode("utf-8"))
                except (UnicodeDecodeError, json.JSONDecodeError) as error:
                    raise UpdateError(
                        "INVALID_CATALOG", f"Bootstrap catalog is invalid: {error}"
                    ) from error
                self.catalog = value
                self.catalog_bytes = self.bootstrap_catalog_bytes
                self.catalog_digest = self.bootstrap_catalog_digest
                self.catalog_generation = value["generation"]
                self.catalog_source = None
                self.components = {
                    item.get("componentId"): item
                    for item in value.get("components", [])
                    if isinstance(item, dict) and isinstance(item.get("componentId"), str)
                }
                self.targets = {
                    item["id"]: item
                    for item in value.get("targets", [])
                    if isinstance(item, dict) and isinstance(item.get("id"), str)
                }
                self.publishers = {
                    item["repository"]: item
                    for item in value.get("publishers", [])
                    if isinstance(item, dict) and isinstance(item.get("repository"), str)
                }
                self.publisher_ids = {
                    item["id"]: item
                    for item in value.get("publishers", [])
                    if isinstance(item, dict) and isinstance(item.get("id"), str)
                }
                self._index_cache.clear()
                self._index_asset_identity.clear()
            return
        self._refresh_active_catalog()

    def _require_authorized_process(self) -> None:
        if self.state_root == DEFAULT_STATE_ROOT and not _running_as_root():
            raise UpdateError(
                "PRIVILEGE_REQUIRED",
                "The fixed Linux update helper must run with its root-authorized OS identity.",
            )

    @contextmanager
    def _exclusive_update_lock(self):
        lock_path = self._private_state_directory("locks") / "update.lock"
        try:
            descriptor = os.open(
                lock_path,
                os.O_CREAT | os.O_RDWR | getattr(os, "O_NOFOLLOW", 0),
                0o600,
            )
        except OSError as error:
            raise UpdateError(
                "UNSAFE_STATE", f"Cannot open updater transaction lock: {error}"
            ) from error
        try:
            info = os.fstat(descriptor)
            if (
                not stat.S_ISREG(info.st_mode)
                or info.st_uid != os.geteuid()
                or stat.S_IMODE(info.st_mode) & 0o077
            ):
                raise UpdateError(
                    "UNSAFE_STATE", "Updater transaction lock is not a private regular file."
                )
            try:
                fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError as error:
                raise UpdateError(
                    "UPDATE_IN_PROGRESS",
                    "Another updater process is staging or applying a component plan.",
                    retryable=True,
                ) from error
            yield
        finally:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            except OSError:
                pass
            os.close(descriptor)

    @contextmanager
    def _placement_read_lock(self):
        """Take a shared lock without creating updater state or changing files."""

        lock_path = self.state_root / "locks" / "update.lock"
        try:
            info = lock_path.lstat()
            if (
                lock_path.is_symlink()
                or not stat.S_ISREG(info.st_mode)
                or info.st_uid != 0
                or info.st_nlink != 1
                or stat.S_IMODE(info.st_mode) & 0o077
            ):
                raise UpdateError("UNSAFE_STATE", "Updater read lock is unsafe.")
            descriptor = os.open(
                lock_path,
                os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
            )
        except FileNotFoundError as error:
            raise UpdateError(
                "PLACEMENT_STATE_UNKNOWN",
                "The persistent updater lock is missing; peer state cannot be read safely.",
                retryable=True,
            ) from error
        except OSError as error:
            raise UpdateError("UNSAFE_STATE", f"Cannot open updater read lock: {error}") from error
        try:
            deadline = time.monotonic() + 10
            while True:
                try:
                    fcntl.flock(descriptor, fcntl.LOCK_SH | fcntl.LOCK_NB)
                    break
                except BlockingIOError:
                    if time.monotonic() >= deadline:
                        raise UpdateError(
                            "UPDATE_IN_PROGRESS",
                            "A component update is changing local state; retry the peer read.",
                            retryable=True,
                        )
                    time.sleep(0.05)
            yield
        finally:
            try:
                fcntl.flock(descriptor, fcntl.LOCK_UN)
            except OSError:
                pass
            os.close(descriptor)

    def placement_peer_response(
        self,
        *,
        operation: str,
        deployment_id: str,
        requester_host_id: str,
        requester_role_id: str,
        group_id: str,
        nonce: str,
        expected_phase: str | None = None,
    ) -> dict[str, Any]:
        """Build a fresh read-only response from protected local evidence."""

        if not _running_as_root():
            raise UpdateError("PRIVILEGE_REQUIRED", "Peer placement evidence requires root.")
        if (
            operation not in {"placement-peer-plan", "placement-peer-receipt"}
            or not isinstance(nonce, str)
            or re.fullmatch(r"[0-9a-f]{64}", nonce) is None
            or not isinstance(deployment_id, str)
            or not isinstance(requester_host_id, str)
            or not isinstance(requester_role_id, str)
            or group_id != "workspace-product-v2"
            or (operation == "placement-peer-plan" and expected_phase is not None)
            or (
                operation == "placement-peer-receipt"
                and expected_phase
                not in {None, "any", "ABSENT", "STAGED", "PREPARED_HELD", "ACTIVE_HELD", "ACTIVE"}
            )
        ):
            raise UpdateError("INVALID_REQUEST", "Peer placement request is invalid.")
        self._reload_catalog_for_operation()
        group = next(
            (
                item
                for item in self.catalog.get("compatibilityGroups", [])
                if isinstance(item, dict) and item.get("groupId") == group_id
            ),
            None,
        )
        if not isinstance(group, dict) or "deploymentRoles" not in group:
            raise UpdateError("PLACEMENT_INVALID", "The signed host-role group is unavailable.")
        module = self._load_component_placement()
        try:
            context = module.load_placement(group, trusted_catalog_digest=self.catalog_digest)
        except Exception as error:
            raise UpdateError(
                "PLACEMENT_INVALID", f"Local placement is invalid: {error}"
            ) from error
        if (
            context is None
            or context.deployment_id != deployment_id
            or context.peer.host_id != requester_host_id
            or context.peer.role_id != requester_role_id
        ):
            raise UpdateError(
                "PLACEMENT_PEER_IDENTITY_MISMATCH",
                "The caller does not match the fixed signed peer identity.",
            )
        with self._placement_read_lock():
            self._verify_placement_catalog_readonly()
            try:
                current_context = module.load_placement(
                    group, trusted_catalog_digest=self.catalog_digest
                )
            except Exception as error:
                raise UpdateError(
                    "PLACEMENT_INVALID", f"Local placement changed: {error}", retryable=True
                ) from error
            if current_context is None or module.plan_binding(
                current_context
            ) != module.plan_binding(context):
                raise UpdateError(
                    "PLACEMENT_CHANGED", "Local placement changed during peer read.", retryable=True
                )
            snapshot = self._placement_local_snapshot(module, context, group)
            now = int(time.time())
            base = {
                "schemaVersion": 1,
                "deploymentId": context.deployment_id,
                "topologyDigest": context.topology_digest,
                "hostConfigDigest": context.local_config_digest,
                "catalogDigest": context.catalog_digest,
                "groupId": context.group_id,
                "groupVersion": context.group_version,
                "contractLock": context.contract_lock,
                "requesterHostId": requester_host_id,
                "requesterRoleId": requester_role_id,
                "hostId": context.host_id,
                "roleId": context.role_id,
                "issuedAt": now,
                "expiresAt": now + module.MAX_PEER_TTL_SECONDS,
                "planId": snapshot["planId"],
                "planDigest": snapshot["planDigest"],
                "desiredComponents": snapshot["desiredComponents"],
            }
            if operation == "placement-peer-plan":
                return {**base, "challengeNonce": nonce}
            phase = snapshot["phase"]
            requested = None if expected_phase in {None, "any"} else expected_phase
            if requested is not None and requested != phase:
                raise UpdateError(
                    "PLACEMENT_PHASE_CHANGED",
                    "Peer phase changed; fetch fresh evidence.",
                    retryable=True,
                )
            admission, hold = self._placement_admission_evidence(module, context, phase, snapshot)
            return {
                **base,
                "phase": phase,
                "challengeNonce": nonce,
                "activePointer": snapshot["activePointer"],
                "stagedComponents": snapshot["stagedComponents"],
                "activeComponents": snapshot["activeComponents"],
                "transaction": snapshot["transaction"],
                "admissionHold": hold,
                "businessAdmission": admission,
                "services": snapshot["services"],
            }

    def _verify_placement_catalog_readonly(self) -> None:
        """Require the active catalog and monotonic receipt without updating either."""

        active = self._read_active_catalog()
        if active is None:
            if self.catalog_source is not None:
                raise UpdateError(
                    "UNSAFE_CATALOG", "The active catalog pointer disappeared during peer read."
                )
            return
        _catalog_bytes, metadata = active
        floor = self._read_catalog_floor()
        if (
            self.catalog_source is None
            or metadata.get("catalogSha256") != self.catalog_digest
            or metadata.get("generation") != self.catalog_generation
            or floor is None
            or floor.get("catalogSha256") != metadata.get("catalogSha256")
            or floor.get("generation") != metadata.get("generation")
        ):
            raise UpdateError(
                "PLACEMENT_CATALOG_CHANGED",
                "The active signed catalog or its monotonic receipt changed during peer read.",
                retryable=True,
            )

    def _placement_local_snapshot(
        self, module: Any, context: Any, group: dict[str, Any]
    ) -> dict[str, Any]:
        """Read exact stage, pointer, service, and transaction state for this role."""

        if self.state_root.is_symlink():
            raise UpdateError("UNSAFE_STATE", "Updater state root is a symbolic link.")
        if not self.state_root.exists():
            return self._placement_empty_snapshot()
        _verify_private_directory(self.state_root)
        members = {
            member.get("componentId")
            for member in group.get("members", [])
            if isinstance(member, dict) and isinstance(member.get("componentId"), str)
        }
        role = context.local_role
        staged_matches: list[dict[str, Any]] = []
        staged_root = self.state_root / "staged"
        if staged_root.exists() or staged_root.is_symlink():
            _verify_private_directory(staged_root)
            for child in sorted(staged_root.iterdir()):
                if child.is_symlink() or not child.is_dir():
                    raise UpdateError("UNSAFE_STATE", "Staged updater inventory is unsafe.")
                stage_path = child / "stage.json"
                if not stage_path.exists() and not stage_path.is_symlink():
                    continue
                record = _read_object(stage_path, "staged component plan")
                plan = record.get("plan")
                if not isinstance(plan, dict):
                    raise UpdateError("INVALID_STAGE", "Staged component plan identity is missing.")
                plan_id, plan_digest = plan.get("planId"), plan.get("planDigest")
                if (
                    not isinstance(plan_id, str)
                    or PLAN_ID_PATTERN.fullmatch(plan_id) is None
                    or not _valid_digest(plan_digest)
                    or child.name != plan_id
                ):
                    raise UpdateError("INVALID_STAGE", "Staged placement plan identity is invalid.")
                self._validate_staged_record(
                    record,
                    expected_plan_id=plan_id,
                    expected_plan_digest=plan_digest,
                )
                record_ids = {
                    item.get("componentId")
                    for item in record.get("components", [])
                    if isinstance(item, dict) and isinstance(item.get("componentId"), str)
                }
                if not record_ids <= set(self.components):
                    raise UpdateError("INVALID_STAGE", "Staged component IDs are unknown.")
                if not record_ids & (members & role.allowed_members):
                    continue
                binding = self._placement_binding_for_group(plan, context.group_id)
                if binding is None:
                    raise UpdateError(
                        "PLACEMENT_STATE_UNKNOWN",
                        "A staged placement-group plan has no trusted host-role binding.",
                        retryable=True,
                    )
                desired = module._valid_desired_components(binding.get("localDesiredComponents"))
                if not role.required_members <= {item["componentId"] for item in desired}:
                    raise UpdateError(
                        "INVALID_STAGE", "Staged placement plan omits required members."
                    )
                stage_items = {
                    item["componentId"]: item
                    for item in record["components"]
                    if item.get("componentId") in members & role.allowed_members
                }
                if not stage_items:
                    continue
                staged_matches.append(
                    {
                        "planId": plan_id,
                        "planDigest": plan_digest,
                        "desiredComponents": desired,
                        "stageItems": stage_items,
                    }
                )
        if len(staged_matches) > 1:
            raise UpdateError(
                "PLACEMENT_STATE_UNKNOWN", "Multiple staged role plans are ambiguous."
            )

        transactions = self._placement_transaction_state()

        staged_ids: set[str] = set()
        active_rows: list[dict[str, Any]] = []
        desired: list[dict[str, Any]] = []
        plan_id: str | None = None
        plan_digest: str | None = None
        phase: str
        if staged_matches:
            match = staged_matches[0]
            desired = match["desiredComponents"]
            plan_id, plan_digest = match["planId"], match["planDigest"]
            desired_by_id = {item["componentId"]: item for item in desired}
            staged_rows = []
            observed_stage_ids = set(match["stageItems"])
            for component_id, item in sorted(match["stageItems"].items()):
                if component_id not in desired_by_id or not self._placement_item_matches_desired(
                    item, desired_by_id[component_id]
                ):
                    raise UpdateError(
                        "INVALID_STAGE", "Staged payload differs from placement plan."
                    )
                current = self._installed(self.components[component_id])
                if current.get("active") is True and not self._placement_installed_matches(
                    current, desired_by_id[component_id]
                ):
                    raise UpdateError(
                        "PLACEMENT_STATE_UNKNOWN",
                        f"Staged {component_id} differs from its still-active release pointer.",
                        retryable=True,
                    )
                identity = self._placement_component_identity(item, desired_by_id[component_id])
                if current.get("active") is True:
                    active_rows.append(identity)
                else:
                    staged_rows.append(identity)
                    staged_ids.add(component_id)
            for component_id, identity in sorted(desired_by_id.items()):
                if component_id in observed_stage_ids:
                    continue
                component = self.components[component_id]
                installed = self._installed(component)
                if not self._placement_installed_matches(installed, identity):
                    raise UpdateError(
                        "PLACEMENT_STATE_UNKNOWN",
                        f"Unstaged desired component {component_id} is not the exact active release.",
                    )
                active_rows.append(self._placement_component_identity(installed, identity))
            phase = "ACTIVE" if not staged_rows else "STAGED"
        else:
            active_rows = self._placement_active_components(group, role.allowed_members)
            active_ids = {row["componentId"] for row in active_rows}
            if not active_ids:
                phase = "ABSENT"
                desired = []
                staged_rows = []
            elif role.required_members <= active_ids:
                phase = "ACTIVE"
                desired = self._placement_desired_from_active(active_rows)
                staged_rows = []
            else:
                raise UpdateError(
                    "PLACEMENT_STATE_UNKNOWN",
                    "Local role has a partial active cohort without a matching staged plan.",
                    retryable=True,
                )

        active_ids = {row["componentId"] for row in active_rows}
        adoption = self._read_placement_adoption(required=False)
        if (
            adoption is not None
            and adoption.get("phase") == "ACTIVE"
            and (adoption.get("planId") != plan_id or adoption.get("planDigest") != plan_digest)
        ):
            # A settled adoption journal proves the deployment identity, not every
            # later release plan. Subsequent ordinary updates are bound by their
            # own signed plan and live admission evidence.
            adoption = None
        if adoption is not None and adoption.get("groupId") == context.group_id:
            if (
                adoption.get("deploymentId") != context.deployment_id
                or adoption.get("roleId") != context.role_id
                or adoption.get("topologyDigest") != context.topology_digest
                or adoption.get("localConfigDigest") != context.local_config_digest
                or adoption.get("catalogDigest") != context.catalog_digest
                or adoption.get("planId") != plan_id
                or adoption.get("planDigest") != plan_digest
                or adoption.get("desiredComponents") != desired
            ):
                raise UpdateError(
                    "PLACEMENT_STATE_UNKNOWN",
                    "The protected adoption journal no longer matches the signed local plan.",
                    retryable=True,
                )
            adoption_phase = adoption.get("phase")
            if adoption_phase == "RELEASE_PENDING":
                observed_phase = self._observed_placement_release_phase(adoption, module, context)
                adoption = {**adoption, "phase": observed_phase}
                adoption_phase = observed_phase
            if adoption_phase == "PREPARED_HELD":
                if (
                    phase != "STAGED"
                    or active_rows
                    or staged_ids != {item["componentId"] for item in desired}
                ):
                    raise UpdateError(
                        "PLACEMENT_STATE_UNKNOWN",
                        "Prepared adoption does not match a fully staged, inactive cohort.",
                        retryable=True,
                    )
                phase = "PREPARED_HELD"
            elif adoption_phase == "ACTIVE_HELD":
                if active_ids != {item["componentId"] for item in desired} or staged_rows:
                    raise UpdateError(
                        "PLACEMENT_STATE_UNKNOWN",
                        "Held adoption does not match the exact active cohort.",
                        retryable=True,
                    )
                phase = "ACTIVE_HELD"
            elif adoption_phase == "ACTIVE":
                if active_ids != {item["componentId"] for item in desired} or staged_rows:
                    raise UpdateError(
                        "PLACEMENT_STATE_UNKNOWN",
                        "Released adoption does not match the exact active cohort.",
                        retryable=True,
                    )
                phase = "ACTIVE"
            else:
                raise UpdateError(
                    "PLACEMENT_STATE_UNKNOWN",
                    "The protected adoption journal is in an unresolved phase.",
                    retryable=True,
                )
        active_pointer = {
            "present": bool(active_rows),
            "digest": (
                "sha256:" + hashlib.sha256(canonical_jcs(active_rows)).hexdigest()
                if active_rows
                else None
            ),
            "components": active_rows,
        }
        # A staged target does not imply its prior service is inactive or ready.
        # Service inventory is asserted only for an active or held lifecycle phase.
        services = (
            self._placement_service_inventory(
                desired,
                active_ids=active_ids,
            )
            if desired and phase in {"ACTIVE", "PREPARED_HELD", "ACTIVE_HELD"}
            else []
        )
        return {
            "phase": phase,
            "planId": plan_id,
            "planDigest": plan_digest,
            "desiredComponents": desired,
            "stagedComponents": staged_rows,
            "activeComponents": active_rows,
            "activePointer": active_pointer,
            "transaction": transactions,
            "services": services,
        }

    @staticmethod
    def _placement_empty_snapshot() -> dict[str, Any]:
        return {
            "phase": "ABSENT",
            "planId": None,
            "planDigest": None,
            "desiredComponents": [],
            "stagedComponents": [],
            "activeComponents": [],
            "activePointer": {"present": False, "digest": None, "components": []},
            "transaction": {"present": False, "phase": "none"},
            "services": [],
        }

    @staticmethod
    def _placement_binding_for_group(plan: dict[str, Any], group_id: str) -> dict[str, Any] | None:
        bindings = plan.get("deploymentPlacement", [])
        if not isinstance(bindings, list):
            raise UpdateError("INVALID_STAGE", "Staged placement bindings are malformed.")
        matches = [
            item for item in bindings if isinstance(item, dict) and item.get("groupId") == group_id
        ]
        return matches[0] if len(matches) == 1 else None

    def _placement_transaction_state(self) -> dict[str, Any]:
        directory = self.state_root / "transactions"
        if not directory.exists() and not directory.is_symlink():
            return {"present": False, "phase": "none"}
        _verify_private_directory(directory)
        terminal = {"succeeded", "rolled_back", "succeeded-held", "rolled_back-held"}
        pending: list[str] = []
        for path in sorted(directory.glob("*.json")):
            if path.is_symlink() or not path.is_file():
                raise UpdateError("UNSAFE_STATE", "Updater transaction inventory is unsafe.")
            record = _read_object(path, "component update transaction")
            phase = record.get("phase")
            if not isinstance(phase, str):
                raise UpdateError(
                    "PLACEMENT_STATE_UNKNOWN", "Updater transaction phase is unknown."
                )
            if phase not in terminal:
                pending.append(phase)
        if pending:
            return {"present": True, "phase": "pending"}
        return {"present": False, "phase": "none"}

    def _placement_active_components(
        self, group: dict[str, Any], allowed_ids: frozenset[str]
    ) -> list[dict[str, Any]]:
        result = []
        all_ids = {
            member.get("componentId")
            for member in group.get("members", [])
            if isinstance(member, dict) and isinstance(member.get("componentId"), str)
        }
        if not all_ids or not allowed_ids <= all_ids:
            raise UpdateError("PLACEMENT_INVALID", "Signed group role membership is inconsistent.")
        for component_id in sorted(all_ids):
            component = self.components.get(component_id)
            if not isinstance(component, dict):
                raise UpdateError(
                    "PLACEMENT_INVALID", "Signed role references an unknown component."
                )
            installed = self._installed(component)
            if installed.get("active") is not True:
                continue
            if component_id not in allowed_ids:
                raise UpdateError(
                    "PLACEMENT_FOREIGN_ACTIVE",
                    f"Active {component_id} belongs to the other host role.",
                )
            if installed.get("identityAttested") is not True:
                raise UpdateError(
                    "PLACEMENT_IDENTITY_UNKNOWN", f"Active {component_id} is unattested."
                )
            manifest = installed.get("manifest")
            source = manifest.get("source") if isinstance(manifest, dict) else None
            channel = manifest.get("channel") if isinstance(manifest, dict) else None
            target_id = (
                self._manifest_target_id(component, manifest)
                if isinstance(manifest, dict)
                else None
            )
            if (
                not isinstance(source, dict)
                or not isinstance(source.get("commit"), str)
                or channel not in {"stable", "preview"}
                or target_id is None
                or not isinstance(component.get("publisher"), str)
            ):
                raise UpdateError(
                    "PLACEMENT_IDENTITY_UNKNOWN", f"Active {component_id} identity is incomplete."
                )
            prefix = self._component_release_tag_prefix(component, channel) or (
                "preview-" if channel == "preview" else "stable-"
            )
            desired = [
                {
                    "componentId": component_id,
                    "version": installed.get("activeVersion"),
                    "manifestDigest": installed.get("manifestDigest"),
                    "artifactDigest": installed.get("artifactDigest"),
                    "targetId": target_id,
                    "releaseId": prefix + source["commit"],
                    "sourceCommit": source["commit"],
                    "sourceRepository": component["publisher"],
                    "channel": channel,
                }
            ]
            result.append(self._placement_component_identity(installed, desired[0]))
        return result

    def _placement_desired_from_active(
        self, active_rows: list[dict[str, Any]]
    ) -> list[dict[str, Any]]:
        result = []
        for row in active_rows:
            component = self.components[row["componentId"]]
            installed = self._installed(component)
            manifest = installed.get("manifest")
            source = manifest.get("source") if isinstance(manifest, dict) else None
            channel = manifest.get("channel") if isinstance(manifest, dict) else None
            if not isinstance(source, dict) or channel not in {"stable", "preview"}:
                raise UpdateError("PLACEMENT_IDENTITY_UNKNOWN", "Active release source is invalid.")
            prefix = self._component_release_tag_prefix(component, channel) or (
                "preview-" if channel == "preview" else "stable-"
            )
            result.append(
                {
                    "componentId": row["componentId"],
                    "version": installed["activeVersion"],
                    "manifestDigest": installed["manifestDigest"],
                    "artifactDigest": installed["artifactDigest"],
                    "targetId": row["targetId"],
                    "releaseId": prefix + source["commit"],
                    "sourceCommit": source["commit"],
                    "sourceRepository": component["publisher"],
                    "channel": channel,
                }
            )
        return sorted(result, key=lambda item: item["componentId"])

    def _placement_item_matches_desired(
        self, item: dict[str, Any], desired: dict[str, Any]
    ) -> bool:
        manifest = item.get("manifest")
        if not isinstance(manifest, dict):
            return False
        source = manifest.get("source")
        component = self.components.get(item.get("componentId"), {})
        return (
            item.get("version") == desired["version"]
            and item.get("manifestDigest") == desired["manifestDigest"]
            and item.get("artifactDigest") == desired["artifactDigest"]
            and self._manifest_target_id(component, manifest) == desired["targetId"]
            and isinstance(source, dict)
            and source.get("commit") == desired["sourceCommit"]
            and component.get("publisher") == desired["sourceRepository"]
            and manifest.get("channel") == desired["channel"]
            and desired["releaseId"]
            == (
                self._component_release_tag_prefix(component, desired["channel"])
                or ("preview-" if desired["channel"] == "preview" else "stable-")
            )
            + desired["sourceCommit"]
        )

    def _placement_installed_matches(
        self, installed: dict[str, Any], desired: dict[str, Any]
    ) -> bool:
        return (
            installed.get("active") is True
            and installed.get("identityAttested") is True
            and installed.get("activeVersion") == desired["version"]
            and installed.get("manifestDigest") == desired["manifestDigest"]
            and installed.get("artifactDigest") == desired["artifactDigest"]
            and installed.get("releaseIdentity") == desired["manifestDigest"]
            and self._placement_item_matches_desired(
                {
                    "version": installed.get("activeVersion"),
                    "manifestDigest": installed.get("manifestDigest"),
                    "artifactDigest": installed.get("artifactDigest"),
                    "manifest": installed.get("manifest"),
                    "componentId": desired["componentId"],
                },
                desired,
            )
        )

    def _placement_component_identity(
        self, installed: dict[str, Any], desired: dict[str, Any]
    ) -> dict[str, Any]:
        return {
            "componentId": desired["componentId"],
            "manifestDigest": desired["manifestDigest"],
            "artifactDigest": desired["artifactDigest"],
            "targetId": desired["targetId"],
            "releaseIdentity": desired["manifestDigest"],
            "identityAttested": True,
        }

    def _placement_service_inventory(
        self,
        desired: list[dict[str, Any]],
        *,
        active_ids: set[str],
    ) -> list[dict[str, Any]]:
        """Read service, process, executable, and signed health state without changing it."""

        rows = []
        for identity in desired:
            component_id = identity["componentId"]
            component = self.components[component_id]
            if component.get("kind") == "data-bundle":
                continue
            unit = component.get("systemdUnit")
            if not isinstance(unit, str) or not unit.endswith(".service"):
                continue
            installed = self._installed(component)
            manifest = installed.get("manifest")
            if not isinstance(manifest, dict):
                # The candidate manifest is available from its immutable local receipt.
                receipt = self._read_release_receipt(component_id, identity["manifestDigest"])
                manifest = receipt.get("manifest") if isinstance(receipt, dict) else None
            if not isinstance(manifest, dict):
                raise UpdateError(
                    "PLACEMENT_IDENTITY_UNKNOWN",
                    f"Signed service manifest is missing for {component_id}.",
                )
            artifact = manifest.get("artifact")
            entrypoint = artifact.get("entrypoint") if isinstance(artifact, dict) else None
            files = artifact.get("files") if isinstance(artifact, dict) else None
            if (
                not isinstance(entrypoint, str)
                or not isinstance(files, dict)
                or not _valid_digest(files.get(entrypoint))
            ):
                raise UpdateError(
                    "PLACEMENT_IDENTITY_UNKNOWN",
                    f"Signed executable map is missing for {component_id}.",
                )
            release_path = (
                self.install_root
                / "components"
                / component_id
                / "releases"
                / (f"{identity['version']}--{identity['manifestDigest'].removeprefix('sha256:')}")
            )
            executable_path = release_path.joinpath(
                *_safe_relative(entrypoint, field="entrypoint").parts
            )
            expected_digest = files[entrypoint]
            completed = self.runner(
                [
                    "systemctl",
                    "show",
                    unit,
                    "--property=ActiveState",
                    "--property=SubState",
                    "--property=MainPID",
                ],
                capture_output=True,
                text=True,
                timeout=10,
                check=False,
            )
            if completed.returncode != 0:
                raise UpdateError("PLACEMENT_SERVICE_UNKNOWN", f"Cannot inspect {unit}.")
            properties = {}
            for line in completed.stdout.splitlines():
                key, separator, value = line.partition("=")
                if separator and key in {"ActiveState", "SubState", "MainPID"}:
                    properties[key] = value
            active_state = properties.get("ActiveState")
            sub_state = properties.get("SubState")
            pid_text = properties.get("MainPID")
            if pid_text is None or not pid_text.isdecimal():
                raise UpdateError("PLACEMENT_SERVICE_UNKNOWN", f"{unit} process state is unknown.")
            main_pid = int(pid_text)
            if component_id in active_ids:
                if active_state != "active" or sub_state != "running" or main_pid <= 1:
                    raise UpdateError("PLACEMENT_SERVICE_UNHEALTHY", f"{unit} is not running.")
                proc_exe = Path("/proc") / str(main_pid) / "exe"
                try:
                    executable_link = os.readlink(proc_exe)
                    stat_info = proc_exe.stat()
                    digest = _file_digest(proc_exe)
                except OSError as error:
                    raise UpdateError(
                        "PLACEMENT_PROCESS_UNKNOWN", f"Cannot verify {unit} executable."
                    ) from error
                if (
                    executable_link.endswith(" (deleted)")
                    or Path(executable_link) != executable_path
                    or not stat.S_ISREG(stat_info.st_mode)
                    or digest != expected_digest
                ):
                    raise UpdateError(
                        "PLACEMENT_PROCESS_MISMATCH",
                        f"{unit} executable differs from its signed release.",
                    )
                self._placement_health_check(component_id, unit, manifest)
                health = "healthy"
                process_digest = digest
            else:
                if active_state != "inactive" or sub_state != "dead" or main_pid != 0:
                    raise UpdateError(
                        "PLACEMENT_SERVICE_UNHEALTHY", f"{unit} is not confirmed inactive."
                    )
                if (
                    executable_path.is_symlink()
                    or not executable_path.is_file()
                    or _file_digest(executable_path) != expected_digest
                ):
                    raise UpdateError(
                        "PLACEMENT_SERVICE_IDENTITY_UNKNOWN",
                        f"Staged executable differs for {component_id}.",
                    )
                health = None
                process_digest = None
            rows.append(
                {
                    "componentId": component_id,
                    "unit": unit,
                    "activeState": active_state,
                    "subState": sub_state,
                    "mainPid": main_pid,
                    "executablePath": str(executable_path),
                    "executableDigest": expected_digest,
                    "processExecutableDigest": process_digest,
                    "identityAttested": True,
                    "health": health,
                }
            )
        return rows

    def _placement_health_check(
        self, component_id: str, unit: str, manifest: dict[str, Any]
    ) -> None:
        health = manifest.get("health")
        if not isinstance(health, dict):
            raise UpdateError(
                "PLACEMENT_SERVICE_UNHEALTHY", f"Signed health contract is missing for {unit}."
            )
        if health.get("kind") == "systemd-active":
            return
        if health.get("kind") != "http":
            raise UpdateError(
                "PLACEMENT_SERVICE_UNHEALTHY", f"Signed health contract is unsupported for {unit}."
            )
        url = f"http://127.0.0.1:{health['port']}{health['path']}"
        try:
            request = urllib.request.Request(url, headers={"User-Agent": USER_AGENT})
            with urllib.request.urlopen(request, timeout=2) as response:
                if not 200 <= response.status < 400:
                    raise UpdateError(
                        "PLACEMENT_SERVICE_UNHEALTHY", f"{component_id} health check failed."
                    )
        except (OSError, urllib.error.URLError, TimeoutError) as error:
            raise UpdateError(
                "PLACEMENT_SERVICE_UNHEALTHY", f"{component_id} health check failed."
            ) from error

    def _placement_admission_evidence(
        self, module: Any, context: Any, phase: str, snapshot: dict[str, Any]
    ) -> tuple[dict[str, Any], dict[str, Any] | None]:
        unavailable = {
            "source": "unavailable",
            "scope": module._role_admission_scope(context.role_id),
            "state": "unavailable",
        }
        if phase in {"ABSENT", "STAGED"}:
            return unavailable, None
        adoption = self._read_placement_adoption(required=False)
        if phase in {"PREPARED_HELD", "ACTIVE_HELD"} and adoption is None:
            raise UpdateError(
                "PLACEMENT_ADMISSION_UNKNOWN",
                "A persisted local adoption hold is unavailable.",
                retryable=True,
            )
        if phase == "ACTIVE" and adoption is None:
            raise UpdateError(
                "PLACEMENT_ADMISSION_UNKNOWN",
                "A released local placement identity is unavailable.",
                retryable=True,
            )
        if adoption is None:
            # ABSENT/STAGED receipts intentionally carry no business admission proof.
            raise UpdateError(
                "PLACEMENT_ADMISSION_UNKNOWN", "Placement admission is unavailable.", retryable=True
            )
        if adoption.get("phase") == "RELEASE_PENDING":
            adoption = {
                **adoption,
                "phase": self._observed_placement_release_phase(adoption, module, context),
            }
        if context.role_id == "control-host":
            state = self._read_control_admission_state(context)
            expected_phase = phase
            hold = state["adoptionHold"] if phase in {"PREPARED_HELD", "ACTIVE_HELD"} else None
            if phase == "ACTIVE":
                health = self._control_readyz()
                try:
                    module._validate_control_admission(health, None, context)
                except Exception as error:
                    raise UpdateError(
                        "PLACEMENT_ADMISSION_UNKNOWN",
                        "Control-host business admission is not proven open.",
                        retryable=True,
                    ) from error
                return health, None
            if (
                state.get("adoptionHold") is None
                or state["adoptionHold"].get("phase") != expected_phase
                or state["adoptionHold"].get("planDigest") != adoption.get("planDigest")
            ):
                raise UpdateError(
                    "PLACEMENT_ADMISSION_UNKNOWN",
                    "Control-host admission state does not match the protected adoption journal.",
                    retryable=True,
                )
            if phase == "PREPARED_HELD":
                return self._control_admission_response(state, api_ready=False), hold
            health = self._control_readyz()
            self._validate_control_readyz(module, context, state, health)
            return health, hold
        if phase in {"PREPARED_HELD", "ACTIVE_HELD"}:
            hold, admission = self._validate_connector_adoption_hold(adoption)
            return admission, hold
        if phase == "ACTIVE" and context.role_id == "connector-host":
            readiness = self._readiness_for("CORE_RUNTIME", requires_restart=False, force=True)
            catalog, _ = self._activity_catalog()
            gate_generation = readiness.get("gate_generation")
            catalog_generation = readiness.get("install_catalog_generation")
            if (
                type(gate_generation) is not int
                or type(catalog_generation) is not int
                or catalog_generation != catalog["generation"]
            ):
                raise UpdateError(
                    "GATE_UNKNOWN", "Connector readiness generation is stale.", retryable=True
                )
            return {
                "source": "runtime-maintenance.GetUpdateReadiness",
                "scope": "kernel-task-and-runtime-admission",
                "state": self._readiness_admission_state(readiness),
                "gateGeneration": gate_generation,
                "catalogGeneration": catalog_generation,
                "readiness": readiness,
            }, None
        raise UpdateError(
            "PLACEMENT_ADMISSION_UNKNOWN",
            "A real persisted adoption hold or released business-admission proof is unavailable.",
            retryable=True,
        )

    def _placement_adoption_path(self, *, create: bool = False) -> Path:
        directory = self.state_root / "placement"
        if create:
            directory = self._private_state_directory("placement")
        elif directory.exists() or directory.is_symlink():
            _verify_private_directory(directory)
        return directory / PLACEMENT_ADOPTION_JOURNAL

    def _read_placement_adoption(self, *, required: bool) -> dict[str, Any] | None:
        path = self._placement_adoption_path()
        if not path.exists() and not path.is_symlink():
            if required:
                raise UpdateError(
                    "PLACEMENT_ADOPTION_UNKNOWN",
                    "No protected host-placement adoption transaction exists.",
                    retryable=True,
                )
            return None
        try:
            info = path.lstat()
        except OSError as error:
            raise UpdateError("UNSAFE_STATE", "Cannot inspect the placement journal.") from error
        if (
            stat.S_ISLNK(info.st_mode)
            or not stat.S_ISREG(info.st_mode)
            or info.st_uid != os.geteuid()
            or info.st_nlink != 1
            or stat.S_IMODE(info.st_mode) != 0o600
        ):
            raise UpdateError("UNSAFE_STATE", "Placement journal ownership or mode is unsafe.")
        value = _read_object(path, "host-placement adoption journal")
        if (
            value.get("schemaVersion") != 1
            or value.get("groupId") != "workspace-product-v2"
            or value.get("phase")
            not in {
                "PREPARE_PENDING",
                "PREPARED_HELD",
                "APPLY_PENDING",
                "ACTIVE_HELD",
                "RELEASE_PENDING",
                "ACTIVE",
            }
            or not isinstance(value.get("planId"), str)
            or PLAN_ID_PATTERN.fullmatch(value["planId"]) is None
            or not _valid_digest(value.get("planDigest"))
            or not isinstance(value.get("desiredComponents"), list)
            or not isinstance(value.get("componentArtifactDigests"), dict)
            or not isinstance(value.get("deploymentId"), str)
            or value.get("roleId") not in {"control-host", "connector-host"}
        ):
            raise UpdateError("PLACEMENT_STATE_UNKNOWN", "Placement journal schema is invalid.")
        if (
            value.get("roleId") == "connector-host"
            and value.get("phase")
            in {"PREPARED_HELD", "APPLY_PENDING", "ACTIVE_HELD", "RELEASE_PENDING"}
            and (
                not isinstance(value.get("maintenanceToken"), str)
                or len(value["maintenanceToken"]) < 32
            )
        ):
            raise UpdateError(
                "PLACEMENT_ADMISSION_UNKNOWN",
                "Connector adoption journal is missing its protected maintenance token.",
                retryable=True,
            )
        return value

    def _write_placement_adoption(self, value: dict[str, Any]) -> Path:
        path = self._placement_adoption_path(create=True)
        _atomic_json(path, value, mode=0o600)
        return path

    @staticmethod
    def _verify_root_directory(path: Path, *, mode: int | None = None) -> None:
        try:
            info = path.lstat()
        except OSError as error:
            raise UpdateError(
                "CONTROL_ADMISSION_UNKNOWN", "Control admission path is unavailable."
            ) from error
        if (
            stat.S_ISLNK(info.st_mode)
            or not stat.S_ISDIR(info.st_mode)
            or info.st_uid != 0
            or stat.S_IMODE(info.st_mode) & 0o022
            or (mode is not None and stat.S_IMODE(info.st_mode) != mode)
        ):
            raise UpdateError("UNSAFE_CONTROL_ADMISSION", "Control admission directory is unsafe.")

    @staticmethod
    def _verify_root_file(path: Path, *, mode: int, gid: int = 0) -> os.stat_result:
        try:
            info = path.lstat()
        except OSError as error:
            raise UpdateError(
                "CONTROL_ADMISSION_UNKNOWN", "Control admission file is unavailable."
            ) from error
        if (
            stat.S_ISLNK(info.st_mode)
            or not stat.S_ISREG(info.st_mode)
            or info.st_uid != 0
            or info.st_gid != gid
            or info.st_nlink != 1
            or stat.S_IMODE(info.st_mode) != mode
        ):
            raise UpdateError("UNSAFE_CONTROL_ADMISSION", "Control admission file is unsafe.")
        return info

    def _control_admission_identity(self, context: Any) -> tuple[int, dict[str, str]]:
        """Bind control gate writes to the preapproved host profile and actual service identity."""

        path = CONTROL_ADMISSION_PROFILE
        self._verify_root_path_chain(path.parent)
        self._verify_root_directory(path.parent)
        info = self._verify_root_file(path, mode=0o600)
        if info.st_size > 4096:
            raise UpdateError(
                "UNSAFE_CONTROL_ADMISSION", "Workspace admission profile is too large."
            )
        try:
            lines = path.read_text(encoding="utf-8").splitlines()
        except (OSError, UnicodeDecodeError) as error:
            raise UpdateError(
                "CONTROL_ADMISSION_UNKNOWN", "Workspace admission profile is unreadable."
            ) from error
        expected_names = {
            "CYRENE_CONTROL_HOST_ADMISSION_PROFILE",
            "CYRENE_ORGANIZATION_ID",
            "CYRENE_WORKSPACE_ID",
            "CYRENE_WORKSPACE_AUTHORITY_INSTANCE_ID",
        }
        parsed: dict[str, str] = {}
        for line in lines:
            if not line or "=" not in line:
                raise UpdateError(
                    "UNSAFE_CONTROL_ADMISSION", "Workspace admission profile syntax is invalid."
                )
            key, value = line.split("=", 1)
            if (
                key not in expected_names
                or key in parsed
                or not value
                or any(ch.isspace() for ch in value)
            ):
                raise UpdateError(
                    "UNSAFE_CONTROL_ADMISSION", "Workspace admission profile fields are invalid."
                )
            parsed[key] = value
        if (
            set(parsed) != expected_names
            or parsed["CYRENE_CONTROL_HOST_ADMISSION_PROFILE"] != "cyrene.control-host.v1"
        ):
            raise UpdateError(
                "UNSAFE_CONTROL_ADMISSION", "Workspace admission profile is incomplete."
            )
        identity = {
            "organizationId": parsed["CYRENE_ORGANIZATION_ID"],
            "workspaceId": parsed["CYRENE_WORKSPACE_ID"],
            "authorityInstanceId": parsed["CYRENE_WORKSPACE_AUTHORITY_INSTANCE_ID"],
        }
        if identity != context.workspace_identity:
            raise UpdateError(
                "PLACEMENT_IDENTITY_MISMATCH",
                "Workspace admission profile does not match the reviewed host identity.",
            )
        for unit, dropin in CONTROL_ADMISSION_DROPINS.items():
            self._verify_root_path_chain(dropin.parent)
            self._verify_root_directory(dropin.parent)
            self._verify_root_file(dropin, mode=0o644)
            try:
                content = dropin.read_bytes()
            except OSError as error:
                raise UpdateError(
                    "CONTROL_ADMISSION_UNKNOWN", "Admission EnvironmentFile drop-in is unreadable."
                ) from error
            if content != b"[Service]\nEnvironmentFile=/etc/cyrene/workspace-admission.env\n":
                raise UpdateError(
                    "UNSAFE_CONTROL_ADMISSION",
                    f"{unit} does not have the exact mandatory admission EnvironmentFile drop-in.",
                )
        unit = "cyrene-workspace-authority.service"
        fragment = self._systemd_property(unit, "FragmentPath")
        fragment_path = Path(fragment)
        if not fragment_path.is_absolute() or not any(
            self._path_is_under(fragment_path, root)
            for root in (
                Path("/etc/systemd/system"),
                Path("/usr/lib/systemd/system"),
                Path("/lib/systemd/system"),
            )
        ):
            raise UpdateError(
                "UNSAFE_CONTROL_ADMISSION",
                "Authority unit fragment is outside systemd directories.",
            )
        fragment_real = fragment_path.resolve(strict=True)
        self._verify_root_file(fragment_real, mode=0o644)
        user = self._systemd_property(unit, "User")
        group = self._systemd_property(unit, "Group")
        try:
            gid = grp.getgrnam(group).gr_gid if group else pwd.getpwnam(user).pw_gid
        except (KeyError, TypeError) as error:
            raise UpdateError(
                "CONTROL_ADMISSION_UNKNOWN", "Authority service effective group is unknown."
            ) from error
        if gid <= 0:
            raise UpdateError(
                "UNSAFE_CONTROL_ADMISSION", "Authority service must run with a non-root group."
            )
        return gid, identity

    def _systemd_property(self, unit: str, name: str) -> str:
        try:
            result = self.runner(
                ["systemctl", "show", f"--property={name}", "--value", unit],
                capture_output=True,
                text=True,
                timeout=10,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired) as error:
            raise UpdateError(
                "CONTROL_ADMISSION_UNKNOWN", f"Cannot read {name} for {unit}."
            ) from error
        value = result.stdout.strip()
        if result.returncode != 0 or "\n" in value or "\r" in value:
            raise UpdateError("CONTROL_ADMISSION_UNKNOWN", f"Systemd {name} for {unit} is unknown.")
        return value

    @staticmethod
    def _verify_root_path_chain(path: Path) -> None:
        absolute = path.absolute()
        current = Path(absolute.anchor)
        for part in absolute.parts[1:]:
            current /= part
            try:
                info = current.lstat()
            except OSError as error:
                raise UpdateError(
                    "CONTROL_ADMISSION_UNKNOWN", "Control admission path chain is unavailable."
                ) from error
            if (
                stat.S_ISLNK(info.st_mode)
                or not stat.S_ISDIR(info.st_mode)
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) & 0o022
            ):
                raise UpdateError(
                    "UNSAFE_CONTROL_ADMISSION", "Control admission path chain is unsafe."
                )

    def _control_lock(self, reader_gid: int, *, exclusive: bool):
        """Open the fixed control gate lock with the service's exact effective group."""

        root = CONTROL_ADMISSION_ROOT
        if not root.exists():
            if not exclusive:
                raise UpdateError(
                    "CONTROL_ADMISSION_UNKNOWN",
                    "Control admission state is absent.",
                    retryable=True,
                )
            parent = root.parent
            if not parent.exists():
                self._verify_root_directory(parent.parent)
                parent.mkdir(mode=0o755)
            self._verify_root_directory(parent)
            root.mkdir(mode=0o750)
            os.chown(root, 0, reader_gid)
            os.chmod(root, 0o750)
        self._verify_root_path_chain(root.parent)
        self._verify_root_directory(root, mode=0o750)
        if root.stat().st_gid != reader_gid:
            raise UpdateError("UNSAFE_CONTROL_ADMISSION", "Control admission reader group changed.")
        lock_path = root / "admission.lock"
        flags = os.O_RDWR | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
        if exclusive:
            flags |= os.O_CREAT
        created = False
        try:
            if exclusive:
                try:
                    descriptor = os.open(lock_path, flags | os.O_CREAT | os.O_EXCL, 0o660)
                    created = True
                except FileExistsError:
                    descriptor = os.open(lock_path, flags)
            else:
                descriptor = os.open(lock_path, flags)
        except OSError as error:
            raise UpdateError(
                "CONTROL_ADMISSION_UNKNOWN",
                "Control admission lock is unavailable.",
                retryable=True,
            ) from error
        info = os.fstat(descriptor)
        if created:
            os.fchown(descriptor, 0, reader_gid)
            os.fchmod(descriptor, 0o660)
            info = os.fstat(descriptor)
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_uid != 0
            or info.st_gid != reader_gid
            or info.st_nlink != 1
            or stat.S_IMODE(info.st_mode) != 0o660
        ):
            os.close(descriptor)
            raise UpdateError(
                "UNSAFE_CONTROL_ADMISSION", "Control admission lock identity is unsafe."
            )
        fcntl.flock(descriptor, fcntl.LOCK_EX if exclusive else fcntl.LOCK_SH)
        return descriptor

    def _read_control_admission_state(self, context: Any) -> dict[str, Any]:
        gid, identity = self._control_admission_identity(context)
        descriptor = self._control_lock(gid, exclusive=False)
        try:
            path = CONTROL_ADMISSION_ROOT / "state.json"
            info = self._verify_root_file(path, mode=0o640, gid=gid)
            if info.st_size > 32 * 1024:
                raise UpdateError(
                    "UNSAFE_CONTROL_ADMISSION", "Control admission state exceeds its size limit."
                )
            state = _read_object(path, "control admission state")
        finally:
            fcntl.flock(descriptor, fcntl.LOCK_UN)
            os.close(descriptor)
        keys = {
            "schema",
            "source",
            "scope",
            "state",
            "generation",
            "readerGid",
            "catalogDigest",
            "topologyDigest",
            "planDigest",
            "adoptionHold",
        }
        hold_keys = {
            "requestId",
            "organizationId",
            "workspaceId",
            "authorityInstanceId",
            "phase",
            "planDigest",
        }
        hold = state.get("adoptionHold")
        if (
            set(state) != keys
            or state.get("schema") != "cyrene.control-host.product-admission.v1"
            or state.get("source") != "control-host-adoption-helper.v1"
            or state.get("scope") != "workspace-product-v2/control-host"
            or state.get("state") not in {"closed", "open"}
            or type(state.get("generation")) is not int
            or state["generation"] < 1
            or state.get("readerGid") != gid
            or state.get("catalogDigest") != context.catalog_digest
            or state.get("topologyDigest") != context.topology_digest
            or not _valid_digest(state.get("planDigest"))
            or not isinstance(hold, dict)
            or set(hold) != hold_keys
            or {key: hold.get(key) for key in identity} != identity
            or hold.get("planDigest") != state.get("planDigest")
            or hold.get("phase") not in {"PREPARED_HELD", "ACTIVE_HELD", "ACTIVE"}
            or (state["state"] == "open") != (hold.get("phase") == "ACTIVE")
        ):
            raise UpdateError(
                "CONTROL_ADMISSION_UNKNOWN",
                "Control admission state does not match the fixed host identity.",
                retryable=True,
            )
        return state

    def _write_control_admission_state(
        self, context: Any, *, plan_id: str, plan_digest: str, phase: str
    ) -> dict[str, Any]:
        gid, identity = self._control_admission_identity(context)
        descriptor = self._control_lock(gid, exclusive=True)
        try:
            state_path = CONTROL_ADMISSION_ROOT / "state.json"
            old: dict[str, Any] | None = None
            if state_path.exists() or state_path.is_symlink():
                info = self._verify_root_file(state_path, mode=0o640, gid=gid)
                if info.st_size > 32 * 1024:
                    raise UpdateError(
                        "UNSAFE_CONTROL_ADMISSION",
                        "Control admission state exceeds its size limit.",
                    )
                old = _read_object(state_path, "control admission state")
            if phase not in {"PREPARED_HELD", "ACTIVE_HELD", "ACTIVE"}:
                raise UpdateError("INVALID_REQUEST", "Control admission phase is unsupported.")
            if old is not None:
                old_hold = old.get("adoptionHold")
                if (
                    not isinstance(old_hold, dict)
                    or {key: old_hold.get(key) for key in identity} != identity
                    or old.get("catalogDigest") != context.catalog_digest
                    or old.get("topologyDigest") != context.topology_digest
                    or old_hold.get("planDigest") != plan_digest
                    or old.get("planDigest") != plan_digest
                    or (old.get("state") == "open") != (old_hold.get("phase") == "ACTIVE")
                ):
                    raise UpdateError(
                        "CONTROL_ADMISSION_UNKNOWN",
                        "Existing control gate is bound to another adoption plan.",
                        retryable=True,
                    )
                if old_hold.get("phase") == phase:
                    return old
                allowed_transitions = {
                    "PREPARED_HELD": {"PREPARED_HELD", "ACTIVE_HELD"},
                    "ACTIVE_HELD": {"ACTIVE_HELD", "ACTIVE"},
                    "ACTIVE": {"ACTIVE"},
                }
                if phase not in allowed_transitions.get(old_hold.get("phase"), set()):
                    raise UpdateError(
                        "CONTROL_ADMISSION_UNKNOWN",
                        "Control gate transition is not permitted.",
                        retryable=True,
                    )
            elif phase != "PREPARED_HELD":
                raise UpdateError(
                    "CONTROL_ADMISSION_UNKNOWN",
                    "Control gate must be prepared before activation.",
                    retryable=True,
                )
            generation = old["generation"] + 1 if old else 1
            request_id = "cyrene-update-" + plan_id
            state = {
                "schema": "cyrene.control-host.product-admission.v1",
                "source": "control-host-adoption-helper.v1",
                "scope": "workspace-product-v2/control-host",
                "state": "open" if phase == "ACTIVE" else "closed",
                "generation": generation,
                "readerGid": gid,
                "catalogDigest": context.catalog_digest,
                "topologyDigest": context.topology_digest,
                "planDigest": plan_digest,
                "adoptionHold": {
                    "requestId": request_id,
                    **identity,
                    "phase": phase,
                    "planDigest": plan_digest,
                },
            }
            _atomic_control_state(state_path, state, gid=gid)
            return state
        finally:
            fcntl.flock(descriptor, fcntl.LOCK_UN)
            os.close(descriptor)

    def _control_admission_response(
        self, state: dict[str, Any], *, api_ready: bool
    ) -> dict[str, Any]:
        return {
            "status": "ready" if api_ready else "not_ready",
            "apiReady": api_ready,
            "executionReady": False,
            "businessReady": False,
            "gate": {
                "source": "cy-workspace-control-plane.deployment-admission.v1",
                "scope": state["scope"],
                "state": state["state"],
                "readerGid": state["readerGid"],
                "generation": state["generation"],
                "catalogDigest": state["catalogDigest"],
                "topologyDigest": state["topologyDigest"],
                "planDigest": state["planDigest"],
                "adoptionHold": state["adoptionHold"],
            },
        }

    def _control_readyz(self) -> dict[str, Any]:
        request = urllib.request.Request(
            "http://127.0.0.1:8080/readyz", headers={"User-Agent": USER_AGENT}
        )
        try:
            with urllib.request.urlopen(request, timeout=2) as response:
                payload = response.read(32 * 1024 + 1)
                if response.status != 200 or len(payload) > 32 * 1024:
                    raise UpdateError(
                        "CONTROL_ADMISSION_UNKNOWN",
                        "Authority readyz response is not valid.",
                        retryable=True,
                    )
        except (OSError, urllib.error.URLError, TimeoutError) as error:
            raise UpdateError(
                "CONTROL_ADMISSION_UNKNOWN", "Authority readyz is unavailable.", retryable=True
            ) from error
        try:
            value = json.loads(payload.decode("utf-8"), object_pairs_hook=_unique_json_object)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "CONTROL_ADMISSION_UNKNOWN",
                "Authority readyz response is malformed.",
                retryable=True,
            ) from error
        if not isinstance(value, dict):
            raise UpdateError(
                "CONTROL_ADMISSION_UNKNOWN",
                "Authority readyz response is not an object.",
                retryable=True,
            )
        return value

    def _validate_control_readyz(
        self, module: Any, context: Any, state: dict[str, Any], health: dict[str, Any]
    ) -> None:
        hold = state["adoptionHold"] if state["adoptionHold"]["phase"] != "ACTIVE" else None
        try:
            module._validate_control_admission(health, hold, context)
        except Exception as error:
            raise UpdateError(
                "CONTROL_ADMISSION_UNKNOWN",
                "Authority readyz does not match the protected gate state.",
                retryable=True,
            ) from error

    def _validate_connector_adoption_hold(
        self, adoption: dict[str, Any]
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        catalog_generation = adoption.get("catalogGeneration")
        gate_generation = adoption.get("gateGeneration")
        components = adoption.get("desiredComponents")
        component_digests = adoption.get("componentArtifactDigests")
        if (
            not isinstance(catalog_generation, int)
            or isinstance(catalog_generation, bool)
            or not isinstance(gate_generation, int)
            or isinstance(gate_generation, bool)
            or not isinstance(components, list)
            or not isinstance(component_digests, dict)
            or set(component_digests)
            != {item.get("componentId") for item in components if isinstance(item, dict)}
        ):
            raise UpdateError(
                "PLACEMENT_ADMISSION_UNKNOWN",
                "Connector adoption hold identity is malformed.",
                retryable=True,
            )
        token = adoption.get("maintenanceToken")
        proofs = []
        for component_id, artifact_digest in sorted(component_digests.items()):
            request_id = adoption["requestId"]
            result = self._broker_request(
                "ValidateMaintenanceHold",
                {
                    "request_id": adoption["requestId"],
                    "maintenance_token": token,
                    "target_kind": "CORE_RUNTIME",
                    "plan_id": adoption["planId"],
                    "plan_digest": adoption["planDigest"],
                    "component_artifact_digests": component_digests,
                    "component_id": component_id,
                    "artifact_digest": artifact_digest,
                    "expected_gate_generation": gate_generation,
                    "expected_catalog_generation": catalog_generation,
                },
                request_id=request_id,
            )
            expected = {
                "valid": True,
                "request_id": request_id,
                "target_kind": "CORE_RUNTIME",
                "plan_id": adoption["planId"],
                "plan_digest": adoption["planDigest"],
                "component_artifact_digests": component_digests,
                "component_id": component_id,
                "artifact_digest": artifact_digest,
                "gate_generation": gate_generation,
                "catalog_generation": catalog_generation,
            }
            if result != expected:
                raise UpdateError(
                    "PLACEMENT_ADMISSION_UNKNOWN",
                    "Connector maintenance proof differs from the protected adoption plan.",
                    retryable=True,
                )
            proofs.append(
                {
                    "valid": True,
                    "request_id": request_id,
                    "target_kind": "CORE_RUNTIME",
                    "plan": {
                        "plan_id": adoption["planId"],
                        "plan_digest": adoption["planDigest"],
                        "component_artifact_digests": component_digests,
                    },
                    "component_id": component_id,
                    "artifact_digest": artifact_digest,
                    "gate_generation": gate_generation,
                    "catalog_generation": catalog_generation,
                }
            )
        return (
            {
                "kind": "CORE_RUNTIME",
                "requestId": adoption["requestId"],
                "planId": adoption["planId"],
                "planDigest": adoption["planDigest"],
                "componentArtifactDigests": component_digests,
                "gateGeneration": gate_generation,
                "catalogGeneration": catalog_generation,
            },
            {
                "source": "runtime-maintenance.ValidateMaintenanceHold",
                "scope": "kernel-task-and-runtime-admission",
                "state": "closed",
                "proofs": proofs,
            },
        )

    def _placement_peer_evidence(
        self, plan: dict[str, Any], *, operation: str, expected_peer_phases: set[str]
    ) -> tuple[Any, Any, Any, dict[str, Any]]:
        """Read and verify the exact remote release target and fresh phase evidence."""

        groups = [
            item
            for item in self.catalog.get("compatibilityGroups", [])
            if isinstance(item, dict) and item.get("groupId") == "workspace-product-v2"
        ]
        if len(groups) != 1:
            raise UpdateError(
                "PLACEMENT_INVALID", "Signed workspace placement group is unavailable."
            )
        group = groups[0]
        loaded = self._placement_module_for_group(group)
        if loaded is None:
            raise UpdateError("PLACEMENT_INVALID", "Fixed host placement profile is unavailable.")
        module, context = loaded
        binding = self._placement_binding_for_group(plan, context.group_id)
        if binding is None or module.plan_binding(context) != {
            key: binding.get(key) for key in module.plan_binding(context)
        }:
            raise UpdateError(
                "PLACEMENT_CHANGED", "Host placement configuration changed.", retryable=True
            )
        self._revalidate_plan_placement(plan, operation=operation)
        peer_plan = module.fetch_peer_plan(context)
        _peer_candidates, units, paths, digests = self._verify_peer_placement_plan(
            context, peer_plan
        )
        evidence = module.fetch_peer_receipt(
            context,
            plan=peer_plan.payload,
            required_service_ids=frozenset(units),
            required_service_units=units,
            required_service_executable_paths=paths,
            required_service_executable_digests=digests,
        )
        if (
            evidence.stable_digest != peer_plan.stable_digest
            or evidence.phase not in expected_peer_phases
        ):
            raise UpdateError(
                "PLACEMENT_PEER_PHASE", "Peer phase or target changed.", retryable=True
            )
        module.authorize_peer_operation(context, evidence, operation)
        if evidence.stable_digest != binding.get("peerEvidenceDigest"):
            raise UpdateError(
                "PLACEMENT_CHANGED",
                "Peer desired release set changed after staging.",
                retryable=True,
            )
        return module, context, evidence, binding

    def _staged_placement_record(
        self, plan_id: Any, plan_digest: Any
    ) -> tuple[
        dict[str, Any], Path, dict[str, Any], Any, Any, dict[str, Any], list[dict[str, Any]]
    ]:
        self._validate_plan_identity(plan_id, plan_digest)
        stage_path = self.state_root / "staged" / plan_id / "stage.json"
        record = _read_object(stage_path, "staged placement plan")
        self._validate_staged_record(
            record, expected_plan_id=plan_id, expected_plan_digest=plan_digest
        )
        plan = record.get("plan")
        group = next(
            (
                item
                for item in self.catalog.get("compatibilityGroups", [])
                if isinstance(item, dict) and item.get("groupId") == "workspace-product-v2"
            ),
            None,
        )
        if not isinstance(plan, dict) or not isinstance(group, dict):
            raise UpdateError("PLACEMENT_INVALID", "Staged host placement plan is unavailable.")
        loaded = self._placement_module_for_group(group)
        if loaded is None:
            raise UpdateError("PLACEMENT_INVALID", "Fixed host placement profile is unavailable.")
        module, context = loaded
        binding = self._placement_binding_for_group(plan, context.group_id)
        if binding is None:
            raise UpdateError("PLACEMENT_INVALID", "Staged plan has no exact deployment binding.")
        desired = module._valid_desired_components(binding.get("localDesiredComponents"))
        desired_ids = {item["componentId"] for item in desired}
        stage_items = {
            item.get("componentId"): item
            for item in record.get("components", [])
            if isinstance(item, dict)
            and item.get("componentId") in context.local_role.allowed_members
        }
        if (
            not context.local_role.required_members <= desired_ids
            or set(stage_items) != desired_ids
            or any(
                not self._placement_item_matches_desired(stage_items[component_id], desired_item)
                for component_id, desired_item in {
                    item["componentId"]: item for item in desired
                }.items()
            )
        ):
            raise UpdateError(
                "PLACEMENT_INVALID",
                "Adoption requires every desired local component to be staged at its exact signed identity.",
            )
        return record, stage_path, plan, module, context, group, desired

    @staticmethod
    def _placement_confirmation(plan_id: Any, plan_digest: Any, confirmation: Any) -> None:
        if (
            not isinstance(confirmation, dict)
            or set(confirmation) != {"planId", "planDigest", "confirmed"}
            or confirmation.get("confirmed") is not True
            or confirmation.get("planId") != plan_id
            or confirmation.get("planDigest") != plan_digest
        ):
            raise UpdateError(
                "CONFIRMATION_MISMATCH",
                "Host adoption requires confirmation bound to the exact planId and planDigest.",
            )

    def prepare_placement_adoption(
        self, plan_id: Any, plan_digest: Any, confirmation: Any
    ) -> dict[str, Any]:
        """Acquire the fixed host admission hold for one fully staged deployment role."""

        self._require_authorized_process()
        self._placement_confirmation(plan_id, plan_digest, confirmation)
        with self._exclusive_update_lock():
            self._reload_catalog_for_operation()
            _record, _stage_path, plan, module, context, group, desired = (
                self._staged_placement_record(plan_id, plan_digest)
            )
            self._revalidate_plan_placement(plan, operation="stage")
            peer_phases = {"STAGED", "PREPARED_HELD"}
            _module, _context, peer, binding = self._placement_peer_evidence(
                plan, operation="stage", expected_peer_phases=peer_phases
            )
            path = self._placement_adoption_path(create=True)
            adoption = self._read_placement_adoption(required=False)
            if adoption is not None:
                if (
                    adoption.get("planId") != plan_id
                    or adoption.get("planDigest") != plan_digest
                    or adoption.get("deploymentId") != context.deployment_id
                    or adoption.get("roleId") != context.role_id
                    or adoption.get("desiredComponents") != desired
                ):
                    raise UpdateError(
                        "PLACEMENT_ADOPTION_CONFLICT",
                        "Another confirmed host adoption must be resolved first.",
                        retryable=True,
                    )
                if adoption.get("phase") in {"PREPARED_HELD", "ACTIVE_HELD", "ACTIVE"}:
                    self._validate_local_placement_adoption(adoption, module, context)
                    return {
                        "status": adoption["phase"].lower(),
                        "planId": plan_id,
                        "planDigest": plan_digest,
                        "peerPhase": peer.phase,
                    }
                if adoption.get("phase") == "PREPARE_PENDING":
                    if context.role_id == "connector-host":
                        if not isinstance(adoption.get("maintenanceToken"), str):
                            raise UpdateError(
                                "PLACEMENT_ADMISSION_UNKNOWN",
                                "BeginMaintenance outcome is unknown; refusing to acquire a second hold.",
                                retryable=True,
                            )
                        self._validate_connector_adoption_hold(adoption)
                        adoption["phase"] = "PREPARED_HELD"
                        _atomic_json(path, adoption, mode=0o600)
                        self._validate_local_placement_adoption(adoption, module, context)
                        return {
                            "status": "prepared_held",
                            "planId": plan_id,
                            "planDigest": plan_digest,
                            "peerPhase": peer.phase,
                            "gateGeneration": adoption.get("gateGeneration"),
                            "catalogGeneration": adoption.get("catalogGeneration"),
                        }
                    state_path = CONTROL_ADMISSION_ROOT / "state.json"
                    state = (
                        self._read_control_admission_state(context)
                        if state_path.exists() or state_path.is_symlink()
                        else None
                    )
                    if state is None:
                        # No state was committed, so retrying this local atomic prepare is safe.
                        pass
                    elif (
                        state.get("adoptionHold", {}).get("phase") == "PREPARED_HELD"
                        and state.get("planDigest") == plan_digest
                    ):
                        adoption["phase"] = "PREPARED_HELD"
                        adoption["gateGeneration"] = state["generation"]
                        _atomic_json(path, adoption, mode=0o600)
                        self._validate_local_placement_adoption(adoption, module, context)
                        return {
                            "status": "prepared_held",
                            "planId": plan_id,
                            "planDigest": plan_digest,
                            "peerPhase": peer.phase,
                            "gateGeneration": state["generation"],
                            "catalogGeneration": 0,
                        }
                    else:
                        raise UpdateError(
                            "PLACEMENT_ADMISSION_UNKNOWN",
                            "Control gate prepare outcome is unknown; refusing to replace it.",
                            retryable=True,
                        )
            snapshot = self._placement_local_snapshot(module, context, group)
            if (
                snapshot.get("phase") != "STAGED"
                or snapshot.get("activeComponents")
                or snapshot.get("transaction", {}).get("present") is not False
                or {item["componentId"] for item in snapshot.get("stagedComponents", [])}
                != {item["componentId"] for item in desired}
            ):
                raise UpdateError(
                    "PLACEMENT_NOT_COLD",
                    "Explicit first adoption requires the complete signed cohort staged with no active pointer.",
                    retryable=True,
                )
            service_rows = self._placement_service_inventory(desired, active_ids=set())
            if any(
                row.get("activeState") != "inactive"
                or row.get("subState") != "dead"
                or row.get("mainPid") != 0
                or row.get("processExecutableDigest") is not None
                for row in service_rows
            ):
                raise UpdateError(
                    "PLACEMENT_NOT_COLD",
                    "All signed host-role services must be confirmed inactive before adoption.",
                    retryable=True,
                )
            desired_digests = {item["componentId"]: item["artifactDigest"] for item in desired}
            request_id = "cyrene-update-" + plan_id
            activity_catalog: dict[str, Any] | None = None
            activity_sources: list[dict[str, Any]] | None = None
            preflight_readiness: dict[str, Any] | None = None
            if context.role_id == "connector-host":
                activity_catalog, activity_sources = self._activity_catalog()
                preflight_readiness = self._readiness_for(
                    "CORE_RUNTIME", requires_restart=True, force=True
                )
                self._require_ready(preflight_readiness, "CORE_RUNTIME")
                if (
                    preflight_readiness.get("install_catalog_generation")
                    != activity_catalog["generation"]
                ):
                    raise UpdateError(
                        "GATE_UNKNOWN",
                        "Activity catalog changed before adoption hold.",
                        retryable=True,
                    )
            else:
                self._control_admission_identity(context)
            journal: dict[str, Any] = {
                "schemaVersion": 1,
                "groupId": context.group_id,
                "deploymentId": context.deployment_id,
                "roleId": context.role_id,
                "topologyDigest": context.topology_digest,
                "localConfigDigest": context.local_config_digest,
                "catalogDigest": context.catalog_digest,
                "planId": plan_id,
                "planDigest": plan_digest,
                "desiredComponents": desired,
                "componentArtifactDigests": desired_digests,
                "peerEvidenceDigest": binding["peerEvidenceDigest"],
                "peerRoleId": context.peer.role_id,
                "peerHostId": context.peer.host_id,
                "requestId": request_id,
                "targetKind": "CORE_RUNTIME"
                if context.role_id == "connector-host"
                else "PACKAGE_ONLY",
                "phase": "PREPARE_PENDING",
                "createdAt": int(time.time()),
            }
            if context.role_id == "connector-host":
                assert activity_catalog is not None and activity_sources is not None
                assert preflight_readiness is not None
                journal.update(
                    {
                        "expectedGateGeneration": preflight_readiness.get("gate_generation"),
                        "expectedCatalogGeneration": activity_catalog["generation"],
                        "expectedActivitySources": activity_sources,
                    }
                )
            _atomic_json(path, journal, mode=0o600)
            if context.role_id == "connector-host":
                begin_transaction = {
                    "planId": plan_id,
                    "requestId": request_id,
                    "planDigest": plan_digest,
                    "componentArtifactDigests": desired_digests,
                    "targetKind": "CORE_RUNTIME",
                    "expectedGateGeneration": journal["expectedGateGeneration"],
                    "expectedCatalogGeneration": journal["expectedCatalogGeneration"],
                    "expectedActivitySources": activity_sources,
                }
                try:
                    token = self._begin_maintenance(begin_transaction)
                except UpdateError as error:
                    if error.maintenance_not_acquired:
                        current = self._read_placement_adoption(required=True)
                        if (
                            current.get("phase") == "PREPARE_PENDING"
                            and current.get("planId") == plan_id
                            and current.get("planDigest") == plan_digest
                        ):
                            path.unlink()
                            self._fsync_directory(path.parent)
                    raise
                journal["maintenanceToken"] = token
                journal["gateGeneration"] = begin_transaction.get(
                    "maintenanceGateGeneration", journal["expectedGateGeneration"]
                )
                journal["catalogGeneration"] = journal["expectedCatalogGeneration"]
            else:
                state = self._write_control_admission_state(
                    context, plan_id=plan_id, plan_digest=plan_digest, phase="PREPARED_HELD"
                )
                journal["gateGeneration"] = state["generation"]
                journal["catalogGeneration"] = 0
            journal["phase"] = "PREPARED_HELD"
            _atomic_json(path, journal, mode=0o600)
            self._validate_local_placement_adoption(journal, module, context)
            return {
                "status": "prepared_held",
                "planId": plan_id,
                "planDigest": plan_digest,
                "peerPhase": peer.phase,
                "gateGeneration": journal["gateGeneration"],
                "catalogGeneration": journal["catalogGeneration"],
            }

    def validate_placement_adoption(self, plan_id: Any, plan_digest: Any) -> dict[str, Any]:
        """Re-read the exact local hold and peer proof without changing admission state."""

        self._require_authorized_process()
        self._validate_plan_identity(plan_id, plan_digest)
        with self._exclusive_update_lock():
            self._reload_catalog_for_operation()
            _record, _stage_path, plan, module, context, _group, _desired = (
                self._staged_placement_record(plan_id, plan_digest)
            )
            adoption = self._read_placement_adoption(required=True)
            assert adoption is not None
            if adoption.get("planId") != plan_id or adoption.get("planDigest") != plan_digest:
                raise UpdateError(
                    "PLACEMENT_ADOPTION_CONFLICT", "The protected hold belongs to another plan."
                )
            self._validate_local_placement_adoption(adoption, module, context)
            peer_phases = (
                {"PREPARED_HELD", "ACTIVE_HELD", "ACTIVE"}
                if adoption.get("phase") != "PREPARED_HELD"
                else {"STAGED", "PREPARED_HELD"}
            )
            _module, _context, peer, _binding = self._placement_peer_evidence(
                plan,
                operation="apply" if peer_phases != {"STAGED", "PREPARED_HELD"} else "stage",
                expected_peer_phases=peer_phases,
            )
            return {
                "status": adoption["phase"].lower(),
                "planId": plan_id,
                "planDigest": plan_digest,
                "peerPhase": peer.phase,
                "gateGeneration": adoption.get("gateGeneration"),
                "catalogGeneration": adoption.get("catalogGeneration"),
            }

    def _validate_local_placement_adoption(
        self, adoption: dict[str, Any], module: Any, context: Any
    ) -> None:
        if (
            adoption.get("deploymentId") != context.deployment_id
            or adoption.get("roleId") != context.role_id
            or adoption.get("topologyDigest") != context.topology_digest
            or adoption.get("localConfigDigest") != context.local_config_digest
            or adoption.get("catalogDigest") != context.catalog_digest
        ):
            raise UpdateError("PLACEMENT_ADOPTION_CONFLICT", "Host identity changed after prepare.")
        phase = adoption.get("phase")
        if phase not in {"PREPARED_HELD", "ACTIVE_HELD", "ACTIVE"}:
            raise UpdateError(
                "PLACEMENT_ADMISSION_UNKNOWN",
                "Local adoption is not in a proven held or released phase.",
                retryable=True,
            )
        if context.role_id == "connector-host":
            if phase in {"PREPARED_HELD", "ACTIVE_HELD"}:
                self._validate_connector_adoption_hold(adoption)
            else:
                readiness = self._readiness_for("CORE_RUNTIME", requires_restart=False, force=True)
                catalog, _sources = self._activity_catalog()
                if (
                    self._readiness_admission_state(readiness) != "open"
                    or readiness.get("install_catalog_generation") != catalog["generation"]
                ):
                    raise UpdateError(
                        "PLACEMENT_ADMISSION_UNKNOWN",
                        "Connector admission is not proven open.",
                        retryable=True,
                    )
        else:
            state = self._read_control_admission_state(context)
            state_phase = state.get("adoptionHold", {}).get("phase")
            if state.get("planDigest") != adoption.get("planDigest") or state_phase != phase:
                raise UpdateError(
                    "PLACEMENT_ADMISSION_UNKNOWN",
                    "Control gate no longer matches the protected adoption journal.",
                    retryable=True,
                )
            if phase in {"ACTIVE_HELD", "ACTIVE"}:
                module_health = self._control_readyz()
                self._validate_control_readyz(module, context, state, module_health)

    def release_placement_adoption(
        self, plan_id: Any, plan_digest: Any, confirmation: Any
    ) -> dict[str, Any]:
        """Release this host's exact hold only after both hosts prove ACTIVE_HELD."""

        self._require_authorized_process()
        self._placement_confirmation(plan_id, plan_digest, confirmation)
        with self._exclusive_update_lock():
            self._reload_catalog_for_operation()
            _record, _stage_path, plan, module, context, group, desired = (
                self._staged_placement_record(plan_id, plan_digest)
            )
            adoption = self._read_placement_adoption(required=True)
            assert adoption is not None
            if adoption.get("planId") != plan_id or adoption.get("planDigest") != plan_digest:
                raise UpdateError(
                    "PLACEMENT_ADOPTION_CONFLICT", "The protected hold belongs to another plan."
                )
            if adoption.get("phase") == "ACTIVE":
                self._validate_local_placement_adoption(adoption, module, context)
                return {"status": "active", "planId": plan_id, "planDigest": plan_digest}
            if adoption.get("phase") == "RELEASE_PENDING":
                self._verify_local_active_held(plan, module, context, allow_release_pending=True)
                _module, _context, peer, _binding = self._placement_peer_evidence(
                    plan, operation="apply", expected_peer_phases={"ACTIVE_HELD", "ACTIVE"}
                )
                return self._recover_placement_release(adoption, module, context, peer=peer)
            if adoption.get("phase") != "ACTIVE_HELD":
                raise UpdateError(
                    "PLACEMENT_NOT_ACTIVE_HELD",
                    "All local signed services must be healthy under the hold before release.",
                    retryable=True,
                )
            snapshot = self._placement_local_snapshot(module, context, group)
            desired_ids = {item["componentId"] for item in desired}
            if (
                snapshot.get("phase") != "ACTIVE_HELD"
                or {item["componentId"] for item in snapshot.get("activeComponents", [])}
                != desired_ids
            ):
                raise UpdateError(
                    "PLACEMENT_NOT_ACTIVE_HELD",
                    "Local pointer and signed service inventory are not healthy under the hold.",
                    retryable=True,
                )
            _module, _context, peer, _binding = self._placement_peer_evidence(
                plan, operation="apply", expected_peer_phases={"ACTIVE_HELD", "ACTIVE"}
            )
            adoption["phase"] = "RELEASE_PENDING"
            _atomic_json(self._placement_adoption_path(), adoption, mode=0o600)
            if context.role_id == "connector-host":
                self._validate_connector_adoption_hold(adoption)
                end_transaction = {
                    "planId": plan_id,
                    "requestId": adoption["requestId"],
                    "planDigest": plan_digest,
                    "targetKind": "CORE_RUNTIME",
                    "maintenanceToken": adoption["maintenanceToken"],
                }
                try:
                    self._end_maintenance(end_transaction, outcome="SUCCESS", healthy=True)
                except UpdateError as error:
                    readiness = self._readiness_for(
                        "CORE_RUNTIME", requires_restart=False, force=True
                    )
                    if self._readiness_admission_state(readiness) != "open":
                        raise UpdateError(
                            "PLACEMENT_RELEASE_PENDING",
                            "Connector hold release is unconfirmed; it remains journaled for retry.",
                            retryable=True,
                        ) from error
                readiness = self._readiness_for("CORE_RUNTIME", requires_restart=False, force=True)
                catalog, _sources = self._activity_catalog()
                if (
                    self._readiness_admission_state(readiness) != "open"
                    or readiness.get("install_catalog_generation") != catalog["generation"]
                ):
                    raise UpdateError(
                        "PLACEMENT_RELEASE_PENDING",
                        "Connector READY admission readback failed after release.",
                        retryable=True,
                    )
            else:
                self._write_control_admission_state(
                    context, plan_id=plan_id, plan_digest=plan_digest, phase="ACTIVE_HELD"
                )
                state = self._read_control_admission_state(context)
                self._validate_control_readyz(module, context, state, self._control_readyz())
                self._write_control_admission_state(
                    context, plan_id=plan_id, plan_digest=plan_digest, phase="ACTIVE"
                )
                opened = self._read_control_admission_state(context)
                self._validate_control_readyz(module, context, opened, self._control_readyz())
            adoption["phase"] = "ACTIVE"
            adoption.pop("maintenanceToken", None)
            _atomic_json(self._placement_adoption_path(), adoption, mode=0o600)
            return {
                "status": "active",
                "planId": plan_id,
                "planDigest": plan_digest,
                "peerPhase": peer.phase,
            }

    def _recover_placement_release(
        self, adoption: dict[str, Any], module: Any, context: Any, peer: Any
    ) -> dict[str, Any]:
        """Resolve a lost End response from authoritative local admission state."""

        plan_id = adoption["planId"]
        plan_digest = adoption["planDigest"]
        if context.role_id == "connector-host":
            readiness = self._readiness_for("CORE_RUNTIME", requires_restart=False, force=True)
            catalog, _sources = self._activity_catalog()
            if readiness.get("install_catalog_generation") != catalog["generation"]:
                raise UpdateError(
                    "PLACEMENT_RELEASE_PENDING",
                    "Connector catalog generation changed during release recovery.",
                    retryable=True,
                )
            if self._readiness_admission_state(readiness) != "open":
                # The exact hold still exists: prove it before retrying End.
                self._validate_connector_adoption_hold(adoption)
                self._end_maintenance(
                    {
                        "planId": plan_id,
                        "requestId": adoption["requestId"],
                        "planDigest": plan_digest,
                        "targetKind": "CORE_RUNTIME",
                        "maintenanceToken": adoption["maintenanceToken"],
                    },
                    outcome="SUCCESS",
                    healthy=True,
                )
                readiness = self._readiness_for("CORE_RUNTIME", requires_restart=False, force=True)
                catalog, _sources = self._activity_catalog()
                if (
                    self._readiness_admission_state(readiness) != "open"
                    or readiness.get("install_catalog_generation") != catalog["generation"]
                ):
                    raise UpdateError(
                        "PLACEMENT_RELEASE_PENDING",
                        "Connector release remains unconfirmed after EndMaintenance retry.",
                        retryable=True,
                    )
        else:
            state = self._read_control_admission_state(context)
            if state.get("state") != "open" or state.get("planDigest") != plan_digest:
                self._write_control_admission_state(
                    context, plan_id=plan_id, plan_digest=plan_digest, phase="ACTIVE"
                )
            state = self._read_control_admission_state(context)
            self._validate_control_readyz(module, context, state, self._control_readyz())
        adoption["phase"] = "ACTIVE"
        adoption.pop("maintenanceToken", None)
        _atomic_json(self._placement_adoption_path(), adoption, mode=0o600)
        return {"status": "active", "planId": plan_id, "planDigest": plan_digest}

    @staticmethod
    def _readiness_admission_state(readiness: dict[str, Any]) -> str:
        """Preserve real busy and unknown snapshots without calling them idle."""

        status = readiness.get("status")
        if status in {
            "READY",
            "ACTIVE_TASKS",
            "ACTIVE_BINDING_OPERATIONS",
            "IDLE_RUNTIME_REQUIRES_UNLOAD",
            "USER_CONFIRMATION_REQUIRED",
        }:
            return "open"
        if status == "MAINTENANCE_ACTIVE":
            return "closed"
        return "unknown"

    def _observed_placement_release_phase(
        self, adoption: dict[str, Any], module: Any, context: Any
    ) -> str:
        """Resolve RELEASE_PENDING from the live gate, not from journal intent."""

        if context.role_id == "connector-host":
            readiness = self._readiness_for("CORE_RUNTIME", requires_restart=False, force=True)
            catalog, _sources = self._activity_catalog()
            if readiness.get("install_catalog_generation") != catalog["generation"]:
                raise UpdateError(
                    "PLACEMENT_ADMISSION_UNKNOWN",
                    "Connector catalog generation changed while release outcome was pending.",
                    retryable=True,
                )
            state = self._readiness_admission_state(readiness)
            if state == "open":
                return "ACTIVE"
            if state == "closed":
                self._validate_connector_adoption_hold(adoption)
                return "ACTIVE_HELD"
            raise UpdateError(
                "PLACEMENT_ADMISSION_UNKNOWN",
                "Connector release outcome is still unknown.",
                retryable=True,
            )
        state = self._read_control_admission_state(context)
        if state.get("planDigest") != adoption.get("planDigest"):
            raise UpdateError(
                "PLACEMENT_ADMISSION_UNKNOWN",
                "Control gate plan differs from the pending release journal.",
                retryable=True,
            )
        phase = state.get("adoptionHold", {}).get("phase")
        if phase not in {"ACTIVE_HELD", "ACTIVE"}:
            raise UpdateError(
                "PLACEMENT_ADMISSION_UNKNOWN",
                "Control gate release outcome is unknown.",
                retryable=True,
            )
        self._validate_control_readyz(module, context, state, self._control_readyz())
        return phase

    def handle(self, request: Any) -> dict[str, Any]:
        """Validate and dispatch one fixed request, returning a shared envelope."""
        if (
            isinstance(request, dict)
            and request.get("protocolVersion") == WORKLOAD_PROTOCOL_VERSION
        ):
            return self.handle_workload(request)
        operation = request.get("operation") if isinstance(request, dict) else None
        envelope_operation = (
            operation
            if isinstance(operation, str)
            and operation
            in {
                "status",
                "check",
                "stage",
                "apply",
                "prepare-adoption",
                "validate-adoption",
                "release-adoption",
                "check-plugin-package",
                "install-plugin-package",
            }
            else "status"
        )
        try:
            if not isinstance(request, dict) or request.get("protocolVersion") != PROTOCOL_VERSION:
                raise UpdateError(
                    "INVALID_REQUEST", "Unsupported component update protocol version."
                )
            fields_by_operation = {
                "status": {
                    "protocolVersion",
                    "operation",
                    "bootstrapMode",
                    "includeProducts",
                },
                "check": {
                    "protocolVersion",
                    "operation",
                    "componentIds",
                    "channel",
                    "bootstrapMode",
                    "includeProducts",
                    "heldRecovery",
                },
                "stage": {
                    "protocolVersion",
                    "operation",
                    "planId",
                    "planDigest",
                    "channel",
                    "bootstrapMode",
                    "heldRecovery",
                },
                "apply": {
                    "protocolVersion",
                    "operation",
                    "planId",
                    "planDigest",
                    "confirmation",
                    "channel",
                    "bootstrapMode",
                    "heldRecovery",
                },
                "prepare-adoption": {
                    "protocolVersion",
                    "operation",
                    "planId",
                    "planDigest",
                    "confirmation",
                },
                "validate-adoption": {
                    "protocolVersion",
                    "operation",
                    "planId",
                    "planDigest",
                },
                "release-adoption": {
                    "protocolVersion",
                    "operation",
                    "planId",
                    "planDigest",
                    "confirmation",
                },
                "check-plugin-package": {"protocolVersion", "operation"},
                "install-plugin-package": {
                    "protocolVersion",
                    "operation",
                    "planId",
                    "planDigest",
                    "confirmation",
                },
            }
            if (
                operation not in fields_by_operation
                or set(request) - fields_by_operation[operation]
            ):
                raise UpdateError(
                    "INVALID_REQUEST", "The request contains an unsupported operation or field."
                )
            self._require_authorized_process()
            if "bootstrapMode" in request and request.get("bootstrapMode") != "first-core":
                raise UpdateError("INVALID_REQUEST", "Unsupported first-install bootstrap mode.")
            if "heldRecovery" in request and request.get("bootstrapMode") != "first-core":
                raise UpdateError(
                    "INVALID_REQUEST", "heldRecovery requires explicit first-core mode."
                )
            if "includeProducts" in request and request.get("bootstrapMode") != "first-core":
                raise UpdateError(
                    "INVALID_REQUEST", "Product first-start selection requires first-core mode."
                )
            if "includeProducts" in request and not isinstance(
                request.get("includeProducts"), bool
            ):
                raise UpdateError("INVALID_REQUEST", "includeProducts must be a boolean.")
            if request.get("bootstrapMode") == "first-core":
                import importlib.util

                helper_path = Path(__file__).with_name("native_core_bootstrap.py")
                if not helper_path.is_file():
                    helper_path = Path(__file__).resolve().parent / "native_core_bootstrap.py"
                spec = importlib.util.spec_from_file_location(
                    "_cyrene_native_core_bootstrap", helper_path
                )
                if spec is None or spec.loader is None:
                    raise UpdateError(
                        "HELPER_UNAVAILABLE", "First-Core bootstrap helper is missing."
                    )
                module = importlib.util.module_from_spec(spec)
                sys.modules[spec.name] = module
                spec.loader.exec_module(module)
                if "heldRecovery" in request:
                    successor_path = Path(__file__).with_name("native_core_successor.py")
                    if not successor_path.is_file() or successor_path.is_symlink():
                        raise UpdateError("HELPER_UNAVAILABLE", "Held successor helper is missing.")
                    successor_spec = importlib.util.spec_from_file_location(
                        "_cyrene_native_core_successor", successor_path
                    )
                    if successor_spec is None or successor_spec.loader is None:
                        raise UpdateError("HELPER_UNAVAILABLE", "Held successor helper is missing.")
                    successor_module = importlib.util.module_from_spec(successor_spec)
                    sys.modules[successor_spec.name] = successor_module
                    successor_spec.loader.exec_module(successor_module)
                    bootstrap_result = successor_module.handle(self, request, module)
                else:
                    bootstrap_result = module.handle(self, request)
                if bootstrap_result is not None:
                    return {
                        "protocolVersion": PROTOCOL_VERSION,
                        "ok": True,
                        "operation": envelope_operation,
                        "result": bootstrap_result,
                    }
            if operation == "status":
                result = self.status()
            elif operation == "check":
                result = self.check(request.get("componentIds"), channel=request.get("channel"))
            elif operation == "stage":
                result = self.stage(
                    request.get("planId"), request.get("planDigest"), channel=request.get("channel")
                )
            elif operation == "check-plugin-package":
                result = self.inspect_plugin_package_plan()
            elif operation == "prepare-adoption":
                result = self.prepare_placement_adoption(
                    request.get("planId"),
                    request.get("planDigest"),
                    request.get("confirmation"),
                )
            elif operation == "validate-adoption":
                result = self.validate_placement_adoption(
                    request.get("planId"), request.get("planDigest")
                )
            elif operation == "release-adoption":
                result = self.release_placement_adoption(
                    request.get("planId"),
                    request.get("planDigest"),
                    request.get("confirmation"),
                )
            elif operation == "install-plugin-package":
                result = self.bootstrap_plugin_package_runtime(
                    plan_id=request.get("planId"),
                    plan_digest=request.get("planDigest"),
                    confirmation=request.get("confirmation"),
                )
            else:
                result = self.apply(
                    request.get("planId"),
                    request.get("planDigest"),
                    request.get("confirmation"),
                    channel=request.get("channel"),
                )
            return {
                "protocolVersion": PROTOCOL_VERSION,
                "ok": True,
                "operation": envelope_operation,
                "result": result,
            }
        except UpdateError as error:
            return {
                "protocolVersion": PROTOCOL_VERSION,
                "ok": False,
                "operation": envelope_operation,
                "error": {"code": error.code, "message": str(error), "retryable": error.retryable},
            }
        except Exception as error:  # noqa: BLE001 - preserve the fixed protocol envelope on unexpected helper errors.
            print(f"component update helper internal error: {error}", file=sys.stderr)
            return {
                "protocolVersion": PROTOCOL_VERSION,
                "ok": False,
                "operation": envelope_operation,
                "error": {
                    "code": "INTERNAL_ERROR",
                    "message": "The component update helper could not complete this request.",
                    "retryable": False,
                },
            }

    def handle_workload(self, request: Any) -> dict[str, Any]:
        """Serve the fixed workload plan protocol over the installed root helper."""

        operation = request.get("operation") if isinstance(request, dict) else None
        public_operation = (
            operation
            if isinstance(operation, str) and operation in {"status", "check", "stage", "apply"}
            else "status"
        )
        try:
            if (
                not isinstance(request, dict)
                or request.get("protocolVersion") != WORKLOAD_PROTOCOL_VERSION
            ):
                raise UpdateError("INVALID_REQUEST", "Unsupported workload plan protocol version.")
            fields_by_operation = {
                "status": {"protocolVersion", "operation", "workloadId"},
                "check": {
                    "protocolVersion",
                    "operation",
                    "workloadId",
                    "targetId",
                    "selections",
                    "action",
                    "channel",
                },
                "stage": {
                    "protocolVersion",
                    "operation",
                    "workloadId",
                    "targetId",
                    "planId",
                    "planDigest",
                    "action",
                    "channel",
                },
                "apply": {
                    "protocolVersion",
                    "operation",
                    "workloadId",
                    "targetId",
                    "planId",
                    "planDigest",
                    "confirmation",
                    "action",
                    "channel",
                },
            }
            if (
                operation not in fields_by_operation
                or set(request) - fields_by_operation[operation]
            ):
                raise UpdateError("INVALID_REQUEST", "The workload request has unsupported fields.")
            if operation in {"stage", "apply"} and (
                "action" not in request or "channel" not in request
            ):
                raise UpdateError(
                    "INVALID_REQUEST",
                    "Stage and apply must repeat the checked action and channel.",
                )
            self._require_authorized_process()
            if operation == "status":
                result = self.workload_status(request.get("workloadId"))
            elif operation == "check":
                action = request.get("action", "install")
                result = self.check_workload(
                    request.get("workloadId"),
                    request.get("targetId"),
                    request.get("selections", {}),
                    action=action,
                    channel=request.get("channel"),
                )
            elif operation == "stage":
                result = self.stage_workload(
                    request.get("workloadId"),
                    request.get("targetId"),
                    request.get("planId"),
                    request.get("planDigest"),
                    action=request.get("action"),
                    channel=request.get("channel"),
                )
            else:
                result = self.apply_workload(
                    request.get("workloadId"),
                    request.get("targetId"),
                    request.get("planId"),
                    request.get("planDigest"),
                    request.get("confirmation"),
                    action=request.get("action"),
                    channel=request.get("channel"),
                )
            return {
                "protocolVersion": WORKLOAD_PROTOCOL_VERSION,
                "ok": True,
                "operation": public_operation,
                "result": result,
            }
        except UpdateError as error:
            return {
                "protocolVersion": WORKLOAD_PROTOCOL_VERSION,
                "ok": False,
                "operation": public_operation,
                "error": {"code": error.code, "message": str(error), "retryable": error.retryable},
            }
        except Exception as error:  # noqa: BLE001 - keep the fixed workload response shape.
            print(f"workload plan helper internal error: {error}", file=sys.stderr)
            return {
                "protocolVersion": WORKLOAD_PROTOCOL_VERSION,
                "ok": False,
                "operation": public_operation,
                "error": {
                    "code": "INTERNAL_ERROR",
                    "message": "The workload plan helper could not complete this request.",
                    "retryable": False,
                },
            }

    def workload_status(self, workload_id: Any = None) -> dict[str, Any]:
        """Read local component receipts without changing the runtime or fetching releases."""

        self._reload_catalog_for_operation()
        self._ensure_state_root()
        if workload_id is not None and workload_id not in WORKLOAD_IDS:
            raise UpdateError("INVALID_WORKLOAD_ID", "Unknown workload ID.")
        selected_ids = (
            self._load_workload_resolver().potential_component_ids(self.catalog, workload_id)
            if workload_id is not None and self.catalog.get("schemaVersion") == 2
            else tuple(sorted(self.components))
        )
        package_inventory = (
            self._read_workload_package_inventory(workload_id, selected_ids)
            if isinstance(workload_id, str) and self.catalog.get("schemaVersion") == 2
            else {"components": {}, "sourceBindings": []}
        )
        rows = []
        host_metadata: dict[str, Any] = {}
        for component_id in selected_ids:
            component = self.components.get(component_id)
            if not isinstance(component, dict):
                continue
            if component_id == WORKLOAD_ECHO_COMPONENT_ID:
                try:
                    echo_receipt = self._read_workload_echo_receipt()
                except UpdateError as error:
                    rows.append(
                        {
                            "componentId": component_id,
                            "installed": False,
                            "version": None,
                            "releaseId": None,
                            "targetId": WORKLOAD_ECHO_TARGET_ID,
                            "manifestDigest": None,
                            "manifestAssetDigest": None,
                            "digest": None,
                            "installationId": None,
                            "verification": {"identityAttested": False},
                            "blockers": [{"code": error.code, "message": str(error)[:500]}],
                        }
                    )
                    host_metadata["echo"] = self._workload_echo_host_metadata(
                        None, package_inventory, unavailable_reason=error.code
                    )
                    continue
                if isinstance(echo_receipt, dict):
                    rows.append(
                        {
                            "componentId": component_id,
                            "installed": True,
                            "version": echo_receipt["version"],
                            "releaseId": echo_receipt["releaseId"],
                            "targetId": echo_receipt["targetId"],
                            "manifestDigest": echo_receipt["manifestDigest"],
                            "manifestAssetDigest": echo_receipt["manifestAssetDigest"],
                            "digest": echo_receipt["digest"],
                            "installationId": None,
                            "verification": echo_receipt["verification"],
                        }
                    )
                else:
                    rows.append(
                        {
                            "componentId": component_id,
                            "installed": False,
                            "version": None,
                            "releaseId": None,
                            "targetId": WORKLOAD_ECHO_TARGET_ID,
                            "manifestDigest": None,
                            "manifestAssetDigest": None,
                            "digest": None,
                            "installationId": None,
                            "verification": {"identityAttested": False},
                        }
                    )
                host_metadata["echo"] = self._workload_echo_host_metadata(
                    echo_receipt, package_inventory
                )
                continue
            if component.get("kind") == "plugin-package":
                identity = package_inventory.get("components", {}).get(component_id)
                hint = self._read_workload_package_runtime_receipt(component_id)
                if isinstance(identity, dict) and identity.get("installed") is True:
                    rows.append(
                        {
                            "componentId": component_id,
                            "installed": True,
                            "version": identity.get("version"),
                            "releaseId": identity.get("releaseId"),
                            "targetId": identity.get("targetId"),
                            "manifestDigest": identity.get("manifestDigest"),
                            "manifestAssetDigest": identity.get("manifestAssetDigest"),
                            "digest": identity.get("digest"),
                            "installationId": identity.get("installationId"),
                            "verification": {
                                "identityAttested": (
                                    isinstance(identity.get("verification"), dict)
                                    and identity["verification"].get("identityAttested") is True
                                )
                            },
                        }
                    )
                    continue
                rows.append(
                    {
                        "componentId": component_id,
                        "installed": False,
                        "version": None,
                        "releaseId": None,
                        "targetId": None,
                        "manifestDigest": None,
                        "manifestAssetDigest": None,
                        "digest": None,
                        "installationId": None,
                        "verification": {"identityAttested": False},
                        **(
                            {
                                "blockers": [
                                    {
                                        "code": "PACKAGE_RUNTIME_READBACK_REQUIRED",
                                        "message": "A local package hint is not confirmed by authenticated Package Runtime UDS readback.",
                                    }
                                ]
                            }
                            if hint is not None
                            else {}
                        ),
                    }
                )
                continue
            if component_id == WORKLOAD_SDK_COMPONENT_ID:
                try:
                    sdk = self._load_workload_sdk_environment()
                    reader = getattr(sdk, "read_workload_sdk_environment", None)
                    identity = reader() if callable(reader) else None
                except (ImportError, OSError, RuntimeError, ValueError) as error:
                    rows.append(
                        {
                            "componentId": component_id,
                            "installed": False,
                            "version": None,
                            "releaseId": None,
                            "targetId": None,
                            "manifestDigest": None,
                            "manifestAssetDigest": None,
                            "digest": None,
                            "installationId": None,
                            "verification": {"identityAttested": False},
                            "blockers": [
                                {
                                    "code": "WORKLOAD_SDK_READBACK_REQUIRED",
                                    "message": str(error)[:500],
                                }
                            ],
                        }
                    )
                    continue
                if isinstance(identity, dict) and identity.get("installed") is True:
                    rows.append(
                        {
                            "componentId": component_id,
                            "installed": True,
                            "version": identity.get("version"),
                            "releaseId": identity.get("releaseId"),
                            "targetId": identity.get("targetId"),
                            "manifestDigest": identity.get("manifestDigest"),
                            "manifestAssetDigest": identity.get("manifestAssetDigest"),
                            "digest": identity.get("digest"),
                            "installationId": None,
                            "verification": identity.get(
                                "verification", {"identityAttested": False}
                            ),
                        }
                    )
                    continue
            try:
                installed = (
                    self._installed_static_web(component)
                    if component.get("kind") == "static-web"
                    else self._installed(component)
                )
            except UpdateError as error:
                rows.append(
                    {
                        "componentId": component_id,
                        "installed": False,
                        "version": None,
                        "releaseId": None,
                        "targetId": None,
                        "manifestDigest": None,
                        "manifestAssetDigest": None,
                        "digest": None,
                        "installationId": None,
                        "verification": {"identityAttested": False},
                        "blockers": [{"code": error.code, "message": str(error)[:500]}],
                    }
                )
                continue
            receipt = (
                self._read_active_receipt(component_id) if installed.get("active") is True else None
            )
            rows.append(
                {
                    "componentId": component_id,
                    "installed": installed.get("active") is True,
                    "version": (
                        receipt.get("version")
                        if isinstance(receipt, dict)
                        else installed.get("activeVersion")
                    ),
                    "releaseId": receipt.get("releaseId") if isinstance(receipt, dict) else None,
                    "targetId": receipt.get("targetId") if isinstance(receipt, dict) else None,
                    "manifestDigest": (
                        receipt.get("manifestDigest")
                        if isinstance(receipt, dict)
                        else installed.get("manifestDigest")
                    ),
                    "manifestAssetDigest": (
                        receipt.get("manifestAssetDigest") if isinstance(receipt, dict) else None
                    ),
                    "digest": installed.get("artifactDigest"),
                    "installationId": None,
                    "verification": {
                        "identityAttested": (
                            receipt.get("schemaVersion") == 2
                            if isinstance(receipt, dict)
                            else installed.get("identityAttested") is True
                        ),
                    },
                }
            )
        if (
            workload_id is not None
            and self.catalog.get("schemaVersion") == 2
            and "cyrene-client-workspace-web" in selected_ids
        ):
            try:
                receipt = self._read_active_receipt("cyrene-client-workspace-web")
                expected_source_receipt = None
                if isinstance(receipt, dict) and _valid_digest(receipt.get("manifestDigest")):
                    installed_dir = self._installed_component_directory(
                        "cyrene-client-workspace-web"
                    )
                    if installed_dir is not None:
                        release_receipt_path = (
                            installed_dir
                            / "releases"
                            / f"{receipt['manifestDigest'].removeprefix('sha256:')}.json"
                        )
                        expected_source_receipt = {
                            "componentId": "cyrene-client-workspace-web",
                            "releaseIdentity": receipt.get("releaseIdentity"),
                            "sourceReceiptDigest": _file_digest(release_receipt_path),
                        }
                web_host = self._load_workload_web_host()
                host_metadata["web"] = web_host.read_web_host_status(
                    expected_source_receipt=expected_source_receipt,
                    runner=self._workload_web_host_runner,
                )
            except (ImportError, OSError, RuntimeError, ValueError) as error:
                host_metadata["web"] = {
                    "schemaVersion": 1,
                    "componentId": "cyrene-client-workspace-web",
                    "installed": False,
                    "available": False,
                    "clientUrl": "http://127.0.0.1:8100/",
                    "serviceUnit": "cyrene-workspace-web.service",
                    "blockers": [
                        {"code": "WORKLOAD_WEB_HOST_READBACK_REQUIRED", "message": str(error)[:500]}
                    ],
                }
        return {
            "status": "ready",
            "workloadId": workload_id,
            "targetId": WORKLOAD_HOST_TARGET,
            "catalogGeneration": self.catalog_generation,
            "catalogDigest": self.catalog_digest,
            "components": rows,
            "sourceBindings": package_inventory.get("sourceBindings", []),
            **({"hostMetadata": host_metadata} if host_metadata else {}),
        }

    def _workload_echo_host_metadata(
        self,
        receipt: dict[str, Any] | None,
        package_inventory: dict[str, Any],
        *,
        unavailable_reason: str | None = None,
    ) -> dict[str, Any]:
        """Read a redacted Echo container receipt and loopback liveness probe."""

        metadata: dict[str, Any] = {
            "schemaVersion": 1,
            "componentId": WORKLOAD_ECHO_COMPONENT_ID,
            "installed": isinstance(receipt, dict),
            "available": False,
            "clientUrl": WORKLOAD_ECHO_API_URL,
            "healthPath": WORKLOAD_ECHO_HEALTH_PATH,
            "version": receipt.get("version") if isinstance(receipt, dict) else None,
            "releaseId": receipt.get("releaseId") if isinstance(receipt, dict) else None,
            "targetId": receipt.get("targetId") if isinstance(receipt, dict) else None,
            "manifestDigest": receipt.get("manifestDigest") if isinstance(receipt, dict) else None,
            "manifestAssetDigest": (
                receipt.get("manifestAssetDigest") if isinstance(receipt, dict) else None
            ),
            "digest": receipt.get("digest") if isinstance(receipt, dict) else None,
            "imageReference": receipt.get("imageReference") if isinstance(receipt, dict) else None,
            "imageDigest": receipt.get("imageDigest") if isinstance(receipt, dict) else None,
            "containerName": None,
            "containerId": None,
            "state": "not-installed",
            "hostUid": None,
            "hostGid": None,
            "activitySourceId": WORKLOAD_ECHO_SOURCE_ID,
            "activityCatalogGeneration": None,
            "dataDirectory": "/var/lib/cyrene/echo",
            "artifactDirectory": "/var/lib/cyrene/echo/artifacts",
            "verification": (
                receipt.get("verification", {"identityAttested": False})
                if isinstance(receipt, dict)
                else {"identityAttested": False}
            ),
            "probes": {"healthz": {"status": None}},
        }
        if unavailable_reason is not None:
            metadata["blockers"] = [
                {
                    "code": "WORKLOAD_OCI_READBACK_REQUIRED",
                    "message": f"Echo runtime receipt is unavailable ({unavailable_reason}).",
                }
            ]
            return metadata
        if receipt is None:
            return metadata

        prior_container = receipt["containerReceipt"]
        metadata.update(
            {
                "containerName": prior_container.get("containerName"),
                "containerId": prior_container.get("containerId"),
                "state": prior_container.get("state"),
                "hostUid": prior_container.get("hostUid"),
                "hostGid": prior_container.get("hostGid"),
                "activityCatalogGeneration": prior_container.get("activityCatalogGeneration"),
            }
        )
        try:
            activity_catalog, source, principal = self._workload_echo_source_identity()
            token = self._read_workload_echo_api_token()
            if token is None:
                raise UpdateError(
                    "WORKLOAD_ECHO_TOKEN_READBACK_REQUIRED",
                    "The protected Echo API bearer is unavailable.",
                )
            prior_runner = receipt.get("runnerIdentity")
            if isinstance(prior_runner, dict):
                connection_ref, runner_identity = self._workload_echo_runner_identity(
                    package_inventory, prior_identity=prior_runner
                )
                if connection_ref is None:
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        "Echo's installed Exact Match connection reference is unavailable.",
                        retryable=True,
                    )
            else:
                # The installed container may predate an optional plugin. Keep
                # its original no-runner environment stable until explicitly
                # reinstalled with a selected Package Runtime binding.
                connection_ref, runner_identity = None, None
            if runner_identity != prior_runner:
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "The active Echo plugin identity differs from the container receipt.",
                    retryable=True,
                )
            spec = self._workload_echo_container_spec(
                {
                    "componentId": receipt["componentId"],
                    "artifactKind": "oci-image",
                    "digest": receipt["digest"],
                    "manifestDigest": receipt["manifestDigest"],
                    "targetId": receipt["targetId"],
                },
                activity_catalog,
                source,
                principal,
                api_token=token[0],
                connection_ref=connection_ref,
                activity_generation=activity_catalog.get("generation"),
            )
            helper = self._load_workload_oci_host()
            observation = helper.container_status(spec, runner=self._workload_oci_runner)
            if observation.state == "not-installed":
                raise UpdateError(
                    "WORKLOAD_OCI_READBACK_REQUIRED",
                    "The Echo container receipt has no matching local container.",
                    retryable=True,
                )
            health_status = (
                self._workload_echo_health_status() if observation.state == "running" else None
            )
            metadata.update(observation.to_receipt_fields())
            metadata["available"] = observation.state == "running" and health_status == 200
            metadata["probes"] = {"healthz": {"status": health_status}}
            if not metadata["available"]:
                metadata["blockers"] = [
                    {
                        "code": "WORKLOAD_ECHO_NOT_READY",
                        "message": "Echo is installed but its container or loopback health probe is not ready.",
                    }
                ]
        except UpdateError as error:
            metadata["blockers"] = [{"code": error.code, "message": str(error)[:500]}]
        except (
            ImportError,
            OSError,
            RuntimeError,
            TypeError,
            ValueError,
            KeyError,
            subprocess.SubprocessError,
        ):
            metadata["blockers"] = [
                {
                    "code": "WORKLOAD_OCI_READBACK_REQUIRED",
                    "message": "The installed Echo container could not be authenticated and read back.",
                }
            ]
        return metadata

    def _workload_plan_directory(self) -> Path:
        root = self._private_state_directory("plans") / "workloads"
        try:
            root.mkdir(mode=0o700, exist_ok=True)
        except OSError as error:
            raise UpdateError(
                "UNSAFE_STATE", "Cannot create workload plan state directory."
            ) from error
        _verify_private_directory(root)
        return root

    def _require_workload_target(self, workload_id: Any, target_id: Any) -> tuple[str, str]:
        if not isinstance(workload_id, str) or workload_id not in WORKLOAD_IDS:
            raise UpdateError(
                "INVALID_WORKLOAD_ID", "workloadId must be catalyst, echo, or plugins."
            )
        if target_id != WORKLOAD_HOST_TARGET:
            raise UpdateError(
                "UNSUPPORTED_TARGET",
                "Only the catalog-pinned Ubuntu 24.04 x86_64 host target is supported.",
            )
        try:
            host = platform.freedesktop_os_release()
        except OSError as error:
            raise UpdateError("UNSUPPORTED_TARGET", "Cannot identify this Linux host.") from error
        if (
            not sys.platform.startswith("linux")
            or host.get("ID") != "ubuntu"
            or host.get("VERSION_ID") != "24.04"
            or platform.machine().lower() not in {"x86_64", "amd64"}
        ):
            raise UpdateError(
                "UNSUPPORTED_TARGET", "Workload installation requires Ubuntu 24.04 x86_64."
            )
        if self.catalog.get("schemaVersion") != 2:
            raise UpdateError(
                "WORKLOAD_CATALOG_UNAVAILABLE",
                "The active trusted catalog does not define workload plans.",
            )
        return workload_id, target_id

    def _workload_target_preference(self, workload_id: str, component_id: str) -> str | None:
        rows = [
            row
            for workload in self.catalog.get("workloads", [])
            if isinstance(workload, dict) and workload.get("workloadId") == workload_id
            for row in workload.get("targetPreferences", [])
            if isinstance(row, dict) and row.get("componentId") == component_id
        ]
        if len(rows) > 1:
            raise UpdateError(
                "INVALID_CATALOG", f"Workload target preference is ambiguous for {component_id}."
            )
        return rows[0].get("targetId") if rows else None

    def _installed_workload_components(
        self, component_ids: tuple[str, ...], *, workload_id: str | None = None
    ) -> tuple[dict[str, dict[str, Any]], dict[str, Any]]:
        installed: dict[str, dict[str, Any]] = {}
        has_plugin_rows = any(
            isinstance(self.components.get(component_id), dict)
            and isinstance(self.components[component_id].get("pluginPackage"), dict)
            for component_id in component_ids
        )
        package_inventory = (
            self._read_workload_package_inventory(workload_id, component_ids)
            if workload_id is not None and has_plugin_rows
            else {"components": {}, "installationRecords": {}, "sourceBindings": []}
        )
        package_identities = package_inventory.get("components", {})
        for component_id in component_ids:
            component = self.components.get(component_id)
            if not isinstance(component, dict):
                continue
            if component_id == WORKLOAD_ECHO_COMPONENT_ID:
                receipt = self._read_workload_echo_receipt()
                if isinstance(receipt, dict):
                    installed[component_id] = {
                        "installed": True,
                        "version": receipt["version"],
                        "releaseId": receipt["releaseId"],
                        "manifestUri": receipt["manifestUri"],
                        "manifestDigest": receipt["manifestDigest"],
                        "manifestAssetDigest": receipt["manifestAssetDigest"],
                        "digest": receipt["digest"],
                        "targetId": receipt["targetId"],
                        "installationId": None,
                        "releaseIdentity": receipt["releaseId"],
                        "imageDigest": receipt["imageDigest"],
                        "imageReference": receipt["imageReference"],
                        "imageIdentity": receipt["containerReceipt"],
                        "containerReceipt": receipt["containerReceipt"],
                        "indexIdentity": receipt["indexIdentity"],
                        "publisherIdentity": receipt["publisherIdentity"],
                        "attestationRef": receipt["attestationRef"],
                        "verification": receipt["verification"],
                    }
                continue
            if isinstance(component.get("pluginPackage"), dict):
                package_identity = package_identities.get(component_id)
                if isinstance(package_identity, dict):
                    installed[component_id] = package_identity
                continue
            if component_id == WORKLOAD_SDK_COMPONENT_ID:
                try:
                    sdk = self._load_workload_sdk_environment()
                    reader = getattr(sdk, "read_workload_sdk_environment", None)
                    if callable(reader):
                        sdk_identity = reader()
                        if isinstance(sdk_identity, dict) and sdk_identity.get("installed") is True:
                            installed[component_id] = sdk_identity
                except Exception as error:
                    raise UpdateError(
                        "WORKLOAD_SDK_READBACK_REQUIRED",
                        "The installed operator SDK identity cannot be read safely.",
                        retryable=True,
                    ) from error
                continue
            if component.get("kind") == "static-web":
                observed = self._installed_static_web(component)
            else:
                observed = self._installed(component)
            if observed.get("active") is True:
                manifest = observed.get("manifest")
                receipt = self._read_active_receipt(component_id)
                if receipt is None and _valid_digest(observed.get("manifestDigest")):
                    receipt = self._read_release_receipt(component_id, observed["manifestDigest"])
                identity: dict[str, Any] = {
                    "installed": True,
                    "version": observed.get("activeVersion"),
                    "digest": observed.get("artifactDigest"),
                }
                if isinstance(receipt, dict) and receipt.get("schemaVersion") == 2:
                    identity.update(
                        {
                            "releaseId": receipt.get("releaseId"),
                            "manifestUri": receipt.get("manifestUri"),
                            "manifestDigest": receipt.get("manifestDigest"),
                            "manifestAssetDigest": receipt.get("manifestAssetDigest"),
                            "digest": receipt.get("artifactDigest"),
                            "targetId": receipt.get("targetId"),
                            "releaseIdentity": receipt.get("releaseIdentity"),
                            "releasePath": receipt.get("releasePath"),
                            "archivePath": receipt.get("archivePath"),
                            "pointerIdentity": receipt.get("pointerIdentity"),
                            "bundleIdentity": receipt.get("bundleIdentity"),
                            "indexIdentity": receipt.get("indexIdentity"),
                            "attestationRef": receipt.get("attestationRef"),
                        }
                    )
                elif isinstance(manifest, dict):
                    # V1 receipts remain useful for install idempotency, but lack the
                    # raw release-byte hash required by the strict uninstall resolver.
                    identity.update(
                        {
                            "manifestDigest": observed.get("manifestDigest"),
                            "releaseIdentity": observed.get("releaseIdentity"),
                            "releasePath": observed.get("releasePath"),
                            "pointerIdentity": observed.get("pointerIdentity"),
                            "bundleIdentity": observed.get("bundleIdentity"),
                        }
                    )
                    if isinstance(manifest.get("releaseId"), str):
                        identity["releaseId"] = manifest["releaseId"]
                    if isinstance(manifest.get("manifestUri"), str):
                        identity["manifestUri"] = manifest["manifestUri"]
                installed[component_id] = identity
        return installed, package_inventory

    def _installed_static_web(self, component: dict[str, Any]) -> dict[str, Any]:
        """Read the static-web current pointer and its matching immutable receipt."""

        component_id = component.get("componentId")
        root = DEFAULT_WORKLOAD_WEB_ROOT / str(component_id)
        active = root / "current"
        if not active.exists() and not active.is_symlink():
            if self._read_active_receipt(str(component_id)) is not None:
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE",
                    f"Static-web identity receipt exists without an active {component_id} tree.",
                )
            return self._empty_installed()
        info = active.lstat()
        if not stat.S_ISLNK(info.st_mode) or info.st_uid != 0:
            raise UpdateError("INVALID_INSTALLED_RELEASE", "Static-web current pointer is unsafe.")
        target = os.readlink(active)
        match = re.fullmatch(r"releases/([A-Za-z0-9][A-Za-z0-9._-]{0,511})", target)
        if match is None:
            raise UpdateError("INVALID_INSTALLED_RELEASE", "Static-web current target is unsafe.")
        release_identity = match.group(1)
        release_root = root / "releases" / release_identity
        if release_root.is_symlink() or not release_root.is_dir():
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE", "Static-web active release is unavailable."
            )
        receipt = self._read_active_receipt(str(component_id))
        if receipt is None or receipt.get("schemaVersion") != 2:
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                "Static-web active release has no complete raw-manifest receipt.",
            )
        manifest = receipt.get("manifest")
        artifact = manifest.get("artifact") if isinstance(manifest, dict) else None
        if (
            receipt.get("pointerIdentity") != release_identity
            or Path(str(receipt.get("releasePath"))) != release_root
            or not isinstance(artifact, dict)
            or artifact.get("kind") != "static-web"
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE", "Static-web receipt identity differs from its pointer."
            )
        self._verify_static_web_tree(release_root, artifact.get("files"))
        return {
            "activeVersion": receipt["version"],
            "manifest": manifest,
            "active": True,
            "identityAttested": True,
            "releaseIdentity": receipt["releaseIdentity"],
            "manifestDigest": receipt["manifestDigest"],
            "artifactDigest": receipt["artifactDigest"],
            "pointerIdentity": release_identity,
            "bundleIdentity": None,
            "releasePath": str(release_root),
        }

    def _read_workload_package_runtime_receipt(self, component_id: str) -> dict[str, Any] | None:
        """Read a package receipt only as a hint until UDS readback authenticates it."""

        directory = self._installed_component_directory(component_id)
        if directory is None:
            return None
        path = directory / "package-runtime.json"
        if not path.exists() and not path.is_symlink():
            return None
        receipt = _read_object(path, f"{component_id} Package Runtime installation receipt")
        if (
            receipt.get("schemaVersion") != 1
            or receipt.get("componentId") != component_id
            or receipt.get("installed") is not True
            or not isinstance(receipt.get("packageId"), str)
            or not isinstance(receipt.get("installationId"), str)
            or ACTIVITY_INSTALLATION_ID_PATTERN.fullmatch(receipt["installationId"]) is None
            or not isinstance(receipt.get("installation"), dict)
            or not isinstance(receipt.get("releaseId"), str)
            or not isinstance(receipt.get("targetId"), str)
            or not _valid_digest(receipt.get("digest"))
            or not _valid_digest(receipt.get("manifestDigest"))
            or not _valid_digest(receipt.get("manifestAssetDigest"))
            or not _valid_digest(receipt.get("packageArtifactDigest"))
            or not _valid_digest(receipt.get("archiveDigest"))
            or not _valid_digest(receipt.get("descriptorDigest"))
            or not _valid_digest(receipt.get("dependencyLockDigest"))
            or not isinstance(receipt.get("indexIdentity"), dict)
            or not isinstance(receipt.get("publisherIdentity"), dict)
            or not isinstance(receipt.get("attestationRef"), dict)
            or receipt.get("verification") != {"identityAttested": True}
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Package Runtime installation receipt is malformed for {component_id}.",
            )
        installation = receipt["installation"]
        verification = installation.get("verification")
        if (
            installation.get("installation_id") != receipt["installationId"]
            or installation.get("package_id") != receipt["packageId"]
            or installation.get("package_version") != receipt.get("version")
            or installation.get("archive_digest") != receipt.get("digest")
            or installation.get("artifact_digest") != receipt.get("packageArtifactDigest")
            or not isinstance(verification, dict)
            or verification.get("archive_digest") != receipt.get("archiveDigest")
            or verification.get("artifact_digest") != receipt.get("packageArtifactDigest")
            or verification.get("descriptor_digest") != receipt.get("descriptorDigest")
            or verification.get("manifest_digest") != receipt.get("manifestDigest")
            or verification.get("dependency_lock_digest") != receipt.get("dependencyLockDigest")
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Package Runtime installation hint differs from its stored receipt for {component_id}.",
            )
        return {
            key: receipt[key]
            for key in (
                "componentId",
                "installed",
                "version",
                "releaseId",
                "manifestUri",
                "targetId",
                "manifestDigest",
                "manifestAssetDigest",
                "digest",
                "indexIdentity",
                "publisherIdentity",
                "attestationRef",
                "packageId",
                "installationId",
                "packageArtifactDigest",
                "archiveDigest",
                "descriptorDigest",
                "dependencyLockDigest",
                "installation",
                "verification",
            )
            if key in receipt
        }

    def _load_workload_package_runtime(self) -> Any:
        """Load the adjacent Platform package owner helper from the installed bundle."""

        module_path = Path(__file__).with_name("workload_package_runtime.py")
        if module_path.is_symlink() or not module_path.is_file():
            raise UpdateError(
                "PACKAGE_RUNTIME_UNAVAILABLE", "The workload Package Runtime helper is missing."
            )
        module_name = "_cyrene_workload_package_runtime"
        existing = sys.modules.get(module_name)
        if existing is not None:
            return existing
        spec = importlib.util.spec_from_file_location(module_name, module_path)
        if spec is None or spec.loader is None:
            raise UpdateError(
                "PACKAGE_RUNTIME_UNAVAILABLE", "The workload Package Runtime helper cannot load."
            )
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        try:
            spec.loader.exec_module(module)
        except Exception as error:
            sys.modules.pop(module_name, None)
            raise UpdateError(
                "PACKAGE_RUNTIME_UNAVAILABLE", "The workload Package Runtime helper failed to load."
            ) from error
        required = (
            "candidate_from_workload_rows",
            "install_workload_package",
            "uninstall_workload_package",
            "build_workload_source_update",
            "apply_workload_source_update",
            "run_package_binding_operation",
            "read_workload_package_inventory",
        )
        if any(not callable(getattr(module, name, None)) for name in required):
            raise UpdateError(
                "PACKAGE_RUNTIME_UNAVAILABLE",
                "The workload Package Runtime helper API is incomplete.",
            )
        return module

    def _workload_plugin_owner_rows(
        self, workload_id: str, component_ids: tuple[str, ...]
    ) -> tuple[dict[str, Any] | None, list[dict[str, Any]]]:
        """Build exact package owner rows only from the signed workload declaration."""

        workloads = [
            row
            for row in self.catalog.get("workloads", [])
            if isinstance(row, dict) and row.get("workloadId") == workload_id
        ]
        if len(workloads) != 1:
            raise UpdateError(
                "INVALID_CATALOG", "The selected workload source declaration is ambiguous."
            )
        workload = workloads[0]
        bindings: dict[str, str] = {}
        for row in workload.get("bindings", []):
            if not isinstance(row, dict) or not isinstance(row.get("componentId"), str):
                raise UpdateError(
                    "INVALID_CATALOG", "The selected workload binding map is malformed."
                )
            component_id = row["componentId"]
            binding_id = row.get("bindingId")
            if (
                component_id in bindings
                or not isinstance(binding_id, str)
                or ACTIVITY_SCOPE_ID_PATTERN.fullmatch(binding_id) is None
            ):
                raise UpdateError(
                    "INVALID_CATALOG", "The selected workload binding map is ambiguous."
                )
            bindings[component_id] = binding_id
        policy = workload.get("sourcePolicy")
        rows: list[dict[str, Any]] = []
        for component_id in component_ids:
            component = self.components.get(component_id)
            plugin = component.get("pluginPackage") if isinstance(component, dict) else None
            if not isinstance(plugin, dict):
                continue
            binding_id = bindings.get(component_id)
            package_id = plugin.get("packageId")
            capability_id = plugin.get("capabilityId")
            if (
                not isinstance(binding_id, str)
                or not isinstance(package_id, str)
                or not isinstance(capability_id, str)
                or not isinstance(policy, dict)
            ):
                raise UpdateError(
                    "SOURCE_BINDING_INVALID",
                    f"Catalog does not declare a complete owner binding for {component_id}.",
                )
            rows.append(
                {
                    "componentId": component_id,
                    "artifactKind": "plugin-package",
                    "packageId": package_id,
                    "capabilityId": capability_id,
                    "bindingId": binding_id,
                    "sourcePolicy": policy,
                }
            )
        return policy if isinstance(policy, dict) else None, rows

    def _workload_source_principals(
        self,
        source_policy: dict[str, Any],
        activity_catalog: dict[str, Any],
    ) -> dict[str, dict[str, Any]]:
        """Resolve owner credentials from the trusted catalog and fixed token directory."""

        principals: dict[str, dict[str, Any]] = {}
        for source in activity_catalog.get("sources", []):
            if not isinstance(source, dict):
                raise UpdateError("GATE_UNKNOWN", "Activity source inventory is malformed.")
            source_id = source.get("source_id")
            if not isinstance(source_id, str):
                raise UpdateError("GATE_UNKNOWN", "Activity source ID is malformed.")
            principals[source_id] = {
                "uid": source["uid"],
                "gid": source["gid"],
                "tokenPath": DEFAULT_ACTIVITY_TOKEN_DIRECTORY / f"{source_id}.token",
            }
        declared_sources: list[str] = []
        if source_policy.get("mode") == "standaloneOperator":
            source_id = source_policy.get("sourceId")
            if isinstance(source_id, str):
                declared_sources.append(source_id)
        elif source_policy.get("mode") == "actualProduct":
            mappings = source_policy.get("productSources")
            if isinstance(mappings, list):
                declared_sources.extend(
                    row["sourceId"]
                    for row in mappings
                    if isinstance(row, dict) and isinstance(row.get("sourceId"), str)
                )
        for source_id in declared_sources:
            if source_id in principals:
                continue
            try:
                user = pwd.getpwnam("cyrene")
                group = grp.getgrnam("cyrene")
            except KeyError as error:
                raise UpdateError(
                    "PACKAGE_RUNTIME_SOURCE_UNAVAILABLE",
                    "The official Cyrene runtime account is unavailable for the selected source.",
                    retryable=True,
                ) from error
            principals[source_id] = {
                "uid": user.pw_uid,
                "gid": group.gr_gid,
                "tokenPath": DEFAULT_ACTIVITY_TOKEN_DIRECTORY / f"{source_id}.token",
            }
        return principals

    def _read_workload_package_inventory(
        self,
        workload_id: str,
        component_ids: tuple[str, ...],
    ) -> dict[str, Any]:
        """Read plugin installs and every live binding through authenticated Package Runtime UDS."""

        source_policy, plugin_rows = self._workload_plugin_owner_rows(workload_id, component_ids)
        if not plugin_rows or source_policy is None:
            return {"components": {}, "installationRecords": {}, "sourceBindings": []}
        hints = {
            row["componentId"]: hint
            for row in plugin_rows
            if (hint := self._read_workload_package_runtime_receipt(row["componentId"])) is not None
        }
        policy_exists = (
            DEFAULT_PACKAGE_RUNTIME_POLICY.exists() or DEFAULT_PACKAGE_RUNTIME_POLICY.is_symlink()
        )
        catalog_exists = (
            self.activity_catalog_path.exists() or self.activity_catalog_path.is_symlink()
        )
        if not policy_exists and not catalog_exists and not hints:
            return {"components": {}, "installationRecords": {}, "sourceBindings": []}
        if not policy_exists:
            if hints:
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "A local Package Runtime hint exists without the authenticated source policy.",
                    retryable=True,
                )
            # No bindings are authorized yet; first installation may register the
            # source under the held parent plan before creating the policy.
            return {"components": {}, "installationRecords": {}, "sourceBindings": []}
        activity_catalog, _source_ids = self._activity_catalog()
        principals = self._workload_source_principals(source_policy, activity_catalog)
        try:
            helper = self._load_workload_package_runtime()
            sdk_environment = self._load_workload_sdk_environment().read_workload_sdk_environment()
            sdk_python = (
                Path(sdk_environment["pythonPath"])
                if isinstance(sdk_environment, dict)
                and sdk_environment.get("installed") is True
                and isinstance(sdk_environment.get("pythonPath"), str)
                else None
            )
            if sdk_python is None or not sdk_python.is_absolute():
                raise UpdateError(
                    "WORKLOAD_SDK_READBACK_REQUIRED",
                    "The installed operator SDK interpreter is not verified.",
                    retryable=True,
                )
            result = helper.read_workload_package_inventory(
                selected_rows=plugin_rows,
                source_principals=principals,
                sdk_python=sdk_python,
                activity_catalog_path=self.activity_catalog_path,
                policy_path=DEFAULT_PACKAGE_RUNTIME_POLICY,
                token_directory=DEFAULT_ACTIVITY_TOKEN_DIRECTORY,
                installation_hints=hints,
            )
        except Exception as error:
            if isinstance(error, UpdateError):
                raise
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Authenticated Package Runtime inventory is unavailable or inconsistent.",
                retryable=True,
            ) from error
        if not isinstance(result, dict) or not isinstance(result.get("components"), dict):
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Package Runtime inventory response is malformed.",
            )
        identities: dict[str, dict[str, Any]] = {}
        for component_id, package_identity in result["components"].items():
            hint = hints.get(component_id)
            if not isinstance(hint, dict) or not isinstance(package_identity, dict):
                continue
            identity = dict(hint)
            identity.update(package_identity)
            identity["releaseId"] = hint["releaseId"]
            identity["manifestAssetDigest"] = hint["manifestAssetDigest"]
            identity["indexIdentity"] = hint["indexIdentity"]
            identity["publisherIdentity"] = hint["publisherIdentity"]
            identity["attestationRef"] = hint["attestationRef"]
            identity["targetId"] = hint["targetId"]
            identity["manifestUri"] = hint.get("manifestUri")
            identity["verification"] = hint["verification"]
            identities[component_id] = identity
        return {
            "components": identities,
            "installationRecords": result.get("installationRecords", {}),
            "sourceBindings": result.get("sourceBindings", []),
            "catalogGeneration": activity_catalog["generation"],
            "sourcePrincipals": principals,
            "sourcePolicy": source_policy,
        }

    def _build_workload_plan(
        self,
        workload_id: str,
        target_id: str,
        selections: Any,
        *,
        action: str = "install",
        channel: Any = None,
    ) -> tuple[dict[str, Any], dict[str, Candidate], dict[str, Any]]:
        selected_channel = self._resolve_channel(channel)
        resolver = self._load_workload_resolver()
        potential_ids = resolver.potential_component_ids(self.catalog, workload_id)
        if not potential_ids:
            resolution = resolver.resolve_workload(
                self.catalog,
                self.catalog_digest,
                workload_id,
                target_id,
                selections,
                {},
                {"indexes": []},
                action=action,
                channel=selected_channel,
            ).to_dict()
            return (
                resolution,
                {},
                {"components": {}, "installationRecords": {}, "sourceBindings": []},
            )
        candidates: dict[str, Candidate] = {}
        candidate_errors: dict[str, UpdateError] = {}
        if action == "install":
            for component_id in potential_ids:
                component = self.components.get(component_id)
                if not isinstance(component, dict):
                    continue
                preferred_target = self._workload_target_preference(workload_id, component_id)
                component_target = self._target_for(component, target_id=preferred_target)
                if component_target is None:
                    continue
                try:
                    candidates[component_id] = self._candidate(
                        component, component_target, selected_channel
                    )
                except UpdateError as error:
                    # The pure resolver emits a scoped blocker only if this release is
                    # required by the chosen workload closure.
                    candidate_errors[component_id] = error
        trusted_indexes = self._trusted_release_indexes(list(candidates.values()))
        installed, package_inventory = self._installed_workload_components(
            potential_ids, workload_id=workload_id
        )
        resolution = resolver.resolve_workload(
            self.catalog,
            self.catalog_digest,
            workload_id,
            target_id,
            selections,
            installed,
            trusted_indexes,
            action=action,
            channel=selected_channel,
        ).to_dict()
        if candidate_errors:
            self._attach_workload_candidate_failures(resolution, candidate_errors)
        return resolution, candidates, package_inventory

    @staticmethod
    def _attach_workload_candidate_failures(
        resolution: dict[str, Any], candidate_errors: dict[str, UpdateError]
    ) -> None:
        """Attach discovery failures only to components already blocked by resolution.

        The resolver owns workload membership and closure. Candidate failures for
        unselected optional components must not create new blockers. Enriched blocker
        details remain part of the plan digest so retries see the same diagnostics.
        中文：只补充解析器已阻断组件的候选错误，不让未选可选组件产生全局阻断。
        """

        blockers = resolution.get("blockers")
        material = resolution.get("planDigestMaterial")
        if not isinstance(blockers, list) or not isinstance(material, dict):
            return

        changed = False
        for blocker in blockers:
            if not isinstance(blocker, dict) or blocker.get("code") not in {
                "MISSING_RELEASE",
                "MISSING_CAPABILITY",
            }:
                continue
            component_id = blocker.get("componentId")
            error = candidate_errors.get(component_id) if isinstance(component_id, str) else None
            if error is None:
                continue
            message = " ".join(str(error).split())[:500]
            details = blocker.get("details")
            updated_details = dict(details) if isinstance(details, dict) else {}
            updated_details["candidateFailure"] = {
                "code": error.code,
                "message": message,
                "retryable": error.retryable,
            }
            blocker["details"] = updated_details
            blocker["retryable"] = error.retryable
            changed = True

        if not changed:
            return
        digest_material = dict(material)
        digest_material["blockers"] = blockers
        digest = (
            "sha256:"
            + hashlib.sha256(
                json.dumps(
                    digest_material,
                    ensure_ascii=False,
                    allow_nan=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
        )
        resolution["blockers"] = blockers
        resolution["planDigestMaterial"] = digest_material
        resolution["planDigest"] = digest
        resolution["planId"] = "plan-" + digest.removeprefix("sha256:")[:32]

    def check_workload(
        self,
        workload_id: Any,
        target_id: Any,
        selections: Any,
        *,
        action: Any = "install",
        channel: Any = None,
    ) -> dict[str, Any]:
        """Resolve the exact catalog workload and persist a digest-bound plan."""

        self._reload_catalog_for_operation()
        self._ensure_state_root()
        if not isinstance(action, str) or action not in {"install", "uninstall"}:
            raise UpdateError("INVALID_ACTION", "Workload action must be install or uninstall.")
        selected_channel = self._resolve_channel(channel)
        if not isinstance(selections, dict):
            raise UpdateError("INVALID_SELECTION", "selections must be a JSON object.")
        if workload_id is None and action == "uninstall":
            include_ids = selections.get("includeComponentIds")
            if (
                not isinstance(include_ids, list)
                or len(include_ids) != 1
                or not isinstance(include_ids[0], str)
            ):
                raise UpdateError(
                    "INVALID_SELECTION",
                    "Uninstall without --workload needs exactly one selected component ID.",
                )
            component_id = include_ids[0]
            owner_ids = sorted(
                workload.get("workloadId")
                for workload in self.catalog.get("workloads", [])
                if isinstance(workload, dict)
                and isinstance(workload.get("workloadId"), str)
                and (
                    component_id in workload.get("requiredComponents", [])
                    or component_id in workload.get("recommendedComponents", [])
                    or component_id in workload.get("optionalComponents", [])
                    or any(
                        isinstance(group, dict) and component_id in group.get("componentIds", [])
                        for group in workload.get("choiceGroups", [])
                    )
                )
            )
            if len(owner_ids) != 1:
                owners = ", ".join(owner_ids) if owner_ids else "none"
                raise UpdateError(
                    "AMBIGUOUS_WORKLOAD_OWNER",
                    f"Component {component_id} has {len(owner_ids)} direct workload owners ({owners}); pass --workload explicitly.",
                )
            workload_id = owner_ids[0]
        workload_id, target_id = self._require_workload_target(workload_id, target_id)
        resolution, candidates, _package_inventory = self._build_workload_plan(
            workload_id, target_id, selections, action=action, channel=selected_channel
        )
        host_blockers: list[dict[str, str]] = []
        selected_rows = resolution.get("selectedComponents", [])
        if resolution.get("status") == "ready" and any(
            isinstance(row, dict) and row.get("artifactKind") == "oci-image"
            for row in selected_rows
        ):
            try:
                self._preflight_workload_oci_runtime()
            except UpdateError as error:
                host_blockers.append({"code": error.code, "message": str(error)[:500]})
        plan_id = resolution.get("planId")
        plan_digest = resolution.get("planDigest")
        if (
            not isinstance(plan_id, str)
            or PLAN_ID_PATTERN.fullmatch(plan_id) is None
            or not _valid_digest(plan_digest)
        ):
            raise UpdateError(
                "INVALID_RESOLUTION", "Workload resolver returned an invalid plan identity."
            )
        if resolution.get("status") == "ready" and not host_blockers:
            selected_ids = {row["componentId"] for row in resolution.get("selectedComponents", [])}
            plan = {
                "schemaVersion": 1,
                "planKind": WORKLOAD_PROTOCOL_VERSION,
                "planId": plan_id,
                "planDigest": plan_digest,
                "catalogGeneration": self.catalog_generation,
                "catalogDigest": self.catalog_digest,
                "channel": selected_channel,
                "workloadId": workload_id,
                "targetId": target_id,
                "action": action,
                "selections": selections,
                "resolution": resolution,
                "candidates": {
                    component_id: {
                        "manifestUri": candidates[component_id].manifest_uri,
                        "manifestDigest": candidates[component_id].manifest_digest,
                        "manifestAssetDigest": candidates[component_id].manifest_asset_digest,
                        "artifactDigest": candidates[component_id].artifact_digest,
                        "releaseTag": candidates[component_id].release_tag,
                        "targetId": next(
                            row["targetId"]
                            for row in resolution["selectedComponents"]
                            if row["componentId"] == component_id
                        ),
                    }
                    for component_id in sorted(selected_ids)
                    if component_id in candidates
                },
                "phase": "checked",
            }
            _atomic_json(self._workload_plan_directory() / f"{plan_id}.json", plan)
        return {
            "status": "blocked" if host_blockers else resolution.get("status"),
            "planId": plan_id,
            "planDigest": plan_digest,
            "catalogDigest": self.catalog_digest,
            "workloadId": workload_id,
            "targetId": target_id,
            "action": action,
            "channel": selected_channel,
            "components": resolution.get("selectedComponents", []),
            "resolution": resolution,
            "warnings": resolution.get("warnings", []),
            "blockers": [*resolution.get("blockers", []), *host_blockers],
        }

    def stage_workload(
        self,
        workload_id: Any,
        target_id: Any,
        plan_id: Any,
        plan_digest: Any,
        *,
        action: Any,
        channel: Any,
    ) -> dict[str, Any]:
        """Re-resolve a checked workload before delegating package materialization."""

        self._require_authorized_process()
        self._clear_release_discovery_caches()
        self._validate_plan_identity(plan_id, plan_digest)
        workload_id, target_id = self._require_workload_target(workload_id, target_id)
        if not isinstance(action, str) or action not in {"install", "uninstall"}:
            raise UpdateError("INVALID_ACTION", "Workload action must be install or uninstall.")
        selected_channel = self._resolve_channel(channel)
        directory = self._workload_plan_directory()
        stored = _read_object(directory / f"{plan_id}.json", "checked workload plan")
        if (
            stored.get("planKind") != WORKLOAD_PROTOCOL_VERSION
            or stored.get("planId") != plan_id
            or stored.get("planDigest") != plan_digest
            or stored.get("workloadId") != workload_id
            or stored.get("targetId") != target_id
            or stored.get("action") != action
            or stored.get("channel") != selected_channel
            or stored.get("catalogDigest") != self.catalog_digest
            or stored.get("catalogGeneration") != self.catalog_generation
            or stored.get("phase") not in {"checked", "staged"}
        ):
            raise UpdateError(
                "PLAN_CHANGED",
                "The checked workload plan is stale or belongs to another workload.",
                retryable=True,
            )
        resolution, candidates, package_inventory = self._build_workload_plan(
            workload_id,
            target_id,
            stored.get("selections"),
            action=action,
            channel=selected_channel,
        )
        if (
            resolution.get("status") != "ready"
            or resolution.get("planDigest") != plan_digest
            or resolution.get("action") != action
            or resolution.get("channel") != selected_channel
        ):
            raise UpdateError(
                "PLAN_CHANGED",
                "Trusted workload releases changed; check again before staging.",
                retryable=True,
            )
        if any(
            isinstance(row, dict) and row.get("artifactKind") == "oci-image"
            for row in resolution.get("selectedComponents", [])
        ):
            self._preflight_workload_oci_runtime()
        if stored.get("phase") == "staged":
            return {
                "status": "staged",
                "planId": plan_id,
                "planDigest": plan_digest,
                "catalogDigest": self.catalog_digest,
                "workloadId": workload_id,
                "targetId": target_id,
                "action": action,
                "channel": selected_channel,
                "components": stored.get("stagedComponents", []),
                "resolution": resolution,
                "warnings": resolution.get("warnings", []),
                "blockers": [],
            }
        stage_parent = self._private_state_directory("staged") / "workload-plans"
        stage_parent.mkdir(mode=0o700, exist_ok=True)
        _verify_private_directory(stage_parent)
        stage_root = stage_parent / plan_id
        if stage_root.exists() or stage_root.is_symlink():
            if stage_root.is_symlink() or not stage_root.is_dir():
                raise UpdateError("UNSAFE_STATE", "Interrupted workload staging path is unsafe.")
            _verify_private_directory(stage_root)
            shutil.rmtree(stage_root)
        stage_root.mkdir(mode=0o700)
        staged = []
        for row in resolution.get("selectedComponents", []):
            component_id = row["componentId"]
            if action == "uninstall":
                staged.append(
                    {
                        "componentId": component_id,
                        "status": "planned-for-uninstall",
                        "artifactKind": row["artifactKind"],
                        "version": row["version"],
                        "digest": row["digest"],
                        "manifestDigest": row["manifestDigest"],
                        "manifestAssetDigest": row["manifestAssetDigest"],
                        "releaseId": row["releaseId"],
                        "targetId": row["targetId"],
                        "indexIdentity": row.get("indexIdentity"),
                        "publisherIdentity": row.get("publisherIdentity"),
                        "attestationRef": row.get("attestationRef"),
                        "bindingId": row.get("bindingId"),
                        "packageId": row.get("packageId"),
                        "installationId": row["installationId"],
                        "installedIdentity": row["installedIdentity"],
                    }
                )
                continue
            if row.get("installed") is True:
                staged.append(
                    {
                        "componentId": component_id,
                        "status": "current",
                        "artifactKind": row["artifactKind"],
                        "version": row["version"],
                        "digest": row["digest"],
                        "manifestDigest": row["manifestDigest"],
                        "manifestAssetDigest": row["manifestAssetDigest"],
                        "releaseId": row["releaseId"],
                        "targetId": row["targetId"],
                        "indexIdentity": row.get("indexIdentity"),
                        "publisherIdentity": row.get("publisherIdentity"),
                        "attestationRef": row.get("attestationRef"),
                        "bindingId": row.get("bindingId"),
                        "packageId": row.get("packageId"),
                        "capabilityId": row.get("capabilityId"),
                        "sourcePolicy": row.get("sourcePolicy"),
                        "installationId": row["installationId"],
                        "installedIdentity": row["installedIdentity"],
                        **(
                            {
                                field: package_inventory["components"][component_id][field]
                                for field in (
                                    "packageArtifactDigest",
                                    "archiveDigest",
                                    "descriptorDigest",
                                    "dependencyLockDigest",
                                )
                                if isinstance(package_inventory.get("components"), dict)
                                and isinstance(
                                    package_inventory["components"].get(component_id), dict
                                )
                                and field in package_inventory["components"][component_id]
                            }
                            if row.get("artifactKind") == "plugin-package"
                            else {}
                        ),
                    }
                )
                continue
            candidate = candidates.get(component_id)
            if candidate is None:
                raise UpdateError(
                    "PLAN_CHANGED", f"Candidate disappeared for {component_id}.", retryable=True
                )
            staged.append(
                self._stage_workload_candidate(
                    candidate,
                    stage_root,
                    plan_id,
                    plan_digest,
                    resolution_component=row,
                )
            )
        stored["phase"] = "staged"
        stored["stagedComponents"] = staged
        _atomic_json(directory / f"{plan_id}.json", stored)
        return {
            "status": "staged",
            "planId": plan_id,
            "planDigest": plan_digest,
            "catalogDigest": self.catalog_digest,
            "workloadId": workload_id,
            "targetId": target_id,
            "action": action,
            "channel": selected_channel,
            "components": staged,
            "resolution": resolution,
            "warnings": resolution.get("warnings", []),
            "blockers": [],
        }

    def _stage_workload_candidate(
        self,
        candidate: Candidate,
        stage_root: Path,
        plan_id: str,
        plan_digest: str,
        *,
        resolution_component: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Verify every release asset and stage one product, web, or Plugin candidate."""

        artifact = candidate.manifest["artifact"]
        kind = artifact["kind"]
        if kind == "plugin-package":
            return self._stage_workload_plugin_package(
                candidate,
                stage_root,
                plan_id,
                plan_digest,
                resolution_component=resolution_component,
            )
        if candidate.component.get("componentId") == WORKLOAD_SDK_COMPONENT_ID:
            return self._stage_workload_sdk(
                candidate, stage_root, plan_id, plan_digest, resolution_component
            )
        if kind == "static-web":
            return self._stage_workload_static_web(
                candidate,
                stage_root,
                plan_id,
                plan_digest,
                resolution_component=resolution_component,
            )
        if kind == "oci-image":
            return self._stage_workload_oci_image(
                candidate,
                plan_id,
                plan_digest,
                resolution_component=resolution_component,
            )
        component = self._stage_candidate(
            candidate,
            stage_root,
            plan_id,
            plan_digest,
            workload_identity=resolution_component,
        )
        return {
            "componentId": component["componentId"],
            "status": "staged",
            "artifactKind": kind,
            "version": component["version"],
            "digest": component["artifactDigest"],
            "manifestDigest": component["manifestDigest"],
            "manifestAssetDigest": candidate.manifest_asset_digest,
            "releaseId": (
                resolution_component.get("releaseId")
                if isinstance(resolution_component, dict)
                else candidate.manifest.get("releaseId")
            ),
            "targetId": (
                resolution_component.get("targetId")
                if isinstance(resolution_component, dict)
                else None
            ),
            "indexIdentity": (
                resolution_component.get("indexIdentity")
                if isinstance(resolution_component, dict)
                else None
            ),
            "publisherIdentity": (
                resolution_component.get("publisherIdentity")
                if isinstance(resolution_component, dict)
                else None
            ),
            "attestationRef": (
                resolution_component.get("attestationRef")
                if isinstance(resolution_component, dict)
                else None
            ),
            "stagedIdentity": {
                "releasePath": component["releasePath"],
                "archivePath": component["archivePath"],
                "pointerIdentity": component["pointerIdentity"],
                "bundleIdentity": component["bundleIdentity"],
            },
        }

    def _stage_workload_oci_image(
        self,
        candidate: Candidate,
        plan_id: str,
        plan_digest: str,
        *,
        resolution_component: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Verify the signed Echo image subject and stage its immutable reference.

        OCI images have no release-asset archive to download. The signed release
        index binds the manifest, while GitHub's artifact verifier checks the exact
        registry repository and image digest before the plan can be applied.
        中文：OCI 镜像没有可下载归档；本阶段验证发布索引、manifest 与镜像 attestation。
        """

        if (
            candidate.component.get("componentId") != WORKLOAD_ECHO_COMPONENT_ID
            or candidate.manifest.get("target")
            != self.targets.get(WORKLOAD_ECHO_TARGET_ID, {}).get("target")
            or not isinstance(resolution_component, dict)
            or resolution_component.get("componentId") != WORKLOAD_ECHO_COMPONENT_ID
            or resolution_component.get("targetId") != WORKLOAD_ECHO_TARGET_ID
        ):
            raise UpdateError(
                "UNSUPPORTED_TARGET",
                "The OCI lifecycle adapter is restricted to Echo on Ubuntu 24.04.",
            )
        artifact = candidate.manifest.get("artifact")
        if (
            not isinstance(artifact, dict)
            or artifact.get("kind") != "oci-image"
            or artifact.get("repository") != "ghcr.io/dohorizon-ai/cyrene-echo"
            or artifact.get("digest") != candidate.artifact_digest
            or artifact.get("platform") != {"os": "linux", "architecture": "amd64"}
            or not _valid_digest(candidate.artifact_digest)
        ):
            raise UpdateError(
                "INVALID_MANIFEST", "Echo OCI image identity is not the trusted release tuple."
            )
        self._verify_workload_oci_attestation(candidate)
        identity = self._workload_receipt_fields(candidate, resolution_component)
        return {
            "componentId": WORKLOAD_ECHO_COMPONENT_ID,
            "status": "staged",
            "artifactKind": "oci-image",
            "version": candidate.manifest["version"],
            "digest": candidate.artifact_digest,
            "manifestDigest": candidate.manifest_digest,
            "manifestAssetDigest": candidate.manifest_asset_digest,
            "releaseId": identity["releaseId"],
            "targetId": identity["targetId"],
            "indexIdentity": identity["indexIdentity"],
            "publisherIdentity": identity["publisherIdentity"],
            "attestationRef": identity["attestationRef"],
            "artifactAttestationVerified": True,
            "stagedIdentity": {
                "planId": plan_id,
                "planDigest": plan_digest,
                "imageReference": f"{artifact['repository']}@{artifact['digest']}",
                "imageDigest": artifact["digest"],
            },
        }

    def _verify_workload_oci_attestation(self, candidate: Candidate) -> None:
        """Verify the exact OCI subject with the trusted publisher workflow."""

        artifact = candidate.manifest.get("artifact")
        publisher = self._publisher_for_component(candidate.component)
        source = candidate.manifest.get("source")
        if (
            candidate.component.get("componentId") != WORKLOAD_ECHO_COMPONENT_ID
            or not isinstance(artifact, dict)
            or artifact.get("kind") != "oci-image"
            or not isinstance(publisher, dict)
            or not isinstance(source, dict)
            or not isinstance(source.get("ref"), str)
            or not isinstance(source.get("commit"), str)
            or not _valid_digest(artifact.get("digest"))
            or artifact.get("repository") != "ghcr.io/dohorizon-ai/cyrene-echo"
        ):
            raise UpdateError("INVALID_ATTESTATION", "Echo OCI attestation identity is incomplete.")
        gh = shutil.which("gh")
        if gh is None:
            raise UpdateError(
                "ATTESTATION_VERIFIER_MISSING",
                "GitHub CLI (`gh`) is required to verify Echo's OCI provenance.",
            )
        subject_uri = f"oci://{artifact['repository']}@{artifact['digest']}"
        arguments = [
            gh,
            "attestation",
            "verify",
            subject_uri,
            "--repo",
            publisher["repository"],
            "--signer-workflow",
            publisher["workflow"],
            "--source-ref",
            source["ref"],
            "--source-digest",
            source["commit"],
            "--predicate-type",
            "https://slsa.dev/provenance/v1",
            "--cert-oidc-issuer",
            "https://token.actions.githubusercontent.com",
            "--format",
            "json",
        ]
        try:
            completed = self.runner(
                arguments,
                capture_output=True,
                text=True,
                timeout=120,
                check=False,
            )
        except subprocess.TimeoutExpired as error:
            raise UpdateError(
                "NETWORK_ERROR", "OCI attestation verification timed out.", retryable=True
            ) from error
        except OSError as error:
            raise UpdateError(
                "ATTESTATION_VERIFIER_MISSING", "GitHub CLI could not verify the OCI subject."
            ) from error
        if completed.returncode != 0:
            detail = f"{completed.stderr} {completed.stdout}".lower()
            if any(
                marker in detail
                for marker in (
                    "network",
                    "connection",
                    "timed out",
                    "timeout",
                    "temporary failure",
                    "dns",
                )
            ):
                raise UpdateError(
                    "NETWORK_ERROR",
                    "OCI attestation verification is temporarily unavailable.",
                    retryable=True,
                )
            raise UpdateError(
                "ATTESTATION_INVALID",
                "GitHub could not verify the pinned Echo OCI repository, workflow, source, and digest.",
            )
        try:
            verification = json.loads(completed.stdout)
        except json.JSONDecodeError as error:
            raise UpdateError(
                "ATTESTATION_INVALID", "GitHub CLI returned malformed OCI attestation JSON."
            ) from error
        if not isinstance(verification, list):
            raise UpdateError(
                "ATTESTATION_INVALID", "GitHub CLI returned an unexpected OCI verification shape."
            )
        raw_digest = artifact["digest"].removeprefix("sha256:")
        subject_name = artifact["repository"]
        matched_subject = any(
            isinstance(result, dict)
            and isinstance(result.get("verificationResult"), dict)
            and isinstance(result["verificationResult"].get("statement"), dict)
            and result["verificationResult"]["statement"].get("predicateType")
            == "https://slsa.dev/provenance/v1"
            and isinstance(result["verificationResult"]["statement"].get("subject"), list)
            and any(
                isinstance(subject, dict)
                and subject.get("name") == subject_name
                and isinstance(subject.get("digest"), dict)
                and subject["digest"].get("sha256") == raw_digest
                for subject in result["verificationResult"]["statement"]["subject"]
            )
            for result in verification
        )
        if not matched_subject:
            raise UpdateError(
                "ATTESTATION_SUBJECT_MISMATCH",
                "The verified SLSA statement does not bind the pinned Echo OCI image digest.",
            )

    def _workload_asset_bytes(
        self, candidate: Candidate, reference: dict[str, Any], *, label: str
    ) -> tuple[bytes, str]:
        if candidate.release_tag is None:
            raise UpdateError(
                "UNTRUSTED_RELEASE_TAG", "Workload assets need an immutable release tag."
            )
        payload = self._get_release_asset_bytes(
            candidate.release_assets,
            reference.get("uri"),
            repository=candidate.component["publisher"],
            release_tag=candidate.release_tag,
            expected_digest=reference.get("sha256"),
            expected_size=reference.get("sizeBytes"),
        )
        publisher = self._publisher_for_component(candidate.component)
        provenance = candidate.manifest.get("provenance", {}).get("attestation")
        if publisher is None or not isinstance(provenance, dict):
            raise UpdateError("UNTRUSTED_ATTESTATION", f"Missing release authority for {label}.")
        subject_name = PurePosixPath(urllib.parse.urlsplit(reference["uri"]).path).name
        proof = self._release_attestation_bundle(
            payload=payload,
            repository=publisher["repository"],
            digest=reference["sha256"],
            workflow=publisher["workflow"],
            source_ref=candidate.manifest["source"]["ref"],
            source_commit=candidate.manifest["source"]["commit"],
            subject_name=subject_name,
            release_assets=candidate.release_assets,
            release_tag=candidate.release_tag,
        )
        return payload, "sha256:" + hashlib.sha256(proof).hexdigest()

    def _stage_workload_sdk(
        self,
        candidate: Candidate,
        stage_root: Path,
        plan_id: str,
        plan_digest: str,
        resolution_component: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Verify and stage the exact official SDK wheel for the workload operator."""

        artifact = candidate.manifest["artifact"]
        if (
            artifact.get("kind") != "python-bundle"
            or artifact.get("format") != "tar.gz"
            or candidate.component.get("componentId") != WORKLOAD_SDK_COMPONENT_ID
            or not isinstance(resolution_component, dict)
            or resolution_component.get("targetId") != WORKLOAD_SDK_TARGET_ID
        ):
            raise UpdateError(
                "SDK_RELEASE_INVALID", "The Runtime Maintenance SDK target is not supported."
            )
        component_root = stage_root / WORKLOAD_SDK_COMPONENT_ID
        component_root.mkdir(mode=0o700)
        filename = PurePosixPath(urllib.parse.urlsplit(artifact["uri"]).path).name
        if not filename or filename in {".", ".."}:
            raise UpdateError("SDK_RELEASE_INVALID", "The SDK archive has no safe filename.")
        archive_path = component_root / filename
        payload, attestation_digest = self._workload_asset_bytes(
            candidate,
            {key: artifact[key] for key in ("uri", "sha256", "sizeBytes")},
            label="Runtime Maintenance SDK bundle",
        )
        self._write_private_file(archive_path, payload)
        bundle_path = component_root / "bundle"
        self._extract_tar(archive_path, bundle_path, expected_files=artifact.get("files"))
        release_path = bundle_path / "sdk-release.json"
        try:
            metadata = json.loads(release_path.read_bytes(), object_pairs_hook=_unique_json_object)
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "SDK_RELEASE_INVALID", "SDK release metadata is invalid JSON."
            ) from error
        distribution = "cyrene-runtime-maintenance"
        version = "0.1.0"
        wheel_name = "cyrene_runtime_maintenance-0.1.0-py3-none-any.whl"
        if (
            not isinstance(metadata, dict)
            or set(metadata) != {"distribution", "version", "wheel", "wheelSha256"}
            or metadata.get("distribution") != distribution
            or metadata.get("version") != version
            or metadata.get("wheel") != wheel_name
            or not _valid_digest(metadata.get("wheelSha256"))
            or candidate.manifest.get("version") != version
            or candidate.manifest.get("contentDigest") != candidate.artifact_digest
            or set(artifact.get("files", {})) != {"sdk-release.json", wheel_name}
        ):
            raise UpdateError(
                "SDK_RELEASE_INVALID", "SDK bundle metadata differs from the pinned component."
            )
        wheel_path = bundle_path / wheel_name
        if (
            wheel_path.is_symlink()
            or not wheel_path.is_file()
            or _file_digest(wheel_path) != metadata["wheelSha256"]
        ):
            raise UpdateError(
                "SDK_RELEASE_INVALID", "SDK wheel digest differs from signed release metadata."
            )
        # The release manifest pins the wheel member separately from its wrapper metadata.
        expected_wheel_digest = artifact["files"][wheel_name]
        if expected_wheel_digest.removeprefix("sha256:") != metadata["wheelSha256"].removeprefix(
            "sha256:"
        ):
            raise UpdateError(
                "SDK_RELEASE_INVALID", "SDK wheel differs from the signed archive file map."
            )
        index_identity = resolution_component.get("indexIdentity")
        if not isinstance(index_identity, dict):
            raise UpdateError("SDK_RELEASE_INVALID", "SDK release has no trusted index identity.")
        identity_fields = self._workload_receipt_fields(candidate, resolution_component)
        return {
            "componentId": WORKLOAD_SDK_COMPONENT_ID,
            "status": "staged",
            "artifactKind": "python-bundle",
            "version": version,
            "digest": candidate.artifact_digest,
            "manifestDigest": candidate.manifest_digest,
            "manifestAssetDigest": candidate.manifest_asset_digest,
            "releaseId": identity_fields["releaseId"],
            "targetId": identity_fields["targetId"],
            "indexIdentity": index_identity,
            "publisherIdentity": identity_fields["publisherIdentity"],
            "attestationRef": identity_fields["attestationRef"],
            "wheelDigest": metadata["wheelSha256"],
            "attestationBundleDigest": attestation_digest,
            "stagedIdentity": {
                "archivePath": str(archive_path),
                "bundlePath": str(bundle_path),
                "wheelPath": str(wheel_path),
                "wheelDigest": metadata["wheelSha256"],
                "planId": plan_id,
                "planDigest": plan_digest,
            },
        }

    def _stage_workload_plugin_package(
        self,
        candidate: Candidate,
        stage_root: Path,
        plan_id: str,
        plan_digest: str,
        *,
        resolution_component: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        artifact = candidate.manifest["artifact"]
        component_id = candidate.component["componentId"]
        package_id = artifact["packageId"]
        component_root = stage_root / component_id
        component_root.mkdir(mode=0o700)
        references: list[tuple[str, dict[str, Any]]] = [
            ("archive", artifact["archive"]),
            ("descriptor", artifact["descriptor"]),
            ("requirementsLock", artifact["requirementsLock"]),
            ("packageReleaseMetadata", artifact["packageReleaseMetadata"]),
        ]
        references.extend(
            (f"preparerWheel{index}", row) for index, row in enumerate(artifact["preparerWheels"])
        )
        sbom = artifact.get("sbom")
        if sbom is not None:
            references.append(("sbom", sbom))
        stored_assets: dict[str, dict[str, Any]] = {}
        payloads: dict[str, bytes] = {}
        proof_digests: dict[str, str] = {}
        for label, reference in references:
            payload, proof_digest = self._workload_asset_bytes(candidate, reference, label=label)
            filename = PurePosixPath(urllib.parse.urlsplit(reference["uri"]).path).name
            target = component_root / filename
            if target.exists() or target.is_symlink():
                raise UpdateError(
                    "UNSAFE_STAGE", f"Duplicate workload release asset basename: {filename}."
                )
            self._write_private_file(target, payload)
            payloads[label] = payload
            proof_digests[label] = proof_digest
            stored_assets[label] = {
                "path": str(target),
                "uri": reference["uri"],
                "sha256": reference["sha256"],
                "sizeBytes": reference["sizeBytes"],
                "attestationBundleDigest": proof_digest,
            }
        metadata = self._parse_plugin_package_release_metadata(
            candidate, payloads["packageReleaseMetadata"], stored_assets
        )
        archive_reference = artifact["archive"]
        archive_path = Path(stored_assets["archive"]["path"])
        payload_root = component_root / "payload"
        self._extract_zip(
            archive_path,
            payload_root,
            expected_files=archive_reference["files"],
            max_entries=archive_reference["maxEntries"],
            max_member_bytes=archive_reference["maxUncompressedBytes"],
            max_expanded_bytes=archive_reference["maxUncompressedBytes"],
        )
        descriptor = self._validate_workload_package_descriptor(
            payloads["descriptor"],
            candidate,
            artifact,
            payload_root,
        )
        self._validate_workload_package_source_policy(
            metadata,
            resolution_component.get("sourcePolicy")
            if isinstance(resolution_component, dict)
            else None,
        )
        binding_id = (
            resolution_component.get("bindingId")
            if isinstance(resolution_component, dict)
            else None
        )
        source_policy = (
            resolution_component.get("sourcePolicy")
            if isinstance(resolution_component, dict)
            else None
        )
        if (
            not isinstance(binding_id, str)
            or ACTIVITY_SCOPE_ID_PATTERN.fullmatch(binding_id) is None
            or not isinstance(source_policy, dict)
        ):
            raise UpdateError(
                "SOURCE_BINDING_INVALID",
                "Plugin package staging requires the selected workload's explicit owner binding.",
            )
        return {
            "componentId": component_id,
            "status": "staged",
            "artifactKind": "plugin-package",
            "version": candidate.manifest["version"],
            "digest": candidate.artifact_digest,
            "manifestDigest": candidate.manifest_digest,
            "manifestAssetDigest": candidate.manifest_asset_digest,
            "packageId": package_id,
            "capabilityId": artifact["capabilityId"],
            "bindingId": binding_id,
            "packageArtifactDigest": descriptor["artifactDigest"],
            "archiveDigest": descriptor["archiveDigest"],
            "descriptorDigest": artifact["descriptor"]["sha256"],
            "dependencyLockDigest": descriptor["dependencyLockDigest"],
            "packageReleaseDigest": artifact["packageReleaseMetadata"]["sha256"],
            "sourceCommit": metadata["source"]["commit"],
            "sourcePolicy": (
                resolution_component.get("sourcePolicy")
                if isinstance(resolution_component, dict)
                else None
            ),
            "assetAttestations": proof_digests,
            "stagedIdentity": {
                "assetPaths": {key: row["path"] for key, row in stored_assets.items()},
                "payloadPath": str(payload_root),
                "planId": plan_id,
                "planDigest": plan_digest,
            },
        }

    def _validate_workload_package_descriptor(
        self,
        payload: bytes,
        candidate: Candidate,
        artifact: dict[str, Any],
        payload_root: Path,
    ) -> dict[str, str]:
        """Bind the signed descriptor to the exact verified ZIP members and release."""

        try:
            descriptor = json.loads(payload, object_pairs_hook=_unique_json_object)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_PACKAGE_DESCRIPTOR", "Package descriptor is invalid JSON."
            ) from error
        package = descriptor.get("package") if isinstance(descriptor, dict) else None
        capability = descriptor.get("capability") if isinstance(descriptor, dict) else None
        implementation = descriptor.get("implementation") if isinstance(descriptor, dict) else None
        implementation_artifact = (
            implementation.get("artifact") if isinstance(implementation, dict) else None
        )
        dependencies = descriptor.get("dependencies") if isinstance(descriptor, dict) else None
        lock = dependencies.get("lock") if isinstance(dependencies, dict) else None
        integrity = descriptor.get("integrity") if isinstance(descriptor, dict) else None
        if (
            not isinstance(descriptor, dict)
            or descriptor.get("record_type") != "package_descriptor"
            or descriptor.get("spec_version") != "0.1"
            or descriptor.get("publication_status") != "PUBLISHED"
            or not isinstance(package, dict)
            or package.get("id") != artifact.get("packageId")
            or package.get("version") != candidate.manifest.get("version")
            or not isinstance(capability, dict)
            or capability.get("id") != artifact.get("capabilityId")
            or not isinstance(implementation_artifact, dict)
            or implementation_artifact.get("status") != "PUBLISHED"
            or implementation_artifact.get("format") != "zip"
            or not isinstance(lock, dict)
            or lock.get("status") != "LOCKED"
            or lock.get("format") != "requirements.lock"
            or lock.get("ref") != "requirements.lock"
            or not isinstance(integrity, dict)
            or not _valid_digest(implementation_artifact.get("digest"))
            or integrity.get("artifact_digest") != implementation_artifact.get("digest")
            or not _valid_digest(integrity.get("archive_digest"))
            or not _valid_digest(lock.get("digest"))
        ):
            raise UpdateError(
                "PACKAGE_DESCRIPTOR_MISMATCH",
                "Package descriptor identity or immutable digest fields differ from the signed release.",
            )
        lock_path = payload_root / "requirements.lock"
        manifest_path = payload_root / "plugin.manifest.json"
        if (
            not lock_path.is_file()
            or lock_path.is_symlink()
            or not manifest_path.is_file()
            or manifest_path.is_symlink()
        ):
            raise UpdateError(
                "PACKAGE_CONTENT_MISMATCH", "Package ZIP is missing its root manifest or lock."
            )
        lock_digest = _file_digest(lock_path)
        if lock_digest != lock["digest"] or lock_digest != artifact["requirementsLock"]["sha256"]:
            raise UpdateError(
                "PACKAGE_LOCK_MISMATCH",
                "The verified ZIP lock differs from its descriptor or release.",
            )
        entries: list[tuple[str, bytes]] = []
        for current, directories, files in os.walk(payload_root, followlinks=False):
            parent = Path(current)
            if parent.is_symlink():
                raise UpdateError(
                    "UNSAFE_PACKAGE_CONTENT", "Package ZIP contains a symlink directory."
                )
            for name in directories + files:
                path = parent / name
                if path.is_symlink():
                    raise UpdateError("UNSAFE_PACKAGE_CONTENT", "Package ZIP contains a symlink.")
                if path.is_file():
                    entries.append((path.relative_to(payload_root).as_posix(), path.read_bytes()))
        entries.sort(key=lambda item: item[0])
        digest = hashlib.sha256()
        for name, content in entries:
            encoded_name = name.encode("utf-8")
            digest.update(len(encoded_name).to_bytes(8, "big"))
            digest.update(encoded_name)
            digest.update(len(content).to_bytes(8, "big"))
            digest.update(content)
        package_artifact_digest = "sha256:" + digest.hexdigest()
        if (
            integrity["archive_digest"] != candidate.artifact_digest
            or package_artifact_digest != integrity["artifact_digest"]
        ):
            raise UpdateError(
                "PACKAGE_CONTENT_MISMATCH",
                "Package Runtime descriptor digest does not match the archive bytes and members.",
            )
        return {
            "artifactDigest": package_artifact_digest,
            "archiveDigest": integrity["archive_digest"],
            "dependencyLockDigest": lock_digest,
        }

    @staticmethod
    def _validate_workload_package_source_policy(
        metadata: dict[str, Any], source_policy: Any
    ) -> None:
        """Require package-declared Product services to match the signed Catalog owner map."""

        policy = metadata.get("source_policy")
        package = metadata.get("package")
        if not isinstance(policy, dict) or not isinstance(package, dict):
            raise UpdateError(
                "PACKAGE_SOURCE_POLICY_INVALID", "Package source policy metadata is missing."
            )
        supported = package.get("supported_services")
        product_sources = policy.get("supported_product_sources")
        if (
            policy.get("authority") != "plugin.manifest.json#supportedServices"
            or not isinstance(supported, list)
            or any(not isinstance(item, str) or not item for item in supported)
            or len(set(supported)) != len(supported)
            or not isinstance(product_sources, list)
        ):
            raise UpdateError(
                "PACKAGE_SOURCE_POLICY_INVALID", "Package source policy metadata is malformed."
            )
        source_map: dict[str, str] = {}
        for row in product_sources:
            if (
                not isinstance(row, dict)
                or set(row) != {"service", "component_id"}
                or not isinstance(row.get("service"), str)
                or not isinstance(row.get("component_id"), str)
                or row["service"] in source_map
            ):
                raise UpdateError(
                    "PACKAGE_SOURCE_POLICY_INVALID", "Package Product source mapping is malformed."
                )
            source_map[row["service"]] = row["component_id"]
        if set(source_map) != set(supported):
            raise UpdateError(
                "PACKAGE_SOURCE_POLICY_INVALID",
                "Package supported services differ from the source map.",
            )
        if source_policy is None:
            return
        if not isinstance(source_policy, dict):
            raise UpdateError("SOURCE_POLICY_INVALID", "Workload source policy is malformed.")
        if source_policy.get("mode") == "actualProduct":
            expected_products = set(source_policy.get("productComponentIds", []))
            if set(source_map.values()) != expected_products:
                raise UpdateError(
                    "SOURCE_POLICY_MISMATCH",
                    "Package-supported Products differ from the signed workload source policy.",
                )

    def _parse_plugin_package_release_metadata(
        self,
        candidate: Candidate,
        payload: bytes,
        stored_assets: dict[str, dict[str, Any]],
    ) -> dict[str, Any]:
        try:
            value = json.loads(payload, object_pairs_hook=_unique_json_object)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_PACKAGE_RELEASE", "Plugin release metadata is invalid JSON."
            ) from error
        artifact = candidate.manifest["artifact"]
        source = value.get("source") if isinstance(value, dict) else None
        package = value.get("package") if isinstance(value, dict) else None
        policy = value.get("attestation_policy") if isinstance(value, dict) else None
        publisher = self._publisher_for_component(candidate.component)
        if (
            not isinstance(value, dict)
            or value.get("record_type") != "cyrene.plugin.package.release.v1"
            or value.get("spec_version") != "1"
            or not isinstance(source, dict)
            or not isinstance(package, dict)
            or not isinstance(policy, dict)
            or source.get("ref") != candidate.manifest["source"].get("ref")
            or source.get("commit") != candidate.manifest["source"].get("commit")
            or package.get("id") != artifact.get("packageId")
            or package.get("version") != candidate.manifest.get("version")
            or package.get("component_id") != candidate.component["componentId"]
            or package.get("capability") != artifact.get("capabilityId")
            or package.get("interface_version") != artifact.get("interfaceVersion")
            or policy.get("provider") != "github-actions"
            or publisher is None
            or policy.get("workflow") != publisher["workflow"]
            or policy.get("source_commit") != candidate.manifest["source"].get("commit")
        ):
            raise UpdateError(
                "PACKAGE_RELEASE_MISMATCH",
                "Signed Package Release identity differs from its manifest.",
            )
        subjects = policy.get("subject_assets")
        if not isinstance(subjects, list):
            raise UpdateError(
                "PACKAGE_RELEASE_MISMATCH", "Package Release subject asset list is missing."
            )
        expected_subjects = {
            PurePosixPath(urllib.parse.urlsplit(row["uri"]).path).name: row["sha256"]
            for key, row in stored_assets.items()
            if key != "packageReleaseMetadata"
        }
        actual_subjects: dict[str, str] = {}
        for subject in subjects:
            if (
                not isinstance(subject, dict)
                or set(subject) != {"name", "sha256"}
                or not isinstance(subject.get("name"), str)
                or not _valid_digest(subject.get("sha256"))
                or subject["name"] in actual_subjects
            ):
                raise UpdateError(
                    "PACKAGE_RELEASE_MISMATCH", "Package Release subject assets are malformed."
                )
            actual_subjects[subject["name"]] = subject["sha256"]
        if actual_subjects != expected_subjects:
            raise UpdateError(
                "PACKAGE_RELEASE_MISMATCH", "Attestation policy does not bind every package asset."
            )
        return value

    def _stage_workload_static_web(
        self,
        candidate: Candidate,
        stage_root: Path,
        plan_id: str,
        plan_digest: str,
        *,
        resolution_component: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        artifact = candidate.manifest["artifact"]
        component_id = candidate.component["componentId"]
        reference = {
            "uri": artifact["uri"],
            "sha256": artifact["sha256"],
            "sizeBytes": artifact["sizeBytes"],
        }
        archive_bytes, attestation_digest = self._workload_asset_bytes(
            candidate, reference, label="static web bundle"
        )
        component_root = stage_root / component_id
        component_root.mkdir(mode=0o700)
        archive_path = (
            component_root / PurePosixPath(urllib.parse.urlsplit(reference["uri"]).path).name
        )
        self._write_private_file(archive_path, archive_bytes)
        payload_root = component_root / "payload"
        self._extract_static_web_archive(archive_path, payload_root, artifact)
        release_id = candidate.manifest.get("releaseId")
        if (
            not isinstance(release_id, str)
            or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,255}", release_id) is None
        ):
            raise UpdateError(
                "INVALID_MANIFEST", "Static web release ID is not a safe path segment."
            )
        releases = DEFAULT_WORKLOAD_WEB_ROOT / component_id / "releases"
        self._ensure_workload_release_directory(releases)
        identity = f"{release_id}--{candidate.manifest_digest.removeprefix('sha256:')}"
        destination = releases / identity
        if destination.exists() or destination.is_symlink():
            if destination.is_symlink() or not destination.is_dir():
                raise UpdateError(
                    "UNSAFE_WEB_ROOT", "Existing static web release is not a directory."
                )
            self._verify_static_web_tree(destination, artifact["files"])
        else:
            temporary = releases / f".{identity}.{uuid.uuid4().hex}.tmp"
            shutil.copytree(payload_root, temporary, symlinks=False)
            self._set_static_web_permissions(temporary)
            os.replace(temporary, destination)
            self._fsync_directory(releases)
        identity_fields = self._workload_receipt_fields(candidate, resolution_component)
        receipt_item = {
            "componentId": component_id,
            "version": candidate.manifest["version"],
            "releaseIdentity": candidate.manifest_digest,
            "manifestDigest": candidate.manifest_digest,
            "artifactDigest": candidate.artifact_digest,
            "bundleIdentity": None,
            "manifest": candidate.manifest,
            "releasePath": str(destination),
            "archivePath": str(archive_path),
            "pointerIdentity": identity,
            **identity_fields,
        }
        self._write_release_receipt(receipt_item)
        return {
            "componentId": component_id,
            "status": "staged",
            "artifactKind": "static-web",
            "version": candidate.manifest["version"],
            "digest": candidate.artifact_digest,
            "manifestDigest": candidate.manifest_digest,
            "manifestAssetDigest": candidate.manifest_asset_digest,
            "releaseId": release_id,
            "targetId": identity_fields.get("targetId"),
            "indexIdentity": identity_fields.get("indexIdentity"),
            "publisherIdentity": identity_fields.get("publisherIdentity"),
            "attestationRef": identity_fields.get("attestationRef"),
            "attestationBundleDigest": attestation_digest,
            "stagedIdentity": {
                "releasePath": str(destination),
                "releaseIdentity": identity,
                "archivePath": str(archive_path),
                "planId": plan_id,
                "planDigest": plan_digest,
            },
        }

    @staticmethod
    def _ensure_workload_release_directory(path: Path) -> None:
        current = Path("/")
        for part in path.parts[1:]:
            current /= part
            current.mkdir(mode=0o755, exist_ok=True)
            info = current.lstat()
            if (
                current.is_symlink()
                or not stat.S_ISDIR(info.st_mode)
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) & 0o022
            ):
                raise UpdateError(
                    "UNSAFE_WEB_ROOT", "Static web release path is not root controlled."
                )

    @staticmethod
    def _set_static_web_permissions(root: Path) -> None:
        for current, directories, files in os.walk(root, followlinks=False):
            directory = Path(current)
            if directory.is_symlink():
                raise UpdateError("UNSAFE_WEB_ROOT", "Static web payload contains a symlink.")
            os.chown(directory, 0, 0)
            directory.chmod(0o755)
            for name in directories + files:
                path = directory / name
                if path.is_symlink():
                    raise UpdateError("UNSAFE_WEB_ROOT", "Static web payload contains a symlink.")
                if path.is_dir():
                    os.chown(path, 0, 0)
                    path.chmod(0o755)
                elif path.is_file():
                    os.chown(path, 0, 0)
                    path.chmod(0o644)
                else:
                    raise UpdateError(
                        "UNSAFE_WEB_ROOT", "Static web payload contains a special file."
                    )

    @staticmethod
    def _verify_static_web_tree(root: Path, expected_files: dict[str, str]) -> None:
        actual: dict[str, str] = {}
        for current, directories, files in os.walk(root, followlinks=False):
            directory = Path(current)
            if directory.is_symlink() or directory.stat().st_uid != 0:
                raise UpdateError("UNSAFE_WEB_ROOT", "Existing static web tree is unsafe.")
            for name in directories + files:
                path = directory / name
                if path.is_symlink():
                    raise UpdateError(
                        "UNSAFE_WEB_ROOT", "Existing static web tree contains a symlink."
                    )
                if path.is_file():
                    actual[path.relative_to(root).as_posix()] = _file_digest(path)
        if actual != expected_files:
            raise UpdateError(
                "WEB_RELEASE_COLLISION", "Existing immutable static web release differs."
            )

    def _extract_static_web_archive(
        self, archive_path: Path, destination: Path, artifact: dict[str, Any]
    ) -> None:
        files = artifact["files"]
        if artifact["format"] == "zip":
            self._extract_zip(
                archive_path,
                destination,
                expected_files=files,
                max_entries=artifact["maxEntries"],
                max_member_bytes=artifact["maxUncompressedBytes"],
                max_expanded_bytes=artifact["maxUncompressedBytes"],
            )
        elif artifact["format"] == "tar.gz":
            self._extract_tar(
                archive_path,
                destination,
                expected_files=files,
                max_entries=artifact["maxEntries"],
                max_member_bytes=artifact["maxUncompressedBytes"],
                max_expanded_bytes=artifact["maxUncompressedBytes"],
            )
        elif artifact["format"] == "tar.zst":
            tar_path = archive_path.with_suffix(".tar")
            try:
                with tar_path.open("xb") as output:
                    result = self.runner(
                        ["zstd", "--decompress", "--stdout", str(archive_path)],
                        stdout=output,
                        stderr=subprocess.PIPE,
                        timeout=180,
                        check=False,
                    )
                if (
                    result.returncode != 0
                    or tar_path.stat().st_size > artifact["maxUncompressedBytes"]
                ):
                    raise UpdateError(
                        "INVALID_ARTIFACT", "Static web archive exceeds its expansion limit."
                    )
                self._extract_tar(
                    tar_path,
                    destination,
                    expected_files=files,
                    max_entries=artifact["maxEntries"],
                    max_member_bytes=artifact["maxUncompressedBytes"],
                    max_expanded_bytes=artifact["maxUncompressedBytes"],
                )
            except (OSError, subprocess.TimeoutExpired) as error:
                raise UpdateError(
                    "INVALID_ARTIFACT", "Cannot safely decompress static web archive."
                ) from error
            finally:
                tar_path.unlink(missing_ok=True)
        else:
            raise UpdateError("INVALID_MANIFEST", "Unsupported static web archive format.")
        self._set_static_web_permissions(destination)
        self._verify_static_web_tree(destination, files)

    def _extract_zip(
        self,
        archive: Path,
        destination: Path,
        *,
        expected_files: dict[str, str],
        max_entries: int,
        max_member_bytes: int,
        max_expanded_bytes: int,
    ) -> None:
        destination.mkdir(mode=0o700)
        found: dict[str, str] = {}
        total = 0
        try:
            with zipfile.ZipFile(archive) as source:
                entries = source.infolist()
                if not entries or len(entries) > max_entries:
                    raise UpdateError(
                        "UNSAFE_ARTIFACT", "ZIP entry count exceeds its signed limit."
                    )
                seen: set[str] = set()
                for entry in entries:
                    if entry.is_dir():
                        continue
                    relative = _safe_relative(entry.filename, field="ZIP entry path")
                    name = relative.as_posix()
                    mode = (entry.external_attr >> 16) & 0xFFFF
                    if stat.S_ISLNK(mode) or not stat.S_ISREG(mode):
                        raise UpdateError("UNSAFE_ARTIFACT", "ZIP contains a link or special file.")
                    if name in seen or entry.file_size > max_member_bytes:
                        raise UpdateError(
                            "UNSAFE_ARTIFACT", "ZIP contains a duplicate or oversized entry."
                        )
                    seen.add(name)
                    total += entry.file_size
                    if total > max_expanded_bytes:
                        raise UpdateError(
                            "UNSAFE_ARTIFACT", "ZIP expansion exceeds its signed limit."
                        )
                    target = destination.joinpath(*relative.parts)
                    target.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
                    digest = hashlib.sha256()
                    size = 0
                    with source.open(entry) as input_stream, target.open("xb") as output_stream:
                        while chunk := input_stream.read(1024 * 1024):
                            size += len(chunk)
                            if size > entry.file_size or size > max_member_bytes:
                                raise UpdateError(
                                    "UNSAFE_ARTIFACT", "ZIP entry exceeded its declared size."
                                )
                            output_stream.write(chunk)
                            digest.update(chunk)
                    if size != entry.file_size:
                        raise UpdateError(
                            "INVALID_ARTIFACT",
                            "ZIP entry length differs from its directory record.",
                        )
                    found[name] = "sha256:" + digest.hexdigest()
        except (OSError, zipfile.BadZipFile, RuntimeError) as error:
            raise UpdateError(
                "INVALID_ARTIFACT", "Cannot safely read the signed ZIP archive."
            ) from error
        if found != expected_files:
            raise UpdateError(
                "ARTIFACT_CONTENT_MISMATCH", "ZIP contents differ from the signed file map."
            )

    def apply_workload(
        self,
        workload_id: Any,
        target_id: Any,
        plan_id: Any,
        plan_digest: Any,
        confirmation: Any,
        *,
        action: Any,
        channel: Any,
    ) -> dict[str, Any]:
        """Apply a staged Product/Web/SDK workload through the native transaction journal."""

        self._require_authorized_process()
        self._clear_release_discovery_caches()
        with self._exclusive_update_lock():
            return self._apply_workload_locked(
                workload_id,
                target_id,
                plan_id,
                plan_digest,
                confirmation,
                action=action,
                channel=channel,
            )

    def _apply_workload_locked(
        self,
        workload_id: Any,
        target_id: Any,
        plan_id: Any,
        plan_digest: Any,
        confirmation: Any,
        *,
        action: Any,
        channel: Any,
    ) -> dict[str, Any]:
        """Revalidate and apply one workload while holding the updater lock."""

        self._validate_plan_identity(plan_id, plan_digest)
        workload_id, target_id = self._require_workload_target(workload_id, target_id)
        if not isinstance(action, str) or action not in {"install", "uninstall"}:
            raise UpdateError("INVALID_ACTION", "Workload action must be install or uninstall.")
        selected_channel = self._resolve_channel(channel)
        if (
            not isinstance(confirmation, dict)
            or set(confirmation) != {"planId", "planDigest", "confirmed"}
            or confirmation.get("planId") != plan_id
            or confirmation.get("planDigest") != plan_digest
            or confirmation.get("confirmed") is not True
        ):
            raise UpdateError(
                "CONFIRMATION_MISMATCH",
                "Apply needs confirmation for the exact plan ID and digest.",
            )
        directory = self._workload_plan_directory()
        stored = _read_object(directory / f"{plan_id}.json", "staged workload plan")
        if (
            stored.get("planKind") != WORKLOAD_PROTOCOL_VERSION
            or stored.get("phase") != "staged"
            or stored.get("planId") != plan_id
            or stored.get("planDigest") != plan_digest
            or stored.get("workloadId") != workload_id
            or stored.get("targetId") != target_id
            or stored.get("action") != action
            or stored.get("channel") != selected_channel
            or stored.get("catalogDigest") != self.catalog_digest
            or stored.get("catalogGeneration") != self.catalog_generation
        ):
            raise UpdateError("PLAN_NOT_STAGED", "This exact workload plan is not staged.")
        if action == "uninstall":
            return self._apply_workload_uninstall_locked(stored, confirmation)
        return self._apply_workload_install_locked(stored, confirmation)

    def _load_workload_sdk_environment(self) -> Any:
        """Load the separately owned, root-verified operator venv installer."""

        module_path = Path(__file__).with_name("workload_sdk_environment.py")
        if module_path.is_symlink() or not module_path.is_file():
            raise UpdateError(
                "WORKLOAD_SDK_UNAVAILABLE", "The workload operator SDK installer is missing."
            )
        module_name = "_cyrene_workload_sdk_environment"
        spec = importlib.util.spec_from_file_location(module_name, module_path)
        if spec is None or spec.loader is None:
            raise UpdateError(
                "WORKLOAD_SDK_UNAVAILABLE", "The workload operator SDK installer cannot load."
            )
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        try:
            spec.loader.exec_module(module)
        except Exception as error:
            sys.modules.pop(module_name, None)
            raise UpdateError(
                "WORKLOAD_SDK_UNAVAILABLE", "The workload operator SDK installer failed to load."
            ) from error
        prepare = getattr(module, "prepare_workload_sdk_environment", None)
        read_environment = getattr(module, "read_workload_sdk_environment", None)
        restore = getattr(module, "restore_workload_sdk_environment", None)
        if not callable(prepare) or not callable(read_environment) or not callable(restore):
            raise UpdateError(
                "WORKLOAD_SDK_UNAVAILABLE", "The workload operator SDK installer API is invalid."
            )
        return module

    @staticmethod
    def _workload_sdk_matches_selected(
        selected: dict[str, Any],
        installed: Any,
    ) -> bool:
        """Compare a protected SDK receipt to one exact selected Catalog row."""

        if not isinstance(installed, dict) or installed.get("installed") is not True:
            return False
        if installed.get("verification") != {"identityAttested": True}:
            return False
        fields = (
            "componentId",
            "artifactKind",
            "version",
            "targetId",
            "releaseId",
            "manifestUri",
            "manifestDigest",
            "manifestAssetDigest",
            "digest",
            "indexIdentity",
            "publisherIdentity",
            "attestationRef",
        )
        if any(installed.get(field) != selected.get(field) for field in fields):
            return False
        index_identity = selected.get("indexIdentity")
        if (
            installed.get("artifactDigest") != selected.get("digest")
            or installed.get("releaseIdentity") != selected.get("manifestDigest")
            or not isinstance(index_identity, dict)
            or installed.get("releaseTag") != index_identity.get("releaseTag")
        ):
            return False
        source_identity = installed.get("sourceIdentity")
        return (
            isinstance(source_identity, dict)
            and source_identity.get("artifactDigest") == selected.get("digest")
            and source_identity.get("manifestDigest") == selected.get("manifestDigest")
            and source_identity.get("manifestAssetDigest") == selected.get("manifestAssetDigest")
            and source_identity.get("releaseId") == selected.get("releaseId")
        )

    def _prepare_workload_sdk_durably(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        sdk_module: Any,
        selected: dict[str, Any],
        staged: dict[str, Any],
        *,
        plan_id: str,
        plan_digest: str,
    ) -> dict[str, Any]:
        """Journal SDK prior identity before venv creation or pointer activation."""

        current = sdk_module.read_workload_sdk_environment()
        if staged.get("status") == "current":
            if not self._workload_sdk_matches_selected(selected, current):
                raise UpdateError(
                    "WORKLOAD_SDK_READBACK_REQUIRED",
                    "The current operator SDK differs from the selected plan.",
                    retryable=True,
                )
            transaction["sdkEnvironment"] = current
            _atomic_json(transaction_path, transaction)
            return current

        staged_identity = staged.get("stagedIdentity")
        if (
            not isinstance(staged_identity, dict)
            or staged_identity.get("planId") != plan_id
            or staged_identity.get("planDigest") != plan_digest
        ):
            raise UpdateError(
                "INVALID_STAGE", "Operator SDK stage is not bound to this workload plan."
            )

        intent = transaction.get("sdkPrepareIntent")
        if intent is None:
            if self._workload_sdk_matches_selected(selected, current):
                raise UpdateError(
                    "WORKLOAD_SDK_READBACK_REQUIRED",
                    "The selected SDK is active without a durable prepare intent.",
                    retryable=True,
                )
            intent = {
                "schemaVersion": 1,
                "planId": plan_id,
                "planDigest": plan_digest,
                "componentId": selected["componentId"],
                "selectedIdentity": selected,
                "stagedIdentity": staged_identity,
                "priorIdentity": current,
                "status": "pending",
            }
            transaction["sdkPrepareIntent"] = intent
            transaction["phase"] = "operator_sdk_prepare_pending"
            _atomic_json(transaction_path, transaction)
        elif (
            not isinstance(intent, dict)
            or intent.get("schemaVersion") != 1
            or intent.get("planId") != plan_id
            or intent.get("planDigest") != plan_digest
            or intent.get("componentId") != selected.get("componentId")
            or intent.get("selectedIdentity") != selected
            or intent.get("stagedIdentity") != staged_identity
        ):
            raise UpdateError(
                "INVALID_TRANSACTION", "Operator SDK prepare intent differs from this plan."
            )

        prior = intent.get("priorIdentity")
        if prior is not None and not isinstance(prior, dict):
            raise UpdateError("INVALID_TRANSACTION", "Operator SDK prior identity is malformed.")
        if current != prior:
            if self._workload_sdk_matches_selected(selected, current):
                transaction["sdkEnvironment"] = current
                intent["status"] = "prepared"
                transaction["phase"] = "applying"
                transaction.pop("recoveryError", None)
                _atomic_json(transaction_path, transaction)
                return current
            raise UpdateError(
                "WORKLOAD_SDK_READBACK_REQUIRED",
                "Operator SDK current differs from both the prior and selected plan identities.",
                retryable=True,
            )

        sdk_component = {**selected, "verification": {"identityAttested": True}}
        try:
            sdk_module.prepare_workload_sdk_environment(sdk_component, staged_identity)
            current = sdk_module.read_workload_sdk_environment()
            if not self._workload_sdk_matches_selected(selected, current):
                raise RuntimeError("active SDK readback differs from the selected signed identity")
        except Exception as error:
            transaction["recoveryError"] = (
                "Operator SDK preparation did not reach a verified active identity."
            )
            _atomic_json(transaction_path, transaction)
            raise UpdateError(
                "WORKLOAD_SDK_INSTALL_FAILED",
                "The verified operator SDK could not be prepared or read back.",
                retryable=True,
            ) from error
        transaction["sdkEnvironment"] = current
        intent["status"] = "prepared"
        transaction["phase"] = "applying"
        transaction.pop("recoveryError", None)
        _atomic_json(transaction_path, transaction)
        return current

    def _restore_workload_sdk_environment(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
    ) -> None:
        """CAS-restore the SDK pointer recorded by a durable prepare intent."""

        intent = transaction.get("sdkPrepareIntent")
        if not isinstance(intent, dict):
            return
        if (
            intent.get("schemaVersion") != 1
            or intent.get("planId") != transaction.get("planId")
            or intent.get("planDigest") != transaction.get("planDigest")
            or not isinstance(intent.get("selectedIdentity"), dict)
            or intent.get("componentId") != intent["selectedIdentity"].get("componentId")
        ):
            raise UpdateError("INVALID_TRANSACTION", "Operator SDK rollback intent is malformed.")
        prior = intent.get("priorIdentity")
        if prior is not None and not isinstance(prior, dict):
            raise UpdateError("INVALID_TRANSACTION", "Operator SDK prior identity is malformed.")
        sdk_module = self._load_workload_sdk_environment()
        current = sdk_module.read_workload_sdk_environment()
        if current == prior:
            intent["status"] = "restored"
            transaction["sdkEnvironmentRestored"] = prior
            _atomic_json(transaction_path, transaction)
            return
        if not self._workload_sdk_matches_selected(intent["selectedIdentity"], current):
            raise UpdateError(
                "WORKLOAD_SDK_READBACK_REQUIRED",
                "Operator SDK current identity differs from both the plan and its prior receipt.",
                retryable=True,
            )
        try:
            restored = sdk_module.restore_workload_sdk_environment(
                prior,
                expected_current=current,
            )
        except Exception as error:
            raise UpdateError(
                "WORKLOAD_SDK_ROLLBACK_FAILED",
                "Operator SDK current pointer could not be restored safely.",
                retryable=True,
            ) from error
        if restored != prior:
            raise UpdateError(
                "WORKLOAD_SDK_READBACK_REQUIRED",
                "Operator SDK rollback did not restore the exact prior identity.",
                retryable=True,
            )
        intent["status"] = "restored"
        transaction["sdkEnvironmentRestored"] = restored
        _atomic_json(transaction_path, transaction)

    def _load_workload_web_host(self) -> Any:
        """Load the adjacent dedicated loopback web-host lifecycle helper."""

        module_path = Path(__file__).with_name("workload_web_host.py")
        if module_path.is_symlink() or not module_path.is_file():
            raise UpdateError(
                "WORKLOAD_WEB_HOST_UNAVAILABLE", "The workload Web host helper is missing."
            )
        module_name = "_cyrene_workload_web_host"
        existing = sys.modules.get(module_name)
        if existing is not None:
            return existing
        spec = importlib.util.spec_from_file_location(module_name, module_path)
        if spec is None or spec.loader is None:
            raise UpdateError(
                "WORKLOAD_WEB_HOST_UNAVAILABLE", "The workload Web host helper cannot load."
            )
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        try:
            spec.loader.exec_module(module)
        except Exception as error:
            sys.modules.pop(module_name, None)
            raise UpdateError(
                "WORKLOAD_WEB_HOST_UNAVAILABLE", "The workload Web host helper failed to load."
            ) from error
        required = (
            "prepare_host_prerequisites",
            "check_web_host_prerequisites",
            "capture_web_host_state",
            "apply_web_host",
            "rollback_web_host",
            "remove_web_host",
            "read_web_host_status",
        )
        if any(not callable(getattr(module, name, None)) for name in required):
            raise UpdateError(
                "WORKLOAD_WEB_HOST_UNAVAILABLE", "The workload Web host helper API is incomplete."
            )
        return module

    def _workload_web_host_runner(
        self, arguments: list[str], environment: Mapping[str, str]
    ) -> subprocess.CompletedProcess[str]:
        """Adapt Web Host's argv/environment callback to the updater runner contract."""

        return self.runner(
            list(arguments),
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
            env=dict(environment),
        )

    def _load_workload_oci_host(self) -> Any:
        """Load the adjacent fixed Echo OCI lifecycle helper."""

        module_path = Path(__file__).with_name("workload_oci_host.py")
        if module_path.is_symlink() or not module_path.is_file():
            raise UpdateError("WORKLOAD_OCI_HOST_UNAVAILABLE", "The Echo OCI helper is missing.")
        module_name = "_cyrene_workload_oci_host"
        existing = sys.modules.get(module_name)
        if existing is not None:
            module = existing
        else:
            spec = importlib.util.spec_from_file_location(module_name, module_path)
            if spec is None or spec.loader is None:
                raise UpdateError(
                    "WORKLOAD_OCI_HOST_UNAVAILABLE", "The Echo OCI helper cannot load."
                )
            module = importlib.util.module_from_spec(spec)
            sys.modules[module_name] = module
            try:
                spec.loader.exec_module(module)
            except Exception as error:
                sys.modules.pop(module_name, None)
                raise UpdateError(
                    "WORKLOAD_OCI_HOST_UNAVAILABLE", "The Echo OCI helper failed to load."
                ) from error
        required = (
            "OciHostSpec",
            "pull_and_verify_image",
            "start_container",
            "container_status",
            "stop_container",
            "remove_container",
        )
        if any(not hasattr(module, name) for name in required):
            raise UpdateError(
                "WORKLOAD_OCI_HOST_UNAVAILABLE", "The Echo OCI helper API is incomplete."
            )
        return module

    def _workload_echo_receipt_path(self) -> Path | None:
        directory = self._installed_component_directory(WORKLOAD_ECHO_COMPONENT_ID)
        return directory / WORKLOAD_ECHO_RECEIPT_NAME if directory is not None else None

    def _read_workload_echo_receipt(self) -> dict[str, Any] | None:
        """Read one redacted root-owned Echo OCI identity receipt."""

        path = self._workload_echo_receipt_path()
        if path is None or (not path.exists() and not path.is_symlink()):
            return None
        receipt = _read_object(path, "Echo OCI active receipt")
        expected = {
            "schemaVersion",
            "componentId",
            "installed",
            "version",
            "releaseId",
            "manifestUri",
            "targetId",
            "manifestDigest",
            "manifestAssetDigest",
            "digest",
            "imageReference",
            "imageDigest",
            "indexIdentity",
            "publisherIdentity",
            "attestationRef",
            "verification",
            "artifactAttestationVerified",
            "runnerIdentity",
            "containerReceipt",
        }
        if (
            set(receipt) != expected
            or receipt.get("schemaVersion") != 1
            or receipt.get("componentId") != WORKLOAD_ECHO_COMPONENT_ID
            or receipt.get("installed") is not True
            or receipt.get("targetId") != WORKLOAD_ECHO_TARGET_ID
            or not isinstance(receipt.get("version"), str)
            or VERSION_PATTERN.fullmatch(receipt["version"]) is None
            or not isinstance(receipt.get("releaseId"), str)
            or not isinstance(receipt.get("manifestUri"), str)
            or not _valid_digest(receipt.get("manifestDigest"))
            or not _valid_digest(receipt.get("manifestAssetDigest"))
            or not _valid_digest(receipt.get("digest"))
            or receipt.get("digest") != receipt.get("imageDigest")
            or receipt.get("imageReference")
            != f"{WORKLOAD_ECHO_IMAGE_REPOSITORY}@{receipt.get('imageDigest')}"
            or not isinstance(receipt.get("indexIdentity"), dict)
            or not isinstance(receipt.get("publisherIdentity"), dict)
            or not isinstance(receipt.get("attestationRef"), dict)
            or receipt.get("verification") != {"identityAttested": True}
            or receipt.get("artifactAttestationVerified") is not True
            or not isinstance(receipt.get("containerReceipt"), dict)
            or receipt.get("runnerIdentity") is not None
            and not isinstance(receipt.get("runnerIdentity"), dict)
        ):
            raise UpdateError("INVALID_INSTALLED_RELEASE", "Echo OCI receipt is malformed.")
        container = receipt["containerReceipt"]
        if (
            container.get("componentId") != WORKLOAD_ECHO_COMPONENT_ID
            or container.get("targetId") != WORKLOAD_ECHO_TARGET_ID
            or container.get("manifestDigest") != receipt["manifestDigest"]
            or container.get("imageDigest") != receipt["imageDigest"]
            or container.get("imageReference") != receipt["imageReference"]
            or container.get("state") not in {"running", "created", "exited"}
            or type(container.get("hostUid")) is not int
            or type(container.get("hostGid")) is not int
            or container.get("activitySourceId") != WORKLOAD_ECHO_SOURCE_ID
            or type(container.get("activityCatalogGeneration")) is not int
            or container.get("activityCatalogGeneration") < 1
            or container.get("dataDirectory") != "/var/lib/cyrene/echo"
            or container.get("artifactDirectory") != "/var/lib/cyrene/echo/artifacts"
        ):
            raise UpdateError("INVALID_INSTALLED_RELEASE", "Echo OCI receipt identity differs.")
        runner_identity = receipt.get("runnerIdentity")
        if runner_identity is not None and (
            set(runner_identity)
            != {"componentId", "sourceId", "bindingId", "packageId", "installationId"}
            or runner_identity.get("componentId") != "cyrene-evaluation-exact-match"
            or not all(
                isinstance(runner_identity.get(field), str) and runner_identity[field]
                for field in ("sourceId", "bindingId", "packageId", "installationId")
            )
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE", "Echo runner owner receipt is malformed."
            )
        return receipt

    def _write_workload_echo_receipt(
        self,
        selected: dict[str, Any],
        container_receipt: dict[str, Any],
        *,
        runner_identity: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Persist exact release and redacted container identity, never env values."""

        digest = selected.get("digest")
        image_reference = f"{WORKLOAD_ECHO_IMAGE_REPOSITORY}@{digest}"
        if (
            selected.get("componentId") != WORKLOAD_ECHO_COMPONENT_ID
            or selected.get("artifactKind") != "oci-image"
            or selected.get("targetId") != WORKLOAD_ECHO_TARGET_ID
            or not _valid_digest(digest)
            or selected.get("manifestDigest") != container_receipt.get("manifestDigest")
            or container_receipt.get("imageDigest") != digest
            or container_receipt.get("imageReference") != image_reference
        ):
            raise UpdateError(
                "WORKLOAD_OCI_READBACK_REQUIRED", "Echo OCI runtime differs from its signed plan."
            )
        receipt = {
            "schemaVersion": 1,
            "componentId": WORKLOAD_ECHO_COMPONENT_ID,
            "installed": True,
            "version": selected["version"],
            "releaseId": selected["releaseId"],
            "manifestUri": selected["manifestUri"],
            "targetId": selected["targetId"],
            "manifestDigest": selected["manifestDigest"],
            "manifestAssetDigest": selected["manifestAssetDigest"],
            "digest": digest,
            "imageReference": image_reference,
            "imageDigest": digest,
            "indexIdentity": selected["indexIdentity"],
            "publisherIdentity": selected["publisherIdentity"],
            "attestationRef": selected["attestationRef"],
            "verification": {"identityAttested": True},
            "artifactAttestationVerified": True,
            "runnerIdentity": runner_identity,
            "containerReceipt": container_receipt,
        }
        directory = self._installed_component_directory(WORKLOAD_ECHO_COMPONENT_ID, create=True)
        assert directory is not None
        _atomic_json(directory / WORKLOAD_ECHO_RECEIPT_NAME, receipt)
        return receipt

    def _clear_workload_echo_receipt(self, image_digest: str) -> None:
        """Clear only the receipt for the exact Echo image removed by this plan."""

        path = self._workload_echo_receipt_path()
        if path is None or (not path.exists() and not path.is_symlink()):
            return
        receipt = self._read_workload_echo_receipt()
        if receipt is not None and receipt.get("imageDigest") != image_digest:
            raise UpdateError("UNINSTALL_CONFLICT", "A different Echo image replaced this plan.")
        if path.is_symlink():
            raise UpdateError("UNSAFE_STATE", "Echo OCI receipt became a symbolic link.")
        path.unlink(missing_ok=True)
        self._fsync_directory(path.parent)

    def _read_workload_echo_api_token(self) -> tuple[str, str, int, int] | None:
        """Read the Echo API bearer only into memory from its fixed protected file."""

        try:
            user_id = pwd.getpwnam("cyrene").pw_uid
            group_id = grp.getgrnam("cyrene").gr_gid
        except KeyError as error:
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT", "Cyrene account is unavailable."
            ) from error
        raw = self._read_workload_protected_file(
            WORKLOAD_ECHO_API_TOKEN_PATH,
            allowed_identities={(0, group_id, 0o640), (user_id, group_id, 0o600)},
            maximum_bytes=4096,
        )
        if raw is None:
            return None
        try:
            token = raw.rstrip(b"\r\n").decode("ascii")
        except UnicodeDecodeError as error:
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT", "Echo API bearer is invalid."
            ) from error
        self._validate_workload_api_token(token)
        digest = "sha256:" + hashlib.sha256(raw).hexdigest()
        return token, digest, user_id, group_id

    def _ensure_workload_echo_api_token(
        self, transaction: dict[str, Any], transaction_path: Path
    ) -> str:
        """Create or reuse the stable root-protected Echo API bearer without Catalyst projection."""

        selected = self._workload_catalyst_token_configuration(generate=True)
        if selected is None or selected[1] != WORKLOAD_ECHO_API_TOKEN_PATH:
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                "Existing API bearer configuration is outside the fixed Echo secret path.",
            )
        token, token_path, group_id = selected
        token_content = (self._validate_workload_api_token(token) + "\n").encode("ascii")
        digest = self._write_workload_managed_config(
            transaction,
            transaction_path,
            path=token_path,
            content=token_content,
            group_id=group_id,
            mode=0o640,
            entry_kind="catalyst-api-token",
        )
        transaction["echoApiTokenIdentity"] = {
            "path": str(token_path),
            "sha256": digest,
            "ownerUid": 0,
            "ownerGid": group_id,
            "mode": 0o640,
        }
        _atomic_json(transaction_path, transaction)
        return token

    def _workload_echo_source_identity(
        self,
    ) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
        """Read the signed Echo source mapping and its exact active host principal."""

        workload = next(
            (
                row
                for row in self.catalog.get("workloads", [])
                if isinstance(row, dict) and row.get("workloadId") == "echo"
            ),
            None,
        )
        policy = workload.get("sourcePolicy") if isinstance(workload, dict) else None
        mappings = policy.get("productSources") if isinstance(policy, dict) else None
        matches = [
            row
            for row in mappings or []
            if isinstance(row, dict) and row.get("componentId") == WORKLOAD_ECHO_COMPONENT_ID
        ]
        if len(matches) != 1 or matches[0].get("sourceId") != WORKLOAD_ECHO_SOURCE_ID:
            raise UpdateError(
                "SOURCE_BINDING_INVALID", "Signed Echo source mapping is unavailable."
            )
        activity_catalog, _ = self._activity_catalog()
        sources = [
            row
            for row in activity_catalog.get("sources", [])
            if isinstance(row, dict) and row.get("source_id") == WORKLOAD_ECHO_SOURCE_ID
        ]
        if len(sources) != 1:
            raise UpdateError(
                "PACKAGE_RUNTIME_SOURCE_UNAVAILABLE",
                "The signed Echo ActivitySource is not registered in the active broker catalog.",
                retryable=True,
            )
        source = sources[0]
        if (
            type(source.get("uid")) is not int
            or source["uid"] <= 0
            or type(source.get("gid")) is not int
            or source["gid"] <= 0
            or not isinstance(source.get("source_token_sha256"), str)
        ):
            raise UpdateError("GATE_UNKNOWN", "Echo ActivitySource identity is malformed.")
        token_digest = source["source_token_sha256"].removeprefix("sha256:")
        if re.fullmatch(r"[0-9a-f]{64}", token_digest) is None:
            raise UpdateError("GATE_UNKNOWN", "Echo ActivitySource token digest is malformed.")
        return (
            activity_catalog,
            source,
            {
                "uid": source["uid"],
                "gid": source["gid"],
                "tokenPath": DEFAULT_ACTIVITY_TOKEN_DIRECTORY / f"{WORKLOAD_ECHO_SOURCE_ID}.token",
                "tokenDigest": token_digest,
            },
        )

    def _workload_echo_runner_identity(
        self,
        package_inventory: dict[str, Any],
        *,
        prior_identity: dict[str, Any] | None = None,
    ) -> tuple[str | None, dict[str, Any] | None]:
        """Read the selected Exact Match connection ref through its scoped SDK owner."""

        component_id = "cyrene-evaluation-exact-match"
        component = self.components.get(component_id)
        plugin = component.get("pluginPackage") if isinstance(component, dict) else None
        if not isinstance(plugin, dict):
            return None, None
        source_policy, plugin_rows = self._workload_plugin_owner_rows(
            "echo",
            tuple(
                sorted(self._load_workload_resolver().potential_component_ids(self.catalog, "echo"))
            ),
        )
        row = next((item for item in plugin_rows if item.get("componentId") == component_id), None)
        if not isinstance(row, dict) or not isinstance(source_policy, dict):
            return None, None
        records = package_inventory.get("installationRecords", {})
        installation = records.get(component_id) if isinstance(records, dict) else None
        if not isinstance(installation, dict):
            return (None, prior_identity) if prior_identity is not None else (None, None)
        installation_id = installation.get("installation_id")
        if not isinstance(installation_id, str):
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED", "Exact Match installation ID is missing."
            )
        binding_id = row.get("bindingId")
        package_id = row.get("packageId")
        source_id = self._workload_policy_source_id(source_policy)
        if not all(
            isinstance(value, str) and value for value in (binding_id, package_id, source_id)
        ):
            raise UpdateError("SOURCE_BINDING_INVALID", "Exact Match owner mapping is incomplete.")
        runner_identity = {
            "componentId": component_id,
            "sourceId": source_id,
            "bindingId": binding_id,
            "packageId": package_id,
            "installationId": installation_id,
        }
        source_bindings = package_inventory.get("sourceBindings", [])
        active = next(
            (
                item
                for item in source_bindings
                if isinstance(item, dict)
                and item.get("sourceId") == source_id
                and item.get("bindingId") == binding_id
                and item.get("packageId") == package_id
                and item.get("activeInstallationId") == installation_id
                and item.get("state") == "RUNNING"
            ),
            None,
        )
        if not isinstance(active, dict):
            if prior_identity is not None and prior_identity == runner_identity:
                # Runtime credentials are never recovered from the updater
                # journal. An inactive owner cannot launch the Echo consumer.
                return None, runner_identity
            return None, None
        if prior_identity is not None and prior_identity != runner_identity:
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Echo's active Exact Match binding differs from its installed receipt.",
                retryable=True,
            )
        activity_catalog, runtime_policy, principals, helper = self._workload_source_state("echo")
        if runtime_policy is None:
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED", "Exact Match source policy is unavailable."
            )
        principal = principals.get(source_id)
        try:
            sdk_environment = self._load_workload_sdk_environment().read_workload_sdk_environment()
        except Exception as error:
            raise UpdateError(
                "WORKLOAD_SDK_READBACK_REQUIRED", "Operator SDK interpreter is unavailable."
            ) from error
        sdk_python = (
            Path(sdk_environment["pythonPath"])
            if isinstance(sdk_environment, dict)
            and sdk_environment.get("installed") is True
            and isinstance(sdk_environment.get("pythonPath"), str)
            else None
        )
        if not isinstance(principal, dict) or sdk_python is None or not sdk_python.is_absolute():
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Exact Match owner credentials are unavailable.",
            )
        request_id = "cyrene-echo-status-" + uuid.uuid4().hex
        try:
            result = helper.run_package_binding_operation(
                operation="runtime_status",
                source_id=source_id,
                uid=principal["uid"],
                gid=principal["gid"],
                token_path=principal["tokenPath"],
                binding_id=binding_id,
                package_id=package_id,
                installation_ids=[installation_id],
                catalog_generation=activity_catalog["generation"],
                request_id=request_id,
                sdk_python=sdk_python,
                activity_catalog=activity_catalog,
                runtime_policy=runtime_policy,
                source_principals=principals,
            )
        except Exception as error:
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Exact Match runtime status is unavailable.",
                retryable=True,
            ) from error
        status = result.get("status") if isinstance(result, dict) else None
        connection_ref = status.get("connection_ref") if isinstance(status, dict) else None
        if (
            not isinstance(status, dict)
            or status.get("binding_id") != binding_id
            or status.get("installation_id") != installation_id
            or status.get("state") != "RUNNING"
            or type(status.get("generation")) is not int
            or status.get("generation") != activity_catalog.get("generation")
            or not isinstance(connection_ref, str)
            or not connection_ref
            or len(connection_ref) > 2048
            or any(ord(character) < 32 for character in connection_ref)
        ):
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Exact Match owner has no matching active connection reference.",
                retryable=True,
            )
        return connection_ref, runner_identity

    def _workload_echo_container_spec(
        self,
        selected: dict[str, Any],
        activity_catalog: dict[str, Any],
        source: dict[str, Any],
        principal: dict[str, Any],
        *,
        api_token: str | None,
        connection_ref: str | None,
        activity_generation: int | None = None,
    ) -> Any:
        """Build the host helper input from signed release, broker, and UDS facts."""

        helper = self._load_workload_oci_host()
        digest = selected.get("digest")
        manifest_digest = selected.get("manifestDigest")
        if (
            selected.get("componentId") != WORKLOAD_ECHO_COMPONENT_ID
            or selected.get("targetId") != WORKLOAD_ECHO_TARGET_ID
            or selected.get("artifactKind") != "oci-image"
            or not _valid_digest(digest)
            or not _valid_digest(manifest_digest)
            or type(principal.get("uid")) is not int
            or type(principal.get("gid")) is not int
        ):
            raise UpdateError("INVALID_STAGE", "Echo OCI host identity is incomplete.")
        token_digest = source.get("source_token_sha256")
        if not isinstance(token_digest, str):
            raise UpdateError("GATE_UNKNOWN", "Echo ActivitySource digest is unavailable.")
        token_digest = token_digest.removeprefix("sha256:")
        if re.fullmatch(r"[0-9a-f]{64}", token_digest) is None:
            raise UpdateError("GATE_UNKNOWN", "Echo ActivitySource digest is malformed.")
        if api_token is not None:
            api_token = self._validate_workload_api_token(api_token)
        environment: dict[str, str] = {}
        if api_token is not None:
            environment["CYRENE_DATA_TOOLS_TOKEN"] = api_token
        if connection_ref is not None:
            if (
                not connection_ref
                or len(connection_ref) > 2048
                or any(ord(character) < 32 for character in connection_ref)
            ):
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED", "Echo runner reference is invalid."
                )
            environment["CYRENE_EVALUATION_RUNNER_CONNECTION_REF"] = connection_ref
        generation = (
            activity_generation
            if activity_generation is not None
            else activity_catalog.get("generation")
        )
        if type(generation) is not int or generation < 1:
            raise UpdateError("GATE_UNKNOWN", "Echo ActivitySource generation is invalid.")
        image_hex = digest.removeprefix("sha256:")
        mapping = {
            "schemaVersion": 1,
            "componentId": WORKLOAD_ECHO_COMPONENT_ID,
            "targetId": WORKLOAD_ECHO_TARGET_ID,
            "target": helper.ECHO_TARGET,
            "manifestDigest": manifest_digest,
            "imageRepository": WORKLOAD_ECHO_IMAGE_REPOSITORY,
            "imageDigest": digest,
            "platform": helper.ECHO_PLATFORM,
            "containerName": "cyrene-echo-" + image_hex[:12],
            "hostUid": principal["uid"],
            "hostGid": principal["gid"],
            "hostPort": 8094,
            "activitySourceId": WORKLOAD_ECHO_SOURCE_ID,
            "activityCatalogGeneration": generation,
            "activityTokenDigest": token_digest,
            "activityTokenPath": str(principal["tokenPath"]),
            "maintenanceSocketPath": str(DEFAULT_SOCKET),
            "dataDirectory": "/var/lib/cyrene/echo",
            "artifactDirectory": "/var/lib/cyrene/echo/artifacts",
            "environment": environment,
        }
        try:
            return helper.OciHostSpec.from_mapping(mapping)
        except Exception as error:
            raise UpdateError(
                "WORKLOAD_OCI_HOST_UNAVAILABLE", "Echo OCI spec failed validation."
            ) from error

    def _workload_oci_runner(self, arguments: list[str]) -> subprocess.CompletedProcess[str]:
        """Adapt the updater runner to the OCI helper's fixed Docker command API."""

        return self.runner(
            ["/usr/bin/docker", "--host", "unix:///var/run/docker.sock", *arguments],
            capture_output=True,
            text=True,
            timeout=300,
            check=False,
        )

    def _preflight_workload_oci_runtime(self) -> None:
        """Require the fixed Docker daemon before changing workload or broker state."""

        docker = Path("/usr/bin/docker")
        if docker.is_symlink() or not docker.is_file() or not os.access(docker, os.X_OK):
            raise UpdateError(
                "OCI_RUNTIME_UNAVAILABLE",
                "Echo installation requires the managed Docker CLI at /usr/bin/docker.",
            )
        try:
            completed = self.runner(
                [
                    str(docker),
                    "--host",
                    "unix:///var/run/docker.sock",
                    "info",
                    "--format",
                    "{{.ServerVersion}}",
                ],
                capture_output=True,
                text=True,
                timeout=5,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired) as error:
            raise UpdateError(
                "OCI_RUNTIME_UNAVAILABLE",
                "The root-managed Docker daemon could not be queried.",
                retryable=True,
            ) from error
        if completed.returncode != 0 or not completed.stdout.strip():
            raise UpdateError(
                "OCI_RUNTIME_UNAVAILABLE",
                "Echo installation requires a running root-managed Docker daemon.",
                retryable=True,
            )

    def _workload_echo_health_status(self) -> int | None:
        """Read the unauthenticated Echo liveness status without collecting response data."""

        request = urllib.request.Request(
            WORKLOAD_ECHO_API_URL.rstrip("/") + WORKLOAD_ECHO_HEALTH_PATH,
            method="GET",
            headers={"Accept": "application/json"},
        )
        try:
            with urllib.request.urlopen(request, timeout=3) as response:
                return response.status
        except urllib.error.HTTPError as error:
            return error.code
        except (OSError, urllib.error.URLError, TimeoutError):
            return None

    @staticmethod
    def _workload_hold_echo(transaction: dict[str, Any]) -> dict[str, Any]:
        """Project one active workload maintenance hold for the official package helper."""

        token = transaction.get("maintenanceToken")
        if not isinstance(token, str) or len(token) < 32:
            raise UpdateError(
                "PENDING_MAINTENANCE", "The workload maintenance hold is unavailable."
            )
        return {
            "transaction_id": _maintenance_request_id(transaction),
            "maintenance_token": token,
            "target_kind": transaction["targetKind"],
            "plan_id": transaction["planId"],
            "plan_digest": transaction["planDigest"],
            "component_artifact_digests": dict(transaction["componentArtifactDigests"]),
            "expected_gate_generation": transaction["expectedGateGeneration"],
            "expected_catalog_generation": transaction["expectedCatalogGeneration"],
        }

    def _begin_workload_hold(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        *,
        phase: str,
        target_kind: str,
        requires_restart: bool,
    ) -> None:
        """Acquire one fresh hold for a resumable subphase of the parent workload plan."""

        if phase not in {
            "core-runtime-install",
            "package-only",
            "core-runtime-activate",
            "core-runtime-echo-quiesce",
            "core-runtime-uninstall",
        }:
            raise UpdateError("INVALID_TRANSACTION", "Workload maintenance phase is invalid.")
        if target_kind not in {"CORE_RUNTIME", "PACKAGE_ONLY"}:
            raise UpdateError("INVALID_TRANSACTION", "Workload maintenance target is invalid.")
        transaction["maintenancePhase"] = phase
        transaction.pop("maintenanceRequestId", None)
        transaction["targetKind"] = target_kind
        transaction["requiresRestart"] = requires_restart
        activity_catalog, activity_sources = self._activity_catalog()
        readiness = self._readiness_for(target_kind, requires_restart=requires_restart, force=True)
        self._require_ready(readiness, target_kind)
        if readiness.get("install_catalog_generation") != activity_catalog["generation"]:
            raise UpdateError(
                "GATE_UNKNOWN",
                "Activity source generation changed during workload readiness.",
                retryable=True,
            )
        gate_generation = readiness.get("gate_generation")
        if type(gate_generation) is not int or gate_generation < 1:
            raise UpdateError(
                "GATE_UNKNOWN", "Maintenance gate generation is unknown.", retryable=True
            )
        transaction["expectedGateGeneration"] = gate_generation
        transaction["expectedCatalogGeneration"] = activity_catalog["generation"]
        transaction["expectedActivitySources"] = activity_sources
        transaction["phase"] = "begin_pending"
        holds = transaction.setdefault("maintenanceHolds", {})
        if not isinstance(holds, dict):
            raise UpdateError("INVALID_TRANSACTION", "Workload hold journal is malformed.")
        request_id = _maintenance_request_id(transaction)
        prior = holds.get(phase)
        if (
            isinstance(prior, dict)
            and prior.get("requestId") == request_id
            and prior.get("status") == "ended"
        ):
            raise UpdateError(
                "TRANSACTION_PHASE_REPLAY",
                "A completed maintenance subphase cannot reuse its request ID.",
            )
        holds[phase] = {
            "requestId": request_id,
            "targetKind": target_kind,
            "expectedGateGeneration": gate_generation,
            "expectedCatalogGeneration": activity_catalog["generation"],
            "componentArtifactDigests": dict(transaction["componentArtifactDigests"]),
            "status": "begin_pending",
        }
        _atomic_json(transaction_path, transaction)
        try:
            token = self._begin_maintenance(transaction)
        except UpdateError as error:
            if error.maintenance_not_acquired:
                holds[phase]["status"] = "not_acquired"
                transaction["phase"] = "applying"
                transaction.pop("maintenanceRequestId", None)
                _atomic_json(transaction_path, transaction)
            raise
        transaction["maintenanceToken"] = token
        transaction["phase"] = "applying"
        holds[phase]["status"] = "active"
        holds[phase]["acquiredAt"] = int(time.time())
        _atomic_json(transaction_path, transaction)

    def _end_workload_hold(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        *,
        outcome: str,
        healthy: bool,
    ) -> None:
        """Close the current hold and persist its exact phase receipt in the parent journal."""

        phase = transaction.get("maintenancePhase")
        holds = transaction.get("maintenanceHolds")
        if (
            not isinstance(phase, str)
            or not isinstance(holds, dict)
            or not isinstance(holds.get(phase), dict)
        ):
            raise UpdateError(
                "INVALID_TRANSACTION", "Workload hold journal omits its phase identity."
            )
        hold = holds[phase]
        hold["status"] = "end_pending"
        hold["outcome"] = outcome
        hold["healthy"] = healthy
        _atomic_json(transaction_path, transaction)
        self._end_maintenance(transaction, outcome=outcome, healthy=healthy)
        hold["status"] = "ended"
        hold["endedAt"] = int(time.time())
        transaction.pop("maintenanceToken", None)
        transaction.pop("maintenanceRequestId", None)
        transaction["phase"] = "applying"
        _atomic_json(transaction_path, transaction)

    @staticmethod
    def _journal_callback(
        transaction: dict[str, Any], transaction_path: Path, key: str
    ) -> Callable[[Mapping[str, Any]], None]:
        """Build a helper callback that durably records one root-private event."""

        def persist(event: Mapping[str, Any]) -> None:
            if not isinstance(event, Mapping):
                raise UpdateError("INVALID_TRANSACTION", "A workload callback is malformed.")
            try:
                safe_event = json.loads(json.dumps(dict(event), allow_nan=False))
            except (TypeError, ValueError) as error:
                raise UpdateError(
                    "INVALID_TRANSACTION", "A workload callback is not JSON-safe."
                ) from error
            events = transaction.setdefault(key, [])
            if not isinstance(events, list):
                raise UpdateError("INVALID_TRANSACTION", "Workload callback journal is malformed.")
            events.append(safe_event)
            _atomic_json(transaction_path, transaction)

        return persist

    def _write_workload_activity_generation(
        self, generation: int, *, previous_generation: int | None
    ) -> None:
        """Atomically project the committed broker generation to Product units."""

        if type(generation) is not int or generation < 1:
            raise UpdateError(
                "CATALOG_GENERATION_MISMATCH", "Activity catalog generation is invalid."
            )
        path = DEFAULT_PACKAGE_ACTIVITY_ENVIRONMENT
        expected = f"CYRENE_RUNTIME_ACTIVITY_CATALOG_GENERATION={generation}\n".encode("ascii")
        previous = (
            f"CYRENE_RUNTIME_ACTIVITY_CATALOG_GENERATION={previous_generation}\n".encode("ascii")
            if type(previous_generation) is int and previous_generation >= 1
            else None
        )
        current: bytes | None = None
        if path.exists() or path.is_symlink():
            descriptor: int | None = None
            try:
                before = path.lstat()
                descriptor = os.open(
                    path,
                    os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0),
                )
                info = os.fstat(descriptor)
                if (
                    path.is_symlink()
                    or not stat.S_ISREG(info.st_mode)
                    or info.st_uid != 0
                    or info.st_gid != 0
                    or stat.S_IMODE(info.st_mode) != 0o644
                    or info.st_nlink != 1
                    or info.st_dev != before.st_dev
                    or info.st_ino != before.st_ino
                    or info.st_size > 4096
                ):
                    raise UpdateError(
                        "PRODUCT_ENVIRONMENT_UNKNOWN", "Product activity generation file is unsafe."
                    )
                current = os.read(descriptor, 4097)
            except OSError as error:
                raise UpdateError(
                    "PRODUCT_ENVIRONMENT_UNKNOWN",
                    "Product activity generation file is unavailable.",
                ) from error
            finally:
                if descriptor is not None:
                    os.close(descriptor)
        if current == expected:
            return
        if current != previous and not (current is None and previous_generation in {None, 0}):
            raise UpdateError(
                "PRODUCT_ENVIRONMENT_UNKNOWN",
                "Product activity generation changed outside the workload transaction.",
                retryable=True,
            )
        path.parent.mkdir(mode=0o755, parents=True, exist_ok=True)
        temporary = path.parent / f".{path.name}.{uuid.uuid4().hex}.tmp"
        descriptor: int | None = None
        try:
            descriptor = os.open(
                temporary,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
                0o644,
            )
            os.fchown(descriptor, 0, 0)
            os.fchmod(descriptor, 0o644)
            with os.fdopen(descriptor, "wb") as stream:
                descriptor = None
                stream.write(expected)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, path)
            self._fsync_directory(path.parent)
        except OSError as error:
            raise UpdateError(
                "PRODUCT_ENVIRONMENT_UNKNOWN", "Product activity generation cannot be updated."
            ) from error
        finally:
            if descriptor is not None:
                os.close(descriptor)
            temporary.unlink(missing_ok=True)

    def _workload_source_state(
        self, workload_id: str
    ) -> tuple[dict[str, Any], dict[str, Any] | None, dict[str, dict[str, Any]], Any]:
        """Read the current Broker and Package Runtime owner state for one workload."""

        helper = self._load_workload_package_runtime()
        workload = next(
            (
                row
                for row in self.catalog.get("workloads", [])
                if isinstance(row, dict) and row.get("workloadId") == workload_id
            ),
            None,
        )
        policy = workload.get("sourcePolicy") if isinstance(workload, dict) else None
        if not isinstance(policy, dict):
            raise UpdateError(
                "SOURCE_POLICY_INVALID", "Signed workload sourcePolicy is unavailable."
            )
        activity_catalog, _activity_sources = self._activity_catalog()
        principals = self._workload_source_principals(policy, activity_catalog)
        runtime_policy: dict[str, Any] | None = None
        if DEFAULT_PACKAGE_RUNTIME_POLICY.exists() or DEFAULT_PACKAGE_RUNTIME_POLICY.is_symlink():
            if DEFAULT_PACKAGE_RUNTIME_POLICY.is_symlink():
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "Package Runtime source policy is an unsafe symlink.",
                    retryable=True,
                )
            try:
                runtime_policy = helper.read_runtime_source_policy_generic(
                    DEFAULT_PACKAGE_RUNTIME_POLICY
                )
            except Exception as error:
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "Package Runtime source policy cannot be read safely.",
                    retryable=True,
                ) from error
        elif activity_catalog.get("sources"):
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Activity owners exist without their authenticated Package Runtime policy.",
                retryable=True,
            )
        return activity_catalog, runtime_policy, principals, helper

    def _update_workload_source_policy(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        *,
        source_policy: dict[str, Any],
        selected_rows: list[dict[str, Any]],
        installation_records: dict[str, dict[str, Any]],
        phase: str,
        remove_component_ids: tuple[str, ...] = (),
    ) -> dict[str, Any]:
        """Update Broker/runtime owner scopes under the caller's current hold."""

        intents = transaction.get("sourceUpdateIntents")
        if "sourceUpdateIntents" in transaction and not isinstance(intents, dict):
            raise UpdateError("INVALID_TRANSACTION", "Workload source-update history is malformed.")
        intent = (
            intents.get(phase)
            if isinstance(intents, dict)
            else transaction.get("sourceUpdateIntent")
        )
        if isinstance(intent, dict) and intent.get("phase") == phase:
            reconciled = self._reconcile_workload_source_policy_intent(
                transaction, transaction_path, phase=phase
            )
            if reconciled is not None:
                return reconciled

        activity_catalog, runtime_policy, principals, helper = self._workload_source_state(
            transaction["workloadId"]
        )
        try:
            update = helper.build_workload_source_update(
                source_policy=source_policy,
                selected_rows=selected_rows,
                installation_records=installation_records,
                activity_catalog=activity_catalog,
                source_principals=principals,
                runtime_policy=runtime_policy,
                remove_component_ids=remove_component_ids,
            )
            prior_generation = activity_catalog["generation"]
            request_id = (
                "cyrene-wsource-" + phase + "-" + transaction["planId"].removeprefix("plan-")
            )
            intent_value = {
                "schemaVersion": 1,
                "phase": phase,
                "requestId": request_id,
                "previousCatalogGeneration": prior_generation,
                "expectedCatalogGeneration": update.expected_generation,
                "previousPolicyDigest": update.previous_policy_digest,
                "bindingScopes": update.binding_scopes,
                "sourceIdentity": update.source_identity,
                "sourceArguments": list(update.source_arguments),
                "runtimeBindings": update.runtime_bindings,
                "changed": update.changed,
                "selectedBindings": list(update.selected_binding_ids),
                "componentArtifactDigests": update.component_artifact_digests,
                "requiredHoldComponentIds": list(update.required_hold_component_ids),
                "parentPlanId": transaction["planId"],
                "parentPlanDigest": transaction["planDigest"],
            }
            if isinstance(intent, dict) and intent.get("phase") == phase:
                identity_fields = (
                    "phase",
                    "requestId",
                    "previousCatalogGeneration",
                    "expectedCatalogGeneration",
                    "previousPolicyDigest",
                    "bindingScopes",
                    "sourceIdentity",
                    "sourceArguments",
                    "runtimeBindings",
                    "changed",
                    "selectedBindings",
                    "componentArtifactDigests",
                    "requiredHoldComponentIds",
                    "parentPlanId",
                    "parentPlanDigest",
                )
                if any(intent.get(field) != intent_value.get(field) for field in identity_fields):
                    raise UpdateError(
                        "INVALID_TRANSACTION",
                        "Workload source-update retry changed its durable desired state.",
                    )
            else:
                source_intents = transaction.setdefault("sourceUpdateIntents", {})
                if not isinstance(source_intents, dict):
                    raise UpdateError(
                        "INVALID_TRANSACTION", "Workload source-update history is malformed."
                    )
                source_intents[phase] = intent_value
                transaction["sourceUpdateIntent"] = intent_value
                _atomic_json(transaction_path, transaction)
            update_result = helper.apply_workload_source_update(
                update,
                maintenance=self._workload_hold_echo(transaction),
                request_id=request_id,
                expected_policy_digest=update.previous_policy_digest,
                activity_catalog_path=self.activity_catalog_path,
                policy_path=DEFAULT_PACKAGE_RUNTIME_POLICY,
                token_directory=DEFAULT_ACTIVITY_TOKEN_DIRECTORY,
                runner=self.runner,
            )
        except Exception as error:
            if isinstance(error, UpdateError):
                raise
            raise UpdateError(
                "PACKAGE_RUNTIME_POLICY_UPDATE_FAILED",
                "The held Broker and Package Runtime owner policy update did not complete.",
                retryable=True,
            ) from error
        generation = update_result.get("catalogGeneration")
        if type(generation) is not int or generation < 1:
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Broker did not return a valid committed source generation.",
                retryable=True,
            )
        self._write_workload_activity_generation(
            generation,
            previous_generation=prior_generation if prior_generation >= 1 else None,
        )
        transaction["sourceUpdate"] = update_result
        source_updates = transaction.setdefault("sourceUpdates", {})
        if not isinstance(source_updates, dict):
            raise UpdateError(
                "INVALID_TRANSACTION", "Workload source-update receipts are malformed."
            )
        source_updates[phase] = update_result
        transaction["activityCatalogGeneration"] = generation
        source_intents = transaction.setdefault("sourceUpdateIntents", {})
        if not isinstance(source_intents, dict):
            raise UpdateError("INVALID_TRANSACTION", "Workload source-update history is malformed.")
        committed_intent = source_intents.get(phase)
        if not isinstance(committed_intent, dict):
            committed_intent = transaction.get("sourceUpdateIntent")
        if not isinstance(committed_intent, dict) or committed_intent.get("phase") != phase:
            raise UpdateError("INVALID_TRANSACTION", "Workload source-update intent disappeared.")
        committed_intent["committed"] = True
        committed_intent["result"] = update_result
        source_intents[phase] = committed_intent
        transaction["sourceUpdateIntent"] = committed_intent
        _atomic_json(transaction_path, transaction)
        return update_result

    def _reconcile_workload_source_policy_intent(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        *,
        phase: str,
    ) -> dict[str, Any] | None:
        """Finish a Broker-committed policy projection from its durable intent."""

        intents = transaction.get("sourceUpdateIntents")
        if "sourceUpdateIntents" in transaction and not isinstance(intents, dict):
            raise UpdateError("INVALID_TRANSACTION", "Workload source-update history is malformed.")
        intent = (
            intents.get(phase)
            if isinstance(intents, dict)
            else transaction.get("sourceUpdateIntent")
        )
        if not isinstance(intent, dict) or intent.get("phase") != phase:
            return None
        if intent.get("committed") is True and isinstance(intent.get("result"), dict):
            self._workload_hold_echo(transaction)
            result = intent["result"]
            if result.get("catalogGeneration") != intent.get(
                "expectedCatalogGeneration"
            ) or result.get("policyGeneration") != intent.get("expectedCatalogGeneration"):
                raise UpdateError(
                    "INVALID_TRANSACTION", "Committed source-update receipt is inconsistent."
                )
            return result
        if (
            intent.get("parentPlanId") != transaction.get("planId")
            or intent.get("parentPlanDigest") != transaction.get("planDigest")
            or not isinstance(intent.get("bindingScopes"), dict)
            or not isinstance(intent.get("sourceIdentity"), dict)
            or not isinstance(intent.get("sourceArguments"), list)
            or not isinstance(intent.get("runtimeBindings"), dict)
            or type(intent.get("changed")) is not bool
            or not isinstance(intent.get("selectedBindings"), list)
            or not isinstance(intent.get("componentArtifactDigests"), dict)
            or not isinstance(intent.get("requiredHoldComponentIds"), list)
        ):
            raise UpdateError("INVALID_TRANSACTION", "Workload source-update intent is malformed.")
        if (
            not isinstance(transaction.get("maintenanceToken"), str)
            or not transaction["maintenanceToken"]
        ):
            return None
        self._workload_hold_echo(transaction)
        helper = self._load_workload_package_runtime()
        expected_generation = intent.get("expectedCatalogGeneration")
        previous_generation = intent.get("previousCatalogGeneration")
        if (
            type(expected_generation) is not int
            or type(previous_generation) is not int
            or expected_generation < 1
            or previous_generation < 0
            or expected_generation != previous_generation + (1 if intent["changed"] else 0)
        ):
            raise UpdateError(
                "INVALID_TRANSACTION", "Workload source-update generation is malformed."
            )
        update = helper.WorkloadSourceUpdate(
            source_arguments=tuple(intent["sourceArguments"]),
            binding_scopes=intent["bindingScopes"],
            source_identity=intent["sourceIdentity"],
            runtime_bindings=intent["runtimeBindings"],
            expected_generation=expected_generation,
            changed=intent["changed"],
            previous_policy_digest=intent.get("previousPolicyDigest"),
            selected_binding_ids=tuple(intent["selectedBindings"]),
            component_artifact_digests=intent["componentArtifactDigests"],
            required_hold_component_ids=tuple(intent["requiredHoldComponentIds"]),
        )
        try:
            update_result = helper.reconcile_workload_source_update(
                update,
                maintenance=self._workload_hold_echo(transaction),
                activity_catalog_path=self.activity_catalog_path,
                policy_path=DEFAULT_PACKAGE_RUNTIME_POLICY,
                token_directory=DEFAULT_ACTIVITY_TOKEN_DIRECTORY,
            )
        except Exception as error:
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Broker source update cannot be reconciled against its durable intent.",
                retryable=True,
            ) from error
        if update_result is None:
            return None
        generation = update_result.get("catalogGeneration")
        if type(generation) is not int or generation != expected_generation:
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Reconciled Broker source generation differs from the durable intent.",
                retryable=True,
            )
        self._write_workload_activity_generation(
            generation,
            previous_generation=previous_generation if previous_generation >= 1 else None,
        )
        transaction["sourceUpdate"] = update_result
        source_updates = transaction.setdefault("sourceUpdates", {})
        if not isinstance(source_updates, dict):
            raise UpdateError(
                "INVALID_TRANSACTION", "Workload source-update receipts are malformed."
            )
        source_updates[phase] = update_result
        transaction["activityCatalogGeneration"] = generation
        intent["committed"] = True
        intent["result"] = update_result
        transaction["sourceUpdateIntent"] = intent
        transaction["sourceUpdateIntents"] = transaction.setdefault("sourceUpdateIntents", {})
        transaction["sourceUpdateIntents"][phase] = intent
        _atomic_json(transaction_path, transaction)
        return update_result

    def _workload_service_units(
        self,
        rows: list[dict[str, Any]],
        source_policy: dict[str, Any],
        candidate_items: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        """Resolve only selected signed Product/service units for this workload."""

        component_ids = {row.get("componentId") for row in rows if isinstance(row, dict)}
        if source_policy.get("mode") == "actualProduct":
            component_ids.update(source_policy.get("productComponentIds", []))
        candidate_by_id = {
            item.get("componentId"): item
            for item in candidate_items
            if isinstance(item, dict) and isinstance(item.get("componentId"), str)
        }
        services: dict[str, dict[str, Any]] = {}
        for component_id in sorted(value for value in component_ids if isinstance(value, str)):
            component = self.components.get(component_id)
            if not isinstance(component, dict):
                continue
            unit = component.get("systemdUnit")
            restart = component.get("restart")
            if not isinstance(unit, str) or not isinstance(restart, dict):
                continue
            if restart.get("group") not in {"core-runtime", "single-service"}:
                continue
            if self._catalog_matched_unit(component) != unit:
                raise UpdateError(
                    "SERVICE_NOT_MANAGED",
                    f"{component_id} has no catalog-matched local systemd service.",
                    retryable=True,
                )
            try:
                self._workload_signed_unit_bytes(component, candidate_by_id.get(component_id))
            except UpdateError:
                raise
            except Exception as error:
                raise UpdateError(
                    "SERVICE_NOT_MANAGED",
                    f"{component_id} has no verified unit in its active or staged release.",
                    retryable=True,
                ) from error
            services[unit] = {
                "componentId": component_id,
                "unit": unit,
                "order": restart.get("order", 0),
                "restartGroup": restart.get("group"),
                "candidate": candidate_by_id.get(component_id),
            }
        return sorted(services.values(), key=lambda item: (item["order"], item["componentId"]))

    def _workload_signed_unit_bytes(
        self, component: dict[str, Any], candidate: dict[str, Any] | None
    ) -> tuple[bytes, Path, str]:
        """Read a service unit only from the exact active or staged signed release."""

        component_id = component.get("componentId")
        unit = component.get("systemdUnit")
        if not isinstance(component_id, str) or not isinstance(unit, str):
            raise UpdateError("SERVICE_NOT_MANAGED", "Catalog service identity is incomplete.")
        if candidate is not None:
            manifest = candidate.get("manifest")
            release_path = Path(candidate.get("releasePath", ""))
        else:
            pointer = self._active_native_pointer_identity(component_id)
            if pointer is None:
                raise UpdateError(
                    "SERVICE_NOT_MANAGED",
                    f"{component_id} has no active signed release for its service unit.",
                )
            release_path = self.install_root / "components" / component_id / "releases" / pointer
            receipt = self._read_active_receipt(component_id)
            manifest = receipt.get("manifest") if isinstance(receipt, dict) else None
        relative = f"systemd/{unit}"
        files = (
            manifest.get("artifact", {}).get("files")
            if isinstance(manifest, dict) and isinstance(manifest.get("artifact"), dict)
            else None
        )
        expected_digest = files.get(relative) if isinstance(files, dict) else None
        if (
            not isinstance(manifest, dict)
            or manifest.get("componentId") != component_id
            or not _valid_digest(manifest.get("manifestDigest"))
            or not _valid_digest(expected_digest)
            or release_path.is_symlink()
            or not release_path.is_dir()
        ):
            raise UpdateError(
                "SERVICE_NOT_MANAGED", f"{component_id} release does not attest its unit file."
            )
        self._validate_manifest_digest(manifest, manifest["manifestDigest"])
        source = release_path / relative
        try:
            info = source.lstat()
            payload = source.read_bytes()
        except OSError as error:
            raise UpdateError(
                "SERVICE_NOT_MANAGED", f"Signed service unit is unavailable for {component_id}."
            ) from error
        if (
            stat.S_ISLNK(info.st_mode)
            or not stat.S_ISREG(info.st_mode)
            or info.st_uid != 0
            or info.st_nlink != 1
            or hashlib.sha256(payload).hexdigest() != expected_digest.removeprefix("sha256:")
            or not self._unit_uses_component_runner(source, component_id)
        ):
            raise UpdateError(
                "SERVICE_NOT_MANAGED", f"Signed service unit identity differs for {component_id}."
            )
        if component_id == "cyrene-client-workspace-control":
            try:
                lines = [line.strip() for line in payload.decode("utf-8").splitlines()]
            except UnicodeDecodeError as error:
                raise UpdateError(
                    "SERVICE_NOT_MANAGED", "Workspace Control unit is not UTF-8."
                ) from error
            required_lines = {
                "User=cyrene",
                "Group=cyrene",
                "WorkingDirectory=/var/lib/cyrene/studio-control",
                "Environment=STUDIO_MODE=local",
                "Environment=STUDIO_CONTROL_HOST=127.0.0.1",
                "Environment=STUDIO_CONTROL_PORT=5182",
                "Environment=STUDIO_CONTROL_DATA_DIR=/var/lib/cyrene/studio-control",
                "Environment=STUDIO_PUBLIC_ORIGINS=http://127.0.0.1:8100,http://localhost:8100",
                "EnvironmentFile=-/etc/cyrene/studio-control.env",
                "ExecStart=/usr/bin/cyrene component-run cyrene-client-workspace-control",
                "ReadWritePaths=/var/lib/cyrene/studio-control",
            }
            if not required_lines.issubset(lines):
                raise UpdateError(
                    "SERVICE_NOT_MANAGED",
                    "Workspace Control unit differs from the signed local-only service contract.",
                )
        return payload, source, "sha256:" + hashlib.sha256(payload).hexdigest()

    def _install_workload_service_units(
        self, transaction: dict[str, Any], services: list[dict[str, Any]]
    ) -> None:
        """Install signed service units atomically while the exact core hold is active."""

        if services and not self.systemd_unit_dirs:
            raise UpdateError(
                "SERVICE_NOT_MANAGED", "No root-controlled systemd unit directory is configured."
            )
        changes: list[dict[str, Any]] = transaction.setdefault("unitFileChanges", [])
        changed = False
        for service in services:
            unit = service["unit"]
            component = self.components[service["componentId"]]
            candidate = service.get("candidate")
            candidate_bytes, _source, candidate_digest = self._workload_signed_unit_bytes(
                component, candidate
            )
            prior_pointer = self._active_native_pointer_identity(service["componentId"])
            prior_bytes = None
            prior_digest = None
            if prior_pointer is not None and candidate is not None:
                _old_bytes, _old_source, prior_digest = self._workload_signed_unit_bytes(
                    component, None
                )
                prior_bytes = _old_bytes
            existing_paths: list[tuple[Path, bytes]] = []
            for directory in self.systemd_unit_dirs:
                path = Path(directory) / unit
                if not path.exists() and not path.is_symlink():
                    continue
                try:
                    info = path.lstat()
                    payload = path.read_bytes()
                except OSError as error:
                    raise UpdateError(
                        "SERVICE_NOT_MANAGED", f"Cannot inspect existing unit {unit}."
                    ) from error
                allowed_digests = {candidate_digest}
                if prior_digest is not None:
                    allowed_digests.add(prior_digest)
                if (
                    stat.S_ISLNK(info.st_mode)
                    or not stat.S_ISREG(info.st_mode)
                    or info.st_uid != 0
                    or info.st_nlink != 1
                    or stat.S_IMODE(info.st_mode) & 0o022
                    or "sha256:" + hashlib.sha256(payload).hexdigest() not in allowed_digests
                ):
                    raise UpdateError(
                        "SERVICE_UNIT_CONFLICT",
                        f"Existing {unit} is not owned by its active or staged signed release.",
                    )
                existing_paths.append((path, payload))
            destination = Path(self.systemd_unit_dirs[0]) / unit
            current = next(
                (payload for path, payload in existing_paths if path == destination), None
            )
            if current == candidate_bytes:
                continue
            if current is not None and (prior_bytes is None or current != prior_bytes):
                raise UpdateError(
                    "SERVICE_UNIT_CONFLICT", f"Existing {unit} changed outside the active release."
                )
            self._verify_root_path_chain(destination.parent)
            destination.parent.mkdir(mode=0o755, parents=True, exist_ok=True)
            prior_info = (
                destination.lstat() if destination.exists() or destination.is_symlink() else None
            )
            changes.append(
                {
                    "path": str(destination),
                    "priorBytes": base64.b64encode(current).decode("ascii")
                    if current is not None
                    else None,
                    "priorMode": stat.S_IMODE(prior_info.st_mode)
                    if prior_info is not None
                    else None,
                    "priorDigest": (
                        "sha256:" + hashlib.sha256(current).hexdigest()
                        if current is not None
                        else None
                    ),
                    "writtenDigest": candidate_digest,
                }
            )
            temporary = destination.with_name(f".{destination.name}.{uuid.uuid4().hex}.tmp")
            descriptor: int | None = None
            try:
                descriptor = os.open(
                    temporary,
                    os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
                    0o644,
                )
                os.fchown(descriptor, 0, 0)
                os.fchmod(descriptor, 0o644)
                with os.fdopen(descriptor, "wb") as stream:
                    descriptor = None
                    stream.write(candidate_bytes)
                    stream.flush()
                    os.fsync(stream.fileno())
                os.replace(temporary, destination)
                self._fsync_directory(destination.parent)
            except OSError as error:
                raise UpdateError(
                    "SERVICE_UNIT_INSTALL_FAILED", f"Cannot install signed {unit}."
                ) from error
            finally:
                if descriptor is not None:
                    os.close(descriptor)
                temporary.unlink(missing_ok=True)
            changed = True
            _atomic_json(self._workload_transaction_path(transaction), transaction)
        if changed:
            self._daemon_reload()

    def _read_workload_protected_file(
        self,
        path: Path,
        *,
        allowed_identities: set[tuple[int, int, int]],
        maximum_bytes: int,
        error_code: str = "CATALYST_AUTH_CONFIGURATION_CONFLICT",
    ) -> bytes | None:
        """Read a bounded root-controlled file without following its final path."""

        try:
            before = path.lstat()
        except FileNotFoundError:
            return None
        except OSError as error:
            raise UpdateError(
                error_code, "A Catalyst authentication file cannot be inspected."
            ) from error
        try:
            self._verify_root_path_chain(path.parent)
            descriptor = os.open(
                path,
                os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0),
            )
            try:
                info = os.fstat(descriptor)
                identity = (info.st_uid, info.st_gid, stat.S_IMODE(info.st_mode))
                if (
                    path.is_symlink()
                    or not stat.S_ISREG(info.st_mode)
                    or info.st_nlink != 1
                    or identity not in allowed_identities
                    or info.st_size > maximum_bytes
                    or (info.st_dev, info.st_ino) != (before.st_dev, before.st_ino)
                ):
                    raise UpdateError(
                        error_code, "A Catalyst authentication file has unsafe ownership or mode."
                    )
                content = os.read(descriptor, maximum_bytes + 1)
                if len(content) > maximum_bytes:
                    raise UpdateError(
                        error_code, "A Catalyst authentication file exceeds its size limit."
                    )
                return content
            finally:
                os.close(descriptor)
        except UpdateError:
            raise
        except OSError as error:
            raise UpdateError(
                error_code, "A Catalyst authentication file cannot be read safely."
            ) from error

    @staticmethod
    def _validate_workload_api_token(value: str) -> str:
        """Validate one printable bearer without retaining it in a transaction record."""

        try:
            encoded = value.encode("ascii")
        except UnicodeEncodeError as error:
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT", "Catalyst API token is not printable ASCII."
            ) from error
        if len(encoded) < 32 or any(byte < 33 or byte > 126 for byte in encoded):
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                "Catalyst API token is not a valid high-entropy value.",
            )
        return value

    @staticmethod
    def _parse_workload_environment_file(
        content: bytes, *, expected_keys: set[str], maximum_lines: int
    ) -> dict[str, str]:
        """Parse the intentionally small systemd EnvironmentFile projection."""

        try:
            lines = content.decode("ascii").splitlines()
        except UnicodeDecodeError as error:
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT", "Catalyst environment file is not ASCII."
            ) from error
        if len(lines) > maximum_lines:
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                "Catalyst environment file has too many entries.",
            )
        result: dict[str, str] = {}
        for line in lines:
            if not line or "=" not in line:
                raise UpdateError(
                    "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                    "Catalyst environment file syntax is invalid.",
                )
            key, value = line.split("=", 1)
            if key not in expected_keys or key in result or not value or value != value.strip():
                raise UpdateError(
                    "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                    "Catalyst environment file fields are invalid.",
                )
            result[key] = value
        if set(result) != expected_keys:
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT", "Catalyst environment file is incomplete."
            )
        return result

    def _check_workload_catalyst_auth_conflicts(self, group_id: int) -> None:
        """Reject unmanaged Catalyst bearer sources before acquiring maintenance."""

        general_environment = self._read_workload_protected_file(
            Path("/etc/cyrene/cyrene.env"),
            allowed_identities={(0, 0, 0o644), (0, group_id, 0o640)},
            maximum_bytes=16384,
        )
        if general_environment is not None:
            try:
                lines = general_environment.decode("utf-8").splitlines()
            except UnicodeDecodeError as error:
                raise UpdateError(
                    "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                    "The existing Cyrene environment file cannot be inspected safely.",
                ) from error
            if any(
                line.strip().startswith("CYRENE_DATA_TOOLS_TOKEN=")
                or "CYRENE_DATA_TOOLS_TOKEN" in line
                for line in lines
                if line.strip() and not line.lstrip().startswith("#")
            ):
                raise UpdateError(
                    "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                    "Catalyst bearer is configured in the world-readable general environment file; move it to a protected token file before installing.",
                )

        expected_dropin = (
            "[Service]\nEnvironmentFile=" + str(DEFAULT_CATALYST_AUTH_ENVIRONMENT) + "\n"
        ).encode("ascii")
        known_dropin_dirs = (
            Path("/etc/systemd/system/cyrene-catalyst.service.d"),
            Path("/run/systemd/system/cyrene-catalyst.service.d"),
            Path("/usr/local/lib/systemd/system/cyrene-catalyst.service.d"),
            Path("/usr/lib/systemd/system/cyrene-catalyst.service.d"),
        )
        for directory in known_dropin_dirs:
            if not directory.exists() and not directory.is_symlink():
                continue
            try:
                info = directory.lstat()
                self._verify_root_path_chain(directory.parent)
                if (
                    stat.S_ISLNK(info.st_mode)
                    or not stat.S_ISDIR(info.st_mode)
                    or info.st_uid != 0
                    or info.st_gid != 0
                    or stat.S_IMODE(info.st_mode) & 0o022
                ):
                    raise UpdateError(
                        "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                        "A Catalyst unit drop-in directory has unsafe ownership or mode.",
                    )
                files = sorted(directory.glob("*.conf"))
            except UpdateError:
                raise
            except OSError as error:
                raise UpdateError(
                    "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                    "Catalyst unit drop-ins cannot be enumerated safely.",
                ) from error
            for path in files:
                if path == DEFAULT_CATALYST_AUTH_DROPIN:
                    content = self._read_workload_protected_file(
                        path,
                        allowed_identities={(0, 0, 0o644)},
                        maximum_bytes=4096,
                    )
                    if content != expected_dropin:
                        raise UpdateError(
                            "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                            "The managed Catalyst authentication drop-in differs from its fixed contract.",
                        )
                    continue
                content = self._read_workload_protected_file(
                    path,
                    allowed_identities={(0, 0, 0o600), (0, 0, 0o644)},
                    maximum_bytes=16384,
                )
                if content is None:
                    continue
                try:
                    lines = content.decode("utf-8").splitlines()
                except UnicodeDecodeError as error:
                    raise UpdateError(
                        "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                        "An unmanaged Catalyst unit drop-in cannot be inspected safely.",
                    ) from error
                if any(
                    line.strip().partition("=")[0].strip() in {"Environment", "EnvironmentFile"}
                    for line in lines
                    if line.strip() and not line.lstrip().startswith("#")
                ):
                    raise UpdateError(
                        "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                        "An unmanaged Catalyst unit drop-in supplies environment values; refusing an ambiguous bearer configuration.",
                    )

    def _workload_catalyst_token_configuration(
        self, *, generate: bool
    ) -> tuple[str, Path, int] | None:
        """Resolve one stable bearer from protected host state or generate it once."""

        try:
            group_id = grp.getgrnam("cyrene").gr_gid
            user_id = pwd.getpwnam("cyrene").pw_uid
        except KeyError as error:
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                "The cyrene service identity is unavailable.",
            ) from error
        self._check_workload_catalyst_auth_conflicts(group_id)
        protected_modes = {(0, group_id, 0o640), (user_id, group_id, 0o600)}
        token_paths: list[Path] = [DEFAULT_CATALYST_API_TOKEN]
        control_bytes = self._read_workload_protected_file(
            DEFAULT_STUDIO_CONTROL_ENVIRONMENT,
            allowed_identities={(0, group_id, 0o640)},
            maximum_bytes=4096,
        )
        if control_bytes is not None:
            control = self._parse_workload_environment_file(
                control_bytes,
                expected_keys={"STUDIO_CATALYST_URL", "STUDIO_CATALYST_API_TOKEN_FILE"},
                maximum_lines=2,
            )
            if control["STUDIO_CATALYST_URL"] != CATALYST_API_ORIGIN:
                raise UpdateError(
                    "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                    "Existing Studio Control points at a different Catalyst origin.",
                )
            configured_path = Path(control["STUDIO_CATALYST_API_TOKEN_FILE"])
            if (
                not configured_path.is_absolute()
                or ".." in configured_path.parts
                or configured_path.parent != Path("/etc/cyrene/secrets")
            ):
                raise UpdateError(
                    "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                    "Existing Studio Control token path is outside the protected secret directory.",
                )
            token_paths.insert(0, configured_path)

        configured_values: list[str] = []
        selected_token_path = token_paths[0]
        seen_paths: set[Path] = set()
        for token_path in token_paths:
            if token_path in seen_paths:
                continue
            seen_paths.add(token_path)
            token_bytes = self._read_workload_protected_file(
                token_path,
                allowed_identities=protected_modes,
                maximum_bytes=4096,
            )
            if token_bytes is not None:
                try:
                    value = token_bytes.rstrip(b"\r\n").decode("ascii")
                except UnicodeDecodeError as error:
                    raise UpdateError(
                        "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                        "Catalyst API token file is not ASCII.",
                    ) from error
                configured_values.append(self._validate_workload_api_token(value))

        auth_bytes = self._read_workload_protected_file(
            DEFAULT_CATALYST_AUTH_ENVIRONMENT,
            allowed_identities={(0, group_id, 0o640)},
            maximum_bytes=4096,
        )
        if auth_bytes is not None:
            auth = self._parse_workload_environment_file(
                auth_bytes,
                expected_keys={"CYRENE_DATA_TOOLS_TOKEN"},
                maximum_lines=1,
            )
            configured_values.append(
                self._validate_workload_api_token(auth["CYRENE_DATA_TOOLS_TOKEN"])
            )

        explicit_token = os.environ.get("CYRENE_DATA_TOOLS_TOKEN")
        if explicit_token:
            configured_values.append(self._validate_workload_api_token(explicit_token))
        if configured_values and any(
            value != configured_values[0] for value in configured_values[1:]
        ):
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                "Existing Catalyst bearer sources disagree; refusing to rotate or overwrite them.",
            )
        if configured_values:
            return configured_values[0], selected_token_path, group_id
        if not generate:
            return None
        return secrets.token_urlsafe(48), selected_token_path, group_id

    def _workload_catalyst_auth_is_configured(self) -> bool:
        """Return whether all fixed Catalyst and Control credential projections match."""

        selected = self._workload_catalyst_token_configuration(generate=False)
        if selected is None:
            return False
        token, token_path, group_id = selected
        token_bytes = self._read_workload_protected_file(
            token_path,
            allowed_identities={
                (0, group_id, 0o640),
                (pwd.getpwnam("cyrene").pw_uid, group_id, 0o600),
            },
            maximum_bytes=4096,
        )
        if token_bytes is None or token_bytes.rstrip(b"\r\n").decode("ascii") != token:
            return False
        auth_bytes = self._read_workload_protected_file(
            DEFAULT_CATALYST_AUTH_ENVIRONMENT,
            allowed_identities={(0, group_id, 0o640)},
            maximum_bytes=4096,
        )
        if auth_bytes is None:
            return False
        auth = self._parse_workload_environment_file(
            auth_bytes,
            expected_keys={"CYRENE_DATA_TOOLS_TOKEN"},
            maximum_lines=1,
        )
        if auth["CYRENE_DATA_TOOLS_TOKEN"] != token:
            return False
        control_bytes = self._read_workload_protected_file(
            DEFAULT_STUDIO_CONTROL_ENVIRONMENT,
            allowed_identities={(0, group_id, 0o640)},
            maximum_bytes=4096,
        )
        if control_bytes is None:
            return False
        control = self._parse_workload_environment_file(
            control_bytes,
            expected_keys={"STUDIO_CATALYST_URL", "STUDIO_CATALYST_API_TOKEN_FILE"},
            maximum_lines=2,
        )
        if control != {
            "STUDIO_CATALYST_URL": CATALYST_API_ORIGIN,
            "STUDIO_CATALYST_API_TOKEN_FILE": str(token_path),
        }:
            return False
        dropin = self._read_workload_protected_file(
            DEFAULT_CATALYST_AUTH_DROPIN,
            allowed_identities={(0, 0, 0o644)},
            maximum_bytes=4096,
        )
        if dropin is None:
            return False
        expected_dropin = (
            "[Service]\nEnvironmentFile=" + str(DEFAULT_CATALYST_AUTH_ENVIRONMENT) + "\n"
        ).encode("ascii")
        return dropin == expected_dropin

    def _ensure_workload_config_directory(self, path: Path, *, group_id: int, mode: int) -> None:
        """Create one fixed root-owned configuration directory with exact access."""

        if path.exists() or path.is_symlink():
            try:
                info = path.lstat()
            except OSError as error:
                raise UpdateError(
                    "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                    "A managed configuration directory cannot be inspected.",
                ) from error
            self._verify_root_path_chain(path.parent)
            if (
                stat.S_ISLNK(info.st_mode)
                or not stat.S_ISDIR(info.st_mode)
                or info.st_uid != 0
                or info.st_gid != group_id
                or stat.S_IMODE(info.st_mode) != mode
            ):
                raise UpdateError(
                    "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                    "A managed configuration directory has unexpected ownership or mode.",
                )
            return
        self._verify_root_path_chain(path.parent)
        try:
            path.mkdir(mode=mode)
            os.chown(path, 0, group_id)
            os.chmod(path, mode)
            self._fsync_directory(path.parent)
        except OSError as error:
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                "A managed configuration directory cannot be created.",
            ) from error

    def _write_workload_managed_config(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        *,
        path: Path,
        content: bytes,
        group_id: int,
        mode: int,
        entry_kind: str,
    ) -> str:
        """Atomically create one exact root-managed file and journal only its digest."""

        existing = self._read_workload_protected_file(
            path,
            allowed_identities=(
                {(0, group_id, mode), (pwd.getpwnam("cyrene").pw_uid, group_id, 0o600)}
                if entry_kind == "catalyst-api-token"
                else {(0, group_id, mode)}
            ),
            maximum_bytes=max(4096, len(content)),
        )
        digest = "sha256:" + hashlib.sha256(content).hexdigest()
        changes = transaction.setdefault("managedConfigFiles", [])
        if not isinstance(changes, list):
            raise UpdateError(
                "INVALID_TRANSACTION", "Managed configuration rollback journal is malformed."
            )
        entry = next(
            (item for item in changes if isinstance(item, dict) and item.get("path") == str(path)),
            None,
        )
        if existing is not None:
            current_digest = "sha256:" + hashlib.sha256(existing).hexdigest()
            if current_digest != digest:
                raise UpdateError(
                    "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                    "An existing managed authentication file differs from this workload identity.",
                )
            if entry is not None and entry.get("writtenDigest") != digest:
                raise UpdateError(
                    "INVALID_TRANSACTION", "Managed configuration retry changed its digest."
                )
            return digest
        if entry is not None and entry.get("writtenDigest") != digest:
            raise UpdateError(
                "INVALID_TRANSACTION", "Managed configuration retry changed its digest."
            )
        if path.parent == DEFAULT_CATALYST_API_TOKEN.parent:
            parent_group, parent_mode = group_id, 0o750
        else:
            parent_group, parent_mode = 0, 0o755
        self._ensure_workload_config_directory(path.parent, group_id=parent_group, mode=parent_mode)
        is_bearer_file = entry_kind == "catalyst-api-token"
        if entry is None and not is_bearer_file:
            entry = {
                "path": str(path),
                "kind": entry_kind,
                "priorDigest": None,
                "writtenDigest": digest,
                "mode": mode,
                "groupId": group_id,
            }
            changes.append(entry)
            _atomic_json(transaction_path, transaction)
        temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
        descriptor: int | None = None
        try:
            descriptor = os.open(
                temporary,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
                mode,
            )
            os.fchown(descriptor, 0, group_id)
            os.fchmod(descriptor, mode)
            with os.fdopen(descriptor, "wb") as stream:
                descriptor = None
                stream.write(content)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, path)
            self._fsync_directory(path.parent)
        except OSError as error:
            raise UpdateError(
                "CATALYST_AUTH_CONFIGURATION_CONFLICT",
                "A managed authentication file cannot be written.",
            ) from error
        finally:
            if descriptor is not None:
                os.close(descriptor)
            temporary.unlink(missing_ok=True)
        if not is_bearer_file:
            _atomic_json(transaction_path, transaction)
        return digest

    def _project_workload_catalyst_auth(
        self, transaction: dict[str, Any], transaction_path: Path
    ) -> dict[str, Any]:
        """Project one stable secret into Catalyst and Control without journaling it."""

        selected = self._workload_catalyst_token_configuration(generate=True)
        assert selected is not None
        token, token_path, group_id = selected
        token_content = (token + "\n").encode("ascii")
        auth_content = f"CYRENE_DATA_TOOLS_TOKEN={token}\n".encode("ascii")
        control_content = (
            f"STUDIO_CATALYST_URL={CATALYST_API_ORIGIN}\n"
            f"STUDIO_CATALYST_API_TOKEN_FILE={token_path}\n"
        ).encode("ascii")
        dropin_content = (
            "[Service]\nEnvironmentFile=" + str(DEFAULT_CATALYST_AUTH_ENVIRONMENT) + "\n"
        ).encode("ascii")
        self._ensure_workload_config_directory(token_path.parent, group_id=group_id, mode=0o750)
        token_digest = self._write_workload_managed_config(
            transaction,
            transaction_path,
            path=token_path,
            content=token_content,
            group_id=group_id,
            mode=0o640,
            entry_kind="catalyst-api-token",
        )
        auth_digest = self._write_workload_managed_config(
            transaction,
            transaction_path,
            path=DEFAULT_CATALYST_AUTH_ENVIRONMENT,
            content=auth_content,
            group_id=group_id,
            mode=0o640,
            entry_kind="catalyst-auth-environment",
        )
        control_digest = self._write_workload_managed_config(
            transaction,
            transaction_path,
            path=DEFAULT_STUDIO_CONTROL_ENVIRONMENT,
            content=control_content,
            group_id=group_id,
            mode=0o640,
            entry_kind="studio-control-environment",
        )
        self._ensure_workload_config_directory(
            DEFAULT_CATALYST_AUTH_DROPIN.parent, group_id=0, mode=0o755
        )
        dropin_digest = self._write_workload_managed_config(
            transaction,
            transaction_path,
            path=DEFAULT_CATALYST_AUTH_DROPIN,
            content=dropin_content,
            group_id=0,
            mode=0o644,
            entry_kind="catalyst-auth-dropin",
        )
        self._daemon_reload()
        identity = {
            "tokenPath": str(token_path),
            "tokenSha256": token_digest,
            "catalystEnvironmentDigest": auth_digest,
            "controlEnvironmentDigest": control_digest,
            "unitDropInDigest": dropin_digest,
            "origin": CATALYST_API_ORIGIN,
        }
        transaction["catalystAuth"] = identity
        _atomic_json(transaction_path, transaction)
        return identity

    def _restore_workload_catalyst_auth(self, transaction: dict[str, Any]) -> None:
        """Remove only new non-token projections that still match the transaction."""

        changed = False
        changes = transaction.get("managedConfigFiles", [])
        if not isinstance(changes, list):
            raise UpdateError(
                "INVALID_TRANSACTION", "Managed configuration rollback journal is malformed."
            )
        for entry in reversed(changes):
            if not isinstance(entry, dict) or entry.get("kind") == "catalyst-api-token":
                continue
            path_text = entry.get("path")
            if not isinstance(path_text, str):
                raise UpdateError(
                    "INVALID_TRANSACTION", "Managed configuration rollback path is malformed."
                )
            path = Path(path_text)
            if path not in {
                DEFAULT_CATALYST_AUTH_ENVIRONMENT,
                DEFAULT_STUDIO_CONTROL_ENVIRONMENT,
                DEFAULT_CATALYST_AUTH_DROPIN,
            }:
                raise UpdateError(
                    "INVALID_TRANSACTION",
                    "Managed configuration rollback path is outside its fixed allowlist.",
                )
            try:
                info = path.lstat()
                content = path.read_bytes()
            except FileNotFoundError:
                continue
            except OSError as error:
                raise UpdateError(
                    "ROLLBACK_CONFLICT",
                    "Managed authentication configuration cannot be read during rollback.",
                ) from error
            current = "sha256:" + hashlib.sha256(content).hexdigest()
            if current == entry.get("priorDigest"):
                continue
            if (
                current != entry.get("writtenDigest")
                or stat.S_ISLNK(info.st_mode)
                or info.st_uid != 0
                or info.st_nlink != 1
            ):
                raise UpdateError(
                    "ROLLBACK_CONFLICT",
                    "Managed authentication configuration changed outside this transaction.",
                )
            path.unlink()
            self._fsync_directory(path.parent)
            changed = True
        if changed:
            self._daemon_reload()

    def _daemon_reload(self) -> None:
        """Reload systemd unit metadata without inventing an empty unit argument."""

        try:
            completed = self.runner(
                ["systemctl", "daemon-reload"],
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired) as error:
            raise UpdateError("SYSTEMD_FAILED", f"Cannot reload systemd units: {error}") from error
        if completed.returncode != 0:
            raise UpdateError(
                "SYSTEMD_FAILED",
                "systemctl daemon-reload failed: "
                + (completed.stderr.strip() or completed.stdout.strip()),
            )

    def _workload_transaction_path(self, transaction: dict[str, Any]) -> Path:
        """Return the already-created root-private journal path for a plan."""

        return self._private_state_directory("transactions") / f"{transaction['planId']}.json"

    def _restore_workload_service_units(self, transaction: dict[str, Any]) -> None:
        """Restore only unit files still matching this transaction's signed bytes."""

        changed = False
        for entry in reversed(transaction.get("unitFileChanges", [])):
            if not isinstance(entry, dict) or not isinstance(entry.get("path"), str):
                raise UpdateError("INVALID_TRANSACTION", "Unit-file rollback journal is malformed.")
            path = Path(entry["path"])
            if not path.is_absolute() or path.name != Path(entry["path"]).name:
                raise UpdateError("INVALID_TRANSACTION", "Unit-file rollback path is invalid.")
            try:
                info = path.lstat()
                current = path.read_bytes()
            except FileNotFoundError:
                current = None
                info = None
            except OSError as error:
                raise UpdateError(
                    "ROLLBACK_CONFLICT", "Cannot read the current systemd unit."
                ) from error
            digest = (
                "sha256:" + hashlib.sha256(current).hexdigest() if current is not None else None
            )
            if digest == entry.get("priorDigest"):
                continue
            if digest != entry.get("writtenDigest"):
                raise UpdateError(
                    "ROLLBACK_CONFLICT", "Systemd unit changed outside this transaction."
                )
            prior = entry.get("priorBytes")
            if prior is None:
                if info is not None and (stat.S_ISLNK(info.st_mode) or info.st_uid != 0):
                    raise UpdateError("ROLLBACK_CONFLICT", "Systemd unit ownership changed.")
                path.unlink(missing_ok=True)
                self._fsync_directory(path.parent)
            else:
                try:
                    prior_bytes = base64.b64decode(prior, validate=True)
                except (ValueError, TypeError) as error:
                    raise UpdateError(
                        "INVALID_TRANSACTION", "Unit rollback bytes are malformed."
                    ) from error
                expected_prior = entry.get("priorDigest")
                if "sha256:" + hashlib.sha256(prior_bytes).hexdigest() != expected_prior:
                    raise UpdateError("INVALID_TRANSACTION", "Unit rollback digest differs.")
                temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.rollback")
                descriptor: int | None = None
                try:
                    descriptor = os.open(
                        temporary,
                        os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
                        0o644,
                    )
                    os.fchown(descriptor, 0, 0)
                    os.fchmod(descriptor, entry.get("priorMode") or 0o644)
                    with os.fdopen(descriptor, "wb") as stream:
                        descriptor = None
                        stream.write(prior_bytes)
                        stream.flush()
                        os.fsync(stream.fileno())
                    os.replace(temporary, path)
                    self._fsync_directory(path.parent)
                except OSError as error:
                    raise UpdateError(
                        "ROLLBACK_FAILED", "Cannot restore the prior systemd unit."
                    ) from error
                finally:
                    if descriptor is not None:
                        os.close(descriptor)
                    temporary.unlink(missing_ok=True)
            changed = True
        if changed:
            self._daemon_reload()

    def _set_workload_unit(self, unit: str, operation: str, *, wait_active: bool = False) -> None:
        """Change one already catalog-validated unit and verify the observed state."""

        self._run_systemctl(operation, unit)
        if wait_active:
            self._wait_unit_active(unit)
            return
        deadline = time.monotonic() + 90
        while time.monotonic() < deadline:
            if self._package_product_unit_state(unit) == "inactive":
                return
            time.sleep(1)
        raise UpdateError("PRODUCT_QUIESCE_TIMEOUT", f"{unit} did not stop within 90 seconds.")

    def _workload_runtime_daemon(self, operation: str, *, wait_active: bool = False) -> str:
        """Stop or start the fixed shared Package Runtime daemon after owner checks."""

        unit = WORKLOAD_PACKAGE_RUNTIME_UNIT
        if operation == "stop":
            state = self._package_product_unit_state(unit)
            if state == "active":
                self._set_workload_unit(unit, "stop")
            return state
        if operation not in {"start", "restart"}:
            raise UpdateError(
                "INVALID_TRANSACTION", "Package Runtime service operation is invalid."
            )
        state = self._package_product_unit_state(unit)
        if state != "active" or operation == "restart":
            self._set_workload_unit(unit, operation, wait_active=True)
        return state

    def _workload_inventory_before_daemon_stop(self, workload_id: str) -> dict[str, Any] | None:
        """Read all live owners immediately before taking down Package Runtime."""

        if self._package_product_unit_state(WORKLOAD_PACKAGE_RUNTIME_UNIT) == "inactive":
            return None
        component_ids = tuple(
            sorted(
                self._load_workload_resolver().potential_component_ids(self.catalog, workload_id)
            )
        )
        inventory = self._read_workload_package_inventory(workload_id, component_ids)
        bindings = inventory.get("sourceBindings", [])
        if not isinstance(bindings, list):
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Package Runtime owner inventory is malformed before daemon stop.",
                retryable=True,
            )
        active = [
            row for row in bindings if isinstance(row, dict) and row.get("state") == "RUNNING"
        ]
        if active:
            owners = sorted(f"{row.get('sourceId')}:{row.get('bindingId')}" for row in active)
            raise UpdateError(
                "COMPONENT_IN_USE",
                "An authenticated Package Runtime owner is active before offline maintenance: "
                + ", ".join(owners),
                retryable=True,
            )
        return inventory

    def _workload_binding_operation(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        *,
        operation: str,
        component: dict[str, Any],
        installation_id: str,
        activity_catalog: dict[str, Any],
        runtime_policy: dict[str, Any],
        source_principals: dict[str, dict[str, Any]],
        helper: Any,
    ) -> dict[str, Any]:
        """Run an owner-scoped Package Runtime SDK mutation with fsynced callbacks."""

        source_policy = component.get("sourcePolicy")
        if not isinstance(source_policy, dict):
            raise UpdateError(
                "SOURCE_POLICY_INVALID", "Selected package has no signed source policy."
            )
        source_id = (
            source_policy.get("sourceId")
            if source_policy.get("mode") == "standaloneOperator"
            else next(
                (
                    row.get("sourceId")
                    for row in source_policy.get("productSources", [])
                    if isinstance(row, dict)
                    and row.get("componentId") in source_policy.get("productComponentIds", [])
                ),
                None,
            )
        )
        component_id = component.get("componentId")
        binding_id = component.get("bindingId")
        package_id = component.get("packageId")
        principal = source_principals.get(source_id) if isinstance(source_id, str) else None
        if (
            not isinstance(component_id, str)
            or not isinstance(binding_id, str)
            or not isinstance(package_id, str)
            or not isinstance(source_id, str)
            or not isinstance(principal, dict)
            or type(principal.get("uid")) is not int
            or type(principal.get("gid")) is not int
            or not isinstance(principal.get("tokenPath"), Path)
        ):
            raise UpdateError(
                "SOURCE_BINDING_INVALID", "Selected package owner identity is incomplete."
            )
        sdk_environment = transaction.get("sdkEnvironment")
        if not isinstance(sdk_environment, dict):
            raise UpdateError(
                "WORKLOAD_SDK_UNAVAILABLE", "The installed operator SDK is unavailable."
            )
        sdk_python = sdk_environment.get("pythonPath")
        if not isinstance(sdk_python, str) or not Path(sdk_python).is_absolute():
            raise UpdateError(
                "WORKLOAD_SDK_UNAVAILABLE", "The operator SDK interpreter receipt is invalid."
            )
        request_id = (
            "cyrene-wop-"
            + transaction["planId"].removeprefix("plan-")
            + "-"
            + operation[:3]
            + "-"
            + hashlib.sha256(installation_id.encode("utf-8")).hexdigest()[:8]
            + "-"
            + component_id
        )
        binding_ops = transaction.setdefault("bindingOperations", [])
        if not isinstance(binding_ops, list):
            raise UpdateError("INVALID_TRANSACTION", "Workload binding journal is malformed.")

        def persist_intent(operation_request_id: str, scope: Mapping[str, Any]) -> None:
            if operation_request_id != request_id or not isinstance(scope, Mapping):
                raise UpdateError(
                    "INVALID_TRANSACTION", "Package Runtime mutation intent is mismatched."
                )
            identity = {"requestId": request_id, "scope": dict(scope), "operation": operation}
            existing = next(
                (
                    row
                    for row in binding_ops
                    if isinstance(row, dict) and row.get("requestId") == request_id
                ),
                None,
            )
            if existing is not None and any(
                existing.get(key) != value for key, value in identity.items()
            ):
                raise UpdateError(
                    "INVALID_TRANSACTION", "Package Runtime retry changed its owner scope."
                )
            if existing is None:
                binding_ops.append({**identity, "state": "intent"})
            _atomic_json(transaction_path, transaction)

        def persist_outcome(status: Mapping[str, Any] | None, receipt: Mapping[str, Any]) -> None:
            _persist_binding_result("outcome", status, None, receipt)

        def persist_reconcile(
            status: Mapping[str, Any] | None,
            installation: Mapping[str, Any],
            receipt: Mapping[str, Any],
        ) -> None:
            _persist_binding_result("reconciled", status, installation, receipt)

        def _persist_binding_result(
            state: str,
            status: Mapping[str, Any] | None,
            installation: Mapping[str, Any] | None,
            receipt: Mapping[str, Any],
        ) -> None:
            if not isinstance(receipt, Mapping) or receipt.get("request_id") != request_id:
                raise UpdateError("INVALID_TRANSACTION", "Package Runtime receipt is mismatched.")
            existing = next(
                (
                    row
                    for row in binding_ops
                    if isinstance(row, dict) and row.get("requestId") == request_id
                ),
                None,
            )
            if existing is None:
                raise UpdateError(
                    "INVALID_TRANSACTION", "Package Runtime outcome has no durable intent."
                )
            journal_status = None
            if isinstance(status, Mapping):
                # Package Runtime status may contain an opaque connection_ref.
                # Keep that value in memory for the caller, never in this journal.
                journal_status = {
                    key: value for key, value in status.items() if key != "connection_ref"
                }
            existing.update(
                {
                    "state": state,
                    "status": journal_status,
                    "installation": dict(installation)
                    if isinstance(installation, Mapping)
                    else None,
                    "receipt": dict(receipt),
                    "updatedAt": int(time.time()),
                }
            )
            _atomic_json(transaction_path, transaction)

        try:
            result = helper.run_package_binding_operation(
                operation=operation,
                source_id=source_id,
                uid=principal["uid"],
                gid=principal["gid"],
                token_path=principal["tokenPath"],
                binding_id=binding_id,
                package_id=package_id,
                installation_ids=[installation_id],
                catalog_generation=activity_catalog["generation"],
                request_id=request_id,
                sdk_python=Path(sdk_python),
                activity_catalog=activity_catalog,
                runtime_policy=runtime_policy,
                source_principals=source_principals,
                persist_intent=persist_intent,
                persist_outcome=persist_outcome,
                persist_reconcile=persist_reconcile,
            )
        except Exception as error:
            if isinstance(error, UpdateError):
                raise
            raise UpdateError(
                "PACKAGE_RUNTIME_OPERATION_FAILED",
                f"Package Runtime {operation} did not complete for {component_id}.",
                retryable=True,
            ) from error
        if not isinstance(result, dict) or result.get("requestId") != request_id:
            raise UpdateError(
                "PACKAGE_RUNTIME_OPERATION_FAILED", "Package Runtime receipt is malformed."
            )
        completed = next(
            (
                entry
                for entry in binding_ops
                if isinstance(entry, dict) and entry.get("requestId") == request_id
            ),
            None,
        )
        if not isinstance(completed, dict):
            raise UpdateError(
                "INVALID_TRANSACTION", "Package Runtime completion lost its durable intent."
            )
        completed["state"] = "completed"
        completed["completedAt"] = int(time.time())
        _atomic_json(transaction_path, transaction)
        return result

    def _write_workload_package_runtime_receipt(
        self,
        component: dict[str, Any],
        staged: dict[str, Any],
        installation: dict[str, Any],
    ) -> dict[str, Any]:
        """Persist the selected release identity plus real Platform InstallationRecord."""

        component_id = component.get("componentId")
        if (
            not isinstance(component_id, str)
            or installation.get("package_id") != component.get("packageId")
            or installation.get("package_version") != component.get("version")
            or installation.get("archive_digest") != component.get("digest")
            or installation.get("artifact_digest") != staged.get("packageArtifactDigest")
            or not _valid_digest(staged.get("packageArtifactDigest"))
            or not _valid_digest(staged.get("descriptorDigest"))
            or not _valid_digest(staged.get("dependencyLockDigest"))
            or not _valid_digest(component.get("manifestDigest"))
            or not _valid_digest(component.get("manifestAssetDigest"))
            or not _valid_digest(component.get("digest"))
        ):
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Platform installation identity differs from the verified staged release.",
            )
        verification = installation.get("verification")
        if (
            not isinstance(verification, dict)
            or verification.get("artifact_digest") != staged["packageArtifactDigest"]
            or verification.get("archive_digest") != component["digest"]
            or verification.get("descriptor_digest") != staged["descriptorDigest"]
            or verification.get("manifest_digest") != component["manifestDigest"]
            or verification.get("dependency_lock_digest") != staged["dependencyLockDigest"]
        ):
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Platform verification record differs from the verified descriptor and manifest.",
            )
        receipt = {
            "schemaVersion": 1,
            "componentId": component_id,
            "installed": True,
            "version": component["version"],
            "releaseId": component["releaseId"],
            "manifestUri": component["manifestUri"],
            "targetId": component["targetId"],
            "manifestDigest": component["manifestDigest"],
            "manifestAssetDigest": component["manifestAssetDigest"],
            "digest": component["digest"],
            "indexIdentity": component["indexIdentity"],
            "publisherIdentity": component["publisherIdentity"],
            "attestationRef": component["attestationRef"],
            "packageId": component["packageId"],
            "installationId": installation["installation_id"],
            "packageArtifactDigest": staged["packageArtifactDigest"],
            "archiveDigest": component["digest"],
            "descriptorDigest": staged["descriptorDigest"],
            "dependencyLockDigest": staged["dependencyLockDigest"],
            "installation": installation,
            "verification": {"identityAttested": True},
        }
        directory = self._installed_component_directory(component_id, create=True)
        assert directory is not None
        _atomic_json(directory / "package-runtime.json", receipt)
        return receipt

    def _clear_workload_package_runtime_receipt(
        self, component_id: str, installation_id: str
    ) -> None:
        """Remove only the updater hint for the exact Platform installation removed."""

        directory = self._installed_component_directory(component_id)
        if directory is None:
            return
        path = directory / "package-runtime.json"
        if not path.exists() and not path.is_symlink():
            return
        receipt = self._read_workload_package_runtime_receipt(component_id)
        if receipt is not None and receipt.get("installationId") != installation_id:
            raise UpdateError(
                "UNINSTALL_CONFLICT",
                "A different Package Runtime identity replaced the selected installation.",
            )
        if path.is_symlink():
            raise UpdateError("UNSAFE_STATE", "Package Runtime receipt became a symbolic link.")
        path.unlink(missing_ok=True)
        self._fsync_directory(directory)

    def _resume_workload_package_uninstall_phase(
        self, transaction: dict[str, Any], transaction_path: Path
    ) -> None:
        """Finish an interrupted held offline uninstall from its exact journal identity."""

        if (
            transaction.get("maintenancePhase") != "core-runtime-uninstall"
            or not transaction.get("maintenanceToken")
            or transaction.get("offlineUninstallIntent") is not True
        ):
            raise UpdateError(
                "PENDING_MAINTENANCE",
                "Package uninstall recovery journal is incomplete.",
                retryable=True,
            )
        component_id = transaction.get("componentId")
        row = transaction.get("selectedRow")
        installation = transaction.get("installation")
        if (
            not isinstance(component_id, str)
            or not isinstance(row, dict)
            or not isinstance(installation, dict)
            or not _valid_digest(installation.get("artifact_digest"))
        ):
            raise UpdateError(
                "INVALID_TRANSACTION", "Package uninstall recovery identity is malformed."
            )
        fresh_inventory = self._workload_inventory_before_daemon_stop(transaction["workloadId"])
        if fresh_inventory is not None:
            current = fresh_inventory.get("installationRecords", {}).get(component_id)
            installation = transaction["installation"]
            identity_fields = (
                "installation_id",
                "package_id",
                "package_version",
                "artifact_digest",
                "archive_digest",
                "descriptor_digest",
                "manifest_digest",
                "dependency_lock_digest",
            )
            if not isinstance(current, dict) or any(
                current.get(field) != installation.get(field) for field in identity_fields
            ):
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "Package Runtime installation identity changed while the uninstall hold was pending.",
                    retryable=True,
                )
            self._workload_runtime_daemon("stop")
        uninstall_result = transaction.get("offlineUninstallResult")
        if not isinstance(uninstall_result, dict):
            helper = self._load_workload_package_runtime()
            request_id = transaction.get("offlineUninstallRequestId")
            if not isinstance(request_id, str):
                raise UpdateError("INVALID_TRANSACTION", "Package uninstall request ID is missing.")
            try:
                uninstall_result = helper.uninstall_workload_package(
                    installation,
                    component_id=component_id,
                    request_id=request_id,
                    maintenance=self._workload_hold_echo(transaction),
                    runner=self.runner,
                )
            except Exception as error:
                raise UpdateError(
                    "PACKAGE_UNINSTALL_FAILED",
                    "Platform offline uninstall recovery did not complete.",
                    retryable=True,
                ) from error
            transaction["offlineUninstallResult"] = uninstall_result
            _atomic_json(transaction_path, transaction)
        source_policy = transaction.get("sourcePolicy")
        digest = installation.get("artifact_digest")
        if not isinstance(source_policy, dict) or not _valid_digest(digest):
            raise UpdateError(
                "INVALID_TRANSACTION", "Package uninstall source update identity is malformed."
            )
        self._update_workload_source_policy(
            transaction,
            transaction_path,
            source_policy=source_policy,
            selected_rows=[{**row, "packageArtifactDigest": digest}],
            installation_records={},
            phase="core-runtime-uninstall",
            remove_component_ids=(component_id,),
        )
        self._end_workload_hold(transaction, transaction_path, outcome="SUCCESS", healthy=True)
        self._workload_runtime_daemon("start", wait_active=True)
        transaction["packageRuntimeStarted"] = True
        _atomic_json(transaction_path, transaction)
        self._clear_workload_package_runtime_receipt(component_id, installation["installation_id"])

    @staticmethod
    def _workload_policy_source_id(source_policy: Mapping[str, Any]) -> str | None:
        """Resolve the one explicitly declared source owner without deriving IDs."""

        if source_policy.get("mode") == "standaloneOperator":
            source_id = source_policy.get("sourceId")
            return source_id if isinstance(source_id, str) else None
        if source_policy.get("mode") == "actualProduct":
            rows = source_policy.get("productSources")
            if isinstance(rows, list) and len(rows) == 1 and isinstance(rows[0], dict):
                source_id = rows[0].get("sourceId")
                return source_id if isinstance(source_id, str) else None
        return None

    def _workload_phase_is_ended(self, transaction: dict[str, Any], phase: str) -> bool:
        holds = transaction.get("maintenanceHolds")
        row = holds.get(phase) if isinstance(holds, dict) else None
        return isinstance(row, dict) and row.get("status") == "ended"

    def _ensure_workload_phase(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        *,
        phase: str,
        target_kind: str,
        requires_restart: bool,
    ) -> bool:
        """Acquire or resume one phase; return false when it already committed."""

        if self._workload_phase_is_ended(transaction, phase):
            return False
        if transaction.get("maintenanceToken"):
            if transaction.get("maintenancePhase") != phase:
                raise UpdateError(
                    "PENDING_MAINTENANCE",
                    "A different workload maintenance phase is still held.",
                    retryable=True,
                )
            return True
        self._begin_workload_hold(
            transaction,
            transaction_path,
            phase=phase,
            target_kind=target_kind,
            requires_restart=requires_restart,
        )
        return True

    def _quiesce_workload_bindings(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        *,
        plugin_rows: list[dict[str, Any]],
        package_inventory: dict[str, Any],
        block_foreign_for_daemon: bool,
        block_foreign_for_products: bool,
    ) -> dict[str, Any]:
        """Deactivate selected active package bindings and block unsafe shared owners."""

        source_bindings = package_inventory.get("sourceBindings", [])
        if not isinstance(source_bindings, list):
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED", "Package Runtime owner inventory is malformed."
            )
        selected: dict[tuple[str, str], dict[str, Any]] = {}
        selected_sources: set[str] = set()
        for row in plugin_rows:
            policy = row.get("sourcePolicy")
            source_id = (
                self._workload_policy_source_id(policy) if isinstance(policy, dict) else None
            )
            binding_id = row.get("bindingId")
            if not isinstance(source_id, str) or not isinstance(binding_id, str):
                raise UpdateError(
                    "SOURCE_BINDING_INVALID", "Selected plugin owner mapping is invalid."
                )
            selected[(source_id, binding_id)] = row
            selected_sources.add(source_id)

        workload = next(
            (
                item
                for item in self.catalog.get("workloads", [])
                if isinstance(item, dict) and item.get("workloadId") == transaction["workloadId"]
            ),
            None,
        )
        workload_policy = workload.get("sourcePolicy") if isinstance(workload, dict) else None
        product_source_ids: set[str] = set()
        if isinstance(workload_policy, dict) and workload_policy.get("mode") == "actualProduct":
            for mapping in workload_policy.get("productSources", []):
                if isinstance(mapping, dict) and isinstance(mapping.get("sourceId"), str):
                    product_source_ids.add(mapping["sourceId"])

        foreign_active: list[dict[str, Any]] = []
        selected_active: list[tuple[dict[str, Any], dict[str, Any]]] = []
        for binding in source_bindings:
            if not isinstance(binding, dict):
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED", "Package Runtime binding row is malformed."
                )
            source_id = binding.get("sourceId")
            binding_id = binding.get("bindingId")
            active_id = binding.get("activeInstallationId")
            if binding.get("state") != "RUNNING" or not isinstance(active_id, str):
                continue
            owner = selected.get((source_id, binding_id))
            if owner is not None:
                selected_active.append((binding, owner))
            elif block_foreign_for_daemon or (
                block_foreign_for_products and source_id in product_source_ids
            ):
                foreign_active.append(binding)
        if foreign_active:
            identifiers = sorted(
                f"{row.get('sourceId')}:{row.get('bindingId')}" for row in foreign_active
            )
            raise UpdateError(
                "COMPONENT_IN_USE",
                "Another active Package Runtime owner prevents this workload change: "
                + ", ".join(identifiers),
                retryable=True,
            )
        if selected_active:
            sdk_environment = transaction.get("sdkEnvironment")
            if not isinstance(sdk_environment, dict):
                raise UpdateError(
                    "WORKLOAD_SDK_UNAVAILABLE", "The verified operator SDK is unavailable."
                )
            activity_catalog, runtime_policy, principals, helper = self._workload_source_state(
                transaction["workloadId"]
            )
            if runtime_policy is None:
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED", "Active bindings have no runtime policy."
                )
            for binding, owner in selected_active:
                self._workload_binding_operation(
                    transaction,
                    transaction_path,
                    operation="deactivate",
                    component=owner,
                    installation_id=binding["activeInstallationId"],
                    activity_catalog=activity_catalog,
                    runtime_policy=runtime_policy,
                    source_principals=principals,
                    helper=helper,
                )
                # A fresh authenticated inventory is required before any shared
                # daemon stop or offline installation.
                package_inventory = self._read_workload_package_inventory(
                    transaction["workloadId"],
                    tuple(
                        sorted(
                            self._load_workload_resolver().potential_component_ids(
                                self.catalog, transaction["workloadId"]
                            )
                        )
                    ),
                )
                still_running = any(
                    isinstance(row, dict)
                    and row.get("sourceId") == binding.get("sourceId")
                    and row.get("bindingId") == binding.get("bindingId")
                    and row.get("state") == "RUNNING"
                    for row in package_inventory.get("sourceBindings", [])
                )
                if still_running:
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        "Package Runtime did not confirm the selected binding was deactivated.",
                        retryable=True,
                    )
        return package_inventory

    def _workload_component_artifact_map(
        self,
        rows: list[dict[str, Any]],
        staged_by_id: dict[str, dict[str, Any]],
        package_inventory: dict[str, Any],
    ) -> dict[str, str]:
        """Build the immutable complete maintenance map with Package digests separated."""

        result: dict[str, str] = {}
        installed = package_inventory.get("components", {})
        for row in rows:
            component_id = row.get("componentId")
            staged = staged_by_id.get(component_id) if isinstance(component_id, str) else None
            if not isinstance(component_id, str) or not isinstance(staged, dict):
                raise UpdateError("INVALID_STAGE", "Workload component identity is incomplete.")
            if row.get("artifactKind") == "plugin-package":
                package_digest = staged.get("packageArtifactDigest")
                if package_digest is None and isinstance(installed, dict):
                    identity = installed.get(component_id)
                    package_digest = (
                        identity.get("packageArtifactDigest")
                        if isinstance(identity, dict)
                        else None
                    )
                if not _valid_digest(package_digest):
                    raise UpdateError(
                        "PACKAGE_DESCRIPTOR_MISMATCH",
                        f"Verified package aggregate digest is missing for {component_id}.",
                    )
                result[component_id] = package_digest
            else:
                digest = row.get("digest")
                if not _valid_digest(digest):
                    raise UpdateError(
                        "INVALID_STAGE", f"Verified component digest is missing for {component_id}."
                    )
                result[component_id] = digest
        if len(result) != len(rows):
            raise UpdateError("INVALID_STAGE", "Workload digest map does not cover each component.")
        return result

    def _resume_workload_package_install_phase(
        self, transaction: dict[str, Any], transaction_path: Path
    ) -> None:
        """Finish a journaled PACKAGE_ONLY install before attempting UDS readback."""

        if (
            transaction.get("maintenancePhase") != "package-only"
            or not transaction.get("maintenanceToken")
            or not isinstance(transaction.get("selectedPluginRows"), list)
            or not isinstance(transaction.get("stagedComponents"), list)
        ):
            raise UpdateError(
                "PENDING_MAINTENANCE",
                "Package-only recovery journal is incomplete.",
                retryable=True,
            )
        fresh_inventory = self._workload_inventory_before_daemon_stop(transaction["workloadId"])
        if fresh_inventory is not None:
            installation_records = fresh_inventory.get("installationRecords", {})
            if isinstance(installation_records, dict):
                transaction.setdefault("packageInstallations", {}).update(
                    {
                        component_id: record
                        for component_id, record in installation_records.items()
                        if isinstance(component_id, str) and isinstance(record, dict)
                    }
                )
            self._workload_runtime_daemon("stop")
            _atomic_json(transaction_path, transaction)
        selected_rows = transaction["selectedPluginRows"]
        staged_by_id = {
            row.get("componentId"): row
            for row in transaction["stagedComponents"]
            if isinstance(row, dict) and isinstance(row.get("componentId"), str)
        }
        installation_records = transaction.setdefault("packageInstallations", {})
        if not isinstance(installation_records, dict):
            raise UpdateError(
                "INVALID_TRANSACTION", "Package install recovery records are malformed."
            )
        helper = self._load_workload_package_runtime()
        maintenance = self._workload_hold_echo(transaction)
        for row in selected_rows:
            if not isinstance(row, dict):
                raise UpdateError(
                    "INVALID_TRANSACTION", "Selected package recovery row is malformed."
                )
            component_id = row.get("componentId")
            staged = staged_by_id.get(component_id) if isinstance(component_id, str) else None
            if not isinstance(component_id, str) or not isinstance(staged, dict):
                raise UpdateError(
                    "INVALID_TRANSACTION", "Package recovery stage identity is missing."
                )
            if staged.get("status") == "current" and isinstance(
                installation_records.get(component_id), dict
            ):
                continue
            request_id = (
                "cyrene-wpkg-"
                + transaction["planId"].removeprefix("plan-")
                + "-"
                + hashlib.sha256(component_id.encode("utf-8")).hexdigest()[:12]
            )
            try:
                record = helper.install_workload_package(
                    row,
                    staged,
                    request_id=request_id,
                    maintenance=maintenance,
                    runner=self.runner,
                )
            except Exception as error:
                raise UpdateError(
                    "PACKAGE_INSTALL_FAILED",
                    f"Platform package recovery did not complete for {component_id}.",
                    retryable=True,
                ) from error
            identity = self._write_workload_package_runtime_receipt(row, staged, record)
            installation_records[component_id] = record
            transaction.setdefault("packageIdentities", {})[component_id] = identity
            _atomic_json(transaction_path, transaction)
        source_rows = [
            {
                **row,
                "packageArtifactDigest": staged_by_id[row["componentId"]].get(
                    "packageArtifactDigest"
                ),
            }
            for row in selected_rows
        ]
        self._update_workload_source_policy(
            transaction,
            transaction_path,
            source_policy=transaction["sourcePolicy"],
            selected_rows=source_rows,
            installation_records=installation_records,
            phase="package-only",
        )
        self._end_workload_hold(transaction, transaction_path, outcome="SUCCESS", healthy=True)
        self._workload_runtime_daemon("start", wait_active=True)
        transaction["packageRuntimeStarted"] = True
        _atomic_json(transaction_path, transaction)

    def _apply_workload_install_assembled(
        self, stored: dict[str, Any], confirmation: dict[str, Any]
    ) -> dict[str, Any]:
        """Apply one signed workload using the existing journal and separated holds."""

        plan_id = stored["planId"]
        plan_digest = stored["planDigest"]
        workload_id = stored["workloadId"]
        target_id = stored["targetId"]
        transaction_path = self._private_state_directory("transactions") / f"{plan_id}.json"
        prior_transaction = None
        if transaction_path.exists() or transaction_path.is_symlink():
            prior_transaction = _read_object(transaction_path, "workload transaction")
            if (
                prior_transaction.get("transactionKind") != "workload-assembly.v1"
                or prior_transaction.get("action") != "install"
                or prior_transaction.get("planId") != plan_id
                or prior_transaction.get("planDigest") != plan_digest
                or prior_transaction.get("workloadId") != workload_id
            ):
                raise UpdateError(
                    "PENDING_MAINTENANCE",
                    "A different transaction occupies this workload plan.",
                    retryable=True,
                )
            if prior_transaction.get("phase") == "succeeded":
                return prior_transaction["result"]
            holds = prior_transaction.get("maintenanceHolds", {})
            package_hold = holds.get("package-only") if isinstance(holds, dict) else None
            if (
                isinstance(package_hold, dict)
                and package_hold.get("status") in {"begin_pending", "active", "end_pending"}
                and prior_transaction.get("maintenanceToken")
            ):
                self._resume_workload_package_install_phase(prior_transaction, transaction_path)
            elif (
                isinstance(package_hold, dict)
                and package_hold.get("status") == "ended"
                and prior_transaction.get("packageRuntimeStarted") is not True
            ):
                self._workload_runtime_daemon("start", wait_active=True)
                prior_transaction["packageRuntimeStarted"] = True
                _atomic_json(transaction_path, prior_transaction)
        resolution, candidates, package_inventory = self._build_workload_plan(
            workload_id,
            target_id,
            stored.get("selections"),
            action="install",
            channel=stored.get("channel"),
        )
        if (
            (resolution.get("status") != "ready" or resolution.get("planDigest") != plan_digest)
            and isinstance(prior_transaction, dict)
            and isinstance(prior_transaction.get("resolution"), dict)
        ):
            resolution = prior_transaction["resolution"]
            if resolution.get("planDigest") != plan_digest or resolution.get("status") != "ready":
                raise UpdateError(
                    "INVALID_TRANSACTION", "Durable workload plan identity is malformed."
                )
        elif resolution.get("status") != "ready" or resolution.get("planDigest") != plan_digest:
            raise UpdateError(
                "PLAN_CHANGED",
                "The installed workload resolution changed; check and stage again.",
                retryable=True,
            )
        rows = resolution.get("selectedComponents")
        staged_rows = stored.get("stagedComponents")
        if not isinstance(rows, list) or not isinstance(staged_rows, list) or not rows:
            raise UpdateError("INVALID_STAGE", "The staged workload component set is malformed.")
        staged_by_id = {
            row.get("componentId"): row
            for row in staged_rows
            if isinstance(row, dict) and isinstance(row.get("componentId"), str)
        }
        if len(staged_by_id) != len(staged_rows) or set(staged_by_id) != {
            row.get("componentId") for row in rows if isinstance(row, dict)
        }:
            raise UpdateError(
                "INVALID_STAGE", "The staged workload component set differs from the signed plan."
            )
        if not _running_as_root():
            raise UpdateError(
                "PRIVILEGE_REQUIRED", "Applying a workload requires the root-owned update helper."
            )

        plugin_rows: list[dict[str, Any]] = []
        native_components: list[dict[str, Any]] = []
        web_components: list[dict[str, Any]] = []
        oci_components: list[dict[str, Any]] = []
        sdk_entry: tuple[dict[str, Any], dict[str, Any]] | None = None
        for row in rows:
            if not isinstance(row, dict):
                raise UpdateError("INVALID_STAGE", "Resolved workload row is malformed.")
            component_id = row["componentId"]
            staged = staged_by_id[component_id]
            artifact_kind = row.get("artifactKind")
            if artifact_kind == "plugin-package":
                owner_row = dict(row)
                owner_row["packageArtifactDigest"] = staged.get("packageArtifactDigest")
                plugin_rows.append(owner_row)
                continue
            if component_id == WORKLOAD_SDK_COMPONENT_ID:
                sdk_entry = (row, staged)
                continue
            if artifact_kind == "oci-image":
                if component_id != WORKLOAD_ECHO_COMPONENT_ID:
                    raise UpdateError(
                        "WORKLOAD_ARTIFACT_UNAVAILABLE",
                        f"No installed OCI supervisor is configured for {component_id}.",
                    )
                receipt = self._read_workload_echo_receipt()
                if staged.get("status") == "current":
                    if (
                        not isinstance(receipt, dict)
                        or receipt.get("digest") != row.get("digest")
                        or receipt.get("manifestDigest") != row.get("manifestDigest")
                        or receipt.get("releaseId") != row.get("releaseId")
                    ):
                        raise UpdateError(
                            "WORKLOAD_OCI_READBACK_REQUIRED",
                            "The current Echo image receipt differs from the selected signed release.",
                            retryable=True,
                        )
                    item = dict(row)
                    item["artifactAttestationVerified"] = (
                        receipt.get("artifactAttestationVerified") is True
                    )
                else:
                    candidate = candidates.get(component_id)
                    identity = staged.get("stagedIdentity")
                    if (
                        candidate is None
                        or not isinstance(identity, dict)
                        or identity.get("planId") != plan_id
                        or identity.get("planDigest") != plan_digest
                        or staged.get("artifactAttestationVerified") is not True
                    ):
                        raise UpdateError(
                            "INVALID_STAGE", "Echo image attestation is not bound to this plan."
                        )
                    item = dict(row)
                    item["manifest"] = candidate.manifest
                    item["artifactAttestationVerified"] = True
                if (
                    not _valid_digest(item.get("digest"))
                    or not _valid_digest(item.get("manifestDigest"))
                    or item.get("targetId") != WORKLOAD_ECHO_TARGET_ID
                ):
                    raise UpdateError("INVALID_STAGE", "Echo image identity is incomplete.")
                oci_components.append(item)
                continue
            if staged.get("status") == "current":
                continue
            candidate = candidates.get(component_id)
            identity = staged.get("stagedIdentity")
            if candidate is None or not isinstance(identity, dict):
                raise UpdateError(
                    "INVALID_STAGE", f"Signed staged identity is missing for {component_id}."
                )
            item = {
                "componentId": component_id,
                "version": candidate.manifest["version"],
                "manifestDigest": candidate.manifest_digest,
                "releaseIdentity": candidate.manifest_digest,
                "artifactDigest": candidate.artifact_digest,
                "restartGroup": self.components[component_id]["restart"]["group"],
                "pointerIdentity": identity.get("pointerIdentity", identity.get("releaseIdentity")),
                "bundleIdentity": identity.get("bundleIdentity"),
                "manifest": candidate.manifest,
                "releasePath": identity.get("releasePath"),
                "archivePath": identity.get("archivePath"),
                "verification": {"identityAttested": True},
            }
            item.update(self._workload_receipt_fields(candidate, row))
            if artifact_kind == "static-web":
                item["pointerIdentity"] = identity.get("releaseIdentity")
                item["bundleIdentity"] = None
                web_components.append(item)
            elif artifact_kind in {"native-binary", "python-bundle"}:
                component = self.components.get(component_id)
                if not isinstance(component, dict) or component.get("kind") not in {
                    "native-binary",
                    "python-bundle",
                }:
                    raise UpdateError(
                        "WORKLOAD_ARTIFACT_UNAVAILABLE", f"No native supervisor for {component_id}."
                    )
                native_components.append(item)
            else:
                raise UpdateError(
                    "WORKLOAD_ARTIFACT_UNAVAILABLE",
                    f"No installed Ubuntu supervisor is configured for {component_id} ({artifact_kind}).",
                    retryable=True,
                )

        if oci_components:
            # Do the read-only host check before preparing the operator
            # environment or changing a pointer. A missing runtime must not
            # leave an otherwise unrelated SDK installation behind.
            self._preflight_workload_oci_runtime()

        component_artifact_digests = self._workload_component_artifact_map(
            rows, staged_by_id, package_inventory
        )
        transaction: dict[str, Any] | None = prior_transaction
        if transaction is not None:
            if (
                transaction.get("transactionKind") != "workload-assembly.v1"
                or transaction.get("planId") != plan_id
                or transaction.get("planDigest") != plan_digest
                or transaction.get("workloadId") != workload_id
                or transaction.get("componentArtifactDigests") != component_artifact_digests
            ):
                raise UpdateError(
                    "PENDING_MAINTENANCE",
                    "A different transaction occupies this workload plan.",
                    retryable=True,
                )
            if transaction.get("phase") == "succeeded":
                return transaction["result"]
            if transaction.get("phase") == "rolled_back":
                raise UpdateError(
                    "APPLY_ROLLED_BACK",
                    transaction.get("rollbackMessage", "Workload apply rolled back."),
                )
        else:
            transaction = None

        sdk_module = self._load_workload_sdk_environment()

        workload_host = next(
            (
                item
                for item in self.catalog.get("workloads", [])
                if isinstance(item, dict) and item.get("workloadId") == workload_id
            ),
            None,
        )
        source_policy = (
            workload_host.get("sourcePolicy") if isinstance(workload_host, dict) else None
        )
        if not isinstance(source_policy, dict):
            raise UpdateError(
                "SOURCE_POLICY_INVALID", "Signed workload sourcePolicy is unavailable."
            )
        service_units = self._workload_service_units(rows, source_policy, native_components)
        transaction = transaction or {
            "schemaVersion": 2,
            "transactionKind": "workload-assembly.v1",
            "planId": plan_id,
            "requestId": "cyrene-update-" + plan_id,
            "planDigest": plan_digest,
            "workloadId": workload_id,
            "targetId": target_id,
            "action": "install",
            "catalogDigest": stored["catalogDigest"],
            "channel": stored["channel"],
            "componentArtifactDigests": component_artifact_digests,
            "phase": "applying",
            "components": native_components,
            "webComponents": web_components,
            "ociComponents": oci_components,
            "selectedComponents": rows,
            "selectedPluginRows": plugin_rows,
            "stagedComponents": staged_rows,
            "resolution": resolution,
            "sourcePolicy": source_policy,
            "requiresRestart": bool(service_units or oci_components),
            "previous": self._capture_active_versions(native_components),
            "previousWeb": [
                self._capture_workload_web_identity(item["componentId"]) for item in web_components
            ],
            "maintenanceHolds": {},
            "bindingOperations": [],
            "packageInstallations": {},
            "unitFileChanges": [],
            "phaseStartedAt": int(time.time()),
        }
        if sdk_entry is None or "sdkEnvironment" not in transaction:
            transaction["sdkEnvironment"] = None
        transaction["selectedComponents"] = rows
        transaction["selectedPluginRows"] = plugin_rows
        transaction["stagedComponents"] = staged_rows
        transaction["resolution"] = resolution
        if not isinstance(transaction.get("packageInstallations"), dict):
            transaction["packageInstallations"] = {}
        for component_id, record in package_inventory.get("installationRecords", {}).items():
            if isinstance(component_id, str) and isinstance(record, dict):
                transaction["packageInstallations"].setdefault(component_id, record)
        transaction["components"] = native_components
        transaction["webComponents"] = web_components
        transaction["ociComponents"] = oci_components
        transaction["previous"] = transaction.get("previous") or self._capture_active_versions(
            native_components
        )
        transaction["previousWeb"] = transaction.get("previousWeb") or [
            self._capture_workload_web_identity(item["componentId"]) for item in web_components
        ]
        if oci_components:
            prior_echo_receipt = self._read_workload_echo_receipt()
            transaction.setdefault("previousEchoReceipt", prior_echo_receipt)
            if isinstance(prior_echo_receipt, dict) and any(
                prior_echo_receipt.get("digest") != item.get("digest")
                or prior_echo_receipt.get("manifestDigest") != item.get("manifestDigest")
                for item in oci_components
            ):
                raise UpdateError(
                    "WORKLOAD_OCI_UPGRADE_UNAVAILABLE",
                    "Replacing an installed Echo image requires a separately verified rollback plan.",
                    retryable=True,
                )
        _atomic_json(transaction_path, transaction)

        if sdk_entry is not None:
            selected_sdk, staged_sdk = sdk_entry
            self._prepare_workload_sdk_durably(
                transaction,
                transaction_path,
                sdk_module,
                selected_sdk,
                staged_sdk,
                plan_id=plan_id,
                plan_digest=plan_digest,
            )

        web_host = None
        if any(row.get("artifactKind") == "static-web" for row in rows):
            web_host = self._load_workload_web_host()
            if "webHostPrerequisite" not in transaction:
                try:
                    transaction["webHostPrerequisite"] = web_host.prepare_host_prerequisites(
                        install_authorized=True,
                        durable_callback=self._journal_callback(
                            transaction, transaction_path, "hostEvents"
                        ),
                        runner=self._workload_web_host_runner,
                    )
                    transaction["webHostPriorState"] = web_host.capture_web_host_state(
                        runner=self._workload_web_host_runner
                    )
                    transaction["webHostApplied"] = False
                    _atomic_json(transaction_path, transaction)
                except Exception as error:
                    raise UpdateError(
                        "WORKLOAD_WEB_HOST_UNAVAILABLE",
                        "The local Web host prerequisite could not be prepared.",
                        retryable=True,
                    ) from error

        selected_ids = {row.get("componentId") for row in rows if isinstance(row, dict)}
        catalyst_auth_selected = {
            CATALYST_COMPONENT_ID,
            STUDIO_CONTROL_COMPONENT_ID,
        }.issubset(selected_ids)
        if catalyst_auth_selected:
            # Credential and unit conflicts are a check-time host preflight. Do
            # not discover them after APT, pointer, or maintenance changes begin.
            self._workload_catalyst_token_configuration(generate=False)
        if oci_components and "echoApiTokenIdentity" not in transaction:
            self._ensure_workload_echo_api_token(transaction, transaction_path)

        # Fresh, authenticated owner status is the preflight before any service or
        # daemon is stopped. Selected old bindings are deactivated by their owner;
        # foreign active bindings are never silently stopped.
        package_changed = any(
            row.get("artifactKind") == "plugin-package"
            and staged_by_id[row["componentId"]].get("status") != "current"
            for row in rows
        )
        oci_changed = any(
            staged_by_id[item["componentId"]].get("status") != "current" for item in oci_components
        )
        activity_catalog, _activity_source_ids = self._activity_catalog()
        source_ids = {
            source["source_id"]
            for source in activity_catalog.get("sources", [])
            if isinstance(source, dict) and isinstance(source.get("source_id"), str)
        }
        declared_product_sources = {
            row.get("sourceId")
            for row in source_policy.get("productSources", [])
            if isinstance(row, dict) and isinstance(row.get("sourceId"), str)
        }
        source_registration_needed = source_policy.get(
            "mode"
        ) == "actualProduct" and not declared_product_sources.issubset(source_ids)
        catalyst_auth_needed = (
            catalyst_auth_selected and not self._workload_catalyst_auth_is_configured()
        )
        core_install_needed = (
            bool(native_components or web_components or oci_changed)
            or source_registration_needed
            or catalyst_auth_needed
        )
        previous_package_bindings = transaction.setdefault("previousPackageBindings", [])
        if not isinstance(previous_package_bindings, list):
            raise UpdateError(
                "INVALID_TRANSACTION", "Prior Package Runtime binding inventory is malformed."
            )
        if plugin_rows and not previous_package_bindings:
            source_bindings = package_inventory.get("sourceBindings", [])
            for row in plugin_rows:
                policy = row.get("sourcePolicy")
                source_id = (
                    self._workload_policy_source_id(policy) if isinstance(policy, dict) else None
                )
                binding_id = row.get("bindingId")
                if not isinstance(source_id, str) or not isinstance(binding_id, str):
                    raise UpdateError(
                        "SOURCE_BINDING_INVALID", "Selected package owner mapping is invalid."
                    )
                existing = next(
                    (
                        item
                        for item in source_bindings
                        if isinstance(item, dict)
                        and item.get("sourceId") == source_id
                        and item.get("bindingId") == binding_id
                    ),
                    None,
                )
                previous_package_bindings.append(
                    {
                        "componentId": row["componentId"],
                        "sourceId": source_id,
                        "bindingId": binding_id,
                        "packageId": row.get("packageId"),
                        "state": existing.get("state", "BINDING_NOT_FOUND")
                        if isinstance(existing, dict)
                        else "BINDING_NOT_FOUND",
                        "activeInstallationId": existing.get("activeInstallationId")
                        if isinstance(existing, dict)
                        else None,
                    }
                )
            _atomic_json(transaction_path, transaction)
        if plugin_rows and (package_changed or core_install_needed):
            package_inventory = self._quiesce_workload_bindings(
                transaction,
                transaction_path,
                plugin_rows=plugin_rows,
                package_inventory=package_inventory,
                block_foreign_for_daemon=package_changed,
                block_foreign_for_products=core_install_needed,
            )
        elif core_install_needed:
            # Without selected package rows, still refuse to stop the Product while
            # another package owner mapped to that Product is active.
            active_product_sources = {
                row.get("sourceId")
                for row in package_inventory.get("sourceBindings", [])
                if isinstance(row, dict)
                and row.get("state") == "RUNNING"
                and row.get("sourceId") in declared_product_sources
            }
            if active_product_sources:
                raise UpdateError(
                    "COMPONENT_IN_USE",
                    "An active Package Runtime binding prevents the Product maintenance phase.",
                    retryable=True,
                )

        if (
            core_install_needed
            and not self._workload_phase_is_ended(transaction, "core-runtime-install")
            and self._ensure_workload_phase(
                transaction,
                transaction_path,
                phase="core-runtime-install",
                target_kind="CORE_RUNTIME",
                requires_restart=bool(service_units),
            )
        ):
            try:
                prior_states = transaction.setdefault("priorServiceStates", {})
                for service in service_units:
                    unit = service["unit"]
                    state = self._package_product_unit_state(unit)
                    prior_states.setdefault(unit, state)
                    if state == "active":
                        self._set_workload_unit(unit, "stop")
                    _atomic_json(transaction_path, transaction)
                self._install_workload_service_units(transaction, service_units)
                for item in native_components:
                    current = self._active_native_pointer_identity(item["componentId"])
                    desired = _native_release_pointer_identity(item)
                    previous = next(
                        row
                        for row in transaction["previous"]
                        if row["componentId"] == item["componentId"]
                    )
                    if current != desired:
                        if current != previous.get("pointerIdentity"):
                            raise UpdateError(
                                "ACTIVE_VERSION_CHANGED",
                                f"Active pointer changed for {item['componentId']}.",
                                retryable=True,
                            )
                        self._activate_transaction(
                            {
                                **transaction,
                                "components": [item],
                                "previous": [previous],
                            }
                        )
                    elif self._read_active_receipt(item["componentId"]) is None:
                        self._write_active_receipt(item)
                for item in web_components:
                    prior = next(
                        row
                        for row in transaction["previousWeb"]
                        if row["componentId"] == item["componentId"]
                    )
                    current = self._capture_workload_web_identity(item["componentId"])
                    if current.get("pointerIdentity") != item["pointerIdentity"]:
                        self._activate_workload_web(item, expected_current=prior["pointerIdentity"])
                if catalyst_auth_selected and not self._workload_catalyst_auth_is_configured():
                    transaction["catalystAuth"] = self._project_workload_catalyst_auth(
                        transaction, transaction_path
                    )
                if source_registration_needed and not plugin_rows:
                    self._update_workload_source_policy(
                        transaction,
                        transaction_path,
                        source_policy=source_policy,
                        selected_rows=[],
                        installation_records={},
                        phase="core-runtime-install",
                    )
                self._end_workload_hold(
                    transaction, transaction_path, outcome="SUCCESS", healthy=True
                )
            except Exception as error:
                transaction["phase"] = "applying"
                _atomic_json(transaction_path, transaction)
                self._recover_workload_apply(transaction, transaction_path, failure=error)
                raise

        if oci_changed:
            selected_echo = next(
                (
                    item
                    for item in oci_components
                    if item.get("componentId") == WORKLOAD_ECHO_COMPONENT_ID
                ),
                None,
            )
            if not isinstance(selected_echo, dict):
                raise UpdateError("INVALID_STAGE", "The Echo OCI plan identity is missing.")
            activity_catalog, source, principal = self._workload_echo_source_identity()
            api_token = self._read_workload_echo_api_token()
            if api_token is None:
                raise UpdateError(
                    "WORKLOAD_ECHO_TOKEN_READBACK_REQUIRED",
                    "The stable Echo API bearer was not persisted before image staging.",
                    retryable=True,
                )
            spec = self._workload_echo_container_spec(
                selected_echo,
                activity_catalog,
                source,
                principal,
                api_token=api_token[0],
                connection_ref=None,
                activity_generation=activity_catalog.get("generation"),
            )
            try:
                helper = self._load_workload_oci_host()
                image_identity = helper.pull_and_verify_image(
                    spec, runner=self._workload_oci_runner
                )
            except Exception as error:
                raise UpdateError(
                    "OCI_IMAGE_UNAVAILABLE",
                    "The verified Echo image could not be fetched and checked by the installed OCI runtime.",
                    retryable=True,
                ) from error
            transaction["echoImageIdentity"] = image_identity
            _atomic_json(transaction_path, transaction)

        if package_changed:
            package_inventory = self._quiesce_workload_bindings(
                transaction,
                transaction_path,
                plugin_rows=plugin_rows,
                package_inventory=package_inventory,
                block_foreign_for_daemon=True,
                block_foreign_for_products=False,
            )
            if any(
                isinstance(row, dict) and row.get("state") == "RUNNING"
                for row in package_inventory.get("sourceBindings", [])
            ):
                raise UpdateError(
                    "COMPONENT_IN_USE",
                    "The Package Runtime daemon still has an active owner binding.",
                    retryable=True,
                )
            if self._ensure_workload_phase(
                transaction,
                transaction_path,
                phase="package-only",
                target_kind="PACKAGE_ONLY",
                requires_restart=False,
            ):
                fresh_inventory = self._workload_inventory_before_daemon_stop(workload_id)
                if fresh_inventory is not None:
                    package_inventory = fresh_inventory
                    installation_records = package_inventory.get("installationRecords", {})
                    if isinstance(installation_records, dict):
                        transaction.setdefault("packageInstallations", {}).update(
                            {
                                component_id: record
                                for component_id, record in installation_records.items()
                                if isinstance(component_id, str) and isinstance(record, dict)
                            }
                        )
                    _atomic_json(transaction_path, transaction)
                prior_daemon_state = self._workload_runtime_daemon("stop")
                transaction["packageRuntimePriorState"] = prior_daemon_state
                _atomic_json(transaction_path, transaction)
                try:
                    helper = self._load_workload_package_runtime()
                    maintenance = self._workload_hold_echo(transaction)
                    installation_records = dict(package_inventory.get("installationRecords", {}))
                    for row in plugin_rows:
                        component_id = row["componentId"]
                        staged = staged_by_id[component_id]
                        if staged.get("status") == "current":
                            record = installation_records.get(component_id)
                            if not isinstance(record, dict):
                                raise UpdateError(
                                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                                    f"Installed package record is missing for {component_id}.",
                                    retryable=True,
                                )
                            continue
                        request_id = (
                            "cyrene-wpkg-"
                            + plan_id.removeprefix("plan-")
                            + "-"
                            + hashlib.sha256(component_id.encode("utf-8")).hexdigest()[:12]
                        )
                        try:
                            record = helper.install_workload_package(
                                row,
                                staged,
                                request_id=request_id,
                                maintenance=maintenance,
                                runner=self.runner,
                            )
                        except Exception as error:
                            raise UpdateError(
                                "PACKAGE_INSTALL_FAILED",
                                f"Platform package install did not complete for {component_id}.",
                                retryable=True,
                            ) from error
                        if not isinstance(record, dict):
                            raise UpdateError(
                                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                                f"Platform install receipt is malformed for {component_id}.",
                            )
                        identity = self._write_workload_package_runtime_receipt(row, staged, record)
                        installation_records[component_id] = record
                        transaction.setdefault("packageIdentities", {})[component_id] = identity
                        transaction.setdefault("packageInstallations", {})[component_id] = record
                        _atomic_json(transaction_path, transaction)
                    source_rows = []
                    for row in plugin_rows:
                        staged = staged_by_id[row["componentId"]]
                        source_rows.append(
                            {**row, "packageArtifactDigest": staged.get("packageArtifactDigest")}
                        )
                    self._update_workload_source_policy(
                        transaction,
                        transaction_path,
                        source_policy=source_policy,
                        selected_rows=source_rows,
                        installation_records=installation_records,
                        phase="package-only",
                    )
                    self._end_workload_hold(
                        transaction, transaction_path, outcome="SUCCESS", healthy=True
                    )
                except Exception:
                    transaction["phase"] = "applying"
                    _atomic_json(transaction_path, transaction)
                    raise
            transaction["packageRuntimeStarted"] = False
            self._workload_runtime_daemon("start", wait_active=True)
            transaction["packageRuntimeStarted"] = True
            _atomic_json(transaction_path, transaction)

        # Activate selected plugin bindings through the non-root source identity and
        # the normal Broker admission SDK. Each mutation's callback is already fsynced
        # into this transaction before the SDK completes its lease.
        if plugin_rows:
            package_inventory = self._read_workload_package_inventory(
                workload_id,
                tuple(
                    sorted(
                        self._load_workload_resolver().potential_component_ids(
                            self.catalog, workload_id
                        )
                    )
                ),
            )
            activity_catalog, runtime_policy, principals, helper = self._workload_source_state(
                workload_id
            )
            if runtime_policy is None:
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "Package Runtime policy is missing after installation.",
                    retryable=True,
                )
            installations = package_inventory.get("installationRecords", {})
            for row in plugin_rows:
                component_id = row["componentId"]
                record = (
                    transaction.get("packageInstallations", {}).get(component_id)
                    if isinstance(transaction.get("packageInstallations"), dict)
                    else None
                )
                if not isinstance(record, dict) and isinstance(installations, dict):
                    record = installations.get(component_id)
                if not isinstance(record, dict) or not isinstance(
                    record.get("installation_id"), str
                ):
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        f"Package installation identity is unavailable for {component_id}.",
                        retryable=True,
                    )
                source_id = self._workload_policy_source_id(row["sourcePolicy"])
                existing_binding = next(
                    (
                        binding
                        for binding in package_inventory.get("sourceBindings", [])
                        if isinstance(binding, dict)
                        and binding.get("sourceId") == source_id
                        and binding.get("bindingId") == row.get("bindingId")
                    ),
                    None,
                )
                if (
                    isinstance(existing_binding, dict)
                    and existing_binding.get("state") == "RUNNING"
                    and existing_binding.get("activeInstallationId") == record["installation_id"]
                ):
                    continue
                self._workload_binding_operation(
                    transaction,
                    transaction_path,
                    operation="activate",
                    component=row,
                    installation_id=record["installation_id"],
                    activity_catalog=activity_catalog,
                    runtime_policy=runtime_policy,
                    source_principals=principals,
                    helper=helper,
                )
                activity_catalog, runtime_policy, principals, helper = self._workload_source_state(
                    workload_id
                )
                if runtime_policy is None:
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        "Package Runtime policy disappeared after activation.",
                        retryable=True,
                    )

            package_inventory = self._read_workload_package_inventory(
                workload_id,
                tuple(
                    sorted(
                        self._load_workload_resolver().potential_component_ids(
                            self.catalog, workload_id
                        )
                    )
                ),
            )
            active_bindings = {
                (binding.get("sourceId"), binding.get("bindingId")): binding.get(
                    "activeInstallationId"
                )
                for binding in package_inventory.get("sourceBindings", [])
                if isinstance(binding, dict)
            }
            for row in plugin_rows:
                source_id = self._workload_policy_source_id(row["sourcePolicy"])
                record = transaction.get("packageInstallations", {}).get(row["componentId"])
                if not isinstance(record, dict):
                    record = package_inventory.get("installationRecords", {}).get(
                        row["componentId"]
                    )
                if not isinstance(record, dict) or active_bindings.get(
                    (source_id, row["bindingId"])
                ) != record.get("installation_id"):
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        f"Active binding readback differs for {row['componentId']}.",
                        retryable=True,
                    )

        core_activation_needed = (
            bool(service_units)
            and (
                core_install_needed
                or any(
                    self._package_product_unit_state(service["unit"]) != "active"
                    for service in service_units
                )
            )
        ) or bool(oci_components)
        web_selected = any(row.get("artifactKind") == "static-web" for row in rows)
        if (core_activation_needed or web_selected) and self._ensure_workload_phase(
            transaction,
            transaction_path,
            phase="core-runtime-activate",
            target_kind="CORE_RUNTIME",
            requires_restart=bool(service_units or oci_components),
        ):
            try:
                for service in service_units:
                    unit = service["unit"]
                    state = self._package_product_unit_state(unit)
                    self._set_workload_unit(
                        unit, "restart" if state == "active" else "start", wait_active=True
                    )
                if CATALYST_COMPONENT_ID in selected_ids:
                    self._wait_http_health(8004, "/healthz", CATALYST_COMPONENT_ID)
                if web_selected and web_host is not None:
                    try:
                        transaction["hostMetadata"] = web_host.apply_web_host(
                            expected_state=transaction.get("webHostPriorState"),
                            durable_callback=self._journal_callback(
                                transaction, transaction_path, "hostEvents"
                            ),
                            runner=self._workload_web_host_runner,
                        )
                        transaction["webHostApplied"] = True
                        _atomic_json(transaction_path, transaction)
                    except Exception as error:
                        raise UpdateError(
                            "WORKLOAD_WEB_HOST_APPLY_FAILED",
                            "The selected Client Web host did not become ready.",
                            retryable=True,
                        ) from error
                if oci_components:
                    selected_echo = next(
                        (
                            item
                            for item in oci_components
                            if item.get("componentId") == WORKLOAD_ECHO_COMPONENT_ID
                        ),
                        None,
                    )
                    if not isinstance(selected_echo, dict):
                        raise UpdateError(
                            "INVALID_STAGE", "The Echo OCI activation identity is missing."
                        )
                    activity_catalog, source, principal = self._workload_echo_source_identity()
                    api_token = self._read_workload_echo_api_token()
                    if api_token is None:
                        raise UpdateError(
                            "WORKLOAD_ECHO_TOKEN_READBACK_REQUIRED",
                            "The protected Echo API bearer is unavailable during activation.",
                            retryable=True,
                        )
                    echo_package_inventory = self._read_workload_package_inventory(
                        "echo",
                        tuple(
                            sorted(
                                self._load_workload_resolver().potential_component_ids(
                                    self.catalog, "echo"
                                )
                            )
                        ),
                    )
                    package_inventory = echo_package_inventory
                    prior_echo = transaction.get("previousEchoReceipt")
                    prior_runner = (
                        prior_echo.get("runnerIdentity") if isinstance(prior_echo, dict) else None
                    )
                    connection_ref, runner_identity = self._workload_echo_runner_identity(
                        echo_package_inventory,
                        prior_identity=prior_runner if isinstance(prior_runner, dict) else None,
                    )
                    transaction["echoContainerIntent"] = {
                        "componentId": WORKLOAD_ECHO_COMPONENT_ID,
                        "planId": plan_id,
                        "planDigest": plan_digest,
                        "imageDigest": selected_echo["digest"],
                        "manifestDigest": selected_echo["manifestDigest"],
                        "activityCatalogGeneration": activity_catalog.get("generation"),
                    }
                    transaction["echoRunnerIdentity"] = runner_identity
                    _atomic_json(transaction_path, transaction)
                    spec = self._workload_echo_container_spec(
                        selected_echo,
                        activity_catalog,
                        source,
                        principal,
                        api_token=api_token[0],
                        connection_ref=connection_ref,
                        activity_generation=activity_catalog.get("generation"),
                    )
                    try:
                        helper = self._load_workload_oci_host()
                        observation = helper.start_container(spec, runner=self._workload_oci_runner)
                    except Exception as error:
                        raise UpdateError(
                            "WORKLOAD_OCI_START_FAILED",
                            "The verified Echo image did not start under its restricted host policy.",
                            retryable=True,
                        ) from error
                    if observation.state != "running":
                        raise UpdateError(
                            "WORKLOAD_ECHO_NOT_READY",
                            "The Echo OCI runtime did not report a running container.",
                            retryable=True,
                        )
                    echo_receipt = self._write_workload_echo_receipt(
                        selected_echo,
                        observation.to_receipt_fields(),
                        runner_identity=runner_identity,
                    )
                    echo_metadata = self._workload_echo_host_metadata(
                        echo_receipt, echo_package_inventory
                    )
                    if echo_metadata.get("available") is not True:
                        raise UpdateError(
                            "WORKLOAD_ECHO_NOT_READY",
                            "Echo failed its authenticated container identity or loopback liveness readback.",
                            retryable=True,
                        )
                    transaction["echoReceipt"] = echo_receipt
                    transaction["echoHostMetadata"] = echo_metadata
                    transaction["echoContainerStarted"] = True
                    _atomic_json(transaction_path, transaction)
                self._end_workload_hold(
                    transaction, transaction_path, outcome="SUCCESS", healthy=True
                )
            except Exception as error:
                transaction["phase"] = "applying"
                _atomic_json(transaction_path, transaction)
                self._recover_workload_apply(transaction, transaction_path, failure=error)
                raise

        host_metadata: dict[str, Any] = {}
        if isinstance(transaction.get("hostMetadata"), dict):
            host_metadata["web"] = transaction["hostMetadata"]
        if isinstance(transaction.get("echoHostMetadata"), dict):
            host_metadata["echo"] = transaction["echoHostMetadata"]
        result = {
            "status": "activated"
            if (service_units or plugin_rows or web_selected or oci_components)
            else "installed",
            "action": "install",
            "planId": plan_id,
            "planDigest": plan_digest,
            "catalogDigest": stored["catalogDigest"],
            "workloadId": workload_id,
            "targetId": target_id,
            "channel": stored["channel"],
            "components": rows,
            "resolution": resolution,
            "sourceBindings": package_inventory.get("sourceBindings", []),
            **({"hostMetadata": host_metadata} if host_metadata else {}),
        }
        transaction["result"] = result
        transaction["phase"] = "succeeded"
        transaction.pop("maintenanceToken", None)
        transaction.pop("recoveryError", None)
        _atomic_json(transaction_path, transaction)
        stored["phase"] = "applied"
        stored["applyResult"] = result
        _atomic_json(self._workload_plan_directory() / f"{plan_id}.json", stored)
        return result

    def _apply_workload_install_locked(
        self, stored: dict[str, Any], confirmation: dict[str, Any]
    ) -> dict[str, Any]:
        """Apply typed Product and static-web payloads with recoverable pointers.

        Plugin Package Runtime activation is intentionally handled by its authenticated
        owner path and is rejected here until the exact source-policy transaction is
        available. This prevents a partial Catalyst install from masquerading as a
        completed workload.
        """

        return self._apply_workload_install_assembled(stored, confirmation)

        plan_id = stored["planId"]
        plan_digest = stored["planDigest"]
        workload_id = stored["workloadId"]
        target_id = stored["targetId"]
        resolution, candidates, _package_inventory = self._build_workload_plan(
            workload_id,
            target_id,
            stored.get("selections"),
            action="install",
            channel=stored.get("channel"),
        )
        if resolution.get("status") != "ready" or resolution.get("planDigest") != plan_digest:
            raise UpdateError(
                "PLAN_CHANGED",
                "The installed workload resolution changed; check and stage again.",
                retryable=True,
            )
        rows = resolution.get("selectedComponents")
        staged_rows = stored.get("stagedComponents")
        if not isinstance(rows, list) or not isinstance(staged_rows, list):
            raise UpdateError("INVALID_STAGE", "The staged workload component set is malformed.")
        staged_by_id = {
            row.get("componentId"): row
            for row in staged_rows
            if isinstance(row, dict) and isinstance(row.get("componentId"), str)
        }
        if len(staged_by_id) != len(staged_rows):
            raise UpdateError(
                "INVALID_STAGE", "The staged workload contains duplicate component IDs."
            )
        selected_ids = {row.get("componentId") for row in rows if isinstance(row, dict)}
        if set(staged_by_id) != selected_ids:
            raise UpdateError(
                "INVALID_STAGE", "The staged workload does not match the selected component set."
            )
        if not _running_as_root():
            raise UpdateError(
                "PRIVILEGE_REQUIRED",
                "Applying a workload requires the root-owned local update helper.",
            )

        pending_packages = [
            component_id
            for component_id, staged in staged_by_id.items()
            if staged.get("artifactKind") == "plugin-package" and staged.get("status") != "current"
        ]
        if pending_packages:
            raise UpdateError(
                "PACKAGE_OWNER_PATH_UNAVAILABLE",
                "Plugin packages are verified and staged, but their authenticated owner-source transaction is not available yet.",
                retryable=True,
            )
        unsupported = [
            component_id
            for component_id, staged in staged_by_id.items()
            if staged.get("status") != "current"
            and staged.get("artifactKind") not in {"native-binary", "python-bundle", "static-web"}
            and component_id != WORKLOAD_SDK_COMPONENT_ID
        ]
        if unsupported:
            raise UpdateError(
                "WORKLOAD_ARTIFACT_UNAVAILABLE",
                "No installed Ubuntu workload supervisor is configured for: "
                + ", ".join(sorted(unsupported)),
                retryable=True,
            )

        transaction_path = self._private_state_directory("transactions") / f"{plan_id}.json"
        if transaction_path.exists() or transaction_path.is_symlink():
            transaction = _read_object(transaction_path, "workload transaction")
            if (
                transaction.get("transactionKind") != "workload-assembly.v1"
                or transaction.get("planId") != plan_id
                or transaction.get("planDigest") != plan_digest
                or transaction.get("workloadId") != workload_id
            ):
                raise UpdateError(
                    "PENDING_MAINTENANCE",
                    "A different transaction occupies this workload plan.",
                    retryable=True,
                )
            if transaction.get("phase") == "succeeded":
                return transaction["result"]
            if transaction.get("phase") == "rolled_back":
                raise UpdateError(
                    "APPLY_ROLLED_BACK",
                    transaction.get(
                        "rollbackMessage", "The previous workload attempt rolled back."
                    ),
                )
            if transaction.get("phase") == "success_end_pending":
                self._health_transaction(transaction)
                self._end_maintenance(transaction, outcome="SUCCESS", healthy=True)
                transaction["phase"] = "succeeded"
                transaction.pop("maintenanceToken", None)
                _atomic_json(transaction_path, transaction)
                stored["phase"] = "applied"
                stored["applyResult"] = transaction["result"]
                _atomic_json(self._workload_plan_directory() / f"{plan_id}.json", stored)
                return transaction["result"]
            if transaction.get("phase") not in {"begin_pending", "applying"}:
                raise UpdateError(
                    "PENDING_MAINTENANCE",
                    "The workload journal needs exact recovery before retry.",
                    retryable=True,
                )
            if transaction.get("phase") == "applying":
                self._recover_workload_apply(transaction, transaction_path)
                raise UpdateError(
                    "INTERRUPTED_WORKLOAD_ROLLED_BACK",
                    "The interrupted workload transaction was restored; recheck and stage a new plan.",
                )
        else:
            transaction = None

        native_components: list[dict[str, Any]] = []
        web_components: list[dict[str, Any]] = []
        all_new: list[dict[str, Any]] = []
        sdk_entry: tuple[dict[str, Any], dict[str, Any]] | None = None
        for row in rows:
            component_id = row["componentId"]
            staged = staged_by_id[component_id]
            if staged.get("status") == "current":
                continue
            candidate = candidates.get(component_id)
            if candidate is None:
                raise UpdateError(
                    "PLAN_CHANGED", f"Candidate disappeared for {component_id}.", retryable=True
                )
            if component_id == WORKLOAD_SDK_COMPONENT_ID:
                sdk_entry = (row, staged)
                all_new.append(
                    {"componentId": component_id, "artifactDigest": candidate.artifact_digest}
                )
                continue
            identity = staged.get("stagedIdentity")
            if not isinstance(identity, dict):
                raise UpdateError(
                    "INVALID_STAGE", f"Staged identity is missing for {component_id}."
                )
            item = {
                "componentId": component_id,
                "version": candidate.manifest["version"],
                "manifestDigest": candidate.manifest_digest,
                "releaseIdentity": candidate.manifest_digest,
                "artifactDigest": candidate.artifact_digest,
                "restartGroup": self.components[component_id]["restart"]["group"],
                "pointerIdentity": identity.get("pointerIdentity", identity.get("releaseIdentity")),
                "bundleIdentity": identity.get("bundleIdentity"),
                "manifest": candidate.manifest,
                "releasePath": identity.get("releasePath"),
                "archivePath": identity.get("archivePath"),
            }
            item.update(self._workload_receipt_fields(candidate, row))
            if staged.get("artifactKind") == "static-web":
                item["pointerIdentity"] = identity.get("releaseIdentity")
                item["bundleIdentity"] = None
                web_components.append(item)
            else:
                component = self.components.get(component_id)
                if (
                    not isinstance(component, dict)
                    or component.get("kind") not in {"native-binary", "python-bundle"}
                    or component.get("activation") not in (None, "systemd")
                ):
                    raise UpdateError(
                        "WORKLOAD_ARTIFACT_UNAVAILABLE",
                        f"No native Product activation is configured for {component_id}.",
                    )
                native_components.append(item)
            all_new.append(
                {"componentId": component_id, "artifactDigest": candidate.artifact_digest}
            )

        if not native_components and not web_components and sdk_entry is None:
            active_product = any(
                isinstance(self.components.get(row.get("componentId")), dict)
                and self.components[row["componentId"]].get("systemdUnit")
                for row in rows
                if isinstance(row, dict)
            )
            return {
                "status": "activated" if active_product else "installed",
                "action": "install",
                "planId": plan_id,
                "planDigest": plan_digest,
                "catalogDigest": stored["catalogDigest"],
                "workloadId": workload_id,
                "targetId": target_id,
                "channel": stored["channel"],
                "components": rows,
                "resolution": resolution,
            }

        if native_components:
            self._require_managed_services(native_components)
        target_kind = (
            "CORE_RUNTIME"
            if any(item["restartGroup"] == "core-runtime" for item in native_components)
            else "PACKAGE_ONLY"
        )
        readiness = self._readiness_for(
            target_kind, requires_restart=bool(native_components), force=True
        )
        self._require_ready(readiness, target_kind)
        activity_catalog, activity_sources = self._activity_catalog()
        if readiness.get("install_catalog_generation") != activity_catalog.get("generation"):
            raise UpdateError(
                "GATE_UNKNOWN",
                "Activity source generation changed during workload readiness.",
                retryable=True,
            )
        if transaction is None:
            transaction = {
                "schemaVersion": 2,
                "transactionKind": "workload-assembly.v1",
                "planId": plan_id,
                "requestId": "cyrene-update-" + plan_id,
                "planDigest": plan_digest,
                "workloadId": workload_id,
                "targetId": target_id,
                "action": "install",
                "componentArtifactDigests": {
                    row["componentId"]: row["artifactDigest"] for row in all_new
                },
                "phase": "begin_pending",
                "targetKind": target_kind,
                "channel": stored["channel"],
                "expectedGateGeneration": readiness.get("gate_generation"),
                "expectedCatalogGeneration": activity_catalog["generation"],
                "expectedActivitySources": activity_sources,
                "components": native_components,
                "requiresRestart": bool(native_components),
                "webComponents": web_components,
                "previous": self._capture_active_versions(native_components),
                "previousWeb": [
                    self._capture_workload_web_identity(item["componentId"])
                    for item in web_components
                ],
                "sdkComponent": sdk_entry[0] if sdk_entry else None,
                "sdkStage": sdk_entry[1]["stagedIdentity"] if sdk_entry else None,
                "resolution": resolution,
                "phaseStartedAt": int(time.time()),
            }
            _atomic_json(transaction_path, transaction)

        if sdk_entry is not None and "sdkEnvironment" not in transaction:
            sdk_module = self._load_workload_sdk_environment()
            transaction["phase"] = "operator_sdk_prepare_pending"
            _atomic_json(transaction_path, transaction)
            try:
                transaction["sdkEnvironment"] = sdk_module.prepare_workload_sdk_environment(
                    sdk_entry[0], sdk_entry[1]["stagedIdentity"]
                )
            except Exception as error:
                transaction["recoveryError"] = str(error)[:500]
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "WORKLOAD_SDK_INSTALL_FAILED",
                    "The verified operator SDK could not be prepared.",
                    retryable=True,
                ) from error
            transaction["phase"] = "begin_pending"
            _atomic_json(transaction_path, transaction)

        if not transaction.get("maintenanceToken"):
            try:
                transaction["maintenanceToken"] = self._begin_maintenance(transaction)
            except UpdateError as error:
                if error.maintenance_not_acquired:
                    self._clear_begin_pending(transaction, transaction_path)
                raise
        transaction["phase"] = "applying"
        _atomic_json(transaction_path, transaction)
        try:
            self._activate_transaction(transaction)
            for item in web_components:
                previous = next(
                    row
                    for row in transaction["previousWeb"]
                    if row["componentId"] == item["componentId"]
                )
                self._activate_workload_web(item, expected_current=previous["pointerIdentity"])
            self._restart_transaction(transaction)
            self._health_transaction(transaction)
        except Exception as failure:
            healthy, rollback_message = self._recover_workload_apply(
                transaction, transaction_path, failure=failure
            )
            raise UpdateError(
                "APPLY_ROLLED_BACK" if healthy else "ROLLBACK_UNHEALTHY",
                f"Workload apply failed ({failure}). {rollback_message}",
                retryable=not healthy,
            ) from failure

        result = {
            "status": "activated" if native_components else "installed",
            "action": "install",
            "planId": plan_id,
            "planDigest": plan_digest,
            "catalogDigest": stored["catalogDigest"],
            "workloadId": workload_id,
            "targetId": target_id,
            "channel": stored["channel"],
            "components": rows,
            "resolution": resolution,
        }
        transaction["result"] = result
        transaction["phase"] = "success_end_pending"
        _atomic_json(transaction_path, transaction)
        try:
            self._end_maintenance(transaction, outcome="SUCCESS", healthy=True)
        except UpdateError as error:
            transaction["recoveryError"] = str(error)
            _atomic_json(transaction_path, transaction)
            raise UpdateError(
                "GATE_END_PENDING",
                "Workload releases are healthy but maintenance completion remains pending.",
                retryable=True,
            ) from error
        transaction["phase"] = "succeeded"
        transaction.pop("maintenanceToken", None)
        transaction.pop("recoveryError", None)
        _atomic_json(transaction_path, transaction)
        stored["phase"] = "applied"
        stored["applyResult"] = result
        _atomic_json(self._workload_plan_directory() / f"{plan_id}.json", stored)
        return result

    def _capture_workload_web_identity(self, component_id: str) -> dict[str, Any]:
        """Capture the exact active web pointer and receipt for transaction rollback."""

        installed = self._installed_static_web(self.components[component_id])
        if installed.get("active") is not True:
            return {
                "componentId": component_id,
                "version": None,
                "releaseIdentity": None,
                "manifestDigest": None,
                "artifactDigest": None,
                "pointerIdentity": None,
                "bundleIdentity": None,
                "identityAttested": False,
            }
        receipt = self._read_active_receipt(component_id)
        if receipt is None:
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Static-web active receipt is missing for {component_id}.",
            )
        return {
            "componentId": component_id,
            "version": receipt["version"],
            "releaseIdentity": receipt["releaseIdentity"],
            "manifestDigest": receipt["manifestDigest"],
            "artifactDigest": receipt["artifactDigest"],
            "pointerIdentity": receipt["pointerIdentity"],
            "bundleIdentity": None,
            "identityAttested": True,
        }

    def _activate_workload_web(self, item: dict[str, Any], *, expected_current: str | None) -> None:
        """Atomically switch the active static-web release to one verified tree."""

        component_id = item["componentId"]
        component_root = DEFAULT_WORKLOAD_WEB_ROOT / component_id
        current_path = component_root / "current"
        if current_path.exists() or current_path.is_symlink():
            info = current_path.lstat()
            if not stat.S_ISLNK(info.st_mode) or info.st_uid != 0:
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE", f"Static-web pointer is unsafe for {component_id}."
                )
            active_target = os.readlink(current_path)
            match = re.fullmatch(r"releases/([A-Za-z0-9][A-Za-z0-9._-]{0,511})", active_target)
            actual_current = match.group(1) if match else None
            if actual_current is None:
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE",
                    f"Static-web pointer target is unsafe for {component_id}.",
                )
        else:
            actual_current = None
        if actual_current != expected_current:
            raise UpdateError(
                "ACTIVE_VERSION_CHANGED",
                f"Static-web active pointer changed for {component_id}.",
                retryable=True,
            )
        release_identity = item.get("pointerIdentity")
        release_path = Path(item.get("releasePath", ""))
        expected_path = component_root / "releases" / str(release_identity)
        if (
            not isinstance(release_identity, str)
            or release_path != expected_path
            or release_path.is_symlink()
            or not release_path.is_dir()
        ):
            raise UpdateError(
                "INVALID_STAGE", f"Static-web staged release path is unsafe for {component_id}."
            )
        artifact = item["manifest"].get("artifact", {})
        self._verify_static_web_tree(release_path, artifact.get("files"))
        temporary = component_root / f".current-{uuid.uuid4().hex}"
        os.symlink(f"releases/{release_identity}", temporary)
        try:
            os.replace(temporary, current_path)
            self._fsync_directory(component_root)
        finally:
            if temporary.exists() or temporary.is_symlink():
                temporary.unlink()
        self._write_active_receipt(item)

    def _rollback_workload_web(self, transaction: dict[str, Any]) -> None:
        """Restore every web pointer only when it still names this transaction."""

        previous_rows = {
            row["componentId"]: row
            for row in transaction.get("previousWeb", [])
            if isinstance(row, dict) and isinstance(row.get("componentId"), str)
        }
        for item in transaction.get("webComponents", []):
            component_id = item["componentId"]
            root = DEFAULT_WORKLOAD_WEB_ROOT / component_id
            current = root / "current"
            previous = previous_rows.get(component_id)
            if previous is None:
                raise UpdateError(
                    "TRANSACTION_IDENTITY_UNKNOWN", "Workload journal omitted prior web identity."
                )
            actual: str | None = None
            if current.exists() or current.is_symlink():
                if not current.is_symlink():
                    raise UpdateError(
                        "ROLLBACK_CONFLICT",
                        f"Static-web pointer is no longer a symlink for {component_id}.",
                    )
                target = os.readlink(current)
                match = re.fullmatch(r"releases/([A-Za-z0-9][A-Za-z0-9._-]{0,511})", target)
                if match is None:
                    raise UpdateError(
                        "ROLLBACK_CONFLICT",
                        f"Static-web pointer is outside the transaction for {component_id}.",
                    )
                actual = match.group(1)
            candidate = item["pointerIdentity"]
            old = previous.get("pointerIdentity")
            if actual not in {candidate, old}:
                raise UpdateError(
                    "ROLLBACK_CONFLICT",
                    f"Static-web pointer changed outside the transaction for {component_id}.",
                )
            if old is None:
                if actual is not None:
                    current.unlink()
                    self._fsync_directory(root)
                self._clear_active_receipt(component_id)
                continue
            temporary = root / f".current-rollback-{uuid.uuid4().hex}"
            os.symlink(f"releases/{old}", temporary)
            try:
                os.replace(temporary, current)
                self._fsync_directory(root)
            finally:
                if temporary.exists() or temporary.is_symlink():
                    temporary.unlink()
            self._restore_active_receipt(component_id, previous)

    def _recover_workload_apply(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        *,
        failure: Exception | None = None,
    ) -> tuple[bool, str]:
        """Rollback interrupted Product/web pointers and release their exact hold."""

        messages: list[str] = []
        healthy = True
        try:
            self._rollback_workload_echo_container(transaction, transaction_path)
        except (OSError, RuntimeError, ValueError) as error:
            healthy = False
            messages.append(f"Echo OCI rollback could not be verified: {error}")
        defer_owner_recovery = bool(transaction.get("maintenanceToken"))
        if not defer_owner_recovery:
            try:
                self._restore_workload_package_bindings(transaction, transaction_path)
            except RuntimeError as error:
                healthy = False
                messages.append(f"Package Runtime owner rollback could not be verified: {error}")
            try:
                self._restore_workload_sdk_environment(transaction, transaction_path)
            except UpdateError as error:
                healthy = False
                messages.append(f"Operator SDK rollback could not be verified: {error}")
        try:
            self._restore_workload_service_units(transaction)
        except UpdateError as error:
            healthy = False
            messages.append(f"Signed service unit rollback could not be verified: {error}")
        try:
            self._restore_workload_catalyst_auth(transaction)
        except UpdateError as error:
            healthy = False
            messages.append(f"Catalyst auth projection rollback could not be verified: {error}")
        if transaction.get("webHostApplied") is True:
            try:
                host = self._load_workload_web_host()
                prior_state = transaction.get("webHostPriorState")
                host_metadata = transaction.get("hostMetadata")
                current_digest = (
                    host_metadata.get("configDigest") if isinstance(host_metadata, dict) else None
                )
                if not isinstance(prior_state, dict) or not _valid_digest(current_digest):
                    raise UpdateError(
                        "INVALID_TRANSACTION", "Web host rollback identity is incomplete."
                    )
                host.rollback_web_host(
                    prior_state=prior_state,
                    expected_current_digest=current_digest,
                    runner=self._workload_web_host_runner,
                )
            except RuntimeError as error:
                healthy = False
                messages.append(f"Web host rollback could not be verified: {error}")
        if transaction.get("components"):
            pointer_healthy, message = self._rollback_transaction(transaction)
            healthy = healthy and pointer_healthy
            messages.append(message)
        try:
            self._rollback_workload_web(transaction)
        except UpdateError as error:
            healthy = False
            messages.append(f"Static-web rollback could not be verified: {error}")
        if transaction.get("maintenanceToken"):
            transaction["phase"] = "rollback_end_pending" if healthy else "rollback_required"
            transaction["rollbackMessage"] = "; ".join(messages)
            _atomic_json(transaction_path, transaction)
            try:
                if transaction.get("transactionKind") == "workload-assembly.v1":
                    self._end_workload_hold(
                        transaction,
                        transaction_path,
                        outcome="ROLLED_BACK" if healthy else "FAILED",
                        healthy=healthy,
                    )
                else:
                    self._end_maintenance(
                        transaction,
                        outcome="ROLLED_BACK" if healthy else "FAILED",
                        healthy=healthy,
                    )
            except UpdateError as error:
                healthy = False
                messages.append(f"Maintenance completion is pending: {error}")
        if (
            defer_owner_recovery
            and healthy
            and not transaction.get("maintenanceToken")
            and transaction.get("packageRuntimeStarted") is not True
            and transaction.get("packageRuntimePriorState") == "active"
        ):
            try:
                self._workload_runtime_daemon("start", wait_active=True)
                transaction["packageRuntimeStarted"] = True
                _atomic_json(transaction_path, transaction)
            except UpdateError as error:
                healthy = False
                messages.append(f"Package Runtime service recovery is pending: {error}")
        if defer_owner_recovery and healthy and not transaction.get("maintenanceToken"):
            try:
                self._restore_workload_package_bindings(transaction, transaction_path)
            except RuntimeError as error:
                healthy = False
                messages.append(f"Package Runtime owner rollback could not be verified: {error}")
            if healthy:
                try:
                    self._restore_workload_sdk_environment(transaction, transaction_path)
                except UpdateError as error:
                    healthy = False
                    messages.append(f"Operator SDK rollback could not be verified: {error}")
        transaction["phase"] = "rolled_back" if healthy else "rollback_required"
        transaction["rollbackMessage"] = (
            "; ".join(messages) or "No workload pointer change required recovery."
        )
        transaction.pop("maintenanceToken", None)
        _atomic_json(transaction_path, transaction)
        return healthy, transaction["rollbackMessage"]

    def _rollback_workload_echo_container(
        self, transaction: dict[str, Any], transaction_path: Path
    ) -> None:
        """Remove only a first-install Echo container started by this journal."""

        intent = transaction.get("echoContainerIntent")
        if not isinstance(intent, dict) or transaction.get("previousEchoReceipt") is not None:
            return
        selected = next(
            (
                row
                for row in transaction.get("ociComponents", [])
                if isinstance(row, dict) and row.get("componentId") == WORKLOAD_ECHO_COMPONENT_ID
            ),
            None,
        )
        if (
            not isinstance(selected, dict)
            or intent.get("componentId") != WORKLOAD_ECHO_COMPONENT_ID
            or intent.get("planId") != transaction.get("planId")
            or intent.get("planDigest") != transaction.get("planDigest")
            or intent.get("imageDigest") != selected.get("digest")
            or intent.get("manifestDigest") != selected.get("manifestDigest")
            or type(intent.get("activityCatalogGeneration")) is not int
        ):
            raise UpdateError("INVALID_TRANSACTION", "Echo rollback intent is malformed.")
        current = self._read_workload_echo_receipt()
        if isinstance(current, dict) and current.get("imageDigest") != intent["imageDigest"]:
            raise UpdateError(
                "UNINSTALL_CONFLICT", "A different Echo image replaced this workload transaction."
            )
        activity_catalog, source, principal = self._workload_echo_source_identity()
        if activity_catalog.get("generation") != intent["activityCatalogGeneration"]:
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Echo ActivitySource generation changed during container rollback.",
                retryable=True,
            )
        api_token = self._read_workload_echo_api_token()
        if api_token is None:
            raise UpdateError(
                "WORKLOAD_ECHO_TOKEN_READBACK_REQUIRED",
                "The protected Echo API bearer is unavailable for rollback.",
                retryable=True,
            )
        runner_identity = transaction.get("echoRunnerIdentity")
        connection_ref: str | None = None
        if isinstance(runner_identity, dict):
            package_ids = tuple(
                sorted(self._load_workload_resolver().potential_component_ids(self.catalog, "echo"))
            )
            package_inventory = self._read_workload_package_inventory("echo", package_ids)
            connection_ref, recovered_identity = self._workload_echo_runner_identity(
                package_inventory,
                prior_identity=runner_identity,
            )
            if recovered_identity != runner_identity or connection_ref is None:
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "Echo's selected runner reference cannot be recovered safely.",
                    retryable=True,
                )
        spec = self._workload_echo_container_spec(
            selected,
            activity_catalog,
            source,
            principal,
            api_token=api_token[0],
            connection_ref=connection_ref,
            activity_generation=intent["activityCatalogGeneration"],
        )
        helper = self._load_workload_oci_host()
        removal = helper.remove_container(
            spec,
            runner=self._workload_oci_runner,
            remove_runtime_credentials=True,
        )
        if removal.state != "not-installed":
            raise UpdateError(
                "WORKLOAD_OCI_REMOVE_FAILED",
                "Echo container rollback did not confirm the exact container removal.",
                retryable=True,
            )
        self._clear_workload_echo_receipt(intent["imageDigest"])
        transaction["echoContainerRemovedOnRollback"] = True
        _atomic_json(transaction_path, transaction)

    def _restore_workload_package_bindings(
        self, transaction: dict[str, Any], transaction_path: Path
    ) -> None:
        """Restore only selected owner bindings captured before this transaction."""

        previous = transaction.get("previousPackageBindings", [])
        selected_rows = transaction.get("selectedPluginRows", [])
        if not isinstance(previous, list) or not isinstance(selected_rows, list):
            raise UpdateError(
                "INVALID_TRANSACTION", "Package Runtime rollback identity is malformed."
            )
        if not previous:
            return
        if transaction.get("maintenanceToken"):
            raise UpdateError(
                "PENDING_MAINTENANCE",
                "Package Runtime bindings cannot be reconciled while a maintenance hold is active.",
                retryable=True,
            )
        if self._package_product_unit_state(WORKLOAD_PACKAGE_RUNTIME_UNIT) != "active":
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Package Runtime must be active before owner binding recovery.",
                retryable=True,
            )
        if not previous:
            return
        rows_by_id = {
            row.get("componentId"): row
            for row in selected_rows
            if isinstance(row, dict) and isinstance(row.get("componentId"), str)
        }
        selected_owner_keys = {
            (row.get("sourceId"), row.get("bindingId")) for row in previous if isinstance(row, dict)
        }
        inventory = self._read_workload_package_inventory(
            transaction["workloadId"],
            tuple(
                sorted(
                    self._load_workload_resolver().potential_component_ids(
                        self.catalog, transaction["workloadId"]
                    )
                )
            ),
        )
        activity_catalog, runtime_policy, principals, helper = self._workload_source_state(
            transaction["workloadId"]
        )
        if runtime_policy is None:
            raise UpdateError(
                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                "Package Runtime policy is unavailable for owner rollback.",
                retryable=True,
            )
        for original in previous:
            if not isinstance(original, dict):
                raise UpdateError(
                    "INVALID_TRANSACTION", "Package Runtime prior owner row is malformed."
                )
            component_id = original.get("componentId")
            row = rows_by_id.get(component_id)
            source_id = original.get("sourceId")
            binding_id = original.get("bindingId")
            desired_id = original.get("activeInstallationId")
            if (
                not isinstance(component_id, str)
                or not isinstance(row, dict)
                or not isinstance(source_id, str)
                or not isinstance(binding_id, str)
                or (desired_id is not None and not isinstance(desired_id, str))
            ):
                raise UpdateError(
                    "INVALID_TRANSACTION", "Package Runtime prior owner identity is incomplete."
                )
            for binding in inventory.get("sourceBindings", []):
                if not isinstance(binding, dict):
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        "Package Runtime owner readback is malformed.",
                        retryable=True,
                    )
                if (
                    binding.get("state") == "RUNNING"
                    and (binding.get("sourceId"), binding.get("bindingId"))
                    not in selected_owner_keys
                ):
                    raise UpdateError(
                        "COMPONENT_IN_USE",
                        "Another Package Runtime owner is active during rollback.",
                        retryable=True,
                    )
            current = next(
                (
                    binding
                    for binding in inventory.get("sourceBindings", [])
                    if isinstance(binding, dict)
                    and binding.get("sourceId") == source_id
                    and binding.get("bindingId") == binding_id
                ),
                None,
            )
            current_id = (
                current.get("activeInstallationId")
                if isinstance(current, dict) and current.get("state") == "RUNNING"
                else None
            )
            if current_id == desired_id:
                continue
            target_id = desired_id or current_id
            if not isinstance(target_id, str):
                continue
            operation = "activate" if desired_id is not None else "deactivate"
            self._workload_binding_operation(
                transaction,
                transaction_path,
                operation=operation,
                component=row,
                installation_id=target_id,
                activity_catalog=activity_catalog,
                runtime_policy=runtime_policy,
                source_principals=principals,
                helper=helper,
            )
            inventory = self._read_workload_package_inventory(
                transaction["workloadId"],
                tuple(
                    sorted(
                        self._load_workload_resolver().potential_component_ids(
                            self.catalog, transaction["workloadId"]
                        )
                    )
                ),
            )
            activity_catalog, runtime_policy, principals, helper = self._workload_source_state(
                transaction["workloadId"]
            )
            if runtime_policy is None:
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "Package Runtime policy disappeared during owner rollback.",
                    retryable=True,
                )
            recovered = next(
                (
                    binding
                    for binding in inventory.get("sourceBindings", [])
                    if isinstance(binding, dict)
                    and binding.get("sourceId") == source_id
                    and binding.get("bindingId") == binding_id
                ),
                None,
            )
            recovered_id = (
                recovered.get("activeInstallationId")
                if isinstance(recovered, dict) and recovered.get("state") == "RUNNING"
                else None
            )
            if recovered_id != desired_id:
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "Package Runtime rollback did not restore the prior active installation.",
                    retryable=True,
                )

    def _apply_workload_uninstall_locked(
        self, stored: dict[str, Any], confirmation: dict[str, Any]
    ) -> dict[str, Any]:
        """Remove one exact, authenticated workload component and retain user data."""

        plan_id = stored["planId"]
        plan_digest = stored["planDigest"]
        workload_id = stored["workloadId"]
        target_id = stored["targetId"]
        transaction_path = self._private_state_directory("transactions") / f"{plan_id}.json"
        transaction: dict[str, Any] | None = None
        if transaction_path.exists() or transaction_path.is_symlink():
            transaction = _read_object(transaction_path, "workload uninstall transaction")
            if (
                transaction.get("transactionKind") != "workload-assembly.v1"
                or transaction.get("action") != "uninstall"
                or transaction.get("planId") != plan_id
                or transaction.get("planDigest") != plan_digest
                or transaction.get("workloadId") != workload_id
            ):
                raise UpdateError(
                    "PENDING_MAINTENANCE",
                    "A different transaction occupies this uninstall plan.",
                    retryable=True,
                )
            if transaction.get("phase") == "succeeded":
                return transaction["result"]
            uninstall_hold = transaction.get("maintenanceHolds", {}).get("core-runtime-uninstall")
            if (
                isinstance(uninstall_hold, dict)
                and uninstall_hold.get("status") in {"begin_pending", "active", "end_pending"}
                and transaction.get("maintenanceToken")
                and transaction.get("offlineUninstallIntent") is True
            ):
                self._resume_workload_package_uninstall_phase(transaction, transaction_path)
            elif (
                isinstance(uninstall_hold, dict)
                and uninstall_hold.get("status") == "ended"
                and transaction.get("packageRuntimeStarted") is not True
                and transaction.get("offlineUninstallIntent") is True
            ):
                self._workload_runtime_daemon("start", wait_active=True)
                transaction["packageRuntimeStarted"] = True
                _atomic_json(transaction_path, transaction)

        resolution, _candidates, package_inventory = self._build_workload_plan(
            workload_id,
            target_id,
            stored.get("selections"),
            action="uninstall",
            channel=stored.get("channel"),
        )
        rows = resolution.get("selectedComponents") if isinstance(resolution, dict) else None
        staged_rows = stored.get("stagedComponents")
        if transaction is not None and (
            transaction.get("offlineUninstallIntent") is True
            or transaction.get("echoUninstallIntent") is True
        ):
            rows = [transaction.get("selectedRow")]
            staged_rows = [transaction.get("stagedRow")]
            resolution = transaction["resolution"]
        if (
            not isinstance(rows, list)
            or len(rows) != 1
            or not isinstance(staged_rows, list)
            or len(staged_rows) != 1
        ):
            # An offline uninstall can complete immediately before a crash. In
            # that narrow case continue only from the exact durable owner identity
            # and component row that was written before the first mutation.
            if (
                transaction is None
                or not isinstance(transaction.get("selectedRow"), dict)
                or not isinstance(transaction.get("stagedRow"), dict)
                or not (
                    transaction.get("offlineUninstallIntent") is True
                    and isinstance(transaction.get("installation"), dict)
                    or transaction.get("echoUninstallIntent") is True
                )
            ):
                raise UpdateError(
                    "PLAN_CHANGED",
                    "The exact installed workload identity is unavailable for uninstall.",
                    retryable=True,
                )
            rows = [transaction["selectedRow"]]
            staged_rows = [transaction["stagedRow"]]
            resolution = transaction["resolution"]
        row = rows[0]
        staged = staged_rows[0]
        if (
            not isinstance(row, dict)
            or not isinstance(staged, dict)
            or row.get("componentId") != staged.get("componentId")
        ):
            raise UpdateError(
                "INVALID_STAGE", "The selected uninstall identity differs from its staged plan."
            )
        if resolution.get("status") != "ready" and not (
            transaction is not None
            and (
                transaction.get("offlineUninstallIntent") is True
                or transaction.get("echoUninstallIntent") is True
            )
        ):
            raise UpdateError(
                "WORKLOAD_UNINSTALL_BLOCKED",
                "The installed component is in use or its owner identity cannot be verified.",
                retryable=True,
            )
        if not _running_as_root():
            raise UpdateError(
                "PRIVILEGE_REQUIRED",
                "Applying a workload uninstall requires the root-owned update helper.",
            )

        component_id = row.get("componentId")
        artifact_kind = row.get("artifactKind")
        if not isinstance(component_id, str) or artifact_kind not in {
            "plugin-package",
            "static-web",
            "oci-image",
        }:
            raise UpdateError(
                "WORKLOAD_UNINSTALL_UNAVAILABLE",
                "This component kind has no registered owner-specific uninstall adapter.",
                retryable=True,
            )

        component_digest = row.get("digest")
        if transaction is not None and artifact_kind == "oci-image":
            component_digests = transaction.get("componentArtifactDigests")
            if (
                not isinstance(component_digests, dict)
                or component_digests.get(component_id) != component_digest
            ):
                raise UpdateError(
                    "INVALID_TRANSACTION",
                    "Echo uninstall digest differs from its durable transaction identity.",
                )
        if transaction is None:
            component_digest = row.get("digest")
            package_identity = row.get("installedIdentity")
            installation: dict[str, Any] | None = None
            source_id: str | None = None
            echo_receipt: dict[str, Any] | None = None
            if artifact_kind == "plugin-package":
                if not isinstance(package_identity, dict):
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        "Uninstall has no authenticated installation identity.",
                        retryable=True,
                    )
                installation_id = row.get("installationId")
                records = package_inventory.get("installationRecords", {})
                installation = records.get(component_id) if isinstance(records, dict) else None
                if (
                    not isinstance(installation, dict)
                    or installation.get("installation_id") != installation_id
                    or package_identity.get("installationId") != installation_id
                    or installation.get("package_id") != row.get("packageId")
                    or installation.get("package_version") != row.get("version")
                    or installation.get("archive_digest") != row.get("digest")
                ):
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        "Fresh Package Runtime readback differs from the selected uninstall identity.",
                        retryable=True,
                    )
                component_digest = installation.get("artifact_digest")
                row = {**row, "packageArtifactDigest": component_digest}
                source_id = self._workload_policy_source_id(row.get("sourcePolicy", {}))
                if not _valid_digest(component_digest) or not isinstance(source_id, str):
                    raise UpdateError(
                        "SOURCE_BINDING_INVALID", "Uninstall package owner mapping is incomplete."
                    )
            elif artifact_kind == "oci-image":
                if component_id != WORKLOAD_ECHO_COMPONENT_ID:
                    raise UpdateError(
                        "WORKLOAD_UNINSTALL_UNAVAILABLE",
                        "No OCI uninstall adapter is registered for this component.",
                    )
                echo_receipt = self._read_workload_echo_receipt()
                installed_identity = row.get("installedIdentity")
                if (
                    not isinstance(echo_receipt, dict)
                    or not isinstance(installed_identity, dict)
                    or echo_receipt.get("digest") != row.get("digest")
                    or echo_receipt.get("manifestDigest") != row.get("manifestDigest")
                    or echo_receipt.get("releaseId") != row.get("releaseId")
                    or installed_identity.get("imageDigest") != echo_receipt.get("imageDigest")
                    or not _valid_digest(component_digest)
                ):
                    raise UpdateError(
                        "WORKLOAD_OCI_READBACK_REQUIRED",
                        "Fresh Echo receipt differs from the selected uninstall identity.",
                        retryable=True,
                    )
                source_id = self._workload_policy_source_id(row.get("sourcePolicy", {}))
                if source_id != WORKLOAD_ECHO_SOURCE_ID:
                    raise UpdateError(
                        "SOURCE_BINDING_INVALID", "Echo uninstall has no signed source owner."
                    )
            if not _valid_digest(component_digest):
                raise UpdateError(
                    "INVALID_STAGE", "Uninstall digest is missing from the selected identity."
                )
            transaction = {
                "schemaVersion": 2,
                "transactionKind": "workload-assembly.v1",
                "planId": plan_id,
                "requestId": "cyrene-update-" + plan_id,
                "planDigest": plan_digest,
                "catalogDigest": stored["catalogDigest"],
                "workloadId": workload_id,
                "targetId": target_id,
                "action": "uninstall",
                "channel": stored["channel"],
                "componentArtifactDigests": {component_id: component_digest},
                "selectedComponents": [row],
                "selectedRow": row,
                "stagedRow": staged,
                "installation": installation,
                "echoReceipt": echo_receipt,
                "echoUninstallIntent": False,
                "sourceId": source_id,
                "sourcePolicy": row.get("sourcePolicy"),
                "echoPriorReceipt": echo_receipt,
                "componentId": component_id,
                "resolution": resolution,
                "maintenanceHolds": {},
                "bindingOperations": [],
                "phase": "applying",
                "phaseStartedAt": int(time.time()),
            }
            _atomic_json(transaction_path, transaction)
        if artifact_kind == "oci-image":
            if component_id != WORKLOAD_ECHO_COMPONENT_ID:
                raise UpdateError(
                    "WORKLOAD_UNINSTALL_UNAVAILABLE",
                    "No OCI uninstall adapter is registered for this component.",
                )
            echo_receipt = transaction.get("echoPriorReceipt")
            if not isinstance(echo_receipt, dict):
                echo_receipt = self._read_workload_echo_receipt()
            if (
                not isinstance(echo_receipt, dict)
                or echo_receipt.get("digest") != component_digest
                or echo_receipt.get("manifestDigest") != row.get("manifestDigest")
                or echo_receipt.get("releaseId") != row.get("releaseId")
            ) and transaction.get("echoUninstallIntent") is not True:
                raise UpdateError(
                    "WORKLOAD_OCI_READBACK_REQUIRED",
                    "The Echo uninstall receipt differs from the selected plan.",
                    retryable=True,
                )
            source_policy = row.get("sourcePolicy")
            if not isinstance(source_policy, dict):
                raise UpdateError(
                    "SOURCE_POLICY_INVALID", "Echo uninstall has no signed owner policy."
                )
            source_id = self._workload_policy_source_id(source_policy)
            if source_id != WORKLOAD_ECHO_SOURCE_ID:
                raise UpdateError(
                    "SOURCE_BINDING_INVALID",
                    "Echo uninstall owner differs from the signed catalog.",
                )
            container_removed = transaction.get("echoContainerRemoved") is True
            if not container_removed:
                self._preflight_workload_oci_runtime()
            if not isinstance(echo_receipt, dict):
                raise UpdateError(
                    "WORKLOAD_OCI_READBACK_REQUIRED",
                    "The redacted Echo runtime receipt is unavailable for recovery.",
                    retryable=True,
                )

            activity_catalog, source, principal = self._workload_echo_source_identity()
            api_token = None if container_removed else self._read_workload_echo_api_token()
            if not container_removed and api_token is None:
                raise UpdateError(
                    "WORKLOAD_ECHO_TOKEN_READBACK_REQUIRED",
                    "The protected Echo API bearer is unavailable; uninstall was not applied.",
                    retryable=True,
                )
            package_ids = tuple(
                sorted(self._load_workload_resolver().potential_component_ids(self.catalog, "echo"))
            )
            package_inventory = self._read_workload_package_inventory("echo", package_ids)
            inventory_generation = package_inventory.get("catalogGeneration")
            if inventory_generation is None:
                inventory_generation = activity_catalog.get("generation")
            if (
                type(inventory_generation) is not int
                or inventory_generation < 1
                or inventory_generation != activity_catalog.get("generation")
            ):
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "Echo's authenticated owner inventory changed catalog generation.",
                    retryable=True,
                )
            durable_generation = transaction.get("echoOwnerCatalogGeneration")
            if durable_generation is None:
                if container_removed or transaction.get("echoUninstallIntent") is True:
                    container_receipt = echo_receipt.get("containerReceipt")
                    durable_generation = (
                        container_receipt.get("activityCatalogGeneration")
                        if isinstance(container_receipt, dict)
                        else None
                    )
                else:
                    durable_generation = inventory_generation
                transaction["echoOwnerCatalogGeneration"] = durable_generation
                _atomic_json(transaction_path, transaction)
            if type(durable_generation) is not int or durable_generation != inventory_generation:
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "Echo's owner catalog generation changed during uninstall recovery.",
                    retryable=True,
                )
            prior_runner_identity = echo_receipt.get("runnerIdentity")
            if isinstance(prior_runner_identity, dict):
                if container_removed:
                    # Removal is already durable, so retry no longer needs the
                    # private connection reference that authorized this container.
                    connection_ref, runner_identity = None, prior_runner_identity
                else:
                    connection_ref, runner_identity = self._workload_echo_runner_identity(
                        package_inventory, prior_identity=prior_runner_identity
                    )
                    if connection_ref is None:
                        raise UpdateError(
                            "PACKAGE_RUNTIME_READBACK_REQUIRED",
                            "Echo's prior exact-match connection reference cannot be recovered safely.",
                            retryable=True,
                        )
            else:
                connection_ref, runner_identity = None, None
            if isinstance(prior_runner_identity, dict) and runner_identity != prior_runner_identity:
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED",
                    "Echo's exact-match owner differs from its installed receipt.",
                    retryable=True,
                )
            transaction["echoRunnerIdentity"] = runner_identity
            _atomic_json(transaction_path, transaction)
            helper = self._load_workload_oci_host()
            spec = None
            if not container_removed:
                spec = self._workload_echo_container_spec(
                    row,
                    activity_catalog,
                    source,
                    principal,
                    api_token=api_token[0] if api_token is not None else None,
                    connection_ref=connection_ref,
                    activity_generation=echo_receipt["containerReceipt"].get(
                        "activityCatalogGeneration"
                    ),
                )
            if spec is not None and transaction.get("echoUninstallIntent") is not True:
                try:
                    observed = helper.container_status(spec, runner=self._workload_oci_runner)
                except Exception as error:
                    raise UpdateError(
                        "WORKLOAD_OCI_READBACK_REQUIRED",
                        "The installed Echo container could not be authenticated before uninstall.",
                        retryable=True,
                    ) from error
                if observed.state == "not-installed":
                    raise UpdateError(
                        "WORKLOAD_OCI_READBACK_REQUIRED",
                        "The installed Echo receipt has no matching container.",
                        retryable=True,
                    )
                transaction["echoUninstallIntent"] = True
                transaction["echoPriorReceipt"] = echo_receipt
                _atomic_json(transaction_path, transaction)

            # Only deactivate bindings explicitly owned by Echo. A different
            # Product/source owner is never stopped as part of Echo removal.
            echo_policy, owner_rows = self._workload_plugin_owner_rows("echo", package_ids)
            if not isinstance(echo_policy, dict):
                raise UpdateError("SOURCE_POLICY_INVALID", "Echo plugin owner policy is missing.")
            owner_by_binding = {
                (owner.get("bindingId"), owner.get("packageId")): owner for owner in owner_rows
            }
            source_bindings = package_inventory.get("sourceBindings", [])
            if not isinstance(source_bindings, list):
                raise UpdateError(
                    "PACKAGE_RUNTIME_READBACK_REQUIRED", "Echo owner inventory is malformed."
                )
            active_echo_bindings = [
                binding
                for binding in source_bindings
                if isinstance(binding, dict)
                and binding.get("sourceId") == source_id
                and binding.get("state") == "RUNNING"
            ]
            expected_runner_identity = transaction.get("echoRunnerIdentity")
            if not isinstance(expected_runner_identity, dict):
                expected_runner_identity = prior_runner_identity
            if isinstance(expected_runner_identity, dict):
                expected_source = expected_runner_identity.get("sourceId")
                expected_binding = expected_runner_identity.get("bindingId")
                expected_package = expected_runner_identity.get("packageId")
                expected_installation = expected_runner_identity.get("installationId")
                expected_component = expected_runner_identity.get("componentId")
                expected_generation = transaction.get("echoOwnerCatalogGeneration")
                if expected_generation is None:
                    container_receipt = echo_receipt.get("containerReceipt")
                    expected_generation = (
                        container_receipt.get("activityCatalogGeneration")
                        if isinstance(container_receipt, dict)
                        else None
                    )
                if (
                    expected_source != source_id
                    or not all(
                        isinstance(value, str) and value
                        for value in (
                            expected_binding,
                            expected_package,
                            expected_installation,
                            expected_component,
                        )
                    )
                    or type(expected_generation) is not int
                    or expected_generation != activity_catalog.get("generation")
                ):
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        "Echo's durable owner identity or ActivitySource generation changed.",
                        retryable=True,
                    )
                expected_owner = (
                    expected_source,
                    expected_binding,
                    expected_package,
                    expected_installation,
                )
                observed_owners = [
                    (
                        binding.get("sourceId"),
                        binding.get("bindingId"),
                        binding.get("packageId"),
                        binding.get("activeInstallationId"),
                    )
                    for binding in active_echo_bindings
                ]
                if active_echo_bindings and observed_owners != [expected_owner]:
                    raise UpdateError(
                        "COMPONENT_IN_USE",
                        "Echo's active Package Runtime owner changed after container removal.",
                        retryable=True,
                    )
                if not active_echo_bindings:
                    expected_request_id = (
                        "cyrene-wop-"
                        + plan_id.removeprefix("plan-")
                        + "-dea-"
                        + hashlib.sha256(expected_installation.encode("utf-8")).hexdigest()[:8]
                        + "-"
                        + expected_component
                    )
                    binding_operations = transaction.get("bindingOperations", [])
                    if not isinstance(binding_operations, list):
                        raise UpdateError(
                            "INVALID_TRANSACTION", "Echo binding operation journal is malformed."
                        )
                    prior_deactivation = next(
                        (
                            operation
                            for operation in binding_operations
                            if isinstance(operation, dict)
                            and operation.get("requestId") == expected_request_id
                        ),
                        None,
                    )
                    prior_scope = (
                        prior_deactivation.get("scope")
                        if isinstance(prior_deactivation, dict)
                        else None
                    )
                    exact_prior_deactivation = (
                        isinstance(prior_deactivation, dict)
                        and prior_deactivation.get("operation") == "deactivate"
                        and isinstance(prior_scope, dict)
                        and prior_scope.get("source_id") == expected_source
                        and prior_scope.get("binding_id") == expected_binding
                        and prior_scope.get("package_id") == expected_package
                        and prior_scope.get("installation_id") == expected_installation
                    )
                    if not exact_prior_deactivation:
                        raise UpdateError(
                            "COMPONENT_IN_USE",
                            "Echo's expected owner disappeared without a durable deactivation record.",
                            retryable=True,
                        )
                    if prior_deactivation.get("state") != "completed":
                        if prior_deactivation.get("state") not in {
                            "intent",
                            "outcome",
                            "reconciled",
                        }:
                            raise UpdateError(
                                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                                "Echo's owner deactivation outcome cannot be reconciled safely.",
                                retryable=True,
                            )
                        expected_owner_row = owner_by_binding.get(
                            (expected_binding, expected_package)
                        )
                        if (
                            not isinstance(expected_owner_row, dict)
                            or expected_owner_row.get("componentId") != expected_component
                        ):
                            raise UpdateError(
                                "SOURCE_BINDING_INVALID",
                                "Echo's durable deactivation no longer matches signed ownership.",
                            )
                        activity_catalog, runtime_policy, principals, package_helper = (
                            self._workload_source_state("echo")
                        )
                        if (
                            runtime_policy is None
                            or activity_catalog.get("generation") != expected_generation
                        ):
                            raise UpdateError(
                                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                                "Echo's Package Runtime source generation changed during recovery.",
                                retryable=True,
                            )
                        self._workload_binding_operation(
                            transaction,
                            transaction_path,
                            operation="deactivate",
                            component=expected_owner_row,
                            installation_id=expected_installation,
                            activity_catalog=activity_catalog,
                            runtime_policy=runtime_policy,
                            source_principals=principals,
                            helper=package_helper,
                        )
                        package_inventory = self._read_workload_package_inventory(
                            "echo", package_ids
                        )
                        source_bindings = package_inventory.get("sourceBindings", [])
                        if not isinstance(source_bindings, list):
                            raise UpdateError(
                                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                                "Echo owner inventory is malformed after deactivation recovery.",
                                retryable=True,
                            )
                        active_echo_bindings = [
                            binding
                            for binding in source_bindings
                            if isinstance(binding, dict)
                            and binding.get("sourceId") == source_id
                            and binding.get("state") == "RUNNING"
                        ]
                        if active_echo_bindings:
                            raise UpdateError(
                                "COMPONENT_IN_USE",
                                "A Package Runtime owner became active during Echo recovery.",
                                retryable=True,
                            )
            elif active_echo_bindings:
                raise UpdateError(
                    "COMPONENT_IN_USE",
                    "An active Echo Package Runtime owner was not present in the installed receipt.",
                    retryable=True,
                )
            if len(active_echo_bindings) > 1:
                raise UpdateError(
                    "COMPONENT_IN_USE",
                    "More than one active package binding owns the Echo Product source.",
                    retryable=True,
                )
            installations = package_inventory.get("installationRecords", {})
            validated_echo_owners: list[tuple[dict[str, Any], dict[str, Any]]] = []
            for binding in active_echo_bindings:
                owner = owner_by_binding.get((binding.get("bindingId"), binding.get("packageId")))
                if not isinstance(owner, dict):
                    raise UpdateError(
                        "COMPONENT_IN_USE",
                        "An unrecognized active Package Runtime binding owns the Echo source.",
                        retryable=True,
                    )
                owner_installation = (
                    installations.get(owner["componentId"])
                    if isinstance(installations, dict)
                    else None
                )
                if not isinstance(owner_installation, dict) or owner_installation.get(
                    "installation_id"
                ) != binding.get("activeInstallationId"):
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        "Echo's active plugin owner differs from its authenticated installation.",
                        retryable=True,
                    )
                validated_echo_owners.append((binding, owner))
                previous_rows = transaction.setdefault("previousPackageBindings", [])
                if not isinstance(previous_rows, list):
                    raise UpdateError(
                        "INVALID_TRANSACTION", "Echo owner rollback journal is malformed."
                    )
                if not any(
                    isinstance(previous, dict)
                    and previous.get("bindingId") == binding.get("bindingId")
                    and previous.get("sourceId") == source_id
                    for previous in previous_rows
                ):
                    previous_rows.append(
                        {
                            "componentId": owner["componentId"],
                            "sourceId": source_id,
                            "bindingId": binding["bindingId"],
                            "packageId": binding["packageId"],
                            "state": "RUNNING",
                            "activeInstallationId": binding["activeInstallationId"],
                        }
                    )
                transaction["selectedPluginRows"] = [owner]
            if validated_echo_owners and not isinstance(transaction.get("sdkEnvironment"), dict):
                sdk_reader = getattr(
                    self._load_workload_sdk_environment(),
                    "read_workload_sdk_environment",
                    None,
                )
                sdk_identity = sdk_reader() if callable(sdk_reader) else None
                if not isinstance(sdk_identity, dict) or sdk_identity.get("installed") is not True:
                    raise UpdateError(
                        "WORKLOAD_SDK_READBACK_REQUIRED",
                        "The operator SDK is needed to deactivate Echo's package owner.",
                        retryable=True,
                    )
                transaction["sdkEnvironment"] = sdk_identity
            _atomic_json(transaction_path, transaction)

            # Stop Echo before deactivating its optional Package Runtime owner.
            # This is a separate CORE_RUNTIME hold because SDK mutations require
            # normal Broker admission after all maintenance holds have closed.
            if (
                not container_removed
                and not self._workload_phase_is_ended(transaction, "core-runtime-echo-quiesce")
                and (
                    self._ensure_workload_phase(
                        transaction,
                        transaction_path,
                        phase="core-runtime-echo-quiesce",
                        target_kind="CORE_RUNTIME",
                        requires_restart=True,
                    )
                )
            ):
                transaction["echoContainerStopIntent"] = True
                _atomic_json(transaction_path, transaction)
                try:
                    assert spec is not None
                    stopped = helper.stop_container(spec, runner=self._workload_oci_runner)
                except Exception as error:
                    raise UpdateError(
                        "WORKLOAD_OCI_STOP_FAILED",
                        "The exact Echo container could not be stopped safely.",
                        retryable=True,
                    ) from error
                if stopped.state not in {"exited", "created"}:
                    raise UpdateError(
                        "WORKLOAD_OCI_STOP_FAILED",
                        "Echo did not reach a stopped container state before owner deactivation.",
                        retryable=True,
                    )
                transaction["echoStoppedReceipt"] = stopped.to_receipt_fields()
                _atomic_json(transaction_path, transaction)
                self._end_workload_hold(
                    transaction, transaction_path, outcome="SUCCESS", healthy=True
                )

            # Remove the stopped container while the exact signed owner is still
            # readable. The connection_ref is intentionally never journaled; doing
            # cleanup before deactivation keeps interrupted retries recoverable.
            if not self._workload_phase_is_ended(transaction, "core-runtime-uninstall") and (
                self._ensure_workload_phase(
                    transaction,
                    transaction_path,
                    phase="core-runtime-uninstall",
                    target_kind="CORE_RUNTIME",
                    requires_restart=True,
                )
            ):
                if transaction.get("echoContainerRemoved") is not True:
                    if spec is None:
                        raise UpdateError(
                            "INVALID_TRANSACTION",
                            "Echo container removal lost its authenticated runtime specification.",
                        )
                    transaction["echoContainerRemovalIntent"] = True
                    _atomic_json(transaction_path, transaction)
                    try:
                        removal = helper.remove_container(
                            spec,
                            runner=self._workload_oci_runner,
                            remove_runtime_credentials=True,
                        )
                    except Exception as error:
                        raise UpdateError(
                            "WORKLOAD_OCI_REMOVE_FAILED",
                            "The exact Echo container could not be removed safely.",
                            retryable=True,
                        ) from error
                    if removal.state != "not-installed":
                        raise UpdateError(
                            "WORKLOAD_OCI_REMOVE_FAILED",
                            "The Echo OCI runtime did not confirm container removal.",
                            retryable=True,
                        )
                    transaction["echoRemovalReceipt"] = removal.to_receipt_fields()
                    self._clear_workload_echo_receipt(component_digest)
                    transaction["echoContainerRemoved"] = True
                    _atomic_json(transaction_path, transaction)
                self._end_workload_hold(
                    transaction, transaction_path, outcome="SUCCESS", healthy=True
                )

            package_inventory = self._read_workload_package_inventory("echo", package_ids)
            refreshed_echo_bindings = [
                binding
                for binding in package_inventory.get("sourceBindings", [])
                if isinstance(binding, dict)
                and binding.get("sourceId") == source_id
                and binding.get("state") == "RUNNING"
            ]
            expected_echo_bindings = [
                (
                    binding.get("bindingId"),
                    binding.get("packageId"),
                    binding.get("activeInstallationId"),
                )
                for binding in active_echo_bindings
            ]
            actual_echo_bindings = [
                (
                    binding.get("bindingId"),
                    binding.get("packageId"),
                    binding.get("activeInstallationId"),
                )
                for binding in refreshed_echo_bindings
            ]
            if actual_echo_bindings != expected_echo_bindings:
                raise UpdateError(
                    "COMPONENT_IN_USE",
                    "Echo Package Runtime ownership changed during container quiescence.",
                    retryable=True,
                )

            if active_echo_bindings:
                for binding, owner in validated_echo_owners:
                    activity_catalog, runtime_policy, principals, package_helper = (
                        self._workload_source_state("echo")
                    )
                    if runtime_policy is None:
                        raise UpdateError(
                            "PACKAGE_RUNTIME_READBACK_REQUIRED",
                            "Echo's Package Runtime policy is unavailable.",
                            retryable=True,
                        )
                    self._workload_binding_operation(
                        transaction,
                        transaction_path,
                        operation="deactivate",
                        component=owner,
                        installation_id=binding["activeInstallationId"],
                        activity_catalog=activity_catalog,
                        runtime_policy=runtime_policy,
                        source_principals=principals,
                        helper=package_helper,
                    )
                    package_inventory = self._read_workload_package_inventory("echo", package_ids)
                    still_active = any(
                        isinstance(current, dict)
                        and current.get("sourceId") == source_id
                        and current.get("state") == "RUNNING"
                        for current in package_inventory.get("sourceBindings", [])
                    )
                    if still_active:
                        raise UpdateError(
                            "PACKAGE_RUNTIME_READBACK_REQUIRED",
                            "Echo's Package Runtime owner remained active after deactivation.",
                            retryable=True,
                        )
                    # One mutation per exact selected binding. Re-read after each
                    # admission so an unexpected additional owner is not ignored.
                    break

            if any(
                isinstance(binding, dict)
                and binding.get("sourceId") == source_id
                and binding.get("state") == "RUNNING"
                for binding in package_inventory.get("sourceBindings", [])
            ):
                raise UpdateError(
                    "COMPONENT_IN_USE",
                    "An active Package Runtime owner still uses the Echo Product source.",
                    retryable=True,
                )

            result = {
                "status": "uninstalled",
                "action": "uninstall",
                "planId": plan_id,
                "planDigest": plan_digest,
                "catalogDigest": stored["catalogDigest"],
                "workloadId": workload_id,
                "targetId": target_id,
                "channel": stored["channel"],
                "components": [dict(row)],
                "resolution": resolution,
                "sourceBindings": package_inventory.get("sourceBindings", []),
                "hostMetadata": {
                    "echo": self._workload_echo_host_metadata(None, package_inventory)
                },
            }
        else:
            component_digest = transaction.get("componentArtifactDigests", {}).get(component_id)
            installation = transaction.get("installation")
            if component_digest is None:
                raise UpdateError(
                    "INVALID_TRANSACTION", "Uninstall transaction omits its component digest."
                )

        if artifact_kind == "plugin-package":
            assert isinstance(installation, dict)
            source_policy = row.get("sourcePolicy")
            if not isinstance(source_policy, dict):
                raise UpdateError(
                    "SOURCE_POLICY_INVALID", "Uninstall package has no signed owner policy."
                )
            package_inventory = self._read_workload_package_inventory(
                workload_id,
                tuple(
                    sorted(
                        self._load_workload_resolver().potential_component_ids(
                            self.catalog, workload_id
                        )
                    )
                ),
            )
            source_id = self._workload_policy_source_id(source_policy)
            binding_id = row.get("bindingId")
            installation_id = row.get("installationId") or installation.get("installation_id")
            if (
                not isinstance(source_id, str)
                or not isinstance(binding_id, str)
                or not isinstance(installation_id, str)
            ):
                raise UpdateError(
                    "SOURCE_BINDING_INVALID", "Uninstall owner identity is incomplete."
                )
            for binding in package_inventory.get("sourceBindings", []):
                if not isinstance(binding, dict):
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        "Runtime binding inventory is malformed.",
                    )
                if (
                    binding.get("sourceId") == source_id
                    and binding.get("bindingId") == binding_id
                    and binding.get("activeInstallationId") not in {None, installation_id}
                    and binding.get("state") == "RUNNING"
                ):
                    raise UpdateError(
                        "COMPONENT_IN_USE",
                        "A different release is active under this owner binding; uninstall was not applied.",
                        retryable=True,
                    )
                if (
                    (binding.get("sourceId") != source_id or binding.get("bindingId") != binding_id)
                    and binding.get("packageId") == row.get("packageId")
                    and installation_id in binding.get("installationIds", [])
                ):
                    raise UpdateError(
                        "COMPONENT_IN_USE",
                        "Another Package Runtime owner references this installation.",
                        retryable=True,
                    )
                if binding.get("state") == "RUNNING" and not (
                    binding.get("sourceId") == source_id and binding.get("bindingId") == binding_id
                ):
                    raise UpdateError(
                        "COMPONENT_IN_USE",
                        "Another active Package Runtime owner prevents offline uninstall.",
                        retryable=True,
                    )
            target_binding = next(
                (
                    binding
                    for binding in package_inventory.get("sourceBindings", [])
                    if isinstance(binding, dict)
                    and binding.get("sourceId") == source_id
                    and binding.get("bindingId") == binding_id
                ),
                None,
            )
            if isinstance(target_binding, dict) and target_binding.get("state") == "RUNNING":
                if target_binding.get("activeInstallationId") != installation_id:
                    raise UpdateError(
                        "COMPONENT_IN_USE",
                        "A different installation is active under this binding.",
                        retryable=True,
                    )
                activity_catalog, runtime_policy, principals, helper = self._workload_source_state(
                    workload_id
                )
                if runtime_policy is None:
                    raise UpdateError(
                        "PACKAGE_RUNTIME_READBACK_REQUIRED",
                        "Uninstall owner policy is unavailable.",
                        retryable=True,
                    )
                self._workload_binding_operation(
                    transaction,
                    transaction_path,
                    operation="deactivate",
                    component=row,
                    installation_id=installation_id,
                    activity_catalog=activity_catalog,
                    runtime_policy=runtime_policy,
                    source_principals=principals,
                    helper=helper,
                )
                package_inventory = self._read_workload_package_inventory(
                    workload_id,
                    tuple(
                        sorted(
                            self._load_workload_resolver().potential_component_ids(
                                self.catalog, workload_id
                            )
                        )
                    ),
                )
            if any(
                isinstance(binding, dict) and binding.get("state") == "RUNNING"
                for binding in package_inventory.get("sourceBindings", [])
            ):
                raise UpdateError(
                    "COMPONENT_IN_USE",
                    "A Package Runtime owner remains active; offline uninstall was not started.",
                    retryable=True,
                )
            if not self._workload_phase_is_ended(transaction, "core-runtime-uninstall"):
                if self._ensure_workload_phase(
                    transaction,
                    transaction_path,
                    phase="core-runtime-uninstall",
                    target_kind="PACKAGE_ONLY",
                    requires_restart=False,
                ):
                    transaction["offlineUninstallIntent"] = True
                    request_id = (
                        "cyrene-wpu-"
                        + plan_id.removeprefix("plan-")
                        + "-"
                        + hashlib.sha256(component_id.encode("utf-8")).hexdigest()[:12]
                    )
                    transaction["offlineUninstallRequestId"] = request_id
                    _atomic_json(transaction_path, transaction)
                    fresh_inventory = self._workload_inventory_before_daemon_stop(workload_id)
                    if fresh_inventory is not None:
                        current = fresh_inventory.get("installationRecords", {}).get(component_id)
                        identity_fields = (
                            "installation_id",
                            "package_id",
                            "package_version",
                            "artifact_digest",
                            "archive_digest",
                            "descriptor_digest",
                            "manifest_digest",
                            "dependency_lock_digest",
                        )
                        if not isinstance(current, dict) or any(
                            current.get(field) != installation.get(field)
                            for field in identity_fields
                        ):
                            raise UpdateError(
                                "PACKAGE_RUNTIME_READBACK_REQUIRED",
                                "Package Runtime installation changed after the uninstall hold began.",
                                retryable=True,
                            )
                    self._workload_runtime_daemon("stop")
                    helper = self._load_workload_package_runtime()
                    try:
                        uninstall_result = helper.uninstall_workload_package(
                            installation,
                            component_id=component_id,
                            request_id=request_id,
                            maintenance=self._workload_hold_echo(transaction),
                            runner=self.runner,
                        )
                    except Exception as error:
                        raise UpdateError(
                            "PACKAGE_UNINSTALL_FAILED",
                            "Platform offline package removal did not complete.",
                            retryable=True,
                        ) from error
                    transaction["offlineUninstallResult"] = uninstall_result
                    _atomic_json(transaction_path, transaction)
                    remove_row = {**row, "packageArtifactDigest": component_digest}
                    self._update_workload_source_policy(
                        transaction,
                        transaction_path,
                        source_policy=source_policy,
                        selected_rows=[remove_row],
                        installation_records={},
                        phase="core-runtime-uninstall",
                        remove_component_ids=(component_id,),
                    )
                    self._end_workload_hold(
                        transaction, transaction_path, outcome="SUCCESS", healthy=True
                    )
                if transaction.get("packageRuntimePriorState", "active") != "inactive":
                    self._workload_runtime_daemon("start", wait_active=True)
                transaction["packageRuntimeStarted"] = True
                _atomic_json(transaction_path, transaction)
                self._clear_workload_package_runtime_receipt(component_id, installation_id)
            already_absent = bool(
                isinstance(transaction.get("offlineUninstallResult"), dict)
                and transaction["offlineUninstallResult"].get("already_absent") is True
            )
            component_result = dict(row)
            if already_absent:
                component_result["alreadyAbsent"] = True
            latest_inventory = self._read_workload_package_inventory(
                workload_id,
                tuple(
                    sorted(
                        self._load_workload_resolver().potential_component_ids(
                            self.catalog, workload_id
                        )
                    )
                ),
            )
            result = {
                "status": "uninstalled",
                "action": "uninstall",
                "planId": plan_id,
                "planDigest": plan_digest,
                "catalogDigest": stored["catalogDigest"],
                "workloadId": workload_id,
                "targetId": target_id,
                "channel": stored["channel"],
                "components": [component_result],
                "resolution": resolution,
                "sourceBindings": latest_inventory.get("sourceBindings", []),
            }
        elif artifact_kind == "static-web":
            web_host = self._load_workload_web_host()
            expected_identity = row.get("installedIdentity")
            if not isinstance(expected_identity, dict):
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE", "Static Web uninstall identity is incomplete."
                )
            expected_digest = row.get("digest")
            if not _valid_digest(expected_digest):
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE", "Static Web uninstall digest is invalid."
                )
            if transaction is None:
                raise UpdateError(
                    "INVALID_TRANSACTION", "Static Web uninstall transaction was not created."
                )
            if not self._workload_phase_is_ended(
                transaction, "core-runtime-uninstall"
            ) and self._ensure_workload_phase(
                transaction,
                transaction_path,
                phase="core-runtime-uninstall",
                target_kind="CORE_RUNTIME",
                requires_restart=True,
            ):
                prior_state = web_host.capture_web_host_state(runner=self._workload_web_host_runner)
                transaction["webHostPriorState"] = prior_state
                _atomic_json(transaction_path, transaction)
                web_host.remove_web_host(
                    expected_state=prior_state,
                    durable_callback=self._journal_callback(
                        transaction, transaction_path, "hostEvents"
                    ),
                    runner=self._workload_web_host_runner,
                )
                current = self._capture_workload_web_identity(component_id)
                pointer_identity = expected_identity.get("pointerIdentity")
                if current.get("pointerIdentity") not in {pointer_identity, None}:
                    raise UpdateError(
                        "UNINSTALL_CONFLICT",
                        "Static Web current pointer changed outside this plan.",
                    )
                current_path = DEFAULT_WORKLOAD_WEB_ROOT / component_id / "current"
                if current_path.exists() or current_path.is_symlink():
                    if (
                        not current_path.is_symlink()
                        or not current_path.readlink().as_posix().startswith("releases/")
                    ):
                        raise UpdateError(
                            "UNINSTALL_CONFLICT", "Static Web current pointer is unsafe."
                        )
                    current_path.unlink()
                    self._fsync_directory(current_path.parent)
                self._clear_active_receipt(component_id)
                self._end_workload_hold(
                    transaction, transaction_path, outcome="SUCCESS", healthy=True
                )
            result = {
                "status": "uninstalled",
                "action": "uninstall",
                "planId": plan_id,
                "planDigest": plan_digest,
                "catalogDigest": stored["catalogDigest"],
                "workloadId": workload_id,
                "targetId": target_id,
                "channel": stored["channel"],
                "components": [dict(row)],
                "resolution": resolution,
                "hostMetadata": {
                    "web": web_host.read_web_host_status(runner=self._workload_web_host_runner)
                },
            }

        transaction["result"] = result
        transaction["phase"] = "succeeded"
        transaction.pop("maintenanceToken", None)
        _atomic_json(transaction_path, transaction)
        stored["phase"] = "applied"
        stored["applyResult"] = result
        _atomic_json(self._workload_plan_directory() / f"{plan_id}.json", stored)
        return result

    def status(self) -> dict[str, Any]:
        """Read installed versions and live gate readiness without changing services."""

        self._reload_catalog_for_operation()
        self._ensure_state_root()
        rows = []
        plans = self._staged_plans()
        staged_by_component = {
            item["componentId"]: (plan, item)
            for plan in plans
            for item in plan.get("components", [])
        }
        for component in self._host_components():
            if self._target_for(component) is None:
                rows.append(self._unsupported_component(component))
                continue
            candidate = self._installed(component)
            gate = self._readiness(component)
            stage_record = staged_by_component.get(component["componentId"])
            if stage_record:
                phase = "staged"
            elif not candidate["activeVersion"]:
                phase = "available"
            else:
                phase = "current" if candidate.get("identityAttested") else "unknown"
            rows.append(self._result_component(component, gate, phase=phase, staged=stage_record))
        return {"status": "ready", "components": rows, "plans": plans}

    def check(
        self,
        component_ids: Any = None,
        *,
        channel: Any = None,
        include_readiness: bool = True,
        _placement_operation: str = "check",
    ) -> dict[str, Any]:
        """Discover trusted channel releases and produce digest-bound plans."""

        self._reload_catalog_for_operation()
        self._ensure_state_root()
        channel = self._resolve_channel(channel)
        if channel not in {"stable", "preview"}:
            raise UpdateError("INVALID_CATALOG", "The default release channel is invalid.")
        if component_ids is None:
            selected = self._default_placement_selection()
        elif (
            isinstance(component_ids, list)
            and component_ids
            and len(component_ids) <= 100
            and all(
                isinstance(value, str) and COMPONENT_ID_PATTERN.fullmatch(value)
                for value in component_ids
            )
            and len(set(component_ids)) == len(component_ids)
        ):
            selected = component_ids
        else:
            raise UpdateError(
                "INVALID_REQUEST", "componentIds must be a unique, non-empty component ID list."
            )
        if _placement_operation not in {"check", "stage"}:
            raise UpdateError("INVALID_REQUEST", "Unsupported internal placement operation.")
        unknown = sorted(set(selected) - set(self.components))
        if unknown:
            raise UpdateError(
                "INVALID_COMPONENT", f"Unknown trusted component IDs: {', '.join(unknown)}"
            )
        if component_ids is not None:
            self._validate_requested_placement(set(selected))

        candidates: dict[str, Candidate] = {}
        skipped: dict[str, str] = {}
        unavailable: dict[str, UpdateError] = {}
        for component_id in selected:
            component = self.components[component_id]
            selected_target = self._target_for(component)
            if selected_target is None:
                skipped[component_id] = "unsupported"
                continue
            try:
                candidates[component_id] = self._candidate(component, selected_target, channel)
            except UpdateError as error:
                unavailable[component_id] = error

        candidates = self._expand_compatibility_groups(candidates, channel)
        self._validate_runtime_dependencies(candidates)
        selected = list(dict.fromkeys([*selected, *candidates.keys()]))
        placement_bindings = self._placement_bindings(
            candidates,
            operation=_placement_operation,
        )
        plan_components = []
        for component_id, candidate in sorted(candidates.items()):
            installed = self._installed(candidate.component)
            same_release = (
                installed.get("active") is True
                and installed.get("identityAttested") is True
                and installed.get("releaseIdentity") == candidate.manifest_digest
                and installed.get("manifestDigest") == candidate.manifest_digest
                and installed.get("artifactDigest") == candidate.artifact_digest
            )
            if same_release:
                continue
            artifact = candidate.manifest["artifact"]
            plan_components.append(
                {
                    "componentId": component_id,
                    "version": candidate.manifest["version"],
                    "manifestDigest": candidate.manifest_digest,
                    "artifactDigest": artifact.get("digest", artifact.get("sha256")),
                    "restartGroup": candidate.component["restart"]["group"],
                }
            )

        plan = None
        if plan_components:
            digest_material = {
                "schemaVersion": 1,
                "channel": channel,
                "catalogGeneration": self.catalog_generation,
                "catalogDigest": self.catalog_digest,
                "components": plan_components,
            }
            if placement_bindings:
                digest_material["deploymentPlacement"] = placement_bindings
            plan_digest = _digest_json(digest_material, "planDigest")
            plan_id = "plan-" + plan_digest.split(":", 1)[1][:32]
            plan = {
                "planId": plan_id,
                "planDigest": plan_digest,
                "channel": channel,
                "catalogGeneration": self.catalog_generation,
                "catalogDigest": self.catalog_digest,
                "phase": "checked",
                "components": plan_components,
            }
            if placement_bindings:
                plan["deploymentPlacement"] = placement_bindings
        rows = []
        for component_id in selected:
            component = self.components[component_id]
            target = self._target_for(component)
            if component_id in skipped or target is None:
                rows.append(self._unsupported_component(component))
                continue
            if component_id in unavailable:
                error = unavailable[component_id]
                gate = (
                    self._readiness(component)
                    if include_readiness
                    else {
                        "status": "UNKNOWN",
                        "blocker_codes": ["READINESS_NOT_QUERIED"],
                        "message": "Check plan generation does not acquire the maintenance gate.",
                    }
                )
                row = self._result_component(
                    component, gate, phase="unknown", update_available=False
                )
                row["blockers"] = [{"code": error.code, "message": str(error)[:500]}]
                row["allowedActions"] = ["check"]
                rows.append(row)
                continue
            candidate = candidates[component_id]
            installed = self._installed(component)
            is_current = (
                installed.get("active") is True
                and installed.get("identityAttested") is True
                and installed.get("releaseIdentity") == candidate.manifest_digest
                and installed.get("manifestDigest") == candidate.manifest_digest
                and installed.get("artifactDigest") == candidate.artifact_digest
            )
            is_available = not is_current
            gate = (
                self._readiness(component)
                if include_readiness
                else {
                    "status": "UNKNOWN",
                    "blocker_codes": ["READINESS_NOT_QUERIED"],
                    "message": "Check plan generation does not acquire the maintenance gate.",
                }
            )
            rows.append(
                self._result_component(
                    component,
                    gate,
                    phase="available" if is_available else "current",
                    available_version=candidate.manifest["version"] if is_available else None,
                    update_available=is_available,
                )
            )
        result: dict[str, Any] = {
            "status": "checked",
            "components": rows,
            "plans": [plan] if plan else [],
        }
        if plan:
            result["plan"] = plan
            plan_directory = self._private_state_directory("plans")
            _atomic_json(plan_directory / f"{plan['planId']}.json", plan)
        return result

    def stage(self, plan_id: Any, plan_digest: Any, *, channel: Any = None) -> dict[str, Any]:
        self._require_authorized_process()
        with self._exclusive_update_lock():
            return self._stage_locked(plan_id, plan_digest, channel=channel)

    def _stage_locked(
        self, plan_id: Any, plan_digest: Any, *, channel: Any = None
    ) -> dict[str, Any]:
        """Download, verify, and install immutable payloads without gate or activation."""

        self._reload_catalog_for_operation()
        self._ensure_state_root()
        self._validate_plan_identity(plan_id, plan_digest)
        stored_plan = _read_object(
            self.state_root / "plans" / f"{plan_id}.json", "checked update plan"
        )
        if stored_plan.get("planDigest") != plan_digest:
            raise UpdateError(
                "PLAN_CHANGED",
                "The latest checked plan no longer matches this digest; run check again.",
                retryable=True,
            )
        if (
            stored_plan.get("catalogGeneration") != self.catalog_generation
            or stored_plan.get("catalogDigest") != self.catalog_digest
        ):
            raise UpdateError(
                "PLAN_CATALOG_CHANGED",
                "The trusted catalog changed after this plan was checked; run check again.",
                retryable=True,
            )
        channel = self._resolve_channel(
            channel if channel is not None else stored_plan.get("channel")
        )
        if stored_plan.get("channel") != channel:
            raise UpdateError(
                "PLAN_CHANNEL_MISMATCH",
                "Stage channel does not match the checked, digest-bound plan.",
            )
        component_ids = [
            item.get("componentId")
            for item in stored_plan.get("components", [])
            if isinstance(item, dict)
        ]
        checked = self.check(
            component_ids,
            channel=channel,
            include_readiness=False,
            _placement_operation="stage",
        )
        plan = self._find_plan(checked, plan_id, plan_digest)
        candidate_map = self._resolve_plan_candidates(plan, channel)
        staged_root = self._private_state_directory("staged")
        plan_root = staged_root / plan_id
        if plan_root.is_symlink():
            raise UpdateError(
                "UNSAFE_STATE", f"Refusing a symlinked staged plan directory: {plan_root}"
            )
        if plan_root.exists():
            shutil.rmtree(plan_root)
        plan_root.mkdir(parents=True, mode=0o700)
        staged_components: list[dict[str, Any]] = []
        try:
            for plan_component in plan["components"]:
                candidate = candidate_map[plan_component["componentId"]]
                staged_components.append(
                    self._stage_candidate(candidate, plan_root, plan_id, plan_digest)
                )
            self._revalidate_plan_placement(plan, operation="stage")
            record = {
                "schemaVersion": 2,
                "plan": plan,
                "channel": channel,
                "components": staged_components,
                "phase": "staged",
                "createdAt": int(time.time()),
            }
            _atomic_json(plan_root / "stage.json", record)
        except Exception:
            shutil.rmtree(plan_root, ignore_errors=True)
            raise
        staged_plan = {**plan, "phase": "staged"}
        staged_rows = [
            self._result_component(
                self.components[item["componentId"]],
                {
                    "status": "UNKNOWN",
                    "blocker_codes": ["READINESS_NOT_QUERIED"],
                    "message": "Staging does not query or acquire the maintenance gate.",
                },
                phase="staged",
                available_version=item["version"],
                staged={"plan": staged_plan, "component": item},
            )
            for item in staged_components
        ]
        return {
            "status": "staged",
            "components": staged_rows,
            "plan": staged_plan,
            "plans": [staged_plan],
        }

    def apply(
        self,
        plan_id: Any,
        plan_digest: Any,
        confirmation: Any,
        *,
        channel: Any = None,
    ) -> dict[str, Any]:
        self._require_authorized_process()
        with self._exclusive_update_lock():
            return self._apply_locked(plan_id, plan_digest, confirmation, channel=channel)

    def _apply_locked(
        self,
        plan_id: Any,
        plan_digest: Any,
        confirmation: Any,
        *,
        channel: Any = None,
    ) -> dict[str, Any]:
        """Atomically gate the runtime, activate, restart, health-check, or rollback."""

        self._reload_catalog_for_operation()
        self._validate_plan_identity(plan_id, plan_digest)
        if (
            not isinstance(confirmation, dict)
            or set(confirmation) != {"planId", "planDigest", "confirmed"}
            or confirmation.get("confirmed") is not True
            or confirmation.get("planId") != plan_id
            or confirmation.get("planDigest") != plan_digest
        ):
            raise UpdateError(
                "CONFIRMATION_MISMATCH",
                "Apply requires confirmation bound to this exact planId and planDigest.",
            )
        stage_path = self.state_root / "staged" / plan_id / "stage.json"
        record = _read_object(stage_path, "staged update plan")
        if (
            record.get("phase") != "staged"
            or record.get("plan", {}).get("planDigest") != plan_digest
        ):
            raise UpdateError(
                "PLAN_NOT_STAGED", "This exact plan is not staged. Stage it again before apply."
            )
        stored_channel = record.get("channel")
        if stored_channel not in {"stable", "preview"} or (
            channel is not None and self._resolve_channel(channel) != stored_channel
        ):
            raise UpdateError(
                "PLAN_CHANNEL_MISMATCH",
                "Apply channel does not match the staged, digest-bound plan.",
            )
        self._validate_staged_record(
            record,
            expected_plan_id=plan_id,
            expected_plan_digest=plan_digest,
        )
        self._revalidate_plan_placement(record["plan"], operation="apply")
        transaction_path = self._private_state_directory("transactions") / f"{plan_id}.json"
        existing = (
            _read_object(transaction_path, "update transaction")
            if transaction_path.exists()
            else None
        )
        placement_binding = self._placement_binding_for_group(
            record.get("plan", {}), "workspace-product-v2"
        )
        if placement_binding is not None:
            adoption = self._read_placement_adoption(required=False)
            if adoption is None:
                raise UpdateError(
                    "PLACEMENT_ADOPTION_REQUIRED",
                    "The exact staged two-host plan must be explicitly prepared before apply.",
                    retryable=True,
                )
            if adoption.get("phase") != "ACTIVE" and (
                adoption.get("planId") != plan_id or adoption.get("planDigest") != plan_digest
            ):
                raise UpdateError(
                    "PLACEMENT_ADOPTION_CONFLICT",
                    "A different two-host adoption hold must be resolved before apply.",
                    retryable=True,
                )
            if adoption.get("planId") == plan_id and adoption.get("planDigest") == plan_digest:
                if adoption.get("phase") in {"PREPARED_HELD", "APPLY_PENDING", "ACTIVE_HELD"}:
                    return self._apply_placement_held(
                        record,
                        transaction_path,
                        existing,
                        adoption,
                        confirmation,
                    )
                if adoption.get("phase") != "ACTIVE":
                    raise UpdateError(
                        "PLACEMENT_ADMISSION_UNKNOWN",
                        "The exact adoption journal is not in an applyable phase.",
                        retryable=True,
                    )
        if existing and existing.get("schemaAdoption") is True:
            if existing.get("phase") == "succeeded":
                return self._applied_result(existing)
            if existing.get("phase") == "rolled_back":
                raise UpdateError(
                    "APPLY_ROLLED_BACK",
                    existing.get("rollbackMessage", "Schema adoption was rolled back."),
                )
        if existing and existing.get("phase") not in {"succeeded", "rolled_back"}:
            if existing.get("schemaAdoption") is True:
                return self._recover_schema_adoption(existing, transaction_path, confirmation)
            return self._recover_transaction(existing, transaction_path, stage_path, confirmation)
        self._require_managed_services(record["components"])
        if not _running_as_root():
            raise UpdateError(
                "PRIVILEGE_REQUIRED",
                "Applying staged components requires the root-owned local update helper.",
            )

        target_kind = (
            "CORE_RUNTIME"
            if any(
                self.components[item["componentId"]]["restart"]["group"] == "core-runtime"
                for item in record["components"]
            )
            else "PACKAGE_ONLY"
        )
        readiness = self._readiness_for(target_kind, requires_restart=True, force=True)
        self._require_ready(readiness, target_kind)
        gate_catalog, gate_sources = self._activity_catalog()
        if readiness.get("install_catalog_generation") != gate_catalog["generation"]:
            raise UpdateError(
                "GATE_UNKNOWN",
                "Installed activity catalog changed during readiness; check again before applying.",
                retryable=True,
            )
        staged_component_ids = {item["componentId"] for item in record["components"]}
        schema_adoption = False
        migration_profile = None
        unit_inventory = None
        if staged_component_ids.intersection(
            {
                "cyrene-runtime-maintenance",
                "cyrene-kernel",
                "cy-package-runtime",
            }
        ):
            migration = self._load_native_runtime_schema_migration()
            try:
                schema_adoption = migration.is_schema1_group_adoption(self, record)
                migration_profile = (
                    migration.read_schema1_profile(Path("/var/lib/cyrene/runtime"))
                    if schema_adoption
                    else None
                )
                unit_inventory = (
                    migration.capture_unit_inventory(self, staged_component_ids)
                    if schema_adoption
                    else None
                )
            except migration.MigrationError as error:
                raise UpdateError(
                    "SCHEMA_ADOPTION_UNKNOWN",
                    f"Cannot verify the installed Core schema-adoption prerequisites: {error}",
                    retryable=True,
                ) from error
        if schema_adoption and target_kind != "CORE_RUNTIME":
            raise UpdateError(
                "SCHEMA_ADOPTION_INVALID",
                "A schema adoption plan must use the complete CORE_RUNTIME maintenance gate.",
            )
        artifact_digests = {
            item["componentId"]: item["artifactDigest"] for item in record["components"]
        }
        authority_activation = self._prepare_authority_activation(record, plan_id, plan_digest)
        transaction = {
            "schemaVersion": 2,
            "planId": plan_id,
            "requestId": "cyrene-update-" + plan_id,
            "planDigest": plan_digest,
            "componentArtifactDigests": artifact_digests,
            "phase": "begin_pending",
            "targetKind": target_kind,
            "channel": stored_channel,
            "expectedGateGeneration": readiness.get("gate_generation"),
            "expectedCatalogGeneration": gate_catalog["generation"],
            "expectedActivitySources": gate_sources,
            "components": record["components"],
            "previous": self._capture_active_versions(record["components"]),
            "authorityActivation": authority_activation,
            "createdAt": int(time.time()),
        }
        if schema_adoption:
            transaction.update(
                {
                    "schemaAdoption": True,
                    "schema1Profile": migration_profile,
                    "preActiveUnits": unit_inventory,
                    "migrationPhase": "planned",
                    "requiresRestart": True,
                    "userConfirmedRestart": True,
                }
            )
        _atomic_json(transaction_path, transaction)
        try:
            token = self._begin_maintenance(transaction)
        except UpdateError as error:
            if error.maintenance_not_acquired:
                self._clear_begin_pending(transaction, transaction_path)
            raise
        transaction["maintenanceToken"] = token
        transaction["phase"] = "applying"
        _atomic_json(transaction_path, transaction)
        if schema_adoption:
            return self._execute_schema_adoption(transaction, transaction_path)
        try:
            self._activate_transaction(transaction)
            self._restart_transaction(transaction)
            self._health_transaction(transaction)
            self._activate_authority_bundle(transaction)
            self._revalidate_plan_placement(record["plan"], operation="apply")
        except Exception as failure:
            healthy_rollback, rollback_message = self._rollback_transaction(transaction)
            transaction["phase"] = (
                "rollback_end_pending" if healthy_rollback else "rollback_required"
            )
            transaction["rollbackHealthy"] = healthy_rollback
            transaction["rollbackMessage"] = rollback_message
            _atomic_json(transaction_path, transaction)
            try:
                self._end_maintenance(
                    transaction,
                    outcome="ROLLED_BACK" if healthy_rollback else "FAILED",
                    healthy=healthy_rollback,
                )
            except UpdateError as end_error:
                transaction["recoveryError"] = str(end_error)
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "ROLLBACK_GATE_HELD",
                    f"Update failed ({failure}); rollback status: {rollback_message}; maintenance gate remains held because EndMaintenance failed: {end_error}",
                    retryable=True,
                ) from failure
            transaction["phase"] = "rolled_back" if healthy_rollback else "rollback_required"
            if healthy_rollback:
                transaction.pop("maintenanceToken", None)
            _atomic_json(transaction_path, transaction)
            raise UpdateError(
                "APPLY_ROLLED_BACK" if healthy_rollback else "ROLLBACK_UNHEALTHY",
                f"Update failed ({failure}). {rollback_message}",
                retryable=not healthy_rollback,
            ) from failure
        transaction["phase"] = "success_end_pending"
        _atomic_json(transaction_path, transaction)
        try:
            self._end_maintenance(transaction, outcome="SUCCESS", healthy=True)
        except UpdateError as end_error:
            transaction["recoveryError"] = str(end_error)
            _atomic_json(transaction_path, transaction)
            raise UpdateError(
                "GATE_END_PENDING",
                f"The new release is healthy, but maintenance completion is not confirmed: {end_error}. Retry this exact plan to reconcile the durable gate record.",
                retryable=True,
            ) from end_error
        transaction["phase"] = "succeeded"
        transaction.pop("maintenanceToken", None)
        transaction.pop("recoveryError", None)
        _atomic_json(transaction_path, transaction)
        return self._applied_result(transaction)

    def _apply_placement_held(
        self,
        record: dict[str, Any],
        transaction_path: Path,
        existing: dict[str, Any] | None,
        adoption: dict[str, Any],
        confirmation: dict[str, Any],
    ) -> dict[str, Any]:
        """Apply this staged role while retaining its separately prepared adoption hold."""

        plan = record["plan"]
        plan_id = plan["planId"]
        plan_digest = plan["planDigest"]
        module, context, _group = self._placement_for_plan(plan)
        if adoption.get("planId") != plan_id or adoption.get("planDigest") != plan_digest:
            raise UpdateError("PLACEMENT_ADOPTION_CONFLICT", "The held plan identity changed.")
        phase = adoption.get("phase")
        if phase == "ACTIVE_HELD":
            if (
                context.role_id == "control-host"
                and existing is not None
                and existing.get("controlGateAdvanced") is True
            ):
                return self._recover_placement_apply(
                    existing, transaction_path, adoption, module, context
                )
            if existing is None or existing.get("phase") != "succeeded-held":
                raise UpdateError(
                    "PLACEMENT_ADMISSION_UNKNOWN",
                    "ACTIVE_HELD has no matching completed updater transaction.",
                    retryable=True,
                )
            self._validate_local_placement_adoption(adoption, module, context)
            return {**self._applied_result(existing), "adoptionPhase": "ACTIVE_HELD"}

        if not _running_as_root():
            raise UpdateError(
                "PRIVILEGE_REQUIRED",
                "Applying staged components requires the root-owned local update helper.",
            )
        self._require_managed_services(record["components"])
        self._validate_local_placement_adoption(
            {**adoption, "phase": "PREPARED_HELD"}, module, context
        )
        self._revalidate_plan_placement(plan, operation="apply")
        peer_phases = {"PREPARED_HELD", "ACTIVE_HELD", "ACTIVE"}
        self._placement_peer_evidence(plan, operation="apply", expected_peer_phases=peer_phases)
        if phase == "APPLY_PENDING":
            return self._recover_placement_apply(
                existing, transaction_path, adoption, module, context
            )
        if phase != "PREPARED_HELD":
            raise UpdateError(
                "PLACEMENT_ADMISSION_UNKNOWN",
                "The local placement hold is not ready for apply.",
                retryable=True,
            )
        if existing is not None and existing.get("phase") not in {
            "rolled_back-held",
            "succeeded-held",
        }:
            return self._recover_placement_apply(
                existing, transaction_path, adoption, module, context
            )
        if existing is not None and existing.get("phase") == "succeeded-held":
            raise UpdateError(
                "PLACEMENT_ADMISSION_UNKNOWN",
                "The updater transaction completed but the held journal did not advance.",
                retryable=True,
            )

        target_kind = "CORE_RUNTIME" if context.role_id == "connector-host" else "PACKAGE_ONLY"
        previous = self._capture_active_versions(record["components"])
        artifact_digests = {
            item["componentId"]: item["artifactDigest"] for item in record["components"]
        }
        transaction: dict[str, Any] = {
            "schemaVersion": 2,
            "planId": plan_id,
            "requestId": adoption["requestId"],
            "planDigest": plan_digest,
            "componentArtifactDigests": artifact_digests,
            "phase": "placement_applying",
            "targetKind": target_kind,
            "channel": record.get("channel"),
            "expectedGateGeneration": adoption.get("gateGeneration"),
            "expectedCatalogGeneration": adoption.get("catalogGeneration"),
            "expectedActivitySources": adoption.get("expectedActivitySources", []),
            "components": record["components"],
            "previous": previous,
            "authorityActivation": self._prepare_authority_activation(record, plan_id, plan_digest),
            "placementAdoption": True,
            "createdAt": int(time.time()),
        }
        adoption["phase"] = "APPLY_PENDING"
        adoption["applyStartedAt"] = int(time.time())
        _atomic_json(self._placement_adoption_path(), adoption, mode=0o600)
        _atomic_json(transaction_path, transaction)
        control_gate_advanced = False
        try:
            self._activate_transaction(transaction)
            self._restart_transaction(transaction)
            self._health_transaction(transaction)
            self._activate_authority_bundle(transaction)
            self._revalidate_plan_placement(plan, operation="apply")
            if context.role_id == "control-host":
                self._write_control_admission_state(
                    context, plan_id=plan_id, plan_digest=plan_digest, phase="ACTIVE_HELD"
                )
                control_gate_advanced = True
                state = self._read_control_admission_state(context)
                self._validate_control_readyz(module, context, state, self._control_readyz())
            transaction["phase"] = "succeeded-held"
            _atomic_json(transaction_path, transaction)
            adoption["phase"] = "ACTIVE_HELD"
            adoption.pop("applyStartedAt", None)
            _atomic_json(self._placement_adoption_path(), adoption, mode=0o600)
            self._validate_local_placement_adoption(adoption, module, context)
            self._verify_local_active_held(plan, module, context)
            return {**self._applied_result(transaction), "adoptionPhase": "ACTIVE_HELD"}
        except Exception as failure:
            if context.role_id == "control-host" and control_gate_advanced:
                transaction["phase"] = "placement_apply_unknown"
                transaction["controlGateAdvanced"] = True
                transaction["recoveryError"] = str(failure)
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "PLACEMENT_APPLY_UNKNOWN",
                    f"Control admission remains closed under the existing hold, but apply verification is incomplete ({failure}); retry the same plan to reconcile.",
                    retryable=True,
                ) from failure
            healthy, message = self._rollback_transaction(transaction)
            transaction["phase"] = "rolled_back-held" if healthy else "rollback_required"
            transaction["rollbackHealthy"] = healthy
            transaction["rollbackMessage"] = message
            _atomic_json(transaction_path, transaction)
            if healthy:
                adoption["phase"] = "PREPARED_HELD"
                adoption.pop("applyStartedAt", None)
                _atomic_json(self._placement_adoption_path(), adoption, mode=0o600)
            raise UpdateError(
                "PLACEMENT_APPLY_ROLLED_BACK" if healthy else "PLACEMENT_ROLLBACK_UNKNOWN",
                f"Placement apply failed ({failure}); {message}",
                retryable=True,
            ) from failure

    def _placement_for_plan(self, plan: dict[str, Any]) -> tuple[Any, Any, dict[str, Any]]:
        group = next(
            (
                item
                for item in self.catalog.get("compatibilityGroups", [])
                if isinstance(item, dict) and item.get("groupId") == "workspace-product-v2"
            ),
            None,
        )
        if not isinstance(group, dict):
            raise UpdateError("PLACEMENT_INVALID", "The signed placement group is unavailable.")
        loaded = self._placement_module_for_group(group)
        if loaded is None:
            raise UpdateError(
                "PLACEMENT_INVALID", "The fixed host placement profile is unavailable."
            )
        module, context = loaded
        if self._placement_binding_for_group(plan, context.group_id) is None:
            raise UpdateError(
                "PLACEMENT_INVALID", "The staged plan is not bound to this placement group."
            )
        return module, context, group

    def _recover_placement_apply(
        self,
        transaction: dict[str, Any] | None,
        transaction_path: Path,
        adoption: dict[str, Any],
        module: Any,
        context: Any,
    ) -> dict[str, Any]:
        """Roll back an interrupted held apply; never infer success from its journal phase."""

        if transaction is None or transaction.get("placementAdoption") is not True:
            raise UpdateError(
                "PLACEMENT_APPLY_UNKNOWN",
                "Interrupted placement apply has no exact rollback identity.",
                retryable=True,
            )
        if context.role_id == "control-host" and transaction.get("controlGateAdvanced") is True:
            adoption["phase"] = "ACTIVE_HELD"
            adoption.pop("applyStartedAt", None)
            _atomic_json(self._placement_adoption_path(), adoption, mode=0o600)
            transaction["phase"] = "succeeded-held"
            transaction.pop("recoveryError", None)
            _atomic_json(transaction_path, transaction)
            try:
                self._validate_local_placement_adoption(adoption, module, context)
                self._verify_local_active_held(
                    {"planId": adoption["planId"], "planDigest": adoption["planDigest"]},
                    module,
                    context,
                )
            except UpdateError:
                adoption["phase"] = "APPLY_PENDING"
                adoption["applyStartedAt"] = transaction.get("createdAt", int(time.time()))
                _atomic_json(self._placement_adoption_path(), adoption, mode=0o600)
                transaction["phase"] = "placement_apply_unknown"
                _atomic_json(transaction_path, transaction)
                raise
            return {
                **self._applied_result(transaction),
                "adoptionPhase": "ACTIVE_HELD",
            }
        if transaction.get("phase") == "succeeded-held":
            adoption["phase"] = "ACTIVE_HELD"
            adoption.pop("applyStartedAt", None)
            _atomic_json(self._placement_adoption_path(), adoption, mode=0o600)
            self._validate_local_placement_adoption(adoption, module, context)
            self._verify_local_active_held(
                {"planId": adoption["planId"], "planDigest": adoption["planDigest"]},
                module,
                context,
            )
            return {
                **self._applied_result(transaction),
                "adoptionPhase": "ACTIVE_HELD",
            }
        if transaction.get("phase") == "rolled_back-held":
            adoption["phase"] = "PREPARED_HELD"
            adoption.pop("applyStartedAt", None)
            _atomic_json(self._placement_adoption_path(), adoption, mode=0o600)
            self._validate_local_placement_adoption(adoption, module, context)
            raise UpdateError(
                "PLACEMENT_APPLY_RECOVERED",
                "The interrupted apply was already rolled back under the existing hold; retry the same confirmed plan to apply again.",
                retryable=True,
            )
        self._validate_recovery_identity(transaction)
        healthy, message = self._rollback_transaction(transaction)
        transaction["phase"] = "rolled_back-held" if healthy else "rollback_required"
        transaction["rollbackHealthy"] = healthy
        transaction["rollbackMessage"] = message
        _atomic_json(transaction_path, transaction)
        if healthy:
            adoption["phase"] = "PREPARED_HELD"
            adoption.pop("applyStartedAt", None)
            _atomic_json(self._placement_adoption_path(), adoption, mode=0o600)
            self._validate_local_placement_adoption(adoption, module, context)
            raise UpdateError(
                "PLACEMENT_APPLY_RECOVERED",
                "An interrupted apply was rolled back under the existing hold; retry the same confirmed plan to apply again.",
                retryable=True,
            )
        raise UpdateError(
            "PLACEMENT_ROLLBACK_UNKNOWN",
            f"Interrupted apply could not be rolled back ({message}); the original hold remains active.",
            retryable=True,
        )

    def _verify_local_active_held(
        self,
        plan: dict[str, Any],
        module: Any,
        context: Any,
        *,
        allow_release_pending: bool = False,
    ) -> None:
        group = next(
            item
            for item in self.catalog.get("compatibilityGroups", [])
            if isinstance(item, dict) and item.get("groupId") == context.group_id
        )
        binding = self._placement_binding_for_group(plan, context.group_id)
        if binding is None:
            raise UpdateError("PLACEMENT_INVALID", "Active held plan binding is unavailable.")
        desired = module._valid_desired_components(binding.get("localDesiredComponents"))
        if allow_release_pending:
            desired_ids = {item["componentId"] for item in desired}
            active = self._placement_active_components(group, context.local_role.allowed_members)
            if {item["componentId"] for item in active} != desired_ids:
                raise UpdateError(
                    "PLACEMENT_NOT_ACTIVE_HELD",
                    "Release recovery found a different active signed component set.",
                    retryable=True,
                )
            self._placement_service_inventory(desired, active_ids=desired_ids)
            if self._placement_transaction_state() != {"present": False, "phase": "none"}:
                raise UpdateError(
                    "PLACEMENT_NOT_ACTIVE_HELD",
                    "Release recovery found an unfinished updater transaction.",
                    retryable=True,
                )
            adoption = self._read_placement_adoption(required=True)
            assert adoption is not None
            if context.role_id == "connector-host":
                readiness = self._readiness_for("CORE_RUNTIME", requires_restart=False, force=True)
                state = self._readiness_admission_state(readiness)
                if state == "closed":
                    self._validate_connector_adoption_hold(adoption)
                elif state != "open":
                    raise UpdateError(
                        "PLACEMENT_ADMISSION_UNKNOWN",
                        "Connector release state is neither proven open nor held.",
                        retryable=True,
                    )
            else:
                state = self._read_control_admission_state(context)
                if state["adoptionHold"]["phase"] not in {"ACTIVE_HELD", "ACTIVE"}:
                    raise UpdateError(
                        "PLACEMENT_ADMISSION_UNKNOWN",
                        "Control release state is not held or open for this adoption.",
                        retryable=True,
                    )
                self._validate_control_readyz(module, context, state, self._control_readyz())
            return
        snapshot = self._placement_local_snapshot(module, context, group)
        if (
            snapshot.get("phase") != "ACTIVE_HELD"
            or {item["componentId"] for item in snapshot.get("activeComponents", [])}
            != {item["componentId"] for item in desired}
            or snapshot.get("transaction") != {"present": False, "phase": "none"}
        ):
            raise UpdateError(
                "PLACEMENT_NOT_ACTIVE_HELD",
                "Local signed pointers, services, or transaction state are not healthy under the hold.",
                retryable=True,
            )

    def _resolve_channel(self, value: Any) -> str:
        channel = self.catalog.get("defaultChannel", DEFAULT_CHANNEL) if value is None else value
        if not isinstance(channel, str) or channel not in {"stable", "preview"}:
            raise UpdateError("INVALID_REQUEST", "channel must be stable or preview.")
        if channel not in self.catalog.get("channels", {}):
            raise UpdateError(
                "INVALID_CATALOG", f"The trusted catalog has no {channel} channel policy."
            )
        return channel

    def _validate_plan_identity(self, plan_id: Any, plan_digest: Any) -> None:
        if (
            not isinstance(plan_id, str)
            or PLAN_ID_PATTERN.fullmatch(plan_id) is None
            or not _valid_digest(plan_digest)
        ):
            raise UpdateError("INVALID_PLAN", "planId or sha256 planDigest is invalid.")

    @staticmethod
    def _find_plan(result: dict[str, Any], plan_id: str, plan_digest: str) -> dict[str, Any]:
        plan = next(
            (item for item in result.get("plans", []) if item.get("planId") == plan_id), None
        )
        if plan is None or plan.get("planDigest") != plan_digest:
            raise UpdateError(
                "PLAN_CHANGED",
                "The latest trusted release set no longer matches this plan; run check again.",
                retryable=True,
            )
        return plan

    def _host_components(self) -> list[dict[str, Any]]:
        return sorted(self.components.values(), key=lambda item: item["componentId"])

    def _target_for(
        self, component: dict[str, Any], *, target_id: str | None = None
    ) -> dict[str, Any] | None:
        try:
            host = platform.freedesktop_os_release()
        except OSError:
            return None
        if not sys.platform.startswith("linux"):
            return None
        host_arch = platform.machine().lower()
        architecture = (
            "x86_64"
            if host_arch in {"x86_64", "amd64"}
            else "aarch64"
            if host_arch in {"aarch64", "arm64"}
            else host_arch
        )
        libc_name, libc_version = platform.libc_ver()
        host_abi = f"{libc_name}-{libc_version}" if libc_name and libc_version else None
        host_version = host.get("VERSION_ID")
        for entry in component.get("targets", []):
            if target_id is not None and entry.get("targetId") != target_id:
                continue
            target = self.targets.get(entry.get("targetId"))
            if target is None or entry.get("support") != "supported":
                continue
            spec = target.get("target", {})
            if spec.get("os") != "linux" or spec.get("architecture") != architecture:
                continue
            portable_data_target = (
                entry.get("artifactKind") == "data-bundle"
                and entry.get("targetId") == "portable-contract-data-v1"
            )
            echo_oci_target = (
                entry.get("artifactKind") == "oci-image"
                and component.get("componentId") == WORKLOAD_ECHO_COMPONENT_ID
                and entry.get("targetId") == WORKLOAD_ECHO_TARGET_ID
                and spec.get("runtime") == "oci"
            )
            if portable_data_target:
                if architecture != spec.get("architecture"):
                    continue
            elif echo_oci_target:
                if host.get("ID") != "ubuntu" or host_version != "24.04":
                    continue
            elif (
                host.get("ID") != "ubuntu"
                or host_version not in {"22.04", "24.04"}
                or spec.get("distribution") != "ubuntu"
                or spec.get("distributionVersion") != host_version
            ):
                continue
            if spec.get("abi") is not None and spec.get("abi") != host_abi:
                continue
            if entry.get("artifactKind") == "python-bundle":
                profile_id = (
                    "linux-ubuntu-24.04-x86_64-python-3.12"
                    if component.get("componentId") == WORKLOAD_SDK_COMPONENT_ID
                    and entry.get("targetId") == WORKLOAD_SDK_TARGET_ID
                    else entry.get("targetId")
                )
                profile = self.native_python_profiles.get(profile_id)
                if (
                    spec.get("runtime") != "python:3.12"
                    or profile is None
                    or any(profile.get(key) != spec.get(key) for key in NATIVE_PYTHON_TARGET_FIELDS)
                    or profile.get("osVersion") != host_version
                    or not self._private_python_runtime_ready(profile)
                ):
                    continue
            if (
                entry.get("artifactKind") == "native-binary"
                and spec.get("runtime") not in NATIVE_BINARY_SUPPORTED_RUNTIMES
            ):
                continue
            if entry.get("artifactKind") == "static-web" and spec.get("runtime") != "static-web":
                continue
            if entry.get("artifactKind") == "oci-image" and not echo_oci_target:
                continue
            if entry.get("artifactKind") == "plugin-package":
                profile = self.native_python_profiles.get(entry.get("targetId"))
                if (
                    spec.get("runtime") != "python:3.12"
                    or profile is None
                    or any(profile.get(key) != spec.get(key) for key in NATIVE_PYTHON_TARGET_FIELDS)
                    or profile.get("osVersion") != host_version
                    or not self._private_python_runtime_ready(profile)
                ):
                    continue
            if (
                entry.get("artifactKind") == "data-bundle"
                and spec.get("runtime") != "cyrene-authority-data"
            ):
                continue
            return {**target, "artifactKind": entry["artifactKind"]}
        return None

    def _unsupported_component(self, component: dict[str, Any]) -> dict[str, Any]:
        return {
            "componentId": component["componentId"],
            "installed": False,
            "supported": False,
            "phase": "unsupported",
            "target": None,
            "updateAvailable": False,
            "gate": {
                "state": "unknown",
                "activeTasks": [],
                "unknownActivitySources": [],
                "blockerCodes": ["UNSUPPORTED_TARGET"],
                "blockers": [
                    {
                        "code": "UNSUPPORTED_TARGET",
                        "message": "This component has no supported exact Ubuntu/glibc target in the trusted catalog.",
                    }
                ],
            },
            "allowedActions": [],
        }

    def _result_component(
        self,
        component: dict[str, Any],
        gate: dict[str, Any],
        *,
        phase: str,
        available_version: str | None = None,
        update_available: bool | None = None,
        staged: Any = None,
    ) -> dict[str, Any]:
        installed = self._installed(component)
        target = self._target_for(component)
        staged_version = None
        if isinstance(staged, tuple):
            staged_version = staged[1].get("version")
        elif isinstance(staged, dict):
            staged_version = staged.get("component", staged).get("version")
        actions = ["check"]
        if target is not None and update_available is True:
            actions.append("stage")
        is_data_bundle = component.get("kind") == "data-bundle"
        service_managed = target is not None and (
            self._authority_available() if is_data_bundle else self._unit_exists(component)
        )
        if (
            target is not None
            and phase == "staged"
            and gate.get("status") == "READY"
            and service_managed
        ):
            actions.append("apply")
        result = {
            "componentId": component["componentId"],
            "installed": installed["activeVersion"] is not None,
            "supported": target is not None,
            "activeVersion": installed["activeVersion"],
            "availableVersion": available_version,
            "stagedVersion": staged_version,
            "phase": phase,
            "target": target["target"] if target else None,
            "artifactKind": target.get("artifactKind") if target else None,
            "updateAvailable": bool(update_available),
            "gate": self._public_gate(gate),
            "allowedActions": actions,
        }
        if target is not None and not service_managed:
            result["blockers"] = [
                {
                    "code": "AUTHORITY_NOT_MANAGED" if is_data_bundle else "SERVICE_NOT_MANAGED",
                    "message": "Authority's restricted local activation socket is unavailable."
                    if is_data_bundle
                    else "The OS target is available, but no catalog-matched local systemd service is installed.",
                }
            ]
        return {key: value for key, value in result.items() if value is not None}

    def _installed(self, component: dict[str, Any]) -> dict[str, Any]:
        if component.get("kind") == "data-bundle":
            if not self._authority_available():
                return self._empty_installed()
            status = self._authority_request({"action": "status"})
            artifact_id = status.get("activeArtifactId")
            if artifact_id is None:
                return self._empty_installed()
            if not _valid_digest(artifact_id):
                raise UpdateError(
                    "AUTHORITY_STATUS_INVALID",
                    "Authority returned an invalid active artifact identity.",
                )
            receipt_directory = self._installed_component_directory(component["componentId"])
            releases = receipt_directory / "releases" if receipt_directory else None
            if releases is not None and releases.is_dir() and not releases.is_symlink():
                for receipt_path in releases.glob("*.json"):
                    identity = "sha256:" + receipt_path.stem
                    receipt = self._read_release_receipt(component["componentId"], identity)
                    if receipt is None or receipt.get("artifactDigest") != artifact_id:
                        continue
                    manifest = receipt.get("manifest")
                    self._validate_manifest_digest(manifest, identity)
                    if _artifact_kind_from_manifest(manifest) != "data-bundle":
                        raise UpdateError(
                            "INVALID_INSTALLED_RELEASE",
                            "Authority data-bundle receipt has the wrong artifact kind.",
                        )
                    return {
                        "activeVersion": manifest["version"],
                        "manifest": manifest,
                        "active": True,
                        "identityAttested": True,
                        "releaseIdentity": identity,
                        "manifestDigest": identity,
                        "artifactDigest": artifact_id,
                        "pointerIdentity": artifact_id.removeprefix("sha256:"),
                        "bundleIdentity": artifact_id,
                        "authorityGeneration": status.get("highestGeneration"),
                        "authorityActivationEpoch": status.get("activationEpoch"),
                    }
            return {
                "activeVersion": artifact_id,
                "manifest": None,
                "active": True,
                "identityAttested": True,
                "releaseIdentity": artifact_id,
                "manifestDigest": None,
                "artifactDigest": artifact_id,
                "pointerIdentity": artifact_id.removeprefix("sha256:"),
                "bundleIdentity": artifact_id,
                "authorityGeneration": status.get("highestGeneration"),
                "authorityActivationEpoch": status.get("activationEpoch"),
            }
        service = component.get("pythonBundleService")
        if service:
            try:
                module = self._load_service_bundle()
                active = module.resolve_active_release(service, install_root=self.install_root)
                if active is None:
                    if self._read_active_receipt(component["componentId"]) is not None:
                        raise UpdateError(
                            "INVALID_INSTALLED_RELEASE",
                            f"Installed identity receipt exists without an active {service} bundle.",
                        )
                    return self._empty_installed()
                inner = module.validate_bundle(active[0].parent, expected_service=service)
                bundle_identity = inner.get("artifact_digest")
                pointer_identity = active[1]
                receipt = self._read_active_receipt(component["componentId"])
                if receipt is None:
                    # Existing inner bundles remain readable and can be restored,
                    # but an inner hash cannot stand in for a verified outer release.
                    return {
                        **self._empty_installed(active_version=active[1], active=True),
                        "manifest": inner,
                        "pointerIdentity": pointer_identity,
                        "bundleIdentity": bundle_identity,
                    }
                outer = receipt["manifest"]
                if (
                    _artifact_kind_from_manifest(outer) != "python-bundle"
                    or receipt["bundleIdentity"] != bundle_identity
                    or receipt.get("pointerIdentity", pointer_identity) != pointer_identity
                ):
                    raise UpdateError(
                        "INVALID_INSTALLED_RELEASE",
                        f"Installed {component['componentId']} receipt does not match the active bundle pointer.",
                    )
                return {
                    "activeVersion": outer["version"],
                    "manifest": outer,
                    "active": True,
                    "identityAttested": True,
                    "releaseIdentity": receipt["releaseIdentity"],
                    "manifestDigest": receipt["manifestDigest"],
                    "artifactDigest": receipt["artifactDigest"],
                    "pointerIdentity": pointer_identity,
                    "bundleIdentity": bundle_identity,
                }
            except UpdateError:
                raise
            except Exception as error:
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE",
                    f"Installed {component['componentId']} release failed integrity validation: {error}",
                ) from error
        root = self.install_root / "components" / component["componentId"]
        active = root / "active"
        if not active.exists() and not active.is_symlink():
            if self._read_active_receipt(component["componentId"]) is not None:
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE",
                    f"Installed identity receipt exists without an active {component['componentId']} release.",
                )
            return self._empty_installed()
        info = active.lstat()
        if not stat.S_ISLNK(info.st_mode) or info.st_uid != 0:
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Active pointer is unsafe for {component['componentId']}.",
            )
        target = os.readlink(active)
        match = re.fullmatch(r"releases/([^/]+)", target)
        if not match:
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Active pointer has an unsafe target for {component['componentId']}.",
            )
        pointer_identity = match.group(1)
        version, pointer_digest = _native_release_directory_identity(pointer_identity)
        if VERSION_PATTERN.fullmatch(version) is None:
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Active pointer has an unsafe release identity for {component['componentId']}.",
            )
        release = root / "releases" / pointer_identity
        if release.is_symlink() or not release.is_dir():
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Active release directory is unsafe for {component['componentId']}.",
            )
        manifest = _read_object(
            release / "component-manifest.json", f"installed {component['componentId']} manifest"
        )
        self._validate_manifest_digest(manifest, manifest.get("manifestDigest"))
        if (
            manifest.get("componentId") != component["componentId"]
            or manifest.get("version") != version
            or _artifact_kind_from_manifest(manifest) != "native-binary"
            or (
                pointer_digest is not None
                and pointer_digest != manifest["manifestDigest"].removeprefix("sha256:")
            )
            or (pointer_digest is None and pointer_identity != version)
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Installed release identity differs for {component['componentId']}.",
            )
        artifact_digest = _artifact_digest_from_manifest(manifest)
        if not _valid_digest(artifact_digest):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Installed artifact digest is invalid for {component['componentId']}.",
            )
        receipt = self._read_active_receipt(component["componentId"])
        if receipt is None:
            receipt = self._read_release_receipt(
                component["componentId"], manifest["manifestDigest"]
            )
        if receipt is not None:
            self._validate_active_receipt(
                receipt,
                component_id=component["componentId"],
                manifest=manifest,
                artifact_digest=artifact_digest,
                pointer_identity=pointer_identity,
                bundle_identity=None,
            )
        return {
            "activeVersion": version,
            "manifest": manifest,
            "active": True,
            "identityAttested": receipt is not None,
            "releaseIdentity": manifest["manifestDigest"],
            "manifestDigest": manifest["manifestDigest"],
            "artifactDigest": artifact_digest,
            "pointerIdentity": pointer_identity,
            "bundleIdentity": None,
        }

    @staticmethod
    def _empty_installed(
        *, active_version: str | None = None, active: bool = False
    ) -> dict[str, Any]:
        return {
            "activeVersion": active_version,
            "manifest": None,
            "active": active,
            "identityAttested": False,
            "releaseIdentity": None,
            "manifestDigest": None,
            "artifactDigest": None,
            "pointerIdentity": None,
            "bundleIdentity": None,
        }

    def _authority_available(self) -> bool:
        try:
            info = self.authority_admin_socket.lstat()
        except OSError:
            return False
        mode = stat.S_IMODE(info.st_mode)
        return stat.S_ISSOCK(info.st_mode) and info.st_uid == 0 and not (mode & 0o007)

    def _authority_request(self, request: dict[str, Any]) -> dict[str, Any]:
        if not self._authority_available():
            raise UpdateError(
                "AUTHORITY_NOT_MANAGED",
                "Authority's restricted local activation socket is unavailable.",
            )
        if not isinstance(request.get("action"), str) or request["action"] not in {
            "status",
            "validateArtifact",
            "activateArtifact",
        }:
            raise UpdateError("AUTHORITY_REQUEST_INVALID", "Authority action is not supported.")
        request_fields = {
            "status": {"action"},
            "validateArtifact": {"action", "planId", "planDigest", "artifactId"},
            "activateArtifact": {
                "action",
                "planId",
                "planDigest",
                "expectedGeneration",
                "artifactId",
            },
        }[request["action"]]
        if set(request) != request_fields:
            raise UpdateError(
                "AUTHORITY_REQUEST_INVALID", "Authority request contains an unexpected field."
            )
        if request["action"] != "status" and (
            not isinstance(request.get("planId"), str)
            or re.fullmatch(r"[A-Za-z0-9._-]{1,128}", request["planId"]) is None
            or not _valid_digest(request.get("planDigest"))
            or not _valid_digest(request.get("artifactId"))
            or (
                request["action"] == "activateArtifact"
                and (
                    not isinstance(request.get("expectedGeneration"), int)
                    or isinstance(request.get("expectedGeneration"), bool)
                    or request["expectedGeneration"] < 0
                )
            )
        ):
            raise UpdateError(
                "AUTHORITY_REQUEST_INVALID", "Authority plan or artifact identity is invalid."
            )
        try:
            payload = (json.dumps(request, separators=(",", ":")) + "\n").encode("utf-8")
            with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as connection:
                connection.settimeout(15)
                connection.connect(str(self.authority_admin_socket))
                connection.sendall(payload)
                response = bytearray()
                while len(response) <= 1024 * 1024:
                    chunk = connection.recv(4096)
                    if not chunk:
                        break
                    response.extend(chunk)
                    if b"\n" in chunk:
                        break
            line, separator, rest = response.partition(b"\n")
            if not separator or rest.strip():
                raise UpdateError(
                    "AUTHORITY_PROTOCOL_ERROR", "Authority returned an incomplete JSONL response."
                )
            value = json.loads(line.decode("utf-8"))
        except UpdateError:
            raise
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, TimeoutError) as error:
            raise UpdateError(
                "AUTHORITY_UNAVAILABLE", f"Authority admin request failed: {error}", retryable=True
            ) from error
        expected_status = {
            "status": "ok",
            "validateArtifact": "valid",
            "activateArtifact": "activated",
        }[request["action"]]
        if not isinstance(value, dict) or value.get("status") != expected_status:
            code = value.get("code") if isinstance(value, dict) else None
            message = value.get("message") if isinstance(value, dict) else None
            raise UpdateError(
                "AUTHORITY_REQUEST_REJECTED",
                str(message or code or "Authority rejected the restricted activation request."),
                retryable=bool(value.get("retryable")) if isinstance(value, dict) else False,
            )
        return value

    def _installed_component_directory(
        self, component_id: str, *, create: bool = False
    ) -> Path | None:
        if COMPONENT_ID_PATTERN.fullmatch(component_id) is None:
            raise UpdateError(
                "INVALID_COMPONENT", "Component ID is invalid for the installed receipt store."
            )
        root = self._private_state_directory("installed")
        directory = root / component_id
        if not directory.exists() and not directory.is_symlink():
            if not create:
                return None
            try:
                directory.mkdir(mode=0o700)
            except OSError as error:
                raise UpdateError(
                    "UNSAFE_STATE",
                    f"Cannot create installed identity directory for {component_id}: {error}",
                ) from error
        _verify_private_directory(directory)
        return directory

    def _read_active_receipt(self, component_id: str) -> dict[str, Any] | None:
        directory = self._installed_component_directory(component_id)
        if directory is None:
            return None
        active_path = directory / "active.json"
        if not active_path.exists() and not active_path.is_symlink():
            return None
        active = _read_object(active_path, f"{component_id} active release receipt")
        if (
            set(active) != {"schemaVersion", "componentId", "releaseIdentity", "bundleIdentity"}
            or active.get("schemaVersion") != 1
            or active.get("componentId") != component_id
            or not _valid_digest(active.get("releaseIdentity"))
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Installed active receipt is malformed for {component_id}.",
            )
        release_identity = active["releaseIdentity"]
        receipt = self._read_release_receipt(component_id, release_identity)
        if receipt is None:
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Installed release receipt is missing for {component_id}.",
            )
        if receipt.get("bundleIdentity") != active.get("bundleIdentity"):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Installed active receipt bundle identity differs for {component_id}.",
            )
        return receipt

    def _read_release_receipt(
        self, component_id: str, release_identity: str
    ) -> dict[str, Any] | None:
        if not _valid_digest(release_identity):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Installed release identity is invalid for {component_id}.",
            )
        directory = self._installed_component_directory(component_id)
        if directory is None:
            return None
        releases = directory / "releases"
        if not releases.exists() and not releases.is_symlink():
            return None
        _verify_private_directory(releases)
        receipt_path = releases / (release_identity.removeprefix("sha256:") + ".json")
        if not receipt_path.exists() and not receipt_path.is_symlink():
            return None
        receipt = _read_object(receipt_path, f"{component_id} verified release receipt")
        required = {
            "schemaVersion",
            "componentId",
            "releaseIdentity",
            "manifestDigest",
            "artifactDigest",
            "version",
            "bundleIdentity",
            "manifest",
        }
        version = receipt.get("schemaVersion")
        workload_fields = {
            "releaseId",
            "targetId",
            "manifestAssetDigest",
            "manifestUri",
            "releaseTag",
            "indexIdentity",
            "publisherIdentity",
            "attestationRef",
            "releasePath",
            "archivePath",
            "pointerIdentity",
        }
        manifest = receipt.get("manifest")
        if (
            set(receipt) != (required if version == 1 else required | workload_fields)
            or version not in {1, 2}
            or receipt.get("componentId") != component_id
            or receipt.get("releaseIdentity") != release_identity
            or receipt.get("manifestDigest") != release_identity
            or not _valid_digest(receipt.get("artifactDigest"))
            or not isinstance(receipt.get("version"), str)
            or VERSION_PATTERN.fullmatch(receipt["version"]) is None
            or not isinstance(manifest, dict)
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Installed release receipt is malformed for {component_id}.",
            )
        if version == 2:
            manifest_uri = receipt.get("manifestUri")
            parsed_manifest_uri = (
                urllib.parse.urlsplit(manifest_uri) if isinstance(manifest_uri, str) else None
            )
            if (
                not isinstance(receipt.get("releaseId"), str)
                or not receipt["releaseId"]
                or not isinstance(receipt.get("targetId"), str)
                or not receipt["targetId"]
                or not _valid_digest(receipt.get("manifestAssetDigest"))
                or parsed_manifest_uri is None
                or parsed_manifest_uri.scheme != "https"
                or not parsed_manifest_uri.netloc
                or not isinstance(receipt.get("releaseTag"), str)
                or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,255}", receipt["releaseTag"]) is None
                or not isinstance(receipt.get("indexIdentity"), dict)
                or not isinstance(receipt.get("publisherIdentity"), dict)
                or receipt.get("attestationRef") is not None
                and not isinstance(receipt.get("attestationRef"), dict)
                or any(
                    not isinstance(receipt.get(field), str)
                    or not Path(receipt[field]).is_absolute()
                    for field in ("releasePath", "archivePath")
                )
                or not isinstance(receipt.get("pointerIdentity"), str)
                or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,255}", receipt["pointerIdentity"])
                is None
            ):
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE",
                    f"Installed workload release evidence is incomplete for {component_id}.",
                )
            expected_release_id = manifest.get("releaseId", receipt.get("releaseTag"))
            if receipt.get("releaseId") != expected_release_id:
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE",
                    f"Installed release tag differs from its manifest for {component_id}.",
                )
        self._validate_manifest_digest(manifest, release_identity)
        if (
            manifest.get("componentId") != component_id
            or manifest.get("version") != receipt["version"]
            or _artifact_digest_from_manifest(manifest) != receipt["artifactDigest"]
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Installed manifest does not match its receipt for {component_id}.",
            )
        return receipt

    def _validate_active_receipt(
        self,
        receipt: dict[str, Any],
        *,
        component_id: str,
        manifest: dict[str, Any],
        artifact_digest: str,
        pointer_identity: str,
        bundle_identity: str | None,
    ) -> None:
        if (
            receipt.get("manifest") != manifest
            or receipt.get("artifactDigest") != artifact_digest
            or receipt.get("bundleIdentity") != bundle_identity
            or (
                receipt.get("pointerIdentity") is not None
                and receipt.get("pointerIdentity") != pointer_identity
            )
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Installed {component_id} receipt does not match its active release pointer.",
            )

    def _write_release_receipt(self, item: dict[str, Any]) -> None:
        component_id = item["componentId"]
        manifest = item["manifest"]
        if (
            item.get("releaseIdentity") != item.get("manifestDigest")
            or not _valid_digest(item.get("releaseIdentity"))
            or item.get("artifactDigest") != _artifact_digest_from_manifest(manifest)
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Cannot persist an incomplete verified identity for {component_id}.",
            )
        self._validate_manifest_digest(manifest, item["releaseIdentity"])
        receipt_directory = self._installed_component_directory(component_id, create=True)
        assert receipt_directory is not None
        releases = receipt_directory / "releases"
        if not releases.exists():
            releases.mkdir(mode=0o700)
        _verify_private_directory(releases)
        receipt = {
            "schemaVersion": 1,
            "componentId": component_id,
            "releaseIdentity": item["releaseIdentity"],
            "manifestDigest": item["manifestDigest"],
            "artifactDigest": item["artifactDigest"],
            "version": item["version"],
            "bundleIdentity": item["bundleIdentity"],
            "manifest": manifest,
        }
        workload_fields = (
            "releaseId",
            "targetId",
            "manifestAssetDigest",
            "manifestUri",
            "releaseTag",
            "indexIdentity",
            "publisherIdentity",
            "attestationRef",
            "releasePath",
            "archivePath",
            "pointerIdentity",
        )
        if any(field in item for field in workload_fields):
            if any(field not in item for field in workload_fields):
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE",
                    f"Cannot persist incomplete workload release evidence for {component_id}.",
                )
            receipt.update({field: item[field] for field in workload_fields})
            receipt["schemaVersion"] = 2
            if not _valid_digest(receipt.get("manifestAssetDigest")):
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE",
                    f"Cannot persist an invalid raw manifest digest for {component_id}.",
                )
            if not isinstance(receipt.get("targetId"), str) or not receipt["targetId"]:
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE",
                    f"Cannot persist a missing target identity for {component_id}.",
                )
        path = releases / (item["manifestDigest"].removeprefix("sha256:") + ".json")
        if path.exists() or path.is_symlink():
            existing = _read_object(path, f"{component_id} verified release receipt")
            if existing != receipt:
                base_fields = (
                    "componentId",
                    "releaseIdentity",
                    "manifestDigest",
                    "artifactDigest",
                    "version",
                    "bundleIdentity",
                    "manifest",
                )
                if any(existing.get(field) != receipt.get(field) for field in base_fields):
                    raise UpdateError(
                        "RELEASE_RECEIPT_COLLISION",
                        f"Verified receipt identity collision for {component_id}.",
                    )
                if existing.get("schemaVersion") == 2 and receipt.get("schemaVersion") == 1:
                    return
                if existing.get("schemaVersion") != 1 or receipt.get("schemaVersion") != 2:
                    raise UpdateError(
                        "RELEASE_RECEIPT_COLLISION",
                        f"Verified release evidence changed for {component_id}.",
                    )
                _atomic_json(path, receipt)
            return
        _atomic_json(path, receipt)

    def _write_active_receipt(self, item: dict[str, Any]) -> None:
        directory = self._installed_component_directory(item["componentId"], create=True)
        assert directory is not None
        active_path = directory / "active.json"
        if active_path.is_symlink():
            raise UpdateError(
                "UNSAFE_STATE",
                f"Refusing a symlinked active identity receipt for {item['componentId']}.",
            )
        active = {
            "schemaVersion": 1,
            "componentId": item["componentId"],
            "releaseIdentity": item["releaseIdentity"],
            "bundleIdentity": item["bundleIdentity"],
        }
        _atomic_json(active_path, active)

    def _restore_active_receipt(self, component_id: str, previous: dict[str, Any]) -> None:
        if previous.get("identityAttested") is not True:
            self._clear_active_receipt(component_id)
            return
        if previous.get("manifestDigest") != previous.get("releaseIdentity") or not _valid_digest(
            previous.get("releaseIdentity")
        ):
            raise UpdateError(
                "TRANSACTION_IDENTITY_UNKNOWN",
                f"Previous {component_id} receipt identity is incomplete.",
            )
        directory = self._installed_component_directory(component_id)
        if directory is None:
            raise UpdateError(
                "TRANSACTION_IDENTITY_UNKNOWN", f"Previous {component_id} receipt is missing."
            )
        receipt = self._read_release_receipt(component_id, previous["releaseIdentity"])
        if receipt is None:
            raise UpdateError(
                "TRANSACTION_IDENTITY_UNKNOWN", f"Previous {component_id} receipt is missing."
            )
        if (
            receipt.get("releaseIdentity") != previous["releaseIdentity"]
            or receipt.get("artifactDigest") != previous.get("artifactDigest")
            or receipt.get("bundleIdentity") != previous.get("bundleIdentity")
            or receipt.get("version") != previous.get("version")
        ):
            raise UpdateError(
                "TRANSACTION_IDENTITY_UNKNOWN",
                f"Previous {component_id} receipt does not match the transaction journal.",
            )
        active = {
            "schemaVersion": 1,
            "componentId": component_id,
            "releaseIdentity": previous["releaseIdentity"],
            "bundleIdentity": previous.get("bundleIdentity"),
        }
        _atomic_json(directory / "active.json", active)

    def _clear_active_receipt(self, component_id: str) -> None:
        directory = self._installed_component_directory(component_id)
        if directory is None:
            return
        active_path = directory / "active.json"
        if active_path.is_symlink():
            raise UpdateError(
                "UNSAFE_STATE", f"Refusing a symlinked active identity receipt for {component_id}."
            )
        if active_path.exists():
            active_path.unlink()
            self._fsync_directory(directory)

    def _load_service_bundle(self) -> Any:
        candidates = [
            self.install_root / "scripts" / "service_bundle.py",
            self.install_root / "packaging" / "service_bundle.py",
            Path(__file__).with_name("service_bundle.py"),
        ]
        module_path = next((candidate for candidate in candidates if candidate.is_file()), None)
        if module_path is None:
            raise UpdateError("SERVICE_BUNDLE_MISSING", "The Product bundle verifier is missing.")
        import importlib.util

        spec = importlib.util.spec_from_file_location(
            "_cyrene_component_service_bundle", module_path
        )
        if spec is None or spec.loader is None:
            raise UpdateError("SERVICE_BUNDLE_MISSING", "Cannot load the Product bundle verifier.")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module

    def _load_native_package_runtime_bootstrap(self) -> Any:
        module_path = Path(__file__).with_name("native_package_runtime_bootstrap.py")
        if not module_path.is_file():
            raise UpdateError(
                "PACKAGE_RUNTIME_BOOTSTRAP_MISSING",
                "The signed Package Runtime bootstrap helper is missing.",
            )
        import importlib.util

        module_name = "_cyrene_native_package_runtime_bootstrap"
        spec = importlib.util.spec_from_file_location(module_name, module_path)
        if spec is None or spec.loader is None:
            raise UpdateError(
                "PACKAGE_RUNTIME_BOOTSTRAP_MISSING",
                "The signed Package Runtime bootstrap helper cannot be loaded.",
            )
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        spec.loader.exec_module(module)
        return module

    def _load_native_first_products_bootstrap(self) -> Any:
        """Load the signed first-Product receipt and bundle verifier."""

        module_path = Path(__file__).with_name("native_first_products.py")
        if not module_path.is_file() or module_path.is_symlink():
            raise UpdateError(
                "PRODUCT_COHORT_UNAVAILABLE",
                "The signed Product cohort verifier is missing or unsafe.",
            )
        import importlib.util

        module_name = "_cyrene_native_first_products_for_package_bootstrap"
        spec = importlib.util.spec_from_file_location(module_name, module_path)
        if spec is None or spec.loader is None:
            raise UpdateError(
                "PRODUCT_COHORT_UNAVAILABLE", "The signed Product cohort verifier cannot load."
            )
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        try:
            spec.loader.exec_module(module)
        except Exception as error:
            raise UpdateError(
                "PRODUCT_COHORT_UNAVAILABLE", "The signed Product cohort verifier failed."
            ) from error
        return module

    def _package_bootstrap_product_units(
        self, activity_catalog: dict[str, Any], package_helper: Any
    ) -> tuple[Any, list[dict[str, Any]], list[dict[str, Any]]]:
        """Derive the exact five Product sources from installed signed evidence.

        中文：从已安装签名回执、bundle 和可信 catalog 派生唯一客户端集合。
        """

        first_products = self._load_native_first_products_bootstrap()
        receipt = first_products._read_receipt()
        target_id = receipt.get("installer", {}).get("targetId")
        receipt, products = first_products._verified_products(
            self, {"targetId": target_id}, first_products.RECEIPT_PATH
        )
        expected = tuple(
            service for _source, _unit, service in package_helper.PACKAGE_BOOTSTRAP_PRODUCT_SOURCES
        )
        if tuple(row.get("service") for row in products) != expected:
            raise UpdateError(
                "PRODUCT_COHORT_UNKNOWN", "Installed signed Product cohort membership is unknown."
            )
        source_records = {
            source["source_id"]: source for source in activity_catalog.get("sources", [])
        }
        expected_source_ids = {
            source_id
            for source_id, _unit, _service in package_helper.PACKAGE_BOOTSTRAP_PRODUCT_SOURCES
        }
        if set(source_records) != expected_source_ids:
            raise UpdateError(
                "PRODUCT_COHORT_UNKNOWN",
                "Runtime activity sources do not exactly match the five signed Product clients.",
                retryable=True,
            )
        rows: list[dict[str, Any]] = []
        for product, (source_id, expected_unit, service) in zip(
            products, package_helper.PACKAGE_BOOTSTRAP_PRODUCT_SOURCES, strict=True
        ):
            component_id = product.get("componentId")
            component = self.components.get(component_id)
            source = source_records.get(source_id)
            if (
                not isinstance(component, dict)
                or component_id != source_id
                or product.get("service") != service
                or component.get("systemdUnit") != expected_unit
                or not isinstance(source, dict)
            ):
                raise UpdateError(
                    "PRODUCT_COHORT_UNKNOWN",
                    f"Signed Product source or unit identity differs for {service}.",
                    retryable=True,
                )
            try:
                first_products._unit_path(self, component, service)
            except Exception as error:
                raise UpdateError(
                    "PRODUCT_COHORT_UNKNOWN",
                    f"Signed Product unit identity is unsafe for {service}.",
                    retryable=True,
                ) from error
            rows.append(
                {
                    "source_id": source_id,
                    "component_id": component_id,
                    "unit": expected_unit,
                    "service": service,
                    "uid": source["uid"],
                    "gid": source["gid"],
                    "source_token_sha256": source["source_token_sha256"],
                }
            )
        return first_products, rows, products

    def _package_product_unit_state(self, unit: str) -> str:
        """Read only an explicit active/inactive systemd state for a fixed unit."""

        try:
            result = self.runner(
                ["systemctl", "show", "--property=ActiveState", "--value", unit],
                capture_output=True,
                text=True,
                timeout=10,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired) as error:
            raise UpdateError(
                "PRODUCT_STATE_UNKNOWN",
                f"Cannot read Product unit state for {unit}.",
                retryable=True,
            ) from error
        state = result.stdout.strip()
        if result.returncode != 0 or state not in {"active", "inactive"}:
            raise UpdateError(
                "PRODUCT_STATE_UNKNOWN",
                f"Product unit {unit} has an unknown systemd state.",
                retryable=True,
            )
        return state

    def _capture_package_product_activity(
        self,
        first_products: Any,
        product_units: list[dict[str, Any]],
        verified_products: list[dict[str, Any]],
    ) -> list[dict[str, str]]:
        """Record active products only after signed pointer/process/API checks.

        中文：只有指针、进程身份和签名健康端点都通过才记录为活动客户端。
        """

        active: list[dict[str, str]] = []
        for row in product_units:
            state = self._package_product_unit_state(row["unit"])
            if state == "active":
                try:
                    product = next(
                        product
                        for product in verified_products
                        if product["service"] == row["service"]
                    )
                    first_products._live_product(self, product)
                except Exception as error:
                    raise UpdateError(
                        "PRODUCT_STATE_UNKNOWN",
                        f"Active Product identity or health is unverified for {row['service']}.",
                        retryable=True,
                    ) from error
                active.append({"source_id": row["source_id"], "unit": row["unit"]})
            else:
                try:
                    pid = first_products._main_pid(self, row["unit"])
                except Exception as error:
                    raise UpdateError(
                        "PRODUCT_STATE_UNKNOWN",
                        f"Inactive Product process state is unknown for {row['service']}.",
                        retryable=True,
                    ) from error
                if pid != 0:
                    raise UpdateError(
                        "PRODUCT_STATE_UNKNOWN",
                        f"Inactive Product unit still has a MainPID: {row['service']}.",
                        retryable=True,
                    )
        return active

    def _wait_package_products_quiesced(
        self, first_products: Any, product_units: list[dict[str, Any]]
    ) -> None:
        """Wait until every fixed Product unit is inactive with MainPID zero."""

        deadline = time.monotonic() + 90
        while time.monotonic() < deadline:
            stopped = True
            for row in product_units:
                if self._package_product_unit_state(row["unit"]) != "inactive":
                    stopped = False
                    break
                if first_products._main_pid(self, row["unit"]) != 0:
                    stopped = False
                    break
            if stopped:
                return
            time.sleep(1)
        raise UpdateError(
            "PRODUCT_QUIESCE_TIMEOUT",
            "A Product unit did not stop within 90 seconds.",
            retryable=True,
        )

    @staticmethod
    def _verify_package_activity_generation(generation: int) -> None:
        """Read back the exact shared generation consumed by all Product units."""

        path = DEFAULT_PACKAGE_ACTIVITY_ENVIRONMENT
        descriptor: int | None = None
        try:
            before = path.lstat()
            descriptor = os.open(
                path,
                os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0),
            )
            info = os.fstat(descriptor)
            if (
                path.is_symlink()
                or not stat.S_ISREG(info.st_mode)
                or info.st_uid != 0
                or info.st_gid != 0
                or stat.S_IMODE(info.st_mode) != 0o644
                or info.st_nlink != 1
                or info.st_dev != before.st_dev
                or info.st_ino != before.st_ino
                or info.st_size > 4096
            ):
                raise UpdateError(
                    "PRODUCT_ENVIRONMENT_UNKNOWN",
                    "Shared Product activity generation metadata is unsafe.",
                    retryable=True,
                )
            content = os.read(descriptor, 4097)
        except OSError as error:
            raise UpdateError(
                "PRODUCT_ENVIRONMENT_UNKNOWN", "Shared Product activity generation is unavailable."
            ) from error
        finally:
            if descriptor is not None:
                os.close(descriptor)
        expected = f"CYRENE_RUNTIME_ACTIVITY_CATALOG_GENERATION={generation}\n".encode("ascii")
        if content != expected:
            raise UpdateError(
                "PRODUCT_ENVIRONMENT_UNKNOWN",
                "Shared Product activity generation does not match the committed catalog.",
                retryable=True,
            )

    def _restore_package_product_activity(
        self,
        first_products: Any,
        product_units: list[dict[str, Any]],
        verified_products: list[dict[str, Any]],
        prior_active_products: list[dict[str, str]],
    ) -> None:
        """Restore exactly the previously active clients and verify signed health.

        中文：只恢复原先活动的客户端，保持原先停用的服务停用。
        """

        active_units = {item.get("unit") for item in prior_active_products}
        if not active_units <= {row["unit"] for row in product_units}:
            raise UpdateError("PRODUCT_STATE_UNKNOWN", "Journal names a foreign Product unit.")
        products_by_service = {item["service"]: item for item in verified_products}
        for row in product_units:
            was_active = row["unit"] in active_units
            state = self._package_product_unit_state(row["unit"])
            if was_active:
                if state == "inactive":
                    self._run_systemctl("start", row["unit"])
                    self._wait_unit_active(row["unit"])
                product = products_by_service.get(row["service"])
                if product is None:
                    raise UpdateError(
                        "PRODUCT_COHORT_UNKNOWN", "Signed Product health identity is missing."
                    )
                first_products._live_product(self, product)
            else:
                if state != "inactive" or first_products._main_pid(self, row["unit"]) != 0:
                    raise UpdateError(
                        "PRODUCT_STATE_CHANGED",
                        f"Previously inactive Product became active: {row['service']}.",
                        retryable=True,
                    )

    def _load_native_runtime_schema_migration(self) -> Any:
        """Load the signed helper that derives legacy state profile and proof bytes."""
        import importlib.util

        module_path = Path(__file__).with_name("native_runtime_schema_migration.py")
        if not module_path.is_file() or module_path.is_symlink():
            raise UpdateError(
                "SCHEMA_ADOPTION_UNAVAILABLE",
                "The signed Core schema-migration helper is missing or unsafe.",
            )
        module_name = "_cyrene_native_runtime_schema_migration"
        spec = importlib.util.spec_from_file_location(module_name, module_path)
        if spec is None or spec.loader is None:
            raise UpdateError(
                "SCHEMA_ADOPTION_UNAVAILABLE",
                "The signed Core schema-migration helper cannot be loaded.",
            )
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        try:
            spec.loader.exec_module(module)
        except Exception as error:
            raise UpdateError(
                "SCHEMA_ADOPTION_UNAVAILABLE",
                "The signed Core schema-migration helper failed to load.",
            ) from error
        return module

    def inspect_plugin_package_plan(self) -> dict[str, Any]:
        """Verify the fixed package cache and return its current confirmable plan."""

        self._require_authorized_process()
        helper = self._load_native_package_runtime_bootstrap()
        with self._exclusive_update_lock():
            verified = helper.verify_cached_package_candidate()
            activity_catalog, _sources = self._activity_catalog()
            _first_products, product_units, _verified_products = (
                self._package_bootstrap_product_units(activity_catalog, helper)
            )
            readiness = self._readiness_for("PACKAGE_ONLY", requires_restart=False, force=True)
            self._require_ready(readiness, "PACKAGE_ONLY")
            gate_generation = readiness.get("gate_generation")
            if type(gate_generation) is not int or gate_generation < 1:
                raise UpdateError(
                    "GATE_UNKNOWN", "Package Runtime gate generation is unknown.", retryable=True
                )
            plan = helper.build_package_bootstrap_plan(
                verified,
                catalog_generation=activity_catalog["generation"],
                gate_generation=gate_generation,
                affected_product_units=product_units,
            )
        return {
            "planId": plan.plan_id,
            "planDigest": plan.plan_digest,
            "catalogGeneration": plan.catalog_generation,
            "gateGeneration": plan.gate_generation,
            "componentArtifactDigests": plan.component_artifact_digests,
            "candidate": plan.material,
        }

    def bootstrap_plugin_package_runtime(
        self,
        *,
        plan_id: Any,
        plan_digest: Any,
        confirmation: Any,
    ) -> dict[str, Any]:
        """Install one reverified package under an exact confirmed broker hold."""

        self._require_authorized_process()
        if not _running_as_root():
            raise UpdateError(
                "PRIVILEGE_REQUIRED", "Package Runtime bootstrap requires the root updater."
            )
        helper = self._load_native_package_runtime_bootstrap()
        with self._exclusive_update_lock():
            self._assert_no_pending_catalog_intent()
            if isinstance(plan_id, str) and PLAN_ID_PATTERN.fullmatch(plan_id):
                pending_path = self._private_state_directory("transactions") / f"{plan_id}.json"
                if pending_path.exists() or pending_path.is_symlink():
                    return self._resume_package_bootstrap_clients(
                        helper,
                        pending_path,
                        plan_id=plan_id,
                        plan_digest=plan_digest,
                        confirmation=confirmation,
                    )
            verified = helper.verify_cached_package_candidate()
            activity_catalog, activity_sources = self._activity_catalog()
            first_products, product_units, verified_products = (
                self._package_bootstrap_product_units(activity_catalog, helper)
            )
            readiness = self._readiness_for("PACKAGE_ONLY", requires_restart=False, force=True)
            self._require_ready(readiness, "PACKAGE_ONLY")
            gate_generation = readiness.get("gate_generation")
            if type(gate_generation) is not int or gate_generation < 1:
                raise UpdateError(
                    "GATE_UNKNOWN", "Package Runtime gate generation is unknown.", retryable=True
                )
            plan = helper.build_package_bootstrap_plan(
                verified,
                catalog_generation=activity_catalog["generation"],
                gate_generation=gate_generation,
                affected_product_units=product_units,
            )
            if plan_id != plan.plan_id or plan_digest != plan.plan_digest:
                raise UpdateError(
                    "PLAN_CHANGED", "Package Runtime candidate differs from the reviewed plan."
                )
            try:
                helper.validate_package_bootstrap_confirmation(
                    plan,
                    {
                        "plan_id": plan_id,
                        "plan_digest": plan_digest,
                        "confirmed": confirmation is True,
                    },
                )
            except helper.PackageRuntimeBootstrapError as error:
                raise UpdateError("CONFIRMATION_MISMATCH", str(error)) from error

            if readiness.get("install_catalog_generation") != activity_catalog["generation"]:
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Activity catalog changed during Package Runtime readiness.",
                    retryable=True,
                )

            try:
                prior_active_products = self._capture_package_product_activity(
                    first_products, product_units, verified_products
                )
            except UpdateError:
                raise
            except Exception as error:
                raise UpdateError(
                    "PRODUCT_STATE_UNKNOWN",
                    "The five signed Product units could not be safely inventoried.",
                    retryable=True,
                ) from error

            transaction_id = f"cyrene-update-{plan.plan_id}"
            transaction_path = (
                self._private_state_directory("transactions") / f"{plan.plan_id}.json"
            )
            if transaction_path.exists() or transaction_path.is_symlink():
                raise UpdateError(
                    "PENDING_MAINTENANCE",
                    "An existing package plan journal must be reconciled before retry.",
                    retryable=True,
                )
            transaction = {
                "schemaVersion": 1,
                "transactionKind": "package-runtime-bootstrap.v1",
                "planId": plan.plan_id,
                "planDigest": plan.plan_digest,
                "plannedGateGeneration": plan.gate_generation,
                "plannedCatalogGeneration": plan.catalog_generation,
                "requestId": transaction_id,
                "componentArtifactDigests": plan.component_artifact_digests,
                "targetKind": "PACKAGE_ONLY",
                "expectedGateGeneration": readiness.get("gate_generation"),
                "expectedCatalogGeneration": activity_catalog["generation"],
                "expectedActivitySources": activity_sources,
                "productCohort": product_units,
                "priorActiveProducts": prior_active_products,
                "phase": "begin_pending",
                "candidate": {
                    **plan.material,
                    "attestationBundleDigests": verified.attestation_bundle_digests,
                },
                "confirmed": True,
                "createdAt": int(time.time()),
            }
            _atomic_json(transaction_path, transaction)
            try:
                begin = self._broker_request(
                    "BeginMaintenance",
                    {
                        "request_id": transaction_id,
                        "target_kind": "PACKAGE_ONLY",
                        "requires_restart": False,
                        "expected_catalog_generation": activity_catalog["generation"],
                        "expected_activity_sources": activity_sources,
                        "expected_gate_generation": readiness.get("gate_generation"),
                        "user_confirmed_restart": True,
                        "plan_id": plan.plan_id,
                        "plan_digest": plan.plan_digest,
                        "component_artifact_digests": plan.component_artifact_digests,
                    },
                    request_id=transaction_id,
                )
            except UpdateError as error:
                if error.maintenance_not_acquired:
                    self._clear_begin_pending(transaction, transaction_path)
                raise
            maintenance_token = begin.get("maintenance_token")
            begin_gate_generation = begin.get("gate_generation")
            if (
                begin.get("status") != "MAINTENANCE_ACTIVE"
                or not isinstance(maintenance_token, str)
                or len(maintenance_token) < 32
                or type(begin_gate_generation) is not int
                or begin_gate_generation < 1
            ):
                transaction["phase"] = "maintenance_state_unknown"
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Package Runtime maintenance ownership was not confirmed; the journal remains pending.",
                    retryable=True,
                )
            transaction["maintenanceToken"] = maintenance_token
            transaction["expectedGateGeneration"] = begin_gate_generation
            transaction["phase"] = "maintenance_active"
            _atomic_json(transaction_path, transaction)

            # Stop only the exact clients that were already healthy and active.
            transaction["phase"] = "product_quiesce_pending"
            _atomic_json(transaction_path, transaction)
            for active_product in prior_active_products:
                self._run_systemctl("stop", active_product["unit"])
            try:
                self._wait_package_products_quiesced(first_products, product_units)
            except Exception as error:
                transaction["phase"] = "product_quiesce_unknown"
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "PRODUCT_QUIESCE_UNKNOWN",
                    "Package Runtime clients did not all prove a stopped state; maintenance remains held.",
                    retryable=True,
                ) from error
            transaction["phase"] = "products_quiesced"
            _atomic_json(transaction_path, transaction)

            maintenance = {
                "transaction_id": transaction_id,
                "maintenance_token": maintenance_token,
                "target_kind": "PACKAGE_ONLY",
                "plan_id": plan.plan_id,
                "plan_digest": plan.plan_digest,
                "component_artifact_digests": plan.component_artifact_digests,
                "expected_gate_generation": begin_gate_generation,
                "expected_catalog_generation": activity_catalog["generation"],
            }
            request_directory, _request_path = helper.stage_offline_install_request(
                verified,
                request_id=transaction_id,
                maintenance=maintenance,
            )
            transaction["stageDirectory"] = str(request_directory)
            _atomic_json(transaction_path, transaction)
            request = helper.build_offline_install_input(
                verified,
                request_id=transaction_id,
                descriptor_path=request_directory / "descriptor.json",
                archive_path=request_directory / "archive.zip",
                maintenance=maintenance,
            )
            installation = helper.run_offline_install(verified, request)
            transaction["installation"] = installation
            transaction["phase"] = "install_complete"
            _atomic_json(transaction_path, transaction)

            current_catalog, _current_sources = self._activity_catalog()
            if current_catalog["generation"] != activity_catalog["generation"]:
                transaction["phase"] = "catalog_generation_unknown"
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Activity catalog changed before package scope commit; maintenance remains held.",
                    retryable=True,
                )
            catalog_update = helper.build_activity_catalog_update(
                verified, installation, current_catalog
            )
            proof_path, scopes_path = helper.stage_catalog_commit_inputs(
                request_directory,
                request_id=transaction_id,
                maintenance=maintenance,
                catalog_update=catalog_update,
            )
            transaction["phase"] = "catalog_update_pending"
            _atomic_json(transaction_path, transaction)
            catalog_command_result = helper.run_activity_catalog_update(
                catalog_update, proof_path=proof_path, scopes_path=scopes_path
            )
            updated_catalog, updated_sources = self._activity_catalog()
            helper.validate_activity_catalog_readback(
                updated_catalog, catalog_update, catalog_command_result
            )
            transaction["expectedCatalogGeneration"] = updated_catalog["generation"]
            transaction["expectedActivitySources"] = updated_sources
            transaction["catalogGeneration"] = updated_catalog["generation"]
            transaction["catalogDigest"] = _file_digest(self.activity_catalog_path)
            transaction["phase"] = "catalog_updated"
            _atomic_json(transaction_path, transaction)

            policy = helper.build_runtime_source_policy(verified, installation, updated_catalog)
            transaction["policyDigest"] = helper.write_runtime_source_policy(policy)
            helper.validate_runtime_source_policy(
                helper.read_runtime_source_policy(), verified, installation, updated_catalog
            )
            transaction["phase"] = "policy_written"
            _atomic_json(transaction_path, transaction)

            previous_generation = activity_catalog["generation"]
            try:
                environment_result = helper.ensure_yield_product_package_environment(
                    verified,
                    installation,
                    updated_catalog,
                    helper.read_runtime_source_policy(),
                    previous_catalog_generation=previous_generation,
                )
                self._verify_package_activity_generation(updated_catalog["generation"])
            except Exception as error:
                transaction["phase"] = "product_environment_unknown"
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "PRODUCT_ENVIRONMENT_UNKNOWN",
                    "The signed Product source generation could not be projected and read back; maintenance remains held.",
                    retryable=True,
                ) from error
            transaction["productEnvironmentChanged"] = bool(environment_result.changed)
            transaction["productEnvironmentGeneration"] = updated_catalog["generation"]
            transaction["phase"] = "product_environment_projected"
            _atomic_json(transaction_path, transaction)

            transaction["phase"] = "runtime_start_pending"
            _atomic_json(transaction_path, transaction)
            try:
                self._run_systemctl("start", "cyrene-package-runtime.service")
                self._wait_unit_active("cyrene-package-runtime.service")
                runtime_authority = helper.probe_runtime_authority(
                    updated_catalog,
                    expected_catalog_generation=updated_catalog["generation"],
                )
            except Exception as error:
                transaction["phase"] = "runtime_health_unknown"
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "PACKAGE_RUNTIME_HEALTH_UNKNOWN",
                    "Package Runtime did not prove the installed source generation and admission capability; maintenance remains held.",
                    retryable=True,
                ) from error
            transaction["runtimeAuthority"] = runtime_authority
            transaction["phase"] = "runtime_health_verified"
            _atomic_json(transaction_path, transaction)

            try:
                self._restore_package_product_activity(
                    first_products,
                    product_units,
                    verified_products,
                    prior_active_products,
                )
            except Exception as error:
                transaction["phase"] = "product_health_pending"
                transaction["recoveryError"] = "Previously active Product health is pending."
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "PRODUCT_RESTORE_PENDING",
                    "Previously active Product clients did not pass signed health checks; maintenance remains held.",
                    retryable=True,
                ) from error
            transaction["phase"] = "products_restored"
            _atomic_json(transaction_path, transaction)

            validate_id = f"cyrene-package-validate-{uuid.uuid4().hex}"
            validation = self._broker_request(
                "ValidateMaintenanceHold",
                {
                    "request_id": validate_id,
                    "maintenance_token": maintenance_token,
                    "target_kind": "PACKAGE_ONLY",
                    "plan_id": plan.plan_id,
                    "plan_digest": plan.plan_digest,
                    "component_artifact_digests": plan.component_artifact_digests,
                    "component_id": verified.package_id,
                    "artifact_digest": verified.artifact_digest,
                    "expected_gate_generation": begin_gate_generation,
                    "expected_catalog_generation": updated_catalog["generation"],
                },
                request_id=validate_id,
            )
            expected_validation = {
                "valid": True,
                "request_id": validate_id,
                "target_kind": "PACKAGE_ONLY",
                "plan_id": plan.plan_id,
                "plan_digest": plan.plan_digest,
                "component_artifact_digests": plan.component_artifact_digests,
                "component_id": verified.package_id,
                "artifact_digest": verified.artifact_digest,
                "gate_generation": begin_gate_generation,
                "catalog_generation": updated_catalog["generation"],
            }
            if validation != expected_validation:
                transaction["phase"] = "hold_validation_unknown"
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Package Runtime hold changed before completion; maintenance remains held.",
                    retryable=True,
                )
            transaction["phase"] = "end_pending"
            _atomic_json(transaction_path, transaction)
            try:
                self._end_maintenance(transaction, outcome="SUCCESS", healthy=True)
            except UpdateError:
                # An End reply may be lost after the broker released admission.
                # Recover only from a fresh, exact READY response for this catalog.
                try:
                    ended_readiness = self._readiness_for(
                        "PACKAGE_ONLY", requires_restart=False, force=True
                    )
                    if (
                        ended_readiness.get("status") != "READY"
                        or ended_readiness.get("install_catalog_generation")
                        != updated_catalog["generation"]
                        or ended_readiness.get("unknown_activity_sources") != []
                    ):
                        raise UpdateError(
                            "GATE_UNKNOWN", "Package Runtime End outcome is not established."
                        )
                except Exception as error:
                    transaction["phase"] = "end_unknown"
                    _atomic_json(transaction_path, transaction)
                    raise UpdateError(
                        "GATE_UNKNOWN",
                        "Package Runtime End outcome is unknown; Product restore remains pending.",
                        retryable=True,
                    ) from error
            transaction["phase"] = "clients_restore_pending"
            _atomic_json(transaction_path, transaction)
            try:
                # Recheck the exact prior-active set after End; recovery here is
                # restore-only and never reacquires the gate or reinstalls bytes.
                self._restore_package_product_activity(
                    first_products,
                    product_units,
                    verified_products,
                    prior_active_products,
                )
            except Exception as error:
                transaction["phase"] = "clients_restore_pending"
                transaction["recoveryError"] = "Previously active Product restore is pending."
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "PRODUCT_RESTORE_PENDING",
                    "Previously active Product clients remain pending restoration; package state is committed.",
                    retryable=True,
                ) from error
            transaction["phase"] = "succeeded"
            transaction.pop("maintenanceToken", None)
            transaction.pop("recoveryError", None)
            _atomic_json(transaction_path, transaction)
            return {
                "status": "installed",
                "planId": plan.plan_id,
                "planDigest": plan.plan_digest,
                "installation": installation,
                "catalogGeneration": updated_catalog["generation"],
                "policyDigest": transaction["policyDigest"],
                "runtimeActivated": False,
            }

    def _resume_package_bootstrap_clients(
        self,
        helper: Any,
        transaction_path: Path,
        *,
        plan_id: str,
        plan_digest: Any,
        confirmation: Any,
    ) -> dict[str, Any]:
        """Resume only the confirmed client-health/End tail of a package plan.

        中文：恢复阶段仅修复客户端健康或结束维护，不重装包、不重新 Begin。
        """

        try:
            info = transaction_path.lstat()
        except OSError as error:
            raise UpdateError(
                "INVALID_LOCAL_STATE", "Package Runtime journal is unavailable."
            ) from error
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_uid != os.geteuid()
            or stat.S_IMODE(info.st_mode) != 0o600
            or info.st_nlink != 1
        ):
            raise UpdateError("UNSAFE_STATE", "Package Runtime journal metadata is unsafe.")
        transaction = _read_object(transaction_path, "Package Runtime transaction journal")
        phase = transaction.get("phase")
        if (
            transaction.get("schemaVersion") != 1
            or transaction.get("transactionKind") != "package-runtime-bootstrap.v1"
            or transaction.get("planId") != plan_id
            or transaction.get("planDigest") != plan_digest
            or transaction.get("requestId") != f"cyrene-update-{plan_id}"
            or transaction.get("targetKind") != "PACKAGE_ONLY"
            or phase
            not in {
                "product_health_pending",
                "products_restored",
                "end_pending",
                "end_unknown",
                "clients_restore_pending",
                "succeeded",
            }
        ):
            raise UpdateError(
                "PENDING_MAINTENANCE",
                "Package Runtime journal is unknown or belongs to another operation.",
                retryable=True,
            )
        verified = helper.verify_cached_package_candidate()
        activity_catalog, activity_sources = self._activity_catalog()
        first_products, product_units, verified_products = self._package_bootstrap_product_units(
            activity_catalog, helper
        )
        if transaction.get("productCohort") != product_units:
            raise UpdateError(
                "PRODUCT_COHORT_UNKNOWN",
                "The signed Product source or unit set differs from the pending plan.",
                retryable=True,
            )
        prior_active = transaction.get("priorActiveProducts")
        cohort_by_source = {row["source_id"]: row["unit"] for row in product_units}
        if (
            not isinstance(prior_active, list)
            or any(
                not isinstance(item, dict)
                or set(item) != {"source_id", "unit"}
                or not isinstance(item.get("source_id"), str)
                or cohort_by_source.get(item.get("source_id")) != item.get("unit")
                for item in prior_active
            )
            or len({item["source_id"] for item in prior_active}) != len(prior_active)
        ):
            raise UpdateError(
                "PRODUCT_STATE_UNKNOWN", "Pending journal has an invalid prior-active Product set."
            )
        try:
            plan = helper.build_package_bootstrap_plan(
                verified,
                catalog_generation=transaction["plannedCatalogGeneration"],
                gate_generation=transaction["plannedGateGeneration"],
                affected_product_units=product_units,
            )
            helper.validate_package_bootstrap_confirmation(
                plan,
                {
                    "plan_id": plan_id,
                    "plan_digest": plan_digest,
                    "confirmed": confirmation is True,
                },
            )
        except Exception as error:
            raise UpdateError(
                "CONFIRMATION_MISMATCH", "Pending Package Runtime plan identity is not valid."
            ) from error
        if (
            plan.plan_id != plan_id
            or plan.plan_digest != plan_digest
            or transaction.get("componentArtifactDigests") != plan.component_artifact_digests
            or transaction.get("candidate", {}).get("attestationBundleDigests")
            != verified.attestation_bundle_digests
            or {
                key: value
                for key, value in transaction.get("candidate", {}).items()
                if key != "attestationBundleDigests"
            }
            != plan.material
        ):
            raise UpdateError(
                "PLAN_CHANGED", "Pending Package Runtime candidate differs from its journal."
            )
        if phase == "succeeded":
            try:
                installation = helper.validate_installation_record(
                    verified, transaction.get("installation")
                )
            except Exception as error:
                raise UpdateError(
                    "TRANSACTION_IDENTITY_UNKNOWN",
                    "Completed Package Runtime installation evidence is invalid.",
                ) from error
            return {
                "status": "installed",
                "planId": plan.plan_id,
                "planDigest": plan.plan_digest,
                "installation": installation,
                "catalogGeneration": transaction.get("catalogGeneration"),
                "policyDigest": transaction.get("policyDigest"),
                "runtimeActivated": False,
            }
        if activity_catalog.get("generation") != transaction.get(
            "expectedCatalogGeneration"
        ) or activity_sources != transaction.get("expectedActivitySources"):
            raise UpdateError(
                "GATE_UNKNOWN",
                "Activity catalog differs from the pending Package Runtime transaction.",
                retryable=True,
            )
        try:
            self._verify_package_activity_generation(activity_catalog["generation"])
            installation = helper.validate_installation_record(
                verified, transaction.get("installation")
            )
            policy = helper.read_runtime_source_policy()
            helper.validate_runtime_source_policy(policy, verified, installation, activity_catalog)
            runtime_authority = helper.probe_runtime_authority(
                activity_catalog, expected_catalog_generation=activity_catalog["generation"]
            )
        except Exception as error:
            raise UpdateError(
                "PACKAGE_RUNTIME_HEALTH_UNKNOWN",
                "Package Runtime source authority is not verified for the pending transaction.",
                retryable=True,
            ) from error

        if phase in {"product_health_pending", "products_restored"}:
            try:
                self._restore_package_product_activity(
                    first_products,
                    product_units,
                    verified_products,
                    transaction["priorActiveProducts"],
                )
            except Exception as error:
                transaction["phase"] = "product_health_pending"
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "PRODUCT_RESTORE_PENDING",
                    "Previously active Product clients remain pending restoration.",
                    retryable=True,
                ) from error
            transaction["phase"] = "products_restored"
            transaction["runtimeAuthority"] = runtime_authority
            _atomic_json(transaction_path, transaction)

        readiness = self._readiness_for("PACKAGE_ONLY", requires_restart=False, force=True)
        if (
            readiness.get("install_catalog_generation") != activity_catalog["generation"]
            or readiness.get("unknown_activity_sources") != []
        ):
            raise UpdateError(
                "GATE_UNKNOWN",
                "Package Runtime gate state is not known for recovery.",
                retryable=True,
            )
        if readiness.get("status") == "MAINTENANCE_ACTIVE":
            validate_id = f"cyrene-package-resume-validate-{uuid.uuid4().hex}"
            validation = self._broker_request(
                "ValidateMaintenanceHold",
                {
                    "request_id": validate_id,
                    "maintenance_token": transaction.get("maintenanceToken"),
                    "target_kind": "PACKAGE_ONLY",
                    "plan_id": plan.plan_id,
                    "plan_digest": plan.plan_digest,
                    "component_artifact_digests": plan.component_artifact_digests,
                    "component_id": verified.package_id,
                    "artifact_digest": verified.artifact_digest,
                    "expected_gate_generation": transaction.get("expectedGateGeneration"),
                    "expected_catalog_generation": activity_catalog["generation"],
                },
                request_id=validate_id,
            )
            expected = {
                "valid": True,
                "request_id": validate_id,
                "target_kind": "PACKAGE_ONLY",
                "plan_id": plan.plan_id,
                "plan_digest": plan.plan_digest,
                "component_artifact_digests": plan.component_artifact_digests,
                "component_id": verified.package_id,
                "artifact_digest": verified.artifact_digest,
                "gate_generation": transaction.get("expectedGateGeneration"),
                "catalog_generation": activity_catalog["generation"],
            }
            if validation != expected:
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Pending Package Runtime hold identity is unknown.",
                    retryable=True,
                )
            transaction["phase"] = "end_pending"
            _atomic_json(transaction_path, transaction)
            self._end_maintenance(transaction, outcome="SUCCESS", healthy=True)
        elif readiness.get("status") != "READY":
            raise UpdateError(
                "GATE_UNKNOWN", "Package Runtime End outcome is unknown.", retryable=True
            )

        transaction["phase"] = "clients_restore_pending"
        _atomic_json(transaction_path, transaction)
        try:
            self._restore_package_product_activity(
                first_products,
                product_units,
                verified_products,
                transaction["priorActiveProducts"],
            )
        except Exception as error:
            transaction["recoveryError"] = "Previously active Product restore is pending."
            _atomic_json(transaction_path, transaction)
            raise UpdateError(
                "PRODUCT_RESTORE_PENDING",
                "Package Runtime is committed; only prior-active Product restoration remains.",
                retryable=True,
            ) from error
        transaction["phase"] = "succeeded"
        transaction.pop("maintenanceToken", None)
        transaction.pop("recoveryError", None)
        _atomic_json(transaction_path, transaction)
        return {
            "status": "installed",
            "planId": plan.plan_id,
            "planDigest": plan.plan_digest,
            "installation": installation,
            "catalogGeneration": activity_catalog["generation"],
            "policyDigest": transaction.get("policyDigest"),
            "runtimeActivated": False,
        }

    def _activity_catalog(self) -> tuple[dict[str, Any], list[str]]:
        catalog = _read_object(self.activity_catalog_path, "runtime activity source catalog")
        if (
            set(catalog) != {"schema_version", "generation", "sources"}
            or type(catalog.get("schema_version")) is not int
            or catalog["schema_version"] != 1
            or not isinstance(catalog.get("generation"), int)
            or isinstance(catalog.get("generation"), bool)
            or catalog["generation"] < 1
        ):
            raise UpdateError(
                "GATE_UNKNOWN",
                "Runtime activity source catalog has an invalid schema or generation.",
                retryable=True,
            )
        sources = catalog.get("sources")
        if not isinstance(sources, list):
            raise UpdateError(
                "GATE_UNKNOWN",
                "Runtime activity source catalog has no sources array; the updater will not assume the runtime is idle.",
                retryable=True,
            )
        ids: list[str] = []
        for source in sources:
            if not isinstance(source, dict) or set(source) not in (
                {"source_id", "uid", "gid", "source_token_sha256"},
                {"source_id", "uid", "gid", "source_token_sha256", "binding_scopes"},
            ):
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Runtime activity source catalog contains an invalid source record.",
                    retryable=True,
                )
            source_id = source["source_id"]
            if (
                not isinstance(source_id, str)
                or re.fullmatch(r"[a-z0-9._-]{1,160}", source_id) is None
            ):
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Runtime activity source catalog contains an invalid source ID.",
                    retryable=True,
                )
            if (
                not isinstance(source["uid"], int)
                or isinstance(source["uid"], bool)
                or not isinstance(source["gid"], int)
                or isinstance(source["gid"], bool)
                or not isinstance(source["source_token_sha256"], str)
                or re.fullmatch(r"[0-9a-f]{64}", source["source_token_sha256"]) is None
            ):
                raise UpdateError(
                    "GATE_UNKNOWN",
                    f"Runtime activity source {source_id} has invalid trust metadata.",
                    retryable=True,
                )
            self._validate_activity_binding_scopes(source)
            ids.append(source_id)
        if len(set(ids)) != len(ids) or ids != sorted(ids):
            raise UpdateError(
                "GATE_UNKNOWN",
                "Runtime activity source IDs must be unique and sorted.",
                retryable=True,
            )
        return catalog, ids

    @staticmethod
    def _validate_activity_binding_scopes(source: dict[str, Any]) -> None:
        """Validate optional mutation scopes; absence and empty lists deny by default."""

        if "binding_scopes" not in source:
            return
        scopes = source["binding_scopes"]
        if not isinstance(scopes, list):
            raise UpdateError(
                "GATE_UNKNOWN",
                "Runtime activity binding scopes must be a JSON array.",
                retryable=True,
            )
        binding_ids: list[str] = []
        for scope in scopes:
            if not isinstance(scope, dict) or set(scope) != {
                "binding_id",
                "package_id",
                "installation_ids",
                "operations",
            }:
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Runtime activity catalog contains a malformed binding scope.",
                    retryable=True,
                )
            binding_id = scope["binding_id"]
            package_id = scope["package_id"]
            installation_ids = scope["installation_ids"]
            operations = scope["operations"]
            if (
                not isinstance(binding_id, str)
                or ACTIVITY_SCOPE_ID_PATTERN.fullmatch(binding_id) is None
                or not isinstance(package_id, str)
                or ACTIVITY_SCOPE_ID_PATTERN.fullmatch(package_id) is None
                or not isinstance(installation_ids, list)
                or not installation_ids
                or any(
                    not isinstance(installation_id, str)
                    or ACTIVITY_INSTALLATION_ID_PATTERN.fullmatch(installation_id) is None
                    for installation_id in installation_ids
                )
                or installation_ids != sorted(set(installation_ids))
                or not isinstance(operations, list)
                or any(
                    not isinstance(operation, str) or operation not in ACTIVITY_BINDING_OPERATIONS
                    for operation in operations
                )
                or operations != sorted(set(operations))
            ):
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Runtime activity catalog contains invalid binding scope fields.",
                    retryable=True,
                )
            binding_ids.append(binding_id)
        if binding_ids != sorted(set(binding_ids)):
            raise UpdateError(
                "GATE_UNKNOWN",
                "Runtime activity binding IDs must be unique and sorted.",
                retryable=True,
            )

    def _broker_request(
        self, method: str, params: dict[str, Any], *, request_id: str | None = None
    ) -> dict[str, Any]:
        catalog: dict[str, Any] | None = None
        sources: list[str] = []
        if method in {"GetUpdateReadiness", "BeginMaintenance"}:
            catalog, sources = self._activity_catalog()
        broker_path = self._resolve_broker_executable()
        if not broker_path.is_file() or not os.access(broker_path, os.X_OK):
            raise UpdateError(
                "GATE_UNKNOWN",
                "The native runtime maintenance broker is unavailable; apply is fail-closed.",
                retryable=True,
            )
        request_id = request_id or "cyrene-update-" + uuid.uuid4().hex
        request_params = dict(params)
        if catalog is not None:
            request_params.setdefault("expected_catalog_generation", catalog["generation"])
            request_params.setdefault("expected_activity_sources", sources)
        payload = {
            "request_id": request_id,
            "method": method,
            "auth": {},
            "params": {
                **request_params,
            },
        }
        try:
            command = [str(broker_path), "request", "--socket", str(self.socket_path)]
            if method != "Health":
                command.append("--operator")
            completed = self.runner(
                command,
                input=json.dumps(payload, separators=(",", ":")) + "\n",
                capture_output=True,
                text=True,
                timeout=20,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired) as error:
            raise UpdateError(
                "GATE_UNKNOWN", f"Cannot reach runtime maintenance broker: {error}", retryable=True
            ) from error
        if completed.returncode != 0:
            detail = (
                completed.stderr.strip()
                or completed.stdout.strip()
                or f"exit {completed.returncode}"
            )
            raise UpdateError(
                "GATE_UNKNOWN",
                f"Runtime maintenance broker rejected the request: {detail}",
                retryable=True,
            )
        lines = completed.stdout.splitlines()
        if len(lines) != 1:
            raise UpdateError(
                "GATE_UNKNOWN",
                "Runtime maintenance broker returned an invalid JSONL response.",
                retryable=True,
            )
        try:
            response = json.loads(lines[0])
        except json.JSONDecodeError as error:
            raise UpdateError(
                "GATE_UNKNOWN",
                "Runtime maintenance broker returned malformed JSON.",
                retryable=True,
            ) from error
        if not isinstance(response, dict) or response.get("request_id") != request_id:
            raise UpdateError(
                "GATE_UNKNOWN",
                "Runtime maintenance broker response identity did not match.",
                retryable=True,
            )
        if "error" in response:
            detail = response["error"]
            code = (
                detail.get("code", "GATE_UNKNOWN") if isinstance(detail, dict) else "GATE_UNKNOWN"
            )
            message = (
                detail.get("message", "Runtime readiness is unknown.")
                if isinstance(detail, dict)
                else "Runtime readiness is unknown."
            )
            refusal_codes = {
                "ACTIVE_TASKS",
                "IDLE_RUNTIME_REQUIRES_UNLOAD",
                "MAINTENANCE_ACTIVE",
                "UNKNOWN",
                "STALE_READINESS",
                "CATALOG_GENERATION_MISMATCH",
                "GATE_GENERATION_MISMATCH",
                "USER_CONFIRMATION_REQUIRED",
                "REQUEST_ID_PLAN_MISMATCH",
                "INVALID_REQUEST",
                "INVALID_ARGUMENT",
                "UNAUTHORIZED",
            }
            raise UpdateError(
                str(code),
                str(message),
                retryable=True,
                maintenance_not_acquired=method == "BeginMaintenance"
                and str(code) in refusal_codes,
            )
        result = response.get("result")
        if not isinstance(result, dict):
            raise UpdateError(
                "GATE_UNKNOWN",
                "Runtime maintenance broker response has no result object.",
                retryable=True,
            )
        return result

    def _resolve_broker_executable(self) -> Path:
        """Resolve an explicit test override or the exact active signed Broker."""

        if self.broker_path is not None:
            return self.broker_path
        return self._resolve_installed_broker()

    def _resolve_installed_broker(self) -> Path:
        """Resolve the default Broker only through its verified active release.

        An ordinary verified release receipt is authoritative. The private completed
        first-install journal is a constrained fallback for installations that predate
        release receipts; it never authorizes an unsigned alias.
        中文：默认 Broker 仅来自已验证的活动签名发布目录；无收据时才核验首次安装日志。
        """

        component_id = BROKER_COMPONENT_ID
        component = self.components.get(component_id)
        if (
            not isinstance(component, dict)
            or component.get("componentId") != component_id
            or component.get("kind") != "native-binary"
            or not self.bootstrap_catalog_authorized
        ):
            raise UpdateError(
                "GATE_UNKNOWN",
                "The trusted component catalog does not contain the runtime maintenance broker.",
                retryable=True,
            )

        installed = self._installed(component)
        manifest = installed.get("manifest")
        if (
            installed.get("active") is not True
            or not isinstance(manifest, dict)
            or manifest.get("componentId") != component_id
            or manifest.get("manifestDigest") != installed.get("manifestDigest")
            or manifest.get("version") != installed.get("activeVersion")
            or _artifact_kind_from_manifest(manifest) != "native-binary"
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                "The active runtime maintenance broker has no matching verified release identity.",
                retryable=True,
            )

        artifact = manifest.get("artifact")
        files = artifact.get("files") if isinstance(artifact, dict) else None
        entrypoint = artifact.get("entrypoint") if isinstance(artifact, dict) else None
        if not isinstance(files, dict) or not isinstance(entrypoint, str):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                "The active broker manifest has no trusted entrypoint or file map.",
            )
        relative_entrypoint = _safe_relative(entrypoint, field="broker.artifact.entrypoint")
        expected_entrypoint_digest = files.get(relative_entrypoint.as_posix())
        if not _valid_digest(expected_entrypoint_digest):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                "The active broker entrypoint has no pinned file digest.",
            )

        try:
            executable_files = _native_executable_files(artifact)
            if relative_entrypoint.as_posix() not in executable_files:
                raise ValueError("entrypoint is not signed executable content")

            component_root = self.install_root / "components" / component_id
            active = component_root / "active"
            active_info = active.lstat()
            if not stat.S_ISLNK(active_info.st_mode) or active_info.st_uid != 0:
                raise ValueError("active pointer is not a root-owned symlink")
            pointer_target = os.readlink(active)
            match = re.fullmatch(r"releases/([^/]+)", pointer_target)
            pointer_identity = installed.get("pointerIdentity")
            if (
                match is None
                or not isinstance(pointer_identity, str)
                or match.group(1) != pointer_identity
            ):
                raise ValueError("active pointer differs from the verified receipt")

            release = component_root / pointer_target
            self._verify_broker_directory_chain(release, relative_paths=[relative_entrypoint])
            manifest_path = release / "component-manifest.json"
            manifest_info = manifest_path.lstat()
            if (
                manifest_path.is_symlink()
                or not stat.S_ISREG(manifest_info.st_mode)
                or manifest_info.st_uid != 0
                or manifest_info.st_nlink != 1
                or stat.S_IMODE(manifest_info.st_mode) & 0o022
                or json.loads(manifest_path.read_text(encoding="utf-8")) != manifest
            ):
                raise ValueError("installed manifest differs from the verified release identity")

            # Every signed payload path and digest remains part of the active identity check.
            for relative_name, expected_digest in files.items():
                relative = _safe_relative(relative_name, field="artifact.files path")
                if not _valid_digest(expected_digest):
                    raise ValueError(f"signed file digest is invalid: {relative_name}")
                self._verify_broker_directory_chain(release, relative_paths=[relative])
                payload_file = release.joinpath(*relative.parts)
                file_info = payload_file.lstat()
                if (
                    payload_file.is_symlink()
                    or not stat.S_ISREG(file_info.st_mode)
                    or file_info.st_uid != 0
                    or file_info.st_nlink != 1
                    or stat.S_IMODE(file_info.st_mode) & 0o022
                    or _file_digest(payload_file) != expected_digest
                    or (
                        relative.as_posix() in executable_files
                        and not stat.S_IMODE(file_info.st_mode) & 0o111
                    )
                ):
                    raise ValueError(
                        f"active Broker payload differs from its signed map: {relative_name}"
                    )

            if installed.get("identityAttested") is not True:
                # New receipts bind the release directly; legacy installations need the
                # exact first-install journal as an additional identity source.
                self._verify_broker_bootstrap_journal(manifest, installed, pointer_target)
        except UpdateError:
            raise
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, ValueError) as error:
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"The active maintenance broker failed install verification: {error}",
                retryable=True,
            ) from error
        return release.joinpath(*relative_entrypoint.parts)

    def _verify_broker_directory_chain(
        self, release: Path, *, relative_paths: list[PurePosixPath]
    ) -> None:
        """Require real root-owned, non-writable install directories and payload parents."""

        component_root = self.install_root / "components" / BROKER_COMPONENT_ID
        directories = [
            self.install_root,
            self.install_root / "components",
            component_root,
            component_root / "releases",
            release,
        ]
        for relative in relative_paths:
            current = release
            for part in relative.parts[:-1]:
                current /= part
                directories.append(current)
        if self.install_root == DEFAULT_INSTALL_ROOT:
            directories = [Path("/"), Path("/usr"), Path("/usr/lib"), *directories]
        for directory in dict.fromkeys(directories):
            info = directory.lstat()
            if (
                not stat.S_ISDIR(info.st_mode)
                or directory.is_symlink()
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) & 0o022
                or not stat.S_IMODE(info.st_mode) & 0o001
            ):
                raise ValueError(f"active broker directory is not root-controlled: {directory}")

    def _verify_broker_bootstrap_journal(
        self, manifest: dict[str, Any], installed: dict[str, Any], pointer: str
    ) -> None:
        """Use the exact completed first-install journal only when no receipt exists."""

        journal_path = self.state_root / BROKER_BOOTSTRAP_JOURNAL
        journal_dir = journal_path.parent
        # Public state ancestors allow normal root-owned 0755 paths; private state stays 0700.
        for directory in list(self.state_root.parents)[:3]:
            info = directory.lstat()
            if (
                not stat.S_ISDIR(info.st_mode)
                or directory.is_symlink()
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) & 0o022
            ):
                raise ValueError("first-install journal ancestor is not root-controlled")
        for directory in (self.state_root, journal_dir):
            info = directory.lstat()
            if (
                not stat.S_ISDIR(info.st_mode)
                or directory.is_symlink()
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) & 0o077
            ):
                raise ValueError("first-install journal directory is not private and root-owned")
        info = journal_path.lstat()
        if (
            not stat.S_ISREG(info.st_mode)
            or journal_path.is_symlink()
            or info.st_uid != 0
            or info.st_nlink != 1
            or stat.S_IMODE(info.st_mode) & 0o077
        ):
            raise ValueError("first-install journal is not a private root-owned file")

        journal = _read_object(journal_path, "maintenance broker first-install journal")
        identity = journal.get("identity")
        artifact = manifest.get("artifact")
        release_identity = pointer.removeprefix("releases/")
        if (
            journal.get("schemaVersion") != 1
            or journal.get("phase") != "complete"
            or re.fullmatch(r"[0-9a-f]{64}", str(journal.get("planDigest"))) is None
            or journal.get("releaseIdentity") != release_identity
            or not isinstance(identity, dict)
            or identity.get("componentId") != BROKER_COMPONENT_ID
            or identity.get("version") != manifest.get("version")
            or identity.get("manifestDigest") != manifest.get("manifestDigest")
            or identity.get("artifactDigest") != artifact.get("sha256")
            or installed.get("artifactDigest") != identity.get("artifactDigest")
            or not any(
                target.get("id") == identity.get("targetId")
                and target.get("target") == manifest.get("target")
                for target in self.targets.values()
            )
            or not _valid_digest(identity.get("indexDigest"))
        ):
            raise ValueError("first-install journal does not bind the active broker receipt")

    def _readiness(self, component: dict[str, Any]) -> dict[str, Any]:
        target_kind = (
            "CORE_RUNTIME"
            if component.get("restart", {}).get("group") == "core-runtime"
            else "PACKAGE_ONLY"
        )
        return self._readiness_for(target_kind, requires_restart=True)

    def _readiness_for(
        self, target_kind: str, *, requires_restart: bool, force: bool = False
    ) -> dict[str, Any]:
        key = (target_kind, requires_restart)
        if not force and key in self._readiness_cache:
            return self._readiness_cache[key]
        try:
            activity_catalog, activity_sources = self._activity_catalog()
            result = self._broker_request(
                "GetUpdateReadiness",
                {
                    "target_kind": target_kind,
                    "requires_restart": requires_restart,
                    "expected_catalog_generation": activity_catalog["generation"],
                    "expected_activity_sources": activity_sources,
                },
            )
            if result.get("install_catalog_generation") != activity_catalog["generation"]:
                result = {
                    **result,
                    "status": "UNKNOWN",
                    "blocker_codes": [*result.get("blocker_codes", []), "ACTIVITY_CATALOG_CHANGED"],
                    "message": "Installed activity catalog changed during readiness.",
                }
        except UpdateError as error:
            result = {
                "status": "UNKNOWN",
                "gate_generation": None,
                "install_catalog_generation": None,
                "active_task_count": None,
                "active_tasks": [],
                "unknown_activity_sources": [],
                "active_worker_count": None,
                "active_allocation_count": None,
                "blocker_codes": [error.code],
                "requires_restart_confirmation": requires_restart,
                "message": str(error),
            }
        self._readiness_cache[key] = result
        return result

    @staticmethod
    def _public_gate(readiness: dict[str, Any]) -> dict[str, Any]:
        state_map = {
            "READY": "idle",
            "ACTIVE_TASKS": "busy",
            "UNKNOWN": "unknown",
            "IDLE_RUNTIME_REQUIRES_UNLOAD": "idle_runtime_requires_unload",
            "MAINTENANCE_ACTIVE": "maintenance_active",
        }
        blockers = [
            {"code": str(code), "message": str(code).replace("_", " ").lower()}
            for code in readiness.get("blocker_codes", [])
        ]
        if readiness.get("message"):
            blockers.append({"code": "BROKER_UNAVAILABLE", "message": readiness["message"]})
        result = {
            "state": state_map.get(readiness.get("status"), "unknown"),
            "gateGeneration": readiness.get("gate_generation"),
            "installCatalogGeneration": readiness.get("install_catalog_generation"),
            "activeTaskCount": readiness.get("active_task_count"),
            "activeTasks": [
                {
                    "sourceId": item.get("source_id", "unknown"),
                    "taskId": item.get("task_id", "unknown"),
                    "state": item.get("state", "unknown"),
                }
                for item in readiness.get("active_tasks", [])
                if isinstance(item, dict)
            ],
            "activeWorkerCount": readiness.get("active_worker_count"),
            "activeAllocationCount": readiness.get("active_allocation_count"),
            "inflightRuntimeAdmissionCount": readiness.get("inflight_runtime_admission_count"),
            "unknownActivitySources": readiness.get("unknown_activity_sources", []),
            "blockerCodes": readiness.get("blocker_codes", []),
            "requiresRestartConfirmation": bool(
                readiness.get("requires_restart_confirmation", False)
            ),
            "blockers": blockers,
        }
        return {key: value for key, value in result.items() if value is not None}

    @staticmethod
    def _require_ready(readiness: dict[str, Any], target_kind: str) -> None:
        status = readiness.get("status")
        if status == "READY":
            numeric_fields = (
                "gate_generation",
                "install_catalog_generation",
                "active_task_count",
                "active_worker_count",
                "active_allocation_count",
                "inflight_runtime_admission_count",
            )
            if any(
                not isinstance(readiness.get(field), int)
                or isinstance(readiness.get(field), bool)
                or readiness[field] < 0
                for field in numeric_fields
            ):
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Runtime readiness omitted valid counters or generations; apply is refused.",
                    retryable=True,
                )
            active = readiness.get("active_tasks")
            if not isinstance(active, list):
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Runtime readiness omitted the active task list; apply is refused.",
                    retryable=True,
                )
            if active or readiness["active_task_count"] != 0:
                raise UpdateError(
                    "ACTIVE_TASKS",
                    "Update refused while Product tasks are active. Finish or stop tasks in their owning Product service; Cyrene will not cancel or drain them.",
                )
            unknown_sources = readiness.get("unknown_activity_sources")
            if not isinstance(unknown_sources, list) or unknown_sources:
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Runtime activity sources are unknown; apply is refused.",
                    retryable=True,
                )
            if readiness["inflight_runtime_admission_count"] != 0:
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Runtime task admission is still in flight; wait for it to settle and check again.",
                    retryable=True,
                )
            if target_kind == "CORE_RUNTIME" and (
                readiness["active_worker_count"] != 0 or readiness["active_allocation_count"] != 0
            ):
                raise UpdateError(
                    "IDLE_RUNTIME_REQUIRES_UNLOAD",
                    "Runtime workers or allocations are still held. Unload the model from its Product, release workers/leases/allocations, then check again; the updater will not terminate them.",
                )
            if not isinstance(readiness.get("requires_restart_confirmation"), bool):
                raise UpdateError(
                    "GATE_UNKNOWN",
                    "Runtime readiness omitted the restart confirmation state; apply is refused.",
                    retryable=True,
                )
            return
        if status == "ACTIVE_TASKS":
            active = readiness.get("active_tasks", [])
            task_names = (
                ", ".join(
                    f"{item.get('source_id', 'unknown')}:{item.get('task_id', 'unknown')} ({item.get('state', 'active')})"
                    for item in active
                    if isinstance(item, dict)
                )
                or "active Product tasks"
            )
            raise UpdateError(
                "ACTIVE_TASKS",
                f"Update refused while {task_names} are active. Finish or stop tasks in their owning Product service; Cyrene will not cancel or drain them.",
            )
        if status == "IDLE_RUNTIME_REQUIRES_UNLOAD":
            raise UpdateError(
                "IDLE_RUNTIME_REQUIRES_UNLOAD",
                "Runtime workers or allocations are still held. Unload the model from its Product, release workers/leases/allocations, then check again; the updater will not terminate them.",
            )
        if status == "MAINTENANCE_ACTIVE":
            raise UpdateError(
                "MAINTENANCE_ACTIVE",
                "Another maintenance transaction already owns the update gate.",
                retryable=True,
            )
        raise UpdateError(
            "GATE_UNKNOWN",
            f"Runtime maintenance readiness is unknown ({target_kind}); apply is refused.",
            retryable=True,
        )

    def _channel_releases(
        self,
        publisher: dict[str, Any],
        channel: str,
        component: dict[str, Any],
        target: dict[str, Any],
        *,
        release_id: str | None = None,
    ) -> tuple[dict[str, Any], str, tuple[dict[str, Any], ...], str]:
        component_prefix = self._component_release_tag_prefix(component, channel)
        key = (
            publisher["repository"],
            channel,
            component["componentId"],
            target["id"],
            release_id or "latest",
        )
        if key in self._index_cache:
            return self._index_cache[key]
        releases_uri = publisher["releaseDiscovery"]["apiUri"]
        expected_api_uri = (
            f"https://api.github.com/repos/{publisher['repository']}/releases?per_page=100"
        )
        if releases_uri != expected_api_uri:
            raise UpdateError(
                "INVALID_CATALOG",
                f"Release discovery URL is not the fixed API for {publisher['repository']}.",
            )
        channel_cfg = self.catalog["channels"][channel]
        expected_prerelease = channel_cfg["releasePrerelease"]
        candidate_releases: list[dict[str, Any]] = []
        if release_id is not None:
            if (
                not isinstance(release_id, str)
                or not release_id
                or len(release_id) > 256
                or "/" in release_id
                or ".." in release_id
                or (component_prefix is not None and not release_id.startswith(component_prefix))
            ):
                raise UpdateError("UNTRUSTED_RELEASE_TAG", "Peer release tag is invalid.")
            exact_uri = (
                f"https://api.github.com/repos/{publisher['repository']}/releases/tags/"
                f"{urllib.parse.quote(release_id, safe='')}"
            )
            if releases_uri != expected_api_uri:
                raise UpdateError("INVALID_CATALOG", "Release discovery URL is not pinned.")
            candidate_release = self._get_json(exact_uri)
            if (
                isinstance(candidate_release, dict)
                and candidate_release.get("tag_name") == release_id
                and candidate_release.get("draft") is False
                and candidate_release.get("prerelease") is expected_prerelease
            ):
                candidate_releases.append(candidate_release)
        else:
            tag_format = publisher.get("tagFormat", "source-sha")
            if tag_format == "source-sha":
                release_prefix = component_prefix or f"{channel}-"
            elif tag_format in {"component-source-sha", "component-version-source-sha"}:
                release_prefix = f"{channel}-{component['componentId']}-"
                if component_prefix not in {None, release_prefix}:
                    raise UpdateError(
                        "INVALID_CATALOG",
                        "The component release prefix differs from the publisher tag format.",
                    )
            else:
                raise UpdateError(
                    "INVALID_CATALOG", f"Unsupported publisher tag format {tag_format!r}."
                )
            seen_release_tags: set[str] = set()
            for page in range(1, 101):
                page_uri = releases_uri if page == 1 else f"{releases_uri}&page={page}"
                releases = self._release_list_page(publisher["repository"], channel, page_uri)
                for item in releases:
                    tag_name = item.get("tag_name") if isinstance(item, dict) else None
                    if (
                        isinstance(item, dict)
                        and item.get("draft") is False
                        and item.get("prerelease") is expected_prerelease
                        and isinstance(tag_name, str)
                        and tag_name.startswith(release_prefix)
                        and tag_name not in seen_release_tags
                    ):
                        candidate_releases.append(item)
                        seen_release_tags.add(tag_name)
                if len(releases) < 100:
                    break

            def published_timestamp(release: dict[str, Any]) -> tuple[bool, float, str]:
                value = release.get("published_at")
                if not isinstance(value, str):
                    value = release.get("created_at")
                if isinstance(value, str):
                    try:
                        parsed = datetime.datetime.fromisoformat(value)
                        if parsed.tzinfo is not None:
                            return True, parsed.timestamp(), str(release.get("tag_name", ""))
                    except (OverflowError, ValueError):
                        pass
                return False, 0.0, str(release.get("tag_name", ""))

            candidate_releases.sort(key=published_timestamp, reverse=True)

        if not candidate_releases:
            raise UpdateError(
                "NO_RELEASE",
                f"No {channel} component release is published for {publisher['repository']}.",
                retryable=True,
            )

        index_asset_name = publisher["releaseDiscovery"]["indexAssetName"]
        requested_target = target.get("target")
        for selected_release in candidate_releases:
            release_tag = selected_release.get("tag_name")
            assets = selected_release.get("assets")
            asset = (
                next(
                    (
                        entry
                        for entry in assets
                        if isinstance(entry, dict) and entry.get("name") == index_asset_name
                    ),
                    None,
                )
                if isinstance(assets, list)
                else None
            )
            if asset is None or not isinstance(asset.get("browser_download_url"), str):
                if release_id is not None:
                    raise UpdateError(
                        "RELEASE_INDEX_MISSING",
                        f"The selected {channel} release has no component index asset.",
                        retryable=True,
                    )
                continue
            if not isinstance(assets, list) or not all(isinstance(item, dict) for item in assets):
                raise UpdateError(
                    "INVALID_RELEASE_ASSETS", "The selected release asset list is invalid."
                )
            release_assets = tuple(dict(item) for item in assets)
            index_uri = asset["browser_download_url"]
            index_bytes = self._get_release_asset_bytes(
                release_assets,
                index_uri,
                repository=publisher["repository"],
                release_tag=release_tag,
            )
            try:
                index = json.loads(index_bytes)
            except (UnicodeDecodeError, json.JSONDecodeError) as error:
                raise UpdateError(
                    "INVALID_RELEASE_INDEX",
                    "The component release index is not valid UTF-8 JSON.",
                ) from error
            if not isinstance(index, dict) or not isinstance(index.get("releases"), list):
                raise UpdateError(
                    "INVALID_RELEASE_INDEX", "The component release index has no release list."
                )
            matching_rows = [
                row
                for row in index["releases"]
                if isinstance(row, dict)
                and row.get("componentId") == component["componentId"]
                and row.get("target") == requested_target
            ]
            if not matching_rows and release_id is None:
                continue

            self._validate_index(index, publisher, channel, selected_release, component)
            index_asset_digest = "sha256:" + hashlib.sha256(index_bytes).hexdigest()
            self._release_attestation_bundle(
                payload=index_bytes,
                repository=publisher["repository"],
                digest=index_asset_digest,
                workflow=publisher["workflow"],
                source_ref=index["source"]["ref"],
                source_commit=index["source"]["commit"],
                subject_name=index["provenance"]["attestation"]["subjectName"],
                release_assets=release_assets,
                release_tag=release_tag,
            )
            result = (index, index_uri, release_assets, release_tag)
            self._index_cache[key] = result
            self._index_asset_identity[key] = (
                index_asset_name,
                index_asset_digest,
            )
            return result

        raise UpdateError(
            "TARGET_RELEASE_MISSING",
            f"No {channel} release index contains {component['componentId']} at {target['id']}.",
            retryable=True,
        )

    def _release_list_page(self, repository: str, channel: str, uri: str) -> list[Any]:
        """Decode a cached raw release-list page without caching component filtering."""

        key = (repository, channel, uri)
        body = self._release_list_cache.get(key)
        if body is None:
            body = self._get_bytes(uri)
        try:
            releases = json.loads(body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_HTTP_JSON", f"Response from {uri} is not valid JSON.", retryable=True
            ) from error
        if not isinstance(releases, list):
            raise UpdateError(
                "RELEASE_DISCOVERY_INVALID",
                "GitHub Releases API did not return a release list.",
                retryable=True,
            )
        if key not in self._release_list_cache:
            # Store the original body only after it has decoded as a successful list response.
            self._release_list_cache[key] = body
        return releases

    def _release_asset_metadata(
        self,
        assets: tuple[dict[str, Any], ...],
        uri: Any,
        *,
        repository: str,
        release_tag: str,
    ) -> dict[str, Any]:
        """Resolve one exact immutable release asset entry from GitHub API metadata."""
        self._require_github_asset_uri(uri, repository)
        parts = urllib.parse.urlsplit(uri)
        expected_prefix = f"/{repository}/releases/download/{release_tag}/"
        if not isinstance(release_tag, str) or not parts.path.startswith(expected_prefix):
            raise UpdateError(
                "UNTRUSTED_URI", "Release asset URL is outside the selected immutable tag."
            )
        basename = PurePosixPath(parts.path).name
        matches = [
            item
            for item in assets
            if item.get("name") == basename and item.get("browser_download_url") == uri
        ]
        if len(matches) != 1:
            raise UpdateError(
                "RELEASE_ASSET_AMBIGUOUS",
                "Selected immutable release does not contain one exact matching asset.",
            )
        asset = matches[0]
        size = asset.get("size")
        digest = asset.get("digest")
        if (
            isinstance(size, bool)
            or not isinstance(size, int)
            or size < 1
            or size > MAX_RELEASE_ASSET_BYTES
            or not _valid_digest(digest)
        ):
            raise UpdateError(
                "INVALID_RELEASE_ASSET_METADATA",
                "Release asset size or SHA-256 metadata is invalid.",
            )
        return asset

    def _get_release_asset_bytes(
        self,
        assets: tuple[dict[str, Any], ...],
        uri: Any,
        *,
        repository: str,
        release_tag: str,
        expected_digest: str | None = None,
        expected_size: int | None = None,
        max_bytes: int = MAX_RELEASE_ASSET_BYTES,
    ) -> bytes:
        """Fetch an asset only when API and signed-manifest identities agree.

        `max_bytes` adds a stricter per-asset ceiling for detached proof files.
        """
        asset = self._release_asset_metadata(
            assets, uri, repository=repository, release_tag=release_tag
        )
        if asset["size"] > max_bytes:
            raise UpdateError(
                "RELEASE_ASSET_TOO_LARGE",
                "Selected release asset exceeds the allowed download size.",
            )
        if (expected_digest is not None and asset["digest"] != expected_digest) or (
            expected_size is not None and asset["size"] != expected_size
        ):
            raise UpdateError(
                "RELEASE_ASSET_IDENTITY_MISMATCH",
                "Release asset metadata differs from its trusted signed tuple.",
            )
        payload = self._get_bytes(uri, max_bytes=max_bytes)
        actual_digest = "sha256:" + hashlib.sha256(payload).hexdigest()
        if len(payload) != asset["size"] or actual_digest != asset["digest"]:
            raise UpdateError(
                "RELEASE_ASSET_DIGEST_MISMATCH",
                "Downloaded release asset differs from its immutable API size or digest.",
            )
        return payload

    def _release_attestation_bundle(
        self,
        *,
        payload: bytes,
        repository: str,
        digest: str,
        workflow: str,
        source_ref: str,
        source_commit: str,
        subject_name: str,
        release_assets: tuple[dict[str, Any], ...] | None = None,
        release_tag: str | None = None,
    ) -> bytes:
        """Return one proof bundle for the exact pinned subject and source.

        A listed detached sidecar is authoritative: malformed or mismatched sidecars fail
        closed. The GitHub attestations API is used only when the selected release omits it.
        """
        if (
            re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+", repository) is None
            or not _valid_digest(digest)
            or not isinstance(subject_name, str)
            or PurePosixPath(subject_name).name != subject_name
        ):
            raise UpdateError("INVALID_ATTESTATION", "Attestation lookup identity is invalid.")
        if (release_assets is None) != (release_tag is None):
            raise UpdateError(
                "INVALID_ATTESTATION", "Release sidecar lookup is missing its release identity."
            )

        sidecar_asset: dict[str, Any] | None = None
        sidecar_uri: str | None = None
        if release_assets is not None and release_tag is not None:
            sidecar_name = f"{subject_name}.attestation.jsonl"
            matching_assets = [
                item
                for item in release_assets
                if isinstance(item, dict) and item.get("name") == sidecar_name
            ]
            if len(matching_assets) > 1:
                raise UpdateError(
                    "RELEASE_ASSET_AMBIGUOUS",
                    "Selected release has duplicate attestation sidecar assets.",
                )
            if matching_assets:
                sidecar_asset = matching_assets[0]
                sidecar_uri = sidecar_asset.get("browser_download_url")
                # Validate the selected asset against this exact immutable release before
                # consulting any previously verified bundle cache.
                sidecar_asset = self._release_asset_metadata(
                    release_assets,
                    sidecar_uri,
                    repository=repository,
                    release_tag=release_tag,
                )
                if sidecar_asset["name"] != sidecar_name:
                    raise UpdateError(
                        "INVALID_ATTESTATION", "Release sidecar name does not match its subject."
                    )
                if sidecar_asset["size"] > MAX_ATTESTATION_RESPONSE_BYTES:
                    raise UpdateError(
                        "INVALID_ATTESTATION", "Attestation sidecar exceeds the size limit."
                    )
        endpoint = (
            f"https://api.github.com/repos/{repository}/attestations/"
            f"{urllib.parse.quote(digest, safe=':')}?per_page=100"
        )
        # Sidecar proof identity must not reuse an older API proof when a sidecar exists.
        cache_identity = {
            "schemaVersion": 2 if sidecar_asset is not None else 1,
            "repository": repository,
            "subjectName": subject_name,
            "subjectDigest": digest,
            "workflow": workflow,
            "sourceRef": source_ref,
            "sourceCommit": source_commit,
        }
        if sidecar_asset is not None:
            cache_identity["proofSource"] = {
                "kind": "release-sidecar",
                "releaseTag": release_tag,
                "assetName": sidecar_asset["name"],
                "assetUri": sidecar_uri,
                "assetDigest": sidecar_asset["digest"],
                "assetSize": sidecar_asset["size"],
            }
        cache_key = hashlib.sha256(
            json.dumps(cache_identity, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()
        cache_path = self._private_state_directory("attestations") / f"{cache_key}.bundle"
        try:
            cached_bundle = _read_private_cache_bytes(
                cache_path,
                max_bytes=MAX_ATTESTATION_BUNDLE_BYTES,
                description="cached attestation bundle",
            )
        except FileNotFoundError:
            cached_bundle = None
        if cached_bundle is not None:
            self._verify_cached_attestation_bundle(
                cached_bundle,
                payload=payload,
                repository=repository,
                digest=digest,
                workflow=workflow,
                source_ref=source_ref,
                source_commit=source_commit,
                subject_name=subject_name,
            )
            return cached_bundle

        if sidecar_asset is not None and sidecar_uri is not None and release_tag is not None:
            sidecar_bytes = self._get_release_asset_bytes(
                release_assets or (),
                sidecar_uri,
                repository=repository,
                release_tag=release_tag,
                expected_digest=sidecar_asset["digest"],
                expected_size=sidecar_asset["size"],
                max_bytes=MAX_ATTESTATION_RESPONSE_BYTES,
            )
            bundles = self._parse_attestation_jsonl(sidecar_bytes)
            verification_errors: list[UpdateError] = []
            for bundle_bytes, bundle in bundles:
                if not self._bundle_declares_subject(bundle, subject_name, digest):
                    continue
                try:
                    self._verify_cached_attestation_bundle(
                        bundle_bytes,
                        payload=payload,
                        repository=repository,
                        digest=digest,
                        workflow=workflow,
                        source_ref=source_ref,
                        source_commit=source_commit,
                        subject_name=subject_name,
                    )
                except UpdateError as error:
                    if error.code in {"ATTESTATION_INVALID", "ATTESTATION_SUBJECT_MISMATCH"}:
                        verification_errors.append(error)
                        continue
                    raise
                _atomic_private_bytes(cache_path, bundle_bytes)
                return bundle_bytes
            if verification_errors:
                raise UpdateError(
                    "ATTESTATION_INVALID",
                    "No detached bundle matches the pinned workflow, source, and subject.",
                ) from verification_errors[-1]
            raise UpdateError(
                "ATTESTATION_INVALID", "Detached sidecar has no bundle for the pinned subject."
            )

        response_bytes = self._get_bytes(endpoint, max_bytes=MAX_ATTESTATION_RESPONSE_BYTES)
        try:
            response = json.loads(response_bytes, object_pairs_hook=_unique_json_object)
        except (UnicodeDecodeError, json.JSONDecodeError, UpdateError) as error:
            raise UpdateError(
                "INVALID_ATTESTATION", "GitHub returned invalid attestation JSON."
            ) from error
        if not isinstance(response, dict) or set(response) != {"attestations"}:
            raise UpdateError(
                "INVALID_ATTESTATION", "GitHub returned an unknown attestation response shape."
            )
        attestations = response.get("attestations")
        if not isinstance(attestations, list) or not attestations or len(attestations) >= 100:
            raise UpdateError(
                "ATTESTATION_MISSING",
                "GitHub returned no complete attestation set for this subject.",
            )

        verification_errors: list[UpdateError] = []
        for item in attestations:
            if not isinstance(item, dict) or set(item) != {
                "repository_id",
                "bundle_url",
                "initiator",
                "bundle",
            }:
                raise UpdateError(
                    "INVALID_ATTESTATION", "GitHub returned an unknown attestation record shape."
                )
            repository_id = item.get("repository_id")
            bundle_url = item.get("bundle_url")
            initiator = item.get("initiator")
            bundle = item.get("bundle")
            bundle_url_parts = (
                urllib.parse.urlsplit(bundle_url) if isinstance(bundle_url, str) else None
            )
            if (
                isinstance(repository_id, bool)
                or not isinstance(repository_id, int)
                or repository_id < 1
                or not isinstance(initiator, str)
                or initiator not in {"github", "user"}
                or bundle_url_parts is None
                or bundle_url_parts.scheme != "https"
                or not bundle_url_parts.hostname
                or not isinstance(bundle, dict)
                or set(bundle) != {"mediaType", "verificationMaterial", "dsseEnvelope"}
            ):
                raise UpdateError(
                    "INVALID_ATTESTATION", "GitHub returned malformed attestation bundle metadata."
                )
            bundle_bytes = json.dumps(bundle, separators=(",", ":")).encode("utf-8")
            if len(bundle_bytes) > MAX_ATTESTATION_BUNDLE_BYTES:
                raise UpdateError(
                    "INVALID_ATTESTATION", "GitHub attestation bundle exceeds the size limit."
                )
            if not self._bundle_declares_subject(bundle, subject_name, digest):
                continue
            try:
                self._verify_cached_attestation_bundle(
                    bundle_bytes,
                    payload,
                    repository=repository,
                    digest=digest,
                    workflow=workflow,
                    source_ref=source_ref,
                    source_commit=source_commit,
                    subject_name=subject_name,
                )
            except UpdateError as error:
                if error.code in {"ATTESTATION_INVALID", "ATTESTATION_SUBJECT_MISMATCH"}:
                    verification_errors.append(error)
                    continue
                raise
            _atomic_private_bytes(cache_path, bundle_bytes)
            return bundle_bytes
        if verification_errors:
            raise UpdateError(
                "ATTESTATION_INVALID",
                "No GitHub attestation bundle matches the pinned workflow, source, and subject.",
            ) from verification_errors[-1]
        raise UpdateError(
            "ATTESTATION_INVALID", "No acceptable GitHub attestation bundle was returned."
        )

    @staticmethod
    def _parse_attestation_jsonl(payload: bytes) -> tuple[tuple[bytes, dict[str, Any]], ...]:
        """Parse every bundle in one bounded detached GitHub attestation sidecar."""
        if not payload or len(payload) > MAX_ATTESTATION_RESPONSE_BYTES:
            raise UpdateError("INVALID_ATTESTATION", "Attestation sidecar size is invalid.")
        lines = payload.split(b"\n")
        if lines and lines[-1] == b"":  # JSONL producers terminate the last record with LF.
            lines.pop()
        if not lines:
            raise UpdateError("INVALID_ATTESTATION", "Attestation sidecar contains no bundles.")

        parsed: list[tuple[bytes, dict[str, Any]]] = []
        for raw_line in lines:
            if raw_line.endswith(b"\r"):
                raw_line = raw_line[:-1]
            if not raw_line.strip() or len(raw_line) > MAX_ATTESTATION_BUNDLE_BYTES:
                raise UpdateError("INVALID_ATTESTATION", "Attestation sidecar line is invalid.")
            try:
                bundle = json.loads(raw_line.decode("utf-8"), object_pairs_hook=_unique_json_object)
            except (UnicodeDecodeError, json.JSONDecodeError, UpdateError) as error:
                raise UpdateError(
                    "INVALID_ATTESTATION", "Attestation sidecar contains invalid JSONL."
                ) from error
            if (
                not isinstance(bundle, dict)
                or set(bundle) != {"mediaType", "verificationMaterial", "dsseEnvelope"}
                or not isinstance(bundle.get("mediaType"), str)
                or not isinstance(bundle.get("verificationMaterial"), dict)
                or not isinstance(bundle.get("dsseEnvelope"), dict)
            ):
                raise UpdateError(
                    "INVALID_ATTESTATION", "Attestation sidecar bundle shape is invalid."
                )
            # Validate the envelope and in-toto statement even for bundles for other
            # subjects; a malformed neighboring record invalidates the whole sidecar.
            ComponentUpdater._bundle_declares_subject(bundle, "", "sha256:" + "0" * 64)
            parsed.append((raw_line, bundle))
        return tuple(parsed)

    def _verify_cached_attestation_bundle(
        self,
        bundle_bytes: bytes,
        payload: bytes,
        *,
        repository: str,
        digest: str,
        workflow: str,
        source_ref: str,
        source_commit: str,
        subject_name: str,
    ) -> None:
        """Re-run subject and cryptographic verification for every bundle consumption."""

        if not bundle_bytes or len(bundle_bytes) > MAX_ATTESTATION_BUNDLE_BYTES:
            raise UpdateError("INVALID_ATTESTATION", "Attestation bundle size is invalid.")
        try:
            bundle = json.loads(bundle_bytes, object_pairs_hook=_unique_json_object)
        except (UnicodeDecodeError, json.JSONDecodeError, UpdateError) as error:
            raise UpdateError(
                "INVALID_ATTESTATION", "Attestation bundle JSON is invalid."
            ) from error
        if (
            not isinstance(bundle, dict)
            or set(bundle) != {"mediaType", "verificationMaterial", "dsseEnvelope"}
            or not isinstance(bundle.get("mediaType"), str)
            or not isinstance(bundle.get("verificationMaterial"), dict)
            or not isinstance(bundle.get("dsseEnvelope"), dict)
        ):
            raise UpdateError("INVALID_ATTESTATION", "Attestation bundle shape is invalid.")
        if not self._bundle_declares_subject(bundle, subject_name, digest):
            raise UpdateError(
                "ATTESTATION_SUBJECT_MISMATCH",
                "Attestation bundle does not bind the expected subject and SHA-256 digest.",
            )
        self._verify_attestation(
            payload,
            subject_name=subject_name,
            digest=digest,
            repository=repository,
            workflow=workflow,
            source_ref=source_ref,
            source_commit=source_commit,
            bundle_bytes=bundle_bytes,
        )

    @staticmethod
    def _bundle_declares_subject(bundle: dict[str, Any], subject_name: str, digest: str) -> bool:
        """Skip unrelated well-formed bundles before invoking the cryptographic verifier."""
        envelope = bundle.get("dsseEnvelope")
        if not isinstance(envelope, dict) or set(envelope) != {
            "payloadType",
            "payload",
            "signatures",
        }:
            raise UpdateError(
                "INVALID_ATTESTATION", "GitHub attestation DSSE envelope is malformed."
            )
        encoded_payload = envelope.get("payload")
        if envelope.get("payloadType") != "application/vnd.in-toto+json" or not isinstance(
            encoded_payload, str
        ):
            raise UpdateError(
                "INVALID_ATTESTATION", "GitHub attestation DSSE payload is malformed."
            )
        try:
            statement = json.loads(
                base64.b64decode(encoded_payload, validate=True),
                object_pairs_hook=_unique_json_object,
            )
        except (ValueError, json.JSONDecodeError, UpdateError) as error:
            raise UpdateError(
                "INVALID_ATTESTATION", "GitHub attestation DSSE payload is invalid."
            ) from error
        if not isinstance(statement, dict):
            raise UpdateError("INVALID_ATTESTATION", "GitHub attestation statement is malformed.")
        if statement.get("predicateType") != "https://slsa.dev/provenance/v1":
            return False
        subjects = statement.get("subject")
        if not isinstance(subjects, list):
            raise UpdateError(
                "INVALID_ATTESTATION", "GitHub attestation subject list is malformed."
            )
        raw_digest = digest.removeprefix("sha256:")
        return any(
            isinstance(subject, dict)
            and subject.get("name") == subject_name
            and isinstance(subject.get("digest"), dict)
            and subject["digest"].get("sha256") == raw_digest
            for subject in subjects
        )

    def _validate_index(
        self,
        index: Any,
        publisher: dict[str, Any],
        channel: str,
        release: dict[str, Any],
        component: dict[str, Any],
    ) -> None:
        if (
            not isinstance(index, dict)
            or index.get("schemaVersion") != 1
            or index.get("repository") != publisher["repository"]
            or index.get("channel") != channel
        ):
            raise UpdateError(
                "INVALID_RELEASE_INDEX", "The release index identity or channel is inconsistent."
            )
        if index.get("indexDigest") != _digest_json(index, "indexDigest"):
            raise UpdateError("INDEX_DIGEST_MISMATCH", "The release index digest is invalid.")
        source = index.get("source")
        attestation = index.get("provenance", {}).get("attestation")
        allowed_refs = self.catalog["channels"][channel]["sourceRefs"]
        if (
            not isinstance(source, dict)
            or source.get("repository") != f"https://github.com/{publisher['repository']}"
            or source.get("ref") not in allowed_refs
            or COMMIT_PATTERN.fullmatch(str(source.get("commit", ""))) is None
        ):
            raise UpdateError(
                "UNTRUSTED_SOURCE",
                "The release index source is outside the trusted repository/ref pins.",
            )
        releases = index.get("releases")
        if not isinstance(releases, list):
            raise UpdateError("INVALID_RELEASE_INDEX", "The release index has no release list.")
        tag_format = publisher.get("tagFormat", "source-sha")
        if tag_format == "source-sha":
            prefix = self._component_release_tag_prefix(component, channel) or f"{channel}-"
            expected_tag = prefix + source["commit"]
        elif tag_format == "component-source-sha":
            prefix = f"{channel}-{component['componentId']}-"
            if self._component_release_tag_prefix(component, channel) not in {None, prefix}:
                raise UpdateError(
                    "INVALID_CATALOG",
                    "The component release prefix differs from the publisher tag format.",
                )
            expected_tag = prefix + source["commit"]
        elif tag_format == "component-version-source-sha":
            prefix = f"{channel}-{component['componentId']}-"
            if self._component_release_tag_prefix(component, channel) not in {None, prefix}:
                raise UpdateError(
                    "INVALID_CATALOG",
                    "The component release prefix differs from the publisher tag format.",
                )
            versions = {
                row.get("version")
                for row in releases
                if isinstance(row, dict) and row.get("componentId") == component["componentId"]
            }
            if len(versions) != 1:
                raise UpdateError(
                    "INVALID_RELEASE_INDEX",
                    "A versioned publisher index must contain one exact component version.",
                )
            version = next(iter(versions))
            if not isinstance(version, str) or SEMVER3_PATTERN.fullmatch(version) is None:
                raise UpdateError(
                    "INVALID_RELEASE_INDEX",
                    "A versioned publisher index contains an invalid component version.",
                )
            expected_tag = f"{prefix}{version}-{source['commit']}"
        else:
            raise UpdateError(
                "INVALID_CATALOG",
                f"Unsupported publisher tag format {tag_format!r}.",
            )
        if release.get("tag_name") != expected_tag:
            raise UpdateError(
                "UNTRUSTED_RELEASE_TAG",
                "The immutable release tag does not match the exact catalog publisher format and source.",
            )
        run = attestation.get("run") if isinstance(attestation, dict) else None
        if (
            not isinstance(attestation, dict)
            or attestation.get("kind") != "github-artifact-attestation"
            or attestation.get("repository") != publisher["repository"]
            or attestation.get("workflow") != publisher["workflow"]
            or attestation.get("predicateType") != "https://slsa.dev/provenance/v1"
            or attestation.get("subjectName") != publisher["releaseDiscovery"].get("indexAssetName")
            or not isinstance(run, dict)
            or not isinstance(run.get("id"), str)
            or re.fullmatch(r"[0-9]{1,30}", run["id"]) is None
            or not isinstance(run.get("attempt"), int)
            or isinstance(run.get("attempt"), bool)
            or run["attempt"] < 1
            or run.get("url")
            != f"https://github.com/{publisher['repository']}/actions/runs/{run['id']}/attempts/{run['attempt']}"
        ):
            raise UpdateError(
                "UNTRUSTED_WORKFLOW",
                "The index attestation identity differs from the trusted publisher workflow.",
            )
        if not isinstance(index.get("compatibilityGroups", []), list):
            raise UpdateError(
                "INVALID_RELEASE_INDEX", "The release index compatibilityGroups field is invalid."
            )

    @staticmethod
    def _component_release_tag_prefix(component: dict[str, Any], channel: str) -> str | None:
        discovery = component.get("releaseDiscovery")
        if discovery is None:
            return None
        if not isinstance(discovery, dict) or set(discovery) != {"tagPrefixes"}:
            raise UpdateError(
                "INVALID_CATALOG",
                f"Component-specific release tag prefixes are invalid for {component.get('componentId')}.",
            )
        prefixes = discovery.get("tagPrefixes")
        prefix = prefixes.get(channel) if isinstance(prefixes, dict) else None
        expected = f"{channel}-{component.get('componentId')}-"
        if (
            not isinstance(prefixes, dict)
            or set(prefixes) != {"preview", "stable"}
            or prefix != expected
            or any(
                prefixes.get(item) != f"{item}-{component.get('componentId')}-"
                for item in ("stable", "preview")
            )
        ):
            raise UpdateError(
                "INVALID_CATALOG",
                f"Component-specific release tag prefixes are invalid for {component.get('componentId')}.",
            )
        return prefix

    def _publisher_for_component(self, component: dict[str, Any]) -> dict[str, Any] | None:
        """Resolve a legacy repository key or an explicit v2 publisher identity.

        V2 catalogs pin publisher IDs so two workflows in one repository cannot
        inherit each other's signing authority. Legacy v1 components continue to
        resolve by repository.
        中文：v2通过publisherId隔离同仓库的发布工作流；v1继续使用仓库身份。
        """

        publisher_id = component.get("publisherId")
        if publisher_id is not None:
            publisher = self.publisher_ids.get(publisher_id)
            if publisher is None or publisher.get("repository") != component.get("publisher"):
                return None
            return publisher
        repository = component.get("publisher")
        return self.publishers.get(repository) if isinstance(repository, str) else None

    def _candidate(
        self,
        component: dict[str, Any],
        target: dict[str, Any],
        channel: str,
        *,
        release_id: str | None = None,
    ) -> Candidate:
        publisher = self._publisher_for_component(component)
        if publisher is None:
            raise UpdateError(
                "INVALID_CATALOG",
                f"No trusted publisher is configured for {component['componentId']}.",
            )
        index, index_uri, release_assets, release_tag = self._channel_releases(
            publisher, channel, component, target, release_id=release_id
        )
        index_key = (
            publisher["repository"],
            channel,
            component["componentId"],
            target["id"],
            release_id or "latest",
        )
        index_asset_identity = self._index_asset_identity.get(index_key)
        if index_asset_identity is None:
            raise UpdateError(
                "INVALID_RELEASE_INDEX",
                "The verified release index has no retained byte identity.",
            )
        entries = [
            item
            for item in index.get("releases", [])
            if isinstance(item, dict)
            and item.get("componentId") == component["componentId"]
            and item.get("target") == target["target"]
        ]
        if len(entries) != 1:
            raise UpdateError(
                "TARGET_RELEASE_MISSING",
                f"Index has no unique {channel} manifest for {component['componentId']} at {target['id']}.",
                retryable=True,
            )
        entry = entries[0]
        manifest_bytes = self._get_release_asset_bytes(
            release_assets,
            entry.get("manifestUri"),
            repository=publisher["repository"],
            release_tag=release_tag,
        )
        try:
            manifest = json.loads(manifest_bytes, object_pairs_hook=_unique_json_object)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_MANIFEST", f"Manifest for {component['componentId']} is invalid JSON."
            ) from error
        self._validate_manifest(manifest, entry, component, target, publisher, channel, index)
        manifest_asset_digest = "sha256:" + hashlib.sha256(manifest_bytes).hexdigest()
        if manifest.get("schemaVersion") == 2:
            manifest_name = PurePosixPath(urllib.parse.urlsplit(entry["manifestUri"]).path).name
            self._release_attestation_bundle(
                payload=manifest_bytes,
                repository=publisher["repository"],
                digest=manifest_asset_digest,
                workflow=publisher["workflow"],
                source_ref=manifest["source"]["ref"],
                source_commit=manifest["source"]["commit"],
                subject_name=manifest_name,
                release_assets=release_assets,
                release_tag=release_tag,
            )
        artifact = manifest["artifact"]
        artifact_digest = (
            artifact.get("archive", {}).get("sha256")
            if artifact.get("kind") == "plugin-package"
            and isinstance(artifact.get("archive"), dict)
            else artifact.get("digest", artifact.get("sha256"))
        )
        if not _valid_digest(artifact_digest):
            raise UpdateError(
                "INVALID_MANIFEST",
                f"Artifact digest is invalid for {component['componentId']}.",
            )
        return Candidate(
            component,
            manifest,
            entry["manifestDigest"],
            artifact_digest,
            entry["manifestUri"],
            index,
            index_uri,
            manifest_bytes,
            release_assets,
            release_tag,
            index_asset_identity[0],
            index_asset_identity[1],
            manifest_asset_digest,
        )

    def _load_workload_resolver(self) -> Any:
        """Load the packaged pure resolver without accepting a substituted path."""

        module_path = Path(__file__).with_name("workload_resolver.py")
        if module_path.is_symlink() or not module_path.is_file():
            raise UpdateError("WORKLOAD_RESOLVER_MISSING", "The workload resolver is unavailable.")
        import importlib.util

        module_name = "_cyrene_workload_resolver"
        spec = importlib.util.spec_from_file_location(module_name, module_path)
        if spec is None or spec.loader is None:
            raise UpdateError("WORKLOAD_RESOLVER_MISSING", "The workload resolver cannot load.")
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        try:
            spec.loader.exec_module(module)
        except Exception as error:
            sys.modules.pop(module_name, None)
            raise UpdateError(
                "WORKLOAD_RESOLVER_INVALID", "The workload resolver failed."
            ) from error
        if not callable(getattr(module, "resolve_workload", None)) or not callable(
            getattr(module, "potential_component_ids", None)
        ):
            raise UpdateError("WORKLOAD_RESOLVER_INVALID", "The workload resolver API is invalid.")
        return module

    def _trusted_release_indexes(self, candidates: list[Candidate]) -> dict[str, Any]:
        """Project only already-attested release indexes and manifests for resolution.

        This projection carries both the raw index asset digest and its canonical
        index digest. It does not create trust: every candidate has already passed
        the updater's catalog, publisher, source, index, manifest, and attestation
        checks before it is included.
        中文：仅把已通过更新器验签的index/manifest投影给解析器，不在此处新建信任。
        """

        indexes: dict[tuple[str, str, str], dict[str, Any]] = {}
        for candidate in candidates:
            publisher = self._publisher_for_component(candidate.component)
            index_source = candidate.index.get("source")
            index_attestation = candidate.index.get("provenance", {}).get("attestation")
            manifest_source = candidate.manifest.get("source")
            manifest_attestation = candidate.manifest.get("provenance", {}).get("attestation")
            if (
                publisher is None
                or candidate.release_tag is None
                or not isinstance(candidate.index_asset_name, str)
                or not _valid_digest(candidate.index_asset_digest)
                or not isinstance(index_source, dict)
                or not isinstance(index_attestation, dict)
                or not isinstance(manifest_source, dict)
                or not isinstance(manifest_attestation, dict)
                or candidate.manifest.get("schemaVersion") == 2
                and not _valid_digest(candidate.manifest_asset_digest)
            ):
                raise UpdateError(
                    "UNTRUSTED_RELEASE_INDEX",
                    f"Verified source identity is incomplete for {candidate.component.get('componentId')!r}.",
                )
            repository = publisher["repository"]
            workflow = publisher["workflow"]
            key = (repository, candidate.index_uri, candidate.release_tag)
            index_attestation_ref = {
                "repository": repository,
                "workflow": workflow,
                "sourceCommit": index_source["commit"],
                "sourceRef": index_source["ref"],
                "subjectName": index_attestation["subjectName"],
                "subjectDigest": candidate.index_asset_digest,
            }
            manifest_attestation_ref = {
                "repository": repository,
                "workflow": workflow,
                "sourceCommit": manifest_source["commit"],
                "sourceRef": manifest_source["ref"],
                "subjectName": manifest_attestation["subjectName"],
                # Manifest bytes are bound by the index's JCS digest; the
                # manifest's provenance subject is its payload/archive digest.
                "subjectDigest": candidate.artifact_digest,
            }
            manifest_asset_attestation_ref = None
            if candidate.manifest.get("schemaVersion") == 2:
                manifest_name = PurePosixPath(
                    urllib.parse.urlsplit(candidate.manifest_uri).path
                ).name
                manifest_asset_attestation_ref = {
                    "repository": repository,
                    "workflow": workflow,
                    "sourceCommit": manifest_source["commit"],
                    "sourceRef": manifest_source["ref"],
                    "subjectName": manifest_name,
                    "subjectDigest": candidate.manifest_asset_digest,
                }
            identity = indexes.get(key)
            if identity is None:
                identity = {
                    "repository": repository,
                    "assetName": candidate.index_asset_name,
                    "assetUri": candidate.index_uri,
                    "assetDigest": candidate.index_asset_digest,
                    "indexDigest": candidate.index.get("indexDigest"),
                    "channel": candidate.manifest.get("channel"),
                    "releaseTag": candidate.release_tag,
                    "source": dict(index_source),
                    "attestationRef": index_attestation_ref,
                    "index": candidate.index,
                    "manifests": [],
                }
                indexes[key] = identity
            elif (
                identity["assetDigest"] != candidate.index_asset_digest
                or identity["indexDigest"] != candidate.index.get("indexDigest")
                or identity["source"] != index_source
            ):
                raise UpdateError(
                    "UNTRUSTED_RELEASE_INDEX",
                    "Candidates grouped under one release index disagree on its verified identity.",
                )
            identity["manifests"].append(
                {
                    "componentId": candidate.component["componentId"],
                    "version": candidate.manifest["version"],
                    "target": candidate.manifest["target"],
                    "manifestUri": candidate.manifest_uri,
                    "manifestDigest": candidate.manifest_digest,
                    "manifestAssetDigest": candidate.manifest_asset_digest,
                    "artifactDigest": candidate.artifact_digest,
                    "manifest": candidate.manifest,
                    "releaseTag": candidate.release_tag,
                    "attestationRef": manifest_attestation_ref,
                    **(
                        {"manifestAssetAttestationRef": manifest_asset_attestation_ref}
                        if manifest_asset_attestation_ref is not None
                        else {}
                    ),
                }
            )
        normalized = []
        for identity in indexes.values():
            identity["manifests"].sort(key=lambda item: (item["componentId"], item["target"]))
            normalized.append(identity)
        normalized.sort(
            key=lambda item: (item["repository"], item["assetName"], item["releaseTag"])
        )
        return {"indexes": normalized}

    def _validate_manifest(
        self,
        manifest: Any,
        entry: dict[str, Any],
        component: dict[str, Any],
        target: dict[str, Any],
        publisher: dict[str, Any],
        channel: str,
        index: dict[str, Any],
    ) -> None:
        required = {
            "schemaVersion",
            "releaseId",
            "componentId",
            "version",
            "channel",
            "target",
            "artifact",
            "dependencies",
            "restart",
            "source",
            "provenance",
            "manifestDigest",
        }
        schema_version = manifest.get("schemaVersion") if isinstance(manifest, dict) else None
        if isinstance(schema_version, bool) or schema_version not in (1, 2):
            raise UpdateError(
                "UNSUPPORTED_MANIFEST_VERSION",
                f"Manifest for {component['componentId']} uses an unsupported schema version.",
            )
        allowed = required | {"health", "compatibility"}
        if schema_version == 2:
            required |= {"protocolVersion", "contentDigest"}
            allowed |= {
                "protocolVersion",
                "contentDigest",
                "dataBundle",
            }
        if (
            not isinstance(manifest, dict)
            or set(manifest) - allowed
            or not required.issubset(manifest)
        ):
            raise UpdateError(
                "INVALID_MANIFEST",
                f"Manifest for {component['componentId']} has an invalid object shape.",
            )
        if (
            manifest.get("schemaVersion") != schema_version
            or manifest.get("componentId") != component["componentId"]
            or manifest.get("version") != entry.get("version")
            or manifest.get("target") != target["target"]
            or manifest.get("channel") != channel
        ):
            raise UpdateError(
                "MANIFEST_IDENTITY_MISMATCH",
                f"Manifest identity differs from its trusted index for {component['componentId']}.",
            )
        if manifest.get("manifestDigest") != _digest_json(manifest, "manifestDigest") or manifest[
            "manifestDigest"
        ] != entry.get("manifestDigest"):
            raise UpdateError(
                "MANIFEST_DIGEST_MISMATCH",
                f"Manifest JCS digest is invalid for {component['componentId']}.",
            )
        if VERSION_PATTERN.fullmatch(str(manifest.get("version", ""))) is None:
            raise UpdateError(
                "INVALID_MANIFEST", "Release version is not a safe immutable path segment."
            )
        if schema_version == 2:
            protocol_version = manifest.get("protocolVersion")
            if (
                not isinstance(protocol_version, str)
                or re.fullmatch(r"[a-z][a-z0-9._-]{0,127}", protocol_version) is None
            ):
                raise UpdateError("INVALID_MANIFEST", "Manifest protocolVersion is invalid.")
            expected_protocol = component.get("protocolVersion")
            group_id = component.get("compatibilityGroup")
            if group_id:
                group = next(
                    (
                        item
                        for item in self.catalog.get("compatibilityGroups", [])
                        if isinstance(item, dict) and item.get("groupId") == group_id
                    ),
                    None,
                )
                member = (
                    next(
                        (
                            item
                            for item in group.get("members", [])
                            if isinstance(item, dict)
                            and item.get("componentId") == component["componentId"]
                        ),
                        None,
                    )
                    if group
                    else None
                )
                member_protocol = (
                    member.get("protocolVersion") if isinstance(member, dict) else None
                )
                if schema_version == 2 and (
                    not isinstance(member_protocol, str)
                    or (expected_protocol is not None and expected_protocol != member_protocol)
                ):
                    raise UpdateError(
                        "INVALID_CATALOG",
                        f"V2 group member {component['componentId']} must have a matching explicit protocol pin.",
                    )
                expected_protocol = member_protocol or expected_protocol
            if not isinstance(expected_protocol, str) or protocol_version != expected_protocol:
                raise UpdateError(
                    "PROTOCOL_VERSION_UNSUPPORTED",
                    f"No trusted client support is pinned for {component['componentId']} protocol {protocol_version!r}.",
                )
            artifact_descriptor = manifest.get("artifact")
            artifact_content_digest = (
                artifact_descriptor.get("digest")
                if isinstance(artifact_descriptor, dict)
                and artifact_descriptor.get("kind") == "oci-image"
                else artifact_descriptor.get("sha256")
                if isinstance(artifact_descriptor, dict)
                else None
            )
            if (
                isinstance(artifact_descriptor, dict)
                and artifact_descriptor.get("kind") == "plugin-package"
                and isinstance(artifact_descriptor.get("archive"), dict)
            ):
                artifact_content_digest = artifact_descriptor["archive"].get("sha256")
            content_digest = manifest.get("contentDigest")
            if not _valid_digest(content_digest) or content_digest != artifact_content_digest:
                raise UpdateError(
                    "CONTENT_DIGEST_MISMATCH",
                    f"Manifest content digest is invalid for {component['componentId']}.",
                )
            compatibility_group = component.get("compatibilityGroup")
            if compatibility_group and not isinstance(manifest.get("compatibility"), dict):
                raise UpdateError(
                    "COMPATIBILITY_MISSING",
                    f"{component['componentId']} v2 release omits its trusted compatibility pins.",
                )
            elif compatibility_group:
                group = next(
                    (
                        item
                        for item in self.catalog.get("compatibilityGroups", [])
                        if item.get("groupId") == compatibility_group
                    ),
                    None,
                )
                compatibility = manifest["compatibility"]
                if (
                    group is None
                    or compatibility.get("groupId") != compatibility_group
                    or compatibility.get("groupVersion") != group.get("groupVersion")
                    or compatibility.get("wireApiVersion") != group.get("wireApiVersion")
                    or compatibility.get("contractApiVersion") != group.get("contractApiVersion")
                ):
                    raise UpdateError(
                        "COMPATIBILITY_GROUP_MISMATCH",
                        f"{component['componentId']} compatibility tuple differs from the trusted group.",
                    )
                if schema_version == 2 and (
                    not _trusted_contract_lock(group.get("contractLock"))
                    or compatibility.get("contractLock") != group.get("contractLock")
                ):
                    raise UpdateError(
                        "COMPATIBILITY_LOCK_UNTRUSTED",
                        f"{component['componentId']} contractLock differs from the trusted catalog pin.",
                    )
            data_bundle = manifest.get("dataBundle")
            artifact_kind = (
                manifest.get("artifact", {}).get("kind")
                if isinstance(manifest.get("artifact"), dict)
                else None
            )
            if artifact_kind == "data-bundle":
                if (
                    not isinstance(data_bundle, dict)
                    or set(data_bundle) != {"proofPath", "proofSha256"}
                    or data_bundle.get("proofPath") != "data-bundle-proof-v1.json"
                    or not _valid_digest(data_bundle.get("proofSha256"))
                ):
                    raise UpdateError(
                        "INVALID_DATA_BUNDLE_PROOF",
                        "V2 data-bundle manifest must pin the fixed proof path and digest.",
                    )
            elif data_bundle is not None:
                raise UpdateError(
                    "INVALID_MANIFEST",
                    "Only data-bundle artifacts may declare dataBundle proof metadata.",
                )
        self._validate_manifest_dependencies(
            manifest.get("dependencies"), component, require_version_range=schema_version == 2
        )
        source = manifest.get("source")
        index_source = index["source"]
        publisher_repo_url = f"https://github.com/{publisher['repository']}"
        allowed_refs = self.catalog["channels"][channel]["sourceRefs"]
        if (
            not isinstance(source, dict)
            or source.get("repository") != publisher_repo_url
            or source.get("ref") not in allowed_refs
            or source.get("ref") != index_source.get("ref")
            or source.get("commit") != index_source.get("commit")
        ):
            raise UpdateError(
                "UNTRUSTED_SOURCE",
                f"Manifest source for {component['componentId']} is not pinned by its attested index.",
            )
        attestation = manifest.get("provenance", {}).get("attestation")
        index_attestation = index["provenance"]["attestation"]
        if (
            not isinstance(attestation, dict)
            or attestation.get("kind") != "github-artifact-attestation"
            or attestation.get("repository") != publisher["repository"]
            or attestation.get("workflow") != publisher["workflow"]
            or attestation.get("predicateType") != "https://slsa.dev/provenance/v1"
            or attestation.get("run") != index_attestation.get("run")
        ):
            raise UpdateError(
                "UNTRUSTED_WORKFLOW",
                f"Manifest provenance for {component['componentId']} differs from its attested release run.",
            )
        artifact = manifest.get("artifact")
        if (
            not isinstance(artifact, dict)
            or artifact.get("kind") != target["artifactKind"]
            or artifact.get("kind") not in component.get("artifactKinds", [])
        ):
            raise UpdateError(
                "UNSUPPORTED_ARTIFACT",
                f"Artifact kind is not supported for {component['componentId']} at this target.",
            )
        oci_image = artifact.get("kind") == "oci-image"
        if oci_image and (
            schema_version != 1
            or component.get("componentId") != WORKLOAD_ECHO_COMPONENT_ID
            or target.get("id") != WORKLOAD_ECHO_TARGET_ID
            or component.get("ociImageRepository") != "ghcr.io/dohorizon-ai/cyrene-echo"
            or set(artifact) != {"kind", "repository", "digest", "platform"}
            or artifact.get("repository") != "ghcr.io/dohorizon-ai/cyrene-echo"
            or not _valid_digest(artifact.get("digest"))
            or artifact.get("platform") != {"os": "linux", "architecture": "amd64"}
        ):
            raise UpdateError(
                "INVALID_MANIFEST",
                "OCI workload identity is outside the exact signed Echo Ubuntu target.",
            )
        plugin_package = artifact.get("kind") == "plugin-package"
        archive = artifact.get("archive") if plugin_package else None
        artifact_sha256 = (
            archive.get("sha256") if isinstance(archive, dict) else artifact.get("sha256")
        )
        artifact_size = (
            archive.get("sizeBytes") if isinstance(archive, dict) else artifact.get("sizeBytes")
        )
        if not oci_image and (
            not _valid_digest(artifact_sha256)
            or not isinstance(artifact_size, int)
            or isinstance(artifact_size, bool)
            or artifact_size < 1
            or artifact_size > MAX_SAFE_INTEGER
        ):
            raise UpdateError(
                "INVALID_MANIFEST",
                f"Artifact digest/size is invalid for {component['componentId']}.",
            )
        if artifact["kind"] == "native-binary":
            if (
                not isinstance(artifact.get("entrypoint"), str)
                or not isinstance(artifact.get("files"), dict)
                or not artifact["files"]
            ):
                raise UpdateError(
                    "INVALID_MANIFEST",
                    f"Native artifact payload map is invalid for {component['componentId']}.",
                )
            _native_executable_files(artifact)
        elif artifact["kind"] in {"python-bundle", "data-bundle", "static-web"}:
            if (
                artifact.get("format") not in {"tar.gz", "tar.zst", "zip"}
                or not isinstance(artifact.get("files"), dict)
                or not artifact["files"]
                or (artifact["kind"] == "data-bundle" and schema_version != 2)
                or (artifact["kind"] == "static-web" and artifact.get("entrypoint") != "index.html")
                or (
                    artifact["kind"] == "static-web"
                    and ("index.html" not in artifact["files"] or schema_version != 2)
                )
                or (
                    artifact["kind"] == "static-web"
                    and (
                        type(artifact.get("maxEntries")) is not int
                        or not 1 <= artifact["maxEntries"] <= 100_000
                        or type(artifact.get("maxUncompressedBytes")) is not int
                        or not 1 <= artifact["maxUncompressedBytes"] <= 4_294_967_296
                    )
                )
            ):
                raise UpdateError(
                    "INVALID_MANIFEST",
                    f"Bundle payload map is invalid for {component['componentId']}.",
                )
            for name, file_digest in artifact["files"].items():
                _safe_relative(name, field="artifact.files path")
                if not _valid_digest(file_digest):
                    raise UpdateError(
                        "INVALID_MANIFEST",
                        f"Python bundle file digest is invalid for {component['componentId']}.",
                    )
        elif plugin_package:
            if schema_version != 2 or not isinstance(archive, dict):
                raise UpdateError(
                    "INVALID_MANIFEST",
                    f"Plugin package archive metadata is invalid for {component['componentId']}.",
                )
            if (
                archive.get("format") != "zip"
                or not isinstance(archive.get("files"), dict)
                or not archive["files"]
                or type(archive.get("maxEntries")) is not int
                or not 1 <= archive["maxEntries"] <= 100_000
                or type(archive.get("maxUncompressedBytes")) is not int
                or not 1 <= archive["maxUncompressedBytes"] <= 4_294_967_296
                or not isinstance(artifact.get("packageId"), str)
                or not re.fullmatch(
                    r"[a-z][a-z0-9-]*(?:\.[a-z][a-z0-9-]*){1,7}", artifact["packageId"]
                )
                or not isinstance(artifact.get("capabilityId"), str)
                or not re.fullmatch(
                    r"[a-z][a-z0-9-]*(?:\.[a-z][a-z0-9-]*){1,7}", artifact["capabilityId"]
                )
                or not isinstance(artifact.get("interfaceVersion"), str)
                or VERSION_PATTERN.fullmatch(artifact["interfaceVersion"]) is None
                or not isinstance(artifact.get("preparerWheels"), list)
                or not artifact["preparerWheels"]
            ):
                raise UpdateError(
                    "INVALID_MANIFEST",
                    f"Plugin package contract is invalid for {component['componentId']}.",
                )
            asset_references = [
                artifact.get("descriptor"),
                artifact.get("requirementsLock"),
                artifact.get("packageReleaseMetadata"),
                *artifact["preparerWheels"],
            ]
            for reference in asset_references:
                if (
                    not isinstance(reference, dict)
                    or set(reference) != {"uri", "sha256", "sizeBytes"}
                    or not isinstance(reference.get("uri"), str)
                    or not _valid_digest(reference.get("sha256"))
                    or type(reference.get("sizeBytes")) is not int
                    or not 1 <= reference["sizeBytes"] <= MAX_SAFE_INTEGER
                ):
                    raise UpdateError(
                        "INVALID_MANIFEST",
                        f"Plugin package asset reference is invalid for {component['componentId']}.",
                    )
                self._require_github_asset_uri(reference["uri"], publisher["repository"])
            self._require_github_asset_uri(archive.get("uri"), publisher["repository"])
            for name, file_digest in archive["files"].items():
                _safe_relative(name, field="plugin package archive.files path")
                if not _valid_digest(file_digest):
                    raise UpdateError(
                        "INVALID_MANIFEST",
                        f"Plugin archive file digest is invalid for {component['componentId']}.",
                    )
        artifact_uri = artifact.get("uri")
        if plugin_package:
            artifact_uri = archive.get("uri") if isinstance(archive, dict) else None
        subject_name = manifest.get("provenance", {}).get("attestation", {}).get("subjectName")
        if oci_image:
            if subject_name != artifact.get("repository"):
                raise UpdateError(
                    "UNTRUSTED_ATTESTATION_SUBJECT",
                    "Echo OCI provenance subject differs from the exact image repository.",
                )
        else:
            if not isinstance(artifact_uri, str):
                raise UpdateError(
                    "INVALID_MANIFEST",
                    f"Artifact download URI is missing for {component['componentId']}.",
                )
            self._require_github_asset_uri(artifact_uri, publisher["repository"])
            if subject_name != PurePosixPath(urllib.parse.urlsplit(artifact_uri).path).name:
                raise UpdateError(
                    "UNTRUSTED_ATTESTATION_SUBJECT",
                    f"Attestation subject differs from artifact basename for {component['componentId']}.",
                )
        restart = manifest.get("restart")
        expected_restart = component.get("restart", {})
        if (
            not isinstance(restart, dict)
            or restart.get("group") != expected_restart.get("group")
            or restart.get("unit", expected_restart.get("unit")) != expected_restart.get("unit")
        ):
            raise UpdateError(
                "RESTART_POLICY_MISMATCH",
                f"Manifest restart policy differs from the trusted catalog for {component['componentId']}.",
            )

    def _validate_manifest_dependencies(
        self, value: Any, component: dict[str, Any], *, require_version_range: bool = False
    ) -> None:
        """Require publisher dependencies to match the trusted component catalog exactly."""

        if not isinstance(value, list):
            raise UpdateError(
                "INVALID_MANIFEST_DEPENDENCIES",
                f"{component['componentId']} dependencies must be a list.",
            )
        trusted = component.get("dependencies", [])
        if not isinstance(trusted, list):
            raise UpdateError(
                "INVALID_CATALOG",
                f"Trusted dependencies are malformed for {component['componentId']}.",
            )

        def normalize(items: list[Any], *, source: str) -> list[dict[str, str]]:
            normalized: list[dict[str, str]] = []
            seen: set[str] = set()
            for item in items:
                expected_shapes = (
                    ({"componentId", "versionRange"},)
                    if require_version_range
                    else ({"componentId"}, {"componentId", "versionRange"})
                )
                if not isinstance(item, dict) or set(item) not in expected_shapes:
                    raise UpdateError(
                        "INVALID_MANIFEST_DEPENDENCIES",
                        f"{source} dependency record is malformed for {component['componentId']}.",
                    )
                dependency_id = item.get("componentId")
                if (
                    not isinstance(dependency_id, str)
                    or dependency_id not in self.components
                    or dependency_id in seen
                ):
                    raise UpdateError(
                        "INVALID_MANIFEST_DEPENDENCIES",
                        f"{source} references an unknown or duplicate dependency for {component['componentId']}.",
                    )
                seen.add(dependency_id)
                row = {"componentId": dependency_id}
                if "versionRange" in item:
                    if not isinstance(item["versionRange"], str) or not item["versionRange"]:
                        raise UpdateError(
                            "DEPENDENCY_RANGE_UNSUPPORTED",
                            f"{source} dependency range is empty for {component['componentId']}.",
                        )
                    _parse_supported_version_range(item["versionRange"])
                    row["versionRange"] = item["versionRange"]
                normalized.append(row)
            return sorted(normalized, key=lambda row: row["componentId"])

        if normalize(value, source="Manifest") != normalize(trusted, source="Catalog"):
            raise UpdateError(
                "DEPENDENCY_CATALOG_MISMATCH",
                f"Published dependencies differ from trusted catalog for {component['componentId']}.",
            )

    def _validate_runtime_dependencies(self, candidates: dict[str, Candidate]) -> None:
        """Check ranged runtime dependencies against installed or same-plan versions."""

        for component_id, candidate in candidates.items():
            for dependency in candidate.component.get("dependencies", []):
                version_range = (
                    dependency.get("versionRange") if isinstance(dependency, dict) else None
                )
                if version_range is None:
                    continue
                dependency_id = dependency["componentId"]
                dependency_component = self.components.get(dependency_id)
                if dependency_component is None:
                    raise UpdateError(
                        "INVALID_CATALOG",
                        f"Unknown trusted dependency {dependency_id!r} for {component_id}.",
                    )
                _parse_supported_version_range(version_range)
                if dependency_component.get("role") == "build-dependency":
                    continue
                planned = candidates.get(dependency_id)
                if planned is not None:
                    dependency_version = planned.manifest.get("version")
                else:
                    installed = self._installed(dependency_component)
                    dependency_version = installed.get("activeVersion")
                if dependency_version is None:
                    raise UpdateError(
                        "DEPENDENCY_NOT_INSTALLED",
                        f"{component_id} requires {dependency_id} {version_range}; install or include that component in the checked plan first.",
                    )
                if not _version_satisfies(dependency_version, version_range):
                    raise UpdateError(
                        "DEPENDENCY_VERSION_UNSATISFIED",
                        f"{component_id} requires {dependency_id} {version_range}, but the installed/planned version is {dependency_version}.",
                    )

    def _load_component_placement(self) -> Any:
        """Load the signed updater's role-placement verifier from its fixed sibling path."""

        module_path = Path(__file__).with_name("component_placement.py")
        if module_path.is_symlink() or not module_path.is_file():
            raise UpdateError(
                "PLACEMENT_HELPER_UNAVAILABLE",
                "The signed component placement verifier is missing or unsafe.",
            )
        import importlib.util

        module_name = "_cyrene_component_placement"
        spec = importlib.util.spec_from_file_location(module_name, module_path)
        if spec is None or spec.loader is None:
            raise UpdateError(
                "PLACEMENT_HELPER_UNAVAILABLE",
                "The signed component placement verifier cannot be loaded.",
            )
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        try:
            spec.loader.exec_module(module)
        except Exception as error:
            raise UpdateError(
                "PLACEMENT_HELPER_UNAVAILABLE",
                "The signed component placement verifier failed to load.",
            ) from error
        return module

    def _placement_module_for_group(self, group: dict[str, Any]) -> Any | None:
        if "deploymentRoles" not in group:
            return None
        module = self._load_component_placement()
        try:
            context = module.load_placement(
                group,
                trusted_catalog_digest=self.catalog_digest,
            )
        except Exception as error:
            raise UpdateError("PLACEMENT_INVALID", f"Host placement is invalid: {error}") from error
        return (module, context) if context is not None else None

    def _default_placement_selection(self) -> list[str]:
        """Keep default checks local to each configured deployment role."""

        selected = list(self.components)
        groups = self.catalog.get("compatibilityGroups", [])
        for group in groups:
            if not isinstance(group, dict) or "deploymentRoles" not in group:
                continue
            loaded = self._placement_module_for_group(group)
            if loaded is None:
                continue
            module, context = loaded
            member_ids = {
                member["componentId"]
                for member in group.get("members", [])
                if isinstance(member, dict) and isinstance(member.get("componentId"), str)
            }
            supported_ids = {
                component_id
                for component_id in member_ids
                if self._target_for(self.components[component_id]) is not None
            }
            active_ids = {
                component_id
                for component_id in member_ids
                if self._installed(self.components[component_id]).get("active") is True
            }
            try:
                selection = module.filter_group_members(
                    context,
                    group,
                    supported_ids,
                    active_ids,
                )
            except Exception as error:
                raise UpdateError(
                    "PLACEMENT_INVALID", f"Host placement is invalid: {error}"
                ) from error
            if selection is None:
                raise UpdateError("PLACEMENT_INVALID", "Host placement selection is unavailable.")
            selected = [component_id for component_id in selected if component_id not in member_ids]
            selected.extend(selection.component_ids)
        return list(dict.fromkeys(selected))

    def _validate_requested_placement(self, requested_ids: set[str]) -> None:
        """Reject explicit requests for a signed group member assigned to the peer."""

        for group in self.catalog.get("compatibilityGroups", []):
            if not isinstance(group, dict) or "deploymentRoles" not in group:
                continue
            member_ids = {
                member.get("componentId")
                for member in group.get("members", [])
                if isinstance(member, dict) and isinstance(member.get("componentId"), str)
            }
            group_requests = requested_ids & member_ids
            if not group_requests:
                continue
            loaded = self._placement_module_for_group(group)
            if loaded is None:
                continue
            module, context = loaded
            supported_ids = {
                component_id
                for component_id in member_ids
                if self._target_for(self.components[component_id]) is not None
            }
            active_ids = {
                component_id
                for component_id in member_ids
                if self._installed(self.components[component_id]).get("active") is True
            }
            try:
                module.filter_group_members(
                    context,
                    group,
                    supported_ids,
                    active_ids,
                    requested_ids=group_requests,
                )
            except Exception as error:
                raise UpdateError(
                    "PLACEMENT_INVALID", f"Requested member violates host placement: {error}"
                ) from error

    def _placement_bindings(
        self,
        candidates: dict[str, Candidate],
        *,
        operation: str,
    ) -> list[dict[str, Any]]:
        """Collect fresh, stable peer evidence for every role-enabled plan group."""

        candidate_ids = set(candidates)
        return self._placement_bindings_for_ids(
            candidate_ids,
            operation=operation,
            candidate_overrides=candidates,
            channel=next(
                (candidate.manifest.get("channel") for candidate in candidates.values()),
                self._resolve_channel(None),
            ),
        )

    def _placement_bindings_for_ids(
        self,
        component_ids: set[str],
        *,
        operation: str,
        candidate_overrides: dict[str, Candidate] | None = None,
        channel: str | None = None,
    ) -> list[dict[str, Any]]:
        group_catalogs = {
            item["groupId"]: item
            for item in self.catalog.get("compatibilityGroups", [])
            if isinstance(item, dict) and isinstance(item.get("groupId"), str)
        }
        groups: dict[str, dict[str, Any]] = {}
        for component_id in component_ids:
            component = self.components.get(component_id)
            group_id = component.get("compatibilityGroup") if isinstance(component, dict) else None
            group = group_catalogs.get(group_id)
            if isinstance(group, dict) and "deploymentRoles" in group:
                groups[group_id] = group

        bindings: list[dict[str, Any]] = []
        for group_id, group in sorted(groups.items()):
            loaded = self._placement_module_for_group(group)
            if loaded is None:
                continue
            module, context = loaded
            member_ids = {
                member["componentId"]
                for member in group.get("members", [])
                if isinstance(member, dict) and isinstance(member.get("componentId"), str)
            }
            local_supported_ids = {
                component_id
                for component_id in member_ids
                if self._target_for(self.components[component_id]) is not None
            }
            active_ids = {
                component_id
                for component_id in member_ids
                if self._installed(self.components[component_id]).get("active") is True
            }
            requested_ids = component_ids & member_ids
            try:
                selection = module.filter_group_members(
                    context,
                    group,
                    local_supported_ids,
                    active_ids,
                    requested_ids=requested_ids,
                )
                if selection is None:
                    raise ValueError("signed role selection is unavailable")
                if not requested_ids <= set(selection.component_ids):
                    raise ValueError("requested candidates are outside the local deployment role")
                local_desired = self._placement_desired_components(
                    group,
                    selection.component_ids,
                    local_role_id=context.role_id,
                    candidates=self._placement_candidate_map_for_channel(
                        component_ids,
                        channel=channel or self._resolve_channel(None),
                        overrides=candidate_overrides,
                    ),
                )
                peer_plan = module.fetch_peer_plan(context)
                _peer_candidates, required_service_units, executable_paths, executable_digests = (
                    self._verify_peer_placement_plan(context, peer_plan)
                )
                required_service_ids = frozenset(required_service_units)
                peer = module.fetch_peer_receipt(
                    context,
                    plan=peer_plan.payload,
                    required_service_ids=required_service_ids,
                    required_service_units=required_service_units,
                    required_service_executable_paths=executable_paths,
                    required_service_executable_digests=executable_digests,
                )
                if peer.stable_digest != peer_plan.stable_digest:
                    raise ValueError("peer desired targets changed between plan and receipt reads")
                module.authorize_peer_operation(context, peer, operation)
                binding = {
                    **module.plan_binding(context),
                    "localMembers": list(selection.component_ids),
                    "excludedOtherRoleMembers": list(selection.excluded_other_role_ids),
                    "localDesiredComponents": local_desired,
                    "peerHostId": context.peer.host_id,
                    "peerRoleId": context.peer.role_id,
                    "peerEvidenceDigest": peer.stable_digest,
                }
            except Exception as error:
                raise UpdateError(
                    "PLACEMENT_INVALID",
                    f"Trusted peer placement proof failed for {group_id}: {error}",
                    retryable=True,
                ) from error
            bindings.append(binding)
        return bindings

    def _placement_candidate_map(self, component_ids: set[str]) -> dict[str, Candidate]:
        """Recover verified candidates for this check or revalidation boundary."""

        return self._placement_candidate_map_for_channel(
            component_ids, channel=self._resolve_channel(None), overrides=None
        )

    def _placement_candidate_map_for_channel(
        self,
        component_ids: set[str],
        *,
        channel: str,
        overrides: dict[str, Candidate] | None,
    ) -> dict[str, Candidate]:
        """Recover candidates while preserving the operation's explicit channel."""

        result = {
            component_id: candidate
            for component_id, candidate in (overrides or {}).items()
            if component_id in component_ids
        }
        for component_id in component_ids:
            if component_id in result:
                continue
            component = self.components.get(component_id)
            if not isinstance(component, dict):
                continue
            target = self._target_for(component)
            if target is None:
                continue
            try:
                result[component_id] = self._candidate(component, target, channel)
            except UpdateError:
                # The caller's candidate map is authoritative for a plan. This method is
                # only a fallback for active members whose release is already installed.
                continue
        return result

    def _placement_desired_components(
        self,
        group: dict[str, Any],
        selected_ids: tuple[str, ...],
        *,
        local_role_id: str,
        candidates: dict[str, Candidate],
    ) -> list[dict[str, Any]]:
        """Bind the role's complete desired component identities into its plan."""

        desired: list[dict[str, Any]] = []
        role = next(
            (
                item
                for item in group.get("deploymentRoles", [])
                if isinstance(item, dict) and item.get("roleId") == local_role_id
            ),
            None,
        )
        required = set(role.get("requiredMembers", [])) if isinstance(role, dict) else set()
        for component_id in selected_ids:
            candidate = candidates.get(component_id)
            if candidate is not None:
                manifest = candidate.manifest
                target_id = self._manifest_target_id(candidate.component, manifest)
                source = manifest.get("source")
                channel = manifest.get("channel")
                if (
                    target_id is None
                    or candidate.release_tag is None
                    or not isinstance(source, dict)
                    or not isinstance(source.get("commit"), str)
                    or not isinstance(channel, str)
                ):
                    raise UpdateError(
                        "PLACEMENT_IDENTITY_UNKNOWN",
                        f"Verified candidate identity is incomplete for {component_id}.",
                    )
                desired.append(
                    {
                        "componentId": component_id,
                        "version": manifest["version"],
                        "manifestDigest": candidate.manifest_digest,
                        "artifactDigest": candidate.artifact_digest,
                        "targetId": target_id,
                        "releaseId": candidate.release_tag,
                        "sourceCommit": source["commit"],
                        "sourceRepository": candidate.component["publisher"],
                        "channel": channel,
                    }
                )
                continue

            component = self.components.get(component_id)
            installed = self._installed(component) if isinstance(component, dict) else None
            manifest = installed.get("manifest") if isinstance(installed, dict) else None
            source = manifest.get("source") if isinstance(manifest, dict) else None
            channel = manifest.get("channel") if isinstance(manifest, dict) else None
            if (
                not isinstance(component, dict)
                or installed.get("active") is not True
                or installed.get("identityAttested") is not True
                or not isinstance(manifest, dict)
                or not isinstance(source, dict)
                or not isinstance(source.get("commit"), str)
                or channel not in {"stable", "preview"}
            ):
                if component_id in required:
                    raise UpdateError(
                        "PLACEMENT_IDENTITY_UNKNOWN",
                        f"Required component {component_id} has no verified active or planned identity.",
                        retryable=True,
                    )
                continue
            target_id = self._manifest_target_id(component, manifest)
            release_id = self._component_release_tag_prefix(component, channel) or (
                "preview-" if channel == "preview" else "stable-"
            )
            release_id += source["commit"]
            desired.append(
                {
                    "componentId": component_id,
                    "version": manifest["version"],
                    "manifestDigest": installed["manifestDigest"],
                    "artifactDigest": installed["artifactDigest"],
                    "targetId": target_id,
                    "releaseId": release_id,
                    "sourceCommit": source["commit"],
                    "sourceRepository": component["publisher"],
                    "channel": channel,
                }
            )
        return sorted(desired, key=lambda item: item["componentId"])

    def _manifest_target_id(
        self, component: dict[str, Any], manifest: dict[str, Any]
    ) -> str | None:
        """Resolve a manifest's target only through its signed catalog component mapping."""

        artifact = manifest.get("artifact")
        if not isinstance(artifact, dict):
            return None
        matches = [
            target_entry.get("targetId")
            for target_entry in component.get("targets", [])
            if isinstance(target_entry, dict)
            and target_entry.get("support") == "supported"
            and target_entry.get("artifactKind") == artifact.get("kind")
            and isinstance(self.targets.get(target_entry.get("targetId")), dict)
            and self.targets[target_entry["targetId"]].get("target") == manifest.get("target")
        ]
        return matches[0] if len(matches) == 1 else None

    def _verify_peer_placement_plan(
        self, context: Any, peer_plan: Any
    ) -> tuple[dict[str, Candidate], dict[str, str], dict[str, str], dict[str, str]]:
        """Verify every peer target against the trusted catalog and immutable release."""

        payload = peer_plan.payload
        desired = payload.get("desiredComponents")
        if not isinstance(desired, list):
            raise UpdateError("PLACEMENT_INVALID", "Peer target list is malformed.")
        candidates: dict[str, Candidate] = {}
        for item in desired:
            if not isinstance(item, dict):
                raise UpdateError("PLACEMENT_INVALID", "Peer target identity is malformed.")
            component_id = item.get("componentId")
            target_id = item.get("targetId")
            channel = item.get("channel")
            component = self.components.get(component_id)
            target = self.targets.get(target_id)
            if (
                not isinstance(component, dict)
                or component_id not in context.peer_role.allowed_members
                or not isinstance(target, dict)
                or channel not in {"stable", "preview"}
                or not any(
                    isinstance(entry, dict)
                    and entry.get("targetId") == target_id
                    and entry.get("support") == "supported"
                    for entry in component.get("targets", [])
                )
            ):
                raise UpdateError(
                    "PLACEMENT_INVALID", "Peer target is outside the signed catalog mapping."
                )
            candidate = self._candidate(
                component, target, channel, release_id=item.get("releaseId")
            )
            source = candidate.manifest.get("source")
            if (
                candidate.release_tag != item.get("releaseId")
                or candidate.manifest.get("version") != item.get("version")
                or candidate.manifest_digest != item.get("manifestDigest")
                or candidate.artifact_digest != item.get("artifactDigest")
                or candidate.component.get("publisher") != item.get("sourceRepository")
                or not isinstance(source, dict)
                or source.get("commit") != item.get("sourceCommit")
                or candidate.manifest.get("channel") != channel
                or self._manifest_target_id(component, candidate.manifest) != target_id
            ):
                raise UpdateError(
                    "PLACEMENT_RELEASE_MISMATCH",
                    f"Peer target differs from its independently verified release: {component_id}.",
                )
            candidates[component_id] = candidate

        required_units: dict[str, str] = {}
        executable_paths: dict[str, str] = {}
        executable_digests: dict[str, str] = {}
        desired_ids = set(candidates)
        required_ids = context.peer_role.required_members & desired_ids
        if desired and context.peer_role.required_members - desired_ids:
            raise UpdateError("PLACEMENT_INVALID", "Peer plan omits required role members.")
        for component_id in sorted(desired_ids):
            candidate = candidates[component_id]
            component = candidate.component
            if component.get("kind") == "data-bundle":
                continue
            unit = component.get("systemdUnit")
            artifact = candidate.manifest.get("artifact")
            entrypoint = artifact.get("entrypoint") if isinstance(artifact, dict) else None
            files = artifact.get("files") if isinstance(artifact, dict) else None
            if (
                not isinstance(unit, str)
                or not unit.endswith(".service")
                or not isinstance(entrypoint, str)
                or not isinstance(files, dict)
                or not _valid_digest(files.get(entrypoint))
                or artifact.get("kind") != "native-binary"
            ):
                raise UpdateError(
                    "PLACEMENT_SERVICE_IDENTITY_UNKNOWN",
                    f"Required peer service has no signed executable identity: {component_id}.",
                )
            path_parts = _safe_relative(entrypoint, field="peer executable entrypoint")
            release_identity = (
                f"{candidate.manifest['version']}--"
                f"{candidate.manifest_digest.removeprefix('sha256:')}"
            )
            executable_path = (
                self.install_root / "components" / component_id / "releases" / release_identity
            ).joinpath(*path_parts.parts)
            required_units[component_id] = unit
            executable_paths[component_id] = str(executable_path)
            executable_digests[component_id] = files[entrypoint]
        if not required_ids <= set(required_units):
            raise UpdateError(
                "PLACEMENT_SERVICE_IDENTITY_UNKNOWN",
                "A required peer service has no signed executable identity.",
            )
        return candidates, required_units, executable_paths, executable_digests

    def _revalidate_plan_placement(
        self,
        plan: dict[str, Any],
        *,
        operation: str,
    ) -> None:
        """Require current host config and peer evidence to match the immutable plan."""

        component_ids = {
            item.get("componentId")
            for item in plan.get("components", [])
            if isinstance(item, dict) and isinstance(item.get("componentId"), str)
        }
        current = self._placement_bindings_for_ids(
            component_ids,
            operation=operation,
            channel=plan.get("channel") if plan.get("channel") in {"stable", "preview"} else None,
        )
        expected = plan.get("deploymentPlacement", [])
        if not isinstance(expected, list) or current != expected:
            raise UpdateError(
                "PLACEMENT_CHANGED",
                "Host placement or peer state changed after this plan was checked; check again.",
                retryable=True,
            )

    def _expand_compatibility_groups(
        self, candidates: dict[str, Candidate], channel: str
    ) -> dict[str, Candidate]:
        expanded = dict(candidates)
        group_catalogs = {
            item["groupId"]: item
            for item in self.catalog.get("compatibilityGroups", [])
            if isinstance(item, dict)
        }
        for candidate in list(candidates.values()):
            compatibility = candidate.manifest.get("compatibility")
            if compatibility is None:
                if candidate.component.get("compatibilityGroup"):
                    raise UpdateError(
                        "COMPATIBILITY_MISSING",
                        f"{candidate.component['componentId']} release omits its trusted compatibility pins.",
                    )
                continue
            group_id = compatibility.get("groupId")
            group = group_catalogs.get(group_id)
            if group is None or candidate.component.get("compatibilityGroup") != group_id:
                raise UpdateError(
                    "COMPATIBILITY_UNTRUSTED", f"Unknown compatibility group {group_id!r}."
                )
            if (
                compatibility.get("wireApiVersion") != group.get("wireApiVersion")
                or compatibility.get("contractApiVersion") != group.get("contractApiVersion")
                or (
                    candidate.manifest.get("schemaVersion") == 2
                    and compatibility.get("groupVersion") != group.get("groupVersion")
                )
            ):
                raise UpdateError(
                    "COMPATIBILITY_API_UNSUPPORTED",
                    f"No client support is pinned for {group_id} compatibility API.",
                )
            if candidate.manifest.get("schemaVersion") == 2:
                trusted_lock = group.get("contractLock")
                if (
                    not _trusted_contract_lock(trusted_lock)
                    or compatibility.get("contractLock") != trusted_lock
                ):
                    raise UpdateError(
                        "COMPATIBILITY_LOCK_UNTRUSTED",
                        f"{group_id} does not match its exact trusted protocol lock.",
                    )
            current_members: list[tuple[dict[str, Any], dict[str, Any]]] = []
            adoption_needed = False
            candidate_pin = (
                group.get("contractLock")
                if candidate.manifest.get("schemaVersion") == 2
                else compatibility["contractLock"]
            )
            members = group["members"]
            member_protocol_versions = {
                member["componentId"]: member.get("protocolVersion") for member in members
            }
            placement = self._placement_module_for_group(group)
            placement_module = placement[0] if placement is not None else None
            placement_context = placement[1] if placement is not None else None
            placement_selection = None
            if placement_context is not None:
                member_ids = {member["componentId"] for member in members}
                local_supported_ids = {
                    component_id
                    for component_id in member_ids
                    if self._target_for(self.components[component_id]) is not None
                }
                active_ids = {
                    component_id
                    for component_id in member_ids
                    if self._installed(self.components[component_id]).get("active") is True
                }
                placement_selection = placement_module.filter_group_members(
                    placement_context,
                    group,
                    local_supported_ids,
                    active_ids,
                    requested_ids=set(expanded),
                )
                if placement_selection is None:
                    raise UpdateError(
                        "PLACEMENT_INVALID", "Signed deployment role selection is unavailable."
                    )
                selected_members = set(placement_selection.component_ids)
            else:
                selected_members = None
            for member in members:
                if selected_members is not None and member["componentId"] not in selected_members:
                    continue
                member_component = self.components[member["componentId"]]
                member_target = self._target_for(member_component)
                if member_target is None:
                    if member.get("requiredForAdoption"):
                        raise UpdateError(
                            "COMPATIBILITY_MEMBER_UNSUPPORTED",
                            f"Required {group_id} member {member['componentId']} has no supported target.",
                        )
                    continue
                installed = self._installed(member_component)
                if not installed["active"]:
                    if member.get("requiredForAdoption"):
                        adoption_needed = True
                    continue
                installed_compat = (installed.get("manifest") or {}).get("compatibility")
                if (
                    (installed.get("manifest") or {}).get("schemaVersion")
                    != candidate.manifest.get("schemaVersion")
                    or not isinstance(installed_compat, dict)
                    or (
                        installed_compat.get("groupId") != group_id
                        or installed_compat.get("contractApiVersion")
                        != compatibility["contractApiVersion"]
                        or installed_compat.get("wireApiVersion") != compatibility["wireApiVersion"]
                        or (
                            candidate.manifest.get("schemaVersion") == 2
                            and installed_compat.get("groupVersion")
                            != compatibility.get("groupVersion")
                        )
                        or (
                            installed_compat.get("contractLock") != candidate_pin
                            if candidate.manifest.get("schemaVersion") == 2
                            else installed_compat.get("contractLock", {}).get("sha256")
                            != candidate_pin.get("sha256")
                        )
                    )
                ):
                    adoption_needed = True
                current_members.append((member_component, member_target))
            if not adoption_needed:
                continue

            required_ids = (
                set(placement_selection.component_ids)
                if placement_selection is not None
                else {
                    member["componentId"]
                    for member in members
                    if member.get("requiredForAdoption")
                    or self.components.get(member["componentId"], {}).get("kind") == "data-bundle"
                }
            )
            required_ids = {
                component_id
                for component_id in required_ids
                if self._target_for(self.components[component_id]) is not None
            }
            include_ids = required_ids | {
                component["componentId"] for component, _ in current_members
            }
            for component_id in sorted(include_ids):
                member_component = self.components[component_id]
                member_target = self._target_for(member_component)
                if member_target is None:
                    raise UpdateError(
                        "COMPATIBILITY_MEMBER_UNSUPPORTED",
                        f"Required {group_id} member {component_id} has no supported target.",
                    )
                if component_id not in expanded:
                    # Compatibility groups may span repositories. Resolve each
                    # member through its own trusted publisher and attested index.
                    expanded[component_id] = self._candidate(
                        member_component, member_target, channel
                    )
                member_candidate = expanded[component_id]
                member_compat = member_candidate.manifest.get("compatibility")
                if (
                    not isinstance(member_compat, dict)
                    or member_compat.get("groupId") != group_id
                    or member_compat.get("contractApiVersion")
                    != compatibility["contractApiVersion"]
                    or member_compat.get("wireApiVersion") != compatibility["wireApiVersion"]
                    or member_compat.get("contractLock") != candidate_pin
                    or member_candidate.manifest.get("schemaVersion")
                    != candidate.manifest.get("schemaVersion")
                    or (
                        member_candidate.manifest.get("schemaVersion") == 2
                        and (
                            member_compat.get("groupVersion") != group.get("groupVersion")
                            or member_candidate.manifest.get("protocolVersion")
                            != member_protocol_versions.get(component_id)
                        )
                    )
                ):
                    raise UpdateError(
                        "COMPATIBILITY_GROUP_MISMATCH",
                        f"Member {component_id} does not share the exact {group_id} contract pins.",
                    )
        return expanded

    def _resolve_plan_candidates(self, plan: dict[str, Any], channel: str) -> dict[str, Candidate]:
        component_ids = [item["componentId"] for item in plan["components"]]
        candidates: dict[str, Candidate] = {}
        for component_id in component_ids:
            component = self.components[component_id]
            target = self._target_for(component)
            if target is None:
                raise UpdateError(
                    "UNSUPPORTED_TARGET",
                    f"Component {component_id} is no longer supported on this host.",
                )
            candidates[component_id] = self._candidate(component, target, channel)
        candidates = self._expand_compatibility_groups(candidates, channel)
        selected = {key: value for key, value in candidates.items() if key in set(component_ids)}
        rebuilt_components = [
            {
                "componentId": key,
                "version": item.manifest["version"],
                "manifestDigest": item.manifest_digest,
                "artifactDigest": item.manifest["artifact"].get(
                    "digest", item.manifest["artifact"].get("sha256")
                ),
                "restartGroup": item.component["restart"]["group"],
            }
            for key, item in sorted(selected.items())
        ]
        material = {
            "schemaVersion": 1,
            "channel": channel,
            "catalogGeneration": plan.get("catalogGeneration"),
            "catalogDigest": plan.get("catalogDigest"),
            "components": rebuilt_components,
        }
        if "deploymentPlacement" in plan:
            material["deploymentPlacement"] = plan["deploymentPlacement"]
        if "sha256:" + hashlib.sha256(canonical_jcs(material)).hexdigest() != plan["planDigest"]:
            raise UpdateError(
                "PLAN_CHANGED",
                "Trusted release inputs changed since check; run check again.",
                retryable=True,
            )
        return selected

    def _validate_data_bundle_proof(
        self, candidate: Candidate, payload_root: Path, channel: str
    ) -> dict[str, Any]:
        """Verify every immutable source subject and its detached SLSA bundle."""
        manifest = candidate.manifest
        envelope = manifest.get("dataBundle")
        trust = self.catalog.get("dataBundleTrust")
        if (
            not isinstance(envelope, dict)
            or set(envelope) != {"proofPath", "proofSha256"}
            or envelope.get("proofPath") != "data-bundle-proof-v1.json"
            or not _valid_digest(envelope.get("proofSha256"))
            or not isinstance(trust, dict)
        ):
            raise UpdateError("INVALID_DATA_BUNDLE_PROOF", "Data-bundle proof envelope is invalid.")
        proof_path = payload_root.joinpath(
            *_safe_relative(envelope["proofPath"], field="dataBundle.proofPath").parts
        )
        if proof_path.is_symlink() or not proof_path.is_file():
            raise UpdateError(
                "INVALID_DATA_BUNDLE_PROOF",
                "The fixed data-bundle proof file is missing or unsafe.",
            )
        proof_bytes = proof_path.read_bytes()
        proof_digest = "sha256:" + hashlib.sha256(proof_bytes).hexdigest()
        if proof_digest != envelope["proofSha256"]:
            raise UpdateError(
                "DATA_BUNDLE_PROOF_DIGEST_MISMATCH", "Data-bundle proof digest is invalid."
            )
        try:
            proof = json.loads(proof_bytes.decode("utf-8"), object_pairs_hook=_unique_json_object)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_DATA_BUNDLE_PROOF", "Data-bundle proof is not valid UTF-8 JSON."
            ) from error
        expected_proof_fields = {
            "schemaVersion",
            "protocolVersion",
            "contractApiVersion",
            "manifestPath",
            "manifestSha256",
            "policyPath",
            "policySha256",
            "policySchemaVersion",
            "owners",
            "policySource",
        }
        if (
            not isinstance(proof, dict)
            or set(proof) != expected_proof_fields
            or isinstance(proof.get("schemaVersion"), bool)
            or proof.get("schemaVersion") != 1
            or proof.get("protocolVersion") != trust.get("protocolVersion")
            or proof.get("protocolVersion") != manifest.get("protocolVersion")
            or proof.get("contractApiVersion") != trust.get("contractApiVersion")
            or proof.get("manifestPath") != trust.get("manifestPath")
        ):
            raise UpdateError(
                "INVALID_DATA_BUNDLE_PROOF", "Data-bundle proof identity or shape is invalid."
            )

        def read_subject(relative: Any, digest: Any, *, label: str) -> bytes:
            path = payload_root.joinpath(*_safe_relative(relative, field=label).parts)
            if path.is_symlink() or not path.is_file() or not _valid_digest(digest):
                raise UpdateError("INVALID_DATA_BUNDLE_PROOF", f"{label} is missing or unsafe.")
            data = path.read_bytes()
            if "sha256:" + hashlib.sha256(data).hexdigest() != digest:
                raise UpdateError(
                    "DATA_BUNDLE_SOURCE_DIGEST_MISMATCH", f"{label} digest is invalid."
                )
            return data

        manifest_bytes = read_subject(
            proof.get("manifestPath"), proof.get("manifestSha256"), label="data bundle manifest"
        )
        try:
            manifest_value = json.loads(manifest_bytes.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_DATA_BUNDLE_PROOF", "The inner bundle manifest is invalid JSON."
            ) from error
        if not isinstance(manifest_value, dict):
            raise UpdateError(
                "INVALID_DATA_BUNDLE_PROOF", "The inner bundle manifest must be an object."
            )
        if manifest_value.get("formatVersion") != 2 or manifest_value.get(
            "wireApiVersion"
        ) != proof.get("protocolVersion"):
            raise UpdateError(
                "DATA_BUNDLE_MANIFEST_MISMATCH",
                "Inner contract-bundle manifest does not bind the declared Product wire protocol.",
            )

        policy_trust = trust.get("policySource")
        policy_source = proof.get("policySource")
        if (
            not isinstance(policy_trust, dict)
            or not isinstance(policy_source, dict)
            or set(policy_source) != {"source", "path", "sha256", "provenance"}
            or policy_source.get("path") != policy_trust.get("path")
            or policy_source.get("sha256") != proof.get("policySha256")
            or proof.get("policyPath") != "workspace-product-policy-v2.json"
            or proof.get("policySchemaVersion") != policy_trust.get("schemaVersion")
        ):
            raise UpdateError(
                "UNTRUSTED_POLICY_SOURCE",
                "Data-bundle policy source differs from the trusted Platform policy.",
            )
        policy_source_identity = policy_source.get("source")
        if (
            not isinstance(policy_source_identity, dict)
            or set(policy_source_identity) != {"repository", "ref", "commit"}
            or policy_source_identity.get("repository") != policy_trust.get("repository")
        ):
            raise UpdateError(
                "UNTRUSTED_POLICY_SOURCE", "Data-bundle policy source identity is not trusted."
            )
        policy_payload = read_subject(
            proof.get("policyPath"), proof.get("policySha256"), label="policy file"
        )
        try:
            policy_value = json.loads(policy_payload.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_POLICY", "Bundled workspace policy is not valid UTF-8 JSON."
            ) from error
        if not isinstance(policy_value, dict) or policy_value.get("schemaVersion") != proof.get(
            "policySchemaVersion"
        ):
            raise UpdateError(
                "INVALID_POLICY",
                "Bundled policy schema version differs from its trusted proof pin.",
            )
        owners = proof.get("owners")
        owner_trust = trust.get("owners")
        if not isinstance(owners, list) or not isinstance(owner_trust, list):
            raise UpdateError("INVALID_DATA_BUNDLE_PROOF", "Data-bundle owner list is invalid.")
        trusted_owners = {
            item.get("ownerId"): item for item in owner_trust if isinstance(item, dict)
        }
        owner_ids = [item.get("ownerId") for item in owners if isinstance(item, dict)]
        if (
            len(owner_ids) != len(owners)
            or len(set(owner_ids)) != len(owner_ids)
            or set(owner_ids) != set(trusted_owners)
        ):
            raise UpdateError(
                "DATA_BUNDLE_OWNERS_MISMATCH",
                "Proof does not contain each trusted owner exactly once.",
            )
        for owner in owners:
            expected_owner = trusted_owners[owner["ownerId"]]
            if (
                set(owner) != {"ownerId", "source", "catalogPath", "catalogSha256", "provenance"}
                or owner.get("catalogPath")
                != f"{expected_owner.get('repository')}/{expected_owner.get('catalogPath')}"
            ):
                raise UpdateError(
                    "DATA_BUNDLE_OWNER_MISMATCH",
                    f"Owner {owner['ownerId']} does not match trusted catalog identity.",
                )
            source = owner.get("source")
            if (
                not isinstance(source, dict)
                or set(source) != {"repository", "ref", "commit"}
                or source.get("repository") != expected_owner.get("repository")
            ):
                raise UpdateError(
                    "DATA_BUNDLE_OWNER_MISMATCH",
                    f"Owner {owner['ownerId']} source identity is not trusted.",
                )
            subject = read_subject(
                owner.get("catalogPath"),
                owner.get("catalogSha256"),
                label=f"owner {owner['ownerId']} catalog",
            )
            self._verify_data_bundle_subject(
                payload_root,
                subject,
                owner,
                label=f"owner {owner['ownerId']} catalog",
                channel=channel,
                expected_subject_path=(
                    expected_owner["repository"] + "/" + expected_owner["catalogPath"]
                ),
                expected_workflow=(
                    expected_owner["repository"] + PRODUCT_CONTRACT_ATTESTATION_WORKFLOW
                ),
            )
        self._validate_inner_bundle_files(
            manifest_value, proof, payload_root, policy_source, trusted_owners
        )
        self._verify_data_bundle_subject(
            payload_root,
            policy_payload,
            policy_source,
            label="policy source",
            channel=channel,
            expected_subject_path=(policy_trust["repository"] + "/" + policy_trust["path"]),
            expected_workflow=(policy_trust["repository"] + PRODUCT_POLICY_ATTESTATION_WORKFLOW),
        )
        return proof

    def _validate_inner_bundle_files(
        self,
        manifest: dict[str, Any],
        proof: dict[str, Any],
        payload_root: Path,
        policy_source: dict[str, Any],
        trusted_owners: dict[str, dict[str, Any]],
    ) -> None:
        """Bind Platform's short local bundle paths to trusted canonical sources.

        The Platform bundle format uses each checkout directory name as its
        inner repository/path prefix. Outer provenance remains fully qualified
        and is validated before this projection is checked.
        中文：仅将可信完整仓库名映射到包内短目录名，不改变外层来源证明。
        """

        proof_owners = {owner["ownerId"]: owner for owner in proof["owners"]}
        manifest_owners = manifest.get("owners")
        files = manifest.get("files")
        if not isinstance(manifest_owners, list) or not isinstance(files, list):
            raise UpdateError(
                "INVALID_DATA_BUNDLE_MANIFEST",
                "Inner bundle manifest owner/file lists are missing.",
            )
        seen_owners: set[str] = set()
        expected_files: dict[str, str] = {}
        for owner in manifest_owners:
            fields = {"ownerId", "repository", "sourceSha", "catalogPath", "catalogSha256"}
            if not isinstance(owner, dict) or set(owner) != fields:
                raise UpdateError(
                    "INVALID_DATA_BUNDLE_MANIFEST", "Inner bundle owner entry has an invalid shape."
                )
            owner_id = owner["ownerId"]
            if not isinstance(owner_id, str):
                raise UpdateError(
                    "INVALID_DATA_BUNDLE_MANIFEST", "Inner bundle owner identifier is invalid."
                )
            proof_owner = proof_owners.get(owner_id)
            trusted = trusted_owners.get(owner_id)
            trusted_repository = trusted.get("repository") if trusted else None
            trusted_catalog_path = trusted.get("catalogPath") if trusted else None
            repository_parts = (
                trusted_repository.split("/") if isinstance(trusted_repository, str) else []
            )
            if (
                len(repository_parts) != 2
                or repository_parts[0] != "DoHorizon-AI"
                or not repository_parts[1].startswith("Cyrene-")
                or trusted_catalog_path != "contracts/product/v2/catalog.json"
            ):
                raise UpdateError(
                    "DATA_BUNDLE_OWNER_MISMATCH",
                    f"Owner {owner_id!r} trusted source identity is invalid.",
                )
            local_repository = repository_parts[1]
            catalog_path = f"{local_repository}/{trusted_catalog_path}"
            if (
                owner_id in seen_owners
                or proof_owner is None
                or trusted is None
                or owner.get("repository") != local_repository
                or owner.get("sourceSha") != proof_owner["source"]["commit"]
                or owner.get("catalogPath") != catalog_path
                or owner.get("catalogSha256")
                != proof_owner["catalogSha256"].removeprefix("sha256:")
            ):
                raise UpdateError(
                    "DATA_BUNDLE_MANIFEST_MISMATCH",
                    f"Inner bundle owner {owner_id!r} differs from its verified proof.",
                )
            seen_owners.add(owner_id)
            expected_files[catalog_path] = owner["catalogSha256"].removeprefix("sha256:")
        if seen_owners != set(proof_owners):
            raise UpdateError(
                "DATA_BUNDLE_MANIFEST_MISMATCH", "Inner bundle manifest omits a proved owner."
            )
        expected_files["workspace-product-policy-v2.json"] = proof["policySha256"].removeprefix(
            "sha256:"
        )
        seen_files: dict[str, str] = {}
        for item in files:
            if not isinstance(item, dict) or set(item) != {"path", "sha256"}:
                raise UpdateError(
                    "INVALID_DATA_BUNDLE_MANIFEST", "Inner bundle file entry has an invalid shape."
                )
            path, digest = item.get("path"), item.get("sha256")
            if (
                not isinstance(path, str)
                or not isinstance(digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", digest) is None
                or path in seen_files
            ):
                raise UpdateError(
                    "INVALID_DATA_BUNDLE_MANIFEST", "Inner bundle file path or digest is invalid."
                )
            file_path = payload_root.joinpath(
                *_safe_relative(path, field="inner bundle file path").parts
            )
            if (
                file_path.is_symlink()
                or not file_path.is_file()
                or _file_digest(file_path) != "sha256:" + digest
            ):
                raise UpdateError(
                    "DATA_BUNDLE_FILE_MISMATCH", f"Inner bundle file {path!r} digest is invalid."
                )
            seen_files[path] = digest
        if any(seen_files.get(path) != digest for path, digest in expected_files.items()):
            raise UpdateError(
                "DATA_BUNDLE_MANIFEST_MISMATCH", "Inner manifest omits proved owner/policy files."
            )

    def _verify_data_bundle_subject(
        self,
        payload_root: Path,
        payload: bytes,
        record: dict[str, Any],
        *,
        label: str,
        channel: str,
        expected_subject_path: str,
        expected_workflow: str,
    ) -> None:
        source = record.get("source")
        provenance = record.get("provenance")
        attested = provenance.get("attestation") if isinstance(provenance, dict) else None
        publisher = (
            self.publishers.get(source.get("repository")) if isinstance(source, dict) else None
        )
        record_subject_path = record.get("catalogPath", record.get("path"))
        if record.get("catalogPath") is not None:
            subject_path = record_subject_path
        elif isinstance(source, dict):
            subject_path = f"{source.get('repository')}/{record_subject_path}"
        else:
            subject_path = None
        if (
            not isinstance(source, dict)
            or not isinstance(provenance, dict)
            or set(provenance)
            != {"attestation", "bundlePath", "bundleSha256", "subjectPath", "subjectDigest"}
            or publisher is None
            or source.get("ref")
            not in self.catalog.get("channels", {}).get(channel, {}).get("sourceRefs", [])
            or re.fullmatch(r"[0-9a-f]{40}", str(source.get("commit", ""))) is None
            or not isinstance(attested, dict)
            or not isinstance(subject_path, str)
            or subject_path != expected_subject_path
        ):
            raise UpdateError(
                "UNTRUSTED_DATA_BUNDLE_SOURCE", f"{label} source proof is incomplete or untrusted."
            )
        attestation = attested.get("attestation")
        _safe_relative(subject_path, field=f"{label} subject path")
        attestation_run = attestation.get("run") if isinstance(attestation, dict) else None
        if (
            not isinstance(attestation, dict)
            or set(attestation)
            - {"kind", "uri", "subjectName", "repository", "workflow", "predicateType", "run"}
            or attestation.get("kind") != "github-artifact-attestation"
            or attestation.get("repository") != source["repository"]
            or attestation.get("workflow") != expected_workflow
            or attestation.get("predicateType") != "https://slsa.dev/provenance/v1"
            or not {
                "kind",
                "subjectName",
                "repository",
                "workflow",
                "predicateType",
                "run",
            }.issubset(attestation)
            or attestation.get("subjectName") != PurePosixPath(subject_path).name
            or not isinstance(attestation_run, dict)
            or set(attestation_run) != {"id", "attempt", "url"}
            or not isinstance(attestation_run.get("id"), str)
            or re.fullmatch(r"[0-9]{1,30}", attestation_run["id"]) is None
            or not isinstance(attestation_run.get("attempt"), int)
            or isinstance(attestation_run.get("attempt"), bool)
            or attestation_run["attempt"] < 1
            or attestation_run.get("url")
            != f"https://github.com/{source['repository']}/actions/runs/{attestation.get('run', {}).get('id')}/attempts/{attestation.get('run', {}).get('attempt')}"
        ):
            raise UpdateError(
                "UNTRUSTED_DATA_BUNDLE_ATTESTATION", f"{label} attestation identity is not trusted."
            )
        bundle_path = payload_root.joinpath(
            *_safe_relative(
                provenance["bundlePath"], field=f"{label} attestation bundle path"
            ).parts
        )
        if (
            bundle_path.is_symlink()
            or not bundle_path.is_file()
            or not _valid_digest(provenance.get("bundleSha256"))
        ):
            raise UpdateError(
                "INVALID_DATA_BUNDLE_ATTESTATION",
                f"{label} attestation bundle is missing or unsafe.",
            )
        bundle_bytes = bundle_path.read_bytes()
        if "sha256:" + hashlib.sha256(bundle_bytes).hexdigest() != provenance["bundleSha256"]:
            raise UpdateError(
                "INVALID_DATA_BUNDLE_ATTESTATION", f"{label} attestation bundle digest is invalid."
            )
        declared_subject_path = provenance.get("subjectPath")
        if declared_subject_path != subject_path or provenance.get("subjectDigest") != record.get(
            "catalogSha256", record.get("sha256")
        ):
            raise UpdateError(
                "DATA_BUNDLE_SUBJECT_MISMATCH",
                f"{label} attestation does not bind the declared source file.",
            )
        self._verify_attestation(
            payload,
            subject_name=PurePosixPath(subject_path).name,
            digest=provenance["subjectDigest"],
            repository=source["repository"],
            workflow=expected_workflow,
            source_ref=source["ref"],
            source_commit=source["commit"],
            bundle_path=bundle_path,
        )

    def _stage_candidate(
        self,
        candidate: Candidate,
        plan_root: Path,
        plan_id: str | None = None,
        plan_digest: str | None = None,
        *,
        workload_identity: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        manifest = candidate.manifest
        artifact = manifest["artifact"]
        filename = PurePosixPath(urllib.parse.urlsplit(artifact["uri"]).path).name
        if not filename or filename in {".", ".."}:
            raise UpdateError("INVALID_MANIFEST", "Artifact URI has no safe basename.")
        component_root = plan_root / candidate.component["componentId"]
        component_root.mkdir(mode=0o700)
        archive_path = component_root / filename
        if candidate.release_tag is None:
            raise UpdateError(
                "INVALID_CANDIDATE", "Candidate is not bound to an immutable release tag."
            )
        payload = self._get_release_asset_bytes(
            candidate.release_assets,
            artifact["uri"],
            repository=candidate.component["publisher"],
            release_tag=candidate.release_tag,
            expected_digest=artifact["sha256"],
            expected_size=artifact["sizeBytes"],
        )
        self._write_private_file(archive_path, payload)
        self._release_attestation_bundle(
            payload=payload,
            subject_name=candidate.manifest["provenance"]["attestation"]["subjectName"],
            digest=artifact["sha256"],
            repository=candidate.component["publisher"],
            workflow=self.publishers[candidate.component["publisher"]]["workflow"],
            source_ref=manifest["source"]["ref"],
            source_commit=manifest["source"]["commit"],
            release_assets=candidate.release_assets,
            release_tag=candidate.release_tag,
        )
        payload_root = component_root / "payload"
        if artifact["kind"] == "native-binary":
            self._extract_native(archive_path, payload_root, artifact)
            installed_path = self._install_native_release(candidate, payload_root)
        elif artifact["kind"] == "python-bundle":
            self._extract_tar(archive_path, payload_root, expected_files=artifact.get("files"))
            service = candidate.component.get("pythonBundleService")
            if not service:
                raise UpdateError(
                    "INVALID_CATALOG",
                    f"{candidate.component['componentId']} has no Product bundle service mapping.",
                )
            module = self._load_service_bundle()
            bundle_root = payload_root
            if (payload_root / service).is_dir():
                bundle_root = payload_root / service
            if (bundle_root / "manifest.json").is_file() is False:
                candidates = [
                    path for path in payload_root.rglob("manifest.json") if path.parent.is_dir()
                ]
                if len(candidates) == 1:
                    bundle_root = candidates[0].parent
            target_profile_id = next(
                (
                    item.get("targetId")
                    for item in candidate.component.get("targets", [])
                    if isinstance(item, dict)
                    and item.get("artifactKind") == "python-bundle"
                    and item.get("support") == "supported"
                    and self.targets.get(item.get("targetId"), {}).get("target")
                    == candidate.manifest.get("target")
                ),
                None,
            )
            if not isinstance(target_profile_id, str):
                raise UpdateError(
                    "UNSUPPORTED_TARGET",
                    f"No trusted Python target profile matches the release for {candidate.component['componentId']}.",
                )
            inner = module.validate_bundle(
                bundle_root,
                expected_service=service,
                expected_target_profile=target_profile_id,
                release_lock_path=self.release_lock_path,
            )
            if inner.get("schema_version") != 2:
                raise UpdateError(
                    "LEGACY_BUNDLE_NOT_STAGEABLE",
                    f"The {service} payload uses inner bundle schema v1. Install this helper to inspect or roll back existing releases, then build a new SDK-backed v2 bundle before staging an update.",
                )
            embedded_runtime_dependencies = inner.get("dependencies", {}).get("runtime", [])
            for dependency in candidate.component.get("dependencies", []):
                if not isinstance(dependency, dict) or "versionRange" not in dependency:
                    continue
                dependency_component = self.components.get(dependency["componentId"], {})
                if dependency_component.get("role") != "build-dependency":
                    continue
                embedded = next(
                    (
                        item
                        for item in embedded_runtime_dependencies
                        if item.get("component_id") == dependency["componentId"]
                    ),
                    None,
                )
                if embedded is None or not _version_satisfies(
                    embedded.get("version"), dependency["versionRange"]
                ):
                    raise UpdateError(
                        "BUILD_DEPENDENCY_UNSATISFIED",
                        f"Bundle for {candidate.component['componentId']} does not embed required build dependency {dependency['componentId']} {dependency['versionRange']}.",
                    )
            installed_path = module.stage_release(
                bundle_root,
                install_root=self.install_root,
                release_lock_path=self.release_lock_path,
            )
            bundle_identity = inner.get("artifact_digest")
            if (
                not isinstance(bundle_identity, str)
                or BUNDLE_ID_PATTERN.fullmatch(bundle_identity) is None
                or installed_path.name != inner.get("version")
            ):
                raise UpdateError(
                    "INVALID_BUNDLE", f"Installed {service} bundle pointer identity is invalid."
                )
        elif artifact["kind"] == "data-bundle":
            payload_root = self._extract_data_bundle_archive(archive_path, payload_root, artifact)
            proof = self._validate_data_bundle_proof(candidate, payload_root, manifest["channel"])
            installed_path = self._install_data_bundle(
                candidate,
                archive_path,
                payload_root,
                plan_id=plan_id,
                plan_digest=plan_digest,
            )
            bundle_identity = artifact["sha256"]
        else:
            raise UpdateError(
                "UNSUPPORTED_ARTIFACT",
                "Linux staging supports only native binary and Python bundle releases.",
            )
        if artifact["kind"] == "native-binary":
            bundle_identity = None
        item = {
            "componentId": candidate.component["componentId"],
            "version": manifest["version"],
            "manifestDigest": candidate.manifest_digest,
            "releaseIdentity": candidate.manifest_digest,
            "artifactDigest": artifact["sha256"],
            "restartGroup": candidate.component["restart"]["group"],
            "pointerIdentity": installed_path.name,
            "bundleIdentity": bundle_identity,
            "manifest": manifest,
            "releasePath": str(installed_path),
            "archivePath": str(archive_path),
        }
        item.update(self._workload_receipt_fields(candidate, workload_identity))
        if artifact["kind"] == "data-bundle":
            item["dataBundle"] = {
                "artifactId": artifact["sha256"],
                "proofSha256": manifest["dataBundle"]["proofSha256"],
                "proofSchemaVersion": proof["schemaVersion"],
            }
        self._write_release_receipt(item)
        return item

    @staticmethod
    def _workload_receipt_fields(
        candidate: Candidate, resolution_component: dict[str, Any] | None
    ) -> dict[str, Any]:
        """Project verified Catalog and release identities into durable local receipts."""

        if resolution_component is None:
            return {}
        return {
            "releaseId": resolution_component.get(
                "releaseId", candidate.manifest.get("releaseId", candidate.release_tag)
            ),
            "targetId": resolution_component.get("targetId"),
            "manifestAssetDigest": candidate.manifest_asset_digest,
            "manifestUri": candidate.manifest_uri,
            "releaseTag": candidate.release_tag,
            "indexIdentity": resolution_component.get("indexIdentity"),
            "publisherIdentity": resolution_component.get("publisherIdentity"),
            "attestationRef": resolution_component.get("attestationRef"),
        }

    def _extract_data_bundle_archive(
        self, archive: Path, destination: Path, artifact: dict[str, Any]
    ) -> Path:
        """Expand a bounded zstd tar without following links or trusting archive paths."""
        if shutil.which("zstd") is None:
            raise UpdateError(
                "DATA_BUNDLE_TOOL_MISSING", "The zstd utility is required to inspect a data bundle."
            )
        compressed = artifact.get("format")
        if compressed not in {"tar.zst", "tar.zstd"}:
            raise UpdateError("INVALID_ARTIFACT", "Data bundle must use the pinned tar.zst format.")
        if (
            artifact.get("sizeBytes") != archive.stat().st_size
            or archive.stat().st_size > 64 * 1024 * 1024
        ):
            raise UpdateError(
                "UNSAFE_ARTIFACT", "Data-bundle archive exceeds its compressed-size limit."
            )
        tar_path = archive.with_suffix(".tar")

        def limit_tar_output() -> None:
            import resource

            output_limit = 320 * 1024 * 1024
            resource.setrlimit(resource.RLIMIT_FSIZE, (output_limit, output_limit))

        try:
            with tar_path.open("xb") as output:
                completed = self.runner(
                    ["zstd", "--decompress", "--stdout", str(archive)],
                    stdout=output,
                    stderr=subprocess.PIPE,
                    timeout=180,
                    check=False,
                    preexec_fn=limit_tar_output,
                )
                output.flush()
                os.fsync(output.fileno())
            if completed.returncode != 0 or tar_path.stat().st_size > 320 * 1024 * 1024:
                raise UpdateError(
                    "INVALID_ARTIFACT",
                    "Cannot decompress data-bundle archive within its expanded-size limit.",
                )
            self._extract_tar(
                tar_path,
                destination,
                expected_files=artifact.get("files"),
                max_entries=1024,
                max_member_bytes=16 * 1024 * 1024,
                max_expanded_bytes=256 * 1024 * 1024,
            )
        except (OSError, subprocess.TimeoutExpired) as error:
            raise UpdateError(
                "INVALID_ARTIFACT", f"Cannot safely decompress data bundle: {error}"
            ) from error
        finally:
            tar_path.unlink(missing_ok=True)
        return destination

    def _install_data_bundle(
        self,
        candidate: Candidate,
        archive_path: Path,
        payload_root: Path,
        *,
        plan_id: str | None = None,
        plan_digest: str | None = None,
    ) -> Path:
        """Install immutable bytes and their extracted view under Authority's fixed root."""
        artifact_id = candidate.manifest["artifact"]["sha256"]
        raw_hex = artifact_id.removeprefix("sha256:")
        if not re.fullmatch(r"[0-9a-f]{64}", raw_hex):
            raise UpdateError("INVALID_DATA_BUNDLE", "Data-bundle artifact identity is invalid.")
        archive_root = self.data_bundle_root / "archives"
        versions_root = self.data_bundle_root / "versions"
        metadata_root = self.data_bundle_root / "metadata"
        try:
            import grp

            authority_group_id = grp.getgrnam("cyrene-authority").gr_gid
            bundle_reader_group_id = grp.getgrnam("cyrene-product-bundle-reader").gr_gid
        except (ImportError, KeyError) as error:
            raise UpdateError(
                "AUTHORITY_GROUP_MISSING",
                "The cyrene-authority and cyrene-product-bundle-reader groups are required for data bundles.",
            ) from error
        group_by_directory = {
            archive_root: authority_group_id,
            versions_root: bundle_reader_group_id,
            metadata_root: authority_group_id,
        }
        try:
            root_info = self.data_bundle_root.lstat()
        except OSError as error:
            raise UpdateError(
                "UNSAFE_DATA_BUNDLE_ROOT",
                "Authority data-bundle root must be provisioned with restricted traversal ACLs.",
            ) from error
        if (
            self.data_bundle_root.is_symlink()
            or not stat.S_ISDIR(root_info.st_mode)
            or root_info.st_uid != 0
            or stat.S_IMODE(root_info.st_mode) & 0o022
        ):
            raise UpdateError("UNSAFE_DATA_BUNDLE_ROOT", "Authority data-bundle root is unsafe.")
        for directory, group_id in group_by_directory.items():
            directory.mkdir(mode=0o750, exist_ok=True)
            info = directory.lstat()
            if (
                directory.is_symlink()
                or not stat.S_ISDIR(info.st_mode)
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) & 0o022
            ):
                raise UpdateError(
                    "UNSAFE_DATA_BUNDLE_ROOT", "Authority data-bundle root is unsafe."
                )
            os.chown(directory, 0, group_id)
            directory.chmod(0o750)
        archive_target = archive_root / f"sha256-{raw_hex}.tar.zst"
        version_target = versions_root / raw_hex
        metadata_directory = metadata_root / raw_hex
        metadata_directory.mkdir(mode=0o750, exist_ok=True)
        metadata_info = metadata_directory.lstat()
        if (
            metadata_directory.is_symlink()
            or not stat.S_ISDIR(metadata_info.st_mode)
            or metadata_info.st_uid != 0
            or stat.S_IMODE(metadata_info.st_mode) & 0o022
        ):
            raise UpdateError("UNSAFE_DATA_BUNDLE_ROOT", "Authority metadata path is unsafe.")
        os.chown(metadata_directory, 0, authority_group_id)
        metadata_directory.chmod(0o750)
        if (
            candidate.manifest_bytes is None
            or _digest_json(candidate.manifest, "manifestDigest") != candidate.manifest_digest
            or candidate.manifest.get("manifestDigest") != candidate.manifest_digest
        ):
            raise UpdateError(
                "INVALID_MANIFEST", "Data-bundle import requires its verified outer manifest bytes."
            )
        try:
            imported_manifest = json.loads(
                candidate.manifest_bytes, object_pairs_hook=_unique_json_object
            )
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_MANIFEST", "Verified data-bundle manifest bytes are invalid."
            ) from error
        if imported_manifest != candidate.manifest:
            raise UpdateError(
                "INVALID_MANIFEST", "Outer manifest bytes differ from the validated manifest."
            )
        metadata_path = metadata_directory / "component-manifest-v2.json"
        import_record_path = metadata_directory / "import-record-v1.json"
        import_record = {
            "schemaVersion": 1,
            "artifactId": artifact_id,
            "componentId": candidate.component["componentId"],
            "channel": candidate.manifest.get("channel"),
            "manifestDigest": candidate.manifest_digest,
            "manifestUri": candidate.manifest_uri,
            "indexUri": candidate.index_uri,
            "indexDigest": candidate.index.get("indexDigest"),
            "indexSource": candidate.index.get("source"),
            "publisherRepository": candidate.component["publisher"],
        }
        if metadata_path.exists() or metadata_path.is_symlink():
            self._validate_authority_metadata_file(metadata_path, authority_group_id)
            if metadata_path.read_bytes() != candidate.manifest_bytes:
                raise UpdateError(
                    "DATA_BUNDLE_COLLISION", "Existing outer manifest metadata differs."
                )
        else:
            self._write_authority_metadata(metadata_path, candidate.manifest_bytes)
        if import_record_path.exists() or import_record_path.is_symlink():
            self._validate_authority_metadata_file(import_record_path, authority_group_id)
            existing_record = _read_object(import_record_path, "existing data-bundle import record")
            if any(existing_record.get(key) != value for key, value in import_record.items()):
                raise UpdateError(
                    "DATA_BUNDLE_COLLISION", "Existing data-bundle import record differs."
                )
        else:
            self._write_authority_metadata(
                import_record_path,
                json.dumps(import_record, ensure_ascii=False, sort_keys=True, indent=2).encode()
                + b"\n",
            )
        if (
            not isinstance(plan_id, str)
            or PLAN_ID_PATTERN.fullmatch(plan_id) is None
            or not _valid_digest(plan_digest)
        ):
            raise UpdateError(
                "INVALID_PLAN", "Data-bundle import requires a digest-bound checked plan."
            )
        plan_refs = metadata_directory / "plans"
        plan_refs.mkdir(mode=0o750, exist_ok=True)
        plan_refs_info = plan_refs.lstat()
        if plan_refs.is_symlink() or not stat.S_ISDIR(plan_refs_info.st_mode):
            raise UpdateError("UNSAFE_DATA_BUNDLE_ROOT", "Authority plan metadata path is unsafe.")
        os.chown(plan_refs, 0, authority_group_id)
        plan_refs.chmod(0o750)
        plan_reference_path = plan_refs / f"{plan_id}.json"
        plan_reference = {
            "schemaVersion": 1,
            "planId": plan_id,
            "planDigest": plan_digest,
            "artifactId": artifact_id,
            "manifestDigest": candidate.manifest_digest,
            "proofSha256": candidate.manifest["dataBundle"]["proofSha256"],
        }
        plan_reference_bytes = (
            json.dumps(plan_reference, ensure_ascii=False, sort_keys=True, indent=2).encode()
            + b"\n"
        )
        if plan_reference_path.exists() or plan_reference_path.is_symlink():
            self._validate_authority_metadata_file(plan_reference_path, authority_group_id)
            existing_reference = _read_object(
                plan_reference_path, "existing data-bundle plan reference"
            )
            if existing_reference != plan_reference:
                raise UpdateError("DATA_BUNDLE_COLLISION", "Existing plan reference differs.")
        else:
            self._write_authority_metadata(plan_reference_path, plan_reference_bytes)
        if archive_target.exists() or archive_target.is_symlink():
            archive_info = archive_target.lstat()
            if (
                archive_target.is_symlink()
                or not stat.S_ISREG(archive_info.st_mode)
                or archive_info.st_uid != 0
                or archive_info.st_gid != authority_group_id
                or stat.S_IMODE(archive_info.st_mode) != 0o640
                or _file_digest(archive_target) != artifact_id
            ):
                raise UpdateError(
                    "DATA_BUNDLE_COLLISION",
                    "Existing content-addressed archive is unsafe or mismatched.",
                )
        else:
            temporary_archive = archive_root / f".{raw_hex}.{uuid.uuid4().hex}.tmp"
            descriptor = os.open(
                temporary_archive,
                os.O_CREAT | os.O_EXCL | os.O_WRONLY | getattr(os, "O_NOFOLLOW", 0),
                0o640,
            )
            with os.fdopen(descriptor, "wb") as output, archive_path.open("rb") as source:
                shutil.copyfileobj(source, output)
                output.flush()
                os.fsync(output.fileno())
            try:
                import grp

                os.chown(temporary_archive, 0, grp.getgrnam("cyrene-authority").gr_gid)
                os.chmod(temporary_archive, 0o640)
            except (ImportError, KeyError) as error:
                temporary_archive.unlink(missing_ok=True)
                raise UpdateError(
                    "AUTHORITY_GROUP_MISSING",
                    "The cyrene-authority group is required for staged bundles.",
                ) from error
            os.replace(temporary_archive, archive_target)
            self._fsync_directory(archive_root)
        if version_target.exists() or version_target.is_symlink():
            version_info = version_target.lstat()
            if (
                version_target.is_symlink()
                or not stat.S_ISDIR(version_info.st_mode)
                or version_info.st_uid != 0
                or version_info.st_gid != bundle_reader_group_id
                or stat.S_IMODE(version_info.st_mode) != 0o750
            ):
                raise UpdateError(
                    "DATA_BUNDLE_COLLISION", "Existing data-bundle version path is unsafe."
                )
            proof = version_target / "data-bundle-proof-v1.json"
            if (
                proof.is_symlink()
                or not proof.is_file()
                or _file_digest(proof) != candidate.manifest["dataBundle"]["proofSha256"]
            ):
                raise UpdateError(
                    "DATA_BUNDLE_COLLISION", "Existing extracted data-bundle proof differs."
                )
            self._verify_existing_bundle_tree(version_target, payload_root, bundle_reader_group_id)
            return version_target
        temporary = versions_root / f".{raw_hex}.{uuid.uuid4().hex}.tmp"
        shutil.copytree(payload_root, temporary, symlinks=False)
        try:
            self._set_bundle_reader_permissions(temporary)
            os.replace(temporary, version_target)
            self._fsync_directory(versions_root)
        finally:
            if temporary.exists():
                shutil.rmtree(temporary)
        return version_target

    @staticmethod
    def _verify_existing_bundle_tree(
        installed_root: Path, verified_root: Path, group_id: int
    ) -> None:
        """Require a reused content-addressed tree to exactly match newly verified payloads."""
        expected_files: dict[str, str] = {}
        expected_directories: set[str] = set()
        for current, directory_names, file_names in os.walk(verified_root, followlinks=False):
            current_path = Path(current)
            for name in directory_names:
                path = current_path / name
                if path.is_symlink() or not path.is_dir():
                    raise UpdateError(
                        "UNSAFE_DATA_BUNDLE", "Verified bundle has an unsafe directory."
                    )
                expected_directories.add(path.relative_to(verified_root).as_posix())
            for name in file_names:
                path = current_path / name
                if path.is_symlink() or not path.is_file():
                    raise UpdateError("UNSAFE_DATA_BUNDLE", "Verified bundle has an unsafe file.")
                expected_files[path.relative_to(verified_root).as_posix()] = _file_digest(path)

        actual_files: dict[str, str] = {}
        actual_directories: set[str] = set()
        for current, directory_names, file_names in os.walk(installed_root, followlinks=False):
            current_path = Path(current)
            info = current_path.lstat()
            if (
                current_path.is_symlink()
                or not stat.S_ISDIR(info.st_mode)
                or info.st_uid != 0
                or info.st_gid != group_id
                or stat.S_IMODE(info.st_mode) != 0o750
            ):
                raise UpdateError(
                    "UNSAFE_DATA_BUNDLE", "Installed bundle directory permissions are unsafe."
                )
            if current_path != installed_root:
                actual_directories.add(current_path.relative_to(installed_root).as_posix())
            for name in directory_names:
                path = current_path / name
                if path.is_symlink() or not path.is_dir():
                    raise UpdateError(
                        "UNSAFE_DATA_BUNDLE", "Installed bundle has an unsafe directory."
                    )
            for name in file_names:
                path = current_path / name
                info = path.lstat()
                if (
                    path.is_symlink()
                    or not stat.S_ISREG(info.st_mode)
                    or info.st_uid != 0
                    or info.st_gid != group_id
                    or stat.S_IMODE(info.st_mode) != 0o640
                ):
                    raise UpdateError(
                        "UNSAFE_DATA_BUNDLE", "Installed bundle file permissions are unsafe."
                    )
                actual_files[path.relative_to(installed_root).as_posix()] = _file_digest(path)
        if actual_files != expected_files or actual_directories != expected_directories:
            raise UpdateError(
                "DATA_BUNDLE_COLLISION",
                "Existing data-bundle tree differs from its verified archive.",
            )

    @staticmethod
    def _write_authority_metadata(path: Path, payload: bytes) -> None:
        """Atomically publish read-only import evidence for Authority's fixed-root reader."""
        try:
            import grp

            group_id = grp.getgrnam("cyrene-authority").gr_gid
        except (ImportError, KeyError) as error:
            raise UpdateError(
                "AUTHORITY_GROUP_MISSING",
                "The cyrene-authority group is required for data-bundle metadata.",
            ) from error
        temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
        descriptor = os.open(
            temporary,
            os.O_CREAT | os.O_EXCL | os.O_WRONLY | getattr(os, "O_NOFOLLOW", 0),
            0o640,
        )
        try:
            with os.fdopen(descriptor, "wb") as output:
                output.write(payload)
                output.flush()
                os.fsync(output.fileno())
            os.chown(temporary, 0, group_id)
            os.chmod(temporary, 0o640)
            os.replace(temporary, path)
            ComponentUpdater._fsync_directory(path.parent)
        finally:
            temporary.unlink(missing_ok=True)

    @staticmethod
    def _validate_authority_metadata_file(path: Path, group_id: int) -> None:
        try:
            info = path.lstat()
        except OSError as error:
            raise UpdateError(
                "UNSAFE_DATA_BUNDLE_ROOT", "Authority metadata file is unavailable."
            ) from error
        if (
            path.is_symlink()
            or not stat.S_ISREG(info.st_mode)
            or info.st_uid != 0
            or info.st_gid != group_id
            or stat.S_IMODE(info.st_mode) != 0o640
        ):
            raise UpdateError(
                "UNSAFE_DATA_BUNDLE_ROOT", "Authority metadata file permissions are unsafe."
            )

    @staticmethod
    def _set_bundle_reader_permissions(root: Path) -> None:
        try:
            import grp

            group_id = grp.getgrnam("cyrene-product-bundle-reader").gr_gid
        except (ImportError, KeyError) as error:
            raise UpdateError(
                "AUTHORITY_GROUP_MISSING",
                "The cyrene-product-bundle-reader group is required for staged bundles.",
            ) from error
        for current, directories, files in os.walk(root, followlinks=False):
            directory = Path(current)
            if directory.is_symlink():
                raise UpdateError("UNSAFE_DATA_BUNDLE", "Extracted data bundle contains a symlink.")
            os.chown(directory, 0, group_id)
            directory.chmod(0o750)
            for name in directories + files:
                path = directory / name
                if path.is_symlink():
                    raise UpdateError(
                        "UNSAFE_DATA_BUNDLE", "Extracted data bundle contains a symlink."
                    )
                if path.is_dir():
                    os.chown(path, 0, group_id)
                    path.chmod(0o750)
                elif path.is_file():
                    os.chown(path, 0, group_id)
                    path.chmod(0o640)
                else:
                    raise UpdateError(
                        "UNSAFE_DATA_BUNDLE", "Extracted data bundle contains a special file."
                    )

    @staticmethod
    def _write_private_file(path: Path, value: bytes) -> None:
        descriptor = os.open(
            path, os.O_CREAT | os.O_EXCL | os.O_WRONLY | getattr(os, "O_NOFOLLOW", 0), 0o600
        )
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(value)
            stream.flush()
            os.fsync(stream.fileno())

    def _extract_native(self, archive: Path, destination: Path, artifact: dict[str, Any]) -> None:
        expected = artifact["files"]
        self._extract_tar(archive, destination, expected_files=expected)
        entrypoint = _safe_relative(artifact["entrypoint"], field="artifact.entrypoint")
        executable_paths = _native_executable_files(artifact)
        binary = destination.joinpath(*entrypoint.parts)
        if not binary.is_file():
            raise UpdateError("INVALID_ARTIFACT", "Native artifact entrypoint is missing.")
        self._normalize_payload(destination, executable_paths)

    def _extract_tar(
        self,
        archive: Path,
        destination: Path,
        expected_files: dict[str, str] | None,
        *,
        max_entries: int | None = None,
        max_member_bytes: int | None = None,
        max_expanded_bytes: int | None = None,
    ) -> None:
        destination.mkdir(mode=0o700)
        found: dict[str, str] = {}
        seen_entries: set[str] = set()
        expanded_bytes = 0
        try:
            with tarfile.open(archive, "r:*") as tar:
                entry_count = 0
                for member in tar:
                    entry_count += 1
                    if max_entries is not None and entry_count > max_entries:
                        raise UpdateError(
                            "UNSAFE_ARTIFACT", "Archive contains too many files or directories."
                        )
                    raw_path = member.name
                    if member.isdir() and raw_path.endswith("/"):
                        raw_path = raw_path[:-1]
                    path = _safe_relative(raw_path, field="tar member")
                    normalized = path.as_posix()
                    if normalized in seen_entries:
                        raise UpdateError(
                            "UNSAFE_ARTIFACT", f"Archive contains a duplicate entry: {member.name}"
                        )
                    seen_entries.add(normalized)
                    target = destination.joinpath(*path.parts)
                    if member.isdir():
                        if member.size != 0:
                            raise UpdateError(
                                "UNSAFE_ARTIFACT",
                                f"Archive directory has unexpected content: {member.name}",
                            )
                        target.mkdir(parents=True, exist_ok=True, mode=0o755)
                        continue
                    if not member.isfile():
                        raise UpdateError(
                            "UNSAFE_ARTIFACT",
                            f"Archive contains a link or special file: {member.name}",
                        )
                    if member.size > (max_member_bytes or 2_000_000_000):
                        raise UpdateError(
                            "UNSAFE_ARTIFACT", f"Archive member is too large: {member.name}"
                        )
                    expanded_bytes += member.size
                    if max_expanded_bytes is not None and expanded_bytes > max_expanded_bytes:
                        raise UpdateError(
                            "UNSAFE_ARTIFACT", "Archive exceeds its expanded-size limit."
                        )
                    target.parent.mkdir(parents=True, exist_ok=True, mode=0o755)
                    source = tar.extractfile(member)
                    if source is None:
                        raise UpdateError(
                            "INVALID_ARTIFACT", f"Archive member cannot be read: {member.name}"
                        )
                    with source, target.open("xb") as output:
                        shutil.copyfileobj(source, output)
                    found[path.as_posix()] = hashlib.sha256(target.read_bytes()).hexdigest()
        except (OSError, tarfile.TarError) as error:
            raise UpdateError(
                "INVALID_ARTIFACT", f"Cannot safely extract release archive: {error}"
            ) from error
        if expected_files is not None:
            wanted = {
                name: digest.removeprefix("sha256:") for name, digest in expected_files.items()
            }
            if found != wanted:
                raise UpdateError(
                    "PAYLOAD_FILE_DIGEST_MISMATCH",
                    "Native payload files do not match the manifest file map.",
                )

    @staticmethod
    def _normalize_payload(root: Path, executable_files: set[str]) -> None:
        for current, directory_names, file_names in os.walk(root, followlinks=False):
            current_path = Path(current)
            current_path.chmod(0o755)
            for name in directory_names:
                path = current_path / name
                if path.is_symlink() or not path.is_dir():
                    raise UpdateError(
                        "UNSAFE_ARTIFACT", f"Payload contains an unsafe directory: {path}"
                    )
                path.chmod(0o755)
            for name in file_names:
                path = current_path / name
                if path.is_symlink() or not path.is_file():
                    raise UpdateError("UNSAFE_ARTIFACT", f"Payload contains an unsafe file: {path}")
                path.chmod(
                    0o755 if path.relative_to(root).as_posix() in executable_files else 0o644
                )

    def _install_native_release(self, candidate: Candidate, payload_root: Path) -> Path:
        component_id = candidate.component["componentId"]
        version = candidate.manifest["version"]
        root = self.install_root / "components" / component_id
        manifest_digest = candidate.manifest_digest
        if not _valid_digest(manifest_digest):
            raise UpdateError(
                "INVALID_MANIFEST", f"Native {component_id} manifest digest is invalid."
            )
        release_identity = f"{version}--{manifest_digest.removeprefix('sha256:')}"
        release = root / "releases" / release_identity
        if payload_root.is_symlink() or not payload_root.is_dir():
            raise UpdateError(
                "UNSAFE_ARTIFACT", "Staged native payload root is not a real directory."
            )
        self._ensure_native_release_directories(component_id)
        if release.exists():
            existing_manifest = _read_object(
                release / "component-manifest.json", "existing component manifest"
            )
            self._validate_manifest_digest(existing_manifest, candidate.manifest_digest)
            if existing_manifest != candidate.manifest:
                raise UpdateError(
                    "RELEASE_COLLISION",
                    f"Native release identity collision for {component_id} {version}.",
                )
            return release
        os.replace(payload_root, release)
        self._atomic_json_file(release / "component-manifest.json", candidate.manifest, mode=0o644)
        item = {
            "componentId": component_id,
            "version": version,
            "releaseIdentity": manifest_digest,
            "manifestDigest": manifest_digest,
            "artifactDigest": _artifact_digest_from_manifest(candidate.manifest),
            "bundleIdentity": None,
            "manifest": candidate.manifest,
        }
        self._write_release_receipt(item)
        return release

    def _ensure_native_release_directories(self, component_id: str) -> None:
        """Create traversable immutable release ancestors despite a restrictive umask."""

        component_root = self.install_root / "components" / component_id
        directories = (
            self.install_root,
            self.install_root / "components",
            component_root,
            component_root / "releases",
        )
        for directory in directories:
            try:
                directory.mkdir(mode=0o755)
            except FileExistsError:
                pass
            except OSError as error:
                raise UpdateError(
                    "UNSAFE_INSTALL_ROOT",
                    f"Cannot create native release directory: {directory}.",
                ) from error

            try:
                metadata = directory.lstat()
            except OSError as error:
                raise UpdateError(
                    "UNSAFE_INSTALL_ROOT",
                    f"Cannot inspect native release directory: {directory}.",
                ) from error
            if (
                not stat.S_ISDIR(metadata.st_mode)
                or metadata.st_uid != os.geteuid()
                or stat.S_IMODE(metadata.st_mode) & 0o022
            ):
                raise UpdateError(
                    "UNSAFE_INSTALL_ROOT",
                    f"Native release directory is not a private-owner directory: {directory}.",
                )
            try:
                # mkdir's mode is filtered by umask; restore the runner's required
                # traversable mode only after rejecting links and writable ancestors.
                os.chmod(directory, 0o755, follow_symlinks=False)
                verified = directory.lstat()
            except OSError as error:
                raise UpdateError(
                    "UNSAFE_INSTALL_ROOT",
                    f"Cannot set native release directory permissions: {directory}.",
                ) from error
            if (
                not stat.S_ISDIR(verified.st_mode)
                or verified.st_uid != os.geteuid()
                or stat.S_IMODE(verified.st_mode) != 0o755
            ):
                raise UpdateError(
                    "UNSAFE_INSTALL_ROOT",
                    f"Native release directory did not retain its required mode: {directory}.",
                )

    @staticmethod
    def _atomic_json_file(path: Path, value: dict[str, Any], *, mode: int) -> None:
        temporary = path.with_name("." + path.name + ".tmp")
        with temporary.open("x", encoding="utf-8") as stream:
            json.dump(value, stream, ensure_ascii=False, sort_keys=True, indent=2)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        temporary.chmod(mode)
        os.replace(temporary, path)

    def _validate_manifest_digest(self, manifest: Any, expected: Any) -> None:
        if (
            not isinstance(manifest, dict)
            or not _valid_digest(expected)
            or manifest.get("manifestDigest") != expected
            or expected != _digest_json(manifest, "manifestDigest")
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE", "Component manifest JCS digest is invalid."
            )

    def _validate_staged_record(
        self,
        record: dict[str, Any],
        *,
        expected_plan_id: str,
        expected_plan_digest: str,
    ) -> None:
        if (
            record.get("schemaVersion") != 2
            or record.get("phase") != "staged"
            or not isinstance(record.get("components"), list)
        ):
            raise UpdateError("INVALID_STAGE", "Staged plan metadata has an unsupported schema.")
        plan = record.get("plan")
        if (
            not isinstance(plan, dict)
            or plan.get("planId") != expected_plan_id
            or plan.get("planDigest") != expected_plan_digest
            or plan.get("channel") != record.get("channel")
            or record.get("channel") not in {"stable", "preview"}
            or plan.get("phase") != "checked"
        ):
            raise UpdateError(
                "INVALID_STAGE", "Staged plan identity or channel differs from apply confirmation."
            )
        plan_components = plan.get("components")
        if not isinstance(plan_components, list) or not plan_components:
            raise UpdateError("INVALID_STAGE", "Staged plan has no checked component list.")
        if (
            plan.get("catalogGeneration") != self.catalog_generation
            or plan.get("catalogDigest") != self.catalog_digest
        ):
            raise UpdateError(
                "PLAN_CATALOG_CHANGED",
                "The staged plan was checked against a different catalog generation; check and stage again.",
            )
        plan_material = {
            "schemaVersion": 1,
            "channel": plan["channel"],
            "catalogGeneration": plan["catalogGeneration"],
            "catalogDigest": plan["catalogDigest"],
            "components": plan_components,
        }
        if "deploymentPlacement" in plan:
            placement = plan["deploymentPlacement"]
            if not isinstance(placement, list) or not placement:
                raise UpdateError("INVALID_STAGE", "Placement plan evidence is invalid.")
            plan_material["deploymentPlacement"] = placement
        expected_digest = "sha256:" + hashlib.sha256(canonical_jcs(plan_material)).hexdigest()
        expected_id = "plan-" + expected_digest.split(":", 1)[1][:32]
        if expected_digest != expected_plan_digest or expected_id != expected_plan_id:
            raise UpdateError(
                "INVALID_STAGE", "Staged plan digest does not match its canonical contents."
            )
        if len(plan_components) != len(record["components"]):
            raise UpdateError(
                "INVALID_STAGE", "Staged component set differs from the checked plan."
            )

        planned_by_id: dict[str, dict[str, Any]] = {}
        plan_fields = {"componentId", "version", "manifestDigest", "artifactDigest", "restartGroup"}
        for planned in plan_components:
            if (
                not isinstance(planned, dict)
                or set(planned) != plan_fields
                or not isinstance(planned.get("componentId"), str)
                or not isinstance(planned.get("version"), str)
                or VERSION_PATTERN.fullmatch(planned["version"]) is None
                or not _valid_digest(planned.get("manifestDigest"))
                or not _valid_digest(planned.get("artifactDigest"))
                or not isinstance(planned.get("restartGroup"), str)
                or planned["componentId"] in planned_by_id
            ):
                raise UpdateError(
                    "INVALID_STAGE", "Checked plan component metadata is invalid or duplicated."
                )
            planned_by_id[planned["componentId"]] = planned

        staged_ids: set[str] = set()
        stage_root = self.state_root / "staged" / expected_plan_id
        for item in record["components"]:
            item_fields = plan_fields | {
                "manifest",
                "releasePath",
                "archivePath",
                "releaseIdentity",
                "pointerIdentity",
                "bundleIdentity",
            }
            if (
                isinstance(item, dict)
                and self.components.get(item.get("componentId"), {}).get("kind") == "data-bundle"
            ):
                item_fields.add("dataBundle")
            if (
                not isinstance(item, dict)
                or set(item) != item_fields
                or not isinstance(item.get("componentId"), str)
                or item.get("componentId") not in self.components
                or item["componentId"] in staged_ids
                or not isinstance(item.get("releasePath"), str)
                or not isinstance(item.get("archivePath"), str)
            ):
                raise UpdateError(
                    "INVALID_STAGE", "Staged component identity is invalid or duplicated."
                )
            component_id = item["componentId"]
            staged_ids.add(component_id)
            planned = planned_by_id.get(component_id)
            if planned is None or any(item.get(key) != planned.get(key) for key in plan_fields):
                raise UpdateError(
                    "INVALID_STAGE",
                    f"Staged metadata differs from the checked plan for {component_id}.",
                )
            manifest = item.get("manifest")
            self._validate_manifest_digest(manifest, item.get("manifestDigest"))
            if (
                manifest.get("componentId") != component_id
                or manifest.get("version") != item["version"]
                or item.get("releaseIdentity") != item.get("manifestDigest")
            ):
                raise UpdateError(
                    "INVALID_STAGE", f"Staged manifest identity differs for {component_id}."
                )
            artifact = manifest.get("artifact")
            artifact_digest = artifact.get("sha256") if isinstance(artifact, dict) else None
            if (
                not _valid_digest(artifact_digest)
                or item.get("artifactDigest") != artifact_digest
                or item.get("restartGroup")
                != self.components[component_id].get("restart", {}).get("group")
            ):
                raise UpdateError(
                    "INVALID_STAGE", f"Staged artifact identity differs for {component_id}."
                )

            component = self.components[component_id]
            service = component.get("pythonBundleService")
            if component.get("kind") == "data-bundle":
                artifact_descriptor = manifest.get("artifact")
                artifact_id = (
                    artifact_descriptor.get("sha256")
                    if isinstance(artifact_descriptor, dict)
                    else None
                )
                expected_release = (
                    self.data_bundle_root / "versions" / artifact_id.removeprefix("sha256:")
                    if _valid_digest(artifact_id)
                    else Path("/")
                )
                expected_pointer = (
                    artifact_id.removeprefix("sha256:") if _valid_digest(artifact_id) else None
                )
                bundle_record = item.get("dataBundle")
                if (
                    not isinstance(bundle_record, dict)
                    or set(bundle_record) != {"artifactId", "proofSha256", "proofSchemaVersion"}
                    or bundle_record.get("artifactId") != artifact_id
                    or bundle_record.get("proofSha256")
                    != manifest.get("dataBundle", {}).get("proofSha256")
                    or bundle_record.get("proofSchemaVersion") != 1
                    or item.get("bundleIdentity") != artifact_id
                ):
                    raise UpdateError(
                        "INVALID_STAGE", "Data-bundle staged identity differs from its manifest."
                    )
            elif service:
                bundle_identity = item.get("bundleIdentity")
                if (
                    not isinstance(bundle_identity, str)
                    or BUNDLE_ID_PATTERN.fullmatch(bundle_identity) is None
                ):
                    raise UpdateError(
                        "INVALID_STAGE",
                        f"Staged Python bundle identity is invalid for {component_id}.",
                    )
                expected_release = (
                    self.install_root / "services" / service / "releases" / bundle_identity
                )
            else:
                expected_pointer = (
                    f"{item['version']}--{item['manifestDigest'].removeprefix('sha256:')}"
                )
                if item.get("bundleIdentity") is not None:
                    raise UpdateError(
                        "INVALID_STAGE",
                        f"Native component {component_id} has a Python bundle identity.",
                    )
                expected_release = (
                    self.install_root / "components" / component_id / "releases" / expected_pointer
                )
            if item.get("pointerIdentity") != expected_release.name:
                raise UpdateError(
                    "INVALID_STAGE", f"Staged pointer identity differs for {component_id}."
                )
            release_path = Path(item["releasePath"])
            if (
                release_path != expected_release
                or release_path.is_symlink()
                or not release_path.is_dir()
            ):
                raise UpdateError(
                    "INVALID_STAGE", f"Staged release is missing or unsafe for {component_id}."
                )
            allowed_release_root = (
                self.data_bundle_root
                if component.get("kind") == "data-bundle"
                else self.install_root
            )
            if not self._path_is_under(release_path, allowed_release_root):
                raise UpdateError(
                    "INVALID_STAGE", f"Staged release escaped its trusted root for {component_id}."
                )
            if component.get("kind") == "data-bundle":
                authority_archive = (
                    self.data_bundle_root
                    / "archives"
                    / f"sha256-{item['artifactDigest'].removeprefix('sha256:')}.tar.zst"
                )
                if (
                    authority_archive.is_symlink()
                    or not authority_archive.is_file()
                    or _file_digest(authority_archive) != item["artifactDigest"]
                ):
                    raise UpdateError(
                        "INVALID_STAGE",
                        "Authority's content-addressed bundle archive is missing or changed.",
                    )
                self._validate_data_bundle_proof(
                    Candidate(
                        component,
                        manifest,
                        item["manifestDigest"],
                        item["artifactDigest"],
                        "",
                        {},
                        "",
                    ),
                    release_path,
                    record["channel"],
                )
            elif service:
                try:
                    inner = self._load_service_bundle().validate_bundle(
                        release_path, expected_service=service
                    )
                except Exception as error:
                    raise UpdateError(
                        "INVALID_STAGE",
                        f"Staged Python bundle failed revalidation for {component_id}: {error}",
                    ) from error
                if (
                    inner.get("schema_version") != 2
                    or inner.get("version") != item["bundleIdentity"]
                    or inner.get("artifact_digest") != item["bundleIdentity"]
                ):
                    raise UpdateError(
                        "INVALID_STAGE",
                        f"Staged Python bundle identity differs for {component_id}.",
                    )
            else:
                local_manifest = _read_object(
                    release_path / "component-manifest.json",
                    f"staged {component_id} release manifest",
                )
                self._validate_manifest_digest(local_manifest, item["manifestDigest"])
                if local_manifest != manifest:
                    raise UpdateError(
                        "INVALID_STAGE", f"Staged native manifest changed for {component_id}."
                    )

            if component.get("kind") != "data-bundle":
                receipt = self._read_release_receipt(component_id, item["releaseIdentity"])
                if (
                    receipt is None
                    or receipt.get("manifest") != manifest
                    or receipt.get("artifactDigest") != item["artifactDigest"]
                    or receipt.get("version") != item["version"]
                    or receipt.get("bundleIdentity") != item.get("bundleIdentity")
                ):
                    raise UpdateError(
                        "INVALID_STAGE",
                        f"Verified release receipt is missing or inconsistent for {component_id}.",
                    )

            archive_path = Path(item["archivePath"])
            if (
                archive_path.parent != stage_root / component_id
                or archive_path.is_symlink()
                or not archive_path.is_file()
                or _file_digest(archive_path) != item["artifactDigest"]
            ):
                raise UpdateError(
                    "INVALID_STAGE", f"Staged archive is missing or unsafe for {component_id}."
                )

    @staticmethod
    def _path_is_under(path: Path, parent: Path) -> bool:
        try:
            path.resolve().relative_to(parent.resolve())
            return True
        except ValueError:
            return False

    def _capture_active_versions(self, components: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Capture actual pointer and verified release identities for rollback."""

        captured = []
        for item in components:
            component_id = item["componentId"]
            component = self.components[component_id]
            installed = self._installed(component)
            if component.get("kind") == "data-bundle" and installed.get("active") is True:
                artifact_id = installed.get("artifactDigest")
                captured.append(
                    {
                        "componentId": component_id,
                        "version": installed.get("activeVersion")
                        if installed.get("manifest")
                        else "0.0.0",
                        "releaseIdentity": installed.get("releaseIdentity")
                        if installed.get("manifest")
                        else None,
                        "manifestDigest": installed.get("manifestDigest")
                        if installed.get("manifest")
                        else None,
                        "artifactDigest": artifact_id,
                        "pointerIdentity": artifact_id.removeprefix("sha256:")
                        if _valid_digest(artifact_id)
                        else None,
                        "bundleIdentity": artifact_id,
                        "identityAttested": True,
                    }
                )
                continue
            captured.append(
                {
                    "componentId": component_id,
                    "version": installed.get("activeVersion"),
                    "releaseIdentity": installed.get("releaseIdentity"),
                    "manifestDigest": installed.get("manifestDigest"),
                    "artifactDigest": installed.get("artifactDigest"),
                    "pointerIdentity": installed.get("pointerIdentity"),
                    "bundleIdentity": installed.get("bundleIdentity"),
                    "identityAttested": installed.get("identityAttested") is True,
                }
            )
        return captured

    def _prepare_authority_activation(
        self, record: dict[str, Any], plan_id: str, plan_digest: str
    ) -> dict[str, Any] | None:
        data_bundle = next(
            (
                item
                for item in record["components"]
                if self.components[item["componentId"]].get("kind") == "data-bundle"
            ),
            None,
        )
        if data_bundle is None:
            return None
        status = self._authority_request({"action": "status"})
        generation = status.get("highestGeneration")
        current = status.get("activeArtifactId")
        if (
            not isinstance(generation, int)
            or isinstance(generation, bool)
            or generation < 0
            or (current is not None and not _valid_digest(current))
        ):
            raise UpdateError(
                "AUTHORITY_STATUS_INVALID",
                "Authority status omitted a valid generation or artifact identity.",
            )
        data = data_bundle.get("dataBundle")
        artifact_id = data.get("artifactId") if isinstance(data, dict) else None
        if not _valid_digest(artifact_id):
            raise UpdateError("INVALID_STAGE", "Staged data-bundle artifact identity is invalid.")
        validation = self._authority_request(
            {
                "action": "validateArtifact",
                "planId": plan_id,
                "planDigest": plan_digest,
                "artifactId": artifact_id,
            }
        )
        if (
            validation.get("artifactId") != artifact_id
            or validation.get("planId") != plan_id
            or validation.get("planDigest") != plan_digest
            or validation.get("highestGeneration") != generation
            or validation.get("nextGeneration") != generation + 1
            or validation.get("currentGeneration") != status.get("currentGeneration")
        ):
            raise UpdateError(
                "AUTHORITY_PLAN_MISMATCH",
                "Authority validation response differs from the confirmed staged plan.",
            )
        return {
            "planId": plan_id,
            "planDigest": plan_digest,
            "artifactId": artifact_id,
            "expectedGeneration": generation,
            "previousArtifactId": current,
            "validationResponse": validation,
        }

    def _activate_authority_bundle(self, transaction: dict[str, Any]) -> None:
        activation = transaction.get("authorityActivation")
        if activation is None:
            return
        response = self._authority_request(
            {
                "action": "activateArtifact",
                "planId": activation["planId"],
                "planDigest": activation["planDigest"],
                "expectedGeneration": activation["expectedGeneration"],
                "artifactId": activation["artifactId"],
            }
        )
        status = self._authority_request({"action": "status"})
        current = status.get("activeArtifactId")
        generation = status.get("highestGeneration")
        if (
            current != activation["artifactId"]
            or not isinstance(generation, int)
            or generation != activation["expectedGeneration"] + 1
            or response.get("artifactId") != activation["artifactId"]
            or response.get("planId") != activation["planId"]
            or response.get("planDigest") != activation["planDigest"]
            or response.get("currentGeneration") != status.get("currentGeneration")
            or response.get("highestGeneration") != generation
            or response.get("activationEpoch") != status.get("activationEpoch")
        ):
            raise UpdateError(
                "AUTHORITY_ACTIVATION_UNCONFIRMED",
                "Authority did not durably activate the verified data bundle.",
                retryable=True,
            )
        activation["activationResponse"] = response
        activation["resultingGeneration"] = generation
        activation["resultingEpoch"] = status.get("activationEpoch")
        transaction_path = self.state_root / "transactions" / f"{transaction['planId']}.json"
        if transaction_path.is_file() and not transaction_path.is_symlink():
            _atomic_json(transaction_path, transaction)

    def _rollback_authority_activation(self, transaction: dict[str, Any]) -> None:
        activation = transaction.get("authorityActivation")
        if not isinstance(activation, dict):
            return
        status = self._authority_request({"action": "status"})
        current = status.get("activeArtifactId")
        if current == activation.get("previousArtifactId"):
            return
        if current != activation.get("artifactId"):
            raise UpdateError(
                "AUTHORITY_ROLLBACK_CONFLICT",
                "Authority active artifact changed outside this update transaction.",
            )
        previous_artifact = activation.get("previousArtifactId")
        if not _valid_digest(previous_artifact):
            raise UpdateError(
                "AUTHORITY_ROLLBACK_UNAVAILABLE",
                "Initial Authority activation has no previous artifact; its durable pointer cannot be rewound.",
            )
        origin_plan_id, origin_plan_digest = self._find_authority_artifact_plan_reference(
            previous_artifact
        )
        generation = status.get("highestGeneration")
        if not isinstance(generation, int) or isinstance(generation, bool) or generation < 0:
            raise UpdateError(
                "AUTHORITY_STATUS_INVALID", "Authority generation is invalid during rollback."
            )
        rollback_material = {
            "schemaVersion": 1,
            "action": "rollback",
            "originPlanId": origin_plan_id,
            "originPlanDigest": origin_plan_digest,
            "artifactId": previous_artifact,
            "recoveryPlanId": transaction["planId"],
            "recoveryPlanDigest": transaction["planDigest"],
        }
        rollback_digest = "sha256:" + hashlib.sha256(canonical_jcs(rollback_material)).hexdigest()
        rollback_id = "plan-rollback-" + rollback_digest.split(":", 1)[1][:32]
        self._persist_authority_rollback_plan_reference(
            previous_artifact,
            plan_id=rollback_id,
            plan_digest=rollback_digest,
            origin_plan_id=origin_plan_id,
            origin_plan_digest=origin_plan_digest,
        )
        validation = self._authority_request(
            {
                "action": "validateArtifact",
                "planId": rollback_id,
                "planDigest": rollback_digest,
                "artifactId": previous_artifact,
            }
        )
        if (
            validation.get("planId") != rollback_id
            or validation.get("planDigest") != rollback_digest
            or validation.get("artifactId") != previous_artifact
            or validation.get("highestGeneration") != generation
            or validation.get("nextGeneration") != generation + 1
            or validation.get("currentGeneration") != status.get("currentGeneration")
        ):
            raise UpdateError(
                "AUTHORITY_PLAN_MISMATCH",
                "Authority rollback validation differs from the confirmed recovery plan.",
            )
        response = self._authority_request(
            {
                "action": "activateArtifact",
                "planId": rollback_id,
                "planDigest": rollback_digest,
                "expectedGeneration": generation,
                "artifactId": previous_artifact,
            }
        )
        after = self._authority_request({"action": "status"})
        if (
            after.get("activeArtifactId") != previous_artifact
            or not isinstance(after.get("highestGeneration"), int)
            or after["highestGeneration"] != generation + 1
            or response.get("planId") != rollback_id
            or response.get("planDigest") != rollback_digest
            or response.get("artifactId") != previous_artifact
            or response.get("currentGeneration") != after.get("currentGeneration")
            or response.get("highestGeneration") != after["highestGeneration"]
            or response.get("activationEpoch") != after.get("activationEpoch")
        ):
            raise UpdateError(
                "AUTHORITY_ROLLBACK_UNCONFIRMED",
                "Authority did not durably restore the previous artifact at a higher generation.",
            )
        activation["rollbackResponse"] = response
        activation["rollbackPlanId"] = rollback_id
        activation["rollbackPlanDigest"] = rollback_digest
        activation["rollbackGeneration"] = after["highestGeneration"]

    def _find_authority_artifact_plan_reference(self, artifact_id: str) -> tuple[str, str]:
        """Find a normal trusted plan reference that originally imported an artifact."""
        if not _valid_digest(artifact_id):
            raise UpdateError("INVALID_PLAN", "Authority artifact identity is invalid.")
        raw_hex = artifact_id.removeprefix("sha256:")
        metadata_directory = self.data_bundle_root / "metadata" / raw_hex
        plans_directory = metadata_directory / "plans"
        try:
            plans_info = plans_directory.lstat()
        except OSError as error:
            raise UpdateError(
                "AUTHORITY_ROLLBACK_UNAVAILABLE",
                "Previous Authority artifact has no imported plan references.",
            ) from error
        if (
            plans_directory.is_symlink()
            or not stat.S_ISDIR(plans_info.st_mode)
            or plans_info.st_uid != 0
            or stat.S_IMODE(plans_info.st_mode) & 0o022
        ):
            raise UpdateError("UNSAFE_DATA_BUNDLE_ROOT", "Authority plan metadata path is unsafe.")
        try:
            import grp

            authority_group_id = grp.getgrnam("cyrene-authority").gr_gid
        except (ImportError, KeyError) as error:
            raise UpdateError(
                "AUTHORITY_GROUP_MISSING", "The cyrene-authority group is required for rollback."
            ) from error

        manifest_path = metadata_directory / "component-manifest-v2.json"
        if manifest_path.is_symlink() or not manifest_path.is_file():
            raise UpdateError(
                "AUTHORITY_ROLLBACK_UNAVAILABLE", "Previous outer manifest metadata is unavailable."
            )
        self._validate_authority_metadata_file(manifest_path, authority_group_id)
        try:
            manifest = json.loads(manifest_path.read_bytes(), object_pairs_hook=_unique_json_object)
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "AUTHORITY_ROLLBACK_UNAVAILABLE", "Previous outer manifest metadata is invalid."
            ) from error
        if not isinstance(manifest, dict):
            raise UpdateError(
                "AUTHORITY_ROLLBACK_UNAVAILABLE", "Previous outer manifest metadata is invalid."
            )
        manifest_digest = manifest.get("manifestDigest")
        envelope = manifest.get("dataBundle")
        if (
            not _valid_digest(manifest_digest)
            or manifest_digest != _digest_json(manifest, "manifestDigest")
            or not isinstance(envelope, dict)
            or set(envelope) != {"proofPath", "proofSha256"}
            or not _valid_digest(envelope.get("proofSha256"))
        ):
            raise UpdateError(
                "AUTHORITY_ROLLBACK_UNAVAILABLE", "Previous outer manifest identity is invalid."
            )

        reference_fields = {
            "schemaVersion",
            "planId",
            "planDigest",
            "artifactId",
            "manifestDigest",
            "proofSha256",
        }
        for path in sorted(plans_directory.glob("*.json")):
            if path.is_symlink() or not path.is_file():
                continue
            self._validate_authority_metadata_file(path, authority_group_id)
            reference = _read_object(path, "Authority artifact plan reference")
            if (
                set(reference) != reference_fields
                or reference.get("schemaVersion") != 1
                or reference.get("planId") != path.stem
                or PLAN_ID_PATTERN.fullmatch(path.stem) is None
                or not _valid_digest(reference.get("planDigest"))
                or reference.get("artifactId") != artifact_id
                or reference.get("manifestDigest") != manifest_digest
                or reference.get("proofSha256") != envelope["proofSha256"]
            ):
                continue
            return path.stem, reference["planDigest"]
        raise UpdateError(
            "AUTHORITY_ROLLBACK_UNAVAILABLE",
            "Previous Authority artifact has no matching normal plan reference.",
        )

    def _persist_authority_rollback_plan_reference(
        self,
        artifact_id: str,
        *,
        plan_id: str,
        plan_digest: str,
        origin_plan_id: str,
        origin_plan_digest: str,
    ) -> None:
        """Bind a monotonic rollback plan to an already verified immutable artifact."""
        if (
            not _valid_digest(artifact_id)
            or re.fullmatch(r"[A-Za-z0-9._-]{1,128}", plan_id) is None
            or not _valid_digest(plan_digest)
            or PLAN_ID_PATTERN.fullmatch(origin_plan_id) is None
            or not _valid_digest(origin_plan_digest)
        ):
            raise UpdateError("INVALID_PLAN", "Authority rollback plan identity is invalid.")
        raw_hex = artifact_id.removeprefix("sha256:")
        metadata_directory = self.data_bundle_root / "metadata" / raw_hex
        manifest_path = metadata_directory / "component-manifest-v2.json"
        import_record_path = metadata_directory / "import-record-v1.json"
        for directory in (
            self.data_bundle_root,
            self.data_bundle_root / "metadata",
            metadata_directory,
        ):
            try:
                info = directory.lstat()
            except OSError as error:
                raise UpdateError(
                    "AUTHORITY_ROLLBACK_UNAVAILABLE",
                    "Previous Authority artifact import metadata is unavailable.",
                ) from error
            if (
                directory.is_symlink()
                or not stat.S_ISDIR(info.st_mode)
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) & 0o022
            ):
                raise UpdateError(
                    "UNSAFE_DATA_BUNDLE_ROOT", "Previous Authority artifact metadata is unsafe."
                )
        if (
            manifest_path.is_symlink()
            or not manifest_path.is_file()
            or import_record_path.is_symlink()
            or not import_record_path.is_file()
        ):
            raise UpdateError(
                "AUTHORITY_ROLLBACK_UNAVAILABLE",
                "Previous Authority artifact has no imported outer manifest metadata.",
            )
        try:
            import grp

            authority_group_id = grp.getgrnam("cyrene-authority").gr_gid
        except (ImportError, KeyError) as error:
            raise UpdateError(
                "AUTHORITY_GROUP_MISSING", "The cyrene-authority group is required for rollback."
            ) from error
        self._validate_authority_metadata_file(manifest_path, authority_group_id)
        self._validate_authority_metadata_file(import_record_path, authority_group_id)
        manifest_bytes = manifest_path.read_bytes()
        try:
            manifest = json.loads(manifest_bytes, object_pairs_hook=_unique_json_object)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "AUTHORITY_ROLLBACK_UNAVAILABLE", "Previous outer manifest metadata is invalid."
            ) from error
        import_record = _read_object(import_record_path, "Authority artifact import record")
        envelope = manifest.get("dataBundle") if isinstance(manifest, dict) else None
        artifact = manifest.get("artifact") if isinstance(manifest, dict) else None
        if (
            not isinstance(manifest, dict)
            or manifest.get("schemaVersion") != 2
            or manifest.get("manifestDigest") != _digest_json(manifest, "manifestDigest")
            or manifest.get("contentDigest") != artifact_id
            or not isinstance(artifact, dict)
            or artifact.get("kind") != "data-bundle"
            or artifact.get("sha256") != artifact_id
            or not isinstance(envelope, dict)
            or set(envelope) != {"proofPath", "proofSha256"}
            or envelope.get("proofPath") != "data-bundle-proof-v1.json"
            or not _valid_digest(envelope.get("proofSha256"))
            or import_record.get("artifactId") != artifact_id
            or import_record.get("manifestDigest") != manifest.get("manifestDigest")
        ):
            raise UpdateError(
                "AUTHORITY_ROLLBACK_UNAVAILABLE",
                "Previous Authority artifact manifest identity is not trustworthy.",
            )
        proof_path = self.data_bundle_root / "versions" / raw_hex / envelope["proofPath"]
        for directory in (self.data_bundle_root / "versions", proof_path.parent):
            try:
                info = directory.lstat()
            except OSError as error:
                raise UpdateError(
                    "AUTHORITY_ROLLBACK_UNAVAILABLE",
                    "Previous Authority artifact version directory is unavailable.",
                ) from error
            if (
                directory.is_symlink()
                or not stat.S_ISDIR(info.st_mode)
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) & 0o022
            ):
                raise UpdateError(
                    "UNSAFE_DATA_BUNDLE_ROOT", "Previous Authority artifact version path is unsafe."
                )
        if (
            proof_path.is_symlink()
            or not proof_path.is_file()
            or _file_digest(proof_path) != envelope["proofSha256"]
        ):
            raise UpdateError(
                "AUTHORITY_ROLLBACK_UNAVAILABLE",
                "Previous Authority artifact proof does not match its outer manifest.",
            )
        plans_directory = metadata_directory / "plans"
        plans_directory.mkdir(mode=0o750, exist_ok=True)
        info = plans_directory.lstat()
        if plans_directory.is_symlink() or not stat.S_ISDIR(info.st_mode) or info.st_uid != 0:
            raise UpdateError("UNSAFE_DATA_BUNDLE_ROOT", "Authority plan metadata path is unsafe.")
        os.chown(plans_directory, 0, authority_group_id)
        plans_directory.chmod(0o750)
        reference = {
            "schemaVersion": 1,
            "planId": plan_id,
            "planDigest": plan_digest,
            "artifactId": artifact_id,
            "manifestDigest": manifest["manifestDigest"],
            "proofSha256": envelope["proofSha256"],
            "action": "rollback",
            "originPlanId": origin_plan_id,
            "originPlanDigest": origin_plan_digest,
        }
        reference_path = plans_directory / f"{plan_id}.json"
        payload = (
            json.dumps(reference, ensure_ascii=False, sort_keys=True, indent=2).encode() + b"\n"
        )
        if reference_path.exists() or reference_path.is_symlink():
            self._validate_authority_metadata_file(reference_path, authority_group_id)
            if (
                reference_path.is_symlink()
                or _read_object(reference_path, "rollback plan reference") != reference
            ):
                raise UpdateError("DATA_BUNDLE_COLLISION", "Rollback plan reference differs.")
        else:
            self._write_authority_metadata(reference_path, payload)

    def _begin_maintenance(self, transaction: dict[str, Any]) -> str:
        request_id = _maintenance_request_id(transaction)
        params = {
            "request_id": request_id,
            "target_kind": transaction["targetKind"],
            "requires_restart": transaction.get("requiresRestart", True) is True,
            "expected_catalog_generation": transaction["expectedCatalogGeneration"],
            "expected_activity_sources": transaction["expectedActivitySources"],
            "expected_gate_generation": transaction["expectedGateGeneration"],
            "user_confirmed_restart": True,
            "plan_id": transaction["planId"],
            "plan_digest": transaction["planDigest"],
            "component_artifact_digests": transaction["componentArtifactDigests"],
        }
        try:
            result = self._broker_request("BeginMaintenance", params, request_id=request_id)
        except UpdateError as error:
            if error.code in {
                "ACTIVE_TASKS",
                "IDLE_RUNTIME_REQUIRES_UNLOAD",
                "MAINTENANCE_ACTIVE",
                "UNKNOWN",
                "STALE_READINESS",
                "CATALOG_GENERATION_MISMATCH",
                "GATE_GENERATION_MISMATCH",
                "USER_CONFIRMATION_REQUIRED",
                "REQUEST_ID_PLAN_MISMATCH",
                "INVALID_REQUEST",
                "INVALID_ARGUMENT",
                "UNAUTHORIZED",
            }:
                error.maintenance_not_acquired = True
            raise
        status = result.get("status")
        token = result.get("maintenance_token")
        blocker_codes = result.get("blocker_codes")
        gate_generation = result.get("gate_generation")
        known_statuses = BEGIN_NO_TOKEN_STATUSES | {"READY"}
        if (
            not isinstance(status, str)
            or status not in known_statuses
            or "maintenance_token" not in result
            or not isinstance(gate_generation, int)
            or isinstance(gate_generation, bool)
            or gate_generation < 0
            or not isinstance(blocker_codes, list)
            or any(not isinstance(code, str) for code in blocker_codes)
        ):
            raise UpdateError(
                "GATE_UNKNOWN",
                "Maintenance broker returned an unknown or malformed BeginMaintenance result; the update transaction remains recoverable.",
                retryable=True,
            )

        if status in BEGIN_NO_TOKEN_STATUSES and token is None:
            if status == "STALE_READINESS":
                raise UpdateError(
                    "STALE_READINESS",
                    "A runtime task or admission changed readiness before the maintenance gate was acquired; retry the same staged plan after activity settles.",
                    retryable=True,
                    maintenance_not_acquired=True,
                )
            if status == "USER_CONFIRMATION_REQUIRED":
                raise UpdateError(
                    "USER_CONFIRMATION_REQUIRED",
                    "The maintenance broker requires explicit confirmation before restarting this component; confirm this exact staged plan and retry.",
                    maintenance_not_acquired=True,
                )
            try:
                self._require_ready(
                    {"status": status, "active_tasks": result.get("active_tasks", [])},
                    transaction["targetKind"],
                )
            except UpdateError as error:
                error.maintenance_not_acquired = True
                raise
            raise UpdateError(
                "GATE_UNKNOWN",
                "Maintenance broker refused the BeginMaintenance request without a token; the update transaction remains recoverable.",
                retryable=True,
            )

        if status != "MAINTENANCE_ACTIVE":
            raise UpdateError(
                "GATE_UNKNOWN",
                "Maintenance broker did not confirm gate ownership; the update transaction remains recoverable.",
                retryable=True,
            )
        if not isinstance(token, str) or len(token) < 32:
            raise UpdateError(
                "GATE_UNKNOWN",
                "Maintenance broker did not return a durable transaction token.",
                retryable=True,
            )
        if transaction.get("schemaAdoption") is True:
            transaction["maintenanceGateGeneration"] = gate_generation
        return token

    def _clear_begin_pending(self, transaction: dict[str, Any], transaction_path: Path) -> None:
        """Remove only the local intent after the broker explicitly refused gate acquisition."""

        if not transaction_path.is_file() or transaction_path.is_symlink():
            return
        current = _read_object(transaction_path, "update transaction")
        if (
            current.get("phase") != "begin_pending"
            or current.get("planId") != transaction.get("planId")
            or current.get("planDigest") != transaction.get("planDigest")
        ):
            raise UpdateError(
                "TRANSACTION_CHANGED",
                "The updater journal changed while a maintenance request was refused.",
                retryable=True,
            )
        if transaction.get("transactionKind") == "workload-assembly.v1" and transaction.get(
            "maintenancePhase"
        ) in {
            "core-runtime-install",
            "package-only",
            "core-runtime-activate",
            "core-runtime-uninstall",
        }:
            phase = transaction["maintenancePhase"]
            holds = transaction.setdefault("maintenanceHolds", {})
            if not isinstance(holds, dict):
                raise UpdateError(
                    "INVALID_TRANSACTION", "Workload maintenance hold journal is malformed."
                )
            holds[phase] = {
                "requestId": _maintenance_request_id(transaction),
                "status": "not_acquired",
            }
            transaction["phase"] = "begin_pending"
            transaction.pop("maintenanceToken", None)
            _atomic_json(transaction_path, transaction)
            return
        transaction_path.unlink()
        self._fsync_directory(transaction_path.parent)

    def _end_maintenance(self, transaction: dict[str, Any], *, outcome: str, healthy: bool) -> None:
        token = transaction.get("maintenanceToken")
        if not isinstance(token, str):
            token = self._begin_maintenance(transaction)
        transaction_id = _maintenance_request_id(transaction)
        if transaction.get("transactionKind") == "workload-assembly.v1" and transaction.get(
            "maintenancePhase"
        ) in {
            "core-runtime-install",
            "package-only",
            "core-runtime-activate",
            "core-runtime-uninstall",
        }:
            request_id = (
                f"cyrene-workload-end-{transaction['maintenancePhase']}-"
                f"{transaction['planId']}-{outcome.lower()}"
            )
        else:
            request_id = f"cyrene-update-end-{transaction['planId']}-{outcome.lower()}"
        result = self._broker_request(
            "EndMaintenance",
            {
                "request_id": transaction_id,
                "target_kind": transaction["targetKind"],
                "maintenance_token": token,
                "outcome": outcome,
                "healthy": healthy,
            },
            request_id=request_id,
        )
        allowed = (
            {"READY", "SUCCESS", "ROLLED_BACK"} if healthy else {"MAINTENANCE_ACTIVE", "FAILED"}
        )
        if result.get("status") not in allowed:
            raise UpdateError(
                "GATE_END_FAILED",
                f"Maintenance broker did not release the gate: {result.get('status', 'unknown')}.",
                retryable=True,
            )

    def _activate_transaction(self, transaction: dict[str, Any]) -> None:
        for item in transaction["components"]:
            component = self.components[item["componentId"]]
            previous = next(
                old for old in transaction["previous"] if old["componentId"] == item["componentId"]
            )
            if component.get("kind") == "data-bundle":
                continue
            if component.get("pythonBundleService"):
                bundle = self._load_service_bundle()
                bundle_identity = item.get("bundleIdentity")
                if not _valid_digest(bundle_identity):
                    raise UpdateError(
                        "TRANSACTION_IDENTITY_UNKNOWN",
                        f"Staged Python bundle identity is missing for {item['componentId']}.",
                    )
                bundle.activate_release(
                    component["pythonBundleService"],
                    bundle_identity,
                    install_root=self.install_root,
                    expected_current_version=previous.get("bundleIdentity"),
                )
                self._write_active_receipt(item)
            else:
                pointer_identity = _native_release_pointer_identity(item)
                self._activate_native(
                    component["componentId"],
                    pointer_identity,
                    expected_current=previous.get("pointerIdentity"),
                )
                self._write_active_receipt(
                    {
                        **item,
                        "releaseIdentity": item.get("releaseIdentity", item.get("manifestDigest")),
                        "bundleIdentity": None,
                    }
                )

    def _activate_native(
        self, component_id: str, pointer_identity: str | None, *, expected_current: str | None
    ) -> None:
        root = self.install_root / "components" / component_id
        active = root / "active"
        current = self._active_native_pointer_identity(component_id)
        if current != expected_current:
            raise UpdateError(
                "ACTIVE_VERSION_CHANGED",
                f"Active {component_id} pointer changed since confirmation.",
                retryable=True,
            )
        if pointer_identity is not None:
            version, pointer_digest = _native_release_directory_identity(pointer_identity)
            if VERSION_PATTERN.fullmatch(version) is None or (
                pointer_digest is not None and len(pointer_digest) != 64
            ):
                raise UpdateError(
                    "TRANSACTION_IDENTITY_UNKNOWN",
                    f"Native {component_id} release pointer identity is invalid.",
                )
            release = root / "releases" / pointer_identity
            if release.is_symlink() or not release.is_dir():
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE",
                    f"Native {component_id} target release is missing or unsafe.",
                )
            manifest = _read_object(
                release / "component-manifest.json", f"{component_id} target release manifest"
            )
            expected_digest = (
                "sha256:" + pointer_digest
                if pointer_digest is not None
                else manifest.get("manifestDigest")
            )
            self._validate_manifest_digest(manifest, expected_digest)
            if manifest.get("componentId") != component_id or manifest.get("version") != version:
                raise UpdateError(
                    "INVALID_INSTALLED_RELEASE",
                    f"Native {component_id} pointer differs from its target manifest.",
                )
        temporary = root / f".active-{uuid.uuid4().hex}"
        try:
            if pointer_identity is None:
                self._remove_symlink_if_target(
                    active, f"releases/{current}" if current is not None else ""
                )
                return
            os.symlink(f"releases/{pointer_identity}", temporary)
            os.replace(temporary, active)
            self._fsync_directory(root)
        finally:
            if temporary.exists() or temporary.is_symlink():
                temporary.unlink()

    def _active_native_pointer_identity(self, component_id: str) -> str | None:
        active = self.install_root / "components" / component_id / "active"
        if not active.exists() and not active.is_symlink():
            return None
        if not active.is_symlink():
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE", f"Active pointer is not a symlink for {component_id}."
            )
        match = re.fullmatch(r"releases/([^/]+)", os.readlink(active))
        if match is None:
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Active pointer has an unsafe target for {component_id}.",
            )
        version, pointer_digest = _native_release_directory_identity(match.group(1))
        if VERSION_PATTERN.fullmatch(version) is None or (
            pointer_digest is not None and len(pointer_digest) != 64
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Active pointer identity is unsafe for {component_id}.",
            )
        return match.group(1)

    def _restart_order(self, transaction: dict[str, Any]) -> list[str]:
        restart_items: dict[str, tuple[int, int, str]] = {}
        if transaction["targetKind"] == "CORE_RUNTIME":
            for component in self.components.values():
                restart = component.get("restart", {})
                unit = restart.get("unit")
                if restart.get("group") == "core-runtime" and unit and self._unit_exists(component):
                    restart_items[unit] = (0, restart.get("order", 0), component["componentId"])
        for staged in transaction["components"]:
            component = self.components[staged["componentId"]]
            restart = component.get("restart", {})
            unit = restart.get("unit")
            if unit and restart.get("group") == "single-service":
                restart_items.setdefault(unit, (1, 0, component["componentId"]))
        return [unit for unit, _ in sorted(restart_items.items(), key=lambda item: item[1])]

    def _unit_exists(self, component: dict[str, Any]) -> bool:
        unit = self._catalog_matched_unit(component)
        if unit is None:
            return False
        for directory in self.systemd_unit_dirs:
            path = directory / unit
            try:
                info = path.lstat()
            except FileNotFoundError:
                continue
            except OSError:
                return False
            if (
                not stat.S_ISREG(info.st_mode)
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) & 0o022
            ):
                return False
            return component.get("kind") != "native-binary" or self._unit_uses_component_runner(
                path, component["componentId"]
            )
        return False

    @staticmethod
    def _catalog_matched_unit(component: dict[str, Any]) -> str | None:
        unit = component.get("systemdUnit")
        restart = component.get("restart")
        restart_unit = restart.get("unit") if isinstance(restart, dict) else None
        if (
            not isinstance(unit, str)
            or unit != restart_unit
            or re.fullmatch(r"[A-Za-z0-9_.@-]+\.service", unit) is None
        ):
            return None
        return unit

    @staticmethod
    def _unit_uses_component_runner(path: Path, component_id: str) -> bool:
        try:
            contents = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            return False
        for line in contents.splitlines():
            stripped = line.strip()
            if not stripped.startswith("ExecStart="):
                continue
            try:
                arguments = shlex.split(stripped.removeprefix("ExecStart="))
            except ValueError:
                return False
            if arguments[:3] == ["/usr/bin/cyrene", "component-run", component_id]:
                return True
        return False

    def _require_managed_services(self, staged_components: list[dict[str, Any]]) -> None:
        """Refuse activation before the gate when a selected service has no trusted host unit."""

        for staged in staged_components:
            component = self.components.get(staged.get("componentId"))
            if component is None or self._target_for(component) is None:
                raise UpdateError(
                    "SERVICE_NOT_MANAGED",
                    "The staged component has no supported, catalog-matched local service.",
                )
            if component.get("kind") == "data-bundle":
                if not self._authority_available():
                    raise UpdateError(
                        "AUTHORITY_NOT_MANAGED",
                        "Authority's restricted local activation socket is unavailable; data bundle remains staged.",
                    )
                continue
            if not self._unit_exists(component):
                raise UpdateError(
                    "SERVICE_NOT_MANAGED",
                    f"The OS target is available, but {component['componentId']} has no catalog-matched local systemd service; the plan remains staged.",
                )

    def _restart_transaction(self, transaction: dict[str, Any]) -> None:
        units = self._restart_order(transaction)
        for unit in units:
            self._run_systemctl("restart", unit)
            self._wait_unit_active(unit)

    def _health_transaction(self, transaction: dict[str, Any]) -> None:
        for item in transaction["components"]:
            manifest = item["manifest"]
            health = manifest.get("health")
            if not health:
                continue
            component = self.components[item["componentId"]]
            unit = component.get("systemdUnit") or component.get("restart", {}).get("unit")
            if health.get("kind") == "systemd-active" and unit:
                self._wait_unit_active(unit)
            elif health.get("kind") == "http":
                self._wait_http_health(health["port"], health["path"], item["componentId"])

    def _rollback_transaction(self, transaction: dict[str, Any]) -> tuple[bool, str]:
        try:
            for previous in transaction["previous"]:
                component = self.components[previous["componentId"]]
                if component.get("kind") == "data-bundle":
                    continue
                candidate = next(
                    item
                    for item in transaction["components"]
                    if item["componentId"] == previous["componentId"]
                )
                if component.get("pythonBundleService"):
                    active = (
                        self.install_root / "services" / component["pythonBundleService"] / "active"
                    )
                    current = self._active_python_pointer_identity(component["pythonBundleService"])
                    allowed_current = {
                        previous.get("bundleIdentity"),
                        candidate.get("bundleIdentity"),
                    }
                    if current not in allowed_current:
                        raise UpdateError(
                            "ROLLBACK_CONFLICT",
                            f"Active {previous['componentId']} bundle pointer is outside the transaction identities.",
                        )
                    expected_current = current
                    bundle_identity = previous.get("bundleIdentity")
                    if bundle_identity is None:
                        if current is not None:
                            self._remove_symlink_if_target(active, f"releases/{current}")
                    else:
                        self._load_service_bundle().activate_release(
                            component["pythonBundleService"],
                            bundle_identity,
                            install_root=self.install_root,
                            expected_current_version=expected_current,
                        )
                    self._restore_active_receipt(previous["componentId"], previous)
                else:
                    current = self._active_native_pointer_identity(previous["componentId"])
                    candidate_pointer = _native_release_pointer_identity(candidate)
                    if current not in {previous.get("pointerIdentity"), candidate_pointer}:
                        raise UpdateError(
                            "ROLLBACK_CONFLICT",
                            f"Active {previous['componentId']} native pointer is outside the transaction identities.",
                        )
                    self._activate_native(
                        previous["componentId"],
                        previous.get("pointerIdentity"),
                        expected_current=current,
                    )
                    self._restore_active_receipt(previous["componentId"], previous)
            self._restart_transaction(transaction)
            self._health_transaction(
                {
                    **transaction,
                    "components": [
                        {
                            **item,
                            "manifest": self._installed(self.components[item["componentId"]]).get(
                                "manifest"
                            )
                            or item["manifest"],
                        }
                        for item in transaction["components"]
                    ],
                }
            )
            self._rollback_authority_activation(transaction)
            return (
                True,
                "Prior active versions were restored and health-checked; gate may be released.",
            )
        except Exception as error:  # noqa: BLE001 - rollback must retain the gate for every unexpected failure.
            return False, f"Rollback could not be verified: {error}; maintenance gate remains held."

    def _schema_migrator_path(self, transaction: dict[str, Any]) -> Path:
        """Resolve the candidate Broker migrator from its staged signed file map."""
        broker = next(
            (
                item
                for item in transaction.get("components", [])
                if isinstance(item, dict)
                and item.get("componentId") == "cyrene-runtime-maintenance"
            ),
            None,
        )
        if not isinstance(broker, dict) or not isinstance(broker.get("manifest"), dict):
            raise UpdateError("SCHEMA_ADOPTION_UNKNOWN", "The staged Broker candidate is missing.")
        artifact = broker["manifest"].get("artifact")
        if not isinstance(artifact, dict):
            raise UpdateError("SCHEMA_ADOPTION_UNKNOWN", "The staged Broker artifact is malformed.")
        entrypoint = artifact.get("entrypoint")
        files = artifact.get("files")
        if not isinstance(entrypoint, str) or not isinstance(files, dict):
            raise UpdateError("SCHEMA_ADOPTION_UNKNOWN", "The staged Broker file map is malformed.")
        relative = _safe_relative(entrypoint, field="Broker migration entrypoint")
        expected = files.get(relative.as_posix())
        if not _valid_digest(expected):
            raise UpdateError(
                "SCHEMA_ADOPTION_UNKNOWN", "The staged Broker entrypoint is not signed."
            )
        release = Path(broker["releasePath"])
        directories = [self.install_root, self.install_root / "components"]
        component_root = self.install_root / "components" / "cyrene-runtime-maintenance"
        directories.extend((component_root, component_root / "releases", release))
        current = release
        for part in relative.parts[:-1]:
            current = current / part
            directories.append(current)
        for directory in directories:
            try:
                info = directory.lstat()
            except OSError as error:
                raise UpdateError(
                    "SCHEMA_ADOPTION_UNKNOWN", "Staged Broker path is unavailable."
                ) from error
            if (
                not stat.S_ISDIR(info.st_mode)
                or info.st_uid != 0
                or stat.S_IMODE(info.st_mode) & 0o022
            ):
                raise UpdateError("SCHEMA_ADOPTION_UNKNOWN", "Staged Broker path is unsafe.")
        executable = release.joinpath(*relative.parts)
        try:
            info = executable.lstat()
            digest = _file_digest(executable)
        except OSError as error:
            raise UpdateError(
                "SCHEMA_ADOPTION_UNKNOWN", "Staged Broker executable is unavailable."
            ) from error
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_uid != 0
            or info.st_nlink != 1
            or stat.S_IMODE(info.st_mode) & 0o022
            or not stat.S_IMODE(info.st_mode) & 0o111
            or digest != expected
        ):
            raise UpdateError(
                "SCHEMA_ADOPTION_UNKNOWN",
                "Staged Broker executable failed signed-file verification.",
            )
        return executable

    def _run_schema_migrator(
        self, transaction: dict[str, Any], operation: str, proof_path: Path
    ) -> dict[str, Any]:
        if operation not in {"migrate-state", "rollback-state"}:
            raise UpdateError(
                "SCHEMA_ADOPTION_INVALID", "Unsupported internal migration operation."
            )
        command = [
            str(self._schema_migrator_path(transaction)),
            operation,
            "--state-dir",
            "/var/lib/cyrene/runtime",
            "--maintenance-proof-file",
            str(proof_path),
        ]
        try:
            completed = self.runner(
                command,
                capture_output=True,
                text=True,
                timeout=300,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired) as error:
            raise UpdateError(
                "SCHEMA_MIGRATION_UNKNOWN",
                f"The signed Broker {operation} command did not return a known result.",
                retryable=True,
            ) from error
        if completed.returncode != 0:
            detail = completed.stderr.strip() or completed.stdout.strip() or "unknown failure"
            raise UpdateError(
                "SCHEMA_MIGRATION_FAILED",
                f"The signed Broker {operation} command refused the transaction: {detail}",
                retryable=True,
            )
        lines = completed.stdout.splitlines()
        if len(lines) != 1:
            raise UpdateError("SCHEMA_MIGRATION_UNKNOWN", "Broker migration output is malformed.")
        try:
            result = json.loads(lines[0])
        except json.JSONDecodeError as error:
            raise UpdateError(
                "SCHEMA_MIGRATION_UNKNOWN", "Broker migration output is not JSON."
            ) from error
        return result if isinstance(result, dict) else {}

    def _schema_migration_proof(self, transaction: dict[str, Any]) -> tuple[dict[str, Any], Path]:
        helper = self._load_native_runtime_schema_migration()
        try:
            proof = helper.create_migration_proof(transaction, transaction.get("schema1Profile"))
        except helper.MigrationError as error:
            raise UpdateError("SCHEMA_ADOPTION_UNKNOWN", str(error), retryable=True) from error
        proof_path = (
            self._private_state_directory("transactions")
            / f"{transaction['planId']}.migration-proof.json"
        )
        if proof_path.exists() or proof_path.is_symlink():
            existing = _read_object(proof_path, "Core schema migration proof")
            if existing != proof:
                raise UpdateError(
                    "SCHEMA_ADOPTION_UNKNOWN",
                    "Persisted migration proof differs from the confirmed plan.",
                )
        else:
            _atomic_json(proof_path, proof, mode=0o600)
        _verify_private_file(proof_path)
        return proof, proof_path

    def _validate_schema_adoption_transaction(self, transaction: dict[str, Any]) -> None:
        helper = self._load_native_runtime_schema_migration()
        staged = transaction.get("components")
        if not isinstance(staged, list) or {
            item.get("componentId") for item in staged if isinstance(item, dict)
        } != set(helper.NATIVE_GROUP_MEMBERS):
            raise UpdateError(
                "TRANSACTION_IDENTITY_UNKNOWN", "Schema-adoption candidate set changed."
            )
        inventory = transaction.get("preActiveUnits")
        if not isinstance(inventory, list):
            raise UpdateError(
                "TRANSACTION_IDENTITY_UNKNOWN", "Schema-adoption unit inventory is missing."
            )
        known_units: set[str] = set()
        for row in inventory:
            if not isinstance(row, dict) or set(row) != {
                "unit",
                "componentId",
                "unitFileState",
                "active",
            }:
                raise UpdateError(
                    "TRANSACTION_IDENTITY_UNKNOWN", "Schema-adoption unit inventory is malformed."
                )
            component = self.components.get(row.get("componentId"))
            unit = self._catalog_matched_unit(component) if isinstance(component, dict) else None
            if (
                not isinstance(row.get("unit"), str)
                or row["unit"] != unit
                or row["unit"] in known_units
                or not isinstance(row.get("unitFileState"), str)
                or type(row.get("active")) is not bool
            ):
                raise UpdateError(
                    "TRANSACTION_IDENTITY_UNKNOWN",
                    "Schema-adoption unit inventory identity changed.",
                )
            known_units.add(row["unit"])
        if transaction.get("schema1Profile") not in helper.SCHEMA1_PROFILES:
            raise UpdateError("TRANSACTION_IDENTITY_UNKNOWN", "Schema-adoption profile is invalid.")
        if (
            transaction.get("targetKind") != "CORE_RUNTIME"
            or transaction.get("schemaAdoption") is not True
        ):
            raise UpdateError(
                "TRANSACTION_IDENTITY_UNKNOWN", "Schema-adoption transaction identity is invalid."
            )

    def _execute_schema_adoption(
        self, transaction: dict[str, Any], transaction_path: Path
    ) -> dict[str, Any]:
        """Apply the exact held schema migration, then start and verify the complete C10 cohort."""
        self._validate_schema_adoption_transaction(transaction)
        helper = self._load_native_runtime_schema_migration()
        _, proof_path = self._schema_migration_proof(transaction)
        try:
            if transaction.get("migrationPhase") in {"planned", "quiesce_pending"}:
                transaction["migrationPhase"] = "quiesce_pending"
                _atomic_json(transaction_path, transaction)
                helper.stop_captured_units(self, transaction["preActiveUnits"])
                transaction["migrationPhase"] = "quiesced"
                _atomic_json(transaction_path, transaction)

            if transaction.get("migrationPhase") in {"quiesced", "migrate_pending"}:
                transaction["migrationPhase"] = "migrate_pending"
                _atomic_json(transaction_path, transaction)
                result = self._run_schema_migrator(transaction, "migrate-state", proof_path)
                if (
                    result.get("migrated") is not True
                    or result.get("schema_version") != 2
                    or type(result.get("gate_generation")) is not int
                    or result.get("gate_generation") != transaction.get("maintenanceGateGeneration")
                    or type(result.get("catalog_generation")) is not int
                    or result.get("catalog_generation")
                    != transaction.get("expectedCatalogGeneration")
                    or not isinstance(result.get("migration_id"), str)
                    or not result["migration_id"]
                ):
                    raise UpdateError(
                        "SCHEMA_MIGRATION_UNKNOWN",
                        "Broker did not confirm the exact schema-2 migration.",
                    )
                transaction["migrationId"] = result["migration_id"]
                transaction["migrationPhase"] = "migrated"
                _atomic_json(transaction_path, transaction)

            if transaction.get("migrationPhase") in {"migrated", "activation_pending"}:
                transaction["migrationPhase"] = "activation_pending"
                _atomic_json(transaction_path, transaction)
                self._activate_schema_adoption_candidates(transaction)
                transaction["migrationPhase"] = "candidate_active"
                _atomic_json(transaction_path, transaction)

            if transaction.get("migrationPhase") in {"candidate_active", "core_start_pending"}:
                transaction["migrationPhase"] = "core_start_pending"
                _atomic_json(transaction_path, transaction)
                for unit in helper.start_core_unit_order(self, transaction["preActiveUnits"]):
                    self._run_systemctl("start", unit)
                    self._wait_unit_active(unit)
                self._validate_schema2_core_health(transaction)
                transaction["migrationPhase"] = "core_healthy"
                _atomic_json(transaction_path, transaction)

            if transaction.get("migrationPhase") not in {"core_healthy", "success_end_pending"}:
                raise UpdateError(
                    "SCHEMA_ADOPTION_UNKNOWN", "Schema-adoption journal phase is unsupported."
                )
        except Exception as failure:
            healthy, message = self._rollback_schema_adoption(
                transaction, transaction_path, proof_path
            )
            transaction["phase"] = "rollback_end_pending" if healthy else "rollback_required"
            transaction["migrationPhase"] = (
                "rollback_end_pending" if healthy else "rollback_required"
            )
            transaction["rollbackHealthy"] = healthy
            transaction["rollbackMessage"] = message
            _atomic_json(transaction_path, transaction)
            if not healthy:
                raise UpdateError(
                    "SCHEMA_ROLLBACK_REQUIRED",
                    f"Schema adoption failed ({failure}); {message}",
                    retryable=True,
                ) from failure
            try:
                self._end_maintenance(transaction, outcome="ROLLED_BACK", healthy=True)
            except UpdateError as end_error:
                transaction["recoveryError"] = str(end_error)
                _atomic_json(transaction_path, transaction)
                raise UpdateError(
                    "SCHEMA_ROLLBACK_GATE_HELD",
                    f"Schema adoption failed ({failure}); rollback is verified but the maintenance hold remains active: {end_error}",
                    retryable=True,
                ) from failure
            transaction["phase"] = "rollback_clients_pending"
            transaction["migrationPhase"] = "rollback_clients_pending"
            _atomic_json(transaction_path, transaction)
            self._restore_previously_active_clients(transaction, core_only=False)
            transaction["phase"] = "rolled_back"
            transaction["migrationPhase"] = "rolled_back"
            transaction.pop("maintenanceToken", None)
            _atomic_json(transaction_path, transaction)
            raise UpdateError(
                "SCHEMA_ADOPTION_ROLLED_BACK", f"Schema adoption failed ({failure}). {message}"
            ) from failure
        return self._complete_schema_adoption(transaction, transaction_path)

    def _complete_schema_adoption(
        self, transaction: dict[str, Any], transaction_path: Path
    ) -> dict[str, Any]:
        transaction["phase"] = "success_end_pending"
        transaction["migrationPhase"] = "success_end_pending"
        _atomic_json(transaction_path, transaction)
        self._validate_schema2_core_health(transaction)
        expected = {item["componentId"]: item for item in transaction["components"]}
        current = {
            item["componentId"]: item
            for item in self._capture_active_versions(transaction["components"])
        }
        if not self._same_release_identities(expected, current, require_attested=True):
            raise UpdateError(
                "TRANSACTION_STATE_MISMATCH",
                "C10 active receipt set differs from the confirmed adoption plan.",
                retryable=True,
            )
        readiness = self._readiness_for("CORE_RUNTIME", requires_restart=True, force=True)
        if readiness.get("status") == "MAINTENANCE_ACTIVE":
            self._end_maintenance(transaction, outcome="SUCCESS", healthy=True)
        elif readiness.get("status") != "READY":
            raise UpdateError(
                "GATE_UNKNOWN",
                "Cannot reconcile C10 maintenance completion while Broker state is unknown.",
                retryable=True,
            )
        transaction["phase"] = "clients_restore_pending"
        transaction["migrationPhase"] = "clients_restore_pending"
        _atomic_json(transaction_path, transaction)
        self._restore_previously_active_clients(transaction, core_only=False)
        transaction["phase"] = "succeeded"
        transaction["migrationPhase"] = "complete"
        transaction.pop("maintenanceToken", None)
        transaction.pop("recoveryError", None)
        _atomic_json(transaction_path, transaction)
        return self._applied_result(transaction)

    def _recover_schema_adoption(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        confirmation: dict[str, Any],
    ) -> dict[str, Any]:
        if transaction.get("planId") != confirmation.get("planId") or transaction.get(
            "planDigest"
        ) != confirmation.get("planDigest"):
            raise UpdateError(
                "TRANSACTION_MISMATCH",
                "Pending schema adoption belongs to a different confirmed plan.",
            )
        if not _running_as_root():
            raise UpdateError(
                "PRIVILEGE_REQUIRED", "Schema adoption recovery requires the root updater."
            )
        self._validate_recovery_identity(transaction)
        self._validate_schema_adoption_transaction(transaction)
        phase = transaction.get("migrationPhase")
        if phase in {"success_end_pending", "clients_restore_pending"}:
            return self._complete_schema_adoption(transaction, transaction_path)
        if phase in {
            "rollback_required",
            "rollback_migration_pending",
            "rollback_state_restored",
            "rollback_activation_pending",
            "rollback_core_start_pending",
        }:
            _, proof_path = self._schema_migration_proof(transaction)
            healthy, message = self._rollback_schema_adoption(
                transaction, transaction_path, proof_path
            )
            if not healthy:
                transaction["phase"] = "rollback_required"
                transaction["migrationPhase"] = "rollback_required"
                transaction["rollbackMessage"] = message
                _atomic_json(transaction_path, transaction)
                raise UpdateError("SCHEMA_ROLLBACK_REQUIRED", message, retryable=True)
            transaction["phase"] = "rollback_end_pending"
            transaction["migrationPhase"] = "rollback_end_pending"
            transaction["rollbackHealthy"] = True
            transaction["rollbackMessage"] = message
            _atomic_json(transaction_path, transaction)
            return self._finish_schema_rollback(transaction, transaction_path)
        if phase in {"rollback_end_pending", "rollback_clients_pending"}:
            expected_previous = {
                item["componentId"]: item for item in transaction.get("previous", [])
            }
            current_previous = {
                item["componentId"]: item
                for item in self._capture_active_versions(transaction["components"])
            }
            if not self._same_release_identities(
                expected_previous, current_previous, require_attested=False
            ):
                raise UpdateError(
                    "TRANSACTION_STATE_MISMATCH",
                    "Restored C9 receipts differ from the recorded rollback identities.",
                    retryable=True,
                )
            self._validate_legacy_core_health(transaction)
            if phase == "rollback_end_pending":
                readiness = self._readiness_for("CORE_RUNTIME", requires_restart=True, force=True)
                if readiness.get("status") == "MAINTENANCE_ACTIVE":
                    self._end_maintenance(transaction, outcome="ROLLED_BACK", healthy=True)
                elif readiness.get("status") != "READY":
                    raise UpdateError(
                        "GATE_UNKNOWN",
                        "Cannot reconcile schema rollback while Broker state is unknown.",
                        retryable=True,
                    )
                transaction["phase"] = "rollback_clients_pending"
                transaction["migrationPhase"] = "rollback_clients_pending"
                _atomic_json(transaction_path, transaction)
            return self._finish_schema_rollback(transaction, transaction_path)
        if phase == "planned" and transaction.get("phase") == "begin_pending":
            try:
                transaction["maintenanceToken"] = self._begin_maintenance(transaction)
            except UpdateError as error:
                if error.maintenance_not_acquired:
                    self._clear_begin_pending(transaction, transaction_path)
                raise
            transaction["phase"] = "applying"
            _atomic_json(transaction_path, transaction)
        return self._execute_schema_adoption(transaction, transaction_path)

    def _finish_schema_rollback(self, transaction: dict[str, Any], transaction_path: Path) -> None:
        self._restore_previously_active_clients(transaction, core_only=False)
        transaction["phase"] = "rolled_back"
        transaction["migrationPhase"] = "rolled_back"
        transaction.pop("maintenanceToken", None)
        _atomic_json(transaction_path, transaction)
        raise UpdateError(
            "INTERRUPTED_UPDATE_ROLLED_BACK",
            transaction.get("rollbackMessage", "Schema adoption was rolled back."),
        )

    def _activate_schema_adoption_candidates(self, transaction: dict[str, Any]) -> None:
        previous = {item["componentId"]: item for item in transaction["previous"]}
        for item in transaction["components"]:
            component_id = item["componentId"]
            current = self._active_native_pointer_identity(component_id)
            candidate_pointer = item["pointerIdentity"]
            old_pointer = previous[component_id].get("pointerIdentity")
            if current == candidate_pointer:
                installed = self._installed(self.components[component_id])
                if installed.get("manifestDigest") != item["manifestDigest"]:
                    raise UpdateError(
                        "TRANSACTION_STATE_MISMATCH",
                        f"Active {component_id} receipt differs from the candidate.",
                    )
                continue
            if current != old_pointer:
                raise UpdateError(
                    "TRANSACTION_STATE_MISMATCH",
                    f"Active {component_id} pointer changed outside the confirmed plan.",
                )
            self._activate_native(component_id, candidate_pointer, expected_current=old_pointer)
            self._write_active_receipt(item)

    def _validate_schema2_core_health(self, transaction: dict[str, Any]) -> None:
        result = self._broker_request("Health", {})
        required = {
            "cyrene.runtime-maintenance.state.v2",
            "cyrene.runtime-maintenance.binding-operations.v1",
        }
        capabilities = result.get("capabilities")
        if (
            result.get("status") != "SERVING"
            or result.get("protocol_version") != "cyrene.runtime-maintenance.broker.v1"
            or result.get("catalog_generation") != transaction.get("expectedCatalogGeneration")
            or result.get("gate_generation") != transaction.get("maintenanceGateGeneration")
            or not isinstance(capabilities, list)
            or any(not isinstance(value, str) or not value for value in capabilities)
            or len(capabilities) != len(set(capabilities))
            or not required.issubset(capabilities)
        ):
            raise UpdateError(
                "SCHEMA_CORE_HEALTH_UNKNOWN",
                "The C10 Broker did not prove schema-2 and binding-operation readiness.",
                retryable=True,
            )
        helper = self._load_native_package_runtime_bootstrap()
        catalog, _sources = self._activity_catalog()
        if catalog.get("generation") != transaction.get("expectedCatalogGeneration"):
            raise UpdateError(
                "SCHEMA_CORE_HEALTH_UNKNOWN",
                "The activity catalog generation changed during Core activation.",
                retryable=True,
            )
        try:
            helper.probe_runtime_authority(
                catalog, expected_catalog_generation=transaction["expectedCatalogGeneration"]
            )
        except Exception as error:
            raise UpdateError(
                "SCHEMA_CORE_HEALTH_UNKNOWN",
                "Package Runtime did not prove source-authenticated C10 readiness.",
                retryable=True,
            ) from error

    def _rollback_schema_adoption(
        self, transaction: dict[str, Any], transaction_path: Path, proof_path: Path
    ) -> tuple[bool, str]:
        helper = self._load_native_runtime_schema_migration()
        try:
            for item in transaction["components"]:
                unit = self._catalog_matched_unit(self.components[item["componentId"]])
                if unit:
                    self._run_systemctl("stop", unit)
                    helper._wait_unit_stopped(self, unit)
            helper.stop_captured_units(self, transaction["preActiveUnits"])
            if transaction.get("migrationPhase") in {
                "migrate_pending",
                "migrated",
                "activation_pending",
                "candidate_active",
                "core_start_pending",
                "core_healthy",
                "success_end_pending",
                "rollback_required",
                "rollback_migration_pending",
                "rollback_state_restored",
                "rollback_activation_pending",
                "rollback_core_start_pending",
            }:
                transaction["migrationPhase"] = "rollback_migration_pending"
                _atomic_json(transaction_path, transaction)
                result = self._run_schema_migrator(transaction, "rollback-state", proof_path)
                if result.get("schema_version") != 1 or result.get("rolled_back") is not True:
                    raise UpdateError(
                        "SCHEMA_ROLLBACK_UNKNOWN",
                        "Broker did not confirm restoration of the schema-1 state.",
                    )
                transaction["migrationPhase"] = "rollback_state_restored"
                _atomic_json(transaction_path, transaction)
            transaction["migrationPhase"] = "rollback_activation_pending"
            _atomic_json(transaction_path, transaction)
            previous = {item["componentId"]: item for item in transaction["previous"]}
            for item in transaction["components"]:
                component_id = item["componentId"]
                prior = previous[component_id]
                current = self._active_native_pointer_identity(component_id)
                candidate_pointer = item["pointerIdentity"]
                old_pointer = prior.get("pointerIdentity")
                if current not in {candidate_pointer, old_pointer}:
                    raise UpdateError(
                        "TRANSACTION_STATE_MISMATCH",
                        f"Active {component_id} pointer cannot be reconciled.",
                    )
                if current != old_pointer:
                    self._activate_native(component_id, old_pointer, expected_current=current)
                self._restore_active_receipt(component_id, prior)
                _atomic_json(transaction_path, transaction)
            transaction["migrationPhase"] = "rollback_core_start_pending"
            _atomic_json(transaction_path, transaction)
            self._restore_previously_active_clients(transaction, core_only=True)
            self._validate_legacy_core_health(transaction)
            return (
                True,
                "The signed prior Core cohort and schema-1 state were restored and verified.",
            )
        except Exception as error:  # noqa: BLE001 - any uncertainty must keep the hold active.
            return (
                False,
                f"Schema rollback could not be verified: {error}; maintenance remains held.",
            )

    def _validate_legacy_source_identity(self, component_id: str, manifest: dict[str, Any]) -> None:
        """Check source fields on a C9 manifest whose digest was verified before adoption."""

        component = self.components[component_id]
        repository = component.get("publisher")
        publisher = self.publishers.get(repository)
        channel = manifest.get("channel")
        source = manifest.get("source")
        provenance = manifest.get("provenance")
        attestation = provenance.get("attestation") if isinstance(provenance, dict) else None
        channels = self.catalog.get("channels")
        channel_config = channels.get(channel) if isinstance(channels, dict) else None
        source_refs = channel_config.get("sourceRefs") if isinstance(channel_config, dict) else None
        source_commit = source.get("commit") if isinstance(source, dict) else None
        source_ref = source.get("ref") if isinstance(source, dict) else None
        workflow = publisher.get("workflow") if isinstance(publisher, dict) else None
        if (
            not isinstance(repository, str)
            or not isinstance(publisher, dict)
            or publisher.get("repository") != repository
            or not isinstance(workflow, str)
            or channel not in {"stable", "preview"}
            or not isinstance(source_refs, list)
            or source_ref not in source_refs
            or not isinstance(source_commit, str)
            or re.fullmatch(r"[0-9a-f]{40}", source_commit) is None
            or not isinstance(source, dict)
            or source.get("repository") != f"https://github.com/{repository}"
            or not isinstance(attestation, dict)
            or attestation.get("kind") != "github-artifact-attestation"
            or attestation.get("repository") != repository
            or attestation.get("workflow") != workflow
            or attestation.get("predicateType") != "https://slsa.dev/provenance/v1"
            or attestation.get("run") is None
        ):
            raise UpdateError(
                "SCHEMA_ROLLBACK_UNKNOWN",
                f"Restored C9 {component_id} source identity is not pinned.",
                retryable=True,
            )

    def _validate_restored_legacy_core_identity(self, transaction: dict[str, Any]) -> Path:
        """Reconcile the signed C9 cohort and running Broker before accepting legacy health."""

        self._validate_schema_adoption_transaction(transaction)
        self._validate_recovery_identity(transaction)
        previous = {
            item["componentId"]: item
            for item in transaction.get("previous", [])
            if isinstance(item, dict) and isinstance(item.get("componentId"), str)
        }
        current = {
            item["componentId"]: item
            for item in self._capture_active_versions(transaction["components"])
        }
        if not self._same_release_identities(previous, current, require_attested=False):
            raise UpdateError(
                "SCHEMA_ROLLBACK_UNKNOWN",
                "Restored C9 release pointers differ from the transaction's prior identities.",
                retryable=True,
            )

        migration = self._load_native_runtime_schema_migration()
        for component_id in (
            "cyrene-runtime-maintenance",
            "cyrene-kernel",
            "cy-package-runtime",
        ):
            prior = previous.get(component_id)
            if prior is None or prior.get("version") is None:
                continue
            if component_id in {BROKER_COMPONENT_ID, "cyrene-kernel"} and (
                prior.get("identityAttested") is not True
            ):
                raise UpdateError(
                    "SCHEMA_ROLLBACK_UNKNOWN",
                    f"Restored C9 {component_id} prior receipt was not attested.",
                    retryable=True,
                )
            component = self.components.get(component_id)
            installed = self._installed(component) if isinstance(component, dict) else None
            manifest = installed.get("manifest") if isinstance(installed, dict) else None
            if (
                not isinstance(component, dict)
                or not isinstance(installed, dict)
                or installed.get("active") is not True
                or installed.get("identityAttested") is not True
                or not isinstance(manifest, dict)
                or type(manifest.get("schemaVersion")) is not int
                or manifest.get("schemaVersion") != 1
                or "compatibility" in manifest
                or manifest.get("manifestDigest") != prior.get("manifestDigest")
                or manifest.get("version") != prior.get("version")
            ):
                raise UpdateError(
                    "SCHEMA_ROLLBACK_UNKNOWN",
                    f"Restored C9 {component_id} receipt or manifest identity is unknown.",
                    retryable=True,
                )
            target = self._target_for(component)
            if target is None or manifest.get("target") != target.get("target"):
                raise UpdateError(
                    "SCHEMA_ROLLBACK_UNKNOWN",
                    f"Restored C9 {component_id} target identity is not supported.",
                    retryable=True,
                )
            self._validate_legacy_source_identity(component_id, manifest)
            try:
                migration.verify_active_native_payload(self, component_id)
            except Exception as error:
                raise UpdateError(
                    "SCHEMA_ROLLBACK_UNKNOWN",
                    f"Restored C9 {component_id} payload did not match its verified receipt.",
                    retryable=True,
                ) from error

        broker_id = BROKER_COMPONENT_ID
        broker_component = self.components[broker_id]
        broker = self._installed(broker_component)
        broker_manifest = broker.get("manifest")
        broker_unit = self._catalog_matched_unit(broker_component)
        inventory = transaction.get("preActiveUnits")
        prior_broker_units = (
            [
                row
                for row in inventory
                if isinstance(row, dict)
                and row.get("componentId") == broker_id
                and row.get("unit") == broker_unit
            ]
            if isinstance(inventory, list)
            else []
        )
        if (
            broker.get("active") is not True
            or broker.get("identityAttested") is not True
            or not isinstance(broker_manifest, dict)
            or type(broker_manifest.get("schemaVersion")) is not int
            or broker_manifest.get("schemaVersion") != 1
            or not isinstance(broker_unit, str)
            or transaction.get("targetKind") != "CORE_RUNTIME"
            or not isinstance(transaction.get("maintenanceToken"), str)
            or len(transaction.get("maintenanceToken", "")) < 32
            or len(prior_broker_units) != 1
            or prior_broker_units[0].get("active") is not True
            or not self._unit_exists(broker_component)
        ):
            raise UpdateError(
                "SCHEMA_ROLLBACK_UNKNOWN",
                "Restored C9 Broker unit or signed release identity is unknown.",
                retryable=True,
            )
        executable = self._resolve_installed_broker()
        self._validate_active_legacy_broker_process(broker_unit, executable, broker_manifest)
        return executable

    def _validate_active_legacy_broker_process(
        self, unit: str, executable: Path, manifest: dict[str, Any]
    ) -> None:
        """Require the restored Broker unit PID to run its verified C9 executable."""

        try:
            completed = self.runner(
                [
                    "systemctl",
                    "show",
                    unit,
                    "--property=ActiveState",
                    "--property=SubState",
                    "--property=MainPID",
                ],
                capture_output=True,
                text=True,
                timeout=10,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired) as error:
            raise UpdateError(
                "SCHEMA_ROLLBACK_UNKNOWN",
                "Cannot inspect the restored C9 Broker service process.",
                retryable=True,
            ) from error
        properties: dict[str, str] = {}
        for line in completed.stdout.splitlines():
            key, separator, value = line.partition("=")
            if separator and key in {"ActiveState", "SubState", "MainPID"}:
                if key in properties:
                    raise UpdateError(
                        "SCHEMA_ROLLBACK_UNKNOWN",
                        "Restored C9 Broker service process identity is malformed.",
                        retryable=True,
                    )
                properties[key] = value
        pid_text = properties.get("MainPID")
        if (
            completed.returncode != 0
            or set(properties) != {"ActiveState", "SubState", "MainPID"}
            or properties.get("ActiveState") != "active"
            or properties.get("SubState") != "running"
            or not isinstance(pid_text, str)
            or not pid_text.isdecimal()
            or int(pid_text) <= 1
        ):
            raise UpdateError(
                "SCHEMA_ROLLBACK_UNKNOWN",
                "Restored C9 Broker service is not confirmed active with a MainPID.",
                retryable=True,
            )
        artifact = manifest.get("artifact")
        files = artifact.get("files") if isinstance(artifact, dict) else None
        entrypoint = artifact.get("entrypoint") if isinstance(artifact, dict) else None
        expected_digest = files.get(entrypoint) if isinstance(files, dict) else None
        proc_exe = Path("/proc") / pid_text / "exe"
        try:
            executable_link = os.readlink(proc_exe)
            executable_info = proc_exe.stat()
            executable_digest = _file_digest(proc_exe)
        except OSError as error:
            raise UpdateError(
                "SCHEMA_ROLLBACK_UNKNOWN",
                "Cannot verify the restored C9 Broker executable.",
                retryable=True,
            ) from error
        if (
            not isinstance(expected_digest, str)
            or not _valid_digest(expected_digest)
            or executable_link.endswith(" (deleted)")
            or Path(executable_link) != executable
            or not stat.S_ISREG(executable_info.st_mode)
            or executable_digest != expected_digest
        ):
            raise UpdateError(
                "SCHEMA_ROLLBACK_UNKNOWN",
                "Restored C9 Broker PID does not run its receipt-pinned executable.",
                retryable=True,
            )

    def _validate_legacy_core_health(self, transaction: dict[str, Any]) -> None:
        self._validate_restored_legacy_core_identity(transaction)
        result = self._broker_request("Health", {})
        required_fields = {
            "status",
            "core_bootstrap_eligible",
            "catalog_generation",
            "gate_generation",
        }
        if (
            set(result) != required_fields
            or result.get("status") != "SERVING"
            or type(result.get("core_bootstrap_eligible")) is not bool
            or type(result.get("catalog_generation")) is not int
            or type(result.get("gate_generation")) is not int
            or type(transaction.get("expectedCatalogGeneration")) is not int
            or type(transaction.get("maintenanceGateGeneration")) is not int
            or result.get("catalog_generation") != transaction.get("expectedCatalogGeneration")
            or result.get("gate_generation") != transaction.get("maintenanceGateGeneration")
        ):
            raise UpdateError(
                "SCHEMA_ROLLBACK_UNKNOWN",
                "Restored C9 Broker health is unknown or does not match its held generations.",
                retryable=True,
            )

    def _restore_previously_active_clients(
        self, transaction: dict[str, Any], *, core_only: bool
    ) -> None:
        rows = transaction.get("preActiveUnits", [])
        selected = []
        for row in rows:
            if not row.get("active"):
                continue
            component = self.components[row["componentId"]]
            is_core = component.get("restart", {}).get("group") == "core-runtime"
            if is_core != core_only:
                continue
            if core_only:
                selected.append(row)
            else:
                selected.append(row)
        if core_only:
            selected.sort(
                key=lambda row: (
                    25
                    if row["componentId"] == "cyrene-runtime-maintenance"
                    else 30
                    if row["componentId"] == "cyrene-kernel"
                    else int(
                        self.components[row["componentId"]].get("restart", {}).get("order", 50)
                    ),
                    row["unit"],
                )
            )
        else:
            selected.sort(key=lambda row: (row["componentId"], row["unit"]))
        for row in selected:
            self._run_systemctl("start", row["unit"])
            self._wait_unit_active(row["unit"])

    def _active_python_pointer_identity(self, service: str) -> str | None:
        try:
            active = self._load_service_bundle().resolve_active_release(
                service, install_root=self.install_root
            )
            return active[1] if active is not None else None
        except Exception as error:
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Active {service} bundle pointer failed integrity validation: {error}",
            ) from error

    def _remove_symlink_if_target(self, path: Path, target: str) -> None:
        if path.is_symlink() and os.readlink(path) == target:
            path.unlink()
            self._fsync_directory(path.parent)
        elif path.exists() or path.is_symlink():
            raise UpdateError(
                "ROLLBACK_CONFLICT", f"Active pointer changed unexpectedly at {path}."
            )

    def _recover_transaction(
        self,
        transaction: dict[str, Any],
        transaction_path: Path,
        stage_path: Path,
        confirmation: dict[str, Any],
    ) -> dict[str, Any]:
        if (
            transaction.get("planDigest") != confirmation["planDigest"]
            or transaction.get("planId") != confirmation["planId"]
        ):
            raise UpdateError(
                "TRANSACTION_MISMATCH",
                "An unresolved transaction exists with a different confirmed plan.",
            )
        self._validate_recovery_identity(transaction)
        if transaction.get("phase") == "succeeded":
            return self._applied_result(transaction)
        if transaction.get("phase") == "rolled_back":
            raise UpdateError(
                "APPLY_ROLLED_BACK",
                transaction.get("rollbackMessage", "Previous attempt rolled back."),
            )
        if transaction.get("phase") in {"success_end_pending", "rollback_end_pending"}:
            return self._recover_end_pending(transaction, transaction_path)
        if transaction.get("phase") == "begin_pending":
            try:
                transaction["maintenanceToken"] = self._begin_maintenance(transaction)
            except UpdateError as error:
                if error.maintenance_not_acquired:
                    self._clear_begin_pending(transaction, transaction_path)
                raise
            transaction["phase"] = "applying"
            _atomic_json(transaction_path, transaction)
        healthy, message = self._rollback_transaction(transaction)
        try:
            self._end_maintenance(
                transaction, outcome="ROLLED_BACK" if healthy else "FAILED", healthy=healthy
            )
        except UpdateError as error:
            transaction["phase"] = "rollback_required"
            transaction["recoveryError"] = str(error)
            _atomic_json(transaction_path, transaction)
            raise UpdateError(
                "ROLLBACK_GATE_HELD",
                f"Interrupted update recovery could not release maintenance: {error}",
                retryable=True,
            ) from error
        transaction["phase"] = "rolled_back" if healthy else "rollback_required"
        transaction["rollbackMessage"] = message
        transaction.pop("maintenanceToken", None)
        _atomic_json(transaction_path, transaction)
        if not healthy:
            raise UpdateError("ROLLBACK_UNHEALTHY", message, retryable=True)
        raise UpdateError(
            "INTERRUPTED_UPDATE_ROLLED_BACK",
            f"Interrupted transaction was rolled back. {message}; run check and stage again before retrying.",
        )

    def _validate_recovery_identity(self, transaction: dict[str, Any]) -> None:
        """Fail held when an unfinished journal lacks exact release identities."""

        components = transaction.get("components")
        previous = transaction.get("previous")
        if (
            transaction.get("schemaVersion") != 2
            or not isinstance(components, list)
            or not components
            or not isinstance(previous, list)
        ):
            raise UpdateError(
                "TRANSACTION_IDENTITY_UNKNOWN",
                "An unfinished legacy update journal has no verified pointer identities; maintenance remains held for operator recovery.",
                retryable=True,
            )
        component_ids: set[str] = set()
        for item in components:
            if not isinstance(item, dict) or not isinstance(item.get("componentId"), str):
                raise UpdateError(
                    "TRANSACTION_IDENTITY_UNKNOWN",
                    "Update journal contains an invalid candidate component identity.",
                    retryable=True,
                )
            component_id = item["componentId"]
            component = self.components.get(component_id)
            if (
                component is None
                or component_id in component_ids
                or not _valid_digest(item.get("manifestDigest"))
                or item.get("releaseIdentity") != item.get("manifestDigest")
                or not _valid_digest(item.get("artifactDigest"))
                or not isinstance(item.get("version"), str)
                or VERSION_PATTERN.fullmatch(item["version"]) is None
            ):
                raise UpdateError(
                    "TRANSACTION_IDENTITY_UNKNOWN",
                    f"Update journal candidate identity is incomplete for {component_id}.",
                    retryable=True,
                )
            component_ids.add(component_id)
            if component.get("kind") == "data-bundle":
                artifact_id = item.get("artifactDigest")
                if (
                    not _valid_digest(artifact_id)
                    or item.get("bundleIdentity") != artifact_id
                    or item.get("pointerIdentity") != artifact_id.removeprefix("sha256:")
                    or not isinstance(item.get("dataBundle"), dict)
                    or item["dataBundle"].get("artifactId") != artifact_id
                ):
                    raise UpdateError(
                        "TRANSACTION_IDENTITY_UNKNOWN",
                        f"Update journal data-bundle identity is incomplete for {component_id}.",
                        retryable=True,
                    )
            elif component.get("pythonBundleService"):
                bundle_identity = item.get("bundleIdentity")
                if (
                    not isinstance(bundle_identity, str)
                    or BUNDLE_ID_PATTERN.fullmatch(bundle_identity) is None
                    or item.get("pointerIdentity") != bundle_identity
                ):
                    raise UpdateError(
                        "TRANSACTION_IDENTITY_UNKNOWN",
                        f"Update journal Python pointer identity is incomplete for {component_id}.",
                        retryable=True,
                    )
            else:
                expected_pointer = (
                    f"{item['version']}--{item['manifestDigest'].removeprefix('sha256:')}"
                )
                if (
                    item.get("bundleIdentity") is not None
                    or item.get("pointerIdentity") != expected_pointer
                ):
                    raise UpdateError(
                        "TRANSACTION_IDENTITY_UNKNOWN",
                        f"Update journal native pointer identity is incomplete for {component_id}.",
                        retryable=True,
                    )

        previous_ids: set[str] = set()
        previous_fields = {
            "componentId",
            "version",
            "releaseIdentity",
            "manifestDigest",
            "artifactDigest",
            "pointerIdentity",
            "bundleIdentity",
            "identityAttested",
        }
        for item in previous:
            if not isinstance(item, dict) or set(item) != previous_fields:
                raise UpdateError(
                    "TRANSACTION_IDENTITY_UNKNOWN",
                    "Update journal has an incomplete prior release identity; maintenance remains held.",
                    retryable=True,
                )
            component_id = item["componentId"]
            component = self.components.get(component_id)
            if (
                component_id not in component_ids
                or component is None
                or component_id in previous_ids
                or not isinstance(item.get("identityAttested"), bool)
            ):
                raise UpdateError(
                    "TRANSACTION_IDENTITY_UNKNOWN",
                    "Update journal prior component set or identity state is invalid.",
                    retryable=True,
                )
            previous_ids.add(component_id)
            if component.get("kind") == "data-bundle":
                if item.get("version") is None:
                    if any(
                        item.get(key) is not None
                        for key in (
                            "releaseIdentity",
                            "manifestDigest",
                            "artifactDigest",
                            "pointerIdentity",
                            "bundleIdentity",
                        )
                    ):
                        raise UpdateError(
                            "TRANSACTION_IDENTITY_UNKNOWN",
                            "Empty Authority snapshot identity has stray fields.",
                            retryable=True,
                        )
                elif item.get("releaseIdentity") is None:
                    artifact_id = item.get("artifactDigest")
                    if (
                        item.get("version") != "0.0.0"
                        or item.get("manifestDigest") is not None
                        or not _valid_digest(artifact_id)
                        or item.get("pointerIdentity") != artifact_id.removeprefix("sha256:")
                        or item.get("bundleIdentity") != artifact_id
                        or item.get("identityAttested") is not True
                    ):
                        raise UpdateError(
                            "TRANSACTION_IDENTITY_UNKNOWN",
                            "Prior Authority snapshot identity is invalid.",
                            retryable=True,
                        )
                elif (
                    not isinstance(item.get("version"), str)
                    or VERSION_PATTERN.fullmatch(item["version"]) is None
                    or not _valid_digest(item.get("releaseIdentity"))
                    or item.get("manifestDigest") != item.get("releaseIdentity")
                    or not _valid_digest(item.get("artifactDigest"))
                    or item.get("pointerIdentity") != item["artifactDigest"].removeprefix("sha256:")
                    or item.get("bundleIdentity") != item.get("artifactDigest")
                ):
                    raise UpdateError(
                        "TRANSACTION_IDENTITY_UNKNOWN",
                        "Prior Authority artifact identity is invalid.",
                        retryable=True,
                    )
                continue
            if item.get("version") is None:
                if any(
                    item.get(key) is not None
                    for key in (
                        "releaseIdentity",
                        "manifestDigest",
                        "artifactDigest",
                        "pointerIdentity",
                        "bundleIdentity",
                    )
                ):
                    raise UpdateError(
                        "TRANSACTION_IDENTITY_UNKNOWN",
                        f"Empty prior state has stray release identity for {component_id}.",
                        retryable=True,
                    )
                continue
            if (
                not isinstance(item.get("version"), str)
                or VERSION_PATTERN.fullmatch(item["version"]) is None
            ):
                raise UpdateError(
                    "TRANSACTION_IDENTITY_UNKNOWN",
                    f"Prior release version is invalid for {component_id}.",
                    retryable=True,
                )
            if component.get("pythonBundleService"):
                bundle_identity = item.get("bundleIdentity")
                if (
                    not isinstance(bundle_identity, str)
                    or BUNDLE_ID_PATTERN.fullmatch(bundle_identity) is None
                    or item.get("pointerIdentity") != bundle_identity
                ):
                    raise UpdateError(
                        "TRANSACTION_IDENTITY_UNKNOWN",
                        f"Prior Python pointer identity is incomplete for {component_id}.",
                        retryable=True,
                    )
            else:
                pointer = item.get("pointerIdentity")
                version, digest = (
                    _native_release_directory_identity(pointer)
                    if isinstance(pointer, str)
                    else ("", None)
                )
                if (
                    pointer is None
                    or version != item["version"]
                    or (digest is not None and item.get("manifestDigest") != "sha256:" + digest)
                ):
                    raise UpdateError(
                        "TRANSACTION_IDENTITY_UNKNOWN",
                        f"Prior native pointer identity is incomplete for {component_id}.",
                        retryable=True,
                    )
            if item["identityAttested"] and (
                not _valid_digest(item.get("releaseIdentity"))
                or item.get("manifestDigest") != item.get("releaseIdentity")
                or not _valid_digest(item.get("artifactDigest"))
            ):
                raise UpdateError(
                    "TRANSACTION_IDENTITY_UNKNOWN",
                    f"Prior verified receipt identity is incomplete for {component_id}.",
                    retryable=True,
                )
        if previous_ids != component_ids:
            raise UpdateError(
                "TRANSACTION_IDENTITY_UNKNOWN",
                "Update journal prior component set differs from the candidate set.",
                retryable=True,
            )

    def _recover_end_pending(
        self, transaction: dict[str, Any], transaction_path: Path
    ) -> dict[str, Any]:
        """Reconcile a durable EndMaintenance request without repeating a restart."""

        phase = transaction["phase"]
        readiness = self._readiness_for(
            transaction["targetKind"], requires_restart=True, force=True
        )
        gate_status = readiness.get("status")
        if gate_status not in {"READY", "MAINTENANCE_ACTIVE"}:
            raise UpdateError(
                "GATE_UNKNOWN",
                f"Cannot reconcile the durable maintenance completion while broker state is {gate_status!r}; journal and gate remain held.",
                retryable=True,
            )

        if phase == "success_end_pending":
            expected = {item["componentId"]: item for item in transaction["components"]}
            current = {
                item["componentId"]: item
                for item in self._capture_active_versions(transaction["components"])
            }
            if not self._same_release_identities(expected, current, require_attested=True):
                raise UpdateError(
                    "TRANSACTION_STATE_MISMATCH",
                    "Active releases differ from the healthy plan recorded before EndMaintenance; refusing to change service state during recovery.",
                    retryable=True,
                )
            self._health_transaction(transaction)
            if gate_status == "MAINTENANCE_ACTIVE":
                self._end_maintenance(transaction, outcome="SUCCESS", healthy=True)
            transaction["phase"] = "succeeded"
            transaction.pop("maintenanceToken", None)
            transaction.pop("recoveryError", None)
            _atomic_json(transaction_path, transaction)
            return self._applied_result(transaction)

        expected_previous = {item["componentId"]: item for item in transaction.get("previous", [])}
        current_previous = {
            item["componentId"]: item
            for item in self._capture_active_versions(transaction["components"])
        }
        if not self._same_release_identities(
            expected_previous, current_previous, require_attested=False
        ):
            raise UpdateError(
                "TRANSACTION_STATE_MISMATCH",
                "Restored releases differ from the rollback identities recorded before EndMaintenance; refusing to release the maintenance gate.",
                retryable=True,
            )
        if gate_status == "MAINTENANCE_ACTIVE":
            self._health_rollback_state(transaction)
            self._end_maintenance(transaction, outcome="ROLLED_BACK", healthy=True)
        else:
            self._health_rollback_state(transaction)
        transaction["phase"] = "rolled_back"
        transaction.pop("maintenanceToken", None)
        transaction.pop("recoveryError", None)
        _atomic_json(transaction_path, transaction)
        raise UpdateError(
            "INTERRUPTED_UPDATE_ROLLED_BACK",
            f"Interrupted update was rolled back and its maintenance completion was reconciled. {transaction.get('rollbackMessage', '')}",
        )

    def _health_rollback_state(self, transaction: dict[str, Any]) -> None:
        restored = []
        for item in transaction["components"]:
            installed = self._installed(self.components[item["componentId"]])
            if installed.get("manifest") is not None:
                restored.append({**item, "manifest": installed["manifest"]})
        if restored:
            self._health_transaction({**transaction, "components": restored})

    @staticmethod
    def _same_release_identities(
        expected: dict[str, dict[str, Any]],
        current: dict[str, dict[str, Any]],
        *,
        require_attested: bool,
    ) -> bool:
        if set(expected) != set(current):
            return False
        fields = (
            "version",
            "releaseIdentity",
            "manifestDigest",
            "artifactDigest",
            "pointerIdentity",
            "bundleIdentity",
        )
        for component_id, item in expected.items():
            active = current[component_id]
            if any(item.get(field) != active.get(field) for field in fields):
                return False
            if require_attested and active.get("identityAttested") is not True:
                return False
        return True

    def _applied_result(self, transaction: dict[str, Any]) -> dict[str, Any]:
        plan = {
            "planId": transaction["planId"],
            "planDigest": transaction["planDigest"],
            "channel": transaction.get("channel", DEFAULT_CHANNEL),
            "phase": "succeeded",
            "components": [
                {
                    "componentId": item["componentId"],
                    "version": item["version"],
                    "manifestDigest": item["manifestDigest"],
                    "artifactDigest": item["artifactDigest"],
                    "restartGroup": item["restartGroup"],
                }
                for item in transaction["components"]
            ],
        }
        rows = [
            self._result_component(
                self.components[item["componentId"]],
                self._readiness(self.components[item["componentId"]]),
                phase="current",
                update_available=False,
            )
            for item in transaction["components"]
        ]
        return {"status": "applied", "components": rows, "plan": plan, "plans": [plan]}

    def _staged_plans(self) -> list[dict[str, Any]]:
        root = self.state_root / "staged"
        if not root.is_dir() or root.is_symlink():
            return []
        plans = []
        for child in sorted(root.iterdir()):
            if child.is_symlink() or not child.is_dir():
                continue
            path = child / "stage.json"
            if not path.is_file() or path.is_symlink():
                continue
            record = _read_object(path, "staged update plan")
            if record.get("phase") == "staged" and isinstance(record.get("plan"), dict):
                plans.append({**record["plan"], "phase": "staged"})
        return plans

    def _get_json(self, uri: str) -> Any:
        try:
            return json.loads(self._get_bytes(uri).decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise UpdateError(
                "INVALID_HTTP_JSON", f"Response from {uri} is not valid JSON.", retryable=True
            ) from error

    def _get_bytes(self, uri: str, *, max_bytes: int = MAX_RELEASE_ASSET_BYTES) -> bytes:
        if not isinstance(uri, str) or urllib.parse.urlsplit(uri).scheme != "https":
            raise UpdateError("UNTRUSTED_URI", "Release assets must use HTTPS.")
        request = urllib.request.Request(
            uri,
            headers={
                "User-Agent": USER_AGENT,
                "Accept": "application/json, application/octet-stream",
            },
        )
        try:
            with self.opener(request, timeout=30) as response:
                final_host = urllib.parse.urlsplit(response.geturl()).hostname or ""
                if final_host not in {"github.com", "api.github.com"} and not final_host.endswith(
                    ".githubusercontent.com"
                ):
                    raise UpdateError(
                        "UNTRUSTED_REDIRECT",
                        f"GitHub asset redirected to an untrusted host: {final_host}.",
                    )
                data = response.read(max_bytes + 1)
                if len(data) > max_bytes:
                    raise UpdateError(
                        "ARTIFACT_TOO_LARGE", "Remote asset exceeds its configured size limit."
                    )
                return data
        except UpdateError:
            raise
        except (OSError, urllib.error.URLError, TimeoutError) as error:
            raise UpdateError(
                "NETWORK_ERROR", f"Cannot download trusted release asset: {error}", retryable=True
            ) from error

    @staticmethod
    def _require_github_asset_uri(uri: Any, repository: str) -> None:
        if not isinstance(uri, str):
            raise UpdateError("UNTRUSTED_URI", "Release index contains a non-string asset URI.")
        parts = urllib.parse.urlsplit(uri)
        if (
            parts.scheme != "https"
            or parts.hostname != "github.com"
            or not parts.path.startswith(f"/{repository}/releases/download/")
        ):
            raise UpdateError(
                "UNTRUSTED_URI", f"Release asset URI is outside the pinned repository {repository}."
            )

    def _verify_attestation(
        self,
        payload: bytes,
        *,
        subject_name: str,
        digest: str,
        repository: str,
        workflow: str,
        source_ref: str,
        source_commit: str,
        bundle_path: Path | None = None,
        bundle_bytes: bytes | None = None,
    ) -> None:
        if (
            Path(repository).name == ""
            or not _valid_digest(digest)
            or (bundle_path is not None and bundle_bytes is not None)
        ):
            raise UpdateError("INVALID_ATTESTATION", "Attestation subject identity is invalid.")
        with tempfile.NamedTemporaryFile(
            prefix="cyrene-attest-", suffix="-" + Path(subject_name).name, delete=False
        ) as stream:
            stream.write(payload)
            temporary_path = Path(stream.name)
        bundle_temporary_path: Path | None = None
        try:
            if shutil.which("gh") is None:
                raise UpdateError(
                    "ATTESTATION_VERIFIER_MISSING",
                    "GitHub CLI (`gh`) is required to verify artifact attestations.",
                )
            arguments = [
                "gh",
                "attestation",
                "verify",
                str(temporary_path),
                "--repo",
                repository,
                "--signer-workflow",
                workflow,
                "--source-ref",
                source_ref,
                "--source-digest",
                source_commit,
                "--predicate-type",
                "https://slsa.dev/provenance/v1",
                "--cert-oidc-issuer",
                "https://token.actions.githubusercontent.com",
                "--format",
                "json",
            ]
            if bundle_path is not None:
                if bundle_path.is_symlink() or not bundle_path.is_file():
                    raise UpdateError("INVALID_ATTESTATION", "Attestation bundle path is unsafe.")
                arguments.extend(["--bundle", str(bundle_path)])
            elif bundle_bytes is not None:
                with tempfile.NamedTemporaryFile(
                    prefix="cyrene-attest-bundle-", suffix=".json", delete=False
                ) as stream:
                    stream.write(bundle_bytes)
                    bundle_temporary_path = Path(stream.name)
                bundle_temporary_path.chmod(0o600)
                arguments.extend(["--bundle", str(bundle_temporary_path)])
            completed = self.runner(
                arguments,
                capture_output=True,
                text=True,
                timeout=60,
                check=False,
            )
            if completed.returncode != 0:
                raise UpdateError(
                    "ATTESTATION_INVALID",
                    f"GitHub artifact attestation verification failed: {completed.stderr.strip() or completed.stdout.strip()}",
                )
            try:
                verification = json.loads(completed.stdout)
            except json.JSONDecodeError as error:
                raise UpdateError(
                    "ATTESTATION_INVALID", "GitHub CLI returned malformed attestation JSON."
                ) from error
            if not isinstance(verification, list):
                raise UpdateError(
                    "ATTESTATION_INVALID",
                    "GitHub CLI returned an unexpected verification result shape.",
                )
            raw_digest = digest.split(":", 1)[1]
            matched_subject = False
            for result in verification:
                if not isinstance(result, dict):
                    continue
                verification_result = result.get("verificationResult")
                statement = (
                    verification_result.get("statement")
                    if isinstance(verification_result, dict)
                    else None
                )
                if (
                    not isinstance(statement, dict)
                    or statement.get("predicateType") != "https://slsa.dev/provenance/v1"
                ):
                    continue
                subjects = statement.get("subject")
                if not isinstance(subjects, list):
                    continue
                if any(
                    isinstance(subject, dict)
                    and subject.get("name") == subject_name
                    and isinstance(subject.get("digest"), dict)
                    and subject["digest"].get("sha256") == raw_digest
                    for subject in subjects
                ):
                    matched_subject = True
                    break
            if not matched_subject:
                raise UpdateError(
                    "ATTESTATION_SUBJECT_MISMATCH",
                    "Verified SLSA statement does not name the expected subject and SHA-256 digest.",
                )
        except subprocess.TimeoutExpired as error:
            raise UpdateError(
                "ATTESTATION_TIMEOUT", "GitHub attestation verification timed out.", retryable=True
            ) from error
        finally:
            temporary_path.unlink(missing_ok=True)
            if bundle_temporary_path is not None:
                bundle_temporary_path.unlink(missing_ok=True)

    def _run_systemctl(self, operation: str, unit: str) -> None:
        try:
            completed = self.runner(
                ["systemctl", operation, unit],
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired) as error:
            raise UpdateError("SYSTEMD_FAILED", f"Cannot {operation} {unit}: {error}") from error
        if completed.returncode != 0:
            raise UpdateError(
                "SYSTEMD_FAILED",
                f"systemctl {operation} {unit} failed: {completed.stderr.strip() or completed.stdout.strip()}",
            )

    def _wait_unit_active(self, unit: str) -> None:
        deadline = time.monotonic() + 90
        while time.monotonic() < deadline:
            try:
                completed = self.runner(
                    ["systemctl", "is-active", "--quiet", unit],
                    capture_output=True,
                    text=True,
                    timeout=5,
                    check=False,
                )
            except (OSError, subprocess.TimeoutExpired):
                completed = None
            if completed is not None and completed.returncode == 0:
                return
            time.sleep(1)
        raise UpdateError("HEALTH_CHECK_FAILED", f"{unit} did not become active within 90 seconds.")

    def _wait_http_health(self, port: int, path: str, component_id: str) -> None:
        deadline = time.monotonic() + 90
        url = f"http://127.0.0.1:{port}{path}"
        while time.monotonic() < deadline:
            try:
                request = urllib.request.Request(url, headers={"User-Agent": USER_AGENT})
                with urllib.request.urlopen(request, timeout=2) as response:
                    if 200 <= response.status < 400:
                        return
            except (OSError, urllib.error.URLError, TimeoutError):
                time.sleep(1)
        raise UpdateError(
            "HEALTH_CHECK_FAILED",
            f"{component_id} did not pass its health endpoint {url} within 90 seconds.",
        )

    @staticmethod
    def _fsync_directory(path: Path) -> None:
        descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(descriptor)
        finally:
            os.close(descriptor)


def run_json_stdio(
    updater: ComponentUpdater, input_stream: Any = sys.stdin, output_stream: Any = sys.stdout
) -> int:
    """Read exactly one fixed JSON request and emit exactly one JSON envelope."""

    line = input_stream.readline(1_048_577)
    if not line or len(line) > 1_048_576 or input_stream.readline(1):
        envelope = {
            "protocolVersion": PROTOCOL_VERSION,
            "ok": False,
            "operation": "status",
            "error": {
                "code": "INVALID_REQUEST",
                "message": "Expected exactly one JSON request line (maximum 1 MiB).",
                "retryable": False,
            },
        }
    else:
        try:
            request = json.loads(line)
            envelope = updater.handle(request)
        except (json.JSONDecodeError, UnicodeDecodeError) as error:
            envelope = {
                "protocolVersion": PROTOCOL_VERSION,
                "ok": False,
                "operation": "status",
                "error": {
                    "code": "INVALID_REQUEST",
                    "message": f"Request must be valid UTF-8 JSON: {error}",
                    "retryable": False,
                },
            }
    output_stream.write(json.dumps(envelope, ensure_ascii=False, separators=(",", ":")) + "\n")
    output_stream.flush()
    return 0


def _validate_startup_arguments(arguments: Any, *, field: str) -> list[str]:
    """Validate fixed manifest or root-owned unit arguments before exec."""

    if not isinstance(arguments, (list, tuple)) or len(arguments) > 64:
        raise UpdateError("INVALID_STARTUP_ARGUMENTS", f"{field} must contain at most 64 strings.")
    validated: list[str] = []
    for argument in arguments:
        if (
            not isinstance(argument, str)
            or not argument
            or "\x00" in argument
            or len(argument.encode("utf-8")) > 512
        ):
            raise UpdateError("INVALID_STARTUP_ARGUMENTS", f"{field} contains an invalid argument.")
        validated.append(argument)
    return validated


def run_component(
    component_id: str,
    *,
    install_root: Path = DEFAULT_INSTALL_ROOT,
    startup_arguments: list[str] | tuple[str, ...] = (),
) -> int:
    """Execute the trusted active native release selected for one fixed component ID."""

    if COMPONENT_ID_PATTERN.fullmatch(component_id) is None:
        raise UpdateError("INVALID_COMPONENT", "Component ID is invalid.")
    root = install_root / "components" / component_id
    directories = (install_root, install_root / "components", root, root / "releases")
    for directory in directories:
        try:
            info = directory.lstat()
        except OSError as error:
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Active release directory is missing for {component_id}: {directory}.",
            ) from error
        if (
            not stat.S_ISDIR(info.st_mode)
            or directory.is_symlink()
            or info.st_uid != 0
            or stat.S_IMODE(info.st_mode) & 0o022
            or not stat.S_IMODE(info.st_mode) & 0o001
            or not os.access(directory, os.X_OK)
        ):
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Active release directory is not root-owned, immutable, and traversable for {component_id}: {directory}.",
            )
    active = root / "active"
    if not active.is_symlink():
        raise UpdateError(
            "COMPONENT_NOT_INSTALLED",
            f"No active immutable release is installed for {component_id}.",
        )
    active_info = active.lstat()
    if active_info.st_uid != 0:
        raise UpdateError(
            "INVALID_INSTALLED_RELEASE", f"Active pointer is not root-owned for {component_id}."
        )
    match = re.fullmatch(r"releases/([^/]+)", os.readlink(active))
    if match is None:
        raise UpdateError(
            "INVALID_INSTALLED_RELEASE", f"Active release pointer is invalid for {component_id}."
        )
    pointer_identity = match.group(1)
    version, pointer_digest = _native_release_directory_identity(pointer_identity)
    if VERSION_PATTERN.fullmatch(version) is None:
        raise UpdateError(
            "INVALID_INSTALLED_RELEASE", f"Active release pointer is invalid for {component_id}."
        )
    release = root / "releases" / pointer_identity
    if release.is_symlink() or not release.is_dir():
        raise UpdateError(
            "INVALID_INSTALLED_RELEASE", f"Active release directory is unsafe for {component_id}."
        )
    release_info = release.lstat()
    if (
        release_info.st_uid != 0
        or stat.S_IMODE(release_info.st_mode) & 0o022
        or not stat.S_IMODE(release_info.st_mode) & 0o001
        or not os.access(release, os.X_OK)
    ):
        raise UpdateError(
            "INVALID_INSTALLED_RELEASE",
            f"Active release directory is not root-controlled and traversable for {component_id}.",
        )
    manifest_path = release / "component-manifest.json"
    if manifest_path.is_symlink():
        raise UpdateError(
            "INVALID_INSTALLED_RELEASE", f"Active release manifest is a symlink for {component_id}."
        )
    manifest_info = manifest_path.lstat()
    if (
        not stat.S_ISREG(manifest_info.st_mode)
        or manifest_info.st_uid != 0
        or stat.S_IMODE(manifest_info.st_mode) & 0o022
        or not stat.S_IMODE(manifest_info.st_mode) & 0o004
        or not os.access(manifest_path, os.R_OK)
    ):
        raise UpdateError(
            "INVALID_INSTALLED_RELEASE",
            f"Active release manifest is not root-owned and readable for {component_id}.",
        )
    manifest = _read_object(manifest_path, f"{component_id} release manifest")
    if manifest.get("manifestDigest") != _digest_json(manifest, "manifestDigest"):
        raise UpdateError(
            "INVALID_INSTALLED_RELEASE",
            f"Active release manifest digest is invalid for {component_id}.",
        )
    if (
        manifest.get("componentId") != component_id
        or manifest.get("version") != version
        or (
            pointer_digest is not None
            and manifest.get("manifestDigest") != "sha256:" + pointer_digest
        )
        or (pointer_digest is None and pointer_identity != version)
    ):
        raise UpdateError(
            "INVALID_INSTALLED_RELEASE",
            f"Active release pointer does not match its manifest for {component_id}.",
        )
    artifact = manifest.get("artifact")
    if not isinstance(artifact, dict) or artifact.get("kind") != "native-binary":
        raise UpdateError(
            "INVALID_INSTALLED_RELEASE",
            f"Active release is not a native binary for {component_id}.",
        )
    relative = _safe_relative(artifact.get("entrypoint"), field="artifact.entrypoint")
    binary = release.joinpath(*relative.parts)
    if binary.is_symlink() or not binary.is_file() or not os.access(binary, os.X_OK):
        raise UpdateError(
            "INVALID_INSTALLED_RELEASE",
            f"Active entrypoint is missing or not executable for {component_id}.",
        )
    arguments = artifact.get("arguments", [])
    manifest_arguments = _validate_startup_arguments(
        arguments, field=f"{component_id} artifact.arguments"
    )
    unit_arguments = _validate_startup_arguments(
        startup_arguments, field="trusted systemd startup arguments"
    )
    environment = os.environ.copy()
    for variable in PRODUCT_CONTRACT_ROOT_ENV.values():
        environment.pop(variable, None)
    contract_env = PRODUCT_CONTRACT_ROOT_ENV.get(component_id)
    if contract_env is not None:
        contract_root = release / "share" / "cyrene" / "product-contracts"
        if contract_root.is_symlink() or not contract_root.is_dir():
            raise UpdateError(
                "INVALID_INSTALLED_RELEASE",
                f"Active release is missing its pinned Product contract directory for {component_id}.",
            )
        environment[contract_env] = str(contract_root)
    os.execve(str(binary), [str(binary), *manifest_arguments, *unit_arguments], environment)
    return 0


def main(argv: list[str] | None = None) -> int:
    """Development entrypoint for standalone component update tests."""

    import argparse

    parser = argparse.ArgumentParser(prog="cyrene component-updates")
    parser.add_argument("--catalog", type=Path, default=DEFAULT_CATALOG)
    parser.add_argument("--activity-catalog", type=Path, default=DEFAULT_ACTIVITY_CATALOG)
    parser.add_argument("--socket", type=Path, default=DEFAULT_SOCKET)
    parser.add_argument("--broker", type=Path)
    parser.add_argument("--install-root", type=Path, default=DEFAULT_INSTALL_ROOT)
    parser.add_argument("--state-root", type=Path, default=DEFAULT_STATE_ROOT)
    args = parser.parse_args(argv)
    updater = ComponentUpdater(
        catalog_path=args.catalog,
        activity_catalog_path=args.activity_catalog,
        socket_path=args.socket,
        broker_path=args.broker,
        install_root=args.install_root,
        state_root=args.state_root,
    )
    return run_json_stdio(updater)


if __name__ == "__main__":
    raise SystemExit(main())
